-- 和合本全文数据（文件序号见文件名 bible_cuv_data_NN.sql）。先运行 bible_cuv_schema.sql 建表，再按序号依次运行各数据文件。可重复运行（冲突自动跳过）。
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 62, 1, '我因锡安必不静默，为耶路撒冷必不息声，直到他的公义如光辉发出，他的救恩如明灯发亮。'),
('CUV', '以赛亚书', 23, 62, 2, '列国必见你的公义；列王必见你的荣耀。你必得新名的称呼，是耶和华亲口所起的。'),
('CUV', '以赛亚书', 23, 62, 3, '你在耶和华的手中要作为华冠，在你神的掌上必作为冕旒。'),
('CUV', '以赛亚书', 23, 62, 4, '你必不再称为撇弃的；你的地也不再称为荒凉的。你却要称为我所喜悦的；你的地也必称为有夫之妇。因为耶和华喜悦你，你的地也必归他。'),
('CUV', '以赛亚书', 23, 62, 5, '少年人怎样娶处女，你的众民（民：原文是子）也要照样娶你；新郎怎样喜悦新妇，你的神也要照样喜悦你。'),
('CUV', '以赛亚书', 23, 62, 6, '耶路撒冷啊，我在你城上设立守望的，他们昼夜必不静默。呼吁耶和华的，你们不要歇息，'),
('CUV', '以赛亚书', 23, 62, 7, '也不要使他歇息，直等他建立耶路撒冷，使耶路撒冷在地上成为可赞美的。'),
('CUV', '以赛亚书', 23, 62, 8, '耶和华指著自己的右手和大能的膀臂起誓说：我必不再将你的五谷给你仇敌作食物；外邦人也不再喝你劳碌得来的新酒。'),
('CUV', '以赛亚书', 23, 62, 9, '惟有那收割的要吃，并赞美耶和华；那聚敛的要在我圣所的院内喝。'),
('CUV', '以赛亚书', 23, 62, 10, '你们当从门经过经过，预备百姓的路；修筑修筑大道，捡去石头，为万民竖立大旗，'),
('CUV', '以赛亚书', 23, 62, 11, '看哪，耶和华曾宣告到地极，对锡安的居民（原文是女子）说：你的拯救者来到。他的赏赐在他那里；他的报应在他面前。'),
('CUV', '以赛亚书', 23, 62, 12, '人必称他们为圣民，为耶和华的赎民；你也必称为被眷顾、不撇弃的城。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 63, 1, '这从以东的波斯拉来，穿红衣服，装扮华美，能力广大，大步行走的是谁呢？就是我，是凭公义说话，以大能施行拯救。'),
('CUV', '以赛亚书', 23, 63, 2, '你的装扮为何有红色？你的衣服为何像踹酒醡的呢？'),
('CUV', '以赛亚书', 23, 63, 3, '我独自踹酒醡；众民中无一人与我同在。我发怒将他们踹下，发烈怒将他们践踏。他们的血溅在我衣服上，并且污染了我一切的衣裳。'),
('CUV', '以赛亚书', 23, 63, 4, '因为，报仇之日在我心中；救赎我民之年已经来到。'),
('CUV', '以赛亚书', 23, 63, 5, '我仰望，见无人帮助；我诧异，没有人扶持。所以，我自己的膀臂为我施行拯救；我的烈怒将我扶持。'),
('CUV', '以赛亚书', 23, 63, 6, '我发怒，踹下众民；发烈怒，使他们沉醉，又将他们的血倒在地上。'),
('CUV', '以赛亚书', 23, 63, 7, '我要照耶和华一切所赐给我们的，提起他的慈爱和美德，并他向以色列家所施的大恩；这恩是照他的怜恤和丰盛的慈爱赐给他们的。'),
('CUV', '以赛亚书', 23, 63, 8, '他说：他们诚然是我的百姓，不行虚假的子民；这样，他就作了他们的救主。'),
('CUV', '以赛亚书', 23, 63, 9, '他们在一切苦难中，他也同受苦难；并且他面前的使者拯救他们；他以慈爱和怜悯救赎他们；在古时的日子常保抱他们，怀搋他们。'),
('CUV', '以赛亚书', 23, 63, 10, '他们竟悖逆，使主的圣灵担忧。他就转作他们的仇敌，亲自攻击他们。'),
('CUV', '以赛亚书', 23, 63, 11, '那时，他们（原文是他）想起古时的日子─摩西和他百姓，说：将百姓和牧养他全群的人从海里领上来的在哪里呢？将他的圣灵降在他们中间的在哪里呢？'),
('CUV', '以赛亚书', 23, 63, 12, '使他荣耀的膀臂在摩西的右手边行动，在他们前面将水分开，要建立自己永远的名，'),
('CUV', '以赛亚书', 23, 63, 13, '带领他们经过深处，如马行走旷野，使他们不致绊跌的在哪里呢？'),
('CUV', '以赛亚书', 23, 63, 14, '耶和华的灵使他们得安息，仿佛牲畜下到山谷；照样，你也引导你的百姓，要建立自己荣耀的名。'),
('CUV', '以赛亚书', 23, 63, 15, '求你从天上垂顾，从你圣洁荣耀的居所观看。你的热心和你大能的作为在哪里呢？你爱慕的心肠和怜悯向我们止住了。'),
('CUV', '以赛亚书', 23, 63, 16, '亚伯拉罕虽然不认识我们，以色列也不承认我们，你却是我们的父。耶和华啊，你是我们的父；从万古以来，你名称为我们的救赎主。'),
('CUV', '以赛亚书', 23, 63, 17, '耶和华啊，你为何使我们走差离开你的道，使我们心里刚硬、不敬畏你呢？求你为你仆人，为你产业支派的缘故，转回来。'),
('CUV', '以赛亚书', 23, 63, 18, '你的圣民不过暂时得这产业；我们的敌人已经践踏你的圣所。'),
('CUV', '以赛亚书', 23, 63, 19, '我们好像你未曾治理的人，又像未曾得称你名下的人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 64, 1, '愿你裂天而降；愿山在你面前震动─'),
('CUV', '以赛亚书', 23, 64, 2, '好像火烧干柴，又像火将水烧开，使你敌人知道你的名，使列国在你面前发颤！'),
('CUV', '以赛亚书', 23, 64, 3, '你曾行我们不能逆料可畏的事。那时你降临，山岭在你面前震动。'),
('CUV', '以赛亚书', 23, 64, 4, '从古以来，人未曾听见、未曾耳闻、未曾眼见在你以外有甚么神为等候他的人行事。'),
('CUV', '以赛亚书', 23, 64, 5, '你迎接那欢喜行义、记念你道的人；你曾发怒，我们仍犯罪；这景况已久，我们还能得救么？'),
('CUV', '以赛亚书', 23, 64, 6, '我们都像不洁净的人；所有的义都像污秽的衣服。我们都像叶子渐渐枯干；我们的罪孽好像风把我们吹去。'),
('CUV', '以赛亚书', 23, 64, 7, '并且无人求告你的名；无人奋力抓住你。原来你掩面不顾我们，使我们因罪孽消化。'),
('CUV', '以赛亚书', 23, 64, 8, '耶和华啊，现在你仍是我们的父！我们是泥，你是窑匠；我们都是你手的工作。'),
('CUV', '以赛亚书', 23, 64, 9, '耶和华啊，求你不要大发震怒，也不要永远记念罪孽。求你垂顾我们，我们都是你的百姓。'),
('CUV', '以赛亚书', 23, 64, 10, '你的圣邑变为旷野。锡安变为旷野；耶路撒冷成为荒场。'),
('CUV', '以赛亚书', 23, 64, 11, '我们圣洁华美的殿─就是我们列祖赞美你的所在被火焚烧；我们所羡慕的美地尽都荒废。'),
('CUV', '以赛亚书', 23, 64, 12, '耶和华啊，有这些事，你还忍得住么？你仍静默使我们深受苦难么？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 65, 1, '素来没有访问我的，现在求问我；没有寻找我的，我叫他们遇见；没有称为我名下的，我对他们说：我在这里！我在这里！'),
('CUV', '以赛亚书', 23, 65, 2, '我整天伸手招呼那悖逆的百姓；他们随自己的意念行不善之道。'),
('CUV', '以赛亚书', 23, 65, 3, '这百姓时常当面惹我发怒；在园中献祭，在坛（原文是砖）上烧香；'),
('CUV', '以赛亚书', 23, 65, 4, '在坟墓间坐著，在隐密处住宿，吃猪肉；他们器皿中有可憎之物做的汤；'),
('CUV', '以赛亚书', 23, 65, 5, '且对人说：你站开罢！不要挨近我，因为我比你圣洁。主说：这些人是我鼻中的烟，是整天烧著的火。'),
('CUV', '以赛亚书', 23, 65, 6, '看哪，这都写在我面前。我必不静默，必施行报应，必将你们的罪孽和你们列祖的罪孽，就是在山上烧香，在冈上亵渎我的罪孽，一同报应在他们后人怀中，我先要把他们所行的量给他们；这是耶和华说的。'),
('CUV', '以赛亚书', 23, 65, 7, 'a'),
('CUV', '以赛亚书', 23, 65, 8, '耶和华如此说：葡萄中寻得新酒，人就说：不要毁坏，因为福在其中。我因我仆人的缘故也必照样而行，不将他们全然毁灭。'),
('CUV', '以赛亚书', 23, 65, 9, '我必从雅各中领出后裔，从犹大中领出承受我众山的。我的选民必承受；我的仆人要在那里居住。'),
('CUV', '以赛亚书', 23, 65, 10, '沙仑平原必成为羊群的圈；亚割谷必成为牛群躺卧之处，都为寻求我的民所得。'),
('CUV', '以赛亚书', 23, 65, 11, '但你们这些离弃耶和华、忘记我的圣山、给时运摆筵席（原文是桌子）、给天命盛满调和酒的，'),
('CUV', '以赛亚书', 23, 65, 12, '我要命定你们归在刀下，都必屈身被杀；因为我呼唤，你们没有答应；我说话，你们没有听从；反倒行我眼中看为恶的，拣选我所不喜悦的。'),
('CUV', '以赛亚书', 23, 65, 13, '所以，主耶和华如此说：我的仆人必得吃，你们却饥饿；我的仆人必得喝，你们却干渴；我的仆人必欢喜，你们却蒙羞。'),
('CUV', '以赛亚书', 23, 65, 14, '我的仆人因心中高兴欢呼，你们却因心中忧愁哀哭，又因心里忧伤哀号。'),
('CUV', '以赛亚书', 23, 65, 15, '你们必留下自己的名，为我选民指著赌咒。主耶和华必杀你们，另起别名称呼他的仆人。'),
('CUV', '以赛亚书', 23, 65, 16, '这样，在地上为自己求福的，必凭真实的神求福；在地上起誓的，必指真实的神起誓。因为，从前的患难已经忘记，也从我眼前隐藏了。'),
('CUV', '以赛亚书', 23, 65, 17, '看哪！我造新天新地；从前的事不再被记念，也不再追想。'),
('CUV', '以赛亚书', 23, 65, 18, '你们当因我所造的永远欢喜快乐；因我造耶路撒冷为人所喜，造其中的居民为人所乐。'),
('CUV', '以赛亚书', 23, 65, 19, '我必因耶路撒冷欢喜，因我的百姓快乐；其中必不再听见哭泣的声音和哀号的声音。'),
('CUV', '以赛亚书', 23, 65, 20, '其中必没有数日夭亡的婴孩，也没有寿数不满的老者；因为百岁死的仍算孩童，有百岁死的罪人算被咒诅。'),
('CUV', '以赛亚书', 23, 65, 21, '他们要建造房屋，自己居住；栽种葡萄园，吃其中的果子。'),
('CUV', '以赛亚书', 23, 65, 22, '他们建造的，别人不得住；他们栽种的，别人不得吃；因为我民的日子必像树木的日子；我选民亲手劳碌得来的必长久享用。'),
('CUV', '以赛亚书', 23, 65, 23, '他们必不徒然劳碌，所生产的，也不遭灾害，因为都是蒙耶和华赐福的后裔；他们的子孙也是如此。'),
('CUV', '以赛亚书', 23, 65, 24, '他们尚未求告，我就应允；正说话的时候，我就垂听。'),
('CUV', '以赛亚书', 23, 65, 25, '豺狼必与羊羔同食；狮子必吃草与牛一样；尘土必作蛇的食物。在我圣山的遍处，这一切都不伤人，不害物。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以赛亚书', 23, 66, 1, '耶和华如此说：天是我的座位；地是我的脚凳。你们要为我造何等的殿宇？哪里是我安息的地方呢？'),
('CUV', '以赛亚书', 23, 66, 2, '耶和华说：这一切都是我手所造的，所以就都有了。但我所看顾的，就是虚心（原文是贫穷）痛悔、因我话而战兢的人。'),
('CUV', '以赛亚书', 23, 66, 3, '假冒为善的宰牛，好像杀人，献羊羔，好像打折狗项，献供物，好像献猪血，烧乳香，好像称颂偶像。这等人拣选自己的道路，心里喜悦行可憎恶的事。'),
('CUV', '以赛亚书', 23, 66, 4, '我也必拣选迷惑他们的事，使他们所惧怕的临到他们；因为我呼唤，无人答应；我说话，他们不听从；反倒行我眼中看为恶的，拣选我所不喜悦的。'),
('CUV', '以赛亚书', 23, 66, 5, '你们因耶和华言语战兢的人当听他的话：你们的弟兄─就是恨恶你们，因我名赶出你们的，曾说：愿耶和华得荣耀，使我们得见你们的喜乐；但蒙羞的究竟是他们！'),
('CUV', '以赛亚书', 23, 66, 6, '有喧哗的声音出自城中！有声音出于殿中！是耶和华向仇敌施行报应的声音！'),
('CUV', '以赛亚书', 23, 66, 7, '锡安未曾劬劳就生产，未觉疼痛就生出男孩。'),
('CUV', '以赛亚书', 23, 66, 8, '国岂能一日而生？民岂能一时而产？因为锡安一劬劳便生下儿女，这样的事谁曾听见？谁曾看见呢？'),
('CUV', '以赛亚书', 23, 66, 9, '耶和华说：我既使他临产，岂不使他生产呢？你的神说：我既使他生产，岂能使他闭胎不生呢？'),
('CUV', '以赛亚书', 23, 66, 10, '你们爱慕耶路撒冷的都要与他一同欢喜快乐；你们为他悲哀的都要与他一同乐上加乐；'),
('CUV', '以赛亚书', 23, 66, 11, '使你们在他安慰的怀中吃奶得饱，使他们得他丰盛的荣耀，犹如挤奶，满心喜乐。'),
('CUV', '以赛亚书', 23, 66, 12, '耶和华如此说：我要使平安延及他，好像江河，使列国的荣耀延及他，如同涨溢的河。你们要从中享受（原文是咂）；你们必蒙抱在肋旁，摇弄在膝上。'),
('CUV', '以赛亚书', 23, 66, 13, '母亲怎样安慰儿子，我就照样安慰你们；你们也必因（或译：在）耶路撒冷得安慰。'),
('CUV', '以赛亚书', 23, 66, 14, '你们看见，就心中快乐；你们的骨头必得滋润像嫩草一样；而且耶和华的手向他仆人所行的必被人知道；他也要向仇敌发恼恨。'),
('CUV', '以赛亚书', 23, 66, 15, '看哪，耶和华必在火中降临；他的车辇像旋风，以烈怒施行报应，以火燄施行责罚；'),
('CUV', '以赛亚书', 23, 66, 16, '因为耶和华在一切有血气的人身上，必以火与刀施行审判；被耶和华所杀的必多。'),
('CUV', '以赛亚书', 23, 66, 17, '那些分别为圣、洁净自己的，进入园内跟在其中一个人的后头，吃猪肉和仓鼠并可憎之物，他们必一同灭绝；这是耶和华说的。'),
('CUV', '以赛亚书', 23, 66, 18, '我知道他们的行为和他们的意念。时候将到，我必将万民万族（族：原文是舌）聚来，看见我的荣耀，'),
('CUV', '以赛亚书', 23, 66, 19, '我要显神迹（或译：记号）在他们中间。逃脱的，我要差到列国去，就是到他施、普勒、拉弓的路德和土巴、雅完，并素来没有听见我名声、没有看见我荣耀辽远的海岛；他们必将我的荣耀传扬在列国中。'),
('CUV', '以赛亚书', 23, 66, 20, '他们必将你们的弟兄从列国中送回，使他们或骑马，或坐车，坐轿，骑骡子，骑独峰驼，到我的圣山耶路撒冷，作为供物献给耶和华，好像以色列人用洁净的器皿盛供物奉到耶和华的殿中；这是耶和华说的。'),
('CUV', '以赛亚书', 23, 66, 21, '耶和华说：我也必从他们中间取人为祭司，为利未人。'),
('CUV', '以赛亚书', 23, 66, 22, '耶和华说：我所要造的新天新地，怎样在我面前长存；你们的后裔和你们的名字也必照样长存。'),
('CUV', '以赛亚书', 23, 66, 23, '每逢月朔、安息日，凡有血气的必来在我面前下拜。这是耶和华说的。'),
('CUV', '以赛亚书', 23, 66, 24, '他们必出去观看那些违背我人的尸首；因为他们的虫是不死的；他们的火是不灭的；凡有血气的都必憎恶他们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 1, 1, '便雅悯地亚拿突城的祭司中，希勒家的儿子耶利米的话记在下面。'),
('CUV', '耶利米书', 24, 1, 2, '犹大王亚们的儿子约西亚在位十三年耶和华的话临到耶利米。'),
('CUV', '耶利米书', 24, 1, 3, '从犹大王约西亚的儿子约雅敬在位的时候，直到犹大王约西亚的儿子西底家在位的末年，就是十一年五月间耶路撒冷人被掳的时候，耶和华的话也常临到耶利米。'),
('CUV', '耶利米书', 24, 1, 4, '耶利米说，耶和华的话临到我说：'),
('CUV', '耶利米书', 24, 1, 5, '我未将你造在腹中，我已晓得你；你未出母胎，我已分别你为圣；我已派你作列国的先知。'),
('CUV', '耶利米书', 24, 1, 6, '我就说：主耶和华啊，我不知怎样说，因为我是年幼的。'),
('CUV', '耶利米书', 24, 1, 7, '耶和华对我说：你不要说我是年幼的，因为我差遣你到谁那里去，你都要去；我吩咐你说甚么话，你都要说。'),
('CUV', '耶利米书', 24, 1, 8, '你不要惧怕他们，因为我与你同在，要拯救你。这是耶和华说的。'),
('CUV', '耶利米书', 24, 1, 9, '于是耶和华伸手按我的口，对我说：我已将当说的话传给你。'),
('CUV', '耶利米书', 24, 1, 10, '看哪，我今日立你在列邦列国之上，为要施行拔出、拆毁、毁坏、倾覆，又要建立、栽植。'),
('CUV', '耶利米书', 24, 1, 11, '耶和华的话又临到我说：「耶利米，你看见甚么？」我说：「我看见一根杏树枝。」'),
('CUV', '耶利米书', 24, 1, 12, '耶和华对我说：「你看得不错；因为我留意保守我的话，使得成就。」'),
('CUV', '耶利米书', 24, 1, 13, '耶和华的话第二次临到我说：「你看见甚么？」我说：「我看见一个烧开的锅，从北而倾。」'),
('CUV', '耶利米书', 24, 1, 14, '耶和华对我说：「必有灾祸从北方发出，临到这地的一切居民。」'),
('CUV', '耶利米书', 24, 1, 15, '耶和华说：「看哪，我要召北方列国的众族；他们要来，各安座位在耶路撒冷的城门口，周围攻击城墙，又要攻击犹大的一切城邑。'),
('CUV', '耶利米书', 24, 1, 16, '至于这民的一切恶，就是离弃我、向别神烧香、跪拜自己手所造的，我要发出我的判语，攻击他们。'),
('CUV', '耶利米书', 24, 1, 17, '所以你当束腰，起来将我所吩咐你的一切话告诉他们；不要因他们惊惶，免得我使你在他们面前惊惶。'),
('CUV', '耶利米书', 24, 1, 18, '看哪，我今日使你成为坚城、铁柱、铜墙，与全地和犹大的君王、首领、祭司，并地上的众民反对。'),
('CUV', '耶利米书', 24, 1, 19, '他们要攻击你，却不能胜你；因为我与你同在，要拯救你。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 2, 1, '耶和华的话临到我说：'),
('CUV', '耶利米书', 24, 2, 2, '你去向耶路撒冷人的耳中喊叫说，耶和华如此说：你幼年的恩爱，婚姻的爱情，你怎样在旷野，在未曾耕种之地跟随我，我都记得。'),
('CUV', '耶利米书', 24, 2, 3, '那时以色列归耶和华为圣，作为土产初熟的果子；凡吞吃他的必算为有罪，灾祸必临到他们。这是耶和华说的。'),
('CUV', '耶利米书', 24, 2, 4, '雅各家、以色列家的各族啊，你们当听耶和华的话。'),
('CUV', '耶利米书', 24, 2, 5, '耶和华如此说：你们的列祖见我有甚么不义，竟远离我，随从虚无的神，自己成为虚妄的呢？'),
('CUV', '耶利米书', 24, 2, 6, '他们也不说：那领我们从埃及地上来，引导我们经过旷野，沙漠有深坑之地，和干旱死荫、无人经过、无人居住之地的耶和华在哪里呢？'),
('CUV', '耶利米书', 24, 2, 7, '我领你们进入肥美之地，使你们得吃其中的果子和美物；但你们进入的时候就玷污我的地，使我的产业成为可憎的。'),
('CUV', '耶利米书', 24, 2, 8, '祭司都不说，耶和华在哪里呢？传讲律法的都不认识我。官长违背我；先知藉巴力说预言，随从无益的神。'),
('CUV', '耶利米书', 24, 2, 9, '耶和华说：我因此必与你们争辩，也必与你们的子孙争辩。'),
('CUV', '耶利米书', 24, 2, 10, '你们且过到基提海岛去察看，打发人往基达去留心查考，看曾有这样的事没有。'),
('CUV', '耶利米书', 24, 2, 11, '岂有一国换了他的神吗？其实这不是神！但我的百姓将他们的荣耀换了那无益的神。'),
('CUV', '耶利米书', 24, 2, 12, '诸天哪，要因此惊奇，极其恐慌，甚为凄凉！这是耶和华说的。'),
('CUV', '耶利米书', 24, 2, 13, '因为我的百姓做了两件恶事，就是离弃我这活水的泉源，为自己凿出池子，是破裂不能存水的池子。'),
('CUV', '耶利米书', 24, 2, 14, '以色列是仆人吗？是家中生的奴仆吗？为何成为掠物呢？'),
('CUV', '耶利米书', 24, 2, 15, '少壮狮子向他咆哮，大声吼叫，使他的地荒凉；城邑也都焚烧，无人居住。'),
('CUV', '耶利米书', 24, 2, 16, '挪弗人和答比匿人也打破你的头顶。'),
('CUV', '耶利米书', 24, 2, 17, '这事临到你身上，不是你自招的吗？不是因耶和华─你神引你行路的时候，你离弃他吗？'),
('CUV', '耶利米书', 24, 2, 18, '现今你为何在埃及路上要喝西曷的水呢？你为何在亚述路上要喝大河的水呢？'),
('CUV', '耶利米书', 24, 2, 19, '你自己的恶必惩治你；你背道的事必责备你。由此可知可见，你离弃耶和华─你的神，不存敬畏我的心，乃为恶事，为苦事。这是主─万军之耶和华说的。'),
('CUV', '耶利米书', 24, 2, 20, '我在古时折断你的轭，解开你的绳索。你说：我必不事奉耶和华；因为你在各高冈上、各青翠树下屈身行淫（或译：我在古时折断你的轭，解开你的绳索，你就说：我必不事奉别神。谁知你在各高冈上、各青翠树下仍屈身行淫）。'),
('CUV', '耶利米书', 24, 2, 21, '然而，我栽你是上等的葡萄树，全然是真种子；你怎么向我变为外邦葡萄树的坏枝子呢？'),
('CUV', '耶利米书', 24, 2, 22, '你虽用碱、多用肥皂洗濯，你罪孽的痕迹仍然在我面前显出。这是主耶和华说的。'),
('CUV', '耶利米书', 24, 2, 23, '你怎能说：我没有玷污、没有随从众巴力？你看你谷中的路，就知道你所行的如何。你是快行的独峰驼，狂奔乱走。'),
('CUV', '耶利米书', 24, 2, 24, '你是野驴，惯在旷野，欲心发动就吸风；起性的时候谁能使牠转去呢？凡寻找牠的必不致疲乏；在牠的月分必能寻见。'),
('CUV', '耶利米书', 24, 2, 25, '我说：你不要使脚上无鞋，喉咙干渴。你倒说：这是枉然。我喜爱别神，我必随从他们。'),
('CUV', '耶利米书', 24, 2, 26, '贼被捉拿，怎样羞愧，﹞以色列家和他们的君王、首领、祭司、先知也都照样羞愧。'),
('CUV', '耶利米书', 24, 2, 27, '他们向木头说：你是我的父；向石头说：你是生我的。他们以背向我，不以面向我；及至遭遇患难的时候却说：起来拯救我们。'),
('CUV', '耶利米书', 24, 2, 28, '你为自己做的神在哪里呢？你遭遇患难的时候，叫他们起来拯救你罢！犹大啊，你神的数目与你城的数目相等。'),
('CUV', '耶利米书', 24, 2, 29, '耶和华说：你们为何与我争辩呢？你们都违背了我。'),
('CUV', '耶利米书', 24, 2, 30, '我责打你们的儿女是徒然的，他们不受惩治。你们自己的刀吞灭你们的先知，好像残害的狮子。'),
('CUV', '耶利米书', 24, 2, 31, '这世代的人哪，你们要看明耶和华的话。我岂向以色列作旷野呢？或作幽暗之地呢？我的百姓为何说：我们脱离约束，再不归向你了？'),
('CUV', '耶利米书', 24, 2, 32, '处女岂能忘记他的妆饰呢？新妇岂能忘记他的美衣呢？我的百姓却忘记了我无数的日子！'),
('CUV', '耶利米书', 24, 2, 33, '你怎么修饰你的道路要求爱情呢？就是恶劣的妇人你也叫他们行你的路。'),
('CUV', '耶利米书', 24, 2, 34, '并且你的衣襟上有无辜穷人的血；你杀他们并不是遇见他们挖窟窿，乃是因这一切的事。'),
('CUV', '耶利米书', 24, 2, 35, '你还说：我无辜；耶和华的怒气必定向我消了。看哪，我必审问你；因你自说：我没有犯罪。'),
('CUV', '耶利米书', 24, 2, 36, '你为何东跑西奔要更换你的路呢？你必因埃及蒙羞，像从前因亚述蒙羞一样。'),
('CUV', '耶利米书', 24, 2, 37, '你也必两手抱头从埃及出来；因为耶和华已经弃绝你所倚靠的，你必不因他们得顺利。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 3, 1, '有话说：人若休妻，妻离他而去，作了别人的妻，前夫岂能再收回他来？若收回他来，那地岂不是大大玷污了么？但你和许多亲爱的行邪淫，还可以归向我。这是耶和华说的。'),
('CUV', '耶利米书', 24, 3, 2, '你向净光的高处举目观看，你在何处没有淫行呢？你坐在道旁等候，好像亚拉伯人在旷野埋伏一样，并且你的淫行邪恶玷污了全地。'),
('CUV', '耶利米书', 24, 3, 3, '因此甘霖停止，春（原文是晚）雨不降。你还是有娼妓之脸，不顾羞耻。'),
('CUV', '耶利米书', 24, 3, 4, '从今以后，你岂不向我呼叫说：我父啊，你是我幼年的恩主。'),
('CUV', '耶利米书', 24, 3, 5, '耶和华岂永远怀怒，存留到底吗？看哪，你又发恶言又行坏事，随自己的私意而行（或译：你虽这样说，还是行恶放纵欲心）。'),
('CUV', '耶利米书', 24, 3, 6, '约西亚王在位的时候，耶和华又对我说：「背道的以色列所行的，你看见没有？他上各高山，在各青翠树下行淫。'),
('CUV', '耶利米书', 24, 3, 7, '他行这些事以后，我说他必归向我，他却不归向我。他奸诈的妹妹犹大也看见了。'),
('CUV', '耶利米书', 24, 3, 8, '背道的以色列行淫，我为这缘故给他休书休他；我看见他奸诈的妹妹犹大，还不惧怕，也去行淫。'),
('CUV', '耶利米书', 24, 3, 9, '因以色列轻忽了他的淫乱，和石头木头行淫，地就被玷污了。'),
('CUV', '耶利米书', 24, 3, 10, '虽有这一切的事，他奸诈的妹妹犹大还不一心归向我，不过是假意归我。这是耶和华说的。」'),
('CUV', '耶利米书', 24, 3, 11, '耶和华对我说：「背道的以色列比奸诈的犹大还显为义。'),
('CUV', '耶利米书', 24, 3, 12, '你去向北方宣告说：耶和华说：背道的以色列啊，回来吧！我必不怒目看你们；因为我是慈爱的，我必不永远存怒。这是耶和华说的。'),
('CUV', '耶利米书', 24, 3, 13, '只要承认你的罪孽，就是你违背耶和华─你的神，在各青翠树下向别神东奔西跑，没有听从我的话。这是耶和华说的。'),
('CUV', '耶利米书', 24, 3, 14, '耶和华说：背道的儿女啊，回来吧！因为我作你们的丈夫，并且我必将你们从一城取一人，从一族取两人，带到锡安。'),
('CUV', '耶利米书', 24, 3, 15, '我也必将合我心的牧者赐给你们。他们必以知识和智慧牧养你们。」'),
('CUV', '耶利米书', 24, 3, 16, '耶和华说：「你们在国中生养众多；当那些日子，人必不再提说耶和华的约柜，不追想，不记念，不觉缺少，也不再制造。'),
('CUV', '耶利米书', 24, 3, 17, '那时，人必称耶路撒冷为耶和华的宝座；万国必到耶路撒冷，在耶和华立名的地方聚集。他们必不再随从自己顽梗的恶心行事。'),
('CUV', '耶利米书', 24, 3, 18, '当那些日子，犹大家要和以色列家同行，从北方之地一同来到我赐给你们列祖为业之地。」'),
('CUV', '耶利米书', 24, 3, 19, '我说：我怎样将你安置在儿女之中，赐给你美地，就是万国中肥美的产业。我又说：你们必称我为父，也不再转去不跟从我。'),
('CUV', '耶利米书', 24, 3, 20, '以色列家，你们向我行诡诈，真像妻子行诡诈离开他丈夫一样。这是耶和华说的。'),
('CUV', '耶利米书', 24, 3, 21, '在净光的高处听见人声，就是以色列人哭泣恳求之声，乃因他们走弯曲之道，忘记耶和华─他们的神。'),
('CUV', '耶利米书', 24, 3, 22, '你们这背道的儿女啊，回来吧！我要医治你们背道的病。看哪，我们来到你这里，因你是耶和华─我们的神。'),
('CUV', '耶利米书', 24, 3, 23, '仰望从小山或从大山的喧嚷中得帮助，真是枉然的。以色列得救，诚然在乎耶和华─我们的神。'),
('CUV', '耶利米书', 24, 3, 24, '从我们幼年以来，那可耻的偶像将我们列祖所劳碌得来的羊群、牛群，和他们的儿女都吞吃了。'),
('CUV', '耶利米书', 24, 3, 25, '我们在羞耻中躺卧罢！愿惭愧将我们遮盖；因为从立国（原文是幼年）以来，我们和我们的列祖常常得罪耶和华─我们的神，没有听从耶和华─我们神的话。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 4, 1, '耶和华说：以色列啊，你若回来归向我，若从我眼前除掉你可憎的偶像，你就不被迁移。'),
('CUV', '耶利米书', 24, 4, 2, '你必凭诚实、公平、公义，指著永生的耶和华起誓；列国必因耶和华称自己为有福，也必因他夸耀。'),
('CUV', '耶利米书', 24, 4, 3, '耶和华对犹大和耶路撒冷人如此说：要开垦你们的荒地，不要撒种在荆棘中。'),
('CUV', '耶利米书', 24, 4, 4, '犹大人和耶路撒冷的居民哪，你们当自行割礼，归耶和华，将心里的污秽除掉；恐怕我的忿怒因你们的恶行发作，如火著起，甚至无人能以熄灭！'),
('CUV', '耶利米书', 24, 4, 5, '你们当传扬在犹大，宣告在耶路撒冷说：你们当在国中吹角，高声呼叫说：你们当聚集！我们好进入坚固城！'),
('CUV', '耶利米书', 24, 4, 6, '应当向锡安竖立大旗。要逃避，不要迟延，因我必使灾祸与大毁灭从北方来到。'),
('CUV', '耶利米书', 24, 4, 7, '有狮子从密林中上来，是毁坏列国的。他已经动身出离本处，要使你的地荒凉，使你的城邑变为荒场无人居住。'),
('CUV', '耶利米书', 24, 4, 8, '因此，你们当腰束麻布，大声哀号，因为耶和华的烈怒没有向我们转消。'),
('CUV', '耶利米书', 24, 4, 9, '耶和华说：到那时，君王和首领的心都要消灭；祭司都要惊奇，先知都要诧异。'),
('CUV', '耶利米书', 24, 4, 10, '我说：哀哉！主耶和华啊，你真是大大地欺哄这百姓和耶路撒冷，说：你们必得平安。其实刀剑害及性命了。'),
('CUV', '耶利米书', 24, 4, 11, '那时，必有话对这百姓和耶路撒冷说：有一阵热风从旷野净光的高处向我的众民（原文是民女）刮来，不是为簸扬，也不是为扬净。'),
('CUV', '耶利米书', 24, 4, 12, '必有一阵更大的风从这些地方为我刮来；现在我又必发出判语，攻击他们。'),
('CUV', '耶利米书', 24, 4, 13, '看哪，仇敌必如云上来；他的战车如旋风，他的马匹比鹰更快。我们有祸了！我们败落了！'),
('CUV', '耶利米书', 24, 4, 14, '耶路撒冷啊，你当洗去心中的恶，使你可以得救。恶念存在你心里要到几时呢？'),
('CUV', '耶利米书', 24, 4, 15, '有声音从但传扬，从以法莲山报祸患。'),
('CUV', '耶利米书', 24, 4, 16, '你们当传给列国，报告攻击耶路撒冷的事说：有探望的人从远方来到，向犹大的城邑大声呐喊。'),
('CUV', '耶利米书', 24, 4, 17, '他们周围攻击耶路撒冷，好像看守田园的，因为他背叛了我。这是耶和华说的。'),
('CUV', '耶利米书', 24, 4, 18, '你的行动，你的作为，招惹这事；这是你罪恶的结果，实在是苦，是害及你心了！'),
('CUV', '耶利米书', 24, 4, 19, '我的肺腑啊，我的肺腑啊，我心疼痛！我心在我著面烦躁不安。我不能静默不言，因为我已经听见角声和打仗的喊声。'),
('CUV', '耶利米书', 24, 4, 20, '毁坏的信息连络不绝，因为全地荒废。我的帐棚忽然毁坏；我的幔子顷刻破裂。'),
('CUV', '耶利米书', 24, 4, 21, '我看见大旗，听见角声，要到几时呢？'),
('CUV', '耶利米书', 24, 4, 22, '耶和华说：我的百性愚顽，不认识我；他们是愚昧无知的儿女，有智慧行恶，没有知识行善。'),
('CUV', '耶利米书', 24, 4, 23, '先知说：我观看地，不料，地是空虚混沌；我观看天，天也无光。'),
('CUV', '耶利米书', 24, 4, 24, '我观看大山，不料，尽都震动，小山也都摇来摇去。'),
('CUV', '耶利米书', 24, 4, 25, '我观看，不料，无人；空中的飞鸟也都躲避。'),
('CUV', '耶利米书', 24, 4, 26, '我观看，不料，肥田变为荒地；一切城邑在耶和华面前，因他的烈怒都被拆毁。'),
('CUV', '耶利米书', 24, 4, 27, '耶和华如此说：全地必然荒凉，我却不毁灭净尽。'),
('CUV', '耶利米书', 24, 4, 28, '因此，地要悲哀，在上的天也必黑暗；因为我言已出，我意已定，必不后悔，也不转意不做。'),
('CUV', '耶利米书', 24, 4, 29, '各城的人因马兵和弓箭手的响声就都逃跑，进入密林，爬上磐石；各城被撇下，无人住在其中。'),
('CUV', '耶利米书', 24, 4, 30, '你凄凉的时候要怎样行呢？你虽穿上朱红衣服，佩戴黄金装饰，用颜料修饰眼目，这样标致是枉然的！恋爱你的藐视你，并且寻索你的性命。'),
('CUV', '耶利米书', 24, 4, 31, '我听见有声音，仿佛妇人产难的声音，好像生头胎疼痛的声音，是锡安女子（就是指民的意思）的声音；他喘著气、挓抄手，说：我有祸了！在杀人的跟前，我的心发昏了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 5, 1, '你们当在耶路撒冷的街上跑来跑去，在宽阔处寻找，看看有一人行公义求诚实没有？若有，我就赦免这城。'),
('CUV', '耶利米书', 24, 5, 2, '其中的人虽然指著永生的耶和华起誓，所起的誓实在是假的。'),
('CUV', '耶利米书', 24, 5, 3, '耶和华啊，你的眼目不是看顾诚实么？你击打他们，他们却不伤恸；你毁灭他们，他们仍不受惩治。他们使脸刚硬过于磐石，不肯回头。'),
('CUV', '耶利米书', 24, 5, 4, '我说：这些人实在是贫穷的，是愚昧的，因为不晓得耶和华的作为和他们神的法则。'),
('CUV', '耶利米书', 24, 5, 5, '我要去见尊大的人，对他们说话，因为他们晓得耶和华的作为和他们神的法则。哪知，这些人齐心将轭折断，挣开绳索。'),
('CUV', '耶利米书', 24, 5, 6, '因此，林中的狮子必害死他们；晚上（或译：野地）的豺狼必灭绝他们；豹子要在城外窥伺他们。凡出城的必被撕碎；因为他们的罪过极多，背道的事也加增了。'),
('CUV', '耶利米书', 24, 5, 7, '我怎能赦免你呢？你的儿女离弃我，又指著那不是神的起誓。我使他们饱足，他们就行奸淫，成群地聚集在娼妓家里。'),
('CUV', '耶利米书', 24, 5, 8, '他们像喂饱的马到处乱跑，各向他邻舍的妻发嘶声。'),
('CUV', '耶利米书', 24, 5, 9, '耶和华说：我岂不因这些事讨罪呢？岂不报复这样的国民呢？'),
('CUV', '耶利米书', 24, 5, 10, '你们要上他葡萄园的墙施行毁坏，但不可毁坏净尽，只可除掉他的枝子，因为不属耶和华。'),
('CUV', '耶利米书', 24, 5, 11, '原来以色列家和犹大家大行诡诈攻击我。这是耶和华说的。'),
('CUV', '耶利米书', 24, 5, 12, '他们不认耶和华，说：这并不是他，灾祸必不临到我们；刀剑和饥荒，我们也看不见。'),
('CUV', '耶利米书', 24, 5, 13, '先知的话必成为风；道也不在他们里面。这灾必临到他们身上。'),
('CUV', '耶利米书', 24, 5, 14, '所以耶和华─万军之神如此说：因为百姓说这话，我必使我的话在你口中为火，使他们为柴；这火便将他们烧灭。'),
('CUV', '耶利米书', 24, 5, 15, '耶和华说：以色列家啊，我必使一国的民从远方来攻击你，是强盛的国，是从古而有的国。他们的言语你不晓得，他们的话你不明白。'),
('CUV', '耶利米书', 24, 5, 16, '他们的箭袋是敞开的坟墓；他们都是勇士。'),
('CUV', '耶利米书', 24, 5, 17, '他们必吃尽你的庄稼和你的粮食，是你儿女该吃的；必吃尽你的牛羊，吃尽你的葡萄和无花果；又必用刀毁坏你所倚靠的坚固城。'),
('CUV', '耶利米书', 24, 5, 18, '耶和华说：就是到那时，我也不将你们毁灭净尽。'),
('CUV', '耶利米书', 24, 5, 19, '百姓若说：耶和华─我们的神为甚么向我们行这一切事呢？你就对他们说：你们怎样离弃耶和华（原文是我），在你们的地上事奉外邦神，也必照样在不属你们的地上事奉外邦人。'),
('CUV', '耶利米书', 24, 5, 20, '当传扬在雅各家，报告在犹大说：'),
('CUV', '耶利米书', 24, 5, 21, '愚昧无知的百姓啊，你们有眼不看，有耳不听，现在当听这话。'),
('CUV', '耶利米书', 24, 5, 22, '耶和华说：你们怎么不惧怕我呢？我以永远的定例，用沙为海的界限，水不得越过。因此，你们在我面前还不战兢么？波浪虽然翻腾，却不能逾越；虽然匉訇，却不能过去。'),
('CUV', '耶利米书', 24, 5, 23, '但这百姓有背叛忤逆的心；他们叛我而去，'),
('CUV', '耶利米书', 24, 5, 24, '心内也不说：我们应当敬畏耶和华─我们的神；他按时赐雨，就是秋雨春雨，又为我们定收割的节令，永存不废。'),
('CUV', '耶利米书', 24, 5, 25, '你们的罪孽使这些事转离你们；你们的罪恶使你们不能得福。'),
('CUV', '耶利米书', 24, 5, 26, '因为在我民中有恶人。他们埋伏窥探，好像捕鸟的人；他们设立圈套陷害人。'),
('CUV', '耶利米书', 24, 5, 27, '笼内怎样满了雀鸟，他们的房中也照样充满诡诈；所以他们得成为大，而且富足。'),
('CUV', '耶利米书', 24, 5, 28, '他们肥胖光润，作恶过甚，不为人伸冤！就是不为孤儿伸冤，不使他亨通，也不为穷人辨屈。'),
('CUV', '耶利米书', 24, 5, 29, '耶和华说：我岂不因这些事讨罪呢？岂不报复这样的国民呢？'),
('CUV', '耶利米书', 24, 5, 30, '国中有可惊骇、可憎恶的事：'),
('CUV', '耶利米书', 24, 5, 31, '就是先知说假预言，祭司藉他们把持权柄；我的百姓也喜爱这些事，到了结局你们怎样行呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 6, 1, '便雅悯人哪，你们要逃出耶路撒冷，在提哥亚吹角，在伯哈基琳立号旗；因为有灾祸与大毁灭从北方张望。'),
('CUV', '耶利米书', 24, 6, 2, '那秀美娇嫩的锡安女子（就是指民的意思），我必剪除。'),
('CUV', '耶利米书', 24, 6, 3, '牧人必引他们的羊群到他那著，在他周围支搭帐棚，各在自己所占之地使羊吃草。'),
('CUV', '耶利米书', 24, 6, 4, '你们要准备攻击他。起来罢，我们可以趁午时上去。哀哉！日已渐斜，晚影拖长了。'),
('CUV', '耶利米书', 24, 6, 5, '起来罢，我们夜间上去，毁坏他的宫殿。'),
('CUV', '耶利米书', 24, 6, 6, '因为万军之耶和华如此说：你们要砍伐树木，筑垒攻打耶路撒冷。这就是那该罚的城，其中尽是欺压。'),
('CUV', '耶利米书', 24, 6, 7, '井怎样涌出水来，这城也照样涌出恶来；在其间常听见有强暴毁灭的事，病患损伤也常在我面前。'),
('CUV', '耶利米书', 24, 6, 8, '耶路撒冷啊，你当受教，免得我心与你生疏，免得我使你荒凉，成为无人居住之地。'),
('CUV', '耶利米书', 24, 6, 9, '万军之耶和华曾如此说：敌人必掳尽以色列剩下的民，如同摘净葡萄一样。你要像摘葡萄的人摘了又摘，回手放在筐子里。'),
('CUV', '耶利米书', 24, 6, 10, '现在我可以向谁说话作见证，使他们听呢？他们的耳朵未受割礼，不能听见。看哪，耶和华的话他们以为羞辱，不以为喜悦。'),
('CUV', '耶利米书', 24, 6, 11, '因此我被耶和华的忿怒充满，难以含忍。我要倾在街中的孩童和聚会的少年人身上，连夫带妻，并年老的与日子满足的都必被擒拿。'),
('CUV', '耶利米书', 24, 6, 12, '他们的房屋、田地，和妻子都必转归别人；我要伸手攻击这地的居民。这是耶和华说的。'),
('CUV', '耶利米书', 24, 6, 13, '因为他们从最小的到至大的都一味地贪婪，从先知到祭司都行事虚谎。'),
('CUV', '耶利米书', 24, 6, 14, '他们轻轻忽忽地医治我百姓的损伤，说：平安了！平安了！其实没有平安。'),
('CUV', '耶利米书', 24, 6, 15, '他们行可憎的事知道惭愧么？不然，他们毫不惭愧，也不知羞耻。因此，他们必在仆倒的人中仆倒；我向他们讨罪的时候，他们必致跌倒。这是耶和华说的。'),
('CUV', '耶利米书', 24, 6, 16, '耶和华如此说：你们当站在路上察看，访问古道，哪是善道，便行在其间；这样，你们心里必得安息。他们却说：我们不行在其间。'),
('CUV', '耶利米书', 24, 6, 17, '我设立守望的人照管你们，说：要听角声。他们却说：我们不听。'),
('CUV', '耶利米书', 24, 6, 18, '列国啊，因此你们当听！会众啊，要知道他们必遭遇的事。'),
('CUV', '耶利米书', 24, 6, 19, '地啊，当听！我必使灾祸临到这百姓，就是他们意念所结的果子；因为他们不听从我的言语，至于我的训诲（或译：律法），他们也厌弃了。'),
('CUV', '耶利米书', 24, 6, 20, '从示巴出的乳香，从远方出的菖蒲（或译：甘蔗）奉来给我有何益呢？你们的燔祭不蒙悦纳；你们的平安祭，我也不喜悦。'),
('CUV', '耶利米书', 24, 6, 21, '所以耶和华如此说：我要将绊脚石放在这百姓前面。父亲和儿子要一同跌在其上；邻舍与朋友也都灭亡。'),
('CUV', '耶利米书', 24, 6, 22, '耶和华如此说：看哪，有一种民从北方而来，并有一大国被激动，从地极来到。'),
('CUV', '耶利米书', 24, 6, 23, '他们拿弓和枪，性情残忍，不施怜悯；他们的声音像海浪匉訇。锡安城（原文是女子）啊，他们骑马都摆队伍，如上战场的人要攻击你。'),
('CUV', '耶利米书', 24, 6, 24, '我们听见他们的风声，手就发软；痛苦将我们抓住，疼痛仿佛产难的妇人。'),
('CUV', '耶利米书', 24, 6, 25, '你们不要往田野去，也不要行在路上，因四围有仇敌的刀剑和惊吓。'),
('CUV', '耶利米书', 24, 6, 26, '我民（原文是民女）哪，应当腰束麻布，滚在灰中。你要悲伤，如丧独生子痛痛哭号，因为灭命的要忽然临到我们。'),
('CUV', '耶利米书', 24, 6, 27, '我使你在我民中为高台（或译：试验人的），为保障，使你知道试验他们的行动。'),
('CUV', '耶利米书', 24, 6, 28, '他们都是极悖逆的，往来谗谤人。他们是铜是铁，都行坏事。'),
('CUV', '耶利米书', 24, 6, 29, '风箱吹火，铅被烧毁；他们炼而又炼，终是徒然；因为恶劣的还未除掉。'),
('CUV', '耶利米书', 24, 6, 30, '人必称他们为被弃的银渣，因为耶和华已经弃掉他们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 7, 1, '耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 7, 2, '你当站在耶和华殿的门口，在那著宣传这话说：你们进这些门敬拜耶和华的一切犹大人，当听耶和华的话。'),
('CUV', '耶利米书', 24, 7, 3, '万军之耶和华─以色列的神如此说：你们改正行动作为，我就使你们在这地方仍然居住。'),
('CUV', '耶利米书', 24, 7, 4, '你们不要倚靠虚谎的话，说：这些是耶和华的殿，是耶和华的殿，是耶和华的殿！'),
('CUV', '耶利米书', 24, 7, 5, '你们若实在改正行动作为，在人和邻舍中间诚然施行公平，'),
('CUV', '耶利米书', 24, 7, 6, '不欺压寄居的和孤儿寡妇；在这地方不流无辜人的血，也不随从别神陷害自己；'),
('CUV', '耶利米书', 24, 7, 7, '我就使你们在这地方仍然居住，就是我古时所赐给你们列祖的地，直到永远。'),
('CUV', '耶利米书', 24, 7, 8, '看哪，你们倚靠虚谎无益的话。'),
('CUV', '耶利米书', 24, 7, 9, '你们偷盗，杀害，奸淫，起假誓，向巴力烧香，并随从素不认识的别神，'),
('CUV', '耶利米书', 24, 7, 10, '且来到这称为我名下的殿，在我面前敬拜；又说：我们可以自由了。你们这样的举动是要行那些可憎的事么？'),
('CUV', '耶利米书', 24, 7, 11, '这称为我名下的殿在你们眼中岂可看为贼窝么？我都看见了。这是耶和华说的。'),
('CUV', '耶利米书', 24, 7, 12, '你们且往示罗去，就是我先前立为我名的居所，察看我因这百姓以色列的罪恶向那地所行的如何。'),
('CUV', '耶利米书', 24, 7, 13, '耶和华说：现在因你们行了这一切的事，我也从早起来警戒你们，你们却不听从；呼唤你们，你们却不答应。'),
('CUV', '耶利米书', 24, 7, 14, '所以我要向这称我为名下、你们所倚靠的殿，与我所赐给你们和你们列祖的地施行，照我从前向示罗所行的一样。'),
('CUV', '耶利米书', 24, 7, 15, '我必将你们从我眼前赶出，正如赶出你们的众弟兄，就是以法莲的一切后裔。'),
('CUV', '耶利米书', 24, 7, 16, '所以，你不要为这百姓祈祷；不要为他们呼求祷告，也不要向我为他们祈求，因我不听允你。'),
('CUV', '耶利米书', 24, 7, 17, '他们在犹大城邑中和耶路撒冷街上所行的，你没有看见么？'),
('CUV', '耶利米书', 24, 7, 18, '孩子捡柴，父亲烧火，妇女抟面做饼，献给天后，又向别神浇奠祭，惹我发怒。'),
('CUV', '耶利米书', 24, 7, 19, '耶和华说：他们岂是惹我发怒呢？不是自己惹祸，以致脸上惭愧么？'),
('CUV', '耶利米书', 24, 7, 20, '所以主耶和华如此说：看哪，我必将我的怒气和忿怒倾在这地方的人和牲畜身上，并田野的树木和地著的出产上，必如火著起，不能熄灭。'),
('CUV', '耶利米书', 24, 7, 21, '万军之耶和华─以色列的神如此说：你们将燔祭加在平安祭上，吃肉罢！'),
('CUV', '耶利米书', 24, 7, 22, '因为我将你们列祖从埃及地领出来的那日，燔祭平安祭的事我并没有提说，也没有吩咐他们。'),
('CUV', '耶利米书', 24, 7, 23, '我只吩咐他们这一件说：你们当听从我的话，我就作你们的神，你们也作我的子民。你们行我所吩咐的一切道，就可以得福。'),
('CUV', '耶利米书', 24, 7, 24, '他们却不听从，不侧耳而听，竟随从自己的计谋和顽梗的恶心，向后不向前。'),
('CUV', '耶利米书', 24, 7, 25, '自从你们列祖出埃及地的那日，直到今日，我差遣我的仆人众先知到你们那里去，每日从早起来差遣他们。'),
('CUV', '耶利米书', 24, 7, 26, '你们却不听从，不侧耳而听，竟硬著颈项行恶，比你们列祖更甚。'),
('CUV', '耶利米书', 24, 7, 27, '你要将这一切的话告诉他们，他们却不听从；呼唤他们，他们却不答应。'),
('CUV', '耶利米书', 24, 7, 28, '你要对他们说：这就是不听从耶和华─他们神的话、不受教训的国民；从他们的口中，诚实灭绝了。'),
('CUV', '耶利米书', 24, 7, 29, '耶路撒冷啊，要剪发抛弃，在净光的高处举哀；因为耶和华丢掉离弃了惹他忿怒的世代。'),
('CUV', '耶利米书', 24, 7, 30, '耶和华说：犹大人行我眼中看为恶的事，将可憎之物设立在称为我名下的殿中，污秽这殿。'),
('CUV', '耶利米书', 24, 7, 31, '他们在欣嫩子谷建筑陀斐特的邱坛，好在火中焚烧自己的儿女。这并不是我所吩咐的，也不是我心所起的意。'),
('CUV', '耶利米书', 24, 7, 32, '耶和华说：因此，日子将到，这地方不再称为陀斐特和欣嫩子谷，反倒称为杀戮谷。因为要在陀斐特葬埋尸首，甚至无处可葬；'),
('CUV', '耶利米书', 24, 7, 33, '并且这百姓的尸首必给空中的飞鸟和地上的野兽作食物，并无人哄赶。'),
('CUV', '耶利米书', 24, 7, 34, '那时，我必使犹大城邑中和耶路撒冷街上，欢喜和快乐的声音，新郎和新妇的声音，都止息了，因为地必成为荒场。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 8, 1, '耶和华说：到那时，人必将犹大王的骸骨和他首领的骸骨、祭司的骸骨、先知的骸骨，并耶路撒冷居民的骸骨，都从坟墓中取出来，'),
('CUV', '耶利米书', 24, 8, 2, '抛散在日头、月亮，和天上众星之下，就是他们从前所喜爱、所事奉、所随从、所求问、所敬拜的。这些骸骨不再收殓，不再葬埋，必在地面上成为粪土；'),
('CUV', '耶利米书', 24, 8, 3, '并且这恶族所剩下的民在我所赶他们到的各处，宁可拣死不拣生。这是万军之耶和华说的。'),
('CUV', '耶利米书', 24, 8, 4, '你要对他们说，耶和华如此说：人跌倒，不再起来么？人转去，不再转来么？'),
('CUV', '耶利米书', 24, 8, 5, '这耶路撒冷的民，为何恒久背道呢？他们守定诡诈，不肯回头。'),
('CUV', '耶利米书', 24, 8, 6, '我留心听，听见他们说不正直的话。无人悔改恶行，说：我做的是甚么呢？他们各人转奔己路，如马直闯战场。'),
('CUV', '耶利米书', 24, 8, 7, '空中的鹳鸟知道来去的定期；斑鸠燕子与白鹤也守候当来的时令；我的百姓却不知道耶和华的法则。'),
('CUV', '耶利米书', 24, 8, 8, '你们怎么说：我们有智慧，耶和华的律法在我们这里？看哪，文士的假笔舞弄虚假。'),
('CUV', '耶利米书', 24, 8, 9, '智慧人惭愧，惊惶，被擒拿；他们弃掉耶和华的话，心里还有甚么智慧呢？'),
('CUV', '耶利米书', 24, 8, 10, '所以我必将他们的妻子给别人，将他们的田地给别人为业；因为他们从最小的到至大的都一味地贪婪，从先知到祭司都行事虚谎。'),
('CUV', '耶利米书', 24, 8, 11, '他们轻轻忽忽地医治我百姓的损伤，说：平安了！平安了！其实没有平安。'),
('CUV', '耶利米书', 24, 8, 12, '他们行可憎的事知道惭愧么？不然，他们毫不惭愧，也不知羞耻。因此他们必在仆倒的人中仆倒；我向他们讨罪的时候，他们必致跌倒。这是耶和华说的。'),
('CUV', '耶利米书', 24, 8, 13, '耶和华说：我必使他们全然灭绝；葡萄树上必没有葡萄，无花果树上必没有果子，叶子也必枯干。我所赐给他们的，必离开他们过去。'),
('CUV', '耶利米书', 24, 8, 14, '我们为何静坐不动呢？我们当聚集，进入坚固城，在那里静默不言；因为耶和华─我们的神使我们静默不言，又将苦胆水给我们喝，都因我们得罪了耶和华。'),
('CUV', '耶利米书', 24, 8, 15, '我们指望平安，却得不著好处；指望痊愈的时候，不料，受了惊惶。'),
('CUV', '耶利米书', 24, 8, 16, '听见从但那里敌人的马喷鼻气，他的壮马发嘶声，全地就都震动；因为他们来吞灭这地和其上所有的，吞灭这城与其中的居民。'),
('CUV', '耶利米书', 24, 8, 17, '看哪，我必使毒蛇到你们中间，是不服法术的，必咬你们。这是耶和华说的。'),
('CUV', '耶利米书', 24, 8, 18, '我有忧愁，愿能自慰；我心在我里面发昏。'),
('CUV', '耶利米书', 24, 8, 19, '听啊，是我百姓的哀声从极远之地而来，说：耶和华不在锡安么？锡安的王不在其中么？耶和华说：他们为甚么以雕刻的偶像和外邦虚无的神惹我发怒呢？'),
('CUV', '耶利米书', 24, 8, 20, '麦秋已过，夏令已完，我们还未得救！'),
('CUV', '耶利米书', 24, 8, 21, '先知说：因我百姓的损伤，我也受了损伤。我哀痛，惊惶将我抓住。'),
('CUV', '耶利米书', 24, 8, 22, '在基列岂没有乳香呢？在那著岂没有医生呢？我百姓为何不得痊愈呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 9, 1, '但愿我的头为水，我的眼为泪的泉源，我好为我百姓（原文是民女；七节同）中被杀的人昼夜哭泣。'),
('CUV', '耶利米书', 24, 9, 2, '惟愿我在旷野有行路人住宿之处，使我可以离开我的民出去；因他们都是行奸淫的，是行诡诈的一党。'),
('CUV', '耶利米书', 24, 9, 3, '他们弯起舌头像弓一样，为要说谎话。他们在国中增长势力，不是为行诚实，乃是恶上加恶，并不认识我。这是耶和华说的。'),
('CUV', '耶利米书', 24, 9, 4, '你们各人当谨防邻舍，不可信靠弟兄；因为弟兄尽行欺骗，邻舍都往来谗谤人。'),
('CUV', '耶利米书', 24, 9, 5, '他们各人欺哄邻舍，不说真话；他们教舌头学习说谎，劳劳碌碌地作孽。'),
('CUV', '耶利米书', 24, 9, 6, '你的住处在诡诈的人中；他们因行诡诈，不肯认识我。这是耶和华说的。'),
('CUV', '耶利米书', 24, 9, 7, '所以万军之耶和华如此说：看哪，我要将他们融化熬炼；不然，我因我百姓的罪该怎样行呢？'),
('CUV', '耶利米书', 24, 9, 8, '他们的舌头是毒箭，说话诡诈；人与邻舍口说和平话，心却谋害他。'),
('CUV', '耶利米书', 24, 9, 9, '耶和华说：我岂不因这些事讨他们的罪呢？岂不报复这样的国民呢？'),
('CUV', '耶利米书', 24, 9, 10, '我要为山岭哭泣悲哀，为旷野的草场扬声哀号；因为都已干焦，甚至无人经过。人也听不见牲畜鸣叫，空中的飞鸟和地上的野兽都已逃去。'),
('CUV', '耶利米书', 24, 9, 11, '我必使耶路撒冷变为乱堆，为野狗的住处，也必使犹大的城邑变为荒场，无人居住。'),
('CUV', '耶利米书', 24, 9, 12, '谁是智慧人，可以明白这事？耶和华的口向谁说过，使他可以传说？遍地为何灭亡，干焦好像旷野，甚至无人经过呢？'),
('CUV', '耶利米书', 24, 9, 13, '耶和华说：因为这百姓离弃我，在他们面前所设立的律法没有遵行，也没有听从我的话；'),
('CUV', '耶利米书', 24, 9, 14, '只随从自己顽梗的心行事，照他们列祖所教训的随从众巴力。'),
('CUV', '耶利米书', 24, 9, 15, '所以万军之耶和华─以色列的神如此说：看哪，我必将茵𫈟给这百姓吃，又将苦胆水给他们喝。'),
('CUV', '耶利米书', 24, 9, 16, '我要把他们散在列邦中，就是他们和他们列祖素不认识的列邦。我也要使刀剑追杀他们，直到将他们灭尽。'),
('CUV', '耶利米书', 24, 9, 17, '万军之耶和华如此说：你们应当思想，将善唱哀歌的妇女召来，又打发人召善哭的妇女来，'),
('CUV', '耶利米书', 24, 9, 18, '叫他们速速为我们举哀，使我们眼泪汪汪，使我们的眼皮涌出水来。'),
('CUV', '耶利米书', 24, 9, 19, '因为听见哀声出于锡安，说：我们怎样败落了！我们大大地惭愧！我们撇下地土；人也拆毁了我们的房屋。'),
('CUV', '耶利米书', 24, 9, 20, '妇女们哪，你们当听耶和华的话，领受他口中的言语；又当教导你们的儿女举哀，各人教导邻舍唱哀歌。'),
('CUV', '耶利米书', 24, 9, 21, '因为死亡上来，进了我们的窗户，入了我们的宫殿；要从外边剪除孩童，从街上剪除少年人。'),
('CUV', '耶利米书', 24, 9, 22, '你当说，耶和华如此说：人的尸首必倒在田野像粪土，又像收割的人遗落的一把禾稼，无人收取。'),
('CUV', '耶利米书', 24, 9, 23, '耶和华如此说：智慧人不要因他的智慧夸口，勇士不要因他的勇力夸口，财主不要因他的财物夸口。'),
('CUV', '耶利米书', 24, 9, 24, '夸口的却因他有聪明，认识我是耶和华，又知道我喜悦在世上施行慈爱、公平，和公义，以此夸口。这是耶和华说的。'),
('CUV', '耶利米书', 24, 9, 25, '耶和华说：看哪，日子将到，我要刑罚一切受过割礼、心却未受割礼的，'),
('CUV', '耶利米书', 24, 9, 26, '就是埃及、犹大、以东、亚扪人、摩押人，和一切住在旷野剃周围头发的；因为列国人都没有受割礼，以色列人心中也没有受割礼。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 10, 1, '以色列家啊，要听耶和华对你们所说的话。'),
('CUV', '耶利米书', 24, 10, 2, '耶和华如此说：你们不要效法列国的行为，也不要为天象惊惶，因列国为此事惊惶。'),
('CUV', '耶利米书', 24, 10, 3, '众民的风俗是虚空的；他们在树林中用斧子砍伐一棵树，匠人用手工造成偶像。'),
('CUV', '耶利米书', 24, 10, 4, '他们用金银妆饰他，用钉子和锤子钉稳，使他不动摇。'),
('CUV', '耶利米书', 24, 10, 5, '他好像棕树，是旋成的，不能说话，不能行走，必须有人抬著。你们不要怕他；他不能降祸，也无力降福。'),
('CUV', '耶利米书', 24, 10, 6, '耶和华啊，没有能比你的！你本为大，有大能大力的名。'),
('CUV', '耶利米书', 24, 10, 7, '万国的王啊，谁不敬畏你？敬畏你本是合宜的；因为在列国的智慧人中，虽有政权的尊荣，也不能比你。'),
('CUV', '耶利米书', 24, 10, 8, '他们尽都是畜类，是愚昧的。偶像的训诲算甚么呢？偶像不过是木头。'),
('CUV', '耶利米书', 24, 10, 9, '有银子打成片，是从他施带来的，并有从乌法来的金子，都是匠人和银匠的手工，又有蓝色紫色料的衣服，都是巧匠的工作。'),
('CUV', '耶利米书', 24, 10, 10, '惟耶和华是真神，是活神，是永远的王。他一发怒，大地震动；他一恼恨，列国都担当不起。'),
('CUV', '耶利米书', 24, 10, 11, '你们要对他们如此说：不是那创造天地的神，必从地上从天下被除灭！）'),
('CUV', '耶利米书', 24, 10, 12, '耶和华用能力创造大地，用智慧建立世界，用聪明铺张穹苍。'),
('CUV', '耶利米书', 24, 10, 13, '他一发声，空中便有多水激动；他使云雾从地极上腾；他造电随雨而闪，从他府库中带出风来。'),
('CUV', '耶利米书', 24, 10, 14, '各人都成了畜类，毫无知识；各银匠都因他雕刻的偶像羞愧。他所铸的偶像本是虚假的，其中并无气息，'),
('CUV', '耶利米书', 24, 10, 15, '都是虚无的，是迷惑人的工作；到追讨的时候必被除灭。'),
('CUV', '耶利米书', 24, 10, 16, '雅各的分不像这些，因他是造作万有的主。以色列也是他产业的支派，万军之耶和华是他的名。'),
('CUV', '耶利米书', 24, 10, 17, '受围困的人哪，当收拾你的财物，从国中带出去。'),
('CUV', '耶利米书', 24, 10, 18, '因为耶和华如此说：这时候，我必将此地的居民，好像用机弦甩出去，又必加害在他们身上，使他们觉悟。'),
('CUV', '耶利米书', 24, 10, 19, '民说：祸哉！我受损伤；我的伤痕极其重大。我却说：这真是我的痛苦，必须忍受。'),
('CUV', '耶利米书', 24, 10, 20, '我的帐棚毁坏；我的绳索折断。我的儿女离我出去，没有了。无人再支搭我的帐棚，挂起我的幔子。'),
('CUV', '耶利米书', 24, 10, 21, '因为牧人都成为畜类，没有求问耶和华，所以不得顺利；他们的羊群也都分散。'),
('CUV', '耶利米书', 24, 10, 22, '有风声！看哪，敌人来了！有大扰乱从北方出来，要使犹大城邑变为荒凉，成为野狗的住处。'),
('CUV', '耶利米书', 24, 10, 23, '耶和华啊，我晓得人的道路不由自己，行路的人也不能定自己的脚步。'),
('CUV', '耶利米书', 24, 10, 24, '耶和华啊，求你从宽惩治我，不要在你的怒中惩治我，恐怕使我归于无有。'),
('CUV', '耶利米书', 24, 10, 25, '愿你将忿怒倾在不认识你的列国中，和不求告你名的各族上；因为他们吞了雅各，不但吞了，而且灭绝，把他的住处变为荒场。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 11, 1, '耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 11, 2, '当听这约的话，告诉犹大人和耶路撒冷的居民，'),
('CUV', '耶利米书', 24, 11, 3, '对他们说，耶和华─以色列的神如此说：不听从这约之话的人必受咒诅。'),
('CUV', '耶利米书', 24, 11, 4, '这约是我将你们列祖从埃及地领出来、脱离铁炉的那日所吩咐他们的，说：你们要听从我的话，照我一切所吩咐的去行。这样，你们就作我的子民，我也作你们的神；'),
('CUV', '耶利米书', 24, 11, 5, '我好坚定向你们列祖所起的誓，给他们流奶与蜜之地，正如今日一样。我就回答说：耶和华啊，阿们！'),
('CUV', '耶利米书', 24, 11, 6, '耶和华对我说：你要在犹大城邑中和耶路撒冷街市上，宣告这一切话说：你们当听从遵行这约的话。'),
('CUV', '耶利米书', 24, 11, 7, '因为我将你们列祖从埃及地领出来的那日，直到今日，都是从早起来，切切诰诫他们说：你们当听从我的话。'),
('CUV', '耶利米书', 24, 11, 8, '他们却不听从，不侧耳而听，竟随从自己顽梗的恶心去行。所以我使这约中一切咒诅的话临到他们身上；这约是我吩咐他们行的，他们却不去行。'),
('CUV', '耶利米书', 24, 11, 9, '耶和华对我说：在犹大人和耶路撒冷居民中有同谋背叛的事。'),
('CUV', '耶利米书', 24, 11, 10, '他们转去效法他们的先祖，不肯听我的话，犯罪作孽，又随从别神，事奉他。以色列家和犹大家背了我与他们列祖所立的约。'),
('CUV', '耶利米书', 24, 11, 11, '所以耶和华如此说：我必使灾祸临到他们，是他们不能逃脱的。他们必向我哀求，我却不听。'),
('CUV', '耶利米书', 24, 11, 12, '那时，犹大城邑的人和耶路撒冷的居民要去哀求他们烧香所供奉的神；只是遭难的时候，这些神毫不拯救他们。'),
('CUV', '耶利米书', 24, 11, 13, '犹大啊，你神的数目与你城的数目相等；你为那可耻的巴力所筑烧香的坛也与耶路撒冷街道的数目相等。'),
('CUV', '耶利米书', 24, 11, 14, '所以你不要为这百姓祈祷，不要为他们呼求祷告；因为他们遭难向我哀求的时候，我必不应允。'),
('CUV', '耶利米书', 24, 11, 15, '我所亲爱的，既行许多淫乱，圣肉也离了你，你在我殿中做甚么呢？你作恶就喜乐。'),
('CUV', '耶利米书', 24, 11, 16, '从前耶和华给你起名叫青橄榄树，又华美又结好果子；如今他用哄嚷之声，点火在其上，枝子也被折断。'),
('CUV', '耶利米书', 24, 11, 17, '原来栽培你的万军之耶和华已经说，要降祸攻击你，是因以色列家和犹大家行恶，向巴力烧香，惹我发怒，是自作自受。'),
('CUV', '耶利米书', 24, 11, 18, '耶和华指示我，我就知道；你将他们所行的给我指明。'),
('CUV', '耶利米书', 24, 11, 19, '我却像柔顺的羊羔被牵到宰杀之地；我并不知道他们设计谋害我，说：我们把树连果子都灭了罢！将他从活人之地剪除，使他的名不再被纪念。'),
('CUV', '耶利米书', 24, 11, 20, '按公义判断、察验人肺腑心肠的万军之耶和华啊，我却要见你在他们身上报仇，因我将我的案件向你禀明了。'),
('CUV', '耶利米书', 24, 11, 21, '所以，耶和华论到寻索你命的亚拿突人如此说：他们说：你不要奉耶和华的名说预言，免得你死在我们手中。'),
('CUV', '耶利米书', 24, 11, 22, '所以万军之耶和华如此说：看哪，我必刑罚他们；他们的少年人必被刀剑杀死，他们的儿女必因饥荒灭亡，'),
('CUV', '耶利米书', 24, 11, 23, '并且没有余剩的人留给他们；因为在追讨之年，我必使灾祸临到亚拿突人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 12, 1, '耶和华啊，我与你争辩的时候，你显为义；但有一件，我还要与你理论：恶人的道路为何亨通呢？大行诡诈的为何得安逸呢？'),
('CUV', '耶利米书', 24, 12, 2, '你栽培了他们，他们也扎了根，长大，而且结果。他们的口是与你相近，心却与你远离。'),
('CUV', '耶利米书', 24, 12, 3, '耶和华啊，你晓得我，看见我，察验我向你是怎样的心。求你将他们拉出来，好像将宰的羊，叫他们等候杀戮的日子。'),
('CUV', '耶利米书', 24, 12, 4, '这地悲哀，通国的青草枯干，要到几时呢？因其上居民的恶行，牲畜和飞鸟都灭绝了。他们曾说：他看不见我们的结局。'),
('CUV', '耶利米书', 24, 12, 5, '耶和华说：你若与步行的人同跑，尚且觉累，怎能与马赛跑呢？你在平安之地，虽然安稳，在约但河边的丛林要怎样行呢？'),
('CUV', '耶利米书', 24, 12, 6, '因为连你弟兄和你父家都用奸诈待你。他们也在你后边大声喊叫，虽向你说好话，你也不要信他们。'),
('CUV', '耶利米书', 24, 12, 7, '我离了我的殿宇，撇弃我的产业，将我心里所亲爱的交在他仇敌的手中。'),
('CUV', '耶利米书', 24, 12, 8, '我的产业向我如林中的狮子，他发声攻击我，因此我恨恶他。'),
('CUV', '耶利米书', 24, 12, 9, '我的产业向我岂如斑点的鸷鸟呢？鸷鸟岂在他四围攻击他呢？你们要去聚集田野的百兽，带来吞吃罢！'),
('CUV', '耶利米书', 24, 12, 10, '许多牧人毁坏我的葡萄园，践踏我的分，使我美好的分变为荒凉的旷野。'),
('CUV', '耶利米书', 24, 12, 11, '他们使地荒凉；地既荒凉，便向我悲哀。全地荒凉，因无人介意。'),
('CUV', '耶利米书', 24, 12, 12, '灭命的都来到旷野中一切净光的高处；耶和华的刀从地这边直到地那边尽行杀灭。凡有血气的都不得平安。'),
('CUV', '耶利米书', 24, 12, 13, '他们种的是麦子，收的是荆棘；劳劳苦苦却毫无益处。因耶和华的烈怒，你们必为自己的土产羞愧。'),
('CUV', '耶利米书', 24, 12, 14, '耶和华如此说：一切恶邻，就是占据我使百姓以色列所承巡菇业的，我要将他们拔出本地，又要将犹大家从他们中间拔出来。'),
('CUV', '耶利米书', 24, 12, 15, '我拔出他们以后，我必转过来怜悯他们，把他们再带回来，各归本业，各归故土。'),
('CUV', '耶利米书', 24, 12, 16, '他们若殷勤学习我百姓的道，指著我的名起誓说：我指著永生的耶和华起誓，正如他们从前教我百姓指著巴力起誓，他们就必建立在我百姓中间。'),
('CUV', '耶利米书', 24, 12, 17, '他们若是不听，我必拔出那国，拔出而且毁灭。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 13, 1, '耶和华对我如此说：你去买一根麻布带子束腰，不可放在水中。'),
('CUV', '耶利米书', 24, 13, 2, '我就照著耶和华的话，买了一根带子束腰。'),
('CUV', '耶利米书', 24, 13, 3, '耶和华的话第二次临到我说：'),
('CUV', '耶利米书', 24, 13, 4, '要拿著你所买的腰带，就是你腰上的带子，起来往伯拉河去，将腰带藏在那里的磐石穴中。'),
('CUV', '耶利米书', 24, 13, 5, '我就去，照著耶和华所吩咐我的，将腰带藏在伯拉河边。'),
('CUV', '耶利米书', 24, 13, 6, '过了多日，耶和华对我说：你起来往伯拉河去，将我吩咐你藏在那里的腰带取出来。'),
('CUV', '耶利米书', 24, 13, 7, '我就往伯拉河去，将腰带从我所藏的地方刨出来，见腰带已经变坏，毫无用了。'),
('CUV', '耶利米书', 24, 13, 8, '耶和华的话临到我说：'),
('CUV', '耶利米书', 24, 13, 9, '耶和华如此说：我必照样败坏犹大的骄傲和耶路撒冷的大骄傲。'),
('CUV', '耶利米书', 24, 13, 10, '这恶民不肯听我的话，按自己顽梗的心而行，随从别神，事奉敬拜，他们也必像这腰带变为无用。'),
('CUV', '耶利米书', 24, 13, 11, '耶和华说：腰带怎样紧贴人腰，照样，我也使以色列全家和犹大全家紧贴我，好叫他们属我为子民，使我得名声，得颂赞，得荣耀；他们却不肯听。'),
('CUV', '耶利米书', 24, 13, 12, '所以你要对他们说：耶和华─以色列的神如此说：各坛都要盛满了酒。他们必对你说：我们岂不确知各坛都要盛满了酒呢？'),
('CUV', '耶利米书', 24, 13, 13, '你就要对他们说：耶和华如此说：我必使这地的一切居民，就是坐大卫宝座的君王和祭司，与先知，并耶路撒冷的一切居民，都酩酊大醉。'),
('CUV', '耶利米书', 24, 13, 14, '耶和华说：我要使他们彼此相碰，就是父与子彼此相碰；我必不可怜，不顾惜，不怜悯，以致灭绝他们。'),
('CUV', '耶利米书', 24, 13, 15, '你们当听，当侧耳而听。不要骄傲，因为耶和华已经说了。'),
('CUV', '耶利米书', 24, 13, 16, '耶和华─你们的神未使黑暗来到，你们的脚未在昏暗山上绊跌之先，当将荣耀归给他；免得你们盼望光明，他使光明变为死荫，成为幽暗。'),
('CUV', '耶利米书', 24, 13, 17, '你们若不听这话，我必因你们的骄傲在暗地哭泣；我眼必痛哭流泪，因为耶和华的群众被掳去了。'),
('CUV', '耶利米书', 24, 13, 18, '你要对君王和太后说：你们当自卑，坐在下边；因你们的头巾，就是你们的华冠，已经脱落了。'),
('CUV', '耶利米书', 24, 13, 19, '南方的城尽都关闭，无人开放；犹大全被掳掠，且掳掠净尽。'),
('CUV', '耶利米书', 24, 13, 20, '你们要举目观看从北方来的人。先前赐给你的群众，就是你佳美的群众，如今在哪里呢？'),
('CUV', '耶利米书', 24, 13, 21, '耶和华立你自己所交的朋友为首，辖制你，那时你还有甚么话说呢？痛苦岂不将你抓住像产难的妇人么？'),
('CUV', '耶利米书', 24, 13, 22, '你若心里说：这一切事为何临到我呢？你的衣襟揭起，你的脚跟受伤，是因你的罪孽甚多。'),
('CUV', '耶利米书', 24, 13, 23, '古实人岂能改变皮肤呢？豹岂能改变斑点呢？若能，你们这习惯行恶的便能行善了。'),
('CUV', '耶利米书', 24, 13, 24, '所以我必用旷野的风吹散他们，像吹过的碎秸一样。'),
('CUV', '耶利米书', 24, 13, 25, '耶和华说：这是你所当得的，是我量给你的分；因为你忘记我，倚靠虚假（或译：偶像）。'),
('CUV', '耶利米书', 24, 13, 26, '所以我要揭起你的衣襟，蒙在你脸上，显出你的丑陋。'),
('CUV', '耶利米书', 24, 13, 27, '你那些可憎恶之事─就是在田野的山上行奸淫，发嘶声，做淫乱的事─我都看见了。耶路撒冷啊，你有祸了！你不肯洁净，还要到几时呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 14, 1, '耶和华论到干旱之灾的话临到耶利米：'),
('CUV', '耶利米书', 24, 14, 2, '犹大悲哀，城门衰败。众人披上黑衣坐在地上；耶路撒冷的哀声上达。'),
('CUV', '耶利米书', 24, 14, 3, '他们的贵胄打发家僮打水；他们来到水池，见没有水，就拿著空器皿，蒙羞惭愧，抱头而回。'),
('CUV', '耶利米书', 24, 14, 4, '耕地的也蒙羞抱头；因为无雨降在地上，地都干裂。'),
('CUV', '耶利米书', 24, 14, 5, '田野的母鹿生下小鹿，就撇弃，因为无草。'),
('CUV', '耶利米书', 24, 14, 6, '野驴站在净光的高处，喘气好像野狗；因为无草，眼目失明。'),
('CUV', '耶利米书', 24, 14, 7, '耶和华啊，我们的罪孽虽然作见证告我们，还求你为你名的缘故行事。我们本是多次背道，得罪了你。'),
('CUV', '耶利米书', 24, 14, 8, '以色列所盼望、在患难时作他救主的啊，你为何在这地像寄居的，又像行路的只住一宵呢？'),
('CUV', '耶利米书', 24, 14, 9, '你为何像受惊的人，像不能救人的勇士呢？耶和华啊，你仍在我们中间；我们也称为你名下的人，求你不要离开我们。'),
('CUV', '耶利米书', 24, 14, 10, '耶和华对这百姓如此说：这百姓喜爱妄行（原文是飘流），不禁止脚步，所以耶和华不悦纳他们。现今要记念他们的罪孽，追讨他们的罪恶。'),
('CUV', '耶利米书', 24, 14, 11, '耶和华又对我说：不要为这百姓祈祷求好处。'),
('CUV', '耶利米书', 24, 14, 12, '他们禁食的时候，我不听他们的呼求；他们献燔祭和素祭，我也不悦纳；我却要用刀剑、饥荒、瘟疫灭绝他们。'),
('CUV', '耶利米书', 24, 14, 13, '我就说：唉！主耶和华啊，那些先知常对他们说：你们必不看见刀剑，也不遭遇饥荒；耶和华要在这地方赐你们长久的平安。'),
('CUV', '耶利米书', 24, 14, 14, '耶和华对我说：那些先知托我的名说假预言，我并没有打发他们，没有吩咐他们，也没有对他们说话；他们向你们预言的，乃是虚假的异象和占卜，并虚无的事，以及本心的诡诈。'),
('CUV', '耶利米书', 24, 14, 15, '所以耶和华如此说：论到托我名说预言的那些先知，我并没有打发他们；他们还说这地不能有刀剑饥荒，其实那些先知必被刀剑饥荒灭绝。'),
('CUV', '耶利米书', 24, 14, 16, '听他们说预言的百姓必因饥荒刀剑抛在耶路撒冷的街道上，无人葬埋。他们连妻子带儿女，都是如此。我必将他们的恶倒在他们身上（或译：我必使他们罪恶的报应临到他们身上）。'),
('CUV', '耶利米书', 24, 14, 17, '你要将这话对他们说：愿我眼泪汪汪，昼夜不息，因为我百姓（原文是民的处女）受了裂口破坏的大伤。'),
('CUV', '耶利米书', 24, 14, 18, '我若出往田间，就见有被刀杀的；我若进入城内，就见有因饥荒患病的；连先知带祭司在国中往来，也是毫无知识（或译：不知怎样才好）。'),
('CUV', '耶利米书', 24, 14, 19, '你全然弃掉犹大么？你心厌恶锡安么？为何击打我们，以致无法医治呢？我们指望平安，却得不著好处；指望痊愈，不料，受了惊惶。'),
('CUV', '耶利米书', 24, 14, 20, '耶和华啊，我们承认自己的罪恶，和我们列祖的罪孽，因我们得罪了你。'),
('CUV', '耶利米书', 24, 14, 21, '求你为你名的缘故，不厌恶我们，不辱没你荣耀的宝座。求你追念，不要背了与我们所立的约。'),
('CUV', '耶利米书', 24, 14, 22, '外邦人虚无的神中有能降雨的么？天能自降甘霖么？耶和华─我们的神啊，能如此的不是你么？所以，我们仍要等候你，因为这一切都是你所造的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 15, 1, '耶和华对我说：虽有摩西和撒母耳站在我面前代求，我的心也不顾惜这百姓。你将他们从我眼前赶出，叫他们去罢！'),
('CUV', '耶利米书', 24, 15, 2, '他们问你说：我们往哪里去呢？你便告诉他们，耶和华如此说：定为死亡的，必致死亡；定为刀杀的，必交刀杀；定为饥荒的，必遭饥荒；定为掳掠的，必被掳掠。'),
('CUV', '耶利米书', 24, 15, 3, '耶和华说：我命定四样害他们，就是刀剑杀戮、狗类撕裂、空中的飞鸟，和地上的野兽吞吃毁灭；'),
('CUV', '耶利米书', 24, 15, 4, '又必使他们在天下万国中抛来抛去，都因犹大王希西家的儿子玛拿西在耶路撒冷所行的事。'),
('CUV', '耶利米书', 24, 15, 5, '耶路撒冷啊，谁可怜你呢？谁为你悲伤呢？谁转身问你的安呢？'),
('CUV', '耶利米书', 24, 15, 6, '耶和华说：你弃绝了我，转身退后；因此我伸手攻击你，毁坏你。我后悔甚不耐烦。'),
('CUV', '耶利米书', 24, 15, 7, '我在境内各城门口（或译：我在这地边界的关口），用簸箕簸了我的百姓，使他们丧掉儿女。我毁灭他们，他们仍不转离所行的道。'),
('CUV', '耶利米书', 24, 15, 8, '他们的寡妇在我面前比海沙更多；我使灭命的午间来，攻击少年人的母亲，使痛苦惊吓忽然临到他身上。'),
('CUV', '耶利米书', 24, 15, 9, '生过七子的妇人力衰气绝；尚在白昼，日头忽落；他抱愧蒙羞。其余的人，我必在他们敌人跟前，交与刀剑。这是耶和华说的。'),
('CUV', '耶利米书', 24, 15, 10, '我的母亲哪，我有祸了！因你生我作为遍地相争相竞的人。我素来没有借贷与人，人也没有借贷与我，人人却都咒骂我。'),
('CUV', '耶利米书', 24, 15, 11, '耶和华说：我必要坚固你，使你得好处。灾祸苦难临到的时候，我必要使仇敌央求你。'),
('CUV', '耶利米书', 24, 15, 12, '（人岂能将铜与铁，就是北方的铁折断呢？）'),
('CUV', '耶利米书', 24, 15, 13, '我必因你在四境之内所犯的一切罪，把你的货物财宝当掠物，白白地交给仇敌。'),
('CUV', '耶利米书', 24, 15, 14, '我也必使仇敌带这掠物到你所不认识的地去，因我怒中起的火要将你们焚烧。'),
('CUV', '耶利米书', 24, 15, 15, '耶和华啊，你是知道的；求你记念我，眷顾我，向逼迫我的人为我报仇；不要向他们忍怒取我的命，要知道我为你的缘故受了凌辱。'),
('CUV', '耶利米书', 24, 15, 16, '耶和华─万军之神啊，我得著你的言语就当食物吃了；你的言语是我心中的欢喜快乐，因我是称为你名下的人。'),
('CUV', '耶利米书', 24, 15, 17, '我没有坐在宴乐人的会中，也没有欢乐；我因你的感动（原文是手）独自静坐，因你使我满心愤恨。'),
('CUV', '耶利米书', 24, 15, 18, '我的痛苦为何长久不止呢？我的伤痕为何无法医治、不能痊愈呢？难道你待我有诡诈，像流干的河道么？'),
('CUV', '耶利米书', 24, 15, 19, '耶和华如此说：你若归回，我就将你再带来，使你站在我面前；你若将宝贵的和下贱的分别出来，你就可以当作我的口。他们必归向你，你却不可归向他们。'),
('CUV', '耶利米书', 24, 15, 20, '我必使你向这百姓成为坚固的铜墙；他们必攻击你，却不能胜你；因我与你同在，要拯救你，搭救你。这是耶和华说的。'),
('CUV', '耶利米书', 24, 15, 21, '我必搭救你脱离恶人的手，救赎你脱离强暴人的手。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 16, 1, '耶和华的话又临到我说：'),
('CUV', '耶利米书', 24, 16, 2, '你在这地方不可娶妻，生儿养女。'),
('CUV', '耶利米书', 24, 16, 3, '因为论到在这地方所生的儿女，又论到在这国中生养他们的父母，耶和华如此说：'),
('CUV', '耶利米书', 24, 16, 4, '他们必死得甚苦，无人哀哭，必不得葬埋，必在地上像粪土，必被刀剑和饥荒灭绝；他们的尸首必给空中的飞鸟和地上的野兽作食物。'),
('CUV', '耶利米书', 24, 16, 5, '耶和华如此说：不要进入丧家，不要去哀哭，也不要为他们悲伤，因我已将我的平安、慈爱、怜悯从这百姓夺去了。这是耶和华说的。'),
('CUV', '耶利米书', 24, 16, 6, '连大带小，都必在这地死亡，不得葬埋。人必不为他们哀哭，不用刀划身，也不使头光秃。'),
('CUV', '耶利米书', 24, 16, 7, '他们有丧事，人必不为他们擘饼，因死人安慰他们；他们丧父丧母，人也不给他们一杯酒安慰他们。'),
('CUV', '耶利米书', 24, 16, 8, '你不可进入宴乐的家，与他们同坐吃喝。'),
('CUV', '耶利米书', 24, 16, 9, '因为万军之耶和华─以色列的神如此说：你们还活著的日子在你们眼前，我必使欢喜和快乐的声音，新郎和新妇的声音，从这地方止息了。'),
('CUV', '耶利米书', 24, 16, 10, '你将这一切的话指示这百姓。他们问你说：耶和华为甚么说，要降这大灾祸攻击我们呢？我们有甚么罪孽呢？我们向耶和华─我们的神犯了甚么罪呢？'),
('CUV', '耶利米书', 24, 16, 11, '你就对他们说：耶和华说：因为你们列祖离弃我，随从别神，事奉敬拜，不遵守我的律法，'),
('CUV', '耶利米书', 24, 16, 12, '而且你们行恶比你们列祖更甚；因为各人随从自己顽梗的恶心行事，甚至不听从我，'),
('CUV', '耶利米书', 24, 16, 13, '所以我必将你们从这地赶出，直赶到你们和你们列祖素不认识的地。你们在那里必昼夜事奉别神，因为我必不向你们施恩。'),
('CUV', '耶利米书', 24, 16, 14, '耶和华说：日子将到，人必不再指著那领以色列人从埃及地上来之永生的耶和华起誓，耶和华说：日子将到，人必不再指著那领以色列人从埃及地上来之永生的耶和华起誓，'),
('CUV', '耶利米书', 24, 16, 15, '却要指著那领以色列人从北方之地，并赶他们到的各国上来之永生的耶和华起誓，并且我要领他们再入我从前赐给他们列祖之地。'),
('CUV', '耶利米书', 24, 16, 16, '耶和华说：我要召许多打鱼的把以色列人打上来，然后我要召许多打猎的，从各山上、各冈上、各石穴中猎取他们。'),
('CUV', '耶利米书', 24, 16, 17, '因我的眼目察看他们的一切行为；他们不能在我面前遮掩，他们的罪孽也不能在我眼前隐藏。'),
('CUV', '耶利米书', 24, 16, 18, '我先要加倍报应他们的罪孽和罪恶；因为他们用可憎之尸玷污我的地土，又用可厌之物充满我的产业。'),
('CUV', '耶利米书', 24, 16, 19, '耶和华啊，你是我的力量，是我的保障；在苦难之日是我的避难所。列国人必从地极来到你这里，说：我们列祖所承受的，不过是虚假，是虚空无益之物。'),
('CUV', '耶利米书', 24, 16, 20, '人岂可为自己制造神呢？其实这不是神。'),
('CUV', '耶利米书', 24, 16, 21, '耶和华说：我要使他们知道，就是这一次使他们知道我的手和我的能力。他们就知道我的名是耶和华了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 17, 1, '犹大的罪是用铁笔、用金钢钻记录的，铭刻在他们的心版上和坛角上。'),
('CUV', '耶利米书', 24, 17, 2, '他们的儿女记念他们高冈上、青翠树旁的坛和木偶。'),
('CUV', '耶利米书', 24, 17, 3, '我田野的山哪，我必因你在四境之内所犯的罪，把你的货物、财宝，并邱坛当掠物交给仇敌；'),
('CUV', '耶利米书', 24, 17, 4, '并且你因自己的罪必失去我所赐给你的产业。我也必使你在你所不认识的地上服事你的仇敌；因为你使我怒中起火，直烧到永远。'),
('CUV', '耶利米书', 24, 17, 5, '耶和华如此说：倚靠人血肉的膀臂，心中离弃耶和华的，那人有祸了！'),
('CUV', '耶利米书', 24, 17, 6, '因他必像沙漠的杜松，不见福乐来到，却要住旷野干旱之处，无人居住的碱地。'),
('CUV', '耶利米书', 24, 17, 7, '倚靠耶和华、以耶和华为可靠的，那人有福了！'),
('CUV', '耶利米书', 24, 17, 8, '他必像树栽于水旁，在河边扎根，炎热来到，并不惧怕，叶子仍必青翠，在干旱之年毫无挂虑，而且结果不止。'),
('CUV', '耶利米书', 24, 17, 9, '人心比万物都诡诈，坏到极处，谁能识透呢？'),
('CUV', '耶利米书', 24, 17, 10, '我─耶和华是鉴察人心、试验人肺腑的，要照各人所行的和他做事的结果报应他。'),
('CUV', '耶利米书', 24, 17, 11, '那不按正道得财的，好像鹧鸪菢不是自己下的蛋；到了中年，那财都必离开他，他终久成为愚顽人。'),
('CUV', '耶利米书', 24, 17, 12, '我们的圣所是荣耀的宝座，从太初安置在高处。'),
('CUV', '耶利米书', 24, 17, 13, '耶和华─以色列的盼望啊，凡离弃你的必致蒙羞。耶和华说：离开我的，他们的名字必写在土里，因为他们离弃我这活水的泉源。'),
('CUV', '耶利米书', 24, 17, 14, '耶和华啊，求你医治我，我便痊愈，拯救我，我便得救；因你是我所赞美的。'),
('CUV', '耶利米书', 24, 17, 15, '他们对我说：耶和华的话在哪里呢？叫这话应验罢！'),
('CUV', '耶利米书', 24, 17, 16, '至于我，那跟从你作牧人的职分，我并没有急忙离弃，也没有想那灾殃的日子；这是你知道的。我口中所出的言语都在你面前。'),
('CUV', '耶利米书', 24, 17, 17, '不要使我因你惊恐；当灾祸的日子，你是我的避难所。'),
('CUV', '耶利米书', 24, 17, 18, '愿那些逼迫我的蒙羞，却不要使我蒙羞；使他们惊惶，却不要使我惊惶；使灾祸的日子临到他们，以加倍的毁坏毁坏他们。'),
('CUV', '耶利米书', 24, 17, 19, '耶和华对我如此说：你去站在平民的门口，就是犹大君王出入的门，又站在耶路撒冷的各门口，'),
('CUV', '耶利米书', 24, 17, 20, '对他们说：你们这犹大君王和犹大众人，并耶路撒冷的一切居民，凡从这些门进入的都当听耶和华的话。'),
('CUV', '耶利米书', 24, 17, 21, '耶和华如此说：你们要谨慎，不要在安息日担甚么担子进入耶路撒冷的各门；'),
('CUV', '耶利米书', 24, 17, 22, '也不要在安息日从家中担出担子去。无论何工都不可做，只要以安息日为圣日，正如我所吩咐你们列祖的。'),
('CUV', '耶利米书', 24, 17, 23, '他们却不听从，不侧耳而听，竟硬著颈项不听，不受教训。'),
('CUV', '耶利米书', 24, 17, 24, '耶和华说：你们若留意听从我，在安息日不担甚么担子进入这城的各门，只以安息日为圣日，在那日无论何工都不做；'),
('CUV', '耶利米书', 24, 17, 25, '那时就有坐大卫宝座的君王和首领，他们与犹大人，并耶路撒冷的居民，或坐车，或骑马，进入这城的各门，而且这城必存到永远。'),
('CUV', '耶利米书', 24, 17, 26, '也必有人从犹大城邑和耶路撒冷四围的各处，从便雅悯地、高原、山地，并南地而来，都带燔祭、平安祭、素祭，和乳香，并感谢祭，到耶和华的殿去。'),
('CUV', '耶利米书', 24, 17, 27, '你们若不听从我，不以安息日为圣日，仍在安息日担担子，进入耶路撒冷的各门，我必在各门中点火；这火也必烧毁耶路撒冷的宫殿，不能熄灭。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 18, 1, '耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 18, 2, '你起来，下到窑匠的家里去，我在那著要使你听我的话。'),
('CUV', '耶利米书', 24, 18, 3, '我就下到窑匠的家里去，正遇他转轮做器皿。'),
('CUV', '耶利米书', 24, 18, 4, '窑匠用泥做的器皿，在他手中做坏了，他又用这泥另做别的器皿；窑匠看怎样好，就怎样做。'),
('CUV', '耶利米书', 24, 18, 5, '耶和华的话就临到我说：'),
('CUV', '耶利米书', 24, 18, 6, '耶和华说：以色列家啊，我待你们，岂不能照这窑匠弄泥么？以色列家啊，泥在窑匠的手中怎样，你们在我的手中也怎样。'),
('CUV', '耶利米书', 24, 18, 7, '我何时论到一邦或一国说，要拔出、拆毁、毁坏；'),
('CUV', '耶利米书', 24, 18, 8, '我所说的那一邦，若是转意离开他们的恶，我就必后悔，不将我想要施行的灾祸降与他们。'),
('CUV', '耶利米书', 24, 18, 9, '我何时论到一邦或一国说，要建立、栽植；'),
('CUV', '耶利米书', 24, 18, 10, '他们若行我眼中看为恶的事，不听从我的话，我就必后悔，不将我所说的福气赐给他们。'),
('CUV', '耶利米书', 24, 18, 11, '现在你要对犹大人和耶路撒冷的居民说：耶和华如此说：我造出灾祸攻击你们，定意刑罚你们。你们各人当回头离开所行的恶道，改正你们的行动作为。'),
('CUV', '耶利米书', 24, 18, 12, '他们却说：这是枉然。我们要照自己的计谋去行。各人随自己顽梗的恶心做事。'),
('CUV', '耶利米书', 24, 18, 13, '所以，耶和华如此说：你们且往各国访问，有谁听见这样的事？以色列民（原文是处女）行了一件极可憎恶的事。'),
('CUV', '耶利米书', 24, 18, 14, '利巴嫩的雪从田野的磐石上岂能断绝呢？从远处流下的凉水岂能干涸呢？'),
('CUV', '耶利米书', 24, 18, 15, '我的百姓竟忘记我，向假神烧香，使他们在所行的路上，在古道上绊跌，使他们行没有修筑的斜路，'),
('CUV', '耶利米书', 24, 18, 16, '以致他们的地令人惊骇，常常嗤笑；凡经过这地的必惊骇摇头。'),
('CUV', '耶利米书', 24, 18, 17, '我必在仇敌面前分散他们，好像用东风吹散一样。遭难的日子，我必以背向他们，不以面向他们。'),
('CUV', '耶利米书', 24, 18, 18, '他们就说：来罢！我们可以设计谋害耶利米；因为我们有祭司讲律法，智慧人设谋略，先知说预言，都不能断绝。来罢！我们可以用舌头击打他，不要理会他的一切话。'),
('CUV', '耶利米书', 24, 18, 19, '耶和华啊，求你理会我，且听那些与我争竞之人的话。'),
('CUV', '耶利米书', 24, 18, 20, '岂可以恶报善呢？他们竟挖坑要害我的性命！求你记念我怎样站在你面前为他们代求，要使你的忿怒向他们转消。'),
('CUV', '耶利米书', 24, 18, 21, '故此，愿你将他们的儿女交与饥荒和刀剑；愿他们的妻无子，且作寡妇；又愿他们的男人被死亡所灭，他们的少年人在阵上被刀击杀。'),
('CUV', '耶利米书', 24, 18, 22, '你使敌军忽然临到他们的时候，愿人听见哀声从他们的屋内发出；因他们挖坑要捉拿我，暗设网罗要绊我的脚。'),
('CUV', '耶利米书', 24, 18, 23, '耶和华啊，他们要杀我的那一切计谋，你都知道。不要赦免他们的罪孽，也不要从你面前涂抹他们的罪恶，要叫他们在你面前跌倒；愿你发怒的时候罚办他们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 19, 1, '耶和华如此说：你去买窑匠的瓦瓶，又带百姓中的长老和祭司中的长老，'),
('CUV', '耶利米书', 24, 19, 2, '出去到欣嫩子谷、哈珥西（就是瓦片的意思）的门口那著，宣告我所吩咐你的话，'),
('CUV', '耶利米书', 24, 19, 3, '说：犹大君王和耶路撒冷的居民哪，当听耶和华的话。万军之耶和华─以色列的神如此说：我必使灾祸临到这地方，凡听见的人都必耳鸣；'),
('CUV', '耶利米书', 24, 19, 4, '因为他们和他们列祖，并犹大君王离弃我，将这地方看为平常，在这里向素不认识的别神烧香，又使这地方满了无辜人的血，'),
('CUV', '耶利米书', 24, 19, 5, '又建筑巴力的邱坛，好在火中焚烧自己的儿子，作为燔祭献给巴力。这不是我所吩咐的，不是我所提说的，也不是我心所起的意。'),
('CUV', '耶利米书', 24, 19, 6, '耶和华说：因此，日子将到，这地方不再称为陀斐特和欣嫩子谷，反倒称为杀戮谷。'),
('CUV', '耶利米书', 24, 19, 7, '我必在这地方使犹大和耶路撒冷的计谋落空，也必使他们在仇敌面前倒于刀下，并寻索其命的人手下。他们的尸首，我必给空中的飞鸟和地上的野兽作食物。'),
('CUV', '耶利米书', 24, 19, 8, '我必使这城令人惊骇嗤笑；凡经过的人，必因这城所遭的灾惊骇嗤笑。'),
('CUV', '耶利米书', 24, 19, 9, '我必使他们在围困窘迫之中，就是仇敌和寻索其命的人窘迫他们的时候，各人吃自己儿女的肉和朋友的肉。'),
('CUV', '耶利米书', 24, 19, 10, '你要在同去的人眼前打碎那瓶，'),
('CUV', '耶利米书', 24, 19, 11, '对他们说：万军之耶和华如此说：我要照样打碎这民和这城，正如人打碎窑匠的瓦器，以致不能再囫囵。并且人要在陀斐特葬埋尸首，甚至无处可葬。'),
('CUV', '耶利米书', 24, 19, 12, '耶和华说：我必向这地方和其中的居民如此行，使这城与陀斐特一样。'),
('CUV', '耶利米书', 24, 19, 13, '耶路撒冷的房屋和犹大君王的宫殿是已经被玷污的，就是他们在其上向天上的万象烧香、向别神浇奠祭的宫殿房屋，都必与陀斐特一样。'),
('CUV', '耶利米书', 24, 19, 14, '耶利米从陀斐特─就是耶和华差他去说预言的地方─回来，站在耶和华殿的院中，对众人说：'),
('CUV', '耶利米书', 24, 19, 15, '万军之耶和华─以色列的神如此说：我必使我所说的一切灾祸临到这城和属城的一切城邑，因为他们硬著颈项不听我的话。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 20, 1, '祭司音麦的儿子巴施户珥作耶和华殿的总管，听见耶利米预言这些事，'),
('CUV', '耶利米书', 24, 20, 2, '他就打先知耶利米，用耶和华殿著便雅悯高门内的枷，将他枷在那里。'),
('CUV', '耶利米书', 24, 20, 3, '次日，巴施户珥将耶利米开枷释放。于是耶利米对他说：耶和华不是叫你的名为巴施户珥，乃是叫你玛歌珥•米撒毕（就是四面惊吓的意思），'),
('CUV', '耶利米书', 24, 20, 4, '因耶和华如此说：我必使你自觉惊吓，你也必使众朋友惊吓；他们必倒在仇敌的刀下，你也必亲眼看见；我必将犹大人全交在巴比伦王的手中，他要将他们掳到巴比伦去，也要用刀将他们杀戮。'),
('CUV', '耶利米书', 24, 20, 5, '并且我要将这城中的一切货财和劳碌得来的，并一切珍宝，以及犹大君王所有的宝物，都交在他们仇敌的手中；仇敌要当作掠物带到巴比伦去。'),
('CUV', '耶利米书', 24, 20, 6, '你这巴施户珥和一切住在你家中的人都必被掳去；你和你的众朋友，就是你向他们说假预言的，都必到巴比伦去，要死在那著，葬在那著。'),
('CUV', '耶利米书', 24, 20, 7, '耶和华啊，你曾劝导我，我也听了你的劝导。你比我有力量，且胜了我。我终日成为笑话，人人都戏弄我。'),
('CUV', '耶利米书', 24, 20, 8, '我每逢讲论的时候，就发出哀声，我喊叫说：有强暴和毁灭！因为耶和华的话终日成了我的凌辱、讥刺。'),
('CUV', '耶利米书', 24, 20, 9, '我若说：我不再提耶和华，也不再奉他的名讲论，我便心里觉得似乎有烧著的火闭塞在我骨中，我就含忍不住，不能自禁。'),
('CUV', '耶利米书', 24, 20, 10, '我听见了许多人的谗谤，四围都是惊吓；就是我知己的朋友也都窥探我，愿我跌倒，说：告他罢，我们也要告他！或者他被引诱，我们就能胜他，在他身上报仇。'),
('CUV', '耶利米书', 24, 20, 11, '然而，耶和华与我同在，好像甚可怕的勇士。因此，逼迫我的必都绊跌，不能得胜；他们必大大蒙羞，就是受永不忘记的羞辱，因为他们行事没有智慧。'),
('CUV', '耶利米书', 24, 20, 12, '试验义人、察看人肺腑心肠的万军之耶和华啊，求你容我见你在他们身上报仇，因我将我的案件向你禀明了。'),
('CUV', '耶利米书', 24, 20, 13, '你们要向耶和华唱歌；赞美耶和华！因他救了穷人的性命脱离恶人的手。'),
('CUV', '耶利米书', 24, 20, 14, '愿我生的那日受咒诅；愿我母亲产我的那日不蒙福！'),
('CUV', '耶利米书', 24, 20, 15, '给我父亲报信说你得了儿子，使我父亲甚欢喜的，愿那人受咒诅。'),
('CUV', '耶利米书', 24, 20, 16, '愿那人像耶和华所倾覆而不后悔的城邑；愿他早晨听见哀声，晌午听见呐喊；'),
('CUV', '耶利米书', 24, 20, 17, '因他在我未出胎的时候不杀我，使我母亲成了我的坟墓，胎就时常重大。'),
('CUV', '耶利米书', 24, 20, 18, '我为何出胎见劳碌愁苦，使我的年日因羞愧消灭呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 21, 1, '耶和华的话临到耶利米。那时，西底家王打发玛基雅的儿子巴施户珥和玛西雅的儿子祭司西番雅去见耶利米，说：'),
('CUV', '耶利米书', 24, 21, 2, '请你为我们求问耶和华；因为巴比伦王尼布甲尼撒来攻击我们，或者耶和华照他一切奇妙的作为待我们，使巴比伦王离开我们上去。'),
('CUV', '耶利米书', 24, 21, 3, '耶利米对他们说：你们当对西底家这样说：'),
('CUV', '耶利米书', 24, 21, 4, '耶和华─以色列的神如此说：我要使你们手中的兵器，就是你们在城外与巴比伦王和围困你们的迦勒底人打仗的兵器翻转过来，又要使这些都聚集在这城中。'),
('CUV', '耶利米书', 24, 21, 5, '并且我要在怒气、忿怒，和大恼恨中，用伸出来的手，并大能的膀臂，亲自攻击你们；'),
('CUV', '耶利米书', 24, 21, 6, '又要击打这城的居民，连人带牲畜都必遭遇大瘟疫死亡。'),
('CUV', '耶利米书', 24, 21, 7, '以后我要将犹大王西底家和他的臣仆百姓，就是在城内，从瘟疫、刀剑、饥荒中剩下的人，都交在巴比伦王尼布甲尼撒的手中和他们仇敌，并寻索其命的人手中。巴比伦王必用刀击杀他们，不顾惜，不可怜，不怜悯。这是耶和华说的。'),
('CUV', '耶利米书', 24, 21, 8, '你要对这百姓说：耶和华如此说：看哪，我将生命的路和死亡的路摆在你们面前。'),
('CUV', '耶利米书', 24, 21, 9, '住在这城著的必遭刀剑、饥荒、瘟疫而死；但出去归降围困你们迦勒底人的必得存活，要以自己的命为掠物。'),
('CUV', '耶利米书', 24, 21, 10, '耶和华说：我向这城变脸，降祸不降福；这城必交在巴比伦王的手中，他必用火焚烧。'),
('CUV', '耶利米书', 24, 21, 11, '至于犹大王的家，你们当听耶和华的话。'),
('CUV', '耶利米书', 24, 21, 12, '大卫家啊，耶和华如此说：你们每早晨要施行公平，拯救被抢夺的脱离欺压人的手，恐怕我的忿怒因你们的恶行发作，如火著起，甚至无人能以熄灭。'),
('CUV', '耶利米书', 24, 21, 13, '耶和华说：住山谷和平原磐石上的居民，你们说：谁能下来攻击我们？谁能进入我们的住处呢？看哪，我与你们为敌。'),
('CUV', '耶利米书', 24, 21, 14, '耶和华又说：我必按你们做事的结果刑罚你们；我也必使火在耶路撒冷的林中著起，将他四围所有的尽行烧灭。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 22, 1, '耶和华如此说：你下到犹大王的宫中，在那著说这话，'),
('CUV', '耶利米书', 24, 22, 2, '说：坐大卫宝座的犹大王啊，你和你的臣仆，并进入城门的百姓，都当听耶和华的话。'),
('CUV', '耶利米书', 24, 22, 3, '耶和华如此说：你们要施行公平和公义，拯救被抢夺的脱离欺压人的手，不可亏负寄居的和孤儿寡妇，不可以强暴待他们，在这地方也不可流无辜人的血。'),
('CUV', '耶利米书', 24, 22, 4, '你们若认真行这事，就必有坐大卫宝座的君王和他的臣仆百姓，或坐车或骑马，从这城的各门进入。'),
('CUV', '耶利米书', 24, 22, 5, '你们若不听这些话，耶和华说：我指著自己起誓，这城必变为荒场。'),
('CUV', '耶利米书', 24, 22, 6, '耶和华论到犹大王的家如此说：我看你如基列，如利巴嫩顶；然而，我必使你变为旷野，为无人居住的城邑。'),
('CUV', '耶利米书', 24, 22, 7, '我要预备行毁灭的人，各拿器械攻击你；他们要砍下你佳美的香柏树，扔在火中。'),
('CUV', '耶利米书', 24, 22, 8, '许多国的民要经过这城，各人对邻舍说：耶和华为何向这大城如此行呢？'),
('CUV', '耶利米书', 24, 22, 9, '他们必回答说：是因离弃了耶和华─他们神的约，事奉敬拜别神。'),
('CUV', '耶利米书', 24, 22, 10, '不要为死人哭号；不要为他悲伤，却要为离家出外的人大大哭号；因为他不得再回来，也不得再见他的本国。'),
('CUV', '耶利米书', 24, 22, 11, '因为耶和华论到从这地方出去的犹大王约西亚的儿子沙龙（在王下23：30名约哈斯），就是接续他父亲约西亚作王的，这样说：他必不得再回到这里来，'),
('CUV', '耶利米书', 24, 22, 12, '却要死在被掳去的地方，必不得再见这地。'),
('CUV', '耶利米书', 24, 22, 13, '那行不义盖房、行不公造楼、白白使用人的手工不给工价的有祸了！'),
('CUV', '耶利米书', 24, 22, 14, '他说：我要为自己盖广大的房、宽敞的楼，为自己开窗户。这楼房的护墙板是香柏木的，楼房是丹色油漆的。'),
('CUV', '耶利米书', 24, 22, 15, '难道你作王是在乎造香柏木楼房争胜么？你的父亲岂不是也吃也喝、也施行公平和公义么？那时他得了福乐。'),
('CUV', '耶利米书', 24, 22, 16, '他为困苦和穷乏人伸冤，那时就得了福乐。认识我不在乎此么？这是耶和华说的。'),
('CUV', '耶利米书', 24, 22, 17, '惟有你的眼和你的心专顾贪婪，流无辜人的血，行欺压和强暴。'),
('CUV', '耶利米书', 24, 22, 18, '所以，耶和华论到犹大王约西亚的儿子约雅敬如此说：人必不为他举哀说：哀哉！我的哥哥；或说：哀哉！我的姊姊；也不为他举哀说：哀哉！我的主；或说：哀哉！我主的荣华。'),
('CUV', '耶利米书', 24, 22, 19, '他被埋葬，好像埋驴一样，要拉出去扔在耶路撒冷的城门之外。'),
('CUV', '耶利米书', 24, 22, 20, '你要上利巴嫩哀号，在巴珊扬声，从亚巴琳哀号，因为你所亲爱的都毁灭了。'),
('CUV', '耶利米书', 24, 22, 21, '你兴盛的时候，我对你说话；你却说：我不听。你自幼年以来总是这样，不听从我的话。'),
('CUV', '耶利米书', 24, 22, 22, '你的牧人要被风吞吃，你所亲爱的必被掳去；那时你必因你一切的恶抱愧蒙羞。'),
('CUV', '耶利米书', 24, 22, 23, '你这住利巴嫩、在香柏树上搭窝的，有痛苦临到你，好像疼痛临到产难的妇人，那时你何等可怜！'),
('CUV', '耶利米书', 24, 22, 24, '耶和华说：犹大王约雅敬的儿子哥尼雅（又名耶哥尼雅；下同），虽是我右手上带印的戒指，我凭我的永生起誓，也必将你从其上摘下来，'),
('CUV', '耶利米书', 24, 22, 25, '并且我必将你交给寻索你命的人和你所惧怕的人手中，就是巴比伦王尼布甲尼撒和迦勒底人的手中。'),
('CUV', '耶利米书', 24, 22, 26, '我也必将你和生你的母亲赶到别国，并不是你们生的地方；你们必死在那里，'),
('CUV', '耶利米书', 24, 22, 27, '但心中甚想归回之地，必不得归回。'),
('CUV', '耶利米书', 24, 22, 28, '哥尼雅这人是被轻看、破坏的器皿么？是无人喜爱的器皿么？他和他的后裔为何被赶到不认识之地呢？'),
('CUV', '耶利米书', 24, 22, 29, '地啊，地啊，地啊，当听耶和华的话！'),
('CUV', '耶利米书', 24, 22, 30, '耶和华如此说：要写明这人算为无子，是平生不得亨通的；因为他后裔中再无一人得亨通，能坐在大卫的宝座上治理犹大。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 23, 1, '耶和华说：那些残害、赶散我草场之羊的牧人有祸了！'),
('CUV', '耶利米书', 24, 23, 2, '耶和华─以色列的神斥责那些牧养他百姓的牧人，如此说：你们赶散我的羊群，并没有看顾他们；我必讨你们这行恶的罪。这是耶和华说的。'),
('CUV', '耶利米书', 24, 23, 3, '我要将我羊群中所余剩的，从我赶他们到的各国内招聚出来，领他们归回本圈；他们也必生养众多。'),
('CUV', '耶利米书', 24, 23, 4, '我必设立照管他们的牧人，牧养他们。他们不再惧怕，不再惊惶，也不缺少一个；这是耶和华说的。'),
('CUV', '耶利米书', 24, 23, 5, '耶和华说：日子将到，我要给大卫兴起一个公义的苗裔；他必掌王权，行事有智慧，在地上施行公平和公义。'),
('CUV', '耶利米书', 24, 23, 6, '在他的日子，犹大必得救，以色列也安然居住。他的名必称为耶和华─我们的义。'),
('CUV', '耶利米书', 24, 23, 7, '耶和华说：日子将到，人必不再指著那领以色列人从埃及地上来永生的耶和华起誓，'),
('CUV', '耶利米书', 24, 23, 8, '却要指著那领以色列家的后裔从北方和赶他们到的各国中上来、永生的耶和华起誓。他们必住在本地。'),
('CUV', '耶利米书', 24, 23, 9, '论到那些先知，我心在我里面忧伤，我骨头都发颤；因耶和华和他的圣言，我像醉酒的人，像被酒所胜的人。'),
('CUV', '耶利米书', 24, 23, 10, '地满了行淫的人！因妄自赌咒，地就悲哀；旷野的草场都枯干了。他们所行的道乃是恶的；他们的勇力使得不正。'),
('CUV', '耶利米书', 24, 23, 11, '连先知带祭司都是亵渎的，就是在我殿中我也看见他们的恶。这是耶和华说的。'),
('CUV', '耶利米书', 24, 23, 12, '因此，他们的道路必像黑暗中的滑地，他们必被追赶，在这路中仆倒；因为当追讨之年，我必使灾祸临到他们。这是耶和华说的。'),
('CUV', '耶利米书', 24, 23, 13, '我在撒玛利亚的先知中曾见愚妄；他们藉巴力说预言，使我的百姓以色列走错了路。'),
('CUV', '耶利米书', 24, 23, 14, '我在耶路撒冷的先知中曾见可憎恶的事；他们行奸淫，做事虚妄，又坚固恶人的手，甚至无人回头离开他的恶。他们在我面前都像所多玛；耶路撒冷的居民都像蛾摩拉。'),
('CUV', '耶利米书', 24, 23, 15, '所以万军之耶和华论到先知如此说：我必将茵𫈟给他们吃，又将苦胆水给他们喝；因为亵渎的事出于耶路撒冷的先知，流行遍地。'),
('CUV', '耶利米书', 24, 23, 16, '万军之耶和华如此说：这些先知向你们说预言，你们不要听他们的话。他们以虚空教训你们，所说的异象是出于自己的心，不是出于耶和华的口。'),
('CUV', '耶利米书', 24, 23, 17, '他们常对藐视我的人说：『耶和华说：你们必享平安』；又对一切按自己顽梗之心而行的人说：『必没有灾祸临到你们。』」'),
('CUV', '耶利米书', 24, 23, 18, '有谁站在耶和华的会中得以听见并会悟他的话呢？有谁留心听他的话呢？'),
('CUV', '耶利米书', 24, 23, 19, '看哪！耶和华的忿怒好像暴风，已经发出；是暴烈的旋风，必转到恶人的头上。'),
('CUV', '耶利米书', 24, 23, 20, '耶和华的怒气必不转消，直到他心中所拟定的成就了。末后的日子你们要全然明白。'),
('CUV', '耶利米书', 24, 23, 21, '我没有打发那些先知，他们竟自奔跑；我没有对他们说话，他们竟自预言。'),
('CUV', '耶利米书', 24, 23, 22, '他们若是站在我的会中，就必使我的百姓听我的话，又使他们回头离开恶道和他们所行的恶。'),
('CUV', '耶利米书', 24, 23, 23, '耶和华说：我岂为近处的神呢？不也为远处的神么？'),
('CUV', '耶利米书', 24, 23, 24, '耶和华说：人岂能在隐密处藏身，使我看不见他呢？耶和华说：我岂不充满天地么？'),
('CUV', '耶利米书', 24, 23, 25, '我已听见那些先知所说的，就是托我名说的假预言，他们说：我做了梦！我做了梦！'),
('CUV', '耶利米书', 24, 23, 26, '说假预言的先知，就是预言本心诡诈的先知，他们这样存心要到几时呢？'),
('CUV', '耶利米书', 24, 23, 27, '他们各人将所做的梦对邻舍述说，想要使我的百姓忘记我的名，正如他们列祖因巴力忘记我的名一样。'),
('CUV', '耶利米书', 24, 23, 28, '得梦的先知可以述说那梦；得我话的人可以诚实讲说我的话。糠秕怎能与麦子比较呢？这是耶和华说的。'),
('CUV', '耶利米书', 24, 23, 29, '耶和华说：我的话岂不像火，又像能打碎磐石的大锤么？'),
('CUV', '耶利米书', 24, 23, 30, '耶和华说：那些先知各从邻舍偷窃我的言语，因此我必与他们反对。'),
('CUV', '耶利米书', 24, 23, 31, '耶和华说：那些先知用舌头，说是耶和华说的；我必与他们反对。'),
('CUV', '耶利米书', 24, 23, 32, '耶和华说：那些以幻梦为预言，又述说这梦，以谎言和矜夸使我百姓走错了路的，我必与他们反对。我没有打发他们，也没有吩咐他们。他们与这百姓毫无益处。这是耶和华说的。'),
('CUV', '耶利米书', 24, 23, 33, '无论是百姓，是先知，是祭司，问你说：耶和华有甚么默示呢？你就对他们说：甚么默示啊？耶和华说：我要撇弃你们。'),
('CUV', '耶利米书', 24, 23, 34, '无论是先知，是祭司，是百姓，说耶和华的默示，我必刑罚那人和他的家。'),
('CUV', '耶利米书', 24, 23, 35, '你们各人要对邻舍，各人要对弟兄如此说：耶和华回答甚么？耶和华说了甚么呢？'),
('CUV', '耶利米书', 24, 23, 36, '耶和华的默示你们不可再提，各人所说的话必作自己的重担（重担和默示原文同），因为你们谬用永生神、万军之耶和华─我们神的言语。'),
('CUV', '耶利米书', 24, 23, 37, '你们要对先知如此说：耶和华回答你甚么？耶和华说了甚么呢？'),
('CUV', '耶利米书', 24, 23, 38, '你们若说耶和华的默示，耶和华就如此说：因你们说耶和华的默示这句话，我也打发人到你们那里去，告诉你们不可说耶和华的默示。'),
('CUV', '耶利米书', 24, 23, 39, '所以我必全然忘记你们，将你们和我所赐给你们并你们列祖的城撇弃了；'),
('CUV', '耶利米书', 24, 23, 40, '又必使永远的凌辱和长久的羞耻临到你们，是不能忘记的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 24, 1, '巴比伦王尼布甲尼撒将犹大王约雅敬的儿子耶哥尼雅和犹大的首领，并工匠、铁匠从耶路撒冷掳去，带到巴比伦。这事以后，耶和华指给我看，有两筐无花果放在耶和华的殿前。'),
('CUV', '耶利米书', 24, 24, 2, '一筐是极好的无花果，好像是初熟的；一筐是极坏的无花果，坏得不可吃。'),
('CUV', '耶利米书', 24, 24, 3, '于是耶和华问我说：耶利米你看见甚么？我说：我看见无花果，好的极好，坏的极坏，坏得不可吃。'),
('CUV', '耶利米书', 24, 24, 4, '耶和华的话临到我说：'),
('CUV', '耶利米书', 24, 24, 5, '耶和华─以色列的神如此说：被掳去的犹大人，就是我打发离开这地到迦勒底人之地去的，我必看顾他们如这好无花果，使他们得好处。'),
('CUV', '耶利米书', 24, 24, 6, '我要眷顾他们，使他们得好处，领他们归回这地。我也要建立他们，必不拆毁；栽植他们，并不拔出。'),
('CUV', '耶利米书', 24, 24, 7, '我要赐他们认识我的心，知道我是耶和华。他们要作我的子民，我要作他们的神，因为他们要一心归向我。'),
('CUV', '耶利米书', 24, 24, 8, '耶和华如此说：我必将犹大王西底家和他的首领，以及剩在这地耶路撒冷的余民，并住在埃及地的犹大人都交出来，好像那极坏、坏得不可吃的无花果。'),
('CUV', '耶利米书', 24, 24, 9, '我必使他们交出来，在天下万国中抛来抛去，遭遇灾祸；在我赶逐他们到的各处成为凌辱、笑谈、讥刺、咒诅。'),
('CUV', '耶利米书', 24, 24, 10, '我必使刀剑、饥荒、瘟疫临到他们，直到他们从我所赐给他们和他们列祖之地灭绝。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 25, 1, '犹大王约西亚的儿子约雅敬第四年，就是巴比伦王尼布甲尼撒的元年，耶和华论犹大众民的话临到耶利米。'),
('CUV', '耶利米书', 24, 25, 2, '先知耶利米就将这话对犹大众人和耶路撒冷的一切居民说：'),
('CUV', '耶利米书', 24, 25, 3, '从犹大王亚们的儿子约西亚十三年直到今日，这二十三年之内，常有耶和华的话临到我；我也对你们传说，就是从早起来传说，只是你们没有听从。'),
('CUV', '耶利米书', 24, 25, 4, '耶和华也从早起来，差遣他的仆人众先知到你们这里来（只是你们没有听从，也没有侧耳而听），'),
('CUV', '耶利米书', 24, 25, 5, '说：你们各人当回头，离开恶道和所作的恶，便可居住耶和华古时所赐给你们和你们列祖之地，直到永远。'),
('CUV', '耶利米书', 24, 25, 6, '不可随从别神事奉敬拜，以你们手所作的惹我发怒；这样，我就不加害与你们。'),
('CUV', '耶利米书', 24, 25, 7, '然而你们没有听从我，竟以手所做的惹我发怒，陷害自己。这是耶和华说的。'),
('CUV', '耶利米书', 24, 25, 8, '所以万军之耶和华如此说：因为你们没有听从我的话，'),
('CUV', '耶利米书', 24, 25, 9, '我必召北方的众族和我仆人巴比伦王尼布甲尼撒来攻击这地和这地的居民，并四围一切的国民。我要将他们尽行灭绝，以致他们令人惊骇、嗤笑，并且永久荒凉。这是耶和华说的。'),
('CUV', '耶利米书', 24, 25, 10, '我又要使欢喜和快乐的声音，新郎和新妇的声音，推磨的声音和灯的亮光，从他们中间止息。'),
('CUV', '耶利米书', 24, 25, 11, '这全地必然荒凉，令人惊骇。这些国民要服事巴比伦王七十年。'),
('CUV', '耶利米书', 24, 25, 12, '七十年满了以后，我必刑罚巴比伦王和那国民，并迦勒底人之地，因他们的罪孽使那地永远荒凉。这是耶和华说的。'),
('CUV', '耶利米书', 24, 25, 13, '我也必使我向那地所说的话，就是记在这书上的话，是耶利米向这些国民说的预言，都临到那地。'),
('CUV', '耶利米书', 24, 25, 14, '因为有多国和大君王必使迦勒底人作奴仆；我也必照他们的行为，按他们手所做的报应他们。'),
('CUV', '耶利米书', 24, 25, 15, '耶和华─以色列的神对我如此说：你从我手中接这杯忿怒的酒，使我所差遣你去的各国的民喝。'),
('CUV', '耶利米书', 24, 25, 16, '他们喝了就要东倒西歪，并要发狂，因我使刀剑临到他们中间。'),
('CUV', '耶利米书', 24, 25, 17, '我就从耶和华的手中接了这杯，给耶和华所差遣我去的各国的民喝，'),
('CUV', '耶利米书', 24, 25, 18, '就是耶路撒冷和犹大的城邑，并耶路撒冷的君王与首领，使这城邑荒凉，令人惊骇、嗤笑、咒诅，正如今日一样。'),
('CUV', '耶利米书', 24, 25, 19, '又有埃及王法老和他的臣仆、首领，以及他的众民，'),
('CUV', '耶利米书', 24, 25, 20, '并杂族的人民和乌斯地的诸王，与非利士地的诸王（亚实基伦、迦萨、以革伦，以及亚实突剩下的人）；'),
('CUV', '耶利米书', 24, 25, 21, '以东、摩押、亚扪人、'),
('CUV', '耶利米书', 24, 25, 22, '推罗的诸王、西顿的诸王、海岛的诸王、'),
('CUV', '耶利米书', 24, 25, 23, '底但、提玛、布斯，和一切剃周围头发的；'),
('CUV', '耶利米书', 24, 25, 24, '亚拉伯的诸王、住旷野杂族人民的诸王、'),
('CUV', '耶利米书', 24, 25, 25, '心利的诸王、以拦的诸王、玛代的诸王、'),
('CUV', '耶利米书', 24, 25, 26, '北方远近的诸王，以及天下地上的万国喝了，以后示沙克（就是巴比伦）王也要喝。'),
('CUV', '耶利米书', 24, 25, 27, '你要对他们说：万军之耶和华─以色列的神如此说：你们要喝，且要喝醉，要呕吐，且要跌倒，不得再起来，都因我使刀剑临到你们中间。'),
('CUV', '耶利米书', 24, 25, 28, '他们若不肯从你手接这杯喝，你就要对他们说：万军之耶和华如此说：你们一定要喝！'),
('CUV', '耶利米书', 24, 25, 29, '我既从称为我名下的城起首施行灾祸，你们能尽免刑罚么？你们必不能免，因为我要命刀剑临到地上一切的居民。这是万军之耶和华说的。'),
('CUV', '耶利米书', 24, 25, 30, '所以你要向他们预言这一切的话，攻击他们，说：耶和华必从高天吼叫，从圣所发声，向自己的羊群大声吼叫；他要向地上一切的居民呐喊，像踹葡萄的一样。'),
('CUV', '耶利米书', 24, 25, 31, '必有响声达到地极，因为耶和华与列国相争；凡有血气的，他必审问；至于恶人，他必交给刀剑。这是耶和华说的。'),
('CUV', '耶利米书', 24, 25, 32, '万军之耶和华如此说：看哪，必有灾祸从这国发到那国，并有大暴风从地极刮起。'),
('CUV', '耶利米书', 24, 25, 33, '到那日，从地这边直到地那边都有耶和华所杀戮的。必无人哀哭，不得收殓，不得葬埋，必在地上成为粪土。'),
('CUV', '耶利米书', 24, 25, 34, '牧人哪，你们当哀号，呼喊；群众的头目啊，你们要滚在灰中；因为你们被杀戮分散的日子足足来到。你们要跌碎，好像美器打碎一样。'),
('CUV', '耶利米书', 24, 25, 35, '牧人无路逃跑；群众的头目也无法逃脱。'),
('CUV', '耶利米书', 24, 25, 36, '听啊，有牧人呼喊，有群众头目哀号的声音，因为耶和华使他们的草场变为荒场。'),
('CUV', '耶利米书', 24, 25, 37, '耶和华发出猛烈的怒气，平安的羊圈就都寂静无声。'),
('CUV', '耶利米书', 24, 25, 38, '他离了隐密处像狮子一样，他们的地，因刀剑凶猛的欺压，又因他猛烈的怒气都成为可惊骇的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 26, 1, '犹大王约西亚的儿子约雅敬登基的时候，有这话从耶和华临到耶利米说：'),
('CUV', '耶利米书', 24, 26, 2, '耶和华如此说：你站在耶和华殿的院内，对犹大众城邑的人，就是到耶和华殿来礼拜的，说我所吩咐你的一切话，一字不可删减。'),
('CUV', '耶利米书', 24, 26, 3, '或者他们肯听从，各人回头离开恶道，使我后悔不将我因他们所行的恶，想要施行的灾祸降与他们。'),
('CUV', '耶利米书', 24, 26, 4, '你要对他们说，耶和华如此说：你们若不听从我，不遵行我设立在你们面前的律法，'),
('CUV', '耶利米书', 24, 26, 5, '不听我从早起来差遣到你们那著去我仆人众先知的话（你们还是没有听从），'),
('CUV', '耶利米书', 24, 26, 6, '我就必使这殿如示罗，使这城为地上万国所咒诅的。'),
('CUV', '耶利米书', 24, 26, 7, '耶利米在耶和华殿中说的这些话，祭司、先知与众民都听见了。'),
('CUV', '耶利米书', 24, 26, 8, '耶利米说完了耶和华所吩咐他对众人说的一切话，祭司、先知与众民都来抓住他，说：你必要死！'),
('CUV', '耶利米书', 24, 26, 9, '你为何托耶和华的名预言，说这殿必如示罗，这城必变为荒场无人居住呢？于是众民都在耶和华的殿中聚集到耶利米那著。'),
('CUV', '耶利米书', 24, 26, 10, '犹大的首领听见这事，就从王宫上到耶和华的殿，坐在耶和华殿的新门口。'),
('CUV', '耶利米书', 24, 26, 11, '祭司、先知对首领和众民说：这人是该死的；因为他说预言攻击这城，正如你们亲耳所听见的。'),
('CUV', '耶利米书', 24, 26, 12, '耶利米就对众首领和众民说：耶和华差遣我预言，攻击这殿和这城，说你们所听见的这一切话。'),
('CUV', '耶利米书', 24, 26, 13, '现在要改正你们的行动作为，听从耶和华─你们神的话，他就必后悔，不将所说的灾祸降与你们。'),
('CUV', '耶利米书', 24, 26, 14, '至于我，我在你们手中，你们眼看何为善，何为正，就那样待我罢！'),
('CUV', '耶利米书', 24, 26, 15, '但你们要确实地知道，若把我治死，就使无辜人的血归到你们和这城，并其中的居民了；因为耶和华实在差遣我到你们这著来，将这一切话传与你们耳中。'),
('CUV', '耶利米书', 24, 26, 16, '首领和众民就对祭司、先知说：这人是不该死的，因为他是奉耶和华─我们神的名向我们说话。'),
('CUV', '耶利米书', 24, 26, 17, '国中的长老就有几个人起来，对聚会的众民说：'),
('CUV', '耶利米书', 24, 26, 18, '当犹大王希西家的日子，有摩利沙人弥迦对犹大众人预言说：万军之耶和华如此说：锡安必被耕种像一块田；耶路撒冷必变为乱堆；这殿的山必像丛林的高处。'),
('CUV', '耶利米书', 24, 26, 19, '犹大王希西家和犹大众人岂是把他治死呢？希西家岂不是敬畏耶和华、恳求他的恩么？耶和华就后悔，不把自己所说的灾祸降与他们。若治死这人，我们就作了大恶，自害己命。'),
('CUV', '耶利米书', 24, 26, 20, '（又有一个人奉耶和华的名说预言，是基列耶琳人示玛雅的儿子乌利亚，他照耶利米的一切话说预言，攻击这城和这地。'),
('CUV', '耶利米书', 24, 26, 21, '约雅敬王和他众勇士、众首领听见了乌利亚的话，王就想要把他治死。乌利亚听见就惧怕，逃往埃及去了。'),
('CUV', '耶利米书', 24, 26, 22, '约雅敬王便打发亚革波的儿子以利拿单，带领几个人往埃及去。'),
('CUV', '耶利米书', 24, 26, 23, '他们就从埃及将乌利亚带出来，送到约雅敬王那里；王用刀杀了他，把他的尸首抛在平民的坟地中。）'),
('CUV', '耶利米书', 24, 26, 24, '然而，沙番的儿子亚希甘保护耶利米，不交在百姓的手中治死他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 27, 1, '犹大王约西亚的儿子约雅敬（约雅敬是西底家的别名，看第三节）登基的时候，有这话从耶和华临到耶利米说：'),
('CUV', '耶利米书', 24, 27, 2, '耶和华对我如此说：你做绳索与轭，加在自己的颈项上，'),
('CUV', '耶利米书', 24, 27, 3, '藉那些来到耶路撒冷见犹大王西底家的使臣之手，把绳索与轭送到以东王、摩押王、亚扪王、推罗王、西顿王那里，'),
('CUV', '耶利米书', 24, 27, 4, '且嘱咐使臣，传与他们的主人说，万军之耶和华─以色列的神如此说：'),
('CUV', '耶利米书', 24, 27, 5, '我用大能和伸出来的膀臂，创造大地和地上的人民、牲畜。我看给谁相宜，就把地给谁。'),
('CUV', '耶利米书', 24, 27, 6, '现在我将这些地都交给我仆人巴比伦王尼布甲尼撒的手，我也将田野的走兽给他使用。'),
('CUV', '耶利米书', 24, 27, 7, '列国都必服事他和他的儿孙，直到他本国遭报的日期来到。那时，多国和大君王要使他作他们的奴仆。'),
('CUV', '耶利米书', 24, 27, 8, '无论哪一邦哪一国，不肯服事这巴比伦王尼布甲尼撒，也不把颈项放在巴比伦王的轭下，我必用刀剑、饥荒、瘟疫刑罚那邦，直到我藉巴比伦王的手将他们毁灭。这是耶和华说的。'),
('CUV', '耶利米书', 24, 27, 9, '至于你们，不可听从你们的先知和占卜的、圆梦的、观兆的，以及行邪术的；他们告诉你们说：你们不致服事巴比伦王。'),
('CUV', '耶利米书', 24, 27, 10, '他们向你们说假预言，要叫你们迁移，远离本地，以致我将你们赶出去，使你们灭亡。'),
('CUV', '耶利米书', 24, 27, 11, '但哪一邦肯把颈项放在巴比伦王的轭下服事他，我必使那邦仍在本地存留，得以耕种居住。这是耶和华说的。'),
('CUV', '耶利米书', 24, 27, 12, '我就照这一切的话对犹大王西底家说：要把你们的颈项放在巴比伦王的轭下，服事他和他的百姓，便得存活。'),
('CUV', '耶利米书', 24, 27, 13, '你和你的百姓为何要因刀剑、饥荒、瘟疫死亡，正如耶和华论到不服事巴比伦王的那国说的话呢？'),
('CUV', '耶利米书', 24, 27, 14, '不可听那些先知对你们所说的话；他们说：你们不致服事巴比伦王，其实他们向你们说假预言。'),
('CUV', '耶利米书', 24, 27, 15, '耶和华说：我并没有打发他们，他们却托我的名说假预言，好使我将你们和向你们说预言的那些先知赶出去，一同灭亡。'),
('CUV', '耶利米书', 24, 27, 16, '我又对祭司和这众民说：耶和华如此说：你们不可听那先知对你们所说的预言。他们说：耶和华殿中的器皿快要从巴比伦带回来；其实他们向你们说假预言。'),
('CUV', '耶利米书', 24, 27, 17, '不可听从他们，只管服事巴比伦王便得存活。这城何致变为荒场呢？'),
('CUV', '耶利米书', 24, 27, 18, '他们若果是先知，有耶和华的话临到他们，让他们祈求万军之耶和华，使那在耶和华殿中和犹大王宫内，并耶路撒冷剩下的器皿，不被带到巴比伦去。'),
('CUV', '耶利米书', 24, 27, 19, '（因为万军之耶和华论到柱子、铜海、盆座，并剩在这城里的器皿，'),
('CUV', '耶利米书', 24, 27, 20, '就是巴比伦王尼布甲尼撒掳掠犹大王约雅敬的儿子耶哥尼雅，和犹大、耶路撒冷一切贵胄的时候所没有掠去的器皿。）'),
('CUV', '耶利米书', 24, 27, 21, '论到那在耶和华殿中和犹大王宫内，并耶路撒冷剩下的器皿，万军之耶和华─以色列的神如此说：'),
('CUV', '耶利米书', 24, 27, 22, '必被带到巴比伦存在那里，直到我眷顾以色列人的日子。那时，我必将这器皿带回来，交还此地。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 28, 1, '当年，就是犹大王西底家登基第四年五月，基遍人押朔的儿子，先知哈拿尼雅，在耶和华的殿中当著祭司和众民对我说：'),
('CUV', '耶利米书', 24, 28, 2, '万军之耶和华─以色列的神如此说：我已经折断巴比伦王的轭。'),
('CUV', '耶利米书', 24, 28, 3, '二年之内，我要将巴比伦王尼布甲尼撒从这地掠到巴比伦的器皿，就是耶和华殿中的一切器皿都带回此地。'),
('CUV', '耶利米书', 24, 28, 4, '我又要将犹大王约雅敬的儿子耶哥尼雅和被掳到巴比伦去的一切犹大人带回此地，因为我要折断巴比伦王的轭。这是耶和华说的。'),
('CUV', '耶利米书', 24, 28, 5, '先知耶利米当著祭司和站在耶和华殿里的众民对先知哈拿尼雅说：'),
('CUV', '耶利米书', 24, 28, 6, '阿们！愿耶和华如此行，愿耶和华成就你所预言的话，将耶和华殿中的器皿和一切被掳去的人从巴比伦带回此地。'),
('CUV', '耶利米书', 24, 28, 7, '然而我向你和众民耳中所要说的话，你应当听。'),
('CUV', '耶利米书', 24, 28, 8, '从古以来，在你我以前的先知，向多国和大邦说预言，论到争战、灾祸、瘟疫的事。'),
('CUV', '耶利米书', 24, 28, 9, '先知预言的平安，到话语成就的时候，人便知道他真是耶和华所差来的。'),
('CUV', '耶利米书', 24, 28, 10, '于是，先知哈拿尼雅将先知耶利米颈项上的轭取下来，折断了。'),
('CUV', '耶利米书', 24, 28, 11, '哈拿尼雅又当著众民说：耶和华如此说：二年之内我必照样从列国人的颈项上折断巴比伦王尼布甲尼撒的轭。于是先知耶利米就走了。'),
('CUV', '耶利米书', 24, 28, 12, '先知哈拿尼雅把先知耶利米颈项上的轭折断以后，耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 28, 13, '你去告诉哈拿尼雅说，耶和华如此说：你折断木轭，却换了铁轭！'),
('CUV', '耶利米书', 24, 28, 14, '因为万军之耶和华─以色列的神如此说：我已将铁轭加在这些国的颈项上，使他们服事巴比伦王尼布甲尼撒，他们总要服事他；我也把田野的走兽给了他。'),
('CUV', '耶利米书', 24, 28, 15, '于是先知耶利米对先知哈拿尼雅说：哈拿尼雅啊，你应当听！耶和华并没有差遣你，你竟使这百姓倚靠谎言。'),
('CUV', '耶利米书', 24, 28, 16, '所以耶和华如此说：看哪，我要叫你去世，你今年必死，因为你向耶和华说了叛逆的话。'),
('CUV', '耶利米书', 24, 28, 17, '这样，先知哈拿尼雅当年七月间就死了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 29, 1, '先知耶利米从耶路撒冷寄信与被掳的祭司、先知，和众民，并生存的长老，就是尼布甲尼撒从耶路撒冷掳到巴比伦去的。'),
('CUV', '耶利米书', 24, 29, 2, '（这在耶哥尼雅王和太后、太监，并犹大、耶路撒冷的首领，以及工匠、铁匠都离了耶路撒冷以后。）'),
('CUV', '耶利米书', 24, 29, 3, '他藉沙番的儿子以利亚萨和希勒家的儿子基玛利的手寄去。他们二人是犹大王西底家打发往巴比伦去见尼布甲尼撒王的。'),
('CUV', '耶利米书', 24, 29, 4, '信上说：万军之耶和华─以色列的神对一切被掳去的（就是我使他们从耶路撒冷被掳到巴比伦的人）如此说：'),
('CUV', '耶利米书', 24, 29, 5, '你们要盖造房屋，住在其中；栽种田园，吃其中所产的；'),
('CUV', '耶利米书', 24, 29, 6, '娶妻生儿女，为你们的儿子娶妻，使你们的女儿嫁人，生儿养女。在那�生养众多，不致减少。'),
('CUV', '耶利米书', 24, 29, 7, '我所使你们被掳到的那城，你们要为那城求平安，为那城祷告耶和华；因为那城得平安，你们也随著得平安。'),
('CUV', '耶利米书', 24, 29, 8, '万军之耶和华─以色列的神如此说：不要被你们中间的先知和占卜的诱惑，也不要听信自己所做的梦；'),
('CUV', '耶利米书', 24, 29, 9, '因为他们托我的名对你们说假预言，我并没有差遣他们。这是耶和华说的。'),
('CUV', '耶利米书', 24, 29, 10, '耶和华如此说：为巴比伦所定的七十年满了以后，我要眷顾你们，向你们成就我的恩言，使你们仍回此地。'),
('CUV', '耶利米书', 24, 29, 11, '耶和华说：我知道我向你们所怀的意念是赐平安的意念，不是降灾祸的意念，要叫你们末后有指望。'),
('CUV', '耶利米书', 24, 29, 12, '你们要呼求我，祷告我，我就应允你们。'),
('CUV', '耶利米书', 24, 29, 13, '你们寻求我，若专心寻求我，就必寻见。'),
('CUV', '耶利米书', 24, 29, 14, '耶和华说：我必被你们寻见，我也必使你们被掳的人归回，将你们从各国中和我所赶你们到的各处招聚了来，又将你们带回我使你们被掳掠离开的地方。这是耶和华说的。'),
('CUV', '耶利米书', 24, 29, 15, '你们说：耶和华在巴比伦为我们兴起先知；'),
('CUV', '耶利米书', 24, 29, 16, '所以耶和华论到坐大卫宝座的王和住在这城里的一切百姓，就是未曾与你们一同被掳的弟兄，'),
('CUV', '耶利米书', 24, 29, 17, '万军之耶和华如此说：看哪，我必使刀剑、饥荒、瘟疫临到他们，使他们像极坏的无花果，坏得不可吃。'),
('CUV', '耶利米书', 24, 29, 18, '我必用刀剑、饥荒、瘟疫追赶他们，使他们在天下万国抛来抛去，在我所赶他们到的各国中，令人咒诅、惊骇、嗤笑、羞辱。'),
('CUV', '耶利米书', 24, 29, 19, '耶和华说：这是因为他们没有听从我的话，就是我从早起来差遣我仆人众先知去说的，无奈他们不听。这是耶和华说的。'),
('CUV', '耶利米书', 24, 29, 20, '所以你们一切被掳去的，就是我从耶路撒冷打发到巴比伦去的，当听耶和华的话。'),
('CUV', '耶利米书', 24, 29, 21, '万军之耶和华─以色列的神论到哥赖雅的儿子亚哈，并玛西雅的儿子西底家，如此说：他们是托我名向你们说假预言的，我必将他们交在巴比伦王尼布甲尼撒的手中；他要在你们眼前杀害他们。'),
('CUV', '耶利米书', 24, 29, 22, '住巴比伦一切被掳的犹大人必藉这二人赌咒说：愿耶和华使你像巴比伦王在火中烧的西底家和亚哈一样。'),
('CUV', '耶利米书', 24, 29, 23, '这二人是在以色列中行了丑事，与邻舍的妻行淫，又假托我名说我未曾吩咐他们的话。知道的是我，作见证的也是我。这是耶和华说的。'),
('CUV', '耶利米书', 24, 29, 24, '论到尼希兰人示玛雅，你当说，'),
('CUV', '耶利米书', 24, 29, 25, '万军之耶和华─以色列的神如此说：你曾用自己的名寄信给耶路撒冷的众民和祭司玛西雅的儿子西番雅，并众祭司，说：'),
('CUV', '耶利米书', 24, 29, 26, '耶和华已经立你西番雅为祭司，代替祭司耶何耶大，使耶和华殿中有官长，好将一切狂妄自称为先知的人用枷枷住，用锁锁住。'),
('CUV', '耶利米书', 24, 29, 27, '现在亚拿突人耶利米向你们自称为先知，你们为何没有责备他呢？'),
('CUV', '耶利米书', 24, 29, 28, '因为他寄信给我们在巴比伦的人说：被掳的事必长久。你们要盖造房屋，住在其中；栽种田园，吃其中所产的。'),
('CUV', '耶利米书', 24, 29, 29, '祭司西番雅就把这信念给先知耶利米听。'),
('CUV', '耶利米书', 24, 29, 30, '于是耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 29, 31, '你当寄信给一切被掳的人说：耶和华论到尼希兰人示玛雅说：因为示玛雅向你们说预言，我并没有差遣他，他使你们倚靠谎言；'),
('CUV', '耶利米书', 24, 29, 32, '所以耶和华如此说：我必刑罚尼希兰人示玛雅和他的后裔，他必无一人存留住在这民中，也不得见我所要赐与我百姓的福乐，因为他向耶和华说了叛逆的话。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 30, 1, '耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 30, 2, '耶和华─以色列的神如此说：你将我对你说过的一切话都写在书上。'),
('CUV', '耶利米书', 24, 30, 3, '耶和华说：日子将到，我要使我的百姓以色列和犹大被掳的人归回；我也要使他们回到我所赐给他们列祖之地，他们就得这地为业。这是耶和华说的。'),
('CUV', '耶利米书', 24, 30, 4, '以下是耶和华论到以色列和犹大所说的话：'),
('CUV', '耶利米书', 24, 30, 5, '耶和华如此说：我们听见声音，是战抖惧怕而不平安的声音。'),
('CUV', '耶利米书', 24, 30, 6, '你们且访问看看，男人有产难么？我怎么看见人人用手掐腰，像产难的妇人，脸面都变青了呢？'),
('CUV', '耶利米书', 24, 30, 7, '哀哉！那日为大，无日可比；这是雅各遭难的时候，但他必被救出来。'),
('CUV', '耶利米书', 24, 30, 8, '万军之耶和华说：到那日，我必从你颈项上折断仇敌的轭，扭开他的绳索；外邦人不得再使你作他们的奴仆。'),
('CUV', '耶利米书', 24, 30, 9, '你们却要事奉耶和华─你们的神和我为你们所要兴起的王大卫。'),
('CUV', '耶利米书', 24, 30, 10, '故此，耶和华说：我的仆人雅各啊，不要惧怕；以色列啊，不要惊惶；因我要从远方拯救你，从被掳到之地拯救你的后裔；雅各必回来得享平靖安逸，无人使他害怕。'),
('CUV', '耶利米书', 24, 30, 11, '因我与你同在，要拯救你，也要将所赶散你到的那些国灭绝净尽，却不将你灭绝净尽，倒要从宽惩治你，万不能不罚你（不罚你：或译以你为无罪）。这是耶和华说的。'),
('CUV', '耶利米书', 24, 30, 12, '耶和华如此说：你的损伤无法医治；你的伤痕极其重大。'),
('CUV', '耶利米书', 24, 30, 13, '无人为你分诉，使你的伤痕得以缠裹；你没有医治的良药。'),
('CUV', '耶利米书', 24, 30, 14, '你所亲爱的都忘记你，不来探问（或译：理会）你。我因你的罪孽甚大，罪恶众多，曾用仇敌加的伤害伤害你，用残忍者的惩治惩治你。'),
('CUV', '耶利米书', 24, 30, 15, '你为何因损伤哀号呢？你的痛苦无法医治。我因你的罪孽甚大，罪恶众多，曾将这些加在你身上。'),
('CUV', '耶利米书', 24, 30, 16, '故此，凡吞吃你的必被吞吃；你的敌人个个都被掳去；掳掠你的必成为掳物；抢夺你的必成为掠物。'),
('CUV', '耶利米书', 24, 30, 17, '耶和华说：我必使你痊愈，医好你的伤痕，都因人称你为被赶散的，说：这是锡安，无人来探问（或译：理会）的！'),
('CUV', '耶利米书', 24, 30, 18, '耶和华如此说：我必使雅各被掳去的帐棚归回，也必顾惜他的住处。城必建造在原旧的山冈；宫殿也照旧有人居住。'),
('CUV', '耶利米书', 24, 30, 19, '必有感谢和欢乐的声音从其中发出，我要使他们增多，不致减少；使他们尊荣，不致卑微。'),
('CUV', '耶利米书', 24, 30, 20, '他们的儿女要如往日；他们的会众坚立在我面前；凡欺压他们的，我必刑罚他。'),
('CUV', '耶利米书', 24, 30, 21, '他们的君王必是属乎他们的；掌权的必从他们中间而出。我要使他就近我，他也要亲近我；不然，谁有胆量亲近我呢？这是耶和华说的。'),
('CUV', '耶利米书', 24, 30, 22, '你们要作我的子民，我要作你们的神。'),
('CUV', '耶利米书', 24, 30, 23, '看哪，耶和华的忿怒好像暴风已经发出；是扫灭的暴风，必转到恶人的头上。'),
('CUV', '耶利米书', 24, 30, 24, '耶和华的烈怒必不转消，直到他心中所拟定的成就了；末后的日子你们要明白。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 31, 1, '耶和华说：那时，我必作以色列各家的神；他们必作我的子民。'),
('CUV', '耶利米书', 24, 31, 2, '耶和华如此说：脱离刀剑的就是以色列人。我使他享安息的时候，他曾在旷野蒙恩。'),
('CUV', '耶利米书', 24, 31, 3, '古时（或译：从远方）耶和华向以色列（原文是我）显现，说：我以永远的爱爱你，因此我以慈爱吸引你。'),
('CUV', '耶利米书', 24, 31, 4, '以色列的民（原文是处女）哪，我要再建立你，你就被建立；你必再以击鼓为美，与欢乐的人一同跳舞而出；'),
('CUV', '耶利米书', 24, 31, 5, '又必在撒玛利亚的山上栽种葡萄园，栽种的人要享用所结的果子。'),
('CUV', '耶利米书', 24, 31, 6, '日子必到，以法莲山上守望的人必呼叫说：起来罢！我们可以上锡安，到耶和华─我们的神那里去。'),
('CUV', '耶利米书', 24, 31, 7, '耶和华如此说：你们当为雅各欢乐歌唱，因万国中为首的欢呼。当传扬颂赞说：耶和华啊，求你拯救你的百姓以色列所剩下的人。'),
('CUV', '耶利米书', 24, 31, 8, '我必将他们从北方领来，从地极招聚；同著他们来的有瞎子、瘸子、孕妇、产妇；他们必成为大帮回到这里来。'),
('CUV', '耶利米书', 24, 31, 9, '他们要哭泣而来。我要照他们恳求的引导他们，使他们在河水旁走正直的路，在其上不致绊跌；因为我是以色列的父，以法莲是我的长子。'),
('CUV', '耶利米书', 24, 31, 10, '列国啊，要听耶和华的话，传扬在远处的海岛说：赶散以色列的必招聚他，又看守他，好像牧人看守羊群。'),
('CUV', '耶利米书', 24, 31, 11, '因耶和华救赎了雅各，救赎他脱离比他更强之人的手。'),
('CUV', '耶利米书', 24, 31, 12, '他们要来到锡安的高处歌唱，又流归耶和华施恩之地，就是有五谷、新酒，和油，并羊羔、牛犊之地。他们的心必像浇灌的园子；他们也不再有一点愁烦。'),
('CUV', '耶利米书', 24, 31, 13, '那时，处女必欢乐跳舞；年少的、年老的，也必一同欢乐；因为我要使他们的悲哀变为欢喜，并要安慰他们，使他们的愁烦转为快乐。'),
('CUV', '耶利米书', 24, 31, 14, '我必以肥油使祭司的心满足；我的百姓也要因我的恩惠知足。这是耶和华说的。'),
('CUV', '耶利米书', 24, 31, 15, '耶和华如此说：在拉玛听见号咷痛哭的声音，是拉结哭他儿女，不肯受安慰，因为他们都不在了。'),
('CUV', '耶利米书', 24, 31, 16, '耶和华如此说：你禁止声音不要哀哭，禁止眼目不要流泪，因你所做之工必有赏赐；他们必从敌国归回。这是耶和华说的。'),
('CUV', '耶利米书', 24, 31, 17, '耶和华说：你末后必有指望；你的儿女必回到自己的境界。'),
('CUV', '耶利米书', 24, 31, 18, '我听见以法莲为自己悲叹说：你责罚我，我便受责罚，像不惯负轭的牛犊一样。求你使我回转，我便回转，因为你是耶和华─我的神。'),
('CUV', '耶利米书', 24, 31, 19, '我回转以后就真正懊悔；受教以后就拍腿叹息；我因担当幼年的凌辱就抱愧蒙羞。'),
('CUV', '耶利米书', 24, 31, 20, '耶和华说：以法莲是我的爱子么？是可喜悦的孩子么？我每逢责备他，仍深顾念他；所以我的心肠恋慕他；我必要怜悯他。'),
('CUV', '耶利米书', 24, 31, 21, '以色列民（原文是处女）哪，你当为自己设立指路碑，竖起引路柱。你要留心向大路，就是你所去的原路；你当回转，回转到你这些城邑。'),
('CUV', '耶利米书', 24, 31, 22, '背道的民（原文是女子）哪，你反来覆去要到几时呢？耶和华在地上造了一件新事，就是女子护卫男子。'),
('CUV', '耶利米书', 24, 31, 23, '万军之耶和华─以色列的神如此说：我使被掳之人归回的时候，他们在犹大地和其中的城邑必再这样说：公义的居所啊，圣山哪，愿耶和华赐福给你。'),
('CUV', '耶利米书', 24, 31, 24, '犹大和属犹大城邑的人，农夫和放羊的人，要一同住在其中。'),
('CUV', '耶利米书', 24, 31, 25, '疲乏的人，我使他饱饫；愁烦的人，我使他知足。'),
('CUV', '耶利米书', 24, 31, 26, '先知说：我醒了，觉著睡得香甜！'),
('CUV', '耶利米书', 24, 31, 27, '耶和华说：日子将到，我要把人的种和牲畜的种播种在以色列家和犹大家。'),
('CUV', '耶利米书', 24, 31, 28, '我先前怎样留意将他们拔出、拆毁、毁坏、倾覆、苦害，也必照样留意将他们建立、栽植。这是耶和华说的。'),
('CUV', '耶利米书', 24, 31, 29, '当那些日子，人不再说：父亲吃了酸葡萄，儿子的牙酸倒了。'),
('CUV', '耶利米书', 24, 31, 30, '但各人必因自己的罪死亡；凡吃酸葡萄的，自己的牙必酸倒。'),
('CUV', '耶利米书', 24, 31, 31, '耶和华说：日子将到，我要与以色列家和犹大家另立新约，'),
('CUV', '耶利米书', 24, 31, 32, '不像我拉著他们祖宗的手，领他们出埃及地的时候，与他们所立的约。我虽作他们的丈夫，他们却背了我的约。这是耶和华说的。'),
('CUV', '耶利米书', 24, 31, 33, '耶和华说：那些日子以后，我与以色列家所立的约乃是这样：我要将我的律法放在他们里面，写在他们心上。我要作他们的神，他们要作我的子民。'),
('CUV', '耶利米书', 24, 31, 34, '他们各人不再教导自己的邻舍和自己的弟兄说：你该认识耶和华，因为他们从最小的到至大的都必认识我。我要赦免他们的罪孽，不再记念他们的罪恶。这是耶和华说的。'),
('CUV', '耶利米书', 24, 31, 35, '那使太阳白日发光，使星月有定例，黑夜发亮，又搅动大海，使海中波浪匉訇的，万军之耶和华是他的名。他如此说：'),
('CUV', '耶利米书', 24, 31, 36, '这些定例若能在我面前废掉，以色列的后裔也就在我面前断绝，永远不再成国。这是耶和华说的。'),
('CUV', '耶利米书', 24, 31, 37, '耶和华如此说：若能量度上天，寻察下地的根基，我就因以色列后裔一切所行的弃绝他们。这是耶和华说的。'),
('CUV', '耶利米书', 24, 31, 38, '耶和华说：日子将到，这城必为耶和华建造，从哈楠业楼直到角门。'),
('CUV', '耶利米书', 24, 31, 39, '准绳要往外量出，直到迦立山，又转到歌亚。'),
('CUV', '耶利米书', 24, 31, 40, '抛尸的全谷和倒灰之处，并一切田地，直到汲沦溪，又直到东方马门的拐角，都要归耶和华为圣，不再拔出，不再倾覆，直到永远。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 32, 1, '犹大王西底家第十年，就是尼布甲尼撒十八年，耶和华的话临到耶利米。'),
('CUV', '耶利米书', 24, 32, 2, '那时巴比伦王的军队围困耶路撒冷，先知耶利米囚在护卫兵的院内，在犹大王的宫中；'),
('CUV', '耶利米书', 24, 32, 3, '因为犹大王西底家已将他囚禁，说：你为甚么预言说，耶和华如此说：我必将这城交在巴比伦王的手中，他必攻取这城。'),
('CUV', '耶利米书', 24, 32, 4, '犹大王西底家必不能逃脱迦勒底人的手，定要交在巴比伦王的手中，要口对口彼此说话，眼对眼彼此相看。'),
('CUV', '耶利米书', 24, 32, 5, '巴比伦王必将西底家带到巴比伦；西底家必住在那里，直到我眷顾他的时候。你们虽与迦勒底人争战，却不顺利。这是耶和华说的。'),
('CUV', '耶利米书', 24, 32, 6, '耶利米说：耶和华的话临到我说：'),
('CUV', '耶利米书', 24, 32, 7, '你叔叔沙龙的儿子哈拿篾必来见你，说：我在亚拿突的那块地，求你买来；因你买这地是合乎赎回之理。'),
('CUV', '耶利米书', 24, 32, 8, '我叔叔的儿子哈拿篾果然照耶和华的话来到护卫兵的院内，对我说：我在便雅悯境内、亚拿突的那块地，求你买来；因你买来是合乎承受之理，是你当赎的。你为自己买来罢！我─耶利米就知道这是耶和华的话。'),
('CUV', '耶利米书', 24, 32, 9, '我便向我叔叔的儿子哈拿篾买了亚拿突的那块地，平了十七舍客勒银子给他。'),
('CUV', '耶利米书', 24, 32, 10, '我在契上画押，将契封缄，又请见证人来，并用天平将银子平给他。'),
('CUV', '耶利米书', 24, 32, 11, '我便将照例按规所立的买契，就是封缄的那一张和敞著的那一张，'),
('CUV', '耶利米书', 24, 32, 12, '当著我叔叔的儿子哈拿篾和画押作见证的人，并坐在护卫兵院内的一切犹大人眼前，交给玛西雅的孙子尼利亚的儿子巴录。'),
('CUV', '耶利米书', 24, 32, 13, '当著他们众人眼前，我嘱咐巴录说：'),
('CUV', '耶利米书', 24, 32, 14, '万军之耶和华─以色列的神如此说：要将这封缄的和敞著的两张契放在瓦器里，可以存留多日。'),
('CUV', '耶利米书', 24, 32, 15, '因为万军之耶和华─以色列的神如此说：将来在这地必有人再买房屋、田地，和葡萄园。'),
('CUV', '耶利米书', 24, 32, 16, '我将买契交给尼利亚的儿子巴录以后，便祷告耶和华说：'),
('CUV', '耶利米书', 24, 32, 17, '主耶和华啊，你曾用大能和伸出来的膀臂创造天地，在你没有难成的事。'),
('CUV', '耶利米书', 24, 32, 18, '你施慈爱与千万人，又将父亲的罪孽报应在他后世子孙的怀中，是至大全能的神，万军之耶和华是你的名。'),
('CUV', '耶利米书', 24, 32, 19, '谋事有大略，行事有大能，注目观看世人一切的举动，为要照各人所行的和他做事的结果报应他。'),
('CUV', '耶利米书', 24, 32, 20, '在埃及地显神迹奇事，直到今日在以色列和别人中间也是如此，使自己得了名声，正如今日一样。'),
('CUV', '耶利米书', 24, 32, 21, '用神迹奇事和大能的手，并伸出来的膀臂与大可畏的事，领你的百姓以色列出了埃及。'),
('CUV', '耶利米书', 24, 32, 22, '将这地赐给他们，就是你向他们列祖起誓应许赐给他们流奶与蜜之地。'),
('CUV', '耶利米书', 24, 32, 23, '他们进入这地得了为业，却不听从你的话，也不遵行你的律法；你一切所吩咐他们行的，他们一无所行，因此你使这一切的灾祸临到他们。'),
('CUV', '耶利米书', 24, 32, 24, '看哪，敌人已经来到，筑垒要攻取这城；城也因刀剑、饥荒、瘟疫交在攻城的迦勒底人手中。你所说的话都成就了，你也看见了。'),
('CUV', '耶利米书', 24, 32, 25, '主耶和华啊，你对我说：要用银子为自己买那块地，又请见证人。其实这城已交在迦勒底人的手中了。'),
('CUV', '耶利米书', 24, 32, 26, '耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 32, 27, '我是耶和华，是凡有血气者的神，岂有我难成的事么？'),
('CUV', '耶利米书', 24, 32, 28, '耶和华如此说：我必将这城交付迦勒底人的手和巴比伦王尼布甲尼撒的手，他必攻取这城。'),
('CUV', '耶利米书', 24, 32, 29, '攻城的迦勒底人必来放火焚烧这城和其中的房屋。在这房屋上，人曾向巴力烧香，向别神浇奠，惹我发怒。'),
('CUV', '耶利米书', 24, 32, 30, '以色列人和犹大人自从幼年以来，专行我眼中看为恶的事；以色列人尽以手所做的惹我发怒。这是耶和华说的。'),
('CUV', '耶利米书', 24, 32, 31, '这城自从建造的那日直到今日，常惹我的怒气和忿怒，使我将这城从我面前除掉；'),
('CUV', '耶利米书', 24, 32, 32, '是因以色列人和犹大人一切的邪恶，就是他们和他们的君王、首领、祭司、先知，并犹大的众人，以及耶路撒冷的居民所行的，惹我发怒。'),
('CUV', '耶利米书', 24, 32, 33, '他们以背向我，不以面向我；我虽从早起来教训他们，他们却不听从，不受教训，'),
('CUV', '耶利米书', 24, 32, 34, '竟把可憎之物设立在称为我名下的殿中，污秽了这殿。'),
('CUV', '耶利米书', 24, 32, 35, '他们在欣嫩子谷建筑巴力的邱坛，好使自己的儿女经火归摩洛；他们行这可憎的事，使犹大陷在罪里，这并不是我所吩咐的，也不是我心所起的意。'),
('CUV', '耶利米书', 24, 32, 36, '现在论到这城，就是你们所说、已经因刀剑、饥荒、瘟疫交在巴比伦王手中的，耶和华─以色列的神如此说：'),
('CUV', '耶利米书', 24, 32, 37, '我在怒气、忿怒，和大恼恨中，将以色列人赶到各国。日后我必从那里将他们招聚出来，领他们回到此地，使他们安然居住。'),
('CUV', '耶利米书', 24, 32, 38, '他们要作我的子民，我要作他们的神。'),
('CUV', '耶利米书', 24, 32, 39, '我要使他们彼此同心同道，好叫他们永远敬畏我，使他们和他们后世的子孙得福乐，'),
('CUV', '耶利米书', 24, 32, 40, '又要与他们立永远的约，必随著他们施恩，并不离开他们，且使他们有敬畏我的心，不离开我。'),
('CUV', '耶利米书', 24, 32, 41, '我必欢喜施恩与他们，要尽心尽意、诚诚实实将他们栽于此地。'),
('CUV', '耶利米书', 24, 32, 42, '因为耶和华如此说：我怎样使这一切大祸临到这百姓，我也要照样使我所应许他们的一切福乐都临到他们。'),
('CUV', '耶利米书', 24, 32, 43, '你们说，这地是荒凉、无人民、无牲畜，是交付迦勒底人手之地。日后在这境内，必有人置买田地。'),
('CUV', '耶利米书', 24, 32, 44, '在便雅悯地、耶路撒冷四围的各处、犹大的城邑、山地的城邑、高原的城邑，并南地的城邑，人必用银子买田地，在契上画押，将契封缄，请出见证人，因为我必使被掳的人归回。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 33, 1, '耶利米还囚在护卫兵的院内，耶和华的话第二次临到他说：'),
('CUV', '耶利米书', 24, 33, 2, '成就的是耶和华，造作、为要建立的也是耶和华；耶和华是他的名。他如此说：'),
('CUV', '耶利米书', 24, 33, 3, '你求告我，我就应允你，并将你所不知道、又大又难的事指示你。'),
('CUV', '耶利米书', 24, 33, 4, '论到这城中的房屋和犹大王的宫室，就是拆毁为挡敌人高垒和刀剑的，耶和华─以色列的神如此说：'),
('CUV', '耶利米书', 24, 33, 5, '人要与迦勒底人争战，正是拿死尸充满这房屋，就是我在怒气和忿怒中所杀的人，因他们的一切恶，我就掩面不顾这城。'),
('CUV', '耶利米书', 24, 33, 6, '看哪，我要使这城得以痊愈安舒，使城中的人得医治，又将丰盛的平安和诚实显明与他们。'),
('CUV', '耶利米书', 24, 33, 7, '我也要使犹大被掳的和以色列被掳的归回，并建立他们和起初一样。'),
('CUV', '耶利米书', 24, 33, 8, '我要除净他们的一切罪，就是向我所犯的罪；又要赦免他们的一切罪，就是干犯我、违背我的罪。'),
('CUV', '耶利米书', 24, 33, 9, '这城要在地上万国人面前使我得颂赞，得荣耀，名为可喜可乐之城。万国人因听见我向这城所赐的福乐、所施的恩惠平安，就惧怕战兢。'),
('CUV', '耶利米书', 24, 33, 10, '耶和华如此说：你们论这地方，说是荒废无人民无牲畜之地，但在这荒凉无人民无牲畜的犹大城邑和耶路撒冷的街上，'),
('CUV', '耶利米书', 24, 33, 11, '必再听见有欢喜和快乐的声音、新郎和新妇的声音，并听见有人说：要称谢万军之耶和华，因耶和华本为善；他的慈爱永远长存！又有奉感谢祭到耶和华殿中之人的声音；因为我必使这地被掳的人归回，和起初一样。这是耶和华说的。'),
('CUV', '耶利米书', 24, 33, 12, '万军之耶和华如此说：在这荒废无人民无牲畜之地，并其中所有的城邑，必再有牧人的住处；他们要使羊群躺卧在那里。'),
('CUV', '耶利米书', 24, 33, 13, '在山地的城邑、高原的城邑、南地的城邑、便雅悯地、耶路撒冷四围的各处，和犹大的城邑必再有羊群从数点的人手下经过。这是耶和华说的。'),
('CUV', '耶利米书', 24, 33, 14, '耶和华说：日子将到，我应许以色列家和犹大家的恩言必然成就。'),
('CUV', '耶利米书', 24, 33, 15, '当那日子，那时候，我必使大卫公义的苗裔长起来；他必在地上施行公平和公义。'),
('CUV', '耶利米书', 24, 33, 16, '在那日子犹大必得救，耶路撒冷必安然居住，他的名必称为耶和华─我们的义。'),
('CUV', '耶利米书', 24, 33, 17, '因为耶和华如此说：大卫必永不断人坐在以色列家的宝座上；'),
('CUV', '耶利米书', 24, 33, 18, '祭司、利未人在我面前也不断人献燔祭、烧素祭，时常办理献祭的事。'),
('CUV', '耶利米书', 24, 33, 19, '耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 33, 20, '耶和华如此说：你们若能废弃我所立白日黑夜的约，使白日黑夜不按时轮转，'),
('CUV', '耶利米书', 24, 33, 21, '就能废弃我与我仆人大卫所立的约，使他没有儿子在他的宝座上为王，并能废弃我与事奉我的祭司、利未人所立的约。'),
('CUV', '耶利米书', 24, 33, 22, '天上的万象不能数算，海边的尘沙也不能斗量；我必照样使我仆人大卫的后裔和事奉我的利未人多起来。'),
('CUV', '耶利米书', 24, 33, 23, '耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 33, 24, '你没有揣摩这百姓的话么？他们说：耶和华所拣选的二族，他已经弃绝了。他们这样藐视我的百姓，以为不再成国。'),
('CUV', '耶利米书', 24, 33, 25, '耶和华如此说：若是我立白日黑夜的约不能存住，若是我未曾安排天地的定例，'),
('CUV', '耶利米书', 24, 33, 26, '我就弃绝雅各的后裔和我仆人大卫的后裔，不使大卫的后裔治理亚伯拉罕、以撒、雅各的后裔；因为我必使他们被掳的人归回，也必怜悯他们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 34, 1, '巴比伦王尼布甲尼撒率领他的全军和地上属他的各国各邦，攻打耶路撒冷和属耶路撒冷所有的城邑。那时，耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 34, 2, '耶和华─以色列的神说，你去告诉犹大王西底家，耶和华如此说：我要将这城交付巴比伦王的手，他必用火焚烧。'),
('CUV', '耶利米书', 24, 34, 3, '你必不能逃脱他的手，定被拿住，交在他的手中。你的眼要见巴比伦王的眼，他要口对口和你说话，你也必到巴比伦去。'),
('CUV', '耶利米书', 24, 34, 4, '犹大王西底家啊，你还要听耶和华的话。耶和华论到你如此说：你必不被刀剑杀死，'),
('CUV', '耶利米书', 24, 34, 5, '你必平安而死，人必为你焚烧物件，好像为你列祖，就是在你以前的先王焚烧一般。人必为你举哀说：哀哉！我主啊。耶和华说：这话是我说的。'),
('CUV', '耶利米书', 24, 34, 6, '于是，先知耶利米在耶路撒冷将这一切话告诉犹大王西底家。'),
('CUV', '耶利米书', 24, 34, 7, '那时，巴比伦王的军队正攻打耶路撒冷，又攻打犹大所剩下的城邑，就是拉吉和亚西加。原来犹大的坚固城只剩下这两座。'),
('CUV', '耶利米书', 24, 34, 8, '西底家王与耶路撒冷的众民立约，要向他们宣告自由，叫各人任他希伯来的仆人和婢女自由出去，谁也不可使他的一个犹大弟兄作奴仆。（此后，有耶和华的话临到耶利米。）'),
('CUV', '耶利米书', 24, 34, 9, 'a'),
('CUV', '耶利米书', 24, 34, 10, '所有立约的首领和众民就任他的仆人婢女自由出去，谁也不再叫他们作奴仆。大家都顺从，将他们释放了；'),
('CUV', '耶利米书', 24, 34, 11, '后来却又反悔，叫所任去自由的仆人婢女回来，勉强他们仍为仆婢。'),
('CUV', '耶利米书', 24, 34, 12, '因此耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 34, 13, '耶和华─以色列的神如此说：我将你们的列祖从埃及地为奴之家领出来的时候，与他们立约说：'),
('CUV', '耶利米书', 24, 34, 14, '你的一个希伯来弟兄若卖给你，服事你六年，到第七年你们各人就要任他自由出去。只是你们列祖不听从我，也不侧耳而听。'),
('CUV', '耶利米书', 24, 34, 15, '如今你们回转，行我眼中看为正的事，各人向邻舍宣告自由，并且在称为我名下的殿中、在我面前立约。'),
('CUV', '耶利米书', 24, 34, 16, '你们却又反悔，亵渎我的名，各人叫所任去随意自由的仆人婢女回来，勉强他们仍为仆婢。'),
('CUV', '耶利米书', 24, 34, 17, '所以耶和华如此说：你们没有听从我，各人向弟兄邻舍宣告自由。看哪！我向你们宣告一样自由，就是使你们自由于刀剑、饥荒、瘟疫之下，并且使你们在天下万国中抛来抛去。这是耶和华说的。'),
('CUV', '耶利米书', 24, 34, 18, '犹大的首领、耶路撒冷的首领、太监、祭司，和国中的众民曾将牛犊劈开，分成两半，从其中经过，在我面前立约。后来又违背我的约，不遵行这约上的话。'),
('CUV', '耶利米书', 24, 34, 19, 'a'),
('CUV', '耶利米书', 24, 34, 20, '我必将他们交在仇敌和寻索其命的人手中；他们的尸首必给空中的飞鸟和地上的野兽作食物。'),
('CUV', '耶利米书', 24, 34, 21, '并且我必将犹大王西底家和他的首领交在他们仇敌和寻索其命的人，与那暂离你们而去巴比伦王军队的手中。'),
('CUV', '耶利米书', 24, 34, 22, '耶和华说：我必吩咐他们回到这城，攻打这城，将城攻取，用火焚烧。我也要使犹大的城邑变为荒场，无人居住。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 35, 1, '当犹大王约西亚之子约雅敬的时候，耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 35, 2, '你去见利甲族的人，和他们说话，领他们进入耶和华殿的一间屋子，给他们酒喝。'),
('CUV', '耶利米书', 24, 35, 3, '我就将哈巴洗尼雅的孙子雅利米雅的儿子雅撒尼亚和他弟兄，并他众子，以及利甲全族的人，'),
('CUV', '耶利米书', 24, 35, 4, '领到耶和华的殿，进入神人伊基大利的儿子哈难众子的屋子。那屋子在首领的屋子旁边，在沙龙之子把门的玛西雅屋子以上。'),
('CUV', '耶利米书', 24, 35, 5, '于是我在利甲族人面前设摆盛满酒的碗和杯，对他们说：请你们喝酒。'),
('CUV', '耶利米书', 24, 35, 6, '他们却说：我们不喝酒；因为我们先祖利甲的儿子约拿达曾吩咐我们说：你们与你们的子孙永不可喝酒，'),
('CUV', '耶利米书', 24, 35, 7, '也不可盖房、撒种、栽种葡萄园，但一生的年日要住帐棚，使你们的日子在寄居之地得以延长。'),
('CUV', '耶利米书', 24, 35, 8, '凡我们先祖利甲的儿子约拿达所吩咐我们的话，我们都听从了。我们和我们的妻子儿女一生的年日都不喝酒，'),
('CUV', '耶利米书', 24, 35, 9, '也不盖房居住，也没有葡萄园、田地，和种子，'),
('CUV', '耶利米书', 24, 35, 10, '但住帐棚，听从我们先祖约拿达的话，照他所吩咐我们的去行。'),
('CUV', '耶利米书', 24, 35, 11, '巴比伦王尼布甲尼撒上此地来，我们因怕迦勒底的军队和亚兰的军队，就说：来吧，我们到耶路撒冷去。这样，我们才住在耶路撒冷。'),
('CUV', '耶利米书', 24, 35, 12, '耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 35, 13, '万军之耶和华─以色列的神如此说：你去对犹大人和耶路撒冷的居民说，耶和华说：你们不受教训，不听从我的话么？'),
('CUV', '耶利米书', 24, 35, 14, '利甲的儿子约拿达所吩咐他子孙不可喝酒的话，他们已经遵守，直到今日也不喝酒，因为他们听从先祖的吩咐。我从早起来警戒你们，你们却不听从我。'),
('CUV', '耶利米书', 24, 35, 15, '我从早起来，差遣我的仆人众先知去，说：你们各人当回头，离开恶道，改正行为，不随从事奉别神，就必住在我所赐给你们和你们列祖的地上。只是你们没有听从我，也没有侧耳而听。'),
('CUV', '耶利米书', 24, 35, 16, '利甲的儿子约拿达的子孙能遵守先人所吩咐他们的命，这百姓却没有听从我！'),
('CUV', '耶利米书', 24, 35, 17, '因此，耶和华─万军之神、以色列的神如此说：我要使我所说的一切灾祸临到犹大人和耶路撒冷的一切居民。因为我对他们说话，他们没有听从；我呼唤他们，他们没有答应。'),
('CUV', '耶利米书', 24, 35, 18, '耶利米对利甲族的人说：万军之耶和华─以色列的神如此说：因你们听从你们先祖约拿达的吩咐，谨守他的一切诫命，照他所吩咐你们的去行，'),
('CUV', '耶利米书', 24, 35, 19, '所以万军之耶和华─以色列的神如此说：利甲的儿子约拿达必永不缺人侍立在我面前。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 36, 1, '犹大王约西亚的儿子约雅敬第四年，耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 36, 2, '你取一书卷，将我对你说攻击以色列和犹大，并各国的一切话，从我对你说话的那日，就是从约西亚的日子起直到今日，都写在其上。'),
('CUV', '耶利米书', 24, 36, 3, '或者犹大家听见我想要降与他们的一切灾祸，各人就回头，离开恶道，我好赦免他们的罪孽和罪恶。'),
('CUV', '耶利米书', 24, 36, 4, '所以，耶利米召了尼利亚的儿子巴录来；巴录就从耶利米口中，将耶和华对耶利米所说的一切话写在书卷上。'),
('CUV', '耶利米书', 24, 36, 5, '耶利米吩咐巴录说：我被拘管，不能进耶和华的殿。'),
('CUV', '耶利米书', 24, 36, 6, '所以你要去趁禁食的日子，在耶和华殿中将耶和华的话，就是你从我口中所写在书卷上的话，念给百姓和一切从犹大城邑出来的人听。'),
('CUV', '耶利米书', 24, 36, 7, '或者他们在耶和华面前恳求各人回头，离开恶道，因为耶和华向这百姓所说要发的怒气和忿怒是大的。'),
('CUV', '耶利米书', 24, 36, 8, '尼利亚的儿子巴录就照先知耶利米一切所吩咐的去行，在耶和华的殿中从书上念耶和华的话。'),
('CUV', '耶利米书', 24, 36, 9, '犹大王约西亚的儿子约雅敬第五年九月，耶路撒冷的众民和那从犹大城邑来到耶路撒冷的众民，在耶和华面前宣告禁食的日子，'),
('CUV', '耶利米书', 24, 36, 10, '巴录就在耶和华殿的上院，耶和华殿的新门口，沙番的儿子文士基玛利雅的屋内，念书上耶利米的话给众民听。'),
('CUV', '耶利米书', 24, 36, 11, '沙番的孙子、基玛利雅的儿子米该亚听见书上耶和华的一切话，'),
('CUV', '耶利米书', 24, 36, 12, '他就下到王宫，进入文士的屋子。众首领，就是文士以利沙玛、示玛雅的儿子第莱雅、亚革波的儿子以利拿单、沙番的儿子基玛利雅、哈拿尼雅的儿子西底家，和其余的首领都坐在那里。'),
('CUV', '耶利米书', 24, 36, 13, '于是米该亚对他们述说他所听见的一切话，就是巴录向百姓念那书的时候所听见的。'),
('CUV', '耶利米书', 24, 36, 14, '众首领就打发古示的曾孙、示利米雅的孙子、尼探雅的儿子犹底到巴录那里，对他说：你将所念给百姓听的书卷拿在手中到我们这里来。尼利亚的儿子巴录就手拿书卷来到他们那里。'),
('CUV', '耶利米书', 24, 36, 15, '他们对他说：请你坐下，念给我们听。巴录就念给他们听。'),
('CUV', '耶利米书', 24, 36, 16, '他们听见这一切话就害怕，面面相观，对巴录说：我们必须将这一切话告诉王。'),
('CUV', '耶利米书', 24, 36, 17, '他们问巴录说：请你告诉我们，你怎样从他口中写这一切话呢？'),
('CUV', '耶利米书', 24, 36, 18, '巴录回答说：他用口向我说这一切话，我就用笔墨写在书上。'),
('CUV', '耶利米书', 24, 36, 19, '众首领对巴录说：你和耶利米要去藏起来，不可叫人知道你们在哪里。'),
('CUV', '耶利米书', 24, 36, 20, '众首领进院见王，却先把书卷存在文士以利沙玛的屋内，以后将这一切话说给王听。'),
('CUV', '耶利米书', 24, 36, 21, '王就打发犹底去拿这书卷来，他便从文士以利沙玛的屋内取来，念给王和王左右侍立的众首领听。'),
('CUV', '耶利米书', 24, 36, 22, '那时正是九月，王坐在过冬的房屋里，王的前面火盆中有烧著的火。'),
('CUV', '耶利米书', 24, 36, 23, '犹底念了三四篇（或译：行），王就用文士的刀将书卷割破，扔在火盆中，直到全卷在火中烧尽了。'),
('CUV', '耶利米书', 24, 36, 24, '王和听见这一切话的臣仆都不惧怕，也不撕裂衣服。'),
('CUV', '耶利米书', 24, 36, 25, '以利拿单和第莱雅，并基玛利雅恳求王不要烧这书卷，他却不听。'),
('CUV', '耶利米书', 24, 36, 26, '王就吩咐哈米勒的儿子（或译：王的儿子）耶拉篾和亚斯列的儿子西莱雅，并亚伯叠的儿子示利米雅，去捉拿文士巴录和先知耶利米。耶和华却将他们隐藏。'),
('CUV', '耶利米书', 24, 36, 27, '王烧了书卷（其上有巴录从耶利米口中所写的话）以后，耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 36, 28, '你再取一卷，将犹大王约雅敬所烧第一卷上的一切话写在其上。'),
('CUV', '耶利米书', 24, 36, 29, '论到犹大王约雅敬你要说，耶和华如此说：你烧了书卷，说：你为甚么在其上写著，说巴比伦王必要来毁灭这地，使这地上绝了人民牲畜呢？'),
('CUV', '耶利米书', 24, 36, 30, '所以耶和华论到犹大王约雅敬说：他后裔中必没有人坐在大卫的宝座上；他的尸首必被抛弃，白日受炎热，黑夜受寒霜。'),
('CUV', '耶利米书', 24, 36, 31, '我必因他和他后裔，并他臣仆的罪孽刑罚他们。我要使我所说的一切灾祸临到他们和耶路撒冷的居民，并犹大人；只是他们不听。'),
('CUV', '耶利米书', 24, 36, 32, '于是，耶利米又取一书卷交给尼利亚的儿子文士巴录，他就从耶利米的口中写了犹大王约雅敬所烧前卷上的一切话，另外又添了许多相彷的话。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 37, 1, '约西亚的儿子西底家代替约雅敬的儿子哥尼雅为王，是巴比伦王尼布甲尼撒立在犹大地作王的。'),
('CUV', '耶利米书', 24, 37, 2, '但西底家和他的臣仆，并国中的百姓，都不听从耶和华藉先知耶利米所说的话。'),
('CUV', '耶利米书', 24, 37, 3, '西底家王打发示利米雅的儿子犹甲和祭司玛西雅的儿子西番雅去见先知耶利米，说：求你为我们祷告耶和华─我们的神。'),
('CUV', '耶利米书', 24, 37, 4, '那时耶利米在民中出入，因为他们还没有把他囚在监里。'),
('CUV', '耶利米书', 24, 37, 5, '法老的军队已经从埃及出来，那围困耶路撒冷的迦勒底人听见他们的风声，就拔营离开耶路撒冷去了。'),
('CUV', '耶利米书', 24, 37, 6, '耶和华的话临到先知耶利米说：'),
('CUV', '耶利米书', 24, 37, 7, '耶和华─以色列的神如此说：犹大王打发你们来求问我，你们要如此对他说：那出来帮助你们法老的军队必回埃及本国去。'),
('CUV', '耶利米书', 24, 37, 8, '迦勒底人必再来攻打这城，并要攻取，用火焚烧。'),
('CUV', '耶利米书', 24, 37, 9, '耶和华如此说：你们不要自欺说迦勒底人必定离开我们，因为他们必不离开。'),
('CUV', '耶利米书', 24, 37, 10, '你们即便杀败了与你们争战的迦勒底全军，但剩下受伤的人也必各人从帐棚里起来，用火焚烧这城。'),
('CUV', '耶利米书', 24, 37, 11, '迦勒底的军队因怕法老的军队，拔营离开耶路撒冷的时候，'),
('CUV', '耶利米书', 24, 37, 12, '耶利米就杂在民中出离耶路撒冷，要往便雅悯地去，在那里得自己的地业。'),
('CUV', '耶利米书', 24, 37, 13, '他到了便雅悯门那里，有守门官名叫伊利雅，是哈拿尼亚的孙子、示利米雅的儿子，他就拿住先知耶利米，说：你是投降迦勒底人哪！'),
('CUV', '耶利米书', 24, 37, 14, '耶利米说：你这是谎话，我并不是投降迦勒底人。伊利雅不听他的话，就拿住他，解到首领那里。'),
('CUV', '耶利米书', 24, 37, 15, '首领恼怒耶利米，就打了他，将他囚在文士约拿单的房屋中，因为他们以这房屋当作监牢。'),
('CUV', '耶利米书', 24, 37, 16, '耶利米来到狱中，进入牢房，在那里囚了多日。'),
('CUV', '耶利米书', 24, 37, 17, '西底家王打发人提出他来，在自己的宫内私下问他说：从耶和华有甚么话临到没有？耶利米说：有！又说：你必交在巴比伦王手中。'),
('CUV', '耶利米书', 24, 37, 18, '耶利米又对西底家王说：我在甚么事上得罪你，或你的臣仆，或这百姓，你竟将我囚在监里呢？'),
('CUV', '耶利米书', 24, 37, 19, '对你们预言巴比伦王必不来攻击你们和这地的先知，现今在哪里呢？'),
('CUV', '耶利米书', 24, 37, 20, '主─我的王啊，求你现在垂听，准我在你面前的恳求：不要使我回到文士约拿单的房屋中，免得我死在那里。'),
('CUV', '耶利米书', 24, 37, 21, '于是，西底家王下令，他们就把耶利米交在护卫兵的院中，每天从饼舖街取一个饼给他，直到城中的饼用尽了。这样，耶利米仍在护卫兵的院中。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 38, 1, '玛坦的儿子示法提雅、巴施户珥的儿子基大利、示利米雅的儿子犹甲、玛基雅的儿子巴示户珥听见耶利米对众人所说的话，说：'),
('CUV', '耶利米书', 24, 38, 2, '耶和华如此说：住在这城里的必遭刀剑、饥荒、瘟疫而死；但出去归降迦勒底人的必得存活，就是以自己命为掠物的，必得存活。'),
('CUV', '耶利米书', 24, 38, 3, '耶和华如此说：这城必要交在巴比伦王军队的手中，他必攻取这城。'),
('CUV', '耶利米书', 24, 38, 4, '于是首领对王说：求你将这人治死；因他向城里剩下的兵丁和众民说这样的话，使他们的手发软。这人不是求这百姓得平安，乃是叫他们受灾祸。'),
('CUV', '耶利米书', 24, 38, 5, '西底家王说：他在你们手中，无论何事，王也不能与你们反对。'),
('CUV', '耶利米书', 24, 38, 6, '他们就拿住耶利米，下在哈米勒的儿子（或译：王的儿子）玛基雅的牢狱里；那牢狱在护卫兵的院中。他们用绳子将耶利米系下去。牢狱里没有水，只有淤泥，耶利米就陷在淤泥中。'),
('CUV', '耶利米书', 24, 38, 7, '在王宫的太监古实人以伯•米勒，听见他们将耶利米下了牢狱（那时王坐在便雅悯门口），'),
('CUV', '耶利米书', 24, 38, 8, '以伯•米勒就从王宫里出来，对王说：'),
('CUV', '耶利米书', 24, 38, 9, '主─我的王啊，这些人向先知耶利米一味地行恶，将他下在牢狱中；他在那里必因饥饿而死，因为城中再没有粮食。'),
('CUV', '耶利米书', 24, 38, 10, '王就吩咐古实人以伯•米勒说：你从这里带领三十人，趁著先知耶利米未死以前，将他从牢狱中提上来。'),
('CUV', '耶利米书', 24, 38, 11, '于是以伯•米勒带领这些人同去，进入王宫，到库房以下，从那里取了些碎布和破烂的衣服，用绳子缒下牢狱去到耶利米那里。'),
('CUV', '耶利米书', 24, 38, 12, '古实人以伯•米勒对耶利米说：你用这些碎布和破烂的衣服放在绳子上，垫你的胳肢窝。耶利米就照样行了。'),
('CUV', '耶利米书', 24, 38, 13, '这样，他们用绳子将耶利米从牢狱里拉上来。耶利米仍在护卫兵的院中。'),
('CUV', '耶利米书', 24, 38, 14, '西底家王打发人带领先知耶利米，进耶和华殿中第三门里见王。王就对耶利米说：我要问你一件事，你丝毫不可向我隐瞒。'),
('CUV', '耶利米书', 24, 38, 15, '耶利米对西底家说：我若告诉你，你岂不定要杀我么？我若劝戒你，你必不听从我。'),
('CUV', '耶利米书', 24, 38, 16, '西底家王就私下向耶利米说：我指著那造我们生命之永生的耶和华起誓：我必不杀你，也不将你交在寻索你命的人手中。'),
('CUV', '耶利米书', 24, 38, 17, '耶利米对西底家说：耶和华─万军之神、以色列的神如此说：你若出去归降巴比伦王的首领，你的命就必存活，这城也不致被火焚烧，你和你的全家都必存活。'),
('CUV', '耶利米书', 24, 38, 18, '你若不出去归降巴比伦王的首领，这城必交在迦勒底人手中。他们必用火焚烧，你也不得脱离他们的手。'),
('CUV', '耶利米书', 24, 38, 19, '西底家王对耶利米说：我怕那些投降迦勒底人的犹大人，恐怕迦勒底人将我交在他们手中，他们戏弄我。'),
('CUV', '耶利米书', 24, 38, 20, '耶利米说：迦勒底人必不将你交出。求你听从我对你所说耶和华的话，这样你必得好处，你的命也必存活。耶利米说：迦勒底人必不将你交出。求你听从我对你所说耶和华的话，这样你必得好处，你的命也必存活。'),
('CUV', '耶利米书', 24, 38, 21, '你若不肯出去，耶和华指示我的话乃是这样：'),
('CUV', '耶利米书', 24, 38, 22, '犹大王宫里所剩的妇女必都带到巴比伦王的首领那里。这些妇女必说：你知己的朋友催逼你，胜过你；见你的脚陷入淤泥中，就转身退后了。'),
('CUV', '耶利米书', 24, 38, 23, '人必将你的后妃和你的儿女带到迦勒底人那里；你也不得脱离他们的手，必被巴比伦王的手捉住；你也必使这城被火焚烧。'),
('CUV', '耶利米书', 24, 38, 24, '西底家对耶利米说：不要使人知道这些话，你就不至于死。'),
('CUV', '耶利米书', 24, 38, 25, '首领若听见了我与你说话，就来见你，问你说：你对王说甚么话不要向我们隐瞒，我们就不杀你。王向你说甚么话也要告诉我们。'),
('CUV', '耶利米书', 24, 38, 26, '你就对他们说：我在王面前恳求不要叫我回到约拿单的房屋死在那里。'),
('CUV', '耶利米书', 24, 38, 27, '随后众首领来见耶利米，问他，他就照王所吩咐的一切话回答他们。他们不再与他说话，因为事情没有泄漏。'),
('CUV', '耶利米书', 24, 38, 28, '于是耶利米仍在护卫兵的院中，直到耶路撒冷被攻取的日子。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 39, 1, '犹大王西底家第九年十月，巴比伦王尼布甲尼撒率领全军来围困耶路撒冷。'),
('CUV', '耶利米书', 24, 39, 2, '西底家十一年四月初九日，城被攻破。'),
('CUV', '耶利米书', 24, 39, 3, '耶路撒冷被攻取的时候，巴比伦王的首领尼甲•沙利薛、三甲•尼波、撒西金─拉撒力、尼甲•沙利薛─拉墨，并巴比伦王其余的一切首领都来坐在中门。'),
('CUV', '耶利米书', 24, 39, 4, '犹大王西底家和一切兵丁看见他们，就在夜间从靠近王园两城中间的门出城逃跑，往亚拉巴逃去。'),
('CUV', '耶利米书', 24, 39, 5, '迦勒底的军队追赶他们，在耶利哥的平原追上西底家，将他拿住，带到哈马地的利比拉、巴比伦王尼布甲尼撒那里；尼布甲尼撒就审判他。'),
('CUV', '耶利米书', 24, 39, 6, '巴比伦王在利比拉、西底家眼前杀了他的众子，又杀了犹大的一切贵胄，'),
('CUV', '耶利米书', 24, 39, 7, '并且剜西底家的眼睛，用铜链锁著他，要带到巴比伦去。'),
('CUV', '耶利米书', 24, 39, 8, '迦勒底人用火焚烧王宫和百姓的房屋，又拆毁耶路撒冷的城墙。'),
('CUV', '耶利米书', 24, 39, 9, '那时，护卫长尼布撒拉旦将城里所剩下的百姓和投降他的逃民，以及其余的民都掳到巴比伦去了。'),
('CUV', '耶利米书', 24, 39, 10, '护卫长尼布撒拉旦却将民中毫无所有的穷人留在犹大地，当时给他们葡萄园和田地。'),
('CUV', '耶利米书', 24, 39, 11, '巴比伦王尼布甲尼撒提到耶利米，嘱咐护卫长尼布撒拉旦说：'),
('CUV', '耶利米书', 24, 39, 12, '你领他去，好好地看待他，切不可害他；他对你怎么说，你就向他怎么行。'),
('CUV', '耶利米书', 24, 39, 13, '护卫长尼布撒拉旦和尼布沙斯班─拉撒力、尼甲•沙利薛─拉墨，并巴比伦王的一切官长，'),
('CUV', '耶利米书', 24, 39, 14, '打发人去，将耶利米从护卫兵院中提出来，交与沙番的孙子亚希甘的儿子基大利，带回家去。于是耶利米住在民中。'),
('CUV', '耶利米书', 24, 39, 15, '耶利米还囚在护卫兵院中的时候，耶和华的话临到他说：'),
('CUV', '耶利米书', 24, 39, 16, '你去告诉古实人以伯•米勒说，万军之耶和华─以色列的神如此说：我说降祸不降福的话必临到这城，到那时必在你面前成就了。'),
('CUV', '耶利米书', 24, 39, 17, '耶和华说：到那日我必拯救你，你必不致交在你所怕的人手中。'),
('CUV', '耶利米书', 24, 39, 18, '我定要搭救你，你不致倒在刀下，却要以自己的命为掠物，因你倚靠我。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 40, 1, '耶利米锁在耶路撒冷和犹大被掳到巴比伦的人中，护卫长尼布撒拉旦将他从拉玛释放以后，耶和华的话临到耶利米。'),
('CUV', '耶利米书', 24, 40, 2, '护卫长将耶利米叫来，对他说：耶和华─你的神曾说要降这祸与此地。'),
('CUV', '耶利米书', 24, 40, 3, '耶和华使这祸临到，照他所说的行了；因为你们得罪耶和华，没有听从他的话，所以这事临到你们。'),
('CUV', '耶利米书', 24, 40, 4, '现在我解开你手上的链子，你若看与我同往巴比伦去好，就可以去，我必厚待你；你若看与我同往巴比伦去不好，就不必去。看哪，全地在你面前，你以为哪里美好，哪里合宜，只管上那里去罢！'),
('CUV', '耶利米书', 24, 40, 5, '耶利米还没有回去，护卫长说：你可以回到沙番的孙子亚希甘的儿子基大利那里去；现在巴比伦王立他作犹大城邑的省长。你可以在他那里住在民中，不然，你看哪里合宜就可以上那里去。于是护卫长送他粮食和礼物，释放他去了。'),
('CUV', '耶利米书', 24, 40, 6, '耶利米就到米斯巴见亚希甘的儿子基大利，在他那里住在境内剩下的民中。'),
('CUV', '耶利米书', 24, 40, 7, '在田野的一切军长和属他们的人听见巴比伦王立了亚希甘的儿子基大利作境内的省长，并将没有掳到巴比伦的男人、妇女、孩童，和境内极穷的人全交给他。'),
('CUV', '耶利米书', 24, 40, 8, '于是军长尼探雅的儿子以实玛利，加利亚的两个儿子约哈难和约拿单，单户篾的儿子西莱雅，并尼陀法人以斐的众子，玛迦人的儿子耶撒尼亚和属他们的人，都到米斯巴见基大利。'),
('CUV', '耶利米书', 24, 40, 9, '沙番的孙子亚希甘的儿子基大利向他们和属他们的人起誓说：不要怕服事迦勒底人，只管住在这地，服事巴比伦王，就可以得福。'),
('CUV', '耶利米书', 24, 40, 10, '至于我，我要住在米斯巴，伺候那到我们这里来的迦勒底人；只是你们当积蓄酒、油，和夏天的果子，收在器皿里，住在你们所占的城邑中。'),
('CUV', '耶利米书', 24, 40, 11, '在摩押地和亚扪人中，在以东地和各国的一切犹大人，听见巴比伦王留下些犹大人，并立沙番的孙子亚希甘的儿子基大利管理他们。'),
('CUV', '耶利米书', 24, 40, 12, '这一切犹大人就从所赶到的各处回来，到犹大地米斯巴的基大利那里，又积蓄了许多的酒，并夏天的果子。'),
('CUV', '耶利米书', 24, 40, 13, '加利亚的儿子约哈难和在田野的一切军长来到米斯巴见基大利，'),
('CUV', '耶利米书', 24, 40, 14, '对他说：亚扪人的王巴利斯打发尼探雅的儿子以实玛利来要你的命，你知道么？亚希甘的儿子基大利却不信他们的话。'),
('CUV', '耶利米书', 24, 40, 15, '加利亚的儿子约哈难在米斯巴私下对基大利说：求你容我去杀尼探雅的儿子以实玛利，必无人知道。何必让他要你的命，使聚集到你这里来的犹大人都分散，以致犹大剩下的人都灭亡呢？'),
('CUV', '耶利米书', 24, 40, 16, '亚希甘的儿子基大利对加利亚的儿子约哈难说：你不可行这事，你所论以实玛利的话是假的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 41, 1, '七月间，王的大臣宗室以利沙玛的孙子、尼探雅的儿子以实玛利带著十个人，来到米斯巴见亚希甘的儿子基大利。他们在米斯巴一同吃饭。'),
('CUV', '耶利米书', 24, 41, 2, '尼探雅的儿子以实玛利和同他来的那十个人起来，用刀杀了沙番的孙子亚希甘的儿子基大利，就是巴比伦王所立为全地省长的。'),
('CUV', '耶利米书', 24, 41, 3, '以实玛利又杀了在米斯巴、基大利那里的一切犹大人和所遇见的迦勒底兵丁。'),
('CUV', '耶利米书', 24, 41, 4, '他杀了基大利，无人知道。'),
('CUV', '耶利米书', 24, 41, 5, '第二天，有八十人从示剑和示罗，并撒玛利亚来，胡须剃去，衣服撕裂，身体划破，手拿素祭和乳香，要奉到耶和华的殿。'),
('CUV', '耶利米书', 24, 41, 6, '尼探雅的儿子以实玛利出米斯巴迎接他们，随走随哭。遇见了他们，就对他们说：你们可以来见亚希甘的儿子基大利。'),
('CUV', '耶利米书', 24, 41, 7, '他们到了城中，尼探雅的儿子以实玛利和同著他的人就将他们杀了，抛在坑中。'),
('CUV', '耶利米书', 24, 41, 8, '只是他们中间有十个人对以实玛利说：不要杀我们，因为我们有许多大麦、小麦、油、蜜藏在田间。于是他住了手，没有将他们杀在弟兄中间。'),
('CUV', '耶利米书', 24, 41, 9, '以实玛利将所杀之人的尸首都抛在坑里基大利的旁边；这坑是从前亚撒王因怕以色列王巴沙所挖的。尼探雅的儿子以实玛利将那些被杀的人填满了坑。'),
('CUV', '耶利米书', 24, 41, 10, '以实玛利将米斯巴剩下的人，就是众公主和仍住在米斯巴所有的百姓，原是护卫长尼布撒拉旦交给亚希甘的儿子基大利的，都掳去了。尼探雅的儿子以实玛利掳了他们，要往亚扪人那里去。'),
('CUV', '耶利米书', 24, 41, 11, '加利亚的儿子约哈难和同著他的众军长听见尼探雅的儿子以实玛利所行的一切恶，'),
('CUV', '耶利米书', 24, 41, 12, '就带领众人前往，要和尼探雅的儿子以实玛利争战，在基遍的大水旁（或译：大水池旁）遇见他。'),
('CUV', '耶利米书', 24, 41, 13, '以实玛利那里的众人看见加利亚的儿子约哈难和同著他的众军长，就都欢喜。'),
('CUV', '耶利米书', 24, 41, 14, '这样，以实玛利从米斯巴所掳去的众人都转身归加利亚的儿子约哈难去了。'),
('CUV', '耶利米书', 24, 41, 15, '尼探雅的儿子以实玛利和八个人脱离约哈难的手，逃往亚扪人那里去了。'),
('CUV', '耶利米书', 24, 41, 16, '尼探雅的儿子以实玛利杀了亚希甘的儿子基大利，从米斯巴将剩下的一切百姓、兵丁、妇女、孩童、太监掳到基遍之后，加利亚的儿子约哈难和同著他的众军长将他们都夺回来，'),
('CUV', '耶利米书', 24, 41, 17, '带到靠近伯利恒的金罕寓（或译：基罗特金罕）住下，要进入埃及去；'),
('CUV', '耶利米书', 24, 41, 18, '因为尼探雅的儿子以实玛利杀了巴比伦王所立为省长的亚希甘的儿子基大利，约哈难惧怕迦勒底人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 42, 1, '众军长和加利亚的儿子约哈难，并何沙雅的儿子耶撒尼亚（又名亚撒利雅，见四十三章二节）以及众百姓，从最小的到至大的都进前来，'),
('CUV', '耶利米书', 24, 42, 2, '对先知耶利米说：求你准我们在你面前祈求，为我们这剩下的人祷告耶和华─你的神。我们本来众多，现在剩下的极少，这是你亲眼所见的。'),
('CUV', '耶利米书', 24, 42, 3, '愿耶和华─你的神指示我们所当走的路，所当做的事。'),
('CUV', '耶利米书', 24, 42, 4, '先知耶利米对他们说：我已经听见你们了，我必照著你们的话祷告耶和华─你们的神。耶和华无论回答甚么，我必都告诉你们，毫不隐瞒。'),
('CUV', '耶利米书', 24, 42, 5, '于是他们对耶利米说：我们若不照耶和华─你的神差遣你来说的一切话行，愿耶和华在我们中间作真实诚信的见证。'),
('CUV', '耶利米书', 24, 42, 6, '我们现在请你到耶和华─我们的神面前，他说的无论是好是歹，我们都必听从；我们听从耶和华─我们神的话，就可以得福。'),
('CUV', '耶利米书', 24, 42, 7, '过了十天，耶和华的话临到耶利米。'),
('CUV', '耶利米书', 24, 42, 8, '他就将加利亚的儿子约哈难和同著他的众军长，并众百姓，从最小的到至大的都叫了来，'),
('CUV', '耶利米书', 24, 42, 9, '对他们说：耶和华─以色列的神，就是你们请我在他面前为你们祈求的主，如此说：'),
('CUV', '耶利米书', 24, 42, 10, '你们若仍住在这地，我就建立你们，必不拆毁，栽植你们，并不拔出，因我为降与你们的灾祸后悔了。'),
('CUV', '耶利米书', 24, 42, 11, '不要怕你们所怕的巴比伦王。耶和华说：不要怕他！因为我与你们同在，要拯救你们脱离他的手。'),
('CUV', '耶利米书', 24, 42, 12, '我也要使他发怜悯，好怜悯你们，叫你们归回本地。'),
('CUV', '耶利米书', 24, 42, 13, '倘若你们说：我们不住在这地，以致不听从耶和华─你们神的话，'),
('CUV', '耶利米书', 24, 42, 14, '说：我们不住这地，却要进入埃及地，在那里看不见争战，听不见角声，也不致无食饥饿。我们必住在那里。'),
('CUV', '耶利米书', 24, 42, 15, '你们所剩下的犹大人哪，现在要听耶和华的话。万军之耶和华─以色列的神如此说：你们若定意要进入埃及，在那里寄居，'),
('CUV', '耶利米书', 24, 42, 16, '你们所惧怕的刀剑在埃及地必追上你们！你们所惧怕的饥荒在埃及要紧紧地跟随你们！你们必死在那里！'),
('CUV', '耶利米书', 24, 42, 17, '凡定意要进入埃及在那里寄居的必遭刀剑、饥荒、瘟疫而死，无一人存留，逃脱我所降与他们的灾祸。'),
('CUV', '耶利米书', 24, 42, 18, '万军之耶和华─以色列的神如此说：我怎样将我的怒气和忿怒倾在耶路撒冷的居民身上，你们进入埃及的时候，我也必照样将我的忿怒倾在你们身上，以致你们令人辱骂、惊骇、咒诅、羞辱，你们不得再见这地方。'),
('CUV', '耶利米书', 24, 42, 19, '所剩下的犹大人哪，耶和华论到你们说：不要进入埃及去。你们要确实地知道我今日警教你们了。'),
('CUV', '耶利米书', 24, 42, 20, '你们行诡诈自害；因为你们请我到耶和华─你们的神那里，说：求你为我们祷告耶和华─我们神，照耶和华─我们的神一切所说的告诉我们，我们就必遵行。'),
('CUV', '耶利米书', 24, 42, 21, '我今日将这话告诉你们，耶和华─你们的神为你们的事差遣我到你们那里说的，你们却一样没有听从。'),
('CUV', '耶利米书', 24, 42, 22, '现在你们要确实地知道，你们在所要去寄居之地必遭刀剑、饥荒、瘟疫而死。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 43, 1, '耶利米向众百姓说完了耶和华─他们神的一切话，就是耶和华─他们神差遣他去所说的一切话。'),
('CUV', '耶利米书', 24, 43, 2, '何沙雅的儿子亚撒利雅和加利亚的儿子约哈难，并一切狂傲的人，就对耶利米说：你说谎言！耶和华─我们的神并没有差遣你来说：你们不可进入埃及，在那里寄居。'),
('CUV', '耶利米书', 24, 43, 3, '这是尼利亚的儿子巴录挑唆你害我们，要将我们交在迦勒底人的手中，使我们有被杀的，有被掳到巴比伦去的。'),
('CUV', '耶利米书', 24, 43, 4, '于是加利亚的儿子约哈难和一切军长，并众百姓，不听从耶和华的话住在犹大地。'),
('CUV', '耶利米书', 24, 43, 5, '加利亚的儿子约哈难和一切军长却将所剩下的犹大人，就是从被赶到各国回来在犹大地寄居的男人、妇女、孩童，和众公主，并护卫长尼布撒拉旦所留在沙番的孙子亚希甘的儿子基大利那里的众人，与先知耶利米，以及尼利亚的儿子巴录，'),
('CUV', '耶利米书', 24, 43, 6, 'a'),
('CUV', '耶利米书', 24, 43, 7, '都带入埃及地，到了答比匿。这是因他们不听从耶和华的话。'),
('CUV', '耶利米书', 24, 43, 8, '在答比匿，耶和华的话临到耶利米说：'),
('CUV', '耶利米书', 24, 43, 9, '你在犹大人眼前要用手拿几块大石头，藏在砌砖的灰泥中，就是在答比匿法老的宫门那里，'),
('CUV', '耶利米书', 24, 43, 10, '对他们说：万军之耶和华─以色列的神如此说：我必召我的仆人巴比伦王尼布甲尼撒来。在所藏的石头上我要安置他的宝座；他必将光华的宝帐支搭在其上。'),
('CUV', '耶利米书', 24, 43, 11, '他要来攻击埃及地，定为死亡的，必致死亡；定为掳掠的，必被掳掠；定为刀杀的，必交刀杀。'),
('CUV', '耶利米书', 24, 43, 12, '我要在埃及神的庙中使火著起，巴比伦王要将庙宇焚烧，神像掳去；他要得（原文是披上）埃及地，好像牧人披上外衣，从那里安然而去。'),
('CUV', '耶利米书', 24, 43, 13, '他必打碎埃及地伯示麦的柱像，用火焚烧埃及神的庙宇。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 44, 1, '有临到耶利米的话，论及一切住在埃及地的犹大人，就是住在密夺、答比匿、挪弗、巴忒罗境内的犹大人，说：'),
('CUV', '耶利米书', 24, 44, 2, '万军之耶和华─以色列的神如此说：我所降与耶路撒冷和犹大各城的一切灾祸你们都看见了。那些城邑今日荒凉，无人居住；'),
('CUV', '耶利米书', 24, 44, 3, '这是因居民所行的恶，去烧香事奉别神，就是他们和你们，并你们列祖所不认识的神，惹我发怒。'),
('CUV', '耶利米书', 24, 44, 4, '我从早起来差遣我的仆人众先知去说，你们切不要行我所厌恶这可憎之事。'),
('CUV', '耶利米书', 24, 44, 5, '他们却不听从，不侧耳而听，不转离恶事，仍向别神烧香。'),
('CUV', '耶利米书', 24, 44, 6, '因此，我的怒气和忿怒都倒出来，在犹大城邑中和耶路撒冷的街市上，如火著起，以致都荒废凄凉，正如今日一样。'),
('CUV', '耶利米书', 24, 44, 7, '现在耶和华─万军之神、以色列的神如此说：你们为何作这大恶自害己命，使你们的男人、妇女、婴孩，和吃奶的都从犹大中剪除、不留一人呢？'),
('CUV', '耶利米书', 24, 44, 8, '就是因你们手所做的，在所去寄居的埃及地向别神烧香惹我发怒，使你们被剪除，在天下万国中令人咒诅羞辱。'),
('CUV', '耶利米书', 24, 44, 9, '你们列祖的恶行，犹大列王和他们后妃的恶行，你们自己和你们妻子的恶行，就是在犹大地、耶路撒冷街上所行的，你们都忘了么？'),
('CUV', '耶利米书', 24, 44, 10, '到如今还没有懊悔，没有惧怕，没有遵行我在你们和你们列祖面前所设立的法度律例。'),
('CUV', '耶利米书', 24, 44, 11, '所以万军之耶和华─以色列的神如此说：我必向你们变脸降灾，以致剪除犹大众人。'),
('CUV', '耶利米书', 24, 44, 12, '那定意进入埃及地、在那里寄居的，就是所剩下的犹大人，我必使他们尽都灭绝，必在埃及地仆倒，必因刀剑饥荒灭绝；从最小的到至大的都必遭刀剑饥荒而死，以致令人辱骂、惊骇、咒诅、羞辱。'),
('CUV', '耶利米书', 24, 44, 13, '我怎样用刀剑、饥荒、瘟疫刑罚耶路撒冷，也必照样刑罚那些住在埃及地的犹大人；'),
('CUV', '耶利米书', 24, 44, 14, '甚至那进入埃及地寄居的，就是所剩下的犹大人，都不得逃脱，也不得存留归回犹大地。他们心中甚想归回居住之地；除了逃脱的以外，一个都不能归回。'),
('CUV', '耶利米书', 24, 44, 15, '那些住在埃及地巴忒罗知道自己妻子向别神烧香的，与旁边站立的众妇女，聚集成群，回答耶利米说：'),
('CUV', '耶利米书', 24, 44, 16, '论到你奉耶和华的名向我们所说的话，我们必不听从。'),
('CUV', '耶利米书', 24, 44, 17, '我们定要成就我们口中所出的一切话，向天后烧香、浇奠祭，按著我们与我们列祖、君王、首领在犹大的城邑中和耶路撒冷的街市上素常所行的一样；因为那时我们吃饱饭、享福乐，并不见灾祸。'),
('CUV', '耶利米书', 24, 44, 18, '自从我们停止向天后烧香、浇奠祭，我们倒缺乏一切，又因刀剑饥荒灭绝。'),
('CUV', '耶利米书', 24, 44, 19, '妇女说：我们向天后烧香、浇奠祭，做天后像的饼供奉他，向他浇奠祭，是外乎我们的丈夫么？'),
('CUV', '耶利米书', 24, 44, 20, '耶利米对一切那样回答他的男人妇女说：'),
('CUV', '耶利米书', 24, 44, 21, '你们与你们列祖、君王、首领，并国内的百姓，在犹大城邑中和耶路撒冷街市上所烧的香，耶和华岂不记念，心中岂不思想么？'),
('CUV', '耶利米书', 24, 44, 22, '耶和华因你们所作的恶、所行可憎的事，不能再容忍，所以你们的地荒凉，令人惊骇咒诅，无人居住，正如今日一样。'),
('CUV', '耶利米书', 24, 44, 23, '你们烧香，得罪耶和华，没有听从他的话，没有遵行他的律法、条例、法度，所以你们遭遇这灾祸，正如今日一样。'),
('CUV', '耶利米书', 24, 44, 24, '耶利米又对众民和众妇女说：你们在埃及地的一切犹大人当听耶和华的话。'),
('CUV', '耶利米书', 24, 44, 25, '万军之耶和华─以色列的神如此说：你们和你们的妻都口中说、手里做，说：我们定要偿还所许的愿，向天后烧香、浇奠祭。现在你们只管坚定所许的愿而偿还罢！'),
('CUV', '耶利米书', 24, 44, 26, '所以你们住在埃及地的一切犹大人当听耶和华的话。耶和华说：我指著我的大名起誓，在埃及全地，我的名不再被犹大一个人的口称呼说：我指著主─永生的耶和华起誓。'),
('CUV', '耶利米书', 24, 44, 27, '我向他们留意降祸不降福；在埃及地的一切犹大人必因刀剑、饥荒所灭，直到灭尽。'),
('CUV', '耶利米书', 24, 44, 28, '脱离刀剑、从埃及地归回犹大地的人数很少；那进入埃及地要在那里寄居的，就是所剩下的犹大人，必知道是谁的话立得住，是我的话呢？是他们的话呢？'),
('CUV', '耶利米书', 24, 44, 29, '耶和华说：我在这地方刑罚你们，必有预兆，使你们知道我降祸与你们的话必要立得住。'),
('CUV', '耶利米书', 24, 44, 30, '耶和华如此说：我必将埃及王法老合弗拉交在他仇敌和寻索其命的人手中，像我将犹大王西底家交在他仇敌和寻索其命的巴比伦王尼布甲尼撒手中一样。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 45, 1, '犹大王约西亚的儿子约雅敬第四年，尼利亚的儿子巴录将先知耶利米口中所说的话写在书上。耶利米说：'),
('CUV', '耶利米书', 24, 45, 2, '巴录啊，耶和华─以色列的神说：'),
('CUV', '耶利米书', 24, 45, 3, '巴录（原文是你）曾说：哀哉！耶和华将忧愁加在我的痛苦上，我因唉哼而困乏，不得安歇。'),
('CUV', '耶利米书', 24, 45, 4, '你要这样告诉他，耶和华如此说：我所建立的，我必拆毁；我所栽植的，我必拔出；在全地我都如此行。'),
('CUV', '耶利米书', 24, 45, 5, '你为自己图谋大事么？不要图谋！我必使灾祸临到凡有血气的。但你无论往哪里去，我必使你以自己的命为掠物。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 46, 1, '耶和华论列国的话临到先知耶利米。'),
('CUV', '耶利米书', 24, 46, 2, '论到关乎埃及王法老尼哥的军队：这军队安营在伯拉河边的迦基米施，是巴比伦王尼布甲尼撒在犹大王约西亚的儿子约雅敬第四年所打败的。'),
('CUV', '耶利米书', 24, 46, 3, '你们要预备大小盾牌，往前上阵。'),
('CUV', '耶利米书', 24, 46, 4, '你们套上车，骑上马！顶盔站立，磨枪贯甲！'),
('CUV', '耶利米书', 24, 46, 5, '我为何看见他们惊惶转身退后呢？他们的勇士打败了，急忙逃跑，并不回头；惊吓四围都有！这是耶和华说的。'),
('CUV', '耶利米书', 24, 46, 6, '不要容快跑的逃避；不要容勇士逃脱（或译：快跑的不能逃避；勇士不能逃脱）；他们在北方伯拉河边绊跌仆倒。'),
('CUV', '耶利米书', 24, 46, 7, '像尼罗河涨发，像江河之水翻腾的是谁呢？'),
('CUV', '耶利米书', 24, 46, 8, '埃及像尼罗河涨发，像江河的水翻腾。他说：我要涨发遮盖遍地；我要毁灭城邑和其中的居民。'),
('CUV', '耶利米书', 24, 46, 9, '马匹上去罢！车辆急行罢！勇士，就是手拿盾牌的古实人和弗人（又作吕彼亚人），并拉弓的路德族，都出去罢！'),
('CUV', '耶利米书', 24, 46, 10, '那日是主─万军之耶和华报仇的日子，要向敌人报仇。刀剑必吞吃得饱，饮血饮足；因为主─万军之耶和华在北方伯拉河边有献祭的事。'),
('CUV', '耶利米书', 24, 46, 11, '埃及的民（原文是处女）哪，可以上基列取乳香去；你虽多服良药，总是徒然，不得治好。'),
('CUV', '耶利米书', 24, 46, 12, '列国听见你的羞辱，遍地满了你的哀声；勇士与勇士彼此相碰，一齐跌倒。'),
('CUV', '耶利米书', 24, 46, 13, '耶和华对先知耶利米所说的话，论到巴比伦王尼布甲尼撒要来攻击埃及地：'),
('CUV', '耶利米书', 24, 46, 14, '你们要传扬在埃及，宣告在密夺，报告在挪弗、答比匿说：要站起出队，自作准备，因为刀剑在你四围施行吞灭的事。'),
('CUV', '耶利米书', 24, 46, 15, '你的壮士为何被冲去呢？他们站立不住；因为耶和华驱逐他们，'),
('CUV', '耶利米书', 24, 46, 16, '使多人绊跌；他们也彼此撞倒，说：起来罢！我们再往本民本地去，好躲避欺压的刀剑。'),
('CUV', '耶利米书', 24, 46, 17, '他们在那里喊叫说：埃及王法老不过是个声音（或译：已经败亡）；他已错过所定的时候了。'),
('CUV', '耶利米书', 24, 46, 18, '君王─名为万军之耶和华的说：我指著我的永生起誓：尼布甲尼撒（原文是他）来的势派必像他泊在众山之中，像迦密在海边一样。'),
('CUV', '耶利米书', 24, 46, 19, '住在埃及的民哪（原文是女子），要预备掳去时所用的物件；因为挪弗必成为荒场，且被烧毁，无人居住。'),
('CUV', '耶利米书', 24, 46, 20, '埃及是肥美的母牛犊；但出于北方的毁灭（或译：牛虻）来到了！来到了！'),
('CUV', '耶利米书', 24, 46, 21, '其中的雇勇好像圈里的肥牛犊，他们转身退后，一齐逃跑，站立不住；因为他们遭难的日子、追讨的时候已经临到。'),
('CUV', '耶利米书', 24, 46, 22, '其中的声音好像蛇行一样。敌人要成队而来，如砍伐树木的手拿斧子攻击他。'),
('CUV', '耶利米书', 24, 46, 23, '耶和华说：埃及的树林虽然不能寻察（或译：穿不过），敌人却要砍伐，因他们多于蝗虫，不可胜数。'),
('CUV', '耶利米书', 24, 46, 24, '埃及的民（原文是女子）必然蒙羞，必交在北方人的手中。'),
('CUV', '耶利米书', 24, 46, 25, '万军之耶和华─以色列的神说：我必刑罚挪的亚扪（埃及尊大之神）和法老，并埃及与埃及的神，以及君王，也必刑罚法老和倚靠他的人。'),
('CUV', '耶利米书', 24, 46, 26, '我要将他们交付寻索其命之人的手和巴比伦王尼布甲尼撒与他臣仆的手；以后埃及必再有人居住，与从前一样。这是耶和华说的。'),
('CUV', '耶利米书', 24, 46, 27, '我的仆人雅各啊，不要惧怕！以色列啊，不要惊惶！因我要从远方拯救你，从被掳到之地拯救你的后裔。雅各必回来，得享平靖安逸，无人使他害怕。'),
('CUV', '耶利米书', 24, 46, 28, '我的仆人雅各啊，不要惧怕！因我与你同在。我要将我所赶你到的那些国灭绝净尽，却不将你灭绝净尽，倒要从宽惩治你，万不能不罚你（不罚你：或译以你为无罪）。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 47, 1, '法老攻击迦萨之先，有耶和华论非利士人的话临到先知耶利米。'),
('CUV', '耶利米书', 24, 47, 2, '耶和华如此说：有水从北方发起，成为涨溢的河，要涨过遍地和其中所有的，并城和其中所住的。人必呼喊；境内的居民都必哀号。'),
('CUV', '耶利米书', 24, 47, 3, '听见敌人壮马蹄跳的响声和战车隆隆、车轮轰轰；为父的手就发软，不回头看顾儿女。'),
('CUV', '耶利米书', 24, 47, 4, '因为日子将到，要毁灭一切非利士人，剪除帮助推罗、西顿所剩下的人。原来耶和华必毁灭非利士人，就是迦斐托海岛余剩的人。'),
('CUV', '耶利米书', 24, 47, 5, '迦萨成了光秃；平原中所剩的亚实基伦归于无有。你用刀划身，要到几时呢？'),
('CUV', '耶利米书', 24, 47, 6, '耶和华的刀剑哪，你到几时才止息呢？你要入鞘，安靖不动。'),
('CUV', '耶利米书', 24, 47, 7, '耶和华既吩咐你攻击亚实基伦和海边之地，他已经派定你，焉能止息呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 48, 1, '论摩押。万军之耶和华─以色列的神如此说：尼波有祸了！因变为荒场。基列亭蒙羞被攻取。米斯迦蒙羞被毁坏；'),
('CUV', '耶利米书', 24, 48, 2, '摩押不再被称赞。有人在希实本设计谋害他，说：来罢！我们将他剪除，不再成国。玛得缅哪，你也必默默无声；刀剑必追赶你。'),
('CUV', '耶利米书', 24, 48, 3, '从何罗念有喊荒凉大毁灭的哀声：'),
('CUV', '耶利米书', 24, 48, 4, '摩押毁灭了！他的孩童（或译：家僮）发哀声，使人听见。'),
('CUV', '耶利米书', 24, 48, 5, '人上鲁希坡随走随哭，因为在何罗念的下坡听见毁灭的哀声。'),
('CUV', '耶利米书', 24, 48, 6, '你们要奔逃，自救性命，独自居住，好像旷野的杜松。'),
('CUV', '耶利米书', 24, 48, 7, '你因倚靠自己所做的和自己的财宝必被攻取。基抹和属他的祭司、首领也要一同被掳去。'),
('CUV', '耶利米书', 24, 48, 8, '行毁灭的必来到各城，并无一城得免。山谷必致败落，平原必被毁坏；正如耶和华所说的。'),
('CUV', '耶利米书', 24, 48, 9, '要将翅膀给摩押，使他可以飞去。他的城邑必致荒凉，无人居住。'),
('CUV', '耶利米书', 24, 48, 10, '（懒惰为耶和华行事的，必受咒诅；禁止刀剑不经血的，必受咒诅。）'),
('CUV', '耶利米书', 24, 48, 11, '摩押自幼年以来常享安逸，如酒在渣滓上澄清，没有从这器皿倒在那器皿里，也未曾被掳去。因此，他的原味尚存，香气未变。'),
('CUV', '耶利米书', 24, 48, 12, '耶和华说：日子将到，我必打发倒酒的往他那里去，将他倒出来，倒空他的器皿，打碎他的坛子。'),
('CUV', '耶利米书', 24, 48, 13, '摩押必因基抹羞愧，像以色列家从前倚靠伯特利的神羞愧一样。'),
('CUV', '耶利米书', 24, 48, 14, '你们怎么说：我们是勇士，是有勇力打仗的呢？'),
('CUV', '耶利米书', 24, 48, 15, '摩押变为荒场，敌人上去进了他的城邑。他所特选的少年人下去遭了杀戮；这是君王─名为万军之耶和华说的。'),
('CUV', '耶利米书', 24, 48, 16, '摩押的灾殃临近；他的苦难速速来到。'),
('CUV', '耶利米书', 24, 48, 17, '凡在他四围的和认识他名的，你们都要为他悲伤，说：那结实的杖和那美好的棍，何竟折断了呢？'),
('CUV', '耶利米书', 24, 48, 18, '住在底本的民哪（原文是女子），要从你荣耀的位上下来，坐受干渴；因毁灭摩押的上来攻击你，毁坏了你的保障。'),
('CUV', '耶利米书', 24, 48, 19, '住亚罗珥的啊，要站在道旁观望，问逃避的男人和逃脱的女人说：是甚么事呢？'),
('CUV', '耶利米书', 24, 48, 20, '摩押因毁坏蒙羞；你们要哀号呼喊，要在亚嫩旁报告说：摩押变为荒场！'),
('CUV', '耶利米书', 24, 48, 21, '刑罚临到平原之地的何伦、雅杂、米法押、'),
('CUV', '耶利米书', 24, 48, 22, '底本、尼波、伯•低比拉太音、'),
('CUV', '耶利米书', 24, 48, 23, '基列亭、伯迦末、伯•米恩、'),
('CUV', '耶利米书', 24, 48, 24, '加略、波斯拉，和摩押地远近所有的城邑。'),
('CUV', '耶利米书', 24, 48, 25, '摩押的角砍断了，摩押的膀臂折断了。这是耶和华说的。'),
('CUV', '耶利米书', 24, 48, 26, '你们要使摩押沉醉，因他向耶和华夸大。他要在自己所吐之中打滚，又要被人嗤笑。'),
('CUV', '耶利米书', 24, 48, 27, '摩押啊，你不曾嗤笑以色列么？他岂是在贼中查出来的呢？你每逢提到他便摇头。'),
('CUV', '耶利米书', 24, 48, 28, '摩押的居民哪，要离开城邑，住在山崖里，像鸽子在深渊口上搭窝。'),
('CUV', '耶利米书', 24, 48, 29, '我们听说摩押人骄傲，是极其骄傲；听说他自高自傲，并且狂妄，居心自大。'),
('CUV', '耶利米书', 24, 48, 30, '耶和华说：我知道他的忿怒是虚空的；他夸大的话一无所成。'),
('CUV', '耶利米书', 24, 48, 31, '因此，我要为摩押哀号，为摩押全地呼喊；人必为吉珥•哈列设人叹息。'),
('CUV', '耶利米书', 24, 48, 32, '西比玛的葡萄树啊，我为你哀哭，甚于雅谢人哀哭。你的枝子蔓延过海，直长到雅谢海。那行毁灭的已经临到你夏天的果子和你所摘的葡萄。'),
('CUV', '耶利米书', 24, 48, 33, '肥田和摩押地的欢喜快乐都被夺去；我使酒醡的酒绝流，无人踹酒欢呼；那欢呼却变为仇敌的呐喊（原文是那欢呼却不是欢呼）。'),
('CUV', '耶利米书', 24, 48, 34, '希实本人发的哀声达到以利亚利，直达到雅杂；从琐珥达到何罗念，直到伊基拉施利施亚，因为宁林的水必然干涸。'),
('CUV', '耶利米书', 24, 48, 35, '耶和华说：我必在摩押地使那在邱坛献祭的，和那向他的神烧香的都断绝了。'),
('CUV', '耶利米书', 24, 48, 36, '我心腹为摩押哀鸣如箫，我心肠为吉珥•哈列设人也是如此，因摩押人所得的财物都灭没了。'),
('CUV', '耶利米书', 24, 48, 37, '各人头上光秃，胡须剪短，手有划伤，腰束麻布。'),
('CUV', '耶利米书', 24, 48, 38, '在摩押的各房顶上和街市上处处有人哀哭；因我打碎摩押，好像打碎无人喜悦的器皿。这是耶和华说的。'),
('CUV', '耶利米书', 24, 48, 39, '摩押何等毁坏！何等哀号！何等羞愧转背！这样，摩押必令四围的人嗤笑惊骇。'),
('CUV', '耶利米书', 24, 48, 40, '耶和华如此说：仇敌必如大鹰飞起，展开翅膀，攻击摩押。'),
('CUV', '耶利米书', 24, 48, 41, '加略被攻取，保障也被占据。到那日，摩押的勇士心中疼痛如临产的妇人。'),
('CUV', '耶利米书', 24, 48, 42, '摩押必被毁灭，不再成国，因他向耶和华夸大。'),
('CUV', '耶利米书', 24, 48, 43, '耶和华说：摩押的居民哪，恐惧、陷坑、网罗都临近你。'),
('CUV', '耶利米书', 24, 48, 44, '躲避恐惧的必坠入陷坑；从陷坑上来的必被网罗缠住；因我必使追讨之年临到摩押。这是耶和华说的。'),
('CUV', '耶利米书', 24, 48, 45, '躲避的人无力站在希实本的影下；因为有火从希实本发出，有火燄出于西宏的城，烧尽摩押的角和哄嚷人的头顶。'),
('CUV', '耶利米书', 24, 48, 46, '摩押啊，你有祸了！属基抹的民灭亡了！因你的众子都被掳去，你的众女也被掳去。'),
('CUV', '耶利米书', 24, 48, 47, '耶和华说：到末后，我还要使被掳的摩押人归回。摩押受审判的话到此为止。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 49, 1, '论亚扪人。耶和华如此说：以色列没有儿子么？没有后嗣么？玛勒堪为何得迦得之地为业呢？属他的民为何住其中的城邑呢？'),
('CUV', '耶利米书', 24, 49, 2, '耶和华说：日子将到，我必使人听见打仗的喊声，是攻击亚扪人拉巴的喊声。拉巴要成为乱堆；属他的乡村（原文是女子）要被火焚烧。先前得以色列地为业的，此时以色列倒要得他们的地为业。这是耶和华说的。'),
('CUV', '耶利米书', 24, 49, 3, '希实本哪，你要哀号，因为爱地变为荒场。拉巴的居民（原文是女子）哪，要呼喊，以麻布束腰；要哭号，在篱笆中跑来跑去；因玛勒堪和属他的祭司、首领要一同被掳去。'),
('CUV', '耶利米书', 24, 49, 4, '背道的民（原文是女子）哪，你们为何因有山谷，就是水流的山谷夸张呢？为何倚靠财宝说：谁能来到我们这里呢？'),
('CUV', '耶利米书', 24, 49, 5, '主─万军之耶和华说：我要使恐吓从四围的人中临到你们；你们必被赶出，各人一直前往，没有人收聚逃民。'),
('CUV', '耶利米书', 24, 49, 6, '后来我还要使被掳的亚扪人归回。这是耶和华说的。'),
('CUV', '耶利米书', 24, 49, 7, '论以东。万军之耶和华如此说：提幔中再没有智慧么？明哲人不再有谋略么？他们的智慧尽归无有么？'),
('CUV', '耶利米书', 24, 49, 8, '底但的居民哪，要转身逃跑，住在深密处；因为我向以扫追讨的时候，必使灾殃临到他。'),
('CUV', '耶利米书', 24, 49, 9, '摘葡萄的若来到他那里，岂不剩下些葡萄呢？盗贼若夜间而来，岂不毁坏直到够了呢？'),
('CUV', '耶利米书', 24, 49, 10, '我却使以扫赤露，显出他的隐密处；他不能自藏。他的后裔、弟兄、邻舍尽都灭绝；他也归于无有。'),
('CUV', '耶利米书', 24, 49, 11, '你撇下孤儿，我必保全他们的命；你的寡妇可以倚靠我。'),
('CUV', '耶利米书', 24, 49, 12, '耶和华如此说：原不该喝那杯的一定要喝。你能尽免刑罚么？你必不能免，一定要喝！'),
('CUV', '耶利米书', 24, 49, 13, '耶和华说：我指著自己起誓，波斯拉必令人惊骇、羞辱、咒诅，并且荒凉。他的一切城邑必变为永远的荒场。'),
('CUV', '耶利米书', 24, 49, 14, '我从耶和华那里听见信息，并有使者被差往列国去，说：你们聚集来攻击以东，要起来争战。'),
('CUV', '耶利米书', 24, 49, 15, '我使你在列国中为最小，在世人中被藐视。'),
('CUV', '耶利米书', 24, 49, 16, '住在山穴中据守山顶的啊，论到你的威吓，你因心中的狂傲自欺；你虽如大鹰高高搭窝，我却从那里拉下你来。这是耶和华说的。'),
('CUV', '耶利米书', 24, 49, 17, '以东必令人惊骇；凡经过的人就受惊骇，又因他一切的灾祸嗤笑。'),
('CUV', '耶利米书', 24, 49, 18, '耶和华说：必无人住在那里，也无人在其中寄居，要像所多玛、蛾摩拉，和邻近的城邑倾覆的时候一样。'),
('CUV', '耶利米书', 24, 49, 19, '仇敌必像狮子从约但河边的丛林上来，攻击坚固的居所。转眼之间，我要使以东人逃跑，离开这地。谁蒙拣选，我就派谁治理这地。谁能比我呢？谁能给我定规日期呢？有何牧人能在我面前站立得住呢？'),
('CUV', '耶利米书', 24, 49, 20, '你们要听耶和华攻击以东所说的谋略和他攻击提幔居民所定的旨意。仇敌定要将他们群众微弱的拉去，定要使他们的居所荒凉。'),
('CUV', '耶利米书', 24, 49, 21, '因他们仆倒的声音，地就震动。人在红海那里必听见呼喊的声音。'),
('CUV', '耶利米书', 24, 49, 22, '仇敌必如大鹰飞起，展开翅膀攻击波斯拉。到那日，以东的勇士心中疼痛如临产的妇人。'),
('CUV', '耶利米书', 24, 49, 23, '论大马色。哈马和亚珥拔蒙羞，因他们听见凶恶的信息就消化了。海上有忧愁，不得平静。'),
('CUV', '耶利米书', 24, 49, 24, '大马色发软，转身逃跑。战兢将他捉住；痛苦忧愁将他抓住，如产难的妇人一样。'),
('CUV', '耶利米书', 24, 49, 25, '我所喜乐可称赞的城，为何被撇弃了呢？'),
('CUV', '耶利米书', 24, 49, 26, '他的少年人必仆倒在街上；当那日，一切兵丁必默默无声。这是万军之耶和华说的。'),
('CUV', '耶利米书', 24, 49, 27, '我必在大马色城中使火著起，烧灭便哈达的宫殿。'),
('CUV', '耶利米书', 24, 49, 28, '论巴比伦王尼布甲尼撒所攻打的基达和夏琐的诸国。耶和华如此说：迦勒底人哪，起来上基达去，毁灭东方人。'),
('CUV', '耶利米书', 24, 49, 29, '他们的帐棚和羊群都要夺去，将幔子和一切器皿，并骆驼为自己掠去。人向他们喊著说：四围都有惊吓。'),
('CUV', '耶利米书', 24, 49, 30, '耶和华说：夏琐的居民哪，要逃奔远方，住在深密处；因为巴比伦王尼布甲尼撒设计谋害你们，起意攻击你们。'),
('CUV', '耶利米书', 24, 49, 31, '耶和华说：迦勒底人哪，起来！上安逸无虑的居民那里去；他们是无门无闩、独自居住的。'),
('CUV', '耶利米书', 24, 49, 32, '他们的骆驼必成为掠物；他们众多的牲畜必成为掳物。我必将剃周围头发的人分散四方（原文是风），使灾殃从四围临到他们。这是耶和华说的。'),
('CUV', '耶利米书', 24, 49, 33, '夏琐必成为野狗的住处，永远凄凉；必无人住在那里，也无人在其中寄居。'),
('CUV', '耶利米书', 24, 49, 34, '犹大王西底家登基的时候，耶和华论以拦的话临到先知耶利米说：'),
('CUV', '耶利米书', 24, 49, 35, '万军之耶和华如此说：我必折断以拦人的弓，就是他们为首的权力。'),
('CUV', '耶利米书', 24, 49, 36, '我要使四风从天的四方刮来，临到以拦人，将他们分散四方（原文是风）。这被赶散的人没有一国不到的。'),
('CUV', '耶利米书', 24, 49, 37, '耶和华说：我必使以拦人在仇敌和寻索其命的人面前惊惶；我也必使灾祸，就是我的烈怒临到他们，又必使刀剑追杀他们，直到将他们灭尽。'),
('CUV', '耶利米书', 24, 49, 38, '我要在以拦设立我的宝座，从那里除灭君王和首领。这是耶和华说的。'),
('CUV', '耶利米书', 24, 49, 39, '到末后，我还要使被掳的以拦人归回。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 50, 1, '耶和华藉先知耶利米论巴比伦和迦勒底人之地所说的话。'),
('CUV', '耶利米书', 24, 50, 2, '你们要在万国中传扬报告，竖立大旗；要报告，不可隐瞒，说：巴比伦被攻取，彼勒蒙羞，米罗达惊惶。巴比伦的神像都蒙羞；他的偶像都惊惶。'),
('CUV', '耶利米书', 24, 50, 3, '因有一国从北方上来攻击他，使他的地荒凉，无人居住，连人带牲畜都逃走了。'),
('CUV', '耶利米书', 24, 50, 4, '耶和华说：当那日子、那时候，以色列人要和犹大人同来，随走随哭，寻求耶和华─他们的神。'),
('CUV', '耶利米书', 24, 50, 5, '他们必访问锡安，又面向这里，说：来罢，你们要与耶和华联合为永远不忘的约。'),
('CUV', '耶利米书', 24, 50, 6, '我的百姓作了迷失的羊，牧人使他们走差路，使他们转到山上。他们从大山走到小山，竟忘了安歇之处。'),
('CUV', '耶利米书', 24, 50, 7, '凡遇见他们的，就把他们吞灭。敌人说：我们没有罪；因他们得罪那作公义居所的耶和华，就是他们列祖所仰望的耶和华。'),
('CUV', '耶利米书', 24, 50, 8, '我民哪，你们要从巴比伦中逃走，从迦勒底人之地出去，要像羊群前面走的公山羊。'),
('CUV', '耶利米书', 24, 50, 9, '因我必激动联合的大国从北方上来攻击巴比伦，他们要摆阵攻击他；他必从那里被攻取。他们的箭好像善射之勇士的箭，一枝也不徒然返回。'),
('CUV', '耶利米书', 24, 50, 10, '迦勒底必成为掠物；凡掳掠他的都必心满意足。这是耶和华说的。'),
('CUV', '耶利米书', 24, 50, 11, '抢夺我产业的啊，你们因欢喜快乐，且像踹谷撒欢的母牛犊，又像发嘶声的壮马。'),
('CUV', '耶利米书', 24, 50, 12, '你们的母巴比伦就极其抱愧，生你们的必然蒙羞。他要列在诸国之末，成为旷野、旱地、沙漠。'),
('CUV', '耶利米书', 24, 50, 13, '因耶和华的忿怒，必无人居住，要全然荒凉。凡经过巴比伦的要受惊骇，又因他所遭的灾殃嗤笑。'),
('CUV', '耶利米书', 24, 50, 14, '所有拉弓的，你们要在巴比伦的四围摆阵，射箭攻击他。不要爱惜箭枝，因他得罪了耶和华。'),
('CUV', '耶利米书', 24, 50, 15, '你们要在他四围呐喊；他已经投降。外郭坍塌了，城墙拆毁了，因为这是耶和华报仇的事。你们要向巴比伦报仇；他怎样待人，也要怎样待他。'),
('CUV', '耶利米书', 24, 50, 16, '你们要将巴比伦撒种的和收割时拿镰刀的都剪除了。他们各人因怕欺压的刀剑，必归回本族，逃到本土。'),
('CUV', '耶利米书', 24, 50, 17, '以色列是打散的羊，是被狮子赶出的。首先是亚述王将他吞灭，末后是巴比伦王尼布甲尼撒将他的骨头折断。'),
('CUV', '耶利米书', 24, 50, 18, '所以万军之耶和华─以色列的神如此说：我必罚巴比伦王和他的地，像我从前罚亚述王一样。'),
('CUV', '耶利米书', 24, 50, 19, '我必再领以色列回他的草场，他必在迦密和巴珊吃草，又在以法莲山上和基列境内得以饱足。'),
('CUV', '耶利米书', 24, 50, 20, '耶和华说：当那日子、那时候，虽寻以色列的罪孽，一无所有；虽寻犹大的罪恶，也无所见；因为我所留下的人，我必赦免。'),
('CUV', '耶利米书', 24, 50, 21, '耶和华说：上去攻击米拉大翁之地，又攻击比割的居民。要追杀灭尽，照我一切所吩咐你的去行。'),
('CUV', '耶利米书', 24, 50, 22, '境内有打仗和大毁灭的响声。'),
('CUV', '耶利米书', 24, 50, 23, '全地的大锤何竟砍断破坏？巴比伦在列国中何竟荒凉？'),
('CUV', '耶利米书', 24, 50, 24, '巴比伦哪，我为你设下网罗，你不知不觉被缠住。你被寻著，也被捉住；因为你与耶和华争竞。'),
('CUV', '耶利米书', 24, 50, 25, '耶和华已经开了武库，拿出他恼恨的兵器；因为主─万军之耶和华在迦勒底人之地有当做的事。'),
('CUV', '耶利米书', 24, 50, 26, '你们要从极远的边界来攻击他，开他的仓廪，将他堆如高堆，毁灭净尽，丝毫不留。'),
('CUV', '耶利米书', 24, 50, 27, '要杀他的一切牛犊，使他们下去遭遇杀戮。他们有祸了，因为追讨他们的日子已经来到。'),
('CUV', '耶利米书', 24, 50, 28, '（有从巴比伦之地逃避出来的人，在锡安扬声报告耶和华─我们的神报仇，就是为他的殿报仇。）'),
('CUV', '耶利米书', 24, 50, 29, '招集一切弓箭手来攻击巴比伦。要在巴比伦四围安营，不要容一人逃脱，照著他所做的报应他；他怎样待人，也要怎样待他，因为他向耶和华─以色列的圣者发了狂傲。'),
('CUV', '耶利米书', 24, 50, 30, '所以他的少年人必仆倒在街上。当那日，一切兵丁必默默无声。这是耶和华说的。'),
('CUV', '耶利米书', 24, 50, 31, '主─万军之耶和华说：你这狂傲的啊，我与你反对，因为我追讨你的日子已经来到。'),
('CUV', '耶利米书', 24, 50, 32, '狂傲的必绊跌仆倒，无人扶起。我也必使火在他的城邑中里起来，将他四围所有的尽行烧灭。'),
('CUV', '耶利米书', 24, 50, 33, '万军之耶和华如此说：以色列人和犹大人一同受欺压；凡掳掠他们的都紧紧抓住他们，不肯释放。'),
('CUV', '耶利米书', 24, 50, 34, '他们的救赎主大有能力，万军之耶和华是他的名。他必伸清他们的冤，好使全地得平安，并搅扰巴比伦的居民。'),
('CUV', '耶利米书', 24, 50, 35, '耶和华说：有刀剑临到迦勒底人和巴比伦的居民，并他的首领与智慧人。'),
('CUV', '耶利米书', 24, 50, 36, '有刀剑临到矜夸的人，他们就成为愚昧；有刀剑临到他的勇士，他们就惊惶。'),
('CUV', '耶利米书', 24, 50, 37, '有刀剑临到他的马匹、车辆，和其中杂族的人民；他们必像妇女一样。有刀剑临到他的宝物，就被抢夺。'),
('CUV', '耶利米书', 24, 50, 38, '有干旱临到他的众水，就必干涸；因为这是有雕刻偶像之地，人因偶像而颠狂。'),
('CUV', '耶利米书', 24, 50, 39, '所以旷野的走兽和豺狼必住在那里，鸵鸟也住在其中，永无人烟，世世代代无人居住。'),
('CUV', '耶利米书', 24, 50, 40, '耶和华说：必无人住在那里，也无人在其中寄居，要像我倾覆所多玛、蛾摩拉，和邻近的城邑一样。'),
('CUV', '耶利米书', 24, 50, 41, '看哪，有一种民从北方而来，并有一大国和许多君王被激动，从地极来到。'),
('CUV', '耶利米书', 24, 50, 42, '他们拿弓和枪，性情残忍，不施怜悯；他们的声音像海浪匉訇。巴比伦城（原文是女子）啊，他们骑马，都摆队伍如上战场的人，要攻击你。'),
('CUV', '耶利米书', 24, 50, 43, '巴比伦王听见他们的风声，手就发软，痛苦将他抓住，疼痛仿佛产难的妇人。'),
('CUV', '耶利米书', 24, 50, 44, '仇敌必像狮子从约但河边的丛林上来，攻击坚固的居所。转眼之间，我要使他们逃跑，离开这地。谁蒙拣选，我就派谁治理这地。谁能比我呢？谁能给我定规日期呢？有何牧人能在我面前站立得住呢？'),
('CUV', '耶利米书', 24, 50, 45, '你们要听耶和华攻击巴比伦所说的谋略和他攻击迦勒底人之地所定的旨意。仇敌定要将他们群众微弱的拉去，定要使他们的居所荒凉。'),
('CUV', '耶利米书', 24, 50, 46, '因巴比伦被取的声音，地就震动，人在列邦都听见呼喊的声音。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 51, 1, '耶和华如此说：我必使毁灭的风刮起，攻击巴比伦和住在立加米的人。'),
('CUV', '耶利米书', 24, 51, 2, '我要打发外邦人来到巴比伦，簸扬他，使他的地空虚。在他遭祸的日子，他们要周围攻击他。'),
('CUV', '耶利米书', 24, 51, 3, '拉弓的，要向拉弓的和贯甲挺身的射箭。不要怜惜他的少年人；要灭尽他的全军。'),
('CUV', '耶利米书', 24, 51, 4, '他们必在迦勒底人之地被杀仆倒，在巴比伦的街上被刺透。'),
('CUV', '耶利米书', 24, 51, 5, '以色列和犹大虽然境内充满违背以色列圣者的罪，却没有被他的神─万军之耶和华丢弃。'),
('CUV', '耶利米书', 24, 51, 6, '你们要从巴比伦中逃奔，各救自己的性命！不要陷在他的罪孽中一同灭亡；因为这是耶和华报仇的时候，他必向巴比伦施行报应。'),
('CUV', '耶利米书', 24, 51, 7, '巴比伦素来是耶和华手中的金杯，使天下沉醉；万国喝了他的酒就颠狂了。'),
('CUV', '耶利米书', 24, 51, 8, '巴比伦忽然倾覆毁坏；要为他哀号；为止他的疼痛，拿乳香或者可以治好。'),
('CUV', '耶利米书', 24, 51, 9, '我们想医治巴比伦，他却没有治好。离开他罢！我们各人归回本国；因为他受的审判通于上天，达到穹苍。'),
('CUV', '耶利米书', 24, 51, 10, '耶和华已经彰显我们的公义。来罢！我们可以在锡安报告耶和华─我们神的作为。'),
('CUV', '耶利米书', 24, 51, 11, '你们要磨尖了箭头，抓住盾牌。耶和华定意攻击巴比伦，将他毁灭，所以激动了玛代君王的心；因这是耶和华报仇，就是为自己的殿报仇。'),
('CUV', '耶利米书', 24, 51, 12, '你们要竖立大旗，攻击巴比伦的城墙；要坚固瞭望台，派定守望的设下埋伏；因为耶和华指著巴比伦居民所说的话、所定的意，他已经作成。'),
('CUV', '耶利米书', 24, 51, 13, '住在众水之上多有财宝的啊，你的结局到了！你贪婪之量满了！'),
('CUV', '耶利米书', 24, 51, 14, '万军之耶和华指著自己起誓说：我必使敌人充满你，像蚂蚱一样；他们必呐喊攻击你。'),
('CUV', '耶利米书', 24, 51, 15, '耶和华用能力创造大地，用智慧建立世界，用聪明铺张穹苍。'),
('CUV', '耶利米书', 24, 51, 16, '他一发声，空中便有多水激动；他使云雾从地极上腾。他造电随雨而闪，从他府库中带出风来。'),
('CUV', '耶利米书', 24, 51, 17, '各人都成了畜类，毫无知识。各银匠都因他的偶像羞愧；他所铸的偶像本是虚假的，其中并无气息，'),
('CUV', '耶利米书', 24, 51, 18, '都是虚无的，是迷惑人的工作，到追讨的时候，必被除灭。'),
('CUV', '耶利米书', 24, 51, 19, '雅各的分不像这些，因他是造作万有的主；以色列也是他产业的支派。万军之耶和华是他的名。'),
('CUV', '耶利米书', 24, 51, 20, '你是我争战的斧子和打仗的兵器；我要用你打碎列国，用你毁灭列邦；'),
('CUV', '耶利米书', 24, 51, 21, '用你打碎马和骑马的；用你打碎战车和坐在其上的；'),
('CUV', '耶利米书', 24, 51, 22, '用你打碎男人和女人；用你打碎老年人和少年人；用你打碎壮丁和处女；'),
('CUV', '耶利米书', 24, 51, 23, '用你打碎牧人和他的群畜；用你打碎农夫和他一对牛；用你打碎省长和副省长。'),
('CUV', '耶利米书', 24, 51, 24, '耶和华说：我必在你们眼前报复巴比伦人和迦勒底居民在锡安所行的诸恶。'),
('CUV', '耶利米书', 24, 51, 25, '耶和华说：你这行毁灭的山哪，就是毁灭天下的山，我与你反对。我必向你伸手，将你从山岩滚下去，使你成为烧毁的山。'),
('CUV', '耶利米书', 24, 51, 26, '人必不从你那里取石头为房角石，也不取石头为根基石；你必永远荒凉。这是耶和华说的。'),
('CUV', '耶利米书', 24, 51, 27, '要在境内竖立大旗，在各国中吹角，使列国预备攻击巴比伦，将亚拉腊、米尼、亚实基拿各国招来攻击他；又派军长来攻击他，使马匹上来如蚂蚱，'),
('CUV', '耶利米书', 24, 51, 28, '使列国和玛代君王，与省长和副省长，并他们所管全地之人，都预备攻击他。'),
('CUV', '耶利米书', 24, 51, 29, '地必震动而瘠苦；因耶和华向巴比伦所定的旨意成立了，使巴比伦之地荒凉，无人居住。'),
('CUV', '耶利米书', 24, 51, 30, '巴比伦的勇士止息争战，藏在坚垒之中。他们的勇力衰尽，好像妇女一样。巴比伦的住处有火著起，门闩都折断了。'),
('CUV', '耶利米书', 24, 51, 31, '通报的要彼此相遇，送信的要互相迎接，报告巴比伦王说：城的四方被攻取了，'),
('CUV', '耶利米书', 24, 51, 32, '渡口被占据了，苇塘被火烧了，兵丁也惊慌了。'),
('CUV', '耶利米书', 24, 51, 33, '万军之耶和华─以色列的神如此说：巴比伦城（原文作女子）好像踹谷的禾场；再过片时，收割他的时候就到了。'),
('CUV', '耶利米书', 24, 51, 34, '以色列人说：巴比伦王尼布甲尼撒吞灭我，压碎我，使我成为空虚的器皿。他像大鱼将我吞下，用我的美物充满他的肚腹，又将我赶出去。'),
('CUV', '耶利米书', 24, 51, 35, '锡安的居民要说：巴比伦以强暴待我，损害我的身体，愿这罪归给他。耶路撒冷人要说：愿流我们血的罪归到迦勒底的居民。'),
('CUV', '耶利米书', 24, 51, 36, '所以，耶和华如此说：我必为你伸冤，为你报仇；我必使巴比伦的海枯竭，使他的泉源干涸。'),
('CUV', '耶利米书', 24, 51, 37, '巴比伦必成为乱堆，为野狗的住处，令人惊骇、嗤笑，并且无人居住。'),
('CUV', '耶利米书', 24, 51, 38, '他们要像少壮狮子咆哮，像小狮子吼叫。'),
('CUV', '耶利米书', 24, 51, 39, '他们火热的时候，我必为他们设摆酒席，使他们沉醉，好叫他们快乐，睡了长觉，永不醒起。这是耶和华说的。'),
('CUV', '耶利米书', 24, 51, 40, '我必使他们像羊羔、像公绵羊和公山羊下到宰杀之地。'),
('CUV', '耶利米书', 24, 51, 41, '示沙克（就是巴比伦）何竟被攻取，天下所称赞的何竟被占据？巴比伦在列国中何竟变为荒场？'),
('CUV', '耶利米书', 24, 51, 42, '海水涨起，漫过巴比伦；他被许多海浪遮盖。'),
('CUV', '耶利米书', 24, 51, 43, '他的城邑变为荒场、旱地、沙漠，无人居住，无人经过之地。'),
('CUV', '耶利米书', 24, 51, 44, '我必刑罚巴比伦的彼勒，使他吐出所吞的。万民必不再流归他那里；巴比伦的城墙也必坍塌了。'),
('CUV', '耶利米书', 24, 51, 45, '我的民哪，你们要从其中出去！各人拯救自己，躲避耶和华的烈怒。'),
('CUV', '耶利米书', 24, 51, 46, '你们不要心惊胆怯，也不要因境内所听见的风声惧怕；因为这年有风声传来；那年也有风声传来，境内有强暴的事，官长攻击官长。'),
('CUV', '耶利米书', 24, 51, 47, '日子将到，我必刑罚巴比伦雕刻的偶像。他全地必然抱愧；他被杀的人必在其中仆倒。'),
('CUV', '耶利米书', 24, 51, 48, '那时，天地和其中所有的，必因巴比伦欢呼，因为行毁灭的要从北方来到他那里。这是耶和华说的。'),
('CUV', '耶利米书', 24, 51, 49, '巴比伦怎样使以色列被杀的人仆倒，照样他全地被杀的人也必在巴比伦仆倒。'),
('CUV', '耶利米书', 24, 51, 50, '你们躲避刀剑的要快走，不要站住！要在远方记念耶和华，心中追想耶路撒冷。'),
('CUV', '耶利米书', 24, 51, 51, '我们听见辱骂就蒙羞，满面惭愧，因为外邦人进入耶和华殿的圣所。'),
('CUV', '耶利米书', 24, 51, 52, '耶和华说：日子将到，我必刑罚巴比伦雕刻的偶像，通国受伤的人必唉哼。'),
('CUV', '耶利米书', 24, 51, 53, '巴比伦虽升到天上，虽使他坚固的高处更坚固，还有行毁灭的从我这里到他那里。这是耶和华说的。'),
('CUV', '耶利米书', 24, 51, 54, '有哀号的声音从巴比伦出来；有大毁灭的响声从迦勒底人之地发出。'),
('CUV', '耶利米书', 24, 51, 55, '因耶和华使巴比伦变为荒场，使其中的大声灭绝。仇敌仿佛众水，波浪匉訇，响声已经发出。'),
('CUV', '耶利米书', 24, 51, 56, '这是行毁灭的临到巴比伦。巴比伦的勇士被捉住，他们的弓折断了；因为耶和华是施行报应的神，必定施行报应。'),
('CUV', '耶利米书', 24, 51, 57, '君王─名为万军之耶和华的说：我必使巴比伦的首领、智慧人、省长、副省长，和勇士都沉醉，使他们睡了长觉，永不醒起。'),
('CUV', '耶利米书', 24, 51, 58, '万军之耶和华如此说：巴比伦宽阔的城墙必全然倾倒；他高大的城门必被火焚烧。众民所劳碌的必致虚空；列国所劳碌的被火焚烧，他们都必困乏。'),
('CUV', '耶利米书', 24, 51, 59, '犹大王西底家在位第四年，上巴比伦去的时候，玛西雅的孙子、尼利亚的儿子西莱雅与王同去（西莱雅是王宫的大臣），先知耶利米有话吩咐他。'),
('CUV', '耶利米书', 24, 51, 60, '耶利米将一切要临到巴比伦的灾祸，就是论到巴比伦的一切话，写在书上。'),
('CUV', '耶利米书', 24, 51, 61, '耶利米对西莱雅说：你到了巴比伦务要念这书上的话；'),
('CUV', '耶利米书', 24, 51, 62, '又说：耶和华啊，你曾论到这地方说：要剪除，甚至连人带牲畜没有在这里居住的，必永远荒凉。'),
('CUV', '耶利米书', 24, 51, 63, '你念完了这书，就把一块石头拴在书上，扔在伯拉河中，'),
('CUV', '耶利米书', 24, 51, 64, '说：巴比伦因耶和华所要降与他的灾祸，必如此沉下去，不再兴起，人民也必困乏。耶利米的话到此为止。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米书', 24, 52, 1, '西底家登基的时候年二十一岁，在耶路撒冷作王十一年。他母亲名叫哈慕他，是立拿人耶利米的女儿。'),
('CUV', '耶利米书', 24, 52, 2, '西底家行耶和华眼中看为恶的事，是照约雅敬一切所行的。'),
('CUV', '耶利米书', 24, 52, 3, '因此耶和华的怒气在耶路撒冷和犹大发作，以致将人民从自己的面前赶出。'),
('CUV', '耶利米书', 24, 52, 4, '西底家背叛巴比伦王。他作王第九年十月初十日，巴比伦王尼布甲尼撒率领全军来攻击耶路撒冷，对城安营，四围筑垒攻城。'),
('CUV', '耶利米书', 24, 52, 5, '于是城被围困直到西底家王十一年。'),
('CUV', '耶利米书', 24, 52, 6, '四月初九日，城里有大饥荒，甚至百姓都没有粮食。'),
('CUV', '耶利米书', 24, 52, 7, '城被攻破，一切兵丁就在夜间从靠近王园两城中间的门，出城逃跑；迦勒底人正在四围攻城。他们就往亚拉巴逃去。'),
('CUV', '耶利米书', 24, 52, 8, '迦勒底的军队追赶西底家王，在耶利哥的平原追上他。他的全军都离开他四散了。'),
('CUV', '耶利米书', 24, 52, 9, '迦勒底人就拿住王，带他到在哈马地利比拉的巴比伦王那里；巴比伦王便审判他。'),
('CUV', '耶利米书', 24, 52, 10, '巴比伦王在西底家眼前杀了他的众子，又在利比拉杀了犹大的一切首领，'),
('CUV', '耶利米书', 24, 52, 11, '并且剜了西底家的眼睛，用铜链锁著他，带到巴比伦去，将他囚在监里，直到他死的日子。'),
('CUV', '耶利米书', 24, 52, 12, '巴比伦王尼布甲尼撒十九年五月初十日，在巴比伦王面前侍立的护卫长尼布撒拉旦进入耶路撒冷，'),
('CUV', '耶利米书', 24, 52, 13, '用火焚烧耶和华的殿和王宫，又焚烧耶路撒冷的房屋，就是各大户家的房屋。'),
('CUV', '耶利米书', 24, 52, 14, '跟从护卫长迦勒底的全军就拆毁耶路撒冷四围的城墙。'),
('CUV', '耶利米书', 24, 52, 15, '那时护卫长尼布撒拉旦将民中最穷的和城里所剩下的百姓，并已经投降巴比伦王的人，以及大众所剩下的人，都掳去了。'),
('CUV', '耶利米书', 24, 52, 16, '但护卫长尼布撒拉旦留下些民中最穷的，使他们修理葡萄园，耕种田地。'),
('CUV', '耶利米书', 24, 52, 17, '耶和华殿的铜柱并殿内的盆座和铜海，迦勒底人都打碎了，将那铜运到巴比伦去了，'),
('CUV', '耶利米书', 24, 52, 18, '又带去锅、铲子、蜡剪、盘子、调羹，并所用的一切铜器、'),
('CUV', '耶利米书', 24, 52, 19, '杯、火鼎、碗、盆、灯台、调羹、爵，无论金的银的，护卫长也都带去了。'),
('CUV', '耶利米书', 24, 52, 20, '所罗门为耶和华殿所造的两根铜柱、一个铜海，并座下的十二只铜牛，这一切的铜多得无法可称。'),
('CUV', '耶利米书', 24, 52, 21, '这一根柱子高十八肘，厚四指，是空的，围十二肘。'),
('CUV', '耶利米书', 24, 52, 22, '柱上有铜顶，高五肘；铜顶的周围有网子和石榴，都是铜的。那一根柱子照此一样，也有石榴。'),
('CUV', '耶利米书', 24, 52, 23, '柱子四面有九十六个石榴，在网子周围，共有一百石榴。'),
('CUV', '耶利米书', 24, 52, 24, '护卫长拿住大祭司西莱雅、副祭司西番亚，和三个把门的，'),
('CUV', '耶利米书', 24, 52, 25, '又从城中拿住一个管理兵丁的官（或译：太监），并在城里所遇常见王面的七个人和检点国民军长的书记，以及城里所遇见的国民六十个人。'),
('CUV', '耶利米书', 24, 52, 26, '护卫长尼布撒拉旦将这些人带到利比拉的巴比伦王那里。'),
('CUV', '耶利米书', 24, 52, 27, '巴比伦王就把他们击杀在哈马地的利比拉。这样，犹大人被掳去离开本地。'),
('CUV', '耶利米书', 24, 52, 28, '尼布甲尼撒所掳的民数记在下面：在他第七年掳去犹大人三千零二十三名；'),
('CUV', '耶利米书', 24, 52, 29, '尼布甲尼撒十八年从耶路撒冷掳去八百三十二人；'),
('CUV', '耶利米书', 24, 52, 30, '尼布甲尼撒二十三年，护卫长尼布撒拉旦掳去犹大人七百四十五名；共有四千六百人。'),
('CUV', '耶利米书', 24, 52, 31, '犹大王约雅斤被掳后三十七年，巴比伦王以未米罗达元年十二月二十五日，使犹大王约雅斤抬头，提他出监，'),
('CUV', '耶利米书', 24, 52, 32, '又对他说恩言，使他的位高过与他一同在巴比伦众王的位，'),
('CUV', '耶利米书', 24, 52, 33, '给他脱了囚服。他终身在巴比伦王面前吃饭。'),
('CUV', '耶利米书', 24, 52, 34, '巴比伦王赐他所需用的食物，日日赐他一分，终身是这样，直到他死的日子。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米哀歌', 25, 1, 1, '先前满有人民的城，现在何竟独坐！先前在列国中为大的，现在竟如寡妇；先前在诸省中为王后的，现在成为进贡的。'),
('CUV', '耶利米哀歌', 25, 1, 2, '她夜间痛哭，泪流满腮；在一切所亲爱的中间没有一个安慰她的。她的朋友都以诡诈待她，成为她的仇敌。'),
('CUV', '耶利米哀歌', 25, 1, 3, '犹大因遭遇苦难，又因多服劳苦就迁到外邦。她住在列国中，寻不著安息；追逼她的都在狭窄之地将她追上。'),
('CUV', '耶利米哀歌', 25, 1, 4, '锡安的路径因无人来守圣节就悲伤；她的城门凄凉；她的祭司叹息；她的处女受艰难，自己也愁苦。'),
('CUV', '耶利米哀歌', 25, 1, 5, '她的敌人为首；她的仇敌亨通；因耶和华为她许多的罪过使她受苦；她的孩童被敌人掳去。'),
('CUV', '耶利米哀歌', 25, 1, 6, '锡安城（原文是女子；下同）的威荣全都失去。她的首领像找不著草场的鹿；在追赶的人前无力行走。'),
('CUV', '耶利米哀歌', 25, 1, 7, '耶路撒冷在困苦窘迫之时，就追想古时一切的乐境。她百姓落在敌人手中，无人救济；敌人看见，就因她的荒凉嗤笑。'),
('CUV', '耶利米哀歌', 25, 1, 8, '耶路撒冷大大犯罪，所以成为不洁之物；素来尊敬她的，见她赤露就都藐视她；她自己也叹息退后。'),
('CUV', '耶利米哀歌', 25, 1, 9, '她的污秽是在衣襟上；她不思想自己的结局，所以非常地败落，无人安慰她。她说：耶和华啊，求你看我的苦难，因为仇敌夸大。'),
('CUV', '耶利米哀歌', 25, 1, 10, '敌人伸手，夺取她的美物；她眼见外邦人进入她的圣所─论这外邦人，你曾吩咐不可入你的会中。'),
('CUV', '耶利米哀歌', 25, 1, 11, '她的民都叹息，寻求食物；他们用美物换粮食，要救性命。他们说：耶和华啊，求你观看，因为我甚是卑贱。'),
('CUV', '耶利米哀歌', 25, 1, 12, '你们一切过路的人哪，这事你们不介意么？你们要观看：有像这临到我的痛苦没有─就是耶和华在他发烈怒的日子使我所受的苦？'),
('CUV', '耶利米哀歌', 25, 1, 13, '他从高天使火进入我的骨头，克制了我；他铺下网罗，绊我的脚，使我转回；他使我终日凄凉发昏。'),
('CUV', '耶利米哀歌', 25, 1, 14, '我罪过的轭是他手所绑的，犹如轭绳缚在我颈项上；他使我的力量衰败。主将我交在我所不能敌挡的人手中。'),
('CUV', '耶利米哀歌', 25, 1, 15, '主轻弃我中间的一切勇士，招聚多人（原文是大会）攻击我，要压碎我的少年人。主将犹大居民踹下，像在酒醡中一样。'),
('CUV', '耶利米哀歌', 25, 1, 16, '我因这些事哭泣；我眼泪汪汪；因为那当安慰我、救我性命的，离我甚远。我的儿女孤苦，因为仇敌得了胜。'),
('CUV', '耶利米哀歌', 25, 1, 17, '锡安举手，无人安慰。耶和华论雅各已经出令，使四围的人作他仇敌；耶路撒冷在他们中间像不洁之物。'),
('CUV', '耶利米哀歌', 25, 1, 18, '耶和华是公义的！他这样待我，是因我违背他的命令。众民哪，请听我的话，看我的痛苦；我的处女和少年人都被掳去。'),
('CUV', '耶利米哀歌', 25, 1, 19, '我招呼我所亲爱的，他们却愚弄我。我的祭司和长老正寻求食物、救性命的时候，就在城中绝气。'),
('CUV', '耶利米哀歌', 25, 1, 20, '耶和华啊，求你观看，因为我在急难中。我心肠扰乱；我心在我里面翻转，因我大大悖逆。在外，刀剑使人丧子；在家，犹如死亡。'),
('CUV', '耶利米哀歌', 25, 1, 21, '听见我叹息的有人；安慰我的却无人！我的仇敌都听见我所遭的患难；因你做这事，他们都喜乐。你必使你报告的日子来到，他们就像我一样。'),
('CUV', '耶利米哀歌', 25, 1, 22, '愿他们的恶行都呈在你面前；你怎样因我的一切罪过待我，求你照样待他们；因我叹息甚多，心中发昏。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米哀歌', 25, 2, 1, '主何竟发怒，使黑云遮蔽锡安城！他将以色列的华美从天扔在地上；在他发怒的日子并不记念自己的脚凳。'),
('CUV', '耶利米哀歌', 25, 2, 2, '主吞灭雅各一切的住处，并不顾惜。他发怒倾覆犹大民的保障，使这保障坍倒在地；他辱没这国和其中的首领。'),
('CUV', '耶利米哀歌', 25, 2, 3, '他发烈怒，把以色列的角全然砍断，在仇敌面前收回右手。他像火焰四围吞灭，将雅各烧毁。'),
('CUV', '耶利米哀歌', 25, 2, 4, '他张弓好像仇敌；他站著举起右手，如同敌人将悦人眼目的，尽行杀戮。在锡安百姓的帐棚上倒出他的忿怒，像火一样。'),
('CUV', '耶利米哀歌', 25, 2, 5, '主如仇敌吞灭以色列和锡安的一切宫殿，拆毁百姓的保障；在犹大民中加增悲伤哭号。'),
('CUV', '耶利米哀歌', 25, 2, 6, '他强取自己的帐幕，好像是园中的窝棚，毁坏他的聚会之处。耶和华使圣节和安息日在锡安都被忘记，又在怒气的愤恨中藐视君王和祭司。'),
('CUV', '耶利米哀歌', 25, 2, 7, '耶和华丢弃自己的祭坛，憎恶自己的圣所，将宫殿的墙垣交付仇敌。他们在耶和华的殿中喧嚷，像在圣会之日一样。'),
('CUV', '耶利米哀歌', 25, 2, 8, '耶和华定意拆毁锡安的城墙；他拉了准绳，不将手收回，定要毁灭。他使外郭和城墙都悲哀，一同衰败。'),
('CUV', '耶利米哀歌', 25, 2, 9, '锡安的门都陷入地内；主将她的门闩毁坏，折断。她的君王和首领落在没有律法的列国中；她的先知不得见耶和华的异象。'),
('CUV', '耶利米哀歌', 25, 2, 10, '锡安城的长老坐在地上默默无声；他们扬起尘土落在头上，腰束麻布；耶路撒冷的处女垂头至地。'),
('CUV', '耶利米哀歌', 25, 2, 11, '我眼中流泪，以致失明，我的心肠扰乱，肝胆涂地，都因我众民遭毁灭，又因孩童和吃奶的在城内街上发昏。'),
('CUV', '耶利米哀歌', 25, 2, 12, '那时，他们在城内街上发昏，好像受伤的，在母亲的怀里，将要丧命；对母亲说：谷、酒在哪里呢？'),
('CUV', '耶利米哀歌', 25, 2, 13, '耶路撒冷的民哪，我可用甚么向你证明呢？我可用甚么与你相比呢？锡安的民哪，我可拿甚么和你比较，好安慰你呢？因为你的裂口大如海，谁能医治你呢？'),
('CUV', '耶利米哀歌', 25, 2, 14, '你的先知为你见虚假和愚昧的异象，并没有显露你的罪孽，使你被掳的归回；却为你见虚假的默示和使你被赶出本境的缘故。'),
('CUV', '耶利米哀歌', 25, 2, 15, '凡过路的都向你拍掌。他们向耶路撒冷城嗤笑，摇头，说：难道人所称为全美的，称为全地所喜悦的，就是这城吗？'),
('CUV', '耶利米哀歌', 25, 2, 16, '你的仇敌都向你大大张口；他们嗤笑，又切齿说：我们吞灭她。这真是我们所盼望的日子临到了！我们亲眼看见了！'),
('CUV', '耶利米哀歌', 25, 2, 17, '耶和华成就了他所定的，应验了他古时所命定的。他倾覆了，并不顾惜，使你的仇敌向你夸耀；使你敌人的角也被高举。'),
('CUV', '耶利米哀歌', 25, 2, 18, '锡安民的心哀求主。锡安的城墙啊，愿你流泪如河，昼夜不息；愿你眼中的瞳人泪流不止。'),
('CUV', '耶利米哀歌', 25, 2, 19, '夜间，每逢交更的时候要起来呼喊，在主面前倾心如水。你的孩童在各市口上受饿发昏；你要为他们的性命向主举手祷告。'),
('CUV', '耶利米哀歌', 25, 2, 20, '耶和华啊，求你观看！见你向谁这样行？妇人岂可吃自己所生育手里所摇弄的婴孩吗？祭司和先知岂可在主的圣所中被杀戮吗？'),
('CUV', '耶利米哀歌', 25, 2, 21, '少年人和老年人都在街上躺卧；我的处女和壮丁都倒在刀下；你发怒的日子杀死他们。你杀了，并不顾惜。'),
('CUV', '耶利米哀歌', 25, 2, 22, '你招聚四围惊吓我的，像在大会的日子招聚人一样。耶和华发怒的日子，无人逃脱，无人存留。我所摇弄所养育的婴孩，仇敌都杀净了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米哀歌', 25, 3, 1, '我是因耶和华忿怒的杖，遭遇困苦的人。'),
('CUV', '耶利米哀歌', 25, 3, 2, '他引导我，使我行在黑暗中，不行在光明里。'),
('CUV', '耶利米哀歌', 25, 3, 3, '他真是终日再三反手攻击我。'),
('CUV', '耶利米哀歌', 25, 3, 4, '他使我的皮肉枯干；他折断（或译：压伤）我的骨头。'),
('CUV', '耶利米哀歌', 25, 3, 5, '他筑垒攻击我，用苦楚（原文是苦胆）和艰难围困我。'),
('CUV', '耶利米哀歌', 25, 3, 6, '他使我住在幽暗之处，像死了许久的人一样。'),
('CUV', '耶利米哀歌', 25, 3, 7, '他用篱笆围住我，使我不能出去；他使我的铜炼沉重。'),
('CUV', '耶利米哀歌', 25, 3, 8, '我哀号求救；他使我的祷告不得上达。'),
('CUV', '耶利米哀歌', 25, 3, 9, '他用凿过的石头挡住我的道；他使我的路弯曲。'),
('CUV', '耶利米哀歌', 25, 3, 10, '他向我如熊埋伏，如狮子在隐密处。'),
('CUV', '耶利米哀歌', 25, 3, 11, '他使我转离正路，将我撕碎，使我凄凉。'),
('CUV', '耶利米哀歌', 25, 3, 12, '他张弓将我当作箭靶子。'),
('CUV', '耶利米哀歌', 25, 3, 13, '他把箭袋中的箭射入我的肺腑。'),
('CUV', '耶利米哀歌', 25, 3, 14, '我成了众民的笑话；他们终日以我为歌曲。'),
('CUV', '耶利米哀歌', 25, 3, 15, '他用苦楚充满我，使我饱用茵𫈟。'),
('CUV', '耶利米哀歌', 25, 3, 16, '他又用沙石碜断我的牙，用灰尘将我蒙蔽。'),
('CUV', '耶利米哀歌', 25, 3, 17, '你使我远离平安，我忘记好处。'),
('CUV', '耶利米哀歌', 25, 3, 18, '我就说：我的力量衰败；我在耶和华那里毫无指望！'),
('CUV', '耶利米哀歌', 25, 3, 19, '耶和华啊，求你记念我如茵𫈟和苦胆的困苦窘迫。'),
('CUV', '耶利米哀歌', 25, 3, 20, '我心想念这些，就在里面忧闷。'),
('CUV', '耶利米哀歌', 25, 3, 21, '我想起这事，心里就有指望。'),
('CUV', '耶利米哀歌', 25, 3, 22, '我们不致消灭，是出于耶和华诸般的慈爱；是因他的怜悯不致断绝。'),
('CUV', '耶利米哀歌', 25, 3, 23, '每早晨，这都是新的；你的诚实极其广大！'),
('CUV', '耶利米哀歌', 25, 3, 24, '我心里说：耶和华是我的分，因此，我要仰望他。'),
('CUV', '耶利米哀歌', 25, 3, 25, '凡等候耶和华，心里寻求他的，耶和华必施恩给他。'),
('CUV', '耶利米哀歌', 25, 3, 26, '人仰望耶和华，静默等候他的救恩，这原是好的。'),
('CUV', '耶利米哀歌', 25, 3, 27, '人在幼年负轭，这原是好的。'),
('CUV', '耶利米哀歌', 25, 3, 28, '他当独坐无言，因为这是耶和华加在他身上的。'),
('CUV', '耶利米哀歌', 25, 3, 29, '他当口贴尘埃，或者有指望。'),
('CUV', '耶利米哀歌', 25, 3, 30, '他当由人打他的腮颊，要满受凌辱。'),
('CUV', '耶利米哀歌', 25, 3, 31, '因为主必不永远丢弃人。'),
('CUV', '耶利米哀歌', 25, 3, 32, '主虽使人忧愁，还要照他诸般的慈爱发怜悯。'),
('CUV', '耶利米哀歌', 25, 3, 33, '因他并不甘心使人受苦，使人忧愁。'),
('CUV', '耶利米哀歌', 25, 3, 34, '人将世上被囚的踹（原文是压）在脚下，'),
('CUV', '耶利米哀歌', 25, 3, 35, '或在至高者面前屈枉人，'),
('CUV', '耶利米哀歌', 25, 3, 36, '或在人的讼事上颠倒是非，这都是主看不上的。'),
('CUV', '耶利米哀歌', 25, 3, 37, '除非主命定，谁能说成就成呢？'),
('CUV', '耶利米哀歌', 25, 3, 38, '祸福不都出于至高者的口吗？'),
('CUV', '耶利米哀歌', 25, 3, 39, '活人因自己的罪受罚，为何发怨言呢？'),
('CUV', '耶利米哀歌', 25, 3, 40, '我们当深深考察自己的行为，再归向耶和华。'),
('CUV', '耶利米哀歌', 25, 3, 41, '我们当诚心向天上的神举手祷告。'),
('CUV', '耶利米哀歌', 25, 3, 42, '我们犯罪背逆，你并不赦免。'),
('CUV', '耶利米哀歌', 25, 3, 43, '你自被怒气遮蔽，追赶我们；你施行杀戮，并不顾惜。'),
('CUV', '耶利米哀歌', 25, 3, 44, '你以黑云遮蔽自己，以致祷告不得透入。'),
('CUV', '耶利米哀歌', 25, 3, 45, '你使我们在万民中成为污秽和渣滓。'),
('CUV', '耶利米哀歌', 25, 3, 46, '我们的仇敌都向我们大大张口。'),
('CUV', '耶利米哀歌', 25, 3, 47, '恐惧和陷坑，残害和毁灭，都临近我们。'),
('CUV', '耶利米哀歌', 25, 3, 48, '因我众民遭的毁灭，我就眼泪下流如河。'),
('CUV', '耶利米哀歌', 25, 3, 49, '我的眼多多流泪，总不止息，'),
('CUV', '耶利米哀歌', 25, 3, 50, '直等耶和华垂顾，从天观看。'),
('CUV', '耶利米哀歌', 25, 3, 51, '因我本城的众民，我的眼，使我的心伤痛。'),
('CUV', '耶利米哀歌', 25, 3, 52, '无故与我为仇的追逼我，像追雀鸟一样。'),
('CUV', '耶利米哀歌', 25, 3, 53, '他们使我的命在牢狱中断绝，并将一块石头抛在我身上。'),
('CUV', '耶利米哀歌', 25, 3, 54, '众水流过我头，我说：我命断绝了！'),
('CUV', '耶利米哀歌', 25, 3, 55, '耶和华啊，我从深牢中求告你的名。'),
('CUV', '耶利米哀歌', 25, 3, 56, '你曾听见我的声音；我求你解救，你不要掩耳不听。'),
('CUV', '耶利米哀歌', 25, 3, 57, '我求告你的日子，你临近我，说：不要惧怕！'),
('CUV', '耶利米哀歌', 25, 3, 58, '主啊，你伸明了我的冤；你救赎了我的命。'),
('CUV', '耶利米哀歌', 25, 3, 59, '耶和华啊，你见了我受的委屈；求你为我伸冤。'),
('CUV', '耶利米哀歌', 25, 3, 60, '他们仇恨我，谋害我，你都看见了。'),
('CUV', '耶利米哀歌', 25, 3, 61, '耶和华啊，你听见他们辱骂我的话，知道他们向我所设的计，'),
('CUV', '耶利米哀歌', 25, 3, 62, '并那些起来攻击我的人口中所说的话，以及终日向我所设的计谋。'),
('CUV', '耶利米哀歌', 25, 3, 63, '求你观看，他们坐下，起来，都以我为歌曲。'),
('CUV', '耶利米哀歌', 25, 3, 64, '耶和华啊，你要按著他们手所做的向他们施行报应。'),
('CUV', '耶利米哀歌', 25, 3, 65, '你要使他们心里刚硬，使你的咒诅临到他们。'),
('CUV', '耶利米哀歌', 25, 3, 66, '你要发怒追赶他们，从耶和华的天下除灭他们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米哀歌', 25, 4, 1, '黄金何其失光！纯金何其变色！圣所的石头倒在各市口上。'),
('CUV', '耶利米哀歌', 25, 4, 2, '锡安宝贵的众子好比精金，现在何竟算为窑匠手所做的瓦瓶？'),
('CUV', '耶利米哀歌', 25, 4, 3, '野狗尚且把奶乳哺其子，我民的妇人倒成为残忍，好像旷野的鸵鸟一般。'),
('CUV', '耶利米哀歌', 25, 4, 4, '吃奶孩子的舌头因干渴贴住上膛；孩童求饼，无人擘给他们。'),
('CUV', '耶利米哀歌', 25, 4, 5, '素来吃美好食物的，现今在街上变为孤寒；素来卧朱红褥子的，现今躺卧粪堆。'),
('CUV', '耶利米哀歌', 25, 4, 6, '都因我众民的罪孽比所多玛的罪还大；所多玛虽然无人加手于他，还是转眼之间被倾覆。'),
('CUV', '耶利米哀歌', 25, 4, 7, '锡安的贵胄素来比雪纯净，比奶更白；他们的身体比红宝玉（或译：珊瑚）更红，像光润的蓝宝石一样。'),
('CUV', '耶利米哀歌', 25, 4, 8, '现在他们的面貌比煤炭更黑，以致在街上无人认识；他们的皮肤紧贴骨头，枯干如同槁木。'),
('CUV', '耶利米哀歌', 25, 4, 9, '饿死的不如被刀杀的，因为这是缺了田间的土产，就身体衰弱，渐渐消灭。'),
('CUV', '耶利米哀歌', 25, 4, 10, '慈悲的妇人，当我众民被毁灭的时候，亲手煮自己的儿女作为食物。'),
('CUV', '耶利米哀歌', 25, 4, 11, '耶和华发怒成就他所定的，倒出他的烈怒；在锡安使火著起，烧毁锡安的根基。'),
('CUV', '耶利米哀歌', 25, 4, 12, '地上的君王和世上的居民都不信敌人和仇敌能进耶路撒冷的城门。'),
('CUV', '耶利米哀歌', 25, 4, 13, '这都因他先知的罪恶和祭司的罪孽；他们在城中流了义人的血。'),
('CUV', '耶利米哀歌', 25, 4, 14, '他们在街上如瞎子乱走，又被血玷污，以致人不能摸他们的衣服。'),
('CUV', '耶利米哀歌', 25, 4, 15, '人向他们喊著说：！不洁净的，躲开，躲开！不要挨近我！他们逃走飘流的时候，列国中有人说：他们不可仍在这里寄居。'),
('CUV', '耶利米哀歌', 25, 4, 16, '耶和华发怒，将他们分散，不再眷顾他们；人不重看祭司，也不厚待长老。'),
('CUV', '耶利米哀歌', 25, 4, 17, '我们仰望人来帮助，以致眼目失明，还是枉然；我们所盼望的，竟盼望一个不能救人的国！'),
('CUV', '耶利米哀歌', 25, 4, 18, '仇敌追赶我们的脚步像打猎的，以致我们不敢在自己的街上行走。我们的结局临近；我们的日子满足；我们的结局来到了。'),
('CUV', '耶利米哀歌', 25, 4, 19, '追赶我们的比空中的鹰更快；他们在山上追逼我们，在旷野埋伏，等候我们。'),
('CUV', '耶利米哀歌', 25, 4, 20, '耶和华的受膏者好比我们鼻中的气，在他们的坑中被捉住；我们曾论到他说：我们必在他荫下，在列国中存活。'),
('CUV', '耶利米哀歌', 25, 4, 21, '住乌斯地的以东民哪，只管欢喜快乐；苦杯也必传到你那里；你必喝醉，以致露体。'),
('CUV', '耶利米哀歌', 25, 4, 22, '锡安的民哪，你罪孽的刑罚受足了，耶和华必不使你再被掳去。以东的民哪，他必追讨你的罪孽，显露你的罪恶。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '耶利米哀歌', 25, 5, 1, '耶和华啊，求你记念我们所遭遇的事，观看我们所受的凌辱。'),
('CUV', '耶利米哀歌', 25, 5, 2, '我们的产业归与外邦人；我们的房屋归与外路人。'),
('CUV', '耶利米哀歌', 25, 5, 3, '我们是无父的孤儿；我们的母亲好像寡妇。'),
('CUV', '耶利米哀歌', 25, 5, 4, '我们出钱才得水喝；我们的柴是人卖给我们的。'),
('CUV', '耶利米哀歌', 25, 5, 5, '追赶我们的，到了我们的颈项上；我们疲乏不得歇息。'),
('CUV', '耶利米哀歌', 25, 5, 6, '我们投降埃及人和亚述人，为要得粮吃饱。'),
('CUV', '耶利米哀歌', 25, 5, 7, '我们列祖犯罪，而今不在了；我们担当他们的罪孽。'),
('CUV', '耶利米哀歌', 25, 5, 8, '奴仆辖制我们，无人救我们脱离他们的手。'),
('CUV', '耶利米哀歌', 25, 5, 9, '因为旷野的刀剑，我们冒著险才得粮食。'),
('CUV', '耶利米哀歌', 25, 5, 10, '因饥饿燥热，我们的皮肤就黑如炉。'),
('CUV', '耶利米哀歌', 25, 5, 11, '敌人在锡安玷污妇人，在犹大的城邑玷污处女。'),
('CUV', '耶利米哀歌', 25, 5, 12, '他们吊起首领的手，也不尊敬老人的面。'),
('CUV', '耶利米哀歌', 25, 5, 13, '少年人扛磨石，孩童背木柴，都绊跌了。'),
('CUV', '耶利米哀歌', 25, 5, 14, '老年人在城门口断绝；少年人不再作乐。'),
('CUV', '耶利米哀歌', 25, 5, 15, '我们心中的快乐止息，跳舞变为悲哀。'),
('CUV', '耶利米哀歌', 25, 5, 16, '冠冕从我们的头上落下；我们犯罪了，我们有祸了！'),
('CUV', '耶利米哀歌', 25, 5, 17, '这些事我们心里发昏，我们的眼睛昏花。'),
('CUV', '耶利米哀歌', 25, 5, 18, '锡安山荒凉，野狗（或译：狐狸）行在其上。'),
('CUV', '耶利米哀歌', 25, 5, 19, '耶和华啊，你存到永远；你的宝座存到万代。'),
('CUV', '耶利米哀歌', 25, 5, 20, '你为何永远忘记我们？为何许久离弃我们？'),
('CUV', '耶利米哀歌', 25, 5, 21, '耶和华啊，求你使我们向你回转，我们便得回转。求你复新我们的日子，像古时一样。'),
('CUV', '耶利米哀歌', 25, 5, 22, '你竟全然弃绝我们，向我们大发烈怒？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 1, 1, '当三十年四月初五日，以西结（原文是我）在迦巴鲁河边被掳的人中，天就开了，得见神的异象。'),
('CUV', '以西结书', 26, 1, 2, '正是约雅斤王被掳去第五年四月初五日，'),
('CUV', '以西结书', 26, 1, 3, '在迦勒底人之地、迦巴鲁河边，耶和华的话特特临到布西的儿子祭司以西结；耶和华的灵（原文是手）降在他身上。'),
('CUV', '以西结书', 26, 1, 4, '我观看，见狂风从北方刮来，随著有一朵包括闪烁火的大云，周围有光辉；从其中的火内发出好像光耀的精金；'),
('CUV', '以西结书', 26, 1, 5, '又从其中显出四个活物的形像来。他们的形状是这样：有人的形像，'),
('CUV', '以西结书', 26, 1, 6, '各有四个脸面，四个翅膀。'),
('CUV', '以西结书', 26, 1, 7, '他们的腿是直的，脚掌好像牛犊之蹄，都灿烂如光明的铜。'),
('CUV', '以西结书', 26, 1, 8, '在四面的翅膀以下有人的手。这四个活物的脸和翅膀乃是这样：'),
('CUV', '以西结书', 26, 1, 9, '翅膀彼此相接，行走并不转身，俱各直往前行。'),
('CUV', '以西结书', 26, 1, 10, '至于脸的形像：前面各有人的脸，右面各有狮子的脸，左面各有牛的脸，后面各有鹰的脸。'),
('CUV', '以西结书', 26, 1, 11, '各展开上边的两个翅膀相接，各以下边的两个翅膀遮体。'),
('CUV', '以西结书', 26, 1, 12, '他们俱各直往前行。灵往哪里去，他们就往那里去，行走并不转身。'),
('CUV', '以西结书', 26, 1, 13, '至于四活物的形像，就如烧著火炭的形状，又如火把的形状。火在四活物中间上去下来，这火有光辉，从火中发出闪电。'),
('CUV', '以西结书', 26, 1, 14, '这活物往来奔走，好像电光一闪。'),
('CUV', '以西结书', 26, 1, 15, '我正观看活物的时候，见活物的脸旁各有一轮在地上。'),
('CUV', '以西结书', 26, 1, 16, '轮的形状和颜色（原文是作法）好像水苍玉。四轮都是一个样式，形状和作法好像轮中套轮。'),
('CUV', '以西结书', 26, 1, 17, '轮行走的时候，向四方都能直行，并不掉转。'),
('CUV', '以西结书', 26, 1, 18, '至于轮辋，高而可畏；四个轮辋周围满有眼睛。'),
('CUV', '以西结书', 26, 1, 19, '活物行走，轮也在旁边行走；活物从地上升，轮也都上升。'),
('CUV', '以西结书', 26, 1, 20, '灵往哪里去，活物就往那里去；活物上升，轮也在活物旁边上升，因为活物的灵在轮中。'),
('CUV', '以西结书', 26, 1, 21, '那些行走，这些也行走；那些站住，这些也站住；那些从地上升，轮也在旁边上升，因为活物的灵在轮中。'),
('CUV', '以西结书', 26, 1, 22, '活物的头以上有穹苍的形像，看著像可畏的水晶，铺张在活物的头以上。'),
('CUV', '以西结书', 26, 1, 23, '穹苍以下，活物的翅膀直张，彼此相对；每活物有两个翅膀遮体。'),
('CUV', '以西结书', 26, 1, 24, '活物行走的时候，我听见翅膀的响声，像大水的声音，像全能者的声音，也像军队哄嚷的声音。活物站住的时候，便将翅膀垂下。'),
('CUV', '以西结书', 26, 1, 25, '在他们头以上的穹苍之上有声音。他们站住的时候，便将翅膀垂下。'),
('CUV', '以西结书', 26, 1, 26, '在他们头以上的穹苍之上有宝座的形像，仿佛蓝宝石；在宝座形像以上有仿佛人的形状。'),
('CUV', '以西结书', 26, 1, 27, '我见从他腰以上有仿佛光耀的精金，周围都有火的形状，又见从他腰以下有仿佛火的形状，周围也有光辉。'),
('CUV', '以西结书', 26, 1, 28, '下雨的日子，云中虹的形状怎样，周围光辉的形状也是怎样。这就是耶和华荣耀的形像。我一看见就俯伏在地，又听见一位说话的声音。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 2, 1, '他对我说：人子啊，你站起来，我要和你说话。'),
('CUV', '以西结书', 26, 2, 2, '他对我说话的时候，灵就进入我里面，使我站起来，我便听见那位对我说话的声音。'),
('CUV', '以西结书', 26, 2, 3, '他对我说：人子啊，我差你往悖逆的国民以色列人那里去。他们是悖逆我的，他们和他们的列祖违背我，直到今日。'),
('CUV', '以西结书', 26, 2, 4, '这众子面无羞耻，心里刚硬。我差你往他们那里去，你要对他们说：主耶和华如此说。'),
('CUV', '以西结书', 26, 2, 5, '他们或听，或不听，（他们是悖逆之家），必知道在他们中间有了先知。'),
('CUV', '以西结书', 26, 2, 6, '人子啊，虽有荆棘和蒺藜在你那里，你又住在蝎子中间，总不要怕他们，也不要怕他们的话；他们虽是悖逆之家，还不要怕他们的话，也不要因他们的脸色惊惶。'),
('CUV', '以西结书', 26, 2, 7, '他们或听，或不听，你只管将我的话告诉他们；他们是极其悖逆的。'),
('CUV', '以西结书', 26, 2, 8, '人子啊，要听我对你所说的话，不要悖逆像那悖逆之家，你要开口吃我所赐给你的。'),
('CUV', '以西结书', 26, 2, 9, '我观看，见有一只手向我伸出来，手中有一书卷。'),
('CUV', '以西结书', 26, 2, 10, '他将书卷在我面前展开，内外都写著字，其上所写的有哀号、叹息、悲痛的话。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 3, 1, '他对我说：人子啊，要吃你所得的，要吃这书卷，好去对以色列家讲说。'),
('CUV', '以西结书', 26, 3, 2, '于是我开口，他就使我吃这书卷，'),
('CUV', '以西结书', 26, 3, 3, '又对我说：人子啊，要吃我所赐给你的这书卷，充满你的肚腹。我就吃了，口中觉得其甜如蜜。'),
('CUV', '以西结书', 26, 3, 4, '他对我说：人子啊，你往以色列家那里去，将我的话对他们讲说。'),
('CUV', '以西结书', 26, 3, 5, '你奉差遣不是往那说话深奥、言语难懂的民那里去，乃是往以色列家去；'),
('CUV', '以西结书', 26, 3, 6, '不是往那说话深奥、言语难懂的多国去，他们的话语是你不懂得的。我若差你往他们那里去，他们必听从你。'),
('CUV', '以西结书', 26, 3, 7, '以色列家却不肯听从你，因为他们不肯听从我；原来以色列全家是额坚心硬的人。'),
('CUV', '以西结书', 26, 3, 8, '看哪，我使你的脸硬过他们的脸，使你的额硬过他们的额。'),
('CUV', '以西结书', 26, 3, 9, '我使你的额像金钢钻，比火石更硬。他们虽是悖逆之家，你不要怕他们，也不要因他们的脸色惊惶。'),
('CUV', '以西结书', 26, 3, 10, '他又对我说：人子啊，我对你所说的一切话，要心里领会，耳中听闻。'),
('CUV', '以西结书', 26, 3, 11, '你往你本国被掳的子民那里去，他们或听，或不听，你要对他们讲说，告诉他们这是主耶和华说的。'),
('CUV', '以西结书', 26, 3, 12, '那时，灵将我举起，我就听见在我身后有震动轰轰的声音，说：从耶和华的所在显出来的荣耀是该称颂的！'),
('CUV', '以西结书', 26, 3, 13, '我又听见那活物翅膀相碰，与活物旁边轮子旋转震动轰轰的响声。'),
('CUV', '以西结书', 26, 3, 14, '于是灵将我举起，带我而去。我心中甚苦，灵性忿激，并且耶和华的灵（原文是手）在我身上大有能力。'),
('CUV', '以西结书', 26, 3, 15, '我就来到提勒亚毕，住在迦巴鲁河边被掳的人那里，到他们所住的地方，在他们中间忧忧闷闷地坐了七日。'),
('CUV', '以西结书', 26, 3, 16, '过了七日，耶和华的话临到我说：'),
('CUV', '以西结书', 26, 3, 17, '人子啊，我立你作以色列家守望的人，所以你要听我口中的话，替我警戒他们。'),
('CUV', '以西结书', 26, 3, 18, '我何时指著恶人说：他必要死；你若不警戒他，也不劝戒他，使他离开恶行，拯救他的性命，这恶人必死在罪孽之中；我却要向你讨他丧命的罪（原文是血）。'),
('CUV', '以西结书', 26, 3, 19, '倘若你警戒恶人，他仍不转离罪恶，也不离开恶行，他必死在罪孽之中，你却救自己脱离了罪。'),
('CUV', '以西结书', 26, 3, 20, '再者，义人何时离义而犯罪，我将绊脚石放在他面前，他就必死；因你没有警戒他，他必死在罪中，他素来所行的义不被记念；我却要向你讨他丧命的罪（原文是血）。'),
('CUV', '以西结书', 26, 3, 21, '倘若你警戒义人，使他不犯罪，他就不犯罪；他因受警戒就必存活，你也救自己脱离了罪。'),
('CUV', '以西结书', 26, 3, 22, '耶和华的灵（原文是手）在那里降在我身上。他对我说：你起来往平原去，我要在那里和你说话。'),
('CUV', '以西结书', 26, 3, 23, '于是我起来往平原去，不料，耶和华的荣耀正如我在迦巴鲁河边所见的一样，停在那里，我就俯伏于地。'),
('CUV', '以西结书', 26, 3, 24, '灵就进入我里面，使我站起来。耶和华对我说：你进房屋去，将门关上。'),
('CUV', '以西结书', 26, 3, 25, '人子啊，人必用绳索捆绑你，你就不能出去在他们中间来往。'),
('CUV', '以西结书', 26, 3, 26, '我必使你的舌头贴住上膛，以致你哑口，不能作责备他们的人；他们原是悖逆之家。'),
('CUV', '以西结书', 26, 3, 27, '但我对你说话的时候，必使你开口，你就要对他们说：主耶和华如此说。听的可以听，不听的任他不听，因为他们是悖逆之家。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 4, 1, '人子啊，你要拿一块砖，摆在你面前，将一座耶路撒冷城画在其上，'),
('CUV', '以西结书', 26, 4, 2, '又围困这城，造台筑垒，安营攻击，在四围安设撞锤攻城，'),
('CUV', '以西结书', 26, 4, 3, '又要拿个铁鏊，放在你和城的中间，作为铁墙。你要对面攻击这城，使城被困；这样，好作以色列家的预兆。'),
('CUV', '以西结书', 26, 4, 4, '你要向左侧卧，承当以色列家的罪孽；要按你向左侧卧的日数，担当他们的罪孽。'),
('CUV', '以西结书', 26, 4, 5, '因为我已将他们作孽的年数定为你向左侧卧的日数，就是三百九十日，你要这样担当以色列家的罪孽。'),
('CUV', '以西结书', 26, 4, 6, '再者，你满了这些日子，还要向右侧卧，担当犹大家的罪孽。我给你定规侧卧四十日，一日顶一年。'),
('CUV', '以西结书', 26, 4, 7, '你要露出膀臂，面向被困的耶路撒冷，说预言攻击这城。'),
('CUV', '以西结书', 26, 4, 8, '我用绳索捆绑你，使你不能辗转，直等你满了困城的日子。'),
('CUV', '以西结书', 26, 4, 9, '你要取小麦、大麦、豆子、红豆、小米、粗麦，装在一个器皿中，用以为自己做饼；要按你侧卧的三百九十日吃这饼。'),
('CUV', '以西结书', 26, 4, 10, '你所吃的要按分两吃，每日二十舍客勒，按时而吃。'),
('CUV', '以西结书', 26, 4, 11, '你喝水也要按制子，每日喝一欣六分之一，按时而喝。'),
('CUV', '以西结书', 26, 4, 12, '你吃这饼像吃大麦饼一样，要用人粪在众人眼前烧烤。'),
('CUV', '以西结书', 26, 4, 13, '耶和华说：以色列人在我所赶他们到的各国中，也必这样吃不洁净的食物。'),
('CUV', '以西结书', 26, 4, 14, '我说：哎！主耶和华啊，我素来未曾被玷污，从幼年到如今没有吃过自死的，或被野兽撕裂的，那可憎的肉也未曾入我的口。'),
('CUV', '以西结书', 26, 4, 15, '于是他对我说：看哪，我给你牛粪代替人粪，你要将你的饼烤在其上。'),
('CUV', '以西结书', 26, 4, 16, '他又对我说：人子啊，我必在耶路撒冷折断他们的杖，就是断绝他们的粮。他们吃饼要按分两，忧虑而吃；喝水也要按制子，惊惶而喝；'),
('CUV', '以西结书', 26, 4, 17, '使他们缺粮缺水，彼此惊惶，因自己的罪孽消灭。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 5, 1, '人子啊，你要拿一把快刀，当作剃头刀，用这刀剃你的头发和你的胡须，用天平将须发平分。'),
('CUV', '以西结书', 26, 5, 2, '围困城的日子满了，你要将三分之一在城中用火焚烧，将三分之一在城的四围用刀砍碎，将三分之一任风吹散；我也要拔刀追赶。'),
('CUV', '以西结书', 26, 5, 3, '你要从其中取几根包在衣襟里，'),
('CUV', '以西结书', 26, 5, 4, '再从这几根中取些扔在火中焚烧，从里面必有火出来烧入以色列全家。'),
('CUV', '以西结书', 26, 5, 5, '主耶和华如此说：这就是耶路撒冷。我曾将他安置在列邦之中；列国都在他的四围。'),
('CUV', '以西结书', 26, 5, 6, '他行恶，违背我的典章，过于列国；干犯我的律例，过于四围的列邦，因为他弃掉我的典章。至于我的律例，他并没有遵行。'),
('CUV', '以西结书', 26, 5, 7, '所以主耶和华如此说：因为你们纷争过于四围的列国，也不遵行我的律例，不谨守我的典章，并以遵从四围列国的恶规尚不满意，'),
('CUV', '以西结书', 26, 5, 8, '所以主耶和华如此说：看哪，我与你反对，必在列国的眼前，在你中间，施行审判；'),
('CUV', '以西结书', 26, 5, 9, '并且因你一切可憎的事，我要在你中间行我所未曾行的，以后我也不再照著行。'),
('CUV', '以西结书', 26, 5, 10, '在你中间父亲要吃儿子，儿子要吃父亲。我必向你施行审判，我必将你所剩下的分散四方（方：原文是风）。'),
('CUV', '以西结书', 26, 5, 11, '主耶和华说：我指著我的永生起誓，因你用一切可憎的物、可厌的事玷污了我的圣所，故此，我定要使你人数减少，我眼必不顾惜你，也不可怜你。'),
('CUV', '以西结书', 26, 5, 12, '你的民三分之一必遭瘟疫而死，在你中间必因饥荒消灭；三分之一必在你四围倒在刀下；我必将三分之一分散四方（方：原文是风），并要拔刀追赶他们。'),
('CUV', '以西结书', 26, 5, 13, '我要这样成就怒中所定的；我向他们发的忿怒止息了，自己就得著安慰。我在他们身上成就怒中所定的那时，他们就知道我─耶和华所说的是出于热心；'),
('CUV', '以西结书', 26, 5, 14, '并且我必使你在四围的列国中，在经过的众人眼前，成了荒凉和羞辱。'),
('CUV', '以西结书', 26, 5, 15, '这样，我必以怒气和忿怒，并烈怒的责备，向你施行审判。那时，你就在四围的列国中成为羞辱、讥刺、警戒、惊骇。这是我─耶和华说的。'),
('CUV', '以西结书', 26, 5, 16, '那时，我要将灭人、使人饥荒的恶箭，就是射去灭人的，射在你们身上，并要加增你们的饥荒，断绝你们所倚靠的粮食；'),
('CUV', '以西结书', 26, 5, 17, '又要使饥荒和恶兽到你那里，叫你丧子，瘟疫和流血的事也必盛行在你那里；我也要使刀剑临到你。这是我─耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 6, 1, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 6, 2, '人子啊，你要面向以色列的众山说预言，'),
('CUV', '以西结书', 26, 6, 3, '说：以色列的众山哪，要听主耶和华的话。主耶和华对大山、小冈、水沟、山谷如此说：我必使刀剑临到你们，也必毁灭你们的邱坛。'),
('CUV', '以西结书', 26, 6, 4, '你们的祭坛必然荒凉，你们的日像必被打碎。我要使你们被杀的人倒在你们的偶像面前；'),
('CUV', '以西结书', 26, 6, 5, '我也要将以色列人的尸首放在他们的偶像面前，将你们的骸骨抛散在你们祭坛的四围。'),
('CUV', '以西结书', 26, 6, 6, '在你们一切的住处，城邑要变为荒场，邱坛必然凄凉，使你们的祭坛荒废，将你们的偶像打碎。你们的日像被砍倒，你们的工作被毁灭。'),
('CUV', '以西结书', 26, 6, 7, '被杀的人必倒在你们中间，你们就知道我是耶和华。'),
('CUV', '以西结书', 26, 6, 8, '你们分散在各国的时候，我必在列邦中使你们有剩下脱离刀剑的人。'),
('CUV', '以西结书', 26, 6, 9, '那脱离刀剑的人必在所掳到的各国中记念我，为他们心中何等伤破，是因他们起淫心，远离我，眼对偶像行邪淫。他们因行一切可憎的恶事，必厌恶自己。'),
('CUV', '以西结书', 26, 6, 10, '他们必知道我是耶和华；我说要使这灾祸临到他们身上，并非空话。'),
('CUV', '以西结书', 26, 6, 11, '主耶和华如此说：你当拍手顿足，说：哀哉！以色列家行这一切可憎的恶事，他们必倒在刀剑、饥荒、瘟疫之下。'),
('CUV', '以西结书', 26, 6, 12, '在远处的，必遭瘟疫而死；在近处的，必倒在刀剑之下；那存留被围困的，必因饥荒而死；我必这样在他们身上成就我怒中所定的。'),
('CUV', '以西结书', 26, 6, 13, '他们被杀的人倒在他们祭坛四围的偶像中，就是各高冈、各山顶、各青翠树下、各茂密的橡树下，乃是他们献馨香的祭牲给一切偶像的地方。那时，他们就知道我是耶和华。'),
('CUV', '以西结书', 26, 6, 14, '我必伸手攻击他们，使他们的地从旷野到第伯拉他一切住处极其荒凉，他们就知道我是耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 7, 1, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 7, 2, '人子啊，主耶和华对以色列地如此说：结局到了，结局到了地的四境！'),
('CUV', '以西结书', 26, 7, 3, '现在你的结局已经临到，我必使我的怒气归与你，也必按你的行为审判你，照你一切可憎的事刑罚你。'),
('CUV', '以西结书', 26, 7, 4, '我眼必不顾惜你，也不可怜你，却要按你所行的报应你，照你中间可憎的事刑罚你。你就知道我是耶和华。'),
('CUV', '以西结书', 26, 7, 5, '主耶和华如此说：有一灾，独有一灾；看哪，临近了！'),
('CUV', '以西结书', 26, 7, 6, '结局来了，结局来了，向你兴起。看哪，来到了！'),
('CUV', '以西结书', 26, 7, 7, '境内的居民哪，所定的灾临到你，时候到了，日子近了，乃是哄嚷并非在山上欢呼的日子。'),
('CUV', '以西结书', 26, 7, 8, '我快要将我的忿怒倾在你身上，向你成就我怒中所定的，按你的行为审判你，照你一切可憎的事刑罚你。'),
('CUV', '以西结书', 26, 7, 9, '我眼必不顾惜你，也不可怜你，必按你所行的报应你，照你中间可憎的事刑罚你。你就知道击打你的是我耶和华。'),
('CUV', '以西结书', 26, 7, 10, '看哪，看哪，日子快到了，所定的灾已经发出。杖已经开花，骄傲已经发芽。'),
('CUV', '以西结书', 26, 7, 11, '强暴兴起，成了罚恶的杖。以色列人，或是他们的群众，或是他们的财宝，无一存留，他们中间也没有得尊荣的。'),
('CUV', '以西结书', 26, 7, 12, '时候到了，日子近了，买主不可欢喜，卖主不可愁烦，因为烈怒已经临到他们众人身上。'),
('CUV', '以西结书', 26, 7, 13, '卖主虽然存活，却不能归回再得所卖的，因为这异象关乎他们众人。谁都不得归回，也没有人在他的罪孽中坚立自己。'),
('CUV', '以西结书', 26, 7, 14, '他们已经吹角，预备齐全，却无一人出战，因为我的烈怒临到他们众人身上。'),
('CUV', '以西结书', 26, 7, 15, '在外有刀剑，在内有瘟疫、饥荒；在田野的，必遭刀剑而死；在城中的，必有饥荒、瘟疫吞灭他。'),
('CUV', '以西结书', 26, 7, 16, '其中所逃脱的就必逃脱，各人因自己的罪孽在山上发出悲声，好像谷中的鸽子哀鸣。'),
('CUV', '以西结书', 26, 7, 17, '手都发软，膝弱如水。'),
('CUV', '以西结书', 26, 7, 18, '要用麻布束腰，被战兢所盖；各人脸上羞愧，头上光秃。'),
('CUV', '以西结书', 26, 7, 19, '他们要将银子抛在街上，金子看如污秽之物。当耶和华发怒的日子，他们的金银不能救他们，不能使心里知足，也不能使肚腹饱满，因为这金银作了他们罪孽的绊脚石。'),
('CUV', '以西结书', 26, 7, 20, '论到耶和华妆饰华美的殿，他建立得威严，他们却在其中制造可憎可厌的偶像，所以这殿我使他们看如污秽之物。'),
('CUV', '以西结书', 26, 7, 21, '我必将这殿交付外邦人为掠物，交付地上的恶人为掳物；他们也必亵渎这殿。'),
('CUV', '以西结书', 26, 7, 22, '我必转脸不顾以色列人，他们亵渎我隐密之所，强盗也必进去亵渎。'),
('CUV', '以西结书', 26, 7, 23, '要制造锁链；因为这地遍满流血的罪，城邑充满强暴的事，'),
('CUV', '以西结书', 26, 7, 24, '所以我必使列国中最恶的人来占据他们的房屋；我必使强暴人的骄傲止息，他们的圣所都要被亵渎。'),
('CUV', '以西结书', 26, 7, 25, '毁灭临近了，他们要求平安，却无平安可得。'),
('CUV', '以西结书', 26, 7, 26, '灾害加上灾害，风声接连风声；他们必向先知求异象，但祭司讲的律法、长老设的谋略都必断绝。'),
('CUV', '以西结书', 26, 7, 27, '君要悲哀，王要披凄凉为衣，国民的手都发颤。我必照他们的行为待他们，按他们应得的审判他们，他们就知道我是耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 8, 1, '第六年六月初五日，我坐在家中；犹大的众长老坐在我面前。在那里主耶和华的灵（原文是手）降在我身上。'),
('CUV', '以西结书', 26, 8, 2, '我观看，见有形像仿佛火的形状，从他腰以下的形状有火，从他腰以上有光辉的形状，仿佛光耀的精金。'),
('CUV', '以西结书', 26, 8, 3, '他伸出仿佛一只手的样式，抓住我的一绺头发，灵就将我举到天地中间，在神的异象中，带我到耶路撒冷朝北的内院门口，在那里有触动主怒偶像的坐位，就是惹动忌邪的。'),
('CUV', '以西结书', 26, 8, 4, '谁知，在那里有以色列神的荣耀，形状与我在平原所见的一样。'),
('CUV', '以西结书', 26, 8, 5, '神对我说：人子啊，你举目向北观看。我就举目向北观看，见祭坛门的北边，在门口有这惹忌邪的偶像；'),
('CUV', '以西结书', 26, 8, 6, '又对我说：人子啊，以色列家所行的，就是在此行这大可憎的事，使我远离我的圣所，你看见了么？你还要看见另有大可憎的事。'),
('CUV', '以西结书', 26, 8, 7, '他领我到院门口。我观看，见墙上有个窟窿。'),
('CUV', '以西结书', 26, 8, 8, '他对我说：人子啊，你要挖墙。我一挖墙，见有一门。'),
('CUV', '以西结书', 26, 8, 9, '他说：你进去，看他们在这里所行可憎的恶事。'),
('CUV', '以西结书', 26, 8, 10, '我进去一看，谁知，在四面墙上画著各样爬物和可憎的走兽，并以色列家一切的偶像。'),
('CUV', '以西结书', 26, 8, 11, '在这些像前有以色列家的七十个长老站立，沙番的儿子雅撒尼亚也站在其中。各人手拿香炉，烟云的香气上腾。'),
('CUV', '以西结书', 26, 8, 12, '他对我说：人子啊，以色列家的长老暗中在各人画像屋里所行的，你看见了么？他们常说：耶和华看不见我们；耶和华已经离弃这地。'),
('CUV', '以西结书', 26, 8, 13, '他又说：你还要看见他们另外行大可憎的事。'),
('CUV', '以西结书', 26, 8, 14, '他领我到耶和华殿外院朝北的门口。谁知，在那里有妇女坐著，为搭模斯哭泣。'),
('CUV', '以西结书', 26, 8, 15, '他对我说：人子啊，你看见了么？你还要看见比这更可憎的事。'),
('CUV', '以西结书', 26, 8, 16, '他又领我到耶和华殿的内院。谁知，在耶和华的殿门口、廊子和祭坛中间，约有二十五个人背向耶和华的殿，面向东方拜日头。'),
('CUV', '以西结书', 26, 8, 17, '他对我说：人子啊，你看见了么？犹大家在此行这可憎的事还算为小么？他们在这地遍行强暴，再三惹我发怒，他们手拿枝条举向鼻前。'),
('CUV', '以西结书', 26, 8, 18, '因此，我也要以忿怒行事，我眼必不顾惜，也不可怜他们；他们虽向我耳中大声呼求，我还是不听。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 9, 1, '他向我耳中大声喊叫说：要使那监管这城的人手中各拿灭命的兵器前来。'),
('CUV', '以西结书', 26, 9, 2, '忽然有六个人从朝北的上门而来，各人手拿杀人的兵器；内中有一人身穿细麻衣，腰间带著墨盒子。他们进来，站在铜祭坛旁。'),
('CUV', '以西结书', 26, 9, 3, '以色列神的荣耀本在基路伯上，现今从那里升到殿的门槛。神将那身穿细麻衣、腰间带著墨盒子的人召来。'),
('CUV', '以西结书', 26, 9, 4, '耶和华对他说：你去走遍耶路撒冷全城，那些因城中所行可憎之事叹息哀哭的人，画记号在额上。'),
('CUV', '以西结书', 26, 9, 5, '我耳中听见他对其余的人说：要跟随他走遍全城，以行击杀。你们的眼不要顾惜，也不要可怜他们。'),
('CUV', '以西结书', 26, 9, 6, '要将年老的、年少的，并处女、婴孩，和妇女，从圣所起全都杀尽，只是凡有记号的人不要挨近他。于是他们从殿前的长老杀起。'),
('CUV', '以西结书', 26, 9, 7, '他对他们说：要污秽这殿，使院中充满被杀的人。你们出去罢！他们就出去，在城中击杀。'),
('CUV', '以西结书', 26, 9, 8, '他们击杀的时候，我被留下，我就俯伏在地，说：哎！主耶和华啊，你将忿怒倾在耶路撒冷，岂要将以色列所剩下的人都灭绝么？'),
('CUV', '以西结书', 26, 9, 9, '他对我说：以色列家和犹大家的罪孽极其重大。遍地有流血的事，满城有冤屈，因为他们说：耶和华已经离弃这地，他看不见我们。'),
('CUV', '以西结书', 26, 9, 10, '故此，我眼必不顾惜，也不可怜他们，要照他们所行的报应在他们头上。'),
('CUV', '以西结书', 26, 9, 11, '那穿细麻衣、腰间带著墨盒子的人将这事回复说：我已经照你所吩咐的行了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 10, 1, '我观看，见基路伯头上的穹苍之中，显出蓝宝石的形状，仿佛宝座的形像。'),
('CUV', '以西结书', 26, 10, 2, '主对那穿细麻衣的人说：你进去，在旋转的轮内基路伯以下，从基路伯中间将火炭取满两手，撒在城上。我就见他进去。'),
('CUV', '以西结书', 26, 10, 3, '那人进去的时候，基路伯站在殿的右边，云彩充满了内院。'),
('CUV', '以西结书', 26, 10, 4, '耶和华的荣耀从基路伯那里上升，停在门槛以上；殿内满了云彩，院宇也被耶和华荣耀的光辉充满。'),
('CUV', '以西结书', 26, 10, 5, '基路伯翅膀的响声听到外院，好像全能神说话的声音。'),
('CUV', '以西结书', 26, 10, 6, '他吩咐那穿细麻衣的人说：要从旋转的轮内基路伯中间取火。那人就进去站在一个轮子旁边。'),
('CUV', '以西结书', 26, 10, 7, '有一个基路伯从基路伯中伸手到基路伯中间的火那里，取些放在那穿细麻衣的人两手中，那人就拿出去了。'),
('CUV', '以西结书', 26, 10, 8, '在基路伯翅膀之下，显出有人手的样式。'),
('CUV', '以西结书', 26, 10, 9, '我又观看，见基路伯旁边有四个轮子。这基路伯旁有一个轮子，那基路伯旁有一个轮子，每基路伯都是如此；轮子的颜色（原文是形状）仿佛水苍玉。'),
('CUV', '以西结书', 26, 10, 10, '至于四轮的形状，都是一个样式，仿佛轮中套轮。'),
('CUV', '以西结书', 26, 10, 11, '轮行走的时候，向四方都能直行，并不掉转。头向何方，他们也随向何方，行走的时候并不掉转。'),
('CUV', '以西结书', 26, 10, 12, '他们全身，连背带手和翅膀，并轮周围都满了眼睛。这四个基路伯的轮子都是如此。'),
('CUV', '以西结书', 26, 10, 13, '至于这些轮子，我耳中听见说是旋转的。'),
('CUV', '以西结书', 26, 10, 14, '基路伯各有四脸：第一是基路伯的脸，第二是人的脸，第三是狮子的脸，第四是鹰的脸。'),
('CUV', '以西结书', 26, 10, 15, '基路伯升上去了；这是我在迦巴鲁河边所见的活物。'),
('CUV', '以西结书', 26, 10, 16, '基路伯行走，轮也在旁边行走。基路伯展开翅膀，离地上升，轮也不转离他们旁边。'),
('CUV', '以西结书', 26, 10, 17, '那些站住，这些也站住；那些上升，这些也一同上升，因为活物的灵在轮中。'),
('CUV', '以西结书', 26, 10, 18, '耶和华的荣耀从殿的门槛那里出去，停在基路伯以上。'),
('CUV', '以西结书', 26, 10, 19, '基路伯出去的时候，就展开翅膀，在我眼前离地上升。轮也在他们的旁边，都停在耶和华殿的东门口。在他们以上有以色列神的荣耀。'),
('CUV', '以西结书', 26, 10, 20, '这是我在迦巴鲁河边所见、以色列神荣耀以下的活物，我就知道他们是基路伯。'),
('CUV', '以西结书', 26, 10, 21, '各有四个脸面，四个翅膀，翅膀以下有人手的样式。'),
('CUV', '以西结书', 26, 10, 22, '至于他们脸的模样，并身体的形像，是我从前在迦巴鲁河边所看见的。他们俱各直往前行。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 11, 1, '灵将我举起，带到耶和华殿向东的东门。谁知，在门口有二十五个人，我见其中有民间的首领押朔的儿子雅撒尼亚和比拿雅的儿子毗拉提。'),
('CUV', '以西结书', 26, 11, 2, '耶和华对我说：人子啊，这就是图谋罪孽的人，在这城中给人设恶谋。'),
('CUV', '以西结书', 26, 11, 3, '他们说：盖房屋的时候尚未临近；这城是锅，我们是肉。'),
('CUV', '以西结书', 26, 11, 4, '人子啊，因此你当说预言，说预言攻击他们。'),
('CUV', '以西结书', 26, 11, 5, '耶和华的灵降在我身上，对我说：你当说，耶和华如此说：以色列家啊，你们口中所说的，心里所想的，我都知道。'),
('CUV', '以西结书', 26, 11, 6, '你们在这城中杀人增多，使被杀的人充满街道。'),
('CUV', '以西结书', 26, 11, 7, '所以主耶和华如此说：你们杀在城中的人就是肉，这城就是锅；你们却要从其中被带出去。'),
('CUV', '以西结书', 26, 11, 8, '你们怕刀剑，我必使刀剑临到你们。这是主耶和华说的。'),
('CUV', '以西结书', 26, 11, 9, '我必从这城中带出你们去，交在外邦人的手中，且要在你们中间施行审判。'),
('CUV', '以西结书', 26, 11, 10, '你们必倒在刀下；我必在以色列的境界审判你们，你们就知道我是耶和华。'),
('CUV', '以西结书', 26, 11, 11, '这城必不作你们的锅，你们也不作其中的肉。我必在以色列的境界审判你们，'),
('CUV', '以西结书', 26, 11, 12, '你们就知道我是耶和华；因为你们没有遵行我的律例，也没有顺从我的典章，却随从你们四围列国的恶规。'),
('CUV', '以西结书', 26, 11, 13, '我正说预言的时候，比拿雅的儿子毗拉提死了。于是我俯伏在地，大声呼叫说：哎！主耶和华啊，你要将以色列剩下的人灭绝净尽么？'),
('CUV', '以西结书', 26, 11, 14, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 11, 15, '人子啊，耶路撒冷的居民对你的弟兄、你的本族、你的亲属、以色列全家，就是对大众说：你们远离耶和华罢！这地是赐给我们为业的。'),
('CUV', '以西结书', 26, 11, 16, '所以你当说：耶和华如此说：我虽将以色列全家远远迁移到列国中，将他们分散在列邦内，我还要在他们所到的列邦，暂作他们的圣所。'),
('CUV', '以西结书', 26, 11, 17, '你当说：主耶和华如此说：我必从万民中招聚你们，从分散的列国内聚集你们，又要将以色列地赐给你们。'),
('CUV', '以西结书', 26, 11, 18, '他们必到那里，也必从其中除掉一切可憎可厌的物。'),
('CUV', '以西结书', 26, 11, 19, '我要使他们有合一的心，也要将新灵放在他们里面，又从他们肉体中除掉石心，赐给他们肉心，'),
('CUV', '以西结书', 26, 11, 20, '使他们顺从我的律例，谨守遵行我的典章。他们要作我的子民，我要作他们的神。'),
('CUV', '以西结书', 26, 11, 21, '至于那些心中随从可憎可厌之物的，我必照他们所行的报应在他们头上。这是主耶和华说的。'),
('CUV', '以西结书', 26, 11, 22, '于是，基路伯展开翅膀，轮子都在他们旁边；在他们以上有以色列神的荣耀。'),
('CUV', '以西结书', 26, 11, 23, '耶和华的荣耀从城中上升，停在城东的那座山上。'),
('CUV', '以西结书', 26, 11, 24, '灵将我举起，在异象中藉著神的灵将我带进迦勒底地，到被掳的人那里；我所见的异象就离我上升去了。'),
('CUV', '以西结书', 26, 11, 25, '我便将耶和华所指示我的一切事都说给被掳的人听。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 12, 1, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 12, 2, '人子啊，你住在悖逆的家中。他们有眼睛看不见，有耳朵听不见，因为他们是悖逆之家。'),
('CUV', '以西结书', 26, 12, 3, '所以人子啊，你要预备掳去使用的物件，在白日当他们眼前从你所住的地方移到别处去；他们虽是悖逆之家，或者可以揣摩思想。'),
('CUV', '以西结书', 26, 12, 4, '你要在白日当他们眼前带出你的物件去，好像预备掳去使用的物件。到了晚上，你要在他们眼前亲自出去，像被掳的人出去一样。'),
('CUV', '以西结书', 26, 12, 5, '你要在他们眼前挖通了墙，从其中将物件带出去。'),
('CUV', '以西结书', 26, 12, 6, '到天黑时，你要当他们眼前搭在肩头上带出去，并要蒙住脸看不见地，因为我立你作以色列家的预兆。'),
('CUV', '以西结书', 26, 12, 7, '我就照著所吩咐的去行，白日带出我的物件，好像预备掳去使用的物件。到了晚上，我用手挖通了墙。天黑的时候，就当他们眼前搭在肩头上带出去。'),
('CUV', '以西结书', 26, 12, 8, '次日早晨，耶和华的话临到我说：'),
('CUV', '以西结书', 26, 12, 9, '人子啊，以色列家，就是那悖逆之家，岂不是问你说：你做什么呢？'),
('CUV', '以西结书', 26, 12, 10, '你要对他们说：主耶和华如此说：这是关乎耶路撒冷的君王和他周围以色列全家的预表（原文是担子）。'),
('CUV', '以西结书', 26, 12, 11, '你要说：我作你们的预兆：我怎样行，他们所遭遇的也必怎样，他们必被掳去。'),
('CUV', '以西结书', 26, 12, 12, '他们中间的君王也必在天黑的时候将物件搭在肩头上带出去。他们要挖通了墙，从其中带出去。他必蒙住脸，眼看不见地。'),
('CUV', '以西结书', 26, 12, 13, '我必将我的网撒在他身上，他必在我的网罗中缠住。我必带他到迦勒底人之地的巴比伦；他虽死在那里，却看不见那地。'),
('CUV', '以西结书', 26, 12, 14, '周围一切帮助他的和他所有的军队，我必分散四方（方：原文是风），也要拔刀追赶他们。'),
('CUV', '以西结书', 26, 12, 15, '我将他们四散在列国、分散在列邦的时候，他们就知道我是耶和华。'),
('CUV', '以西结书', 26, 12, 16, '我却要留下他们几个人得免刀剑、饥荒、瘟疫，使他们在所到的各国中述说他们一切可憎的事，人就知道我是耶和华。'),
('CUV', '以西结书', 26, 12, 17, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 12, 18, '人子啊，你吃饭必胆战，喝水必惶惶忧虑。'),
('CUV', '以西结书', 26, 12, 19, '你要对这地的百姓说：主耶和华论耶路撒冷和以色列地的居民如此说，他们吃饭必忧虑，喝水必惊惶。因其中居住的众人所行强暴的事，这地必然荒废，一无所存。'),
('CUV', '以西结书', 26, 12, 20, '有居民的城邑必变为荒场，地也必变为荒废；你们就知道我是耶和华。'),
('CUV', '以西结书', 26, 12, 21, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 12, 22, '人子啊，在你们以色列地怎么有这俗语，说日子迟延，一切异象都落了空呢？'),
('CUV', '以西结书', 26, 12, 23, '你要告诉他们说：主耶和华如此说：我必使这俗语止息，以色列中不再用这俗语。你却要对他们说：日子临近，一切的异象必都应验。'),
('CUV', '以西结书', 26, 12, 24, '从此，在以色列家中必不再有虚假的异象和奉承的占卜。'),
('CUV', '以西结书', 26, 12, 25, '我─耶和华说话，所说的必定成就，不再耽延。你们这悖逆之家，我所说的话必趁你们在世的日子成就。这是主耶和华说的。'),
('CUV', '以西结书', 26, 12, 26, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 12, 27, '人子啊，以色列家的人说：他所见的异象是关乎后来许多的日子，所说的预言是指著极远的时候。'),
('CUV', '以西结书', 26, 12, 28, '所以你要对他们说：主耶和华如此说：我的话没有一句再耽延的，我所说的必定成就。这是主耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 13, 1, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 13, 2, '人子啊，你要说预言攻击以色列中说预言的先知，对那些本己心发预言的说：你们当听耶和华的话。'),
('CUV', '以西结书', 26, 13, 3, '主耶和华如此说：愚顽的先知有祸了，他们随从自己的心意，却一无所见。'),
('CUV', '以西结书', 26, 13, 4, '以色列啊，你的先知好像荒场中的狐狸，'),
('CUV', '以西结书', 26, 13, 5, '没有上去堵挡破口，也没有为以色列家重修墙垣，使他们当耶和华的日子在阵上站立得住。'),
('CUV', '以西结书', 26, 13, 6, '这些人所见的是虚假，是谎诈的占卜。他们说是耶和华说的，其实耶和华并没有差遣他们，他们倒使人指望那话必然立定。'),
('CUV', '以西结书', 26, 13, 7, '你们岂不是见了虚假的异象么？岂不是说了谎诈的占卜么？你们说，这是耶和华说的，其实我没有说。'),
('CUV', '以西结书', 26, 13, 8, '所以主耶和华如此说：因你们说的是虚假，见的是谎诈，我就与你们反对。这是主耶和华说的。'),
('CUV', '以西结书', 26, 13, 9, '我的手必攻击那见虚假异象、用谎诈占卜的先知，他们必不列在我百姓的会中，不录在以色列家的册上，也不进入以色列地；你们就知道我是主耶和华。'),
('CUV', '以西结书', 26, 13, 10, '因为他们诱惑我的百姓，说：平安！其实没有平安，就像有人立起墙壁，他们倒用未泡透的灰抹上。'),
('CUV', '以西结书', 26, 13, 11, '所以你要对那些抹上未泡透灰的人说：墙要倒塌，必有暴雨漫过。大冰雹啊，你们要降下，狂风也要吹裂这墙。'),
('CUV', '以西结书', 26, 13, 12, '这墙倒塌之后，人岂不问你们说：你们抹上未泡透的灰在哪里呢？'),
('CUV', '以西结书', 26, 13, 13, '所以主耶和华如此说：我要发怒，使狂风吹裂这墙，在怒中使暴雨漫过，又发怒降下大冰雹，毁灭这墙。'),
('CUV', '以西结书', 26, 13, 14, '我要这样拆毁你们那未泡透灰所抹的墙，拆平到地，以致根基露出，墙必倒塌，你们也必在其中灭亡；你们就知道我是耶和华。'),
('CUV', '以西结书', 26, 13, 15, '我要这样向墙和用未泡透灰抹墙的人成就我怒中所定的，并要对你们说：墙和抹墙的人都没有了。'),
('CUV', '以西结书', 26, 13, 16, '这抹墙的就是以色列的先知，他们指著耶路撒冷说预言，为这城见了平安的异象，其实没有平安。这是主耶和华说的。'),
('CUV', '以西结书', 26, 13, 17, '人子啊，你要面向本民中、从己心发预言的女子说预言，攻击他们，'),
('CUV', '以西结书', 26, 13, 18, '说主耶和华如此说：这些妇女有祸了！他们为众人的膀臂缝靠枕，给高矮之人做下垂的头巾，为要猎取人的性命。难道你们要猎取我百姓的性命，为利己将人救活么？'),
('CUV', '以西结书', 26, 13, 19, '你们为两把大麦，为几块饼，在我民中亵渎我，对肯听谎言的民说谎，杀死不该死的人，救活不该活的人。'),
('CUV', '以西结书', 26, 13, 20, '所以主耶和华如此说：看哪，我与你们的靠枕反对，就是你们用以猎取人、使人的性命如鸟飞的。我要将靠枕从你们的膀臂上扯去，释放你们猎取如鸟飞的人。'),
('CUV', '以西结书', 26, 13, 21, '我也必撕裂你们下垂的头巾，救我百姓脱离你们的手，不再被猎取，落在你们手中。你们就知道我是耶和华。'),
('CUV', '以西结书', 26, 13, 22, '我不使义人伤心，你们却以谎话使他伤心，又坚固恶人的手，使他不回头离开恶道得以救活。'),
('CUV', '以西结书', 26, 13, 23, '你们就不再见虚假的异象，也不再行占卜的事；我必救我的百姓脱离你们的手；你们就知道我是耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 14, 1, '有几个以色列长老到我这里来，坐在我面前。'),
('CUV', '以西结书', 26, 14, 2, '耶和华的话就临到我说：'),
('CUV', '以西结书', 26, 14, 3, '人子啊，这些人已将他们的假神接到心里，把陷于罪的绊脚石放在面前，我岂能丝毫被他们求问么？'),
('CUV', '以西结书', 26, 14, 4, '所以你要告诉他们：主耶和华如此说：以色列家的人中，凡将他的假神接到心里，把陷于罪的绊脚石放在面前，又就了先知来的，我─耶和华在他所求的事上，必按他众多的假神回答他（或译：必按他拜许多假神的罪报应他），'),
('CUV', '以西结书', 26, 14, 5, '好在以色列家的心事上捉住他们，因为他们都藉著假神与我生疏。'),
('CUV', '以西结书', 26, 14, 6, '所以你要告诉以色列家说：主耶和华如此说：回头罢！离开你们的偶像，转脸莫从你们一切可憎的事。'),
('CUV', '以西结书', 26, 14, 7, '因为以色列家的人，或在以色列中寄居的外人，凡与我隔绝，将他的假神接到心里，把陷于罪的绊脚石放在面前，又就了先知来要为自己的事求问我的，我─耶和华必亲自回答他。'),
('CUV', '以西结书', 26, 14, 8, '我必向那人变脸，使他作了警戒，笑谈，令人惊骇，并且我要将他从我民中剪除；你们就知道我是耶和华。'),
('CUV', '以西结书', 26, 14, 9, '先知若被迷惑说一句预言，是我─耶和华任那先知受迷惑，我也必向他伸手，将他从我民以色列中除灭。'),
('CUV', '以西结书', 26, 14, 10, '他们必担当自己的罪孽。先知的罪孽和求问之人的罪孽都是一样，'),
('CUV', '以西结书', 26, 14, 11, '好使以色列家不再走迷离开我，不再因各样的罪过玷污自己，只要作我的子民，我作他们的神。这是主耶和华说的。'),
('CUV', '以西结书', 26, 14, 12, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 14, 13, '人子啊，若有一国犯罪干犯我，我也向他伸手折断他们的杖，就是断绝他们的粮，使饥荒临到那地，将人与牲畜从其中剪除；'),
('CUV', '以西结书', 26, 14, 14, '其中虽有挪亚、但以理、约伯这三人，他们只能因他们的义救自己的性命。这是主耶和华说的。'),
('CUV', '以西结书', 26, 14, 15, '我若使恶兽经过糟践那地，使地荒凉，以致因这些兽，人都不得经过；'),
('CUV', '以西结书', 26, 14, 16, '虽有这三人在其中，主耶和华说：我指著我的永生起誓，他们连儿带女都不能得救，只能自己得救，那地仍然荒凉。'),
('CUV', '以西结书', 26, 14, 17, '或者我使刀剑临到那地，说：刀剑哪，要经过那地，以致我将人与牲畜从其中剪除；'),
('CUV', '以西结书', 26, 14, 18, '虽有这三人在其中，主耶和华说：我指著我的永生起誓，他们连儿带女都不能得救，只能自己得救。'),
('CUV', '以西结书', 26, 14, 19, '或者我叫瘟疫流行那地，使我灭命（原文是带血）的忿怒倾在其上，好将人与牲畜从其中剪除；'),
('CUV', '以西结书', 26, 14, 20, '虽有挪亚、但以理、约伯在其中，主耶和华说：我指著我的永生起誓，他们连儿带女都不能救，只能因他们的义救自己的性命。'),
('CUV', '以西结书', 26, 14, 21, '主耶和华如此说：我将这四样大灾─就是刀剑、饥荒、恶兽、瘟疫降在耶路撒冷，将人与牲畜从其中剪除，岂不更重么？'),
('CUV', '以西结书', 26, 14, 22, '然而其中必有剩下的人，他们连儿带女必带到你们这里来，你们看见他们所行所为的，要因我降给耶路撒冷的一切灾祸，便得了安慰。'),
('CUV', '以西结书', 26, 14, 23, '你们看见他们所行所为的，得了安慰，就知道我在耶路撒冷中所行的并非无故。这是主耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 15, 1, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 15, 2, '人子啊，葡萄树比别样树有甚么强处？葡萄枝比众树枝有甚么好处？'),
('CUV', '以西结书', 26, 15, 3, '其上可以取木料做甚么工用，可以取来做钉子挂甚么器皿么？'),
('CUV', '以西结书', 26, 15, 4, '看哪，已经抛在火中当作柴烧，火既烧了两头，中间也被烧了，还有益于工用么？'),
('CUV', '以西结书', 26, 15, 5, '完全的时候尚且不合乎甚么工用，何况被火烧坏，还能合乎甚么工用么？'),
('CUV', '以西结书', 26, 15, 6, '所以，主耶和华如此说：众树以内的葡萄树，我怎样使他在火中当柴，也必照样待耶路撒冷的居民。'),
('CUV', '以西结书', 26, 15, 7, '我必向他们变脸；他们虽从火中出来，火却要烧灭他们。我向他们变脸的时候，你们就知道我是耶和华。'),
('CUV', '以西结书', 26, 15, 8, '我必使地土荒凉，因为他们行事干犯我。这是主耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 16, 1, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 16, 2, '人子啊，你要使耶路撒冷知道他那些可憎的事，'),
('CUV', '以西结书', 26, 16, 3, '说主耶和华对耶路撒冷如此说：你根本，你出世，是在迦南地；你父亲是亚摩利人，你母亲是赫人。'),
('CUV', '以西结书', 26, 16, 4, '论到你出世的景况，在你初生的日子没有为你断脐带，也没有用水洗你，使你洁净，丝毫没有撒盐在你身上，也没有用布裹你。'),
('CUV', '以西结书', 26, 16, 5, '谁的眼也不可怜你，为你做一件这样的事怜恤你；但你初生的日子扔在田野，是因你被厌恶。'),
('CUV', '以西结书', 26, 16, 6, '我从你旁边经过，见你滚在血中，就对你说：你虽在血中，仍可存活；你虽在血中，仍可存活。'),
('CUV', '以西结书', 26, 16, 7, '我使你生长好像田间所长的，你就渐渐长大，以致极其俊美，两乳成形，头发长成，你却仍然赤身露体。'),
('CUV', '以西结书', 26, 16, 8, '我从你旁边经过，看见你的时候正动爱情，便用衣襟搭在你身上，遮盖你的赤体；又向你起誓，与你结盟，你就归于我。这是主耶和华说的。'),
('CUV', '以西结书', 26, 16, 9, '那时我用水洗你，洗净你身上的血，又用油抹你。'),
('CUV', '以西结书', 26, 16, 10, '我也使你身穿绣花衣服，脚穿海狗皮鞋，并用细麻布给你束腰，用丝绸为衣披在你身上，'),
('CUV', '以西结书', 26, 16, 11, '又用妆饰打扮你，将镯子戴在你手上，将金链戴在你项上。'),
('CUV', '以西结书', 26, 16, 12, '我也将环子戴在你鼻子上，将耳环戴在你耳朵上，将华冠戴在你头上。'),
('CUV', '以西结书', 26, 16, 13, '这样，你就有金银的妆饰，穿的是细麻衣和丝绸，并绣花衣；吃的是细面、蜂蜜，并油。你也极其美貌，发达到王后的尊荣。'),
('CUV', '以西结书', 26, 16, 14, '你美貌的名声传在列邦中，你十分美貌，是因我加在你身上的威荣。这是主耶和华说的。'),
('CUV', '以西结书', 26, 16, 15, '只是你仗著自己的美貌，又因你的名声就行邪淫。你纵情淫乱，使过路的任意而行。'),
('CUV', '以西结书', 26, 16, 16, '你用衣服为自己在高处结彩，在其上行邪淫。这样的事将来必没有，也必不再行了。'),
('CUV', '以西结书', 26, 16, 17, '你又将我所给你那华美的金银、宝器为自己制造人像，与他行邪淫；'),
('CUV', '以西结书', 26, 16, 18, '又用你的绣花衣服给他披上，并将我的膏油和香料摆在他跟前；'),
('CUV', '以西结书', 26, 16, 19, '又将我赐给你的食物，就是我赐给你吃的细面、油，和蜂蜜，都摆在他跟前为馨香的供物。这是主耶和华说的。'),
('CUV', '以西结书', 26, 16, 20, '并且你将给我所生的儿女焚献给他。'),
('CUV', '以西结书', 26, 16, 21, '你行淫乱岂是小事，竟将我的儿女杀了，使他们经火归与他么？'),
('CUV', '以西结书', 26, 16, 22, '你行这一切可憎和淫乱的事，并未追念你幼年赤身露体滚在血中的日子。'),
('CUV', '以西结书', 26, 16, 23, '你行这一切恶事之后（主耶和华说：你有祸了！有祸了！）'),
('CUV', '以西结书', 26, 16, 24, '又为自己建造圆顶花楼，在各街上做了高台。'),
('CUV', '以西结书', 26, 16, 25, '你在一切市口上建造高台，使你的美貌变为可憎的，又与一切过路的多行淫乱。'),
('CUV', '以西结书', 26, 16, 26, '你也和你邻邦放纵情欲的埃及人行淫，加增你的淫乱，惹我发怒。'),
('CUV', '以西结书', 26, 16, 27, '因此我伸手攻击你，减少你应用的粮食，又将你交给恨你的非利士众女（众女是城邑的意思；本章下同），使他们任意待你。他们见你的淫行，为你羞耻。'),
('CUV', '以西结书', 26, 16, 28, '你因贪色无厌，又与亚述人行淫，与他们行淫之后，仍不满意，'),
('CUV', '以西结书', 26, 16, 29, '并且多行淫乱，直到那贸易之地，就是迦勒底，你仍不满意。'),
('CUV', '以西结书', 26, 16, 30, '主耶和华说：你行这一切事，都是不知羞耻妓女所行的，可见你的心是何等懦弱！'),
('CUV', '以西结书', 26, 16, 31, '因你在一切市口上建造圆顶花楼，在各街上做了高台，你却藐视赏赐，不像妓女。'),
('CUV', '以西结书', 26, 16, 32, '哎！你这行淫的妻啊，宁肯接外人，不接丈夫。'),
('CUV', '以西结书', 26, 16, 33, '凡妓女是得人赠送，你反倒赠送你所爱的人，贿赂他们从四围来与你行淫。'),
('CUV', '以西结书', 26, 16, 34, '你行淫与别的妇女相反，因为不是人从你行淫；你既赠送人，人并不赠送你；所以你与别的妇女相反。'),
('CUV', '以西结书', 26, 16, 35, '你这妓女啊，要听耶和华的话。'),
('CUV', '以西结书', 26, 16, 36, '主耶和华如此说：因你的污秽倾泄了，你与你所爱的行淫露出下体，又因你拜一切可憎的偶像，流儿女的血献给他，'),
('CUV', '以西结书', 26, 16, 37, '我就要将你一切相欢相爱的和你一切所恨的都聚集来，从四围攻击你；又将你的下体露出，使他们看尽了。'),
('CUV', '以西结书', 26, 16, 38, '我也要审判你，好像官长审判淫妇和流人血的妇女一样。我因忿怒忌恨，使流血的罪归到你身上。'),
('CUV', '以西结书', 26, 16, 39, '我又要将你交在他们手中；他们必拆毁你的圆顶花楼，毁坏你的高台，剥去你的衣服，夺取你的华美宝器，留下你赤身露体。'),
('CUV', '以西结书', 26, 16, 40, '他们也必带多人来攻击你，用石头打死你，用刀剑刺透你，'),
('CUV', '以西结书', 26, 16, 41, '用火焚烧你的房屋，在许多妇人眼前向你施行审判。我必使你不再行淫，也不再赠送与人。'),
('CUV', '以西结书', 26, 16, 42, '这样，我就止息向你发的忿怒，我的忌恨也要离开你，我要安静不再恼怒。'),
('CUV', '以西结书', 26, 16, 43, '因你不追念你幼年的日子，在这一切的事上向我发烈怒，所以我必照你所行的报应在你头上，你就不再贪淫，行那一切可憎的事。这是主耶和华说的。'),
('CUV', '以西结书', 26, 16, 44, '凡说俗语的必用俗语攻击你，说：母亲怎样，女儿也怎样。'),
('CUV', '以西结书', 26, 16, 45, '你正是你母亲的女儿，厌弃丈夫和儿女；你正是你姊妹的姊妹，厌弃丈夫和儿女。你母亲是赫人，你父亲是亚摩利人。'),
('CUV', '以西结书', 26, 16, 46, '你的姊姊是撒玛利亚，他和他的众女住在你左边；你的妹妹是所多玛，他和他的众女住在你右边。'),
('CUV', '以西结书', 26, 16, 47, '你没有效法他们的行为，也没有照他们可憎的事去做，你以那为小事，你一切所行的倒比他们更坏。'),
('CUV', '以西结书', 26, 16, 48, '主耶和华说：我指著我的永生起誓，你妹妹所多玛与他的众女尚未行你和你众女所行的事。'),
('CUV', '以西结书', 26, 16, 49, '看哪，你妹妹所多玛的罪孽是这样：他和他的众女都心骄气傲，粮食饱足，大享安逸，并没有扶助困苦和穷乏人的手。'),
('CUV', '以西结书', 26, 16, 50, '他们狂傲，在我面前行可憎的事，我看见便将他们除掉。'),
('CUV', '以西结书', 26, 16, 51, '撒玛利亚没有犯你一半的罪，你行可憎的事比他更多，使你的姊妹因你所行一切可憎的事，倒显为义。'),
('CUV', '以西结书', 26, 16, 52, '你既断定你姊妹为义（为义：或译当受羞辱），就要担当自己的羞辱；因你所犯的罪比他们更为可憎，他们就比你更显为义；你既使你的姊妹显为义，你就要抱愧担当自己的羞辱。'),
('CUV', '以西结书', 26, 16, 53, '我必叫他们被掳的归回，就是叫所多玛和他的众女，撒玛利亚和他的众女，并你们中间被掳的，都要归回，'),
('CUV', '以西结书', 26, 16, 54, '好使你担当自己的羞辱，并因你一切所行的使他们得安慰，你就抱愧。'),
('CUV', '以西结书', 26, 16, 55, '你的妹妹所多玛和他的众女必归回原位；撒玛利亚和他的众女，你和你的众女，也必归回原位。'),
('CUV', '以西结书', 26, 16, 56, '在你骄傲的日子，你的恶行没有显露以先，你的口就不提你的妹妹所多玛。那受了凌辱的亚兰众女和亚兰四围非利士的众女都恨恶你，藐视你。'),
('CUV', '以西结书', 26, 16, 57, 'a'),
('CUV', '以西结书', 26, 16, 58, '耶和华说：你贪淫和可憎的事，你已经担当了。'),
('CUV', '以西结书', 26, 16, 59, '主耶和华如此说：你这轻看誓言、背弃盟约的，我必照你所行的待你。'),
('CUV', '以西结书', 26, 16, 60, '然而我要追念在你幼年时与你所立的约，也要与你立定永约。'),
('CUV', '以西结书', 26, 16, 61, '你接待你姊姊和你妹妹的时候，你要追念你所行的，自觉惭愧；并且我要将他们赐你为女儿，却不是按著前约。'),
('CUV', '以西结书', 26, 16, 62, '我要坚定与你所立的约（你就知道我是耶和华），'),
('CUV', '以西结书', 26, 16, 63, '好使你在我赦免你一切所行的时候，心里追念，自觉抱愧，又因你的羞辱就不再开口。这是主耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 17, 1, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 17, 2, '人子啊，你要向以色列家出谜语，设比喻，'),
('CUV', '以西结书', 26, 17, 3, '说主耶和华如此说：有一大鹰，翅膀大，翎毛长，羽毛丰满，彩色俱备，来到利巴嫩，将香柏树梢拧去，'),
('CUV', '以西结书', 26, 17, 4, '就是折去香柏树尽尖的嫩枝，叼到贸易之地，放在买卖城中；'),
('CUV', '以西结书', 26, 17, 5, '又将以色列地的枝子栽于肥田里，插在大水旁，如插柳树，'),
('CUV', '以西结书', 26, 17, 6, '就渐渐生长，成为蔓延矮小的葡萄树。其枝转向那鹰，其根在鹰以下，于是成了葡萄树，生出枝子，发出小枝。'),
('CUV', '以西结书', 26, 17, 7, '又有一大鹰，翅膀大，羽毛多。这葡萄树从栽种的畦中向这鹰弯过根来，发出枝子，好得他的浇灌。'),
('CUV', '以西结书', 26, 17, 8, '这树栽于肥田多水的旁边，好生枝子，结果子，成为佳美的葡萄树。'),
('CUV', '以西结书', 26, 17, 9, '你要说，主耶和华如此说：这葡萄树岂能发旺呢？鹰岂不拔出他的根来，芟除他的果子，使他枯干，使他发的嫩叶都枯干了么？也不用大力和多民，就拔出他的根来。'),
('CUV', '以西结书', 26, 17, 10, '葡萄树虽然栽种，岂能发旺呢？一经东风，岂不全然枯干么？必在生长的畦中枯干了。'),
('CUV', '以西结书', 26, 17, 11, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 17, 12, '你对那悖逆之家说：你们不知道这些事是甚么意思么？你要告诉他们说，巴比伦王曾到耶路撒冷，将其中的君王和首领带到巴比伦自己那里去。'),
('CUV', '以西结书', 26, 17, 13, '从以色列的宗室中取一人与他立约，使他发誓，并将国中有势力的人掳去，'),
('CUV', '以西结书', 26, 17, 14, '使国低微不能自强，惟因守盟约得以存立。'),
('CUV', '以西结书', 26, 17, 15, '他却背叛巴比伦王，打发使者往埃及去，要他们给他马匹和多民。他岂能亨通呢？行这样事的人岂能逃脱呢？他背约岂能逃脱呢？'),
('CUV', '以西结书', 26, 17, 16, '他轻看向王所起的誓，背弃王与他所立的约。主耶和华说：我指著我的永生起誓，他定要死在立他作王、巴比伦王的京都。'),
('CUV', '以西结书', 26, 17, 17, '敌人筑垒造台，与他打仗的时候，为要剪除多人，法老虽领大军队和大群众，还是不能帮助他。'),
('CUV', '以西结书', 26, 17, 18, '他轻看誓言，背弃盟约，已经投降，却又做这一切的事，他必不能逃脱。'),
('CUV', '以西结书', 26, 17, 19, '所以主耶和华如此说：我指著我的永生起誓，他既轻看指我所起的誓，背弃指我所立的约，我必要使这罪归在他头上。'),
('CUV', '以西结书', 26, 17, 20, '我必将我的网撒在他身上，他必在我的网罗中缠住。我必带他到巴比伦，并要在那里因他干犯我的罪刑罚他。'),
('CUV', '以西结书', 26, 17, 21, '他的一切军队，凡逃跑的，都必倒在刀下；所剩下的，也必分散四方（方：原文是风）。你们就知道说这话的是我─耶和华。'),
('CUV', '以西结书', 26, 17, 22, '主耶和华如此说：我要将香柏树梢拧去栽上，就是从尽尖的嫩枝中折一嫩枝，栽于极高的山上；'),
('CUV', '以西结书', 26, 17, 23, '在以色列高处的山栽上。他就生枝子，结果子，成为佳美的香柏树，各类飞鸟都必宿在其下，就是宿在枝子的荫下。'),
('CUV', '以西结书', 26, 17, 24, '田野的树木都必知道我─耶和华使高树矮小，矮树高大；青树枯干，枯树发旺。我─耶和华如此说，也如此行了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 18, 1, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 18, 2, '你们在以色列地怎么用这俗语说父亲吃了酸葡萄，儿子的牙酸倒了呢？'),
('CUV', '以西结书', 26, 18, 3, '主耶和华说：我指著我的永生起誓，你们在以色列中，必不再有用这俗语的因由。'),
('CUV', '以西结书', 26, 18, 4, '看哪，世人都是属我的；为父的怎样属我，为子的也照样属我；犯罪的，他必死亡。'),
('CUV', '以西结书', 26, 18, 5, '人若是公义，且行正直与合理的事：'),
('CUV', '以西结书', 26, 18, 6, '未曾在山上吃过祭偶像之物，未曾仰望以色列家的偶像，未曾玷污邻舍的妻，未曾在妇人的经期内亲近他，'),
('CUV', '以西结书', 26, 18, 7, '未曾亏负人，乃将欠债之人的当头还给他；未曾抢夺人的物件，却将食物给饥饿的人吃，将衣服给赤身的人穿；'),
('CUV', '以西结书', 26, 18, 8, '未曾向借钱的弟兄取利，也未曾向借粮的弟兄多要，缩手不作罪孽，在两人之间，按至理判断；'),
('CUV', '以西结书', 26, 18, 9, '遵行我的律例，谨守我的典章，按诚实行事─这人是公义的，必定存活。这是主耶和华说的。'),
('CUV', '以西结书', 26, 18, 10, '他若生一个儿子，作强盗，是流人血的，不行以上所说之善，反行其中之恶，乃在山上吃过祭偶像之物，并玷污邻舍的妻，'),
('CUV', '以西结书', 26, 18, 11, 'a'),
('CUV', '以西结书', 26, 18, 12, '亏负困苦和穷乏的人，抢夺人的物，未曾将当头还给人，仰望偶像，并行可憎的事，'),
('CUV', '以西结书', 26, 18, 13, '向借钱的弟兄取利，向借粮的弟兄多要─这人岂能存活呢？他必不能存活。他行这一切可憎的事，必要死亡，他的罪（原文是血）必归到他身上。'),
('CUV', '以西结书', 26, 18, 14, '他若生一个儿子，见父亲所犯的一切罪便惧怕（有古卷：思量），不照样去做；'),
('CUV', '以西结书', 26, 18, 15, '未曾在山上吃过祭偶像之物，未曾仰望以色列家的偶像，未曾玷污邻舍的妻，'),
('CUV', '以西结书', 26, 18, 16, '未曾亏负人，未曾取人的当头，未曾抢夺人的物件，却将食物给饥饿的人吃，将衣服给赤身的人穿，'),
('CUV', '以西结书', 26, 18, 17, '缩手不害贫穷人，未曾向借钱的弟兄取利，也未曾向借粮的弟兄多要；他顺从我的典章，遵行我的律例，就不因父亲的罪孽死亡，定要存活。'),
('CUV', '以西结书', 26, 18, 18, '至于他父亲；因为欺人太甚，抢夺弟兄，在本国的民中行不善，他必因自己的罪孽死亡。'),
('CUV', '以西结书', 26, 18, 19, '你们还说：儿子为何不担当父亲的罪孽呢？儿子行正直与合理的事，谨守遵行我的一切律例，他必定存活。'),
('CUV', '以西结书', 26, 18, 20, '惟有犯罪的，他必死亡。儿子必不担当父亲的罪孽，父亲也不担当儿子的罪孽。义人的善果必归自己，恶人的恶报也必归自己。'),
('CUV', '以西结书', 26, 18, 21, '恶人若回头离开所做的一切罪恶，谨守我一切的律例，行正直与合理的事，他必定存活，不致死亡。'),
('CUV', '以西结书', 26, 18, 22, '他所犯的一切罪过都不被记念，因所行的义，他必存活。'),
('CUV', '以西结书', 26, 18, 23, '主耶和华说：恶人死亡，岂是我喜悦的么？不是喜悦他回头离开所行的道存活么？'),
('CUV', '以西结书', 26, 18, 24, '义人若转离义行而作罪孽，照著恶人所行一切可憎的事而行，他岂能存活么？他所行的一切义都不被记念；他必因所犯的罪、所行的恶死亡。'),
('CUV', '以西结书', 26, 18, 25, '你们还说：主的道不公平！以色列家啊，你们当听，我的道岂不公平么？你们的道岂不是不公平么？'),
('CUV', '以西结书', 26, 18, 26, '义人若转离义行而作罪孽死亡，他是因所作的罪孽死亡。'),
('CUV', '以西结书', 26, 18, 27, '再者，恶人若回头离开所行的恶，行正直与合理的事，他必将性命救活了。'),
('CUV', '以西结书', 26, 18, 28, '因为他思量，回头离开所犯的一切罪过，必定存活，不致死亡。'),
('CUV', '以西结书', 26, 18, 29, '以色列家还说：主的道不公平！以色列家啊，我的道岂不公平么？你们的道岂不是不公平么？'),
('CUV', '以西结书', 26, 18, 30, '所以主耶和华说：以色列家啊，我必按你们各人所行的审判你们。你们当回头离开所犯的一切罪过。这样，罪孽必不使你们败亡。'),
('CUV', '以西结书', 26, 18, 31, '你们要将所犯的一切罪过尽行抛弃，自做一个新心和新灵。以色列家啊，你们何必死亡呢？'),
('CUV', '以西结书', 26, 18, 32, '主耶和华说：我不喜悦那死人之死，所以你们当回头而存活。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 19, 1, '你当为以色列的王作起哀歌，'),
('CUV', '以西结书', 26, 19, 2, '说：你的母亲是甚么呢？是个母狮子，蹲伏在狮子中间，在少壮狮子中养育小狮子。'),
('CUV', '以西结书', 26, 19, 3, '在他小狮子中养大一个，成了少壮狮子，学会抓食而吃人。'),
('CUV', '以西结书', 26, 19, 4, '列国听见了就把他捉在他们的坑中，用钩子拉到埃及地去。'),
('CUV', '以西结书', 26, 19, 5, '母狮见自己等候失了指望，就从他小狮子中又将一个养为少壮狮子。'),
('CUV', '以西结书', 26, 19, 6, '他在众狮子中走来走去，成了少壮狮子，学会抓食而吃人。'),
('CUV', '以西结书', 26, 19, 7, '他知道列国的宫殿，又使他们的城邑变为荒场；因他咆哮的声音，遍地和其中所有的就都荒废。'),
('CUV', '以西结书', 26, 19, 8, '于是四围邦国各省的人来攻击他，将网撒在他身上，捉在他们的坑中。'),
('CUV', '以西结书', 26, 19, 9, '他们用钩子钩住他，将他放在笼中，带到巴比伦王那里，将他放入坚固之所，使他的声音在以色列山上不再听见。'),
('CUV', '以西结书', 26, 19, 10, '你的母亲先前如葡萄树，极其茂盛（原文是在你血中），栽于水旁。因为水多，就多结果子，满生枝子；'),
('CUV', '以西结书', 26, 19, 11, '生出坚固的枝干，可作掌权者的杖。这枝干高举在茂密的枝中，而且他生长高大，枝子繁多，远远可见。'),
('CUV', '以西结书', 26, 19, 12, '但这葡萄树因忿怒被拔出摔在地上；东风吹干其上的果子，坚固的枝干折断枯干，被火烧毁了；'),
('CUV', '以西结书', 26, 19, 13, '如今栽于旷野干旱无水之地。'),
('CUV', '以西结书', 26, 19, 14, '火也从他枝干中发出，烧灭果子，以致没有坚固的枝干可作掌权者的杖。这是哀歌，也必用以作哀歌。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 20, 1, '第七年五月初十日，有以色列的几个长老来求问耶和华，坐在我面前。'),
('CUV', '以西结书', 26, 20, 2, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 20, 3, '人子啊，你要告诉以色列的长老说，主耶和华如此说：你们来是求问我么？主耶和华说：我指著我的永生起誓，我必不被你们求问。'),
('CUV', '以西结书', 26, 20, 4, '人子啊，你要审问审问他们么？你当使他们知道他们列祖那些可憎的事，'),
('CUV', '以西结书', 26, 20, 5, '对他们说，主耶和华如此说：当日我拣选以色列，向雅各家的后裔起誓，在埃及地将自己向他们显现，说：我是耶和华─你们的神。'),
('CUV', '以西结书', 26, 20, 6, '那日我向他们起誓，必领他们出埃及地，到我为他们察看的流奶与蜜之地；那地在万国中是有荣耀的。'),
('CUV', '以西结书', 26, 20, 7, '我对他们说，你们各人要抛弃眼所喜爱那可憎之物，不可因埃及的偶像玷污自己。我是耶和华─你们的神。'),
('CUV', '以西结书', 26, 20, 8, '他们却悖逆我，不肯听从我，不抛弃他们眼所喜爱那可憎之物，不离弃埃及的偶像。我就说，我要将我的忿怒倾在他们身上，在埃及地向他们成就我怒中所定的。'),
('CUV', '以西结书', 26, 20, 9, '我却为我名的缘故没有这样行，免得我名在他们所住的列国人眼前被亵渎；我领他们出埃及地，在这列国人的眼前将自己向他们显现。'),
('CUV', '以西结书', 26, 20, 10, '这样，我就使他们出埃及地，领他们到旷野，'),
('CUV', '以西结书', 26, 20, 11, '将我的律例赐给他们，将我的典章指示他们；人若遵行就必因此活著。'),
('CUV', '以西结书', 26, 20, 12, '又将我的安息日赐给他们，好在我与他们中间为证据，使他们知道我─耶和华是叫他们成为圣的。'),
('CUV', '以西结书', 26, 20, 13, '以色列家却在旷野悖逆我，不顺从我的律例，厌弃我的典章（人若遵行就必因此活著），大大干犯我的安息日。我就说，要在旷野将我的忿怒倾在他们身上，灭绝他们。'),
('CUV', '以西结书', 26, 20, 14, '我却为我名的缘故，没有这样行，免得我的名在我领他们出埃及的列国人眼前被亵渎。'),
('CUV', '以西结书', 26, 20, 15, '并且我在旷野向他们起誓，必不领他们进入我所赐给他们流奶与蜜之地（那地在万国中是有荣耀的）；'),
('CUV', '以西结书', 26, 20, 16, '因为他们厌弃我的典章，不顺从我的律例，干犯我的安息日，他们的心随从自己的偶像。'),
('CUV', '以西结书', 26, 20, 17, '虽然如此，我眼仍顾惜他们，不毁灭他们，不在旷野将他们灭绝净尽。'),
('CUV', '以西结书', 26, 20, 18, '我在旷野对他们的儿女说：不要遵行你们父亲的律例，不要谨守他们的恶规，也不要因他们的偶像玷污自己。'),
('CUV', '以西结书', 26, 20, 19, '我是耶和华─你们的神，你们要顺从我的律例，谨守遵行我的典章，'),
('CUV', '以西结书', 26, 20, 20, '且以我的安息日为圣。这日在我与你们中间为证据，使你们知道我是耶和华─你们的神。'),
('CUV', '以西结书', 26, 20, 21, '只是他们的儿女悖逆我，不顺从我的律例，也不谨守遵行我的典章（人若遵行就必因此活著），干犯我的安息日。我就说，要将我的忿怒倾在他们身上，在旷野向他们成就我怒中所定的。'),
('CUV', '以西结书', 26, 20, 22, '虽然如此，我却为我名的缘故缩手没有这样行，免得我的名在我领他们出埃及的列国人眼前被亵渎。'),
('CUV', '以西结书', 26, 20, 23, '并且我在旷野向他们起誓，必将他们分散在列国，四散在列邦；'),
('CUV', '以西结书', 26, 20, 24, '因为他们不遵行我的典章，竟厌弃我的律例，干犯我的安息日，眼目仰望他们父亲的偶像。'),
('CUV', '以西结书', 26, 20, 25, '我也任他们遵行不美的律例，谨守不能使人活著的恶规。'),
('CUV', '以西结书', 26, 20, 26, '因他们将一切头生的经火，我就任凭他们在这供献的事上玷污自己，好叫他们凄凉，使他们知道我是耶和华。'),
('CUV', '以西结书', 26, 20, 27, '人子啊，你要告诉以色列家说，主耶和华如此说：你们的列祖在得罪我的事上亵渎我；'),
('CUV', '以西结书', 26, 20, 28, '因为我领他们到了我起誓应许赐给他们的地，他们看见各高山、各茂密树，就在那里献祭，奉上惹我发怒的供物，也在那里焚烧馨香的祭牲，并浇上奠祭。'),
('CUV', '以西结书', 26, 20, 29, '我就对他们说：你们所上的那高处叫甚么呢？（那高处的名字叫巴麻直到今日。）'),
('CUV', '以西结书', 26, 20, 30, '所以你要对以色列家说，主耶和华如此说：你们仍照你们列祖所行的玷污自己么？仍照他们可憎的事行邪淫么？'),
('CUV', '以西结书', 26, 20, 31, '你们奉上供物使你们儿子经火的时候，仍将一切偶像玷污自己，直到今日么？以色列家啊，我岂被你们求问么？主耶和华说：我指著我的永生起誓，我必不被你们求问。'),
('CUV', '以西结书', 26, 20, 32, '你们说：我们要像外邦人和列国的宗族一样，去事奉木头与石头。你们所起的这心意万不能成就。'),
('CUV', '以西结书', 26, 20, 33, '主耶和华说：我指著我的永生起誓，我总要作王，用大能的手和伸出来的膀臂，并倾出来的忿怒，治理你们。'),
('CUV', '以西结书', 26, 20, 34, '我必用大能的手和伸出来的膀臂，并倾出来的忿怒，将你们从万民中领出来，从分散的列国内聚集你们。'),
('CUV', '以西结书', 26, 20, 35, '我必带你们到外邦人的旷野，在那里当面刑罚你们。'),
('CUV', '以西结书', 26, 20, 36, '我怎样在埃及地的旷野刑罚你们的列祖，也必照样刑罚你们。这是主耶和华说的。'),
('CUV', '以西结书', 26, 20, 37, '我必使你们从杖下经过，使你们被约拘束。'),
('CUV', '以西结书', 26, 20, 38, '我必从你们中间除净叛逆和得罪我的人，将他们从所寄居的地方领出来，他们却不得入以色列地。你们就知道我是耶和华。'),
('CUV', '以西结书', 26, 20, 39, '以色列家啊，至于你们，主耶和华如此说：从此以后若不听从我，就任凭你们去事奉偶像，只是不可再因你们的供物和偶像亵渎我的圣名。'),
('CUV', '以西结书', 26, 20, 40, '主耶和华说：在我的圣山，就是以色列高处的山，所有以色列的全家都要事奉我。我要在那里悦纳你们，向你们要供物和初熟的土产，并一切的圣物。'),
('CUV', '以西结书', 26, 20, 41, '我从万民中领你们出来，从分散的列国内聚集你们，那时我必悦纳你们好像馨香之祭，要在外邦人眼前在你们身上显为圣。'),
('CUV', '以西结书', 26, 20, 42, '我领你们进入以色列地，就是我起誓应许赐给你们列祖之地，那时你们就知道我是耶和华。'),
('CUV', '以西结书', 26, 20, 43, '你们在那里要追念玷污自己的行动作为，又要因所做的一切恶事厌恶自己。'),
('CUV', '以西结书', 26, 20, 44, '主耶和华说：以色列家啊，我为我名的缘故，不照著你们的恶行和你们的坏事待你们；你们就知道我是耶和华。'),
('CUV', '以西结书', 26, 20, 45, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 20, 46, '人子啊，你要面向南方，向南滴下预言攻击南方田野的树林。'),
('CUV', '以西结书', 26, 20, 47, '对南方的树林说，要听耶和华的话。主耶和华如此说：我必使火在你中间著起，烧灭你中间的一切青树和枯树，猛烈的火燄必不熄灭。从南到北，人的脸面都被烧焦。'),
('CUV', '以西结书', 26, 20, 48, '凡有血气的都必知道是我─耶和华使火著起，这火必不熄灭。'),
('CUV', '以西结书', 26, 20, 49, '于是我说：哎！主耶和华啊，人都指著我说：他岂不是说比喻的么？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 21, 1, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 21, 2, '人子啊，你要面向耶路撒冷和圣所滴下预言，攻击以色列地。'),
('CUV', '以西结书', 26, 21, 3, '对以色列地说，耶和华如此说：我与你为敌，并要拔刀出鞘，从你中间将义人和恶人一并剪除。'),
('CUV', '以西结书', 26, 21, 4, '我既要从你中间剪除义人和恶人，所以我的刀要出鞘，自南至北攻击一切有血气的；'),
('CUV', '以西结书', 26, 21, 5, '一切有血气的就知道我─耶和华已经拔刀出鞘，必不再入鞘。'),
('CUV', '以西结书', 26, 21, 6, '人子啊，你要叹息，在他们眼前弯著腰，苦苦地叹息。'),
('CUV', '以西结书', 26, 21, 7, '他们问你说：为何叹息呢﹖你就说：因为有风声、灾祸要来。人心都必消化，手都发软，精神衰败，膝弱如水。看哪，这灾祸临近，必然成就。这是主耶和华说的。'),
('CUV', '以西结书', 26, 21, 8, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 21, 9, '人子啊，你要预言。耶和华吩咐我如此说：有刀、有刀，是磨快擦亮的；'),
('CUV', '以西结书', 26, 21, 10, '磨快为要行杀戮，擦亮为要像闪电。我们岂可快乐么﹖罚我子的杖藐视各树。'),
('CUV', '以西结书', 26, 21, 11, '这刀已经交给人擦亮，为要应手使用。这刀已经磨快擦亮，好交在行杀戮的人手中。'),
('CUV', '以西结书', 26, 21, 12, '人子啊，你要呼喊哀号，因为这刀临到我的百姓和以色列一切的首领。他们和我的百姓都交在刀下，所以你要拍腿叹息。'),
('CUV', '以西结书', 26, 21, 13, '有试验的事；若那藐视的杖归于无有，怎么样呢﹖这是主耶和华说的。'),
('CUV', '以西结书', 26, 21, 14, '人子啊，你要拍掌预言。我─耶和华要使这刀，就是致死伤的刀，一连三次加倍刺人，进入他们的内屋，使大人受死伤的就是这刀。'),
('CUV', '以西结书', 26, 21, 15, '我设立这恐吓人的刀，攻击他们的一切城门，使他们的心消化，加增他们跌倒的事。哎！这刀造得像闪电，磨得尖利，要行杀戮。'),
('CUV', '以西结书', 26, 21, 16, '刀啊，你归在右边，摆在左边；你面向哪方，就向那方杀戮。'),
('CUV', '以西结书', 26, 21, 17, '我也要拍掌，并要使我的忿怒止息。这是我─耶和华说的。'),
('CUV', '以西结书', 26, 21, 18, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 21, 19, '人子啊，你要定出两条路，好使巴比伦王的刀来。这两条路必从一地分出来，又要在通城的路口上画出一只手来。'),
('CUV', '以西结书', 26, 21, 20, '你要定出一条路，使刀来到亚扪人的拉巴；又要定出一条路，使刀来到犹大的坚固城耶路撒冷。'),
('CUV', '以西结书', 26, 21, 21, '因为巴比伦王站在岔路那里，在两条路口上要占卜。他摇签（原文是箭）求问神像，察看牺牲的肝；'),
('CUV', '以西结书', 26, 21, 22, '在右手中拿著为耶路撒冷占卜的签，使他安设撞城锤，张口叫杀，扬声呐喊，筑垒造台，以撞城锤，攻打城门。'),
('CUV', '以西结书', 26, 21, 23, '据那些曾起誓的犹大人看来，这是虚假的占卜；但巴比伦王要使他们想起罪孽，以致将他们捉住。'),
('CUV', '以西结书', 26, 21, 24, '主耶和华如此说：因你们的过犯显露，使你们的罪孽被记念，以致你们的罪恶在行为上都彰显出来；又因你们被记念，就被捉住。'),
('CUV', '以西结书', 26, 21, 25, '你这受死伤行恶的以色列王啊，罪孽的尽头到了，受报的日子已到。'),
('CUV', '以西结书', 26, 21, 26, '主耶和华如此说：当除掉冠，摘下冕，景况必不再像先前；要使卑者升为高，使高者降为卑。'),
('CUV', '以西结书', 26, 21, 27, '我要将这国倾覆，倾覆，而又倾覆；这国也必不再有，直等到那应得的人来到，我就赐给他。'),
('CUV', '以西结书', 26, 21, 28, '人子啊，要发预言说：主耶和华论到亚扪人和他们的凌辱，吩咐我如此说：有刀，有拔出来的刀，已经擦亮，为行杀戮，使他像闪电以行吞灭。'),
('CUV', '以西结书', 26, 21, 29, '人为你见虚假的异象，行谎诈的占卜，使你倒在受死伤之恶人的颈项上。他们罪孽到了尽头，受报的日子已到。'),
('CUV', '以西结书', 26, 21, 30, '你将刀收入鞘罢！在你受造之处、生长之地，我必刑罚你。'),
('CUV', '以西结书', 26, 21, 31, '我必将我的恼恨倒在你身上，将我烈怒的火喷在你身上；又将你交在善于杀灭的畜类人手中。'),
('CUV', '以西结书', 26, 21, 32, '你必当柴被火焚烧，你的血必流在国中，你必不再被记念，因为这是我─耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 22, 1, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 22, 2, '人子啊，你要审问审问这流人血的城么﹖当使他知道他一切可憎的事。'),
('CUV', '以西结书', 26, 22, 3, '你要说，主耶和华如此说：哎！这城有流人血的事在其中，叫他受报的日期来到，又做偶像玷污自己，陷害自己。'),
('CUV', '以西结书', 26, 22, 4, '你因流了人的血，就为有罪；你做了偶像，就玷污自己，使你受报之日临近，报应之年来到。所以我叫你受列国的凌辱和列邦的讥诮。'),
('CUV', '以西结书', 26, 22, 5, '你这名臭、多乱的城啊，那些离你近、离你远的都必讥诮你。'),
('CUV', '以西结书', 26, 22, 6, '看哪，以色列的首领各逞其能，在你中间流人之血。'),
('CUV', '以西结书', 26, 22, 7, '在你中间有轻慢父母的，有欺压寄居的，有亏负孤儿寡妇的。'),
('CUV', '以西结书', 26, 22, 8, '你藐视了我的圣物，干犯了我的安息日。'),
('CUV', '以西结书', 26, 22, 9, '在你中间有谗谤人、流人血的；有在山上吃过祭偶像之物的，有行淫乱的。'),
('CUV', '以西结书', 26, 22, 10, '在你中间有露继母下体羞辱父亲的，有玷辱月经不洁净之妇人的。'),
('CUV', '以西结书', 26, 22, 11, '这人与邻舍的妻行可憎的事；那人贪淫玷污儿妇；还有玷辱同父之姊妹的。'),
('CUV', '以西结书', 26, 22, 12, '在你中间有为流人血受贿赂的；有向借钱的弟兄取利，向借粮的弟兄多要的。且因贪得无餍，欺压邻舍夺取财物，竟忘了我。这是主耶和华说的。'),
('CUV', '以西结书', 26, 22, 13, '看哪，我因你所得不义之财和你中间所流的血，就拍掌叹息。'),
('CUV', '以西结书', 26, 22, 14, '到了我惩罚你的日子，你的心还能忍受么﹖你的手还能有力么﹖我─耶和华说了这话，就必照著行。'),
('CUV', '以西结书', 26, 22, 15, '我必将你分散在列国，四散在列邦。我也必从你中间除掉你的污秽。'),
('CUV', '以西结书', 26, 22, 16, '你必在列国人的眼前因自己所行的被亵渎，你就知道我是耶和华。'),
('CUV', '以西结书', 26, 22, 17, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 22, 18, '人子啊，以色列家在我看为渣滓。他们都是炉中的铜、锡、铁、铅，都是银渣滓。'),
('CUV', '以西结书', 26, 22, 19, '所以主耶和华如此说：因你们都成为渣滓，我必聚集你们在耶路撒冷中。'),
('CUV', '以西结书', 26, 22, 20, '人怎样将银、铜、铁、铅、锡聚在炉中，吹火镕化；照样，我也要发怒气和忿怒，将你们聚集放在城中，镕化你们。'),
('CUV', '以西结书', 26, 22, 21, '我必聚集你们，把我烈怒的火吹在你们身上，你们就在其中镕化。'),
('CUV', '以西结书', 26, 22, 22, '银子怎样镕化在炉中，你们也必照样镕化在城中，你们就知道我─耶和华是将忿怒倒在你们身上了。'),
('CUV', '以西结书', 26, 22, 23, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 22, 24, '人子啊，你要对这地说：你是未得洁净之地，在恼恨的日子也没有雨下在你以上。'),
('CUV', '以西结书', 26, 22, 25, '其中的先知同谋背叛，如咆哮的狮子抓撕掠物。他们吞灭人民，抢夺财宝，使这地多有寡妇。'),
('CUV', '以西结书', 26, 22, 26, '其中的祭司强解我的律法，亵渎我的圣物，不分别圣的和俗的，也不使人分辨洁净的和不洁净的，又遮眼不顾我的安息日；我也在他们中间被亵慢。'),
('CUV', '以西结书', 26, 22, 27, '其中的首领仿佛豺狼抓撕掠物，杀人流血，伤害人命，要得不义之财。'),
('CUV', '以西结书', 26, 22, 28, '其中的先知为百姓用未泡透的灰抹墙，就是为他们见虚假的异象，用谎诈的占卜，说：主耶和华如此说，其实耶和华没有说。'),
('CUV', '以西结书', 26, 22, 29, '国内众民一味地欺压，惯行抢夺，亏负困苦穷乏的，背理欺压寄居的。'),
('CUV', '以西结书', 26, 22, 30, '我在他们中间寻找一人重修墙垣，在我面前为这国站在破口防堵，使我不灭绝这国，却找不著一个。'),
('CUV', '以西结书', 26, 22, 31, '所以我将恼恨倒在他们身上，用烈怒的火灭了他们，照他们所行的报应在他们头上。这是主耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 23, 1, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 23, 2, '人子啊，有两个女子，是一母所生，'),
('CUV', '以西结书', 26, 23, 3, '他们在埃及行邪淫，在幼年时行邪淫。他们在那里作处女的时候，有人拥抱他们的怀，抚摸他们的乳。'),
('CUV', '以西结书', 26, 23, 4, '他们的名字，姊姊名叫阿荷拉，妹妹名叫阿荷利巴。他们都归于我，生了儿女。论到他们的名字，阿荷拉就是撒玛利亚，阿荷利巴就是耶路撒冷。'),
('CUV', '以西结书', 26, 23, 5, '阿荷拉归我之后行邪淫，贪恋所爱的人，就是他的邻邦亚述人。'),
('CUV', '以西结书', 26, 23, 6, '这些人都穿蓝衣，作省长、副省长，都骑著马，是可爱的少年人。'),
('CUV', '以西结书', 26, 23, 7, '阿荷拉就与亚述人中最美的男子放纵淫行，他因所恋爱之人的一切偶像，玷污自己。'),
('CUV', '以西结书', 26, 23, 8, '自从在埃及的时候，他就没有离开淫乱，因为他年幼作处女的时候，埃及人与他行淫，抚摸他的乳，纵欲与他行淫。'),
('CUV', '以西结书', 26, 23, 9, '因此，我将他交在他所爱的人手中，就是他所恋爱的亚述人手中。'),
('CUV', '以西结书', 26, 23, 10, '他们就露了他的下体，掳掠他的儿女，用刀杀了他，使他在妇女中留下臭名，因他们向他施行审判。'),
('CUV', '以西结书', 26, 23, 11, '他妹妹阿荷利巴虽然看见了，却还贪恋，比他姊姊更丑；行淫乱比他姊姊更多。'),
('CUV', '以西结书', 26, 23, 12, '他贪恋邻邦的亚述人，就是穿极华美的衣服，骑著马的省长、副省长，都是可爱的少年人。'),
('CUV', '以西结书', 26, 23, 13, '我看见他被玷污了，他姊妹二人同行一路。'),
('CUV', '以西结书', 26, 23, 14, '阿荷利巴又加增淫行，因他看见人像画在墙上，就是用丹色所画迦勒底人的像，'),
('CUV', '以西结书', 26, 23, 15, '腰间系著带子，头上有下垂的裹头巾，都是军长的形状，仿照巴比伦人的形像；他们的故土就是迦勒底。'),
('CUV', '以西结书', 26, 23, 16, '阿荷利巴一看见就贪恋他们，打发使者往迦勒底去见他们。'),
('CUV', '以西结书', 26, 23, 17, '巴比伦人就来登他爱情的床，与他行淫玷污他。他被玷污，随后心里与他们生疏。'),
('CUV', '以西结书', 26, 23, 18, '这样，他显露淫行，又显露下体；我心就与他生疏，像先前与他姊姊生疏一样。'),
('CUV', '以西结书', 26, 23, 19, '他还加增他的淫行，追念他幼年在埃及地行邪淫的日子，'),
('CUV', '以西结书', 26, 23, 20, '贪恋情人身壮精足，如驴如马。'),
('CUV', '以西结书', 26, 23, 21, '这样，你就想起你幼年的淫行。那时，埃及人拥抱你的怀，抚摸你的乳。'),
('CUV', '以西结书', 26, 23, 22, '阿荷利巴啊，主耶和华如此说：我必激动你先爱而后生疏的人来攻击你。我必使他们来，在你四围攻击你。'),
('CUV', '以西结书', 26, 23, 23, '所来的就是巴比伦人、迦勒底的众人、比割人、书亚人、哥亚人，同著他们的还有亚述众人，乃是作省长、副省长、作军长有名声的，都骑著马，是可爱的少年人。'),
('CUV', '以西结书', 26, 23, 24, '他们必带兵器、战车、辎重车，率领大众来攻击你。他们要拿大小盾牌，顶盔摆阵，在你四围攻击你。我要将审判的事交给他们，他们必按著自己的条例审判你。'),
('CUV', '以西结书', 26, 23, 25, '我必以忌恨攻击你；他们必以忿怒办你。他们必割去你的鼻子和耳朵；你遗留（或译：余剩；下同）的人必倒在刀下。他们必掳去你的儿女；你所遗留的必被火焚烧。'),
('CUV', '以西结书', 26, 23, 26, '他们必剥去你的衣服，夺取你华美的宝器。'),
('CUV', '以西结书', 26, 23, 27, '这样，我必使你的淫行和你从埃及地染来的淫乱止息了，使你不再仰望亚述，也不再追念埃及。'),
('CUV', '以西结书', 26, 23, 28, '主耶和华如此说：我必将你交在你所恨恶的人手中，就是你心与他生疏的人手中。'),
('CUV', '以西结书', 26, 23, 29, '他们必以恨恶办你，夺取你一切劳碌得来的，留下你赤身露体。你淫乱的下体，连你的淫行，带你的淫乱，都被显露。'),
('CUV', '以西结书', 26, 23, 30, '人必向你行这些事；因为你随从外邦人行邪淫，被他们的偶像玷污了。'),
('CUV', '以西结书', 26, 23, 31, '你走了你姊姊所走的路，所以我必将他的杯交在你手中。'),
('CUV', '以西结书', 26, 23, 32, '主耶和华如此说：你必喝你姊姊所喝的杯；那杯又深又广，盛得甚多，使你被人嗤笑讥刺。'),
('CUV', '以西结书', 26, 23, 33, '你必酩酊大醉，满有愁苦，喝干你姊姊撒玛利亚的杯，就是令人惊骇凄凉的杯。'),
('CUV', '以西结书', 26, 23, 34, '你必喝这杯，以致喝尽。杯破又龈杯片，撕裂自己的乳；因为这事我曾说过。这是主耶和华说的。'),
('CUV', '以西结书', 26, 23, 35, '主耶和华如此说：因你忘记我，将我丢在背后，所以你要担当你淫行和淫乱的报应。'),
('CUV', '以西结书', 26, 23, 36, '耶和华又对我说：人子啊，你要审问阿荷拉与阿荷利巴么﹖当指出他们所行可憎的事。'),
('CUV', '以西结书', 26, 23, 37, '他们行淫，手中有杀人的血，又与偶像行淫，并使他们为我所生的儿女经火烧给偶像。'),
('CUV', '以西结书', 26, 23, 38, '此外，他们还有向我所行的，就是同日玷污我的圣所，干犯我的安息日。'),
('CUV', '以西结书', 26, 23, 39, '他们杀了儿女献与偶像，当天又入我的圣所，将圣所亵渎了。他们在我殿中所行的乃是如此。'),
('CUV', '以西结书', 26, 23, 40, '况且你们二妇打发使者去请远方人。使者到他们那里，他们就来了。你们为他们沐浴己身，粉饰眼目，佩戴妆饰，'),
('CUV', '以西结书', 26, 23, 41, '坐在华美的床上，前面摆设桌案，将我的香料膏油摆在其上。'),
('CUV', '以西结书', 26, 23, 42, '在那里有群众安逸欢乐的声音，并有粗俗的人和酒徒从旷野同来，把镯子戴在二妇的手上，把华冠戴在他们的头上。'),
('CUV', '以西结书', 26, 23, 43, '我论这行淫衰老的妇人说：现在人还要与他行淫，他也要与人行淫。'),
('CUV', '以西结书', 26, 23, 44, '人与阿荷拉，并阿荷利巴二淫妇茍合，好像与妓女苟合。'),
('CUV', '以西结书', 26, 23, 45, '必有义人，照审判淫妇和流人血的妇人之例，审判他们；因为他们是淫妇，手中有杀人的血。'),
('CUV', '以西结书', 26, 23, 46, '主耶和华如此说：我必使多人来攻击他们，使他们抛来抛去，被人抢夺。'),
('CUV', '以西结书', 26, 23, 47, '这些人必用石头打死他们，用刀剑杀害他们，又杀戮他们的儿女，用火焚烧他们的房屋。'),
('CUV', '以西结书', 26, 23, 48, '这样，我必使淫行从境内止息，好叫一切妇人都受警戒，不效法你们的淫行。'),
('CUV', '以西结书', 26, 23, 49, '人必照著你们的淫行报应你们；你们要担当拜偶像的罪，就知道我是主耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 24, 1, '第九年十月初十日，耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 24, 2, '人子啊，今日正是巴比伦王就近耶路撒冷的日子，你要将这日记下，'),
('CUV', '以西结书', 26, 24, 3, '要向这悖逆之家设比喻说，主耶和华如此说：将锅放在火上，放好了，就倒水在其中；'),
('CUV', '以西结书', 26, 24, 4, '将肉块，就是一切肥美的肉块、腿，和肩都聚在其中，拿美好的骨头把锅装满；'),
('CUV', '以西结书', 26, 24, 5, '取羊群中最好的，将柴堆在锅下，使锅开滚，好把骨头煮在其中。'),
('CUV', '以西结书', 26, 24, 6, '主耶和华如此说：祸哉！这流人血的城，就是长锈的锅。其中的锈未曾除掉，须要将肉块从其中一一取出来，不必为他拈阄。'),
('CUV', '以西结书', 26, 24, 7, '城中所流的血倒在净光的磐石上，不倒在地上，用土掩盖。'),
('CUV', '以西结书', 26, 24, 8, '这城中所流的血倒在净光的磐石上，不得掩盖，乃是出于我，为要发忿怒施行报应。'),
('CUV', '以西结书', 26, 24, 9, '所以主耶和华如此说：祸哉！这流人血的城，我也必大堆火柴，'),
('CUV', '以西结书', 26, 24, 10, '添上木柴，使火著旺，将肉煮烂，把汤熬浓，使骨头烤焦；'),
('CUV', '以西结书', 26, 24, 11, '把锅倒空坐在炭火上，使锅烧热，使铜烧红，镕化其中的污秽，除净其上的锈。'),
('CUV', '以西结书', 26, 24, 12, '这锅劳碌疲乏，所长的大锈仍未除掉；这锈就是用火也不能除掉。'),
('CUV', '以西结书', 26, 24, 13, '在你污秽中有淫行，我洁净你，你却不洁净。你的污秽再不能洁净，直等我向你发的忿怒止息。'),
('CUV', '以西结书', 26, 24, 14, '我─耶和华说过的必定成就，必照话而行，必不返回，必不顾惜，也不后悔。人必照你的举动行为审判你。这是主耶和华说的。'),
('CUV', '以西结书', 26, 24, 15, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 24, 16, '人子啊，我要将你眼目所喜爱的忽然取去，你却不可悲哀哭泣，也不可流泪，'),
('CUV', '以西结书', 26, 24, 17, '只可叹息，不可出声，不可办理丧事；头上仍勒裹头巾，脚上仍穿鞋，不可蒙著嘴唇，也不可吃吊丧的食物。'),
('CUV', '以西结书', 26, 24, 18, '于是我将这事早晨告诉百姓，晚上我的妻就死了。次日早晨我便遵命而行。'),
('CUV', '以西结书', 26, 24, 19, '百姓问我说：你这样行与我们有甚么关系，你不告诉我们么﹖'),
('CUV', '以西结书', 26, 24, 20, '我回答他们：耶和华的话临到我说：'),
('CUV', '以西结书', 26, 24, 21, '你告诉以色列家，主耶和华如此说：我必使我的圣所，就是你们势力所夸耀、眼里所喜爱、心中所爱惜的被亵渎，并且你们所遗留的儿女必倒在刀下。'),
('CUV', '以西结书', 26, 24, 22, '那时，你们必行我仆人所行的，不蒙著嘴唇，也不吃吊丧的食物。'),
('CUV', '以西结书', 26, 24, 23, '你们仍要头上勒裹头巾，脚上穿鞋；不可悲哀哭泣。你们必因自己的罪孽相对叹息，渐渐消灭。'),
('CUV', '以西结书', 26, 24, 24, '以西结必这样为你们作预兆；凡他所行的，你们也必照样行。那事来到，你们就知道我是主耶和华。'),
('CUV', '以西结书', 26, 24, 25, '人子啊，我除掉他们所倚靠、所欢喜的荣耀，并眼中所喜爱、心里所重看的儿女。'),
('CUV', '以西结书', 26, 24, 26, '那日逃脱的人岂不来到你这里，使你耳闻这事么﹖'),
('CUV', '以西结书', 26, 24, 27, '你必向逃脱的人开口说话，不再哑口。你必这样为他们作预兆，他们就知道我是耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 25, 1, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 25, 2, '人子啊，你要面向亚扪人说预言，攻击他们，'),
('CUV', '以西结书', 26, 25, 3, '说：你们当听主耶和华的话。主耶和华如此说：我的圣所被亵渎，以色列地变荒凉，犹大家被掳掠；那时，你便因这些事说：阿哈！'),
('CUV', '以西结书', 26, 25, 4, '所以我必将你的地交给东方人为业；他们必在你的地上安营居住，吃你的果子，喝你的奶。'),
('CUV', '以西结书', 26, 25, 5, '我必使拉巴为骆驼场，使亚扪人的地为羊群躺卧之处，你们就知道我是耶和华。'),
('CUV', '以西结书', 26, 25, 6, '主耶和华如此说：因你拍手顿足，以满心的恨恶向以色列地欢喜，'),
('CUV', '以西结书', 26, 25, 7, '所以我伸手攻击你，将你交给列国作为掳物。我必从万民中剪除你，使你从万国中败亡。我必除灭你，你就知道我是耶和华。'),
('CUV', '以西结书', 26, 25, 8, '主耶和华如此说：因摩押和西珥人说：看哪，犹大家与列国无异，'),
('CUV', '以西结书', 26, 25, 9, '所以我要破开摩押边界上的城邑，就是摩押人看为本国之荣耀的伯耶西末、巴力免、基列亭，'),
('CUV', '以西结书', 26, 25, 10, '好使东方人来攻击亚扪人。我必将亚扪人之地交给他们为业，使亚扪人在列国中不再被记念。'),
('CUV', '以西结书', 26, 25, 11, '我必向摩押施行审判，他们就知道我是耶和华。'),
('CUV', '以西结书', 26, 25, 12, '主耶和华如此说：因为以东报仇雪恨，攻击犹大家，向他们报仇，大大有罪，'),
('CUV', '以西结书', 26, 25, 13, '所以主耶和华如此说：我必伸手攻击以东，剪除人与牲畜，使以东从提幔起，人必倒在刀下，地要变为荒凉，直到底但。'),
('CUV', '以西结书', 26, 25, 14, '我必藉我民以色列的手报复以东；以色列民必照我的怒气，按我的忿怒在以东施报，以东人就知道是我施报。这是主耶和华说的。'),
('CUV', '以西结书', 26, 25, 15, '主耶和华如此说：因非利士人向犹大人报仇，就是以恨恶的心报仇雪恨，永怀仇恨，要毁灭他们，'),
('CUV', '以西结书', 26, 25, 16, '所以主耶和华如此说：我必伸手攻击非利士人，剪除基利提人，灭绝沿海剩下的居民。'),
('CUV', '以西结书', 26, 25, 17, '我向他们大施报应，发怒斥责他们。我报复他们的时候，他们就知道我是耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 26, 1, '第十一年十一月初一日，耶和华的话临到我说：'),
('CUV', '以西结书', 26, 26, 2, '人子啊，因推罗向耶路撒冷说：阿哈，那作众民之门的已经破坏，向我开放；他既变为荒场，我必丰盛。'),
('CUV', '以西结书', 26, 26, 3, '所以，主耶和华如此说：推罗啊，我必与你为敌，使许多国民上来攻击你，如同海使波浪涌上来一样。'),
('CUV', '以西结书', 26, 26, 4, '他们必破坏推罗的墙垣，拆毁他的城楼。我也要刮净尘土，使他成为净光的磐石。'),
('CUV', '以西结书', 26, 26, 5, '他必在海中作晒网的地方，也必成为列国的掳物。这是主耶和华说的。'),
('CUV', '以西结书', 26, 26, 6, '属推罗城邑的居民（原文是田间的众女；八节同）必被刀剑杀灭，他们就知道我是耶和华。'),
('CUV', '以西结书', 26, 26, 7, '主耶和华如此说：我必使诸王之王的巴比伦王尼布甲尼撒率领马匹车辆、马兵、军队，和许多人民从北方来攻击你推罗。'),
('CUV', '以西结书', 26, 26, 8, '他必用刀剑杀灭属你城邑的居民，也必造台筑垒举盾牌攻击你。'),
('CUV', '以西结书', 26, 26, 9, '他必安设撞城锤攻破你的墙垣，用铁器拆毁你的城楼。'),
('CUV', '以西结书', 26, 26, 10, '因他的马匹众多，尘土扬起遮蔽你。他进入你的城门，好像人进入已有破口之城。那时，你的墙垣必因骑马的和战车、辎重车的响声震动。'),
('CUV', '以西结书', 26, 26, 11, '他的马蹄必践踏你一切的街道，他必用刀杀戮你的居民；你坚固的柱子（或译：柱像）必倒在地上。'),
('CUV', '以西结书', 26, 26, 12, '人必以你的财宝为掳物，以你的货财为掠物，破坏你的墙垣，拆毁你华美的房屋，将你的石头、木头、尘土都抛在水中。'),
('CUV', '以西结书', 26, 26, 13, '我必使你唱歌的声音止息，人也不再听见你弹琴的声音。'),
('CUV', '以西结书', 26, 26, 14, '我必使你成为净光的磐石，作晒网的地方；你不得再被建造，因为这是主耶和华说的。'),
('CUV', '以西结书', 26, 26, 15, '主耶和华对推罗如此说：在你中间行杀戮，受伤之人唉哼的时候，因你倾倒的响声，海岛岂不都震动么﹖'),
('CUV', '以西结书', 26, 26, 16, '那时靠海的君王必都下位，除去朝服，脱下花衣，披上战兢，坐在地上，时刻发抖，为你惊骇。'),
('CUV', '以西结书', 26, 26, 17, '他们必为你作起哀歌说：你这有名之城，素为航海之人居住，在海上为最坚固的；平日你和居民使一切住在那里的人无不惊恐；现在何竟毁灭了﹖'),
('CUV', '以西结书', 26, 26, 18, '如今在你这倾覆的日子，海岛都必战兢；海中的群岛见你归于无有就都惊惶。'),
('CUV', '以西结书', 26, 26, 19, '主耶和华如此说：推罗啊，我使你变为荒凉，如无人居住的城邑；又使深水漫过你，大水淹没你。'),
('CUV', '以西结书', 26, 26, 20, '那时，我要叫你下入阴府，与古时的人一同在地的深处、久已荒凉之地居住，使你不再有居民。我也要在活人之地显荣耀（我也……荣耀：或译在活人之地不再有荣耀）。'),
('CUV', '以西结书', 26, 26, 21, '我必叫你令人惊恐，不再存留于世；人虽寻找你，却永寻不见。这是主耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 27, 1, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 27, 2, '人子啊，要为推罗作起哀歌，'),
('CUV', '以西结书', 26, 27, 3, '说：你居住海口，是众民的商埠；你的交易通到许多的海岛。主耶和华如此说：推罗啊，你曾说：我是全然美丽的。'),
('CUV', '以西结书', 26, 27, 4, '你的境界在海中，造你的使你全然美丽。'),
('CUV', '以西结书', 26, 27, 5, '他们用示尼珥的松树做你的一切板，用利巴嫩的香柏树做桅杆，'),
('CUV', '以西结书', 26, 27, 6, '用巴珊的橡树做你的桨，用象牙镶嵌基提海岛的黄杨木为坐板（或译：舱板）。'),
('CUV', '以西结书', 26, 27, 7, '你的篷帆是用埃及绣花细麻布做的，可以做你的大旗；你的凉棚是用以利沙岛的蓝色、紫色布做的。'),
('CUV', '以西结书', 26, 27, 8, '西顿和亚发的居民作你荡桨的。推罗啊，你中间的智慧人作掌舵的。'),
('CUV', '以西结书', 26, 27, 9, '迦巴勒的老者和聪明人都在你中间作补缝的；一切泛海的船只和水手都在你中间经营交易的事。'),
('CUV', '以西结书', 26, 27, 10, '波斯人、路德人、弗人在你军营中作战士；他们在你中间悬挂盾牌和头盔，彰显你的尊荣。'),
('CUV', '以西结书', 26, 27, 11, '亚发人和你的军队都在你四围的墙上，你的望楼也有勇士；他们悬挂盾牌，成全你的美丽。'),
('CUV', '以西结书', 26, 27, 12, '他施人因你多有各类的财物，就作你的客商，拿银、铁、锡、铅兑换你的货物。'),
('CUV', '以西结书', 26, 27, 13, '雅完人、土巴人、米设人都与你交易；他们用人口和铜器兑换你的货物。'),
('CUV', '以西结书', 26, 27, 14, '陀迦玛族用马和战马并骡子兑换你的货物。'),
('CUV', '以西结书', 26, 27, 15, '底但人与你交易，许多海岛作你的码头；他们拿象牙、乌木与你兑换（或译：进贡）。'),
('CUV', '以西结书', 26, 27, 16, '亚兰人因你的工作很多，就作你的客商；他们用绿宝石、紫色布绣货、细麻布、珊瑚、红宝石兑换你的货物。'),
('CUV', '以西结书', 26, 27, 17, '犹大和以色列地的人都与你交易；他们用米匿的麦子、饼、蜜、油、乳香兑换你的货物。'),
('CUV', '以西结书', 26, 27, 18, '大马色人因你的工作很多，又因你多有各类的财物，就拿黑本酒和白羊毛与你交易。'),
('CUV', '以西结书', 26, 27, 19, '威但人和雅完人拿纺成的线、亮铁、桂皮、菖蒲兑换你的货物。'),
('CUV', '以西结书', 26, 27, 20, '底但人用高贵的毯子、鞍、屉与你交易。'),
('CUV', '以西结书', 26, 27, 21, '亚拉伯人和基达的一切首领都作你的客商，用羊羔、公绵羊、公山羊与你交易。'),
('CUV', '以西结书', 26, 27, 22, '示巴和拉玛的商人与你交易，他们用各类上好的香料、各类的宝石，和黄金兑换你的货物。'),
('CUV', '以西结书', 26, 27, 23, '哈兰人、干尼人、伊甸人、示巴的商人，和亚述人、基抹人与你交易。'),
('CUV', '以西结书', 26, 27, 24, '这些商人以美好的货物包在绣花蓝色包袱内，又有华丽的衣服装在香柏木的箱子里，用绳捆著与你交易。'),
('CUV', '以西结书', 26, 27, 25, '他施的船只接连成帮为你运货，你便在海中丰富极其荣华。'),
('CUV', '以西结书', 26, 27, 26, '荡桨的已经把你荡到大水之处，东风在海中将你打破。'),
('CUV', '以西结书', 26, 27, 27, '你的资财、物件、货物、水手、掌舵的、补缝的、经营交易的，并你中间的战士和人民，在你破坏的日子必都沉在海中。'),
('CUV', '以西结书', 26, 27, 28, '你掌舵的呼号之声一发，郊野都必震动。'),
('CUV', '以西结书', 26, 27, 29, '凡荡桨的和水手，并一切泛海掌舵的，都必下船登岸。'),
('CUV', '以西结书', 26, 27, 30, '他们必为你放声痛哭，把尘土撒在头上，在灰中打滚；'),
('CUV', '以西结书', 26, 27, 31, '又为你使头上光秃，用麻布束腰，号咷痛哭，苦苦悲哀。'),
('CUV', '以西结书', 26, 27, 32, '他们哀号的时候，为你作起哀歌哀哭，说：有何城如推罗﹖有何城如他在海中成为寂寞的呢﹖'),
('CUV', '以西结书', 26, 27, 33, '你由海上运出货物，就使许多国民充足；你以许多资财、货物使地上的君王丰富。'),
('CUV', '以西结书', 26, 27, 34, '你在深水中被海浪打破的时候，你的货物和你中间的一切人民，就都沉下去了。'),
('CUV', '以西结书', 26, 27, 35, '海岛的居民为你惊奇；他们的君王都甚恐慌，面带愁容。'),
('CUV', '以西结书', 26, 27, 36, '各国民中的客商都向你发嘶声；你令人惊恐，不再存留于世，直到永远。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 28, 1, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 28, 2, '人子啊，你对推罗君王说，主耶和华如此说：因你心里高傲，说：我是神；我在海中坐神之位。你虽然居心自比神，也不过是人，并不是神！'),
('CUV', '以西结书', 26, 28, 3, '看哪，你比但以理更有智慧，甚么秘事都不能向你隐藏。'),
('CUV', '以西结书', 26, 28, 4, '你靠自己的智慧聪明得了金银财宝，收入库中。'),
('CUV', '以西结书', 26, 28, 5, '你靠自己的大智慧和贸易增添资财，又因资财心里高傲。'),
('CUV', '以西结书', 26, 28, 6, '所以主耶和华如此说：因你居心自比神，'),
('CUV', '以西结书', 26, 28, 7, '我必使外邦人，就是列国中的强暴人临到你这里；他们必拔刀砍坏你用智慧得来的美物，亵渎你的荣光。'),
('CUV', '以西结书', 26, 28, 8, '他们必使你下坑；你必死在海中，与被杀的人一样。'),
('CUV', '以西结书', 26, 28, 9, '在杀你的人面前你还能说我是神么﹖其实你在杀害你的人手中，不过是人，并不是神。'),
('CUV', '以西结书', 26, 28, 10, '你必死在外邦人手中，与未受割礼（或译：不洁；下同）的人一样，因为这是主耶和华说的。'),
('CUV', '以西结书', 26, 28, 11, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 28, 12, '人子啊，你为推罗王作起哀歌，说主耶和华如此说：你无所不备，智慧充足，全然美丽。'),
('CUV', '以西结书', 26, 28, 13, '你曾在伊甸神的园中，佩戴各样宝石，就是红宝石、红璧玺、金钢石、水苍玉、红玛瑙、碧玉、蓝宝石、绿宝石、红玉，和黄金；又有精美的鼓笛在你那里，都是在你受造之日预备齐全的。'),
('CUV', '以西结书', 26, 28, 14, '你是那受膏遮掩约柜的基路伯；我将你安置在神的圣山上；你在发光如火的宝石中间往来。'),
('CUV', '以西结书', 26, 28, 15, '你从受造之日所行的都完全，后来在你中间又察出不义。'),
('CUV', '以西结书', 26, 28, 16, '因你贸易很多，就被强暴的事充满，以致犯罪，所以我因你亵渎圣地，就从神的山驱逐你。遮掩约柜的基路伯啊，我已将你从发光如火的宝石中除灭。'),
('CUV', '以西结书', 26, 28, 17, '你因美丽心中高傲，又因荣光败坏智慧，我已将你摔倒在地，使你倒在君王面前，好叫他们目睹眼见。'),
('CUV', '以西结书', 26, 28, 18, '你因罪孽众多，贸易不公，就亵渎你那里的圣所。故此，我使火从你中间发出，烧灭你，使你在所有观看的人眼前变为地上的炉灰。'),
('CUV', '以西结书', 26, 28, 19, '各国民中，凡认识你的，都必为你惊奇。你令人惊恐，不再存留于世，直到永远。'),
('CUV', '以西结书', 26, 28, 20, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 28, 21, '人子啊，你要向西顿预言攻击他，'),
('CUV', '以西结书', 26, 28, 22, '说主耶和华如此说：西顿哪，我与你为敌，我必在你中间得荣耀。我在你中间施行审判、显为圣的时候，人就知道我是耶和华。'),
('CUV', '以西结书', 26, 28, 23, '我必使瘟疫进入西顿，使血流在他街上。被杀的必在其中仆倒，四围有刀剑临到他，人就知道我是耶和华。'),
('CUV', '以西结书', 26, 28, 24, '四围恨恶以色列家的人，必不再向他们作刺人的荆棘，伤人的蒺藜，人就知道我是主耶和华。'),
('CUV', '以西结书', 26, 28, 25, '主耶和华如此说：我将分散在万民中的以色列家招聚回来，向他们在列邦人眼前显为圣的时候，他们就在我赐给我仆人雅各之地，仍然居住。'),
('CUV', '以西结书', 26, 28, 26, '他们要在这地上安然居住。我向四围恨恶他们的众人施行审判以后，他们要盖造房屋，栽种葡萄园，安然居住，就知道我是耶和华─他们的神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 29, 1, '第十年十月十二日，耶和华的话临到我说：'),
('CUV', '以西结书', 26, 29, 2, '人子啊，你要向埃及王法老预言攻击他和埃及全地，'),
('CUV', '以西结书', 26, 29, 3, '说主耶和华如此说：埃及王法老啊，我与你这卧在自己河中的大鱼为敌。你曾说：这河是我的，是我为自己造的。'),
('CUV', '以西结书', 26, 29, 4, '我─耶和华必用钩子钩住你的腮颊，又使江河中的鱼贴住你的鳞甲；我必将你和所有贴住你鳞甲的鱼，从江河中拉上来，'),
('CUV', '以西结书', 26, 29, 5, '把你并江河中的鱼都抛在旷野；你必倒在田间，不被收殓，不被掩埋。我已将你给地上野兽、空中飞鸟作食物。'),
('CUV', '以西结书', 26, 29, 6, '埃及一切的居民，因向以色列家成了芦苇的杖，就知道我是耶和华。'),
('CUV', '以西结书', 26, 29, 7, '他们用手持住你，你就断折，伤了他们的肩；他们倚靠你，你就断折，闪了他们的腰。'),
('CUV', '以西结书', 26, 29, 8, '所以主耶和华如此说：我必使刀剑临到你，从你中间将人与牲畜剪除。'),
('CUV', '以西结书', 26, 29, 9, '埃及地必荒废凄凉，他们就知道我是耶和华。因为法老说：这河是我的，是我所造的，'),
('CUV', '以西结书', 26, 29, 10, '所以我必与你并你的江河为敌，使埃及地，从色弗尼塔直到古实境界，全然荒废凄凉。'),
('CUV', '以西结书', 26, 29, 11, '人的脚、兽的蹄都不经过，四十年之久并无人居住。'),
('CUV', '以西结书', 26, 29, 12, '我必使埃及地在荒凉的国中成为荒凉，使埃及城在荒废的城中变为荒废，共有四十年。我必将埃及人分散在列国，四散在列邦。'),
('CUV', '以西结书', 26, 29, 13, '主耶和华如此说：满了四十年，我必招聚分散在各国民中的埃及人。'),
('CUV', '以西结书', 26, 29, 14, '我必叫埃及被掳的人回来，使他们归回本地巴忒罗。在那里必成为低微的国，'),
('CUV', '以西结书', 26, 29, 15, '必为列国中最低微的，也不再自高于列国之上。我必减少他们，以致不再辖制列国。'),
('CUV', '以西结书', 26, 29, 16, '埃及必不再作以色列家所倚靠的；以色列家仰望埃及人的时候，便思念罪孽。他们就知道我是主耶和华。'),
('CUV', '以西结书', 26, 29, 17, '二十七年正月初一日，耶和华的话临到我说：'),
('CUV', '以西结书', 26, 29, 18, '人子啊，巴比伦王尼布甲尼撒使他的军兵大大效劳，攻打推罗，以致头都光秃，肩都磨破；然而他和他的军兵攻打推罗，并没有从那里得甚么酬劳。'),
('CUV', '以西结书', 26, 29, 19, '所以主耶和华如此说：我必将埃及地赐给巴比伦王尼布甲尼撒；他必掳掠埃及群众，抢其中的财为掳物，夺其中的货为掠物，这就可以作他军兵的酬劳。'),
('CUV', '以西结书', 26, 29, 20, '我将埃及地赐给他，酬他所效的劳，因王与军兵是为我勤劳。这是主耶和华说的。'),
('CUV', '以西结书', 26, 29, 21, '当那日，我必使以色列家的角发生，又必使你─以西结在他们中间得以开口；他们就知道我是耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 30, 1, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 30, 2, '人子啊，你要发预言说，主耶和华如此说：哀哉这日！你们应当哭号。'),
('CUV', '以西结书', 26, 30, 3, '因为耶和华的日子临近，就是密云之日，列国受罚之期。'),
('CUV', '以西结书', 26, 30, 4, '必有刀剑临到埃及；在埃及被杀之人仆倒的时候，古实人就有痛苦，人民必被掳掠，基址必被拆毁。'),
('CUV', '以西结书', 26, 30, 5, '古实人、弗人（或译：吕彼亚）、路德人、杂族的人民，并古巴人，以及同盟之地的人都要与埃及人一同倒在刀下。'),
('CUV', '以西结书', 26, 30, 6, '耶和华如此说：扶助埃及的也必倾倒。埃及因势力而有的骄傲必降低微；其中的人民，从色弗尼塔起（见二十九章十节）必倒在刀下。这是主耶和华说的。'),
('CUV', '以西结书', 26, 30, 7, '埃及地在荒凉的国中必成为荒凉；埃及城在荒废的城中也变为荒废。'),
('CUV', '以西结书', 26, 30, 8, '我在埃及中使火著起；帮助埃及的，都被灭绝。那时，他们就知道我是耶和华。'),
('CUV', '以西结书', 26, 30, 9, '到那日，必有使者坐船，从我面前出去，使安逸无虑的古实人惊惧；必有痛苦临到他们，好像埃及遭灾的日子一样。看哪，这事临近了！'),
('CUV', '以西结书', 26, 30, 10, '主耶和华如此说：我必藉巴比伦王尼布甲尼撒的手，除灭埃及众人。'),
('CUV', '以西结书', 26, 30, 11, '他和随从他的人，就是列国中强暴的，必进来毁灭这地。他们必拔刀攻击埃及，使遍地有被杀的人。'),
('CUV', '以西结书', 26, 30, 12, '我必使江河干涸，将地卖在恶人的手中；我必藉外邦人的手，使这地和其中所有的变为凄凉。这是我─耶和华说的。'),
('CUV', '以西结书', 26, 30, 13, '主耶和华如此说：我必毁灭偶像，从挪弗除灭神像；必不再有君王出自埃及地。我要使埃及地的人惧怕。'),
('CUV', '以西结书', 26, 30, 14, '我必使巴忒罗荒凉，在琐安中使火著起，向挪施行审判。'),
('CUV', '以西结书', 26, 30, 15, '我必将我的忿怒倒在埃及的保障上，就是训上，并要剪除挪的众人。'),
('CUV', '以西结书', 26, 30, 16, '我必在埃及中使火著起；训必大大痛苦；挪必被攻破；挪弗白日（或译：终日）见仇敌。'),
('CUV', '以西结书', 26, 30, 17, '亚文和比伯实的少年人必倒在刀下；这些城的人必被掳掠。'),
('CUV', '以西结书', 26, 30, 18, '我在答比匿折断埃及的诸轭，使他因势力而有的骄傲在其中止息。那时，日光必退去；至于这城，必有密云遮蔽，其中的女子必被掳掠。'),
('CUV', '以西结书', 26, 30, 19, '我必这样向埃及施行审判，他们就知道我是耶和华。'),
('CUV', '以西结书', 26, 30, 20, '十一年正月初七日，耶和华的话临到我说：'),
('CUV', '以西结书', 26, 30, 21, '人子啊，我已打折埃及王法老的膀臂；没有敷药，也没有用布缠好，使他有力持刀。'),
('CUV', '以西结书', 26, 30, 22, '所以主耶和华如此说：看哪，我与埃及王法老为敌，必将他有力的膀臂和已打折的膀臂全行打断，使刀从他手中坠落。'),
('CUV', '以西结书', 26, 30, 23, '我必将埃及人分散在列国，四散在列邦。'),
('CUV', '以西结书', 26, 30, 24, '我必使巴比伦王的膀臂有力，将我的刀交在他手中；却要打断法老的膀臂，他就在巴比伦王面前唉哼，如同受死伤的人一样。'),
('CUV', '以西结书', 26, 30, 25, '我必扶持巴比伦王的膀臂，法老的膀臂却要下垂；我将我的刀交在巴比伦王手中，他必举刀攻击埃及地，他们就知道我是耶和华。'),
('CUV', '以西结书', 26, 30, 26, '我必将埃及人分散在列国，四散在列邦；他们就知道我是耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 31, 1, '十一年三月初一日，耶和华的话临到我说：'),
('CUV', '以西结书', 26, 31, 2, '人子啊，你要向埃及王法老和他的众人说：在威势上谁能与你相比呢？'),
('CUV', '以西结书', 26, 31, 3, '亚述王曾如利巴嫩中的香柏树，枝条荣美，影密如林，极其高大，树尖插入云中。'),
('CUV', '以西结书', 26, 31, 4, '众水使他生长；深水使他长大。所栽之地有江河围流，汊出的水道延到田野诸树。'),
('CUV', '以西结书', 26, 31, 5, '所以他高大超过田野诸树；发旺的时候，枝子繁多，因得大水之力枝条长长。'),
('CUV', '以西结书', 26, 31, 6, '空中的飞鸟都在枝子上搭窝；田野的走兽都在枝条下生子；所有大国的人民都在他荫下居住。'),
('CUV', '以西结书', 26, 31, 7, '树大条长，成为荣美，因为根在众水之旁。'),
('CUV', '以西结书', 26, 31, 8, '神园中的香柏树不能遮蔽他；松树不及他的枝子；枫树不及他的枝条；神园中的树都没有他荣美。'),
('CUV', '以西结书', 26, 31, 9, '我使他的枝条蕃多，成为荣美，以致神伊甸园中的树都嫉妒他。'),
('CUV', '以西结书', 26, 31, 10, '所以主耶和华如此说：因他高大，树尖插入云中，心骄气傲，'),
('CUV', '以西结书', 26, 31, 11, '我就必将他交给列国中大有威势的人；他必定办他。我因他的罪恶，已经驱逐他。'),
('CUV', '以西结书', 26, 31, 12, '外邦人，就是列邦中强暴的，将他砍断弃掉。他的枝条落在山间和一切谷中，他的枝子折断，落在地的一切河旁。地上的众民已经走去，离开他的荫下。'),
('CUV', '以西结书', 26, 31, 13, '空中的飞鸟都要宿在这败落的树上，田野的走兽都要卧在他的枝条下，'),
('CUV', '以西结书', 26, 31, 14, '好使水旁的诸树不因高大而自尊，也不将树尖插入云中，并且那些得水滋润、有势力的，也不得高大自立。因为他们在世人中，和下坑的人都被交与死亡，到阴府去了。'),
('CUV', '以西结书', 26, 31, 15, '主耶和华如此说：他下阴间的那日，我便使人悲哀。我为他遮盖深渊，使江河凝结，大水停流；我也使利巴嫩为他凄惨，田野的诸树都因他发昏。'),
('CUV', '以西结书', 26, 31, 16, '我将他扔到阴间，与下坑的人一同下去。那时，列国听见他坠落的响声就都震动，并且伊甸的一切树─就是利巴嫩得水滋润、最佳最美的树─都在阴府受了安慰。'),
('CUV', '以西结书', 26, 31, 17, '他们也与他同下阴间，到被杀的人那里。他们曾作他的膀臂，在列国中他的荫下居住。'),
('CUV', '以西结书', 26, 31, 18, '在这样荣耀威势上，在伊甸园诸树中，谁能与你相比呢？然而你要与伊甸的诸树一同下到阴府，在未受割礼的人中，与被杀的人一同躺卧。法老和他的群众乃是如此。这是主耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 32, 1, '十二年十二月初一日，耶和华的话临到我说：'),
('CUV', '以西结书', 26, 32, 2, '人子啊，你要为埃及王法老作哀歌，说：从前你在列国中，如同少壮狮子；现在你却像海中的大鱼。你冲出江河，用爪搅动诸水，使江河浑浊。'),
('CUV', '以西结书', 26, 32, 3, '主耶和华如此说：我必用多国的人民，将我的网撒在你身上，把你拉上来。'),
('CUV', '以西结书', 26, 32, 4, '我必将你丢在地上，抛在田野，使空中的飞鸟都落在你身上，使遍地的野兽吃你得饱。'),
('CUV', '以西结书', 26, 32, 5, '我必将你的肉丢在山间，用你高大的尸首填满山谷。'),
('CUV', '以西结书', 26, 32, 6, '我又必用你的血浇灌你所游泳之地，漫过山顶；河道都必充满。'),
('CUV', '以西结书', 26, 32, 7, '我将你扑灭的时候，要把天遮蔽，使众星昏暗，以密云遮掩太阳，月亮也不放光。'),
('CUV', '以西结书', 26, 32, 8, '我必使天上的亮光都在你以上变为昏暗，使你的地上黑暗。这是主耶和华说的。'),
('CUV', '以西结书', 26, 32, 9, '我使你败亡的风声传到你所不认识的各国。那时，我必使多民的心因你愁烦。'),
('CUV', '以西结书', 26, 32, 10, '我在许多国民和君王面前向你抡我的刀，国民就必因你惊奇，君王也必因你极其恐慌。在你仆倒的日子，他们各人为自己的性命时刻战兢。'),
('CUV', '以西结书', 26, 32, 11, '主耶和华如此说：巴比伦王的刀必临到你。'),
('CUV', '以西结书', 26, 32, 12, '我必藉勇士的刀使你的众民仆倒；这勇士都是列国中强暴的。他们必使埃及的骄傲归于无有；埃及的众民必被灭绝。'),
('CUV', '以西结书', 26, 32, 13, '我必从埃及多水旁除灭所有的走兽；人脚兽蹄必不再搅浑这水。'),
('CUV', '以西结书', 26, 32, 14, '那时，我必使埃及河澄清，江河像油缓流。这是主耶和华说的。'),
('CUV', '以西结书', 26, 32, 15, '我使埃及地变为荒废凄凉；这地缺少从前所充满的，又击杀其中一切的居民。那时，他们就知道我是耶和华。'),
('CUV', '以西结书', 26, 32, 16, '人必用这哀歌去哀哭，列国的女子为埃及和他的群众也必以此悲哀。这是主耶和华说的。'),
('CUV', '以西结书', 26, 32, 17, '十二年十二月十五日，耶和华的话临到我说：'),
('CUV', '以西结书', 26, 32, 18, '人子啊，你要为埃及群众哀号，又要将埃及和有名之国的女子，并下坑的人，一同扔到阴府去。'),
('CUV', '以西结书', 26, 32, 19, '你埃及的美丽胜过谁呢？你下去与未受割礼的人一同躺卧罢！'),
('CUV', '以西结书', 26, 32, 20, '他们必在被杀的人中仆到。他被交给刀剑，要把他和他的群众拉去。'),
('CUV', '以西结书', 26, 32, 21, '强盛的勇士要在阴间对埃及王和帮助他的说话；他们是未受割礼被杀的人，已经下去，躺卧不动。'),
('CUV', '以西结书', 26, 32, 22, '亚述和他的众民都在那里，他民的坟墓在他四围；他们都是被杀倒在刀下的。'),
('CUV', '以西结书', 26, 32, 23, '他们的坟墓在坑中极深之处。他的众民在他坟墓的四围，都是被杀倒在刀下的；他们曾在活人之地使人惊恐。'),
('CUV', '以西结书', 26, 32, 24, '以拦也在那里，他的群众在他坟墓的四围，都是被杀倒在刀下、未受割礼而下阴府的；他们曾在活人之地使人惊恐，并且与下坑的人一同担当羞辱。'),
('CUV', '以西结书', 26, 32, 25, '人给他和他的群众在被杀的人中设立床榻。他民的坟墓在他四围，他们都是未受割礼被刀杀的；他们曾在活人之地使人惊恐，并且与下坑的人一同担当羞辱。以拦已经放在被杀的人中。'),
('CUV', '以西结书', 26, 32, 26, '米设、土巴，和他们的群众都在那里。他民的坟墓在他四围，他们都是未受割礼被刀杀的；他们曾在活人之地使人惊恐。'),
('CUV', '以西结书', 26, 32, 27, '他们不得与那未受割礼仆倒的勇士一同躺卧；这些勇士带著兵器下阴间，头枕刀剑，骨头上有本身的罪孽；他们曾在活人之地使勇士惊恐。'),
('CUV', '以西结书', 26, 32, 28, '法老啊，你必在未受割礼的人中败坏，与那些被杀的人一同躺卧。'),
('CUV', '以西结书', 26, 32, 29, '以东也在那里。他君王和一切首领虽然仗著势力，还是放在被杀的人中；他们必与未受割礼的和下坑的人一同躺卧。'),
('CUV', '以西结书', 26, 32, 30, '在那里有北方的众王子和一切西顿人，都与被杀的人下去。他们虽然仗著势力使人惊恐，还是蒙羞。他们未受割礼，和被刀杀的一同躺卧，与下坑的人一同担当羞辱。'),
('CUV', '以西结书', 26, 32, 31, '法老看见他们，便为他被杀的军队受安慰。这是主耶和华说的。'),
('CUV', '以西结书', 26, 32, 32, '我任凭法老在活人之地使人惊恐，法老和他的群众必放在未受割礼和被杀的人中。这是主耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 33, 1, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 33, 2, '人子啊，你要告诉本国的子民说：我使刀剑临到哪一国，那一国的民从他们中间选立一人为守望的。'),
('CUV', '以西结书', 26, 33, 3, '他见刀剑临到那地，若吹角警戒众民，'),
('CUV', '以西结书', 26, 33, 4, '凡听见角声不受警戒的，刀剑若来除灭了他，他的罪（原文是血）就必归到自己的头上。'),
('CUV', '以西结书', 26, 33, 5, '他听见角声，不受警戒，他的罪必归到自己的身上；他若受警戒，便是救了自己的性命。'),
('CUV', '以西结书', 26, 33, 6, '倘若守望的人见刀剑临到，不吹角，以致民不受警戒，刀剑来杀了他们中间的一个人，他虽然死在罪孽之中，我却要向守望的人讨他丧命的罪（原文是血）。'),
('CUV', '以西结书', 26, 33, 7, '人子啊，我照样立你作以色列家守望的人。所以你要听我口中的话，替我警戒他们。'),
('CUV', '以西结书', 26, 33, 8, '我对恶人说：恶人哪，你必要死！你─以西结若不开口警戒恶人，使他离开所行的道，这恶人必死在罪孽之中，我却要向你讨他丧命的罪（原文是血）。'),
('CUV', '以西结书', 26, 33, 9, '倘若你警戒恶人转离所行的道，他仍不转离，他必死在罪孽之中，你却救自己脱离了罪。'),
('CUV', '以西结书', 26, 33, 10, '人子啊，你要对以色列家说：你们常说：我们的过犯罪恶在我们身上，我们必因此消灭，怎能存活呢？'),
('CUV', '以西结书', 26, 33, 11, '你对他们说，主耶和华说：我指著我的永生起誓，我断不喜悦恶人死亡，惟喜悦恶人转离所行的道而活。以色列家啊，你们转回，转回罢！离开恶道，何必死亡呢？'),
('CUV', '以西结书', 26, 33, 12, '人子啊，你要对本国的人民说：义人的义，在犯罪之日不能救他；至于恶人的恶，在他转离恶行之日也不能使他倾倒；义人在犯罪之日也不能因他的义存活。'),
('CUV', '以西结书', 26, 33, 13, '我对义人说：你必定存活！他若倚靠他的义而作罪孽，他所行的义都不被记念。他必因所作的罪孽死亡。'),
('CUV', '以西结书', 26, 33, 14, '再者，我对恶人说：你必定死亡！他若转离他的罪，行正直与合理的事：'),
('CUV', '以西结书', 26, 33, 15, '还人的当头和所抢夺的，遵行生命的律例，不作罪孽，他必定存活，不致死亡。'),
('CUV', '以西结书', 26, 33, 16, '他所犯的一切罪必不被记念。他行了正直与合理的事，必定存活。'),
('CUV', '以西结书', 26, 33, 17, '你本国的子民还说：主的道不公平。其实他们的道不公平。'),
('CUV', '以西结书', 26, 33, 18, '义人转离他的义而作罪孽，就必因此死亡。'),
('CUV', '以西结书', 26, 33, 19, '恶人转离他的恶，行正直与合理的事，就必因此存活。'),
('CUV', '以西结书', 26, 33, 20, '你们还说：主的道不公平。以色列家啊，我必按你们各人所行的审判你们。'),
('CUV', '以西结书', 26, 33, 21, '我们被掳之后十二年十月初五日，有人从耶路撒冷逃到我这里，说：城已攻破。'),
('CUV', '以西结书', 26, 33, 22, '逃来的人未到前一日的晚上，耶和华的灵（原文是手）降在我身上，开我的口。到第二日早晨，那人来到我这里，我口就开了，不再缄默。'),
('CUV', '以西结书', 26, 33, 23, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 33, 24, '人子啊，住在以色列荒废之地的人说：亚伯拉罕独自一人能得这地为业，我们人数众多，这地更是给我们为业的。'),
('CUV', '以西结书', 26, 33, 25, '所以你要对他们说，主耶和华如此说：你们吃带血的物，仰望偶像，并且杀人流血，你们还能得这地为业么？'),
('CUV', '以西结书', 26, 33, 26, '你们倚仗自己的刀剑行可憎的事，人人玷污邻舍的妻，你们还能得这地为业么？'),
('CUV', '以西结书', 26, 33, 27, '你要对他们这样说，主耶和华如此说：我指著我的永生起誓，在荒场中的，必倒在刀下；在田野间的，必交给野兽吞吃；在保障和洞里的，必遭瘟疫而死。'),
('CUV', '以西结书', 26, 33, 28, '我必使这地荒凉，令人惊骇；他因势力而有的骄傲也必止息。以色列的山都必荒凉，无人经过。'),
('CUV', '以西结书', 26, 33, 29, '我因他们所行一切可憎的事使地荒凉，令人惊骇。那时，他们就知道我是耶和华。'),
('CUV', '以西结书', 26, 33, 30, '人子啊，你本国的子民在墙垣旁边、在房屋门口谈论你。弟兄对弟兄彼此说：来罢！听听有甚么话从耶和华而出。'),
('CUV', '以西结书', 26, 33, 31, '他们来到你这里如同民来聚会，坐在你面前仿佛是我的民。他们听你的话却不去行；因为他们的口多显爱情，心却追随财利。'),
('CUV', '以西结书', 26, 33, 32, '他们看你如善于奏乐、声音幽雅之人所唱的雅歌，他们听你的话却不去行。'),
('CUV', '以西结书', 26, 33, 33, '看哪，所说的快要应验；应验了，他们就知道在他们中间有了先知。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 34, 1, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 34, 2, '人子啊，你要向以色列的牧人发预言，攻击他们，说，主耶和华如此说：祸哉！以色列的牧人只知牧养自己。牧人岂不当牧养群羊么？'),
('CUV', '以西结书', 26, 34, 3, '你们吃脂油、穿羊毛、宰肥壮的，却不牧养群羊。'),
('CUV', '以西结书', 26, 34, 4, '瘦弱的，你们没有养壮；有病的，你们没有医治；受伤的，你们没有缠裹；被逐的，你们没有领回；失丧的，你们没有寻找；但用强暴严严地辖制。'),
('CUV', '以西结书', 26, 34, 5, '因无牧人，羊就分散；既分散，便作了一切野兽的食物。'),
('CUV', '以西结书', 26, 34, 6, '我的羊在诸山间、在各高冈上流离，在全地上分散，无人去寻，无人去找。'),
('CUV', '以西结书', 26, 34, 7, '所以，你们这些牧人要听耶和华的话。'),
('CUV', '以西结书', 26, 34, 8, '主耶和华说：我指著我的永生起誓，我的羊因无牧人就成为掠物，也作了一切野兽的食物。我的牧人不寻找我的羊；这些牧人只知牧养自己，并不牧养我的羊。'),
('CUV', '以西结书', 26, 34, 9, '所以你们这些牧人要听耶和华的话。'),
('CUV', '以西结书', 26, 34, 10, '主耶和华如此说：我必与牧人为敌，必向他们的手追讨我的羊，使他们不再牧放群羊；牧人也不再牧养自己。我必救我的羊脱离他们的口，不再作他们的食物。'),
('CUV', '以西结书', 26, 34, 11, '主耶和华如此说：看哪，我必亲自寻找我的羊，将他们寻见。'),
('CUV', '以西结书', 26, 34, 12, '牧人在羊群四散的日子怎样寻找他的羊，我必照样寻找我的羊。这些羊在密云黑暗的日子散到各处，我必从那里救回他们来。'),
('CUV', '以西结书', 26, 34, 13, '我必从万民中领出他们，从各国内聚集他们，引导他们归回故土，也必在以色列山上─一切溪水旁边、境内一切可居之处─牧养他们。'),
('CUV', '以西结书', 26, 34, 14, '我必在美好的草场牧养他们。他们的圈必在以色列高处的山上，他们必在佳美之圈中躺卧，也在以色列山肥美的草场吃草。'),
('CUV', '以西结书', 26, 34, 15, '主耶和华说：我必亲自作我羊的牧人，使他们得以躺卧。'),
('CUV', '以西结书', 26, 34, 16, '失丧的，我必寻找；被逐的，我必领回；受伤的，我必缠裹；有病的，我必医治；只是肥的壮的，我必除灭，也要秉公牧养他们。'),
('CUV', '以西结书', 26, 34, 17, '我的羊群哪，论到你们，主耶和华如此说：我必在羊与羊中间、公绵羊与公山羊中间施行判断。'),
('CUV', '以西结书', 26, 34, 18, '你们这些肥壮的羊，在美好的草场吃草还以为小事么？剩下的草，你们竟用蹄践踏了；你们喝清水，剩下的水，你们竟用蹄搅浑了。'),
('CUV', '以西结书', 26, 34, 19, '至于我的羊，只得吃你们所践踏的，喝你们所搅浑的。'),
('CUV', '以西结书', 26, 34, 20, '所以，主耶和华如此说：我必在肥羊和瘦羊中间施行判断。'),
('CUV', '以西结书', 26, 34, 21, '因为你们用胁用肩拥挤一切瘦弱的，又用角抵触，以致使他们四散。'),
('CUV', '以西结书', 26, 34, 22, '所以，我必拯救我的群羊不再作掠物；我也必在羊和羊中间施行判断。'),
('CUV', '以西结书', 26, 34, 23, '我必立一牧人照管他们，牧养他们，就是我的仆人大卫。他必牧养他们，作他们的牧人。'),
('CUV', '以西结书', 26, 34, 24, '我─耶和华必作他们的神，我的仆人大卫必在他们中间作王。这是耶和华说的。'),
('CUV', '以西结书', 26, 34, 25, '我必与他们立平安的约，使恶兽从境内断绝，他们就必安居在旷野，躺卧在林中。'),
('CUV', '以西结书', 26, 34, 26, '我必使他们与我山的四围成为福源，我也必叫时雨落下，必有福如甘霖而降。'),
('CUV', '以西结书', 26, 34, 27, '田野的树必结果，地也必有出产；他们必在故土安然居住。我折断他们所负的轭，救他们脱离那以他们为奴之人的手；那时，他们就知道我是耶和华。'),
('CUV', '以西结书', 26, 34, 28, '他们必不再作外邦人的掠物，地上的野兽也不再吞吃他们；却要安然居住，无人惊吓。'),
('CUV', '以西结书', 26, 34, 29, '我必给他们兴起有名的植物；他们在境内不再为饥荒所灭，也不再受外邦人的羞辱，'),
('CUV', '以西结书', 26, 34, 30, '必知道我、耶和华─他们的神是与他们同在的，并知道他们─以色列家是我的民。这是主耶和华说的。'),
('CUV', '以西结书', 26, 34, 31, '你们作我的羊，我草场上的羊，乃是以色列人，我也是你们的神。这是主耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 35, 1, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 35, 2, '人子啊，你要面向西珥山发预言，攻击他，'),
('CUV', '以西结书', 26, 35, 3, '对他说，主耶和华如此说：西珥山哪，我与你为敌，必向你伸手攻击你，使你荒凉，令人惊骇。'),
('CUV', '以西结书', 26, 35, 4, '我必使你的城邑变为荒场，成为凄凉。你就知道我是耶和华。'),
('CUV', '以西结书', 26, 35, 5, '因为你永怀仇恨，在以色列人遭灾、罪孽到了尽头的时候，将他们交与刀剑，'),
('CUV', '以西结书', 26, 35, 6, '所以主耶和华说：我指著我的永生起誓，我必使你遭遇流血的报应，罪（原文是血；本节同）必追赶你；你既不恨恶杀人流血，所以这罪必追赶你。'),
('CUV', '以西结书', 26, 35, 7, '我必使西珥山荒凉，令人惊骇，来往经过的人我必剪除。'),
('CUV', '以西结书', 26, 35, 8, '我必使西珥山满有被杀的人。被刀杀的，必倒在你小山和山谷，并一切的溪水中。'),
('CUV', '以西结书', 26, 35, 9, '我必使你永远荒凉，使你的城邑无人居住，你的民就知道我是耶和华。'),
('CUV', '以西结书', 26, 35, 10, '因为你曾说：这二国这二邦必归于我，我必得为业（其实耶和华仍在那里），'),
('CUV', '以西结书', 26, 35, 11, '所以主耶和华说：我指著我的永生起誓，我必照你的怒气和你从仇恨中向他们所发的嫉妒待你。我审判你的时候，必将自己显明在他们中间。'),
('CUV', '以西结书', 26, 35, 12, '你也必知道我─耶和华听见了你的一切毁谤，就是你攻击以色列山的话，说：这些山荒凉，是归我们吞灭的。'),
('CUV', '以西结书', 26, 35, 13, '你们也用口向我夸大，增添与我反对的话，我都听见了。'),
('CUV', '以西结书', 26, 35, 14, '主耶和华如此说：全地欢乐的时候，我必使你荒凉。'),
('CUV', '以西结书', 26, 35, 15, '你怎样因以色列家的地业荒凉而喜乐，我必照你所行的待你。西珥山哪，你和以东全地必都荒凉。你们就知道我是耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 36, 1, '人子啊，你要对以色列山发预言说：以色列山哪，要听耶和华的话。'),
('CUV', '以西结书', 26, 36, 2, '主耶和华如此说：因仇敌说：阿哈！这永久的山冈都归我们为业了！'),
('CUV', '以西结书', 26, 36, 3, '所以要发预言说，主耶和华如此说：因为敌人使你荒凉，四围吞吃，好叫你归与其余的外邦人为业，并且多嘴多舌的人提起你来，百姓也说你有臭名。'),
('CUV', '以西结书', 26, 36, 4, '故此，以色列山要听主耶和华的话。大山小冈、水沟山谷、荒废之地、被弃之城，为四围其余的外邦人所占据、所讥刺的，'),
('CUV', '以西结书', 26, 36, 5, '主耶和华对你们如此说：我真发愤恨如火，责备那其余的外邦人和以东的众人。他们快乐满怀，心存恨恶，将我的地归自己为业，又看为被弃的掠物。'),
('CUV', '以西结书', 26, 36, 6, '所以，你要指著以色列地说预言，对大山小冈、水沟山谷说，主耶和华如此说：我发愤恨和忿怒说，因你们曾受外邦人的羞辱，'),
('CUV', '以西结书', 26, 36, 7, '所以我起誓说：你们四围的外邦人总要担当自己的羞辱。这是主耶和华说的。'),
('CUV', '以西结书', 26, 36, 8, '以色列山哪，你必发枝条，为我的民以色列结果子，因为他们快要来到。'),
('CUV', '以西结书', 26, 36, 9, '看哪，我是帮助你的，也必向你转意，使你得以耕种。'),
('CUV', '以西结书', 26, 36, 10, '我必使以色列全家的人数在你上面增多，城邑有人居住，荒场再被建造。'),
('CUV', '以西结书', 26, 36, 11, '我必使人和牲畜在你上面加增；他们必生养众多。我要使你照旧有人居住，并要赐福与你比先前更多，你就知道我是耶和华。'),
('CUV', '以西结书', 26, 36, 12, '我必使人，就是我的民以色列，行在你上面。他们必得你为业；你也不再使他们丧子。'),
('CUV', '以西结书', 26, 36, 13, '主耶和华如此说：因为人对你说：你是吞吃人的，又使国民丧子，'),
('CUV', '以西结书', 26, 36, 14, '所以主耶和华说：你必不再吞吃人，也不再使国民丧子。'),
('CUV', '以西结书', 26, 36, 15, '我使你不再听见各国的羞辱，不再受万民的辱骂，也不再使国民绊跌。这是主耶和华说的。'),
('CUV', '以西结书', 26, 36, 16, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 36, 17, '人子啊，以色列家住在本地的时候，在行动作为上玷污那地。他们的行为在我面前，好像正在经期的妇人那样污秽。'),
('CUV', '以西结书', 26, 36, 18, '所以我因他们在那地上流人的血，又因他们以偶像玷污那地，就把我的忿怒倾在他们身上。'),
('CUV', '以西结书', 26, 36, 19, '我将他们分散在列国，四散在列邦，按他们的行动作为惩罚他们。'),
('CUV', '以西结书', 26, 36, 20, '他们到了所去的列国，就使我的圣名被亵渎；因为人谈论他们说，这是耶和华的民，是从耶和华的地出来的。'),
('CUV', '以西结书', 26, 36, 21, '我却顾惜我的圣名，就是以色列家在所到的列国中所亵渎的。'),
('CUV', '以西结书', 26, 36, 22, '所以，你要对以色列家说，主耶和华如此说：以色列家啊，我行这事不是为你们，乃是为我的圣名，就是在你们到的列国中所亵渎的。'),
('CUV', '以西结书', 26, 36, 23, '我要使我的大名显为圣；这名在列国中已被亵渎，就是你们在他们中间所亵渎的。我在他们眼前，在你们身上显为圣的时候，他们就知道我是耶和华。这是主耶和华说的。'),
('CUV', '以西结书', 26, 36, 24, '我必从各国收取你们，从列邦聚集你们，引导你们归回本地。'),
('CUV', '以西结书', 26, 36, 25, '我必用清水洒在你们身上，你们就洁净了。我要洁净你们，使你们脱离一切的污秽，弃掉一切的偶像。'),
('CUV', '以西结书', 26, 36, 26, '我也要赐给你们一个新心，将新灵放在你们里面，又从你们的肉体中除掉石心，赐给你们肉心。'),
('CUV', '以西结书', 26, 36, 27, '我必将我的灵放在你们里面，使你们顺从我的律例，谨守遵行我的典章。'),
('CUV', '以西结书', 26, 36, 28, '你们必住在我所赐给你们列祖之地。你们要作我的子民，我要作你们的神。'),
('CUV', '以西结书', 26, 36, 29, '我必救你们脱离一切的污秽，也必命五谷丰登，不使你们遭遇饥荒。'),
('CUV', '以西结书', 26, 36, 30, '我必使树木多结果子，田地多出土产，好叫你们不再因饥荒受外邦人的讥诮。'),
('CUV', '以西结书', 26, 36, 31, '那时，你们必追想你们的恶行和你们不善的作为，就因你们的罪孽和可憎的事厌恶自己。'),
('CUV', '以西结书', 26, 36, 32, '主耶和华说：你们要知道，我这样行不是为你们。以色列家啊，当为自己的行为抱愧蒙羞。'),
('CUV', '以西结书', 26, 36, 33, '主耶和华如此说：我洁净你们，使你们脱离一切罪孽的日子，必使城邑有人居住，荒场再被建造。'),
('CUV', '以西结书', 26, 36, 34, '过路的人虽看为荒废之地，现今这荒废之地仍得耕种。'),
('CUV', '以西结书', 26, 36, 35, '他们必说：这先前为荒废之地，现在成如伊甸园；这荒废凄凉、毁坏的城邑现在坚固有人居住。'),
('CUV', '以西结书', 26, 36, 36, '那时，在你们四围其余的外邦人必知道我─耶和华修造那毁坏之处，培植那荒废之地。我─耶和华说过，也必成就。'),
('CUV', '以西结书', 26, 36, 37, '主耶和华如此说：我要加增以色列家的人数，多如羊群。他们必为这事向我求问，我要给他们成就。'),
('CUV', '以西结书', 26, 36, 38, '耶路撒冷在守节作祭物所献的羊群怎样多，照样，荒凉的城邑必被人群充满。他们就知道我是耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 37, 1, '耶和华的灵（原文是手）降在我身上。耶和华藉他的灵带我出去，将我放在平原中；这平原遍满骸骨。'),
('CUV', '以西结书', 26, 37, 2, '他使我从骸骨的四围经过，谁知在平原的骸骨甚多，而且极其枯干。'),
('CUV', '以西结书', 26, 37, 3, '他对我说：人子啊，这些骸骨能复活么？我说：主耶和华啊，你是知道的。'),
('CUV', '以西结书', 26, 37, 4, '他又对我说：你向这些骸骨发预言说：枯干的骸骨啊，要听耶和华的话。'),
('CUV', '以西结书', 26, 37, 5, '主耶和华对这些骸骨如此说：我必使气息进入你们里面，你们就要活了。'),
('CUV', '以西结书', 26, 37, 6, '我必给你们加上筋，使你们长肉，又将皮遮蔽你们，使气息进入你们里面，你们就要活了；你们便知道我是耶和华。'),
('CUV', '以西结书', 26, 37, 7, '于是，我遵命说预言。正说预言的时候，不料，有响声，有地震；骨与骨互相联络。'),
('CUV', '以西结书', 26, 37, 8, '我观看，见骸骨上有筋，也长了肉，又有皮遮蔽其上，只是还没有气息。'),
('CUV', '以西结书', 26, 37, 9, '主对我说：人子啊，你要发预言，向风发预言，说主耶和华如此说：气息啊，要从四方（原文是风）而来，吹在这些被杀的人身上，使他们活了。'),
('CUV', '以西结书', 26, 37, 10, '于是我遵命说预言，气息就进入骸骨，骸骨便活了，并且站起来，成为极大的军队。'),
('CUV', '以西结书', 26, 37, 11, '主对我说：人子啊，这些骸骨就是以色列全家。他们说：我们的骨头枯干了，我们的指望失去了，我们灭绝净尽了。'),
('CUV', '以西结书', 26, 37, 12, '所以你要发预言对他们说，主耶和华如此说：我的民哪，我必开你们的坟墓，使你们从坟墓中出来，领你们进入以色列地。'),
('CUV', '以西结书', 26, 37, 13, '我的民哪，我开你们的坟墓，使你们从坟墓中出来，你们就知道我是耶和华。'),
('CUV', '以西结书', 26, 37, 14, '我必将我的灵放在你们里面，你们就要活了。我将你们安置在本地，你们就知道我─耶和华如此说，也如此成就了。这是耶和华说的。'),
('CUV', '以西结书', 26, 37, 15, '耶和华的话又临到我说：'),
('CUV', '以西结书', 26, 37, 16, '人子啊，你要取一根木杖，在其上写为犹大和他的同伴以色列人；又取一根木杖，在其上写为约瑟，就是为以法莲，又为他的同伴以色列全家。'),
('CUV', '以西结书', 26, 37, 17, '你要使这两根木杖接连为一，在你手中成为一根。'),
('CUV', '以西结书', 26, 37, 18, '你本国的子民问你说：这是甚么意思？你不指示我们么？'),
('CUV', '以西结书', 26, 37, 19, '你就对他们说：主耶和华如此说：我要将约瑟和他同伴以色列支派的杖，就是那在以法莲手中的，与犹大的杖一同接连为一，在我手中成为一根。'),
('CUV', '以西结书', 26, 37, 20, '你所写的那两根杖要在他们眼前拿在手中，'),
('CUV', '以西结书', 26, 37, 21, '要对他们说，主耶和华如此说：我要将以色列人从他们所到的各国收取，又从四围聚集他们，引导他们归回本地。'),
('CUV', '以西结书', 26, 37, 22, '我要使他们在那地，在以色列山上成为一国，有一王作他们众民的王。他们不再为二国，决不再分为二国；'),
('CUV', '以西结书', 26, 37, 23, '也不再因偶像和可憎的物，并一切的罪过玷污自己。我却要救他们出离一切的住处，就是他们犯罪的地方；我要洁净他们，如此，他们要作我的子民，我要作他们的神。'),
('CUV', '以西结书', 26, 37, 24, '我的仆人大卫必作他们的王；众民必归一个牧人。他们必顺从我的典章，谨守遵行我的律例。'),
('CUV', '以西结书', 26, 37, 25, '他们必住在我赐给我仆人雅各的地上，就是你们列祖所住之地。他们和他们的子孙，并子孙的子孙，都永远住在那里。我的仆人大卫必作他们的王，直到永远。'),
('CUV', '以西结书', 26, 37, 26, '并且我要与他们立平安的约，作为永约。我也要将他们安置在本地，使他们的人数增多，又在他们中间设立我的圣所，直到永远。'),
('CUV', '以西结书', 26, 37, 27, '我的居所必在他们中间；我要作他们的神，他们要作我的子民。'),
('CUV', '以西结书', 26, 37, 28, '我的圣所在以色列人中间直到永远，外邦人就必知道我是叫以色列成为圣的耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 38, 1, '耶和华的话临到我说：'),
('CUV', '以西结书', 26, 38, 2, '人子啊，你要面向玛各地的歌革，就是罗施、米设、土巴的王发预言攻击他，'),
('CUV', '以西结书', 26, 38, 3, '说主耶和华如此说：罗施、米设、土巴的王歌革啊，我与你为敌。'),
('CUV', '以西结书', 26, 38, 4, '我必用钩子钩住你的腮颊，调转你，将你和你的军兵、马匹、马兵带出来，都披挂整齐，成了大队，有大小盾牌，各拿刀剑。'),
('CUV', '以西结书', 26, 38, 5, '波斯人、古实人，和弗人（又作吕彼亚人），各拿盾牌，头上戴盔；'),
('CUV', '以西结书', 26, 38, 6, '歌篾人和他的军队，北方极处的陀迦玛族和他的军队，这许多国的民都同著你。'),
('CUV', '以西结书', 26, 38, 7, '那聚集到你这里的各队都当准备；你自己也要准备，作他们的大帅。'),
('CUV', '以西结书', 26, 38, 8, '过了多日，你必被差派。到末后之年，你必来到脱离刀剑从列国收回之地，到以色列常久荒凉的山上；但那从列国中招聚出来的必在其上安然居住。'),
('CUV', '以西结书', 26, 38, 9, '你和你的军队，并同著你许多国的民，必如暴风上来，如密云遮盖地面。'),
('CUV', '以西结书', 26, 38, 10, '主耶和华如此说：到那时，你心必起意念，图谋恶计，'),
('CUV', '以西结书', 26, 38, 11, '说：我要上那无城墙的乡村，我要到那安静的民那里，他们都没有城墙，无门、无闩，安然居住。'),
('CUV', '以西结书', 26, 38, 12, '我去要抢财为掳物，夺货为掠物，反手攻击那从前荒凉、现在有人居住之地，又攻击那住世界中间、从列国招聚、得了牲畜财货的民。'),
('CUV', '以西结书', 26, 38, 13, '示巴人、底但人、他施的客商，和其间的少壮狮子都必问你说：你来要抢财为掳物么？你聚集军队要夺货为掠物么？要夺取金银，掳去牲畜、财货么？要抢夺许多财宝为掳物么？'),
('CUV', '以西结书', 26, 38, 14, '人子啊，你要因此发预言，对歌革说，主耶和华如此说：到我民以色列安然居住之日，你岂不知道么？'),
('CUV', '以西结书', 26, 38, 15, '你必从本地，从北方的极处率领许多国的民来，都骑著马，乃一大队极多的军兵。'),
('CUV', '以西结书', 26, 38, 16, '歌革啊，你必上来攻击我的民以色列，如密云遮盖地面。末后的日子，我必带你来攻击我的地，到我在外邦人眼前，在你身上显为圣的时候，好叫他们认识我。'),
('CUV', '以西结书', 26, 38, 17, '主耶和华如此说：我在古时藉我的仆人以色列的先知所说的，就是你么？当日他们多年预言我必带你来攻击以色列人。'),
('CUV', '以西结书', 26, 38, 18, '主耶和华说：歌革上来攻击以色列地的时候，我的怒气要从鼻孔里发出。'),
('CUV', '以西结书', 26, 38, 19, '我发愤恨和烈怒如火说：那日在以色列地必有大震动，'),
('CUV', '以西结书', 26, 38, 20, '甚至海中的鱼、天空的鸟、田野的兽，并地上的一切昆虫，和其上的众人，因见我的面就都震动；山岭必崩裂，陡岩必塌陷，墙垣都必坍倒。'),
('CUV', '以西结书', 26, 38, 21, '主耶和华说：我必命我的诸山发刀剑来攻击歌革；人都要用刀剑杀害弟兄。'),
('CUV', '以西结书', 26, 38, 22, '我必用瘟疫和流血的事刑罚他。我也必将暴雨、大雹与火，并硫磺降与他和他的军队，并他所率领的众民。'),
('CUV', '以西结书', 26, 38, 23, '我必显为大，显为圣，在多国人的眼前显现；他们就知道我是耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 39, 1, '人子啊，你要向歌革发预言攻击他，说主耶和华如此说：罗施、米设、土巴的王歌革啊，我与你为敌。'),
('CUV', '以西结书', 26, 39, 2, '我必调转你，领你前往，使你从北方的极处上来，带你到以色列的山上。'),
('CUV', '以西结书', 26, 39, 3, '我必从你左手打落你的弓，从你右手打掉你的箭。'),
('CUV', '以西结书', 26, 39, 4, '你和你的军队，并同著你的列国人，都必倒在以色列的山上。我必将你给各类的鸷鸟和田野的走兽作食物。'),
('CUV', '以西结书', 26, 39, 5, '你必倒在田野，因为我曾说过。这是主耶和华说的。'),
('CUV', '以西结书', 26, 39, 6, '我要降火在玛各和海岛安然居住的人身上，他们就知道我是耶和华。'),
('CUV', '以西结书', 26, 39, 7, '我要在我民以色列中显出我的圣名，也不容我的圣名再被亵渎，列国人就知道我是耶和华─以色列中的圣者。'),
('CUV', '以西结书', 26, 39, 8, '主耶和华说：这日事情临近，也必成就，乃是我所说的日子。'),
('CUV', '以西结书', 26, 39, 9, '住以色列城邑的人必出去捡器械，就是大小盾牌、弓箭、梃杖、枪矛，都当柴烧火，直烧七年，'),
('CUV', '以西结书', 26, 39, 10, '甚至他们不必从田野捡柴，也不必从树林伐木；因为他们要用器械烧火，并且抢夺那抢夺他们的人，掳掠那掳掠他们的人。这是主耶和华说的。'),
('CUV', '以西结书', 26, 39, 11, '当那日，我必将以色列地的谷，就是海东人所经过的谷，赐给歌革为坟地，使经过的人到此停步。在那里人必葬埋歌革和他的群众，就称那地为哈们歌革谷。'),
('CUV', '以西结书', 26, 39, 12, '以色列家的人必用七个月葬埋他们，为要洁净全地。'),
('CUV', '以西结书', 26, 39, 13, '全地的居民都必葬埋他们。当我得荣耀的日子，这事必叫他们得名声。这是主耶和华说的。'),
('CUV', '以西结书', 26, 39, 14, '他们必分派人时常巡查遍地，与过路的人一同葬埋那剩在地面上的尸首，好洁净全地。过了七个月，他们还要巡查。'),
('CUV', '以西结书', 26, 39, 15, '巡查遍地的人要经过全地，见有人的骸骨，就在旁边立一标记，等葬埋的人来将骸骨葬在哈们歌革谷。'),
('CUV', '以西结书', 26, 39, 16, '他们必这样洁净那地，并有一城名叫哈摩那。'),
('CUV', '以西结书', 26, 39, 17, '人子啊，主耶和华如此说：你要对各类的飞鸟和田野的走兽说：你们聚集来罢，要从四方聚到我为你们献祭之地，就是在以色列山上献大祭之地，好叫你们吃肉、喝血。'),
('CUV', '以西结书', 26, 39, 18, '你们必吃勇士的肉，喝地上首领的血，就如吃公绵羊、羊羔、公山羊、公牛，都是巴珊的肥畜。'),
('CUV', '以西结书', 26, 39, 19, '你们吃我为你们所献的祭，必吃饱了脂油，喝醉了血。'),
('CUV', '以西结书', 26, 39, 20, '你们必在我席上饱吃马匹和坐车的人，并勇士和一切的战士。这是主耶和华说的。'),
('CUV', '以西结书', 26, 39, 21, '我必显我的荣耀在列国中；万民就必看见我所行的审判与我在他们身上所加的手。'),
('CUV', '以西结书', 26, 39, 22, '这样，从那日以后，以色列家必知道我是耶和华─他们的神。'),
('CUV', '以西结书', 26, 39, 23, '列国人也必知道以色列家被掳掠是因他们的罪孽。他们得罪我，我就掩面不顾，将他们交在敌人手中，他们便都倒在刀下。'),
('CUV', '以西结书', 26, 39, 24, '我是照他们的污秽和罪过待他们，并且我掩面不顾他们。'),
('CUV', '以西结书', 26, 39, 25, '主耶和华如此说：我要使雅各被掳的人归回，要怜悯以色列全家，又为我的圣名发热心。'),
('CUV', '以西结书', 26, 39, 26, '他们在本地安然居住，无人惊吓，是我将他们从万民中领回，从仇敌之地召来。我在许多国的民眼前，在他们身上显为圣的时候，他们要担当自己的羞辱和干犯我的一切罪。'),
('CUV', '以西结书', 26, 39, 27, 'a'),
('CUV', '以西结书', 26, 39, 28, '因我使他们被掳到外邦人中，后又聚集他们归回本地，他们就知道我是耶和华─他们的神；我必不再留他们一人在外邦。'),
('CUV', '以西结书', 26, 39, 29, '我也不再掩面不顾他们，因我已将我的灵浇灌以色列家。这是主耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 40, 1, '我们被掳掠第二十五年，耶路撒冷城攻破后十四年，正在年初，月之初十日，耶和华的灵（原文是手）降在我身上，他把我带到以色列地。'),
('CUV', '以西结书', 26, 40, 2, '在神的异象中带我到以色列地，安置在至高的山上；在山上的南边有仿佛一座城建立。'),
('CUV', '以西结书', 26, 40, 3, '他带我到那里，见有一人，颜色（原文是形状）如铜，手拿麻绳和量度的竿，站在门口。'),
('CUV', '以西结书', 26, 40, 4, '那人对我说：人子啊，凡我所指示你的，你都要用眼看，用耳听，并要放在心上。我带你到这里来，特为要指示你；凡你所见的，你都要告诉以色列家。'),
('CUV', '以西结书', 26, 40, 5, '我见殿四围有墙。那人手拿量度的竿，长六肘，每肘是一肘零一掌。他用竿量墙，厚一竿，高一竿。'),
('CUV', '以西结书', 26, 40, 6, '他到了朝东的门，就上门的台阶，量门的这槛，宽一竿；又量门的那槛，宽一竿。'),
('CUV', '以西结书', 26, 40, 7, '又有卫房，每房长一竿，宽一竿，相隔五肘。门槛，就是挨著向殿的廊门槛，宽一竿。'),
('CUV', '以西结书', 26, 40, 8, '他又量向殿门的廊子，宽一竿。'),
('CUV', '以西结书', 26, 40, 9, '又量门廊，宽八肘，墙柱厚二肘；那门的廊子向著殿。'),
('CUV', '以西结书', 26, 40, 10, '东门洞有卫房：这旁三间，那旁三间，都是一样的尺寸；这边的柱子和那边的柱子，也是一样的尺寸。'),
('CUV', '以西结书', 26, 40, 11, '他量门口，宽十肘，长十三肘。'),
('CUV', '以西结书', 26, 40, 12, '卫房前展出的境界：这边一肘，那边一肘；卫房这边六肘，那边六肘。'),
('CUV', '以西结书', 26, 40, 13, '又量门洞，从这卫房顶的后檐到那卫房顶的后檐，宽二十五肘；卫房门与门相对。'),
('CUV', '以西结书', 26, 40, 14, '又量（原文是造）廊子六十肘（七十士译本是二十肘），墙柱外是院子，有廊为界，在门洞两边。'),
('CUV', '以西结书', 26, 40, 15, '从大门口到内廊前，共五十肘。'),
('CUV', '以西结书', 26, 40, 16, '卫房和门洞两旁柱间并廊子，都有严紧的窗櫺；里边都有窗櫺，柱上有雕刻的棕树。'),
('CUV', '以西结书', 26, 40, 17, '他带我到外院，见院的四围有铺石地；铺石地上有屋子三十间。'),
('CUV', '以西结书', 26, 40, 18, '铺石地，就是矮铺石地在各门洞两旁，以门洞的长短为度。'),
('CUV', '以西结书', 26, 40, 19, '他从下门量到内院外，共宽一百肘，东面北面都是如此。'),
('CUV', '以西结书', 26, 40, 20, '他量外院朝北的门，长宽若干。'),
('CUV', '以西结书', 26, 40, 21, '门洞的卫房，这旁三间，那旁三间。门洞的柱子和廊子，与第一门的尺寸一样。门洞长五十肘，宽二十五肘。'),
('CUV', '以西结书', 26, 40, 22, '其窗櫺和廊子，并雕刻的棕树，与朝东的门尺寸一样。登七层台阶上到这门，前面有廊子。'),
('CUV', '以西结书', 26, 40, 23, '内院有门与这门相对，北面东面都是如此。他从这门量到那门，共一百肘。'),
('CUV', '以西结书', 26, 40, 24, '他带我往南去，见朝南有门，又照先前的尺寸量门洞的柱子和廊子。'),
('CUV', '以西结书', 26, 40, 25, '门洞两旁与廊子的周围都有窗櫺，和先量的窗櫺一样。门洞长五十肘，宽二十五肘。'),
('CUV', '以西结书', 26, 40, 26, '登七层台阶上到这门，前面有廊子；柱上有雕刻的棕树，这边一棵，那边一棵。'),
('CUV', '以西结书', 26, 40, 27, '内院朝南有门。从这门量到朝南的那门，共一百肘。'),
('CUV', '以西结书', 26, 40, 28, '他带我从南门到内院，就照先前的尺寸量南门。'),
('CUV', '以西结书', 26, 40, 29, '卫房和柱子，并廊子都照先前的尺寸。门洞两旁与廊子的周围都有窗櫺。门洞长五十肘，宽二十五肘。'),
('CUV', '以西结书', 26, 40, 30, '周围有廊子，长二十五肘，宽五肘。'),
('CUV', '以西结书', 26, 40, 31, '廊子朝著外院，柱上有雕刻的棕树。登八层台阶上到这门。'),
('CUV', '以西结书', 26, 40, 32, '他带我到内院的东面，就照先前的尺寸量东门。'),
('CUV', '以西结书', 26, 40, 33, '卫房和柱子，并廊子都照先前的尺寸。门洞两旁与廊子的周围都有窗櫺。门洞长五十肘，宽二十五肘。'),
('CUV', '以西结书', 26, 40, 34, '廊子朝著外院。门洞两旁的柱子都有雕刻的棕树。登八层台阶上到这门。'),
('CUV', '以西结书', 26, 40, 35, '他带我到北门，就照先前的尺寸量那门，'),
('CUV', '以西结书', 26, 40, 36, '就是量卫房和柱子，并廊子。门洞周围都有窗櫺；门洞长五十肘，宽二十五肘。'),
('CUV', '以西结书', 26, 40, 37, '廊柱朝著外院。门洞两旁的柱子都有雕刻的棕树。登八层台阶上到这门。'),
('CUV', '以西结书', 26, 40, 38, '门洞的柱旁有屋子和门；祭司（原文是他们）在那里洗燔祭牲。'),
('CUV', '以西结书', 26, 40, 39, '在门廊内，这边有两张桌子，那边有两张桌子，在其上可以宰杀燔祭牲、赎罪祭牲，和赎愆祭牲。'),
('CUV', '以西结书', 26, 40, 40, '上到朝北的门口，这边有两张桌子，门廊那边也有两张桌子。'),
('CUV', '以西结书', 26, 40, 41, '门这边有四张桌子，那边有四张桌子，共八张；在其上祭司宰杀牺牲。'),
('CUV', '以西结书', 26, 40, 42, '为燔祭牲有四张桌子，是凿过的石头做成的，长一肘半，宽一肘半，高一肘。祭司将宰杀燔祭牲和平安祭牲所用的器皿放在其上。'),
('CUV', '以西结书', 26, 40, 43, '有钩子，宽一掌，钉在廊内的四围。桌子上有牺牲的肉。'),
('CUV', '以西结书', 26, 40, 44, '在北门旁，内院里有屋子，为歌唱的人而设。这屋子朝南（南：原文是东）；在南门旁，又有一间朝北。'),
('CUV', '以西结书', 26, 40, 45, '他对我说：这朝南的屋子是为看守殿宇的祭司；'),
('CUV', '以西结书', 26, 40, 46, '那朝北的屋子是为看守祭坛的祭司。这些祭司是利未人中撒督的子孙，近前来事奉耶和华的。'),
('CUV', '以西结书', 26, 40, 47, '他又量内院，长一百肘，宽一百肘，是见方的。祭坛在殿前。'),
('CUV', '以西结书', 26, 40, 48, '于是他带我到殿前的廊子，量廊子的墙柱。这面厚五肘，那面厚五肘。门两旁，这边三肘，那边三肘。'),
('CUV', '以西结书', 26, 40, 49, '廊子长二十肘，宽十一肘。上廊子有台阶。靠近墙柱又有柱子，这边一根，那边一根。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 41, 1, '他带我到殿那里量墙柱：这面厚六肘，那面厚六肘，宽窄与会幕相同。'),
('CUV', '以西结书', 26, 41, 2, '门口宽十肘。门两旁，这边五肘，那边五肘。他量殿长四十肘，宽二十肘。'),
('CUV', '以西结书', 26, 41, 3, '他到内殿量墙柱，各厚二肘。门口宽六肘，门两旁各宽七肘。'),
('CUV', '以西结书', 26, 41, 4, '他量内殿，长二十肘，宽二十肘。他对我说：这是至圣所。'),
('CUV', '以西结书', 26, 41, 5, '他又量殿墙，厚六肘；围著殿有旁屋，各宽四肘。'),
('CUV', '以西结书', 26, 41, 6, '旁屋有三层，层叠而上，每层排列三十间。旁屋的梁木搁在殿墙坎上，免得插入殿墙。'),
('CUV', '以西结书', 26, 41, 7, '这围殿的旁屋越高越宽；因旁屋围殿悬叠而上，所以越上越宽，从下一层，由中一层，到上一层。'),
('CUV', '以西结书', 26, 41, 8, '我又见围著殿有高月台。旁屋的根基，高足一竿，就是六大肘。'),
('CUV', '以西结书', 26, 41, 9, '旁屋的外墙厚五肘。旁屋之外还有余地。'),
('CUV', '以西结书', 26, 41, 10, '在旁屋与对面的房屋中间有空地，宽二十肘。'),
('CUV', '以西结书', 26, 41, 11, '旁屋的门都向余地：一门向北，一门向南。周围的余地宽五肘。'),
('CUV', '以西结书', 26, 41, 12, '在西面空地之后有房子，宽七十肘，长九十肘，墙四围厚五肘。'),
('CUV', '以西结书', 26, 41, 13, '这样，他量殿，长一百肘，又量空地和那房子并墙，共长一百肘。'),
('CUV', '以西结书', 26, 41, 14, '殿的前面和两旁的空地，宽一百肘。'),
('CUV', '以西结书', 26, 41, 15, '他量空地后面的那房子，并两旁的楼廊，共长一百肘。'),
('CUV', '以西结书', 26, 41, 16, '内殿、院廊、门槛、严紧的窗櫺，并对著门槛的三层楼廊，从地到窗櫺（窗櫺都有蔽子），'),
('CUV', '以西结书', 26, 41, 17, '直到门以上，就是到内殿和外殿内外四围墙壁，都按尺寸用木板遮蔽。'),
('CUV', '以西结书', 26, 41, 18, '墙上雕刻基路伯和棕树。每二基路伯中间有一棵棕树，每基路伯有二脸。'),
('CUV', '以西结书', 26, 41, 19, '这边有人脸向著棕树，那边有狮子脸向著棕树，殿内周围都是如此。'),
('CUV', '以西结书', 26, 41, 20, '从地至门以上，都有基路伯和棕树。殿墙就是这样。'),
('CUV', '以西结书', 26, 41, 21, '殿的门柱是方的。至圣所的前面，形状和殿的形状一样。'),
('CUV', '以西结书', 26, 41, 22, '坛是木头做的，高三肘，长二肘。坛角和坛面，并四旁，都是木头做的。他对我说：这是耶和华面前的桌子。'),
('CUV', '以西结书', 26, 41, 23, '殿和至圣所的门各有两扇。'),
('CUV', '以西结书', 26, 41, 24, '每扇分两扇，这两扇是折叠的。这边门分两扇，那边门也分两扇。'),
('CUV', '以西结书', 26, 41, 25, '殿的门扇上雕刻基路伯和棕树，与刻在墙上的一般。在外头廊前有木槛。'),
('CUV', '以西结书', 26, 41, 26, '廊这边那边都有严紧的窗櫺和棕树；殿的旁屋和槛就是这样。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 42, 1, '他带我出来向北，到外院，又带我进入圣屋；这圣屋一排顺著空地，一排与北边铺石地之屋相对。'),
('CUV', '以西结书', 26, 42, 2, '这圣屋长一百肘，宽五十肘，有向北的门。'),
('CUV', '以西结书', 26, 42, 3, '对著内院那二十肘宽之空地，又对著外院的铺石地，在第三层楼上有楼廊对著楼廊。'),
('CUV', '以西结书', 26, 42, 4, '在圣屋前有一条夹道，宽十肘，长一百肘。房门都向北。'),
('CUV', '以西结书', 26, 42, 5, '圣屋因为楼廊占去些地方，所以上层比中下两层窄些。'),
('CUV', '以西结书', 26, 42, 6, '圣屋有三层，却无柱子，不像外院的屋子有柱子；所以上层比中下两层更窄。'),
('CUV', '以西结书', 26, 42, 7, '圣屋外，东边有墙，靠著外院，长五十肘。'),
('CUV', '以西结书', 26, 42, 8, '靠著外院的圣屋长五十肘。殿北面的圣屋长一百肘。'),
('CUV', '以西结书', 26, 42, 9, '在圣屋以下，东头有进入之处，就是从外院进入之处。'),
('CUV', '以西结书', 26, 42, 10, '向南（原文是东）在内院墙里有圣屋，一排与铺石地之屋相对，一排顺著空地。'),
('CUV', '以西结书', 26, 42, 11, '这圣屋前的夹道与北边圣屋的夹道长宽一样；出入之处与北屋门的样式相同。'),
('CUV', '以西结书', 26, 42, 12, '正在墙前、夹道的东头，有门可以进入，与向南圣屋的门一样。'),
('CUV', '以西结书', 26, 42, 13, '他对我说：顺著空地的南屋北屋，都是圣屋；亲近耶和华的祭司当在那里吃至圣的物，也当在那里放至圣的物，就是素祭、赎罪祭，和赎愆祭，因此处为圣。'),
('CUV', '以西结书', 26, 42, 14, '祭司进去出了圣所的时候，不可直到外院，但要在圣屋放下他们供职的衣服，因为是圣衣；要穿上别的衣服才可以到属民的外院。'),
('CUV', '以西结书', 26, 42, 15, '他量完了内殿，就带我出朝东的门，量院的四围。'),
('CUV', '以西结书', 26, 42, 16, '他用量度的竿量四围，量东面五百肘（原文是竿；本章下同），'),
('CUV', '以西结书', 26, 42, 17, '用竿量北面五百肘，.'),
('CUV', '以西结书', 26, 42, 18, '用竿量南面五百肘，'),
('CUV', '以西结书', 26, 42, 19, '又转到西面，用竿量五百肘。'),
('CUV', '以西结书', 26, 42, 20, '他量四面，四围有墙，长五百肘，宽五百肘，为要分别圣地与俗地。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 43, 1, '以后，他带我到一座门，就是朝东的门。'),
('CUV', '以西结书', 26, 43, 2, '以色列神的荣光从东而来。他的声音如同多水的声音；地就因他的荣耀发光。'),
('CUV', '以西结书', 26, 43, 3, '其状如从前他来灭城的时候我所见的异象，那异象如我在迦巴鲁河边所见的异象，我就俯伏在地。'),
('CUV', '以西结书', 26, 43, 4, '耶和华的荣光从朝东的门照入殿中。'),
('CUV', '以西结书', 26, 43, 5, '灵将我举起，带入内院，不料，耶和华的荣光充满了殿。'),
('CUV', '以西结书', 26, 43, 6, '我听见有一位从殿中对我说话。有一人站在我旁边。'),
('CUV', '以西结书', 26, 43, 7, '他对我说：人子啊，这是我宝座之地，是我脚掌所踏之地。我要在这里住，在以色列人中直到永远。以色列家和他们的君王必不再玷污我的圣名，就是行邪淫、在锡安的高处葬埋他们君王的尸首，'),
('CUV', '以西结书', 26, 43, 8, '使他们的门槛挨近我的门槛，他们的门框挨近我的门框；他们与我中间仅隔一墙，并且行可憎的事，玷污了我的圣名，所以我发怒灭绝他们。'),
('CUV', '以西结书', 26, 43, 9, '现在他们当从我面前远除邪淫和他们君王的尸首，我就住在他们中间直到永远。'),
('CUV', '以西结书', 26, 43, 10, '人子啊，你要将这殿指示以色列家，使他们因自己的罪孽惭愧，也要他们量殿的尺寸。'),
('CUV', '以西结书', 26, 43, 11, '他们若因自己所行的一切事惭愧，你就将殿的规模、样式、出入之处，和一切形状、典章、礼仪、法则指示他们，在他们眼前写上，使他们遵照殿的一切规模典章去做。'),
('CUV', '以西结书', 26, 43, 12, '殿的法则乃是如此：殿在山顶上，四围的全界要称为至圣。这就是殿的法则。'),
('CUV', '以西结书', 26, 43, 13, '以下量祭坛，是以肘为度（这肘是一肘零一掌）。底座高一肘，边宽一肘，四围起边高一掌，这是坛的座。'),
('CUV', '以西结书', 26, 43, 14, '从底座到下层磴台，高二肘，边宽一肘。从小磴台到大磴台，高四肘，边宽一肘。'),
('CUV', '以西结书', 26, 43, 15, '坛上的供台，高四肘。供台的四拐角上都有角。'),
('CUV', '以西结书', 26, 43, 16, '供台长十二肘，宽十二肘，四面见方。'),
('CUV', '以西结书', 26, 43, 17, '磴台长十四肘，宽十四肘，四面见方。四围起边高半肘，底座四围的边宽一肘。台阶朝东。'),
('CUV', '以西结书', 26, 43, 18, '他对我说：人子啊，主耶和华如此说：建造祭坛，为要在其上献燔祭洒血，造成的时候典章如下：'),
('CUV', '以西结书', 26, 43, 19, '主耶和华说，你要将一只公牛犊作为赎罪祭，给祭司利未人撒督的后裔，就是那亲近我、事奉我的。'),
('CUV', '以西结书', 26, 43, 20, '你要取些公牛的血，抹在坛的四角和磴台的四拐角，并四围所起的边上。你这样洁净坛，坛就洁净了。'),
('CUV', '以西结书', 26, 43, 21, '你又要将那作赎罪祭的公牛犊烧在殿外、圣地之外预定之处。'),
('CUV', '以西结书', 26, 43, 22, '次日，要将无残疾的公山羊献为赎罪祭；要洁净坛，像用公牛犊洁净的一样。'),
('CUV', '以西结书', 26, 43, 23, '洁净了坛，就要将一只无残疾的公牛犊和羊群中一只无残疾的公绵羊'),
('CUV', '以西结书', 26, 43, 24, '奉到耶和华前。祭司要撒盐在其上，献与耶和华为燔祭。'),
('CUV', '以西结书', 26, 43, 25, '七日内，每日要预备一只公山羊为赎罪祭，也要预备一只公牛犊和羊群中的一只公绵羊，都要没有残疾的。'),
('CUV', '以西结书', 26, 43, 26, '七日祭司洁净坛，坛就洁净了；要这样把坛分别为圣。'),
('CUV', '以西结书', 26, 43, 27, '满了七日，自八日以后，祭司要在坛上献你们的燔祭和平安祭；我必悦纳你们。这是主耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 44, 1, '他又带我回到圣地朝东的外门；那门关闭了。'),
('CUV', '以西结书', 26, 44, 2, '耶和华对我说：这门必须关闭，不可敞开，谁也不可由其中进入；因为耶和华─以色列的神已经由其中进入，所以必须关闭。'),
('CUV', '以西结书', 26, 44, 3, '至于王，他必按王的位分，坐在其内，在耶和华面前吃饼。他必由这门的廊而入，也必由此而出。'),
('CUV', '以西结书', 26, 44, 4, '他又带我由北门来到殿前。我观看，见耶和华的荣光充满耶和华的殿，我就俯伏在地。'),
('CUV', '以西结书', 26, 44, 5, '耶和华对我说：人子啊，我对你所说耶和华殿中的一切典章法则，你要放在心上，用眼看，用耳听，并要留心殿宇和圣地一切出入之处。'),
('CUV', '以西结书', 26, 44, 6, '你要对那悖逆的以色列家说，主耶和华如此说：以色列家啊，你们行一切可憎的事，当够了罢！'),
('CUV', '以西结书', 26, 44, 7, '你们把我的食物，就是脂油和血献上的时候，将身心未受割礼的外邦人领进我的圣地，玷污了我的殿；又背了我的约，在你们一切可憎的事上，加上这一层。'),
('CUV', '以西结书', 26, 44, 8, '你们也没有看守我的圣物，却派别人在圣地替你们看守我所吩咐你们的。'),
('CUV', '以西结书', 26, 44, 9, '主耶和华如此说：以色列中的外邦人，就是身心未受割礼的，都不可入我的圣地。'),
('CUV', '以西结书', 26, 44, 10, '当以色列人走迷的时候，有利未人远离我，就是走迷离开我、随从他们的偶像，他们必担当自己的罪孽。'),
('CUV', '以西结书', 26, 44, 11, '然而他们必在我的圣地当仆役，照管殿门，在殿中供职；必为民宰杀燔祭牲和平安祭牲，必站在民前伺候他们。'),
('CUV', '以西结书', 26, 44, 12, '因为这些利未人曾在偶像前伺候这民，成了以色列家罪孽的绊脚石，所以我向他们起誓：他们必担当自己的罪孽。这是主耶和华说的。'),
('CUV', '以西结书', 26, 44, 13, '他们不可亲近我，给我供祭司的职分，也不可挨近我的一件圣物，就是至圣的物；他们却要担当自己的羞辱和所行可憎之事的报应。'),
('CUV', '以西结书', 26, 44, 14, '然而我要使他们看守殿宇，办理其中的一切事，并做其内一切当做之工。'),
('CUV', '以西结书', 26, 44, 15, '以色列人走迷离开我的时候，祭司利未人撒督的子孙仍看守我的圣所。他们必亲近我，事奉我，并且侍立在我面前，将脂油与血献给我。这是主耶和华说的。'),
('CUV', '以西结书', 26, 44, 16, '他们必进入我的圣所，就近我的桌前事奉我，守我所吩咐的。'),
('CUV', '以西结书', 26, 44, 17, '他们进内院门必穿细麻衣。在内院门和殿内供职的时候不可穿羊毛衣服。'),
('CUV', '以西结书', 26, 44, 18, '他们头上要戴细麻布裹头巾，腰穿细麻布裤子；不可穿使身体出汗的衣服。'),
('CUV', '以西结书', 26, 44, 19, '他们出到外院的民那里，当脱下供职的衣服，放在圣屋内，穿上别的衣服，免得因圣衣使民成圣。'),
('CUV', '以西结书', 26, 44, 20, '不可剃头，也不可容发绺长长，只可剪发。'),
('CUV', '以西结书', 26, 44, 21, '祭司进内院的时候都不可喝酒。'),
('CUV', '以西结书', 26, 44, 22, '不可娶寡妇和被休的妇人为妻，只可娶以色列后裔中的处女，或是祭司遗留的寡妇。'),
('CUV', '以西结书', 26, 44, 23, '他们要使我的民知道圣俗的分别，又使他们分辨洁净的和不洁净的。'),
('CUV', '以西结书', 26, 44, 24, '有争讼的事，他们应当站立判断，要按我的典章判断。在我一切的节期必守我的律法、条例，也必以我的安息日为圣日。'),
('CUV', '以西结书', 26, 44, 25, '他们不可挨近死尸沾染自己，只可为父亲、母亲、儿子、女儿、弟兄，和未嫁人的姊妹沾染自己。'),
('CUV', '以西结书', 26, 44, 26, '祭司洁净之后，必再计算七日。'),
('CUV', '以西结书', 26, 44, 27, '当他进内院，进圣所，在圣所中事奉的日子，要为自己献赎罪祭。这是主耶和华说的。'),
('CUV', '以西结书', 26, 44, 28, '祭司必有产业，我是他们的产业。不可在以色列中给他们基业；我是他们的基业。'),
('CUV', '以西结书', 26, 44, 29, '素祭、赎罪祭，和赎愆祭他们都可以吃，以色列中一切永献的物都要归他们。'),
('CUV', '以西结书', 26, 44, 30, '首先初熟之物和一切所献的供物都要归给祭司。你们也要用初熟的麦子磨面给祭司；这样，福气就必临到你们的家了。'),
('CUV', '以西结书', 26, 44, 31, '无论是鸟是兽，凡自死的，或是撕裂的，祭司都不可吃。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 45, 1, '你们拈阄分地为业，要献上一分给耶和华为圣供地，长二万五千肘，宽一万肘。这分以内，四围都为圣地。'),
('CUV', '以西结书', 26, 45, 2, '其中有作为圣所之地，长五百肘，宽五百肘，四面见方。四围再有五十肘为郊野之地。'),
('CUV', '以西结书', 26, 45, 3, '要以肘为度量地，长二万五千肘，宽一万肘。其中有圣所，是至圣的。'),
('CUV', '以西结书', 26, 45, 4, '这是全地的一分圣地，要归与供圣所职事的祭司，就是亲近事奉耶和华的，作为他们房屋之地与圣所之圣地。'),
('CUV', '以西结书', 26, 45, 5, '又有一分，长二万五千肘，宽一万肘，要归与在殿中供职的利未人，作为二十间房屋之业。'),
('CUV', '以西结书', 26, 45, 6, '也要分定属城的地业，宽五千肘，长二万五千肘，挨著那分圣供地，要归以色列全家。'),
('CUV', '以西结书', 26, 45, 7, '归王之地要在圣供地和属城之地的两旁，就是圣供地和属城之地的旁边，西至西头，东至东头，从西到东，其长与每支派的分一样。'),
('CUV', '以西结书', 26, 45, 8, '这地在以色列中必归王为业。我所立的王必不再欺压我的民，却要按支派将地分给以色列家。'),
('CUV', '以西结书', 26, 45, 9, '主耶和华如此说：以色列的王啊，你们应当知足，要除掉强暴和抢夺的事，施行公平和公义，不再勒索我的民。这是主耶和华说的。'),
('CUV', '以西结书', 26, 45, 10, '你们要用公道天平、公道伊法、公道罢特。'),
('CUV', '以西结书', 26, 45, 11, '伊法与罢特大小要一样。罢特可盛贺梅珥十分之一，伊法也可盛贺梅珥十分之一，都以贺梅珥的大小为准。'),
('CUV', '以西结书', 26, 45, 12, '舍客勒是二十季拉；二十舍客勒，二十五舍客勒，十五舍客勒，为你们的弥那。'),
('CUV', '以西结书', 26, 45, 13, '你们当献的供物乃是这样：一贺梅珥麦子要献伊法六分之一；一贺梅珥大麦要献伊法六分之一。'),
('CUV', '以西结书', 26, 45, 14, '你们献所分定的油，按油的罢特，一柯珥油要献罢特十分之一（原来十罢特就是一贺梅珥）。'),
('CUV', '以西结书', 26, 45, 15, '从以色列滋润的草场上每二百羊中，要献一只羊羔。这都可作素祭、燔祭、平安祭，为民赎罪。这是主耶和华说的。'),
('CUV', '以西结书', 26, 45, 16, '此地的民都要奉上这供物给以色列中的王。'),
('CUV', '以西结书', 26, 45, 17, '王的本分是在节期、月朔、安息日，就是以色列家一切的节期，奉上燔祭、素祭、奠祭。他要预备赎罪祭、素祭、燔祭，和平安祭，为以色列家赎罪。'),
('CUV', '以西结书', 26, 45, 18, '主耶和华如此说：正月初一日，你要取无残疾的公牛犊，洁净圣所。'),
('CUV', '以西结书', 26, 45, 19, '祭司要取些赎罪祭牲的血，抹在殿的门柱上和坛磴台的四角上，并内院的门框上。'),
('CUV', '以西结书', 26, 45, 20, '本月初七日（七十士译本是七月初一日）也要为误犯罪的和愚蒙犯罪的如此行，为殿赎罪。'),
('CUV', '以西结书', 26, 45, 21, '正月十四日，你们要守逾越节，守节七日，要吃无酵饼。'),
('CUV', '以西结书', 26, 45, 22, '当日，王要为自己和国内的众民预备一只公牛作赎罪祭。'),
('CUV', '以西结书', 26, 45, 23, '这节的七日，每日他要为耶和华预备无残疾的公牛七只、公绵羊七只为燔祭。每日又要预备公山羊一只为赎罪祭。'),
('CUV', '以西结书', 26, 45, 24, '他也要预备素祭，就是为一只公牛同献一伊法细面，为一只公绵羊同献一伊法细面，每一伊法细面加油一欣。'),
('CUV', '以西结书', 26, 45, 25, '七月十五日守节的时候，七日他都要如此行，照逾越节的赎罪祭、燔祭、素祭，和油的条例一样。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 46, 1, '主耶和华如此说：内院朝东的门，在办理事务的六日内必须关闭；惟有安息日和月朔必须敞开。'),
('CUV', '以西结书', 26, 46, 2, '王要从这门的廊进入，站在门框旁边。祭司要为他预备燔祭和平安祭，他就要在门槛那里敬拜，然后出去。这门直到晚上不可关闭。'),
('CUV', '以西结书', 26, 46, 3, '在安息日和月朔，国内的居民要在这门口，耶和华面前敬拜。'),
('CUV', '以西结书', 26, 46, 4, '安息日，王所献与耶和华的燔祭要用无残疾的羊羔六只，无残疾的公绵羊一只；'),
('CUV', '以西结书', 26, 46, 5, '同献的素祭要为公绵羊献一伊法细面，为羊羔照他的力量而献，一伊法细面加油一欣。'),
('CUV', '以西结书', 26, 46, 6, '当月朔，要献无残疾的公牛犊一只，羊羔六只，公绵羊一只，都要无残疾的。'),
('CUV', '以西结书', 26, 46, 7, '他也要预备素祭，为公牛献一伊法细面，为公绵羊献一伊法细面，为羊羔照他的力量而献，一伊法细面加油一欣。'),
('CUV', '以西结书', 26, 46, 8, '王进入的时候必由这门的廊而入，也必由此而出。'),
('CUV', '以西结书', 26, 46, 9, '在各节期，国内居民朝见耶和华的时候，从北门进入敬拜的，必由南门而出；从南门进入的，必由北门而出。不可从所入的门而出，必要直往前行，由对门而出。'),
('CUV', '以西结书', 26, 46, 10, '民进入，王也要在民中进入；民出去，王也要一同出去。'),
('CUV', '以西结书', 26, 46, 11, '在节期和圣会的日子同献的素祭，要为一只公牛献一伊法细面，为一只公绵羊献一伊法细面，为羊羔照他的力量而献，一伊法细面加油一欣。'),
('CUV', '以西结书', 26, 46, 12, '王预备甘心献的燔祭或平安祭，就是向耶和华甘心献的，当有人为他开朝东的门。他就预备燔祭和平安祭，与安息日预备的一样，献毕就出去。他出去之后，当有人将门关闭。'),
('CUV', '以西结书', 26, 46, 13, '每日，你要预备无残疾一岁的羊羔一只，献与耶和华为燔祭；要每早晨预备。'),
('CUV', '以西结书', 26, 46, 14, '每早晨也要预备同献的素祭，细面一伊法六分之一，并油一欣三分之一，调和细面。这素祭要常献与耶和华为永远的定例。'),
('CUV', '以西结书', 26, 46, 15, '每早晨要这样预备羊羔、素祭，并油为常献的燔祭。'),
('CUV', '以西结书', 26, 46, 16, '主耶和华如此说：王若将产业赐给他的儿子，就成了他儿子的产业，那是他们承受为业的。'),
('CUV', '以西结书', 26, 46, 17, '倘若王将一分产业赐给他的臣仆，就成了他臣仆的产业；到自由之年仍要归与王。至于王的产业，必归与他的儿子。'),
('CUV', '以西结书', 26, 46, 18, '王不可夺取民的产业，以致驱逐他们离开所承受的；他要从自己的地业中，将产业赐给他儿子，免得我的民分散，各人离开所承受的。'),
('CUV', '以西结书', 26, 46, 19, '那带我的，将我从门旁进入之处、领进为祭司预备的圣屋，是朝北的，见后头西边有一块地。'),
('CUV', '以西结书', 26, 46, 20, '他对我说：这是祭司煮赎愆祭、赎罪祭，烤素祭之地，免得带到外院，使民成圣。'),
('CUV', '以西结书', 26, 46, 21, '他又带我到外院，使我经过院子的四拐角，见每拐角各有一个院子。'),
('CUV', '以西结书', 26, 46, 22, '院子四拐角的院子，周围有墙，每院长四十肘，宽三十肘。四拐角院子的尺寸都是一样，'),
('CUV', '以西结书', 26, 46, 23, '其中周围有一排房子，房子内有煮肉的地方。'),
('CUV', '以西结书', 26, 46, 24, '他对我说：这都是煮肉的房子，殿内的仆役要在这里煮民的祭物。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 47, 1, '他带我回到殿门，见殿的门槛下有水往东流出（原来殿面朝东）。这水从槛下，由殿的右边，在祭坛的南边往下流。'),
('CUV', '以西结书', 26, 47, 2, '他带我出北门，又领我从外边转到朝东的外门，见水从右边流出。'),
('CUV', '以西结书', 26, 47, 3, '他手拿准绳往东出去的时候，量了一千肘，使我逿过水，水到踝子骨。'),
('CUV', '以西结书', 26, 47, 4, '他又量了一千肘，使我逿过水，水就到膝；再量了一千肘，使我逿过水，水便到腰；'),
('CUV', '以西结书', 26, 47, 5, '又量了一千肘，水便成了河，使我不能逿过。因为水势涨起，成为可洑的水，不可逿的河。'),
('CUV', '以西结书', 26, 47, 6, '他对我说：人子啊，你看见了甚么？他就带我回到河边。'),
('CUV', '以西结书', 26, 47, 7, '我回到河边的时候，见在河这边与那边的岸上有极多的树木。'),
('CUV', '以西结书', 26, 47, 8, '他对我说：这水往东方流去，必下到亚拉巴，直到海。所发出来的水必流入盐海，使水变甜（原文是得医治；下同）。'),
('CUV', '以西结书', 26, 47, 9, '这河水所到之处，凡滋生的动物都必生活，并且因这流来的水必有极多的鱼，海水也变甜了。这河水所到之处，百物都必生活。'),
('CUV', '以西结书', 26, 47, 10, '必有渔夫站在河边，从隐基底直到隐以革莲，都作晒（或译：张）网之处。那鱼各从其类，好像大海的鱼甚多。'),
('CUV', '以西结书', 26, 47, 11, '只是泥泞之地与洼湿之处不得治好，必为盐地。'),
('CUV', '以西结书', 26, 47, 12, '在河这边与那边的岸上必生长各类的树木；其果可作食物，叶子不枯干，果子不断绝。每月必结新果子，因为这水是从圣所流出来的。树上的果子必作食物，叶子乃为治病。'),
('CUV', '以西结书', 26, 47, 13, '主耶和华如此说：你们要照地的境界，按以色列十二支派分地为业。约瑟必得两分。'),
('CUV', '以西结书', 26, 47, 14, '你们承受这地为业，要彼此均分；因为我曾起誓应许将这地赐与你们的列祖；这地必归你们为业。'),
('CUV', '以西结书', 26, 47, 15, '地的四界乃是如此：北界从大海往希特伦，直到西达达口。'),
('CUV', '以西结书', 26, 47, 16, '又往哈马、比罗他、西伯莲（西伯莲在大马色与哈马两界中间），到浩兰边界的哈撒哈提干。'),
('CUV', '以西结书', 26, 47, 17, '这样，境界从海边往大马色地界上的哈萨以难，北边以哈马地为界。这是北界。'),
('CUV', '以西结书', 26, 47, 18, '东界在浩兰、大马色、基列，和以色列地的中间，就是约但河。你们要从北界量到东海。这是东界。'),
('CUV', '以西结书', 26, 47, 19, '南界是从他玛到米利巴加低斯的水，延到埃及小河，直到大海。这是南界。'),
('CUV', '以西结书', 26, 47, 20, '西界就是大海，从南界直到哈马口对面之地。这是西界。'),
('CUV', '以西结书', 26, 47, 21, '你们要按著以色列的支派彼此分这地。'),
('CUV', '以西结书', 26, 47, 22, '要拈阄分这地为业，归与自己和你们中间寄居的外人，就是在你们中间生养儿女的外人。你们要看他们如同以色列人中所生的一样；他们在以色列支派中要与你们同得地业'),
('CUV', '以西结书', 26, 47, 23, '外人寄居在哪支派中，你们就在那里分给他地业。这是主耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '以西结书', 26, 48, 1, '众支派按名所得之地记在下面：从北头，由希特伦往哈马口，到大马色地界上的哈萨以难。北边靠著哈马地（各支派的地都有东西的边界），是但的一分。'),
('CUV', '以西结书', 26, 48, 2, '挨著但的地界，从东到西，是亚设的一分。'),
('CUV', '以西结书', 26, 48, 3, '挨著亚设的地界，从东到西，是拿弗他利的一分。'),
('CUV', '以西结书', 26, 48, 4, '挨著拿弗他利的地界，从东到西，是玛拿西的一分。'),
('CUV', '以西结书', 26, 48, 5, '挨著玛拿西的地界，从东到西，是以法莲的一分。'),
('CUV', '以西结书', 26, 48, 6, '挨著以法莲的地界，从东到西，是流便的一分。'),
('CUV', '以西结书', 26, 48, 7, '挨著流便的地界，从东到西，是犹大的一分。'),
('CUV', '以西结书', 26, 48, 8, '挨著犹大的地界，从东到西，必有你们所当献的供地，宽二万五千肘。从东界到西界，长短与各分之地相同，圣地当在其中。'),
('CUV', '以西结书', 26, 48, 9, '你们献与耶和华的供地要长二万五千肘，宽一万肘。'),
('CUV', '以西结书', 26, 48, 10, '这圣供地要归与祭司，北长二万五千肘，西宽一万肘，东宽一万肘，南长二万五千肘。耶和华的圣地当在其中。'),
('CUV', '以西结书', 26, 48, 11, '这地要归与撒督的子孙中成为圣的祭司，就是那守我所吩咐的。当以色列人走迷的时候，他们不像那些利未人走迷了。'),
('CUV', '以西结书', 26, 48, 12, '这要归与他们为供地，是全地中至圣的。供地挨著利未人的地界。'),
('CUV', '以西结书', 26, 48, 13, '利未人所得的地要长二万五千肘，宽一万肘，与祭司的地界相等，都长二万五千肘，宽一万肘。'),
('CUV', '以西结书', 26, 48, 14, '这地不可卖，不可换，初熟之物也不可归与别人，因为是归耶和华为圣的。'),
('CUV', '以西结书', 26, 48, 15, '这二万五千肘前面所剩下五千肘宽之地要作俗用，作为造城盖房郊野之地。城要在当中。'),
('CUV', '以西结书', 26, 48, 16, '城的尺寸乃是如此：北面四千五百肘，南面四千五百肘，东面四千五百肘，西面四千五百肘。'),
('CUV', '以西结书', 26, 48, 17, '城必有郊野，向北二百五十肘，向南二百五十肘，向东二百五十肘，向西二百五十肘。'),
('CUV', '以西结书', 26, 48, 18, '靠著圣供地的余地，东长一万肘，西长一万肘，要与圣供地相等；其中的土产要作城内工人的食物。'),
('CUV', '以西结书', 26, 48, 19, '所有以色列支派中，在城内做工的，都要耕种这地。'),
('CUV', '以西结书', 26, 48, 20, '你们所献的圣供地连归城之地，是四方的：长二万五千肘，宽二万五千肘。'),
('CUV', '以西结书', 26, 48, 21, '圣供地连归城之地，两边的余地要归与王。供地东边，南北二万五千肘，东至东界，西边南北二万五千肘，西至西界，与各分之地相同，都要归王。圣供地和殿的圣地要在其中，'),
('CUV', '以西结书', 26, 48, 22, '并且利未人之地，与归城之地的东西两边延长之地（这两地在王地中间），就是在犹大和便雅悯两界中间，要归与王。'),
('CUV', '以西结书', 26, 48, 23, '论到其余的支派，从东到西，是便雅悯的一分。'),
('CUV', '以西结书', 26, 48, 24, '挨著便雅悯的地界，从东到西，是西缅的一分。'),
('CUV', '以西结书', 26, 48, 25, '挨著西缅的地界，从东到西，是以萨迦的一分。'),
('CUV', '以西结书', 26, 48, 26, '挨著以萨迦的地界，从东到西，是西布伦的一分。'),
('CUV', '以西结书', 26, 48, 27, '挨著西布伦的地界，从东到西，是迦得的一分。'),
('CUV', '以西结书', 26, 48, 28, '迦得地的南界是从他玛到米利巴加低斯的水，延到埃及小河，直到大海。'),
('CUV', '以西结书', 26, 48, 29, '这就是你们要拈阄分给以色列支派为业之地，乃是他们各支派所得之分。这是主耶和华说的。'),
('CUV', '以西结书', 26, 48, 30, '城的北面四千五百肘。出城之处如下；'),
('CUV', '以西结书', 26, 48, 31, '城的各门要按以色列支派的名字。北面有三门，一为流便门，一为犹大门，一为利未门；'),
('CUV', '以西结书', 26, 48, 32, '东面四千五百肘，有三门，一为约瑟门，一为便雅悯门，一为但门；'),
('CUV', '以西结书', 26, 48, 33, '南面四千五百肘，有三门，一为西缅门，一为以萨迦门，一为西布伦门；'),
('CUV', '以西结书', 26, 48, 34, '西面四千五百肘，有三门，一为迦得门，一为亚设门，一为拿弗他利门。'),
('CUV', '以西结书', 26, 48, 35, '城四围共一万八千肘。从此以后，这城的名字必称为耶和华的所在。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '但以理书', 27, 1, 1, '犹大王约雅敬在位第三年，巴比伦王尼布甲尼撒来到耶路撒冷，将城围困。'),
('CUV', '但以理书', 27, 1, 2, '主将犹大王约雅敬，并神殿中器皿的几分交付他手。他就把这器皿带到示拿地，收入他神的庙里，放在他神的库中。'),
('CUV', '但以理书', 27, 1, 3, '王吩咐太监长亚施毗拿，从以色列人的宗室和贵胄中带进几个人来，'),
('CUV', '但以理书', 27, 1, 4, '就是年少没有残疾、相貌俊美、通达各样学问、知识聪明俱备、足能侍立在王宫里的，要教他们迦勒底的文字言语。'),
('CUV', '但以理书', 27, 1, 5, '王派定将自己所用的膳和所饮的酒，每日赐他们一分，养他们三年。满了三年，好叫他们在王面前侍立。'),
('CUV', '但以理书', 27, 1, 6, '他们中间有犹大族的人：但以理、哈拿尼雅、米沙利、亚撒利雅。'),
('CUV', '但以理书', 27, 1, 7, '太监长给他们起名：称但以理为伯提沙撒，称哈拿尼雅为沙得拉，称米沙利为米煞，称亚撒利雅为亚伯尼歌。'),
('CUV', '但以理书', 27, 1, 8, '但以理却立志不以王的膳和王所饮的酒玷污自己，所以求太监长容他不玷污自己。'),
('CUV', '但以理书', 27, 1, 9, '神使但以理在太监长眼前蒙恩惠，受怜悯。'),
('CUV', '但以理书', 27, 1, 10, '太监长对但以理说：我惧怕我主我王，他已经派定你们的饮食；倘若他见你们的面貌比你们同岁的少年人肌瘦，怎么好呢？这样，你们就使我的头在王那里难保。'),
('CUV', '但以理书', 27, 1, 11, '但以理对太监长所派管理但以理、哈拿尼雅、米沙利、亚撒利雅的委办说：'),
('CUV', '但以理书', 27, 1, 12, '求你试试仆人们十天，给我们素菜吃，白水喝，'),
('CUV', '但以理书', 27, 1, 13, '然后看看我们的面貌和用王膳那少年人的面貌，就照你所看的待仆人罢！'),
('CUV', '但以理书', 27, 1, 14, '委办便允准他们这件事，试看他们十天。'),
('CUV', '但以理书', 27, 1, 15, '过了十天，见他们的面貌比用王膳的一切少年人更加俊美肥胖。'),
('CUV', '但以理书', 27, 1, 16, '于是委办撤去派他们用的膳，饮的酒，给他们素菜吃。'),
('CUV', '但以理书', 27, 1, 17, '这四个少年人，神在各样文字学问（学问：原文是智慧）上赐给他们聪明知识；但以理又明白各样的异象和梦兆。'),
('CUV', '但以理书', 27, 1, 18, '尼布甲尼撒王预定带进少年人来的日期满了，太监长就把他们带到王面前。'),
('CUV', '但以理书', 27, 1, 19, '王与他们谈论，见少年人中无一人能比但以理、哈拿尼雅、米沙利、亚撒利雅，所以留他们在王面前侍立。'),
('CUV', '但以理书', 27, 1, 20, '王考问他们一切事，就见他们的智慧聪明比通国的术士和用法术的胜过十倍。'),
('CUV', '但以理书', 27, 1, 21, '到古列王元年，但以理还在。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '但以理书', 27, 2, 1, '尼布甲尼撒在位第二年，他做了梦，心里烦乱，不能睡觉。'),
('CUV', '但以理书', 27, 2, 2, '王吩咐人将术士、用法术的、行邪术的，和迦勒底人召来，要他们将王的梦告诉王，他们就来站在王前。'),
('CUV', '但以理书', 27, 2, 3, '王对他们说：我做了一梦，心里烦乱，要知道这是甚么梦。'),
('CUV', '但以理书', 27, 2, 4, '迦勒底人用亚兰的言语对王说：愿王万岁！请将那梦告诉仆人，仆人就可以讲解。'),
('CUV', '但以理书', 27, 2, 5, '王回答迦勒底人说：梦我已经忘了（或译：我已定命；八节同），你们若不将梦和梦的讲解告诉我，就必被凌迟，你们的房屋必成为粪堆；'),
('CUV', '但以理书', 27, 2, 6, '你们若将梦和梦的讲解告诉我，就必从我这里得赠品和赏赐，并大尊荣。现在你们要将梦和梦的讲解告诉我。'),
('CUV', '但以理书', 27, 2, 7, '他们第二次对王说：请王将梦告诉仆人，仆人就可以讲解。'),
('CUV', '但以理书', 27, 2, 8, '王回答说：我准知道你们是故意迟延，因为你们知道那梦我已经忘了。'),
('CUV', '但以理书', 27, 2, 9, '你们若不将梦告诉我，只有一法待你们；因为你们预备了谎言乱语向我说，要等候时势改变。现在你们要将梦告诉我，因我知道你们能将梦的讲解告诉我。'),
('CUV', '但以理书', 27, 2, 10, '迦勒底人在王面前回答说：世上没有人能将王所问的事说出来；因为没有君王、大臣、掌权的向术士，或用法术的，或迦勒底人问过这样的事。'),
('CUV', '但以理书', 27, 2, 11, '王所问的事甚难。除了不与世人同居的神明，没有人在王面前能说出来。'),
('CUV', '但以理书', 27, 2, 12, '因此，王气忿忿地大发烈怒，吩咐灭绝巴比伦所有的哲士。'),
('CUV', '但以理书', 27, 2, 13, '于是命令发出，哲士将要见杀，人就寻找但以理和他的同伴，要杀他们。'),
('CUV', '但以理书', 27, 2, 14, '王的护卫长亚略出来，要杀巴比伦的哲士，但以理就用婉言回答他，'),
('CUV', '但以理书', 27, 2, 15, '向王的护卫长亚略说：王的命令为何这样紧急呢？亚略就将情节告诉但以理。'),
('CUV', '但以理书', 27, 2, 16, '但以理遂进去求王宽限，就可以将梦的讲解告诉王。'),
('CUV', '但以理书', 27, 2, 17, '但以理回到他的居所，将这事告诉他的同伴哈拿尼雅、米沙利、亚撒利雅，'),
('CUV', '但以理书', 27, 2, 18, '要他们祈求天上的神施怜悯，将这奥秘的事指明，免得但以理和他的同伴与巴比伦其余的哲士一同灭亡。'),
('CUV', '但以理书', 27, 2, 19, '这奥秘的事就在夜间异象中给但以理显明，但以理便称颂天上的神。'),
('CUV', '但以理书', 27, 2, 20, '但以理说：神的名是应当称颂的！从亘古直到永远，因为智慧能力都属乎他。'),
('CUV', '但以理书', 27, 2, 21, '他改变时候、日期，废王，立王，将智慧赐与智慧人，将知识赐与聪明人。'),
('CUV', '但以理书', 27, 2, 22, '他显明深奥隐秘的事，知道暗中所有的，光明也与他同居。'),
('CUV', '但以理书', 27, 2, 23, '我列祖的神啊，我感谢你，赞美你，因你将智慧才能赐给我，允准我们所求的，把王的事给我们指明。'),
('CUV', '但以理书', 27, 2, 24, '于是，但以理进去见亚略，就是王所派灭绝巴比伦哲士的，对他说：不要灭绝巴比伦的哲士，求你领我到王面前，我要将梦的讲解告诉王。'),
('CUV', '但以理书', 27, 2, 25, '亚略就急忙将但以理领到王面前，对王说：我在被掳的犹大人中遇见一人，他能将梦的讲解告诉王。'),
('CUV', '但以理书', 27, 2, 26, '王问称为伯提沙撒的但以理说：你能将我所做的梦和梦的讲解告诉我么？'),
('CUV', '但以理书', 27, 2, 27, '但以理在王面前回答说：王所问的那奥秘事，哲士、用法术的、术士、观兆的都不能告诉王；'),
('CUV', '但以理书', 27, 2, 28, '只有一位在天上的神能显明奥秘的事。他已将日后必有的事指示尼布甲尼撒王。你的梦和你在床上脑中的异象是这样：'),
('CUV', '但以理书', 27, 2, 29, '王啊，你在床上想到后来的事，那显明奥秘事的主把将来必有的事指示你。'),
('CUV', '但以理书', 27, 2, 30, '至于那奥秘的事显明给我，并非因我的智慧胜过一切活人，乃为使王知道梦的讲解和心里的思念。'),
('CUV', '但以理书', 27, 2, 31, '王啊，你梦见一个大像，这像甚高，极其光耀，站在你面前，形状甚是可怕。'),
('CUV', '但以理书', 27, 2, 32, '这像的头是精金的，胸膛和膀臂是银的，肚腹和腰是铜的，'),
('CUV', '但以理书', 27, 2, 33, '腿是铁的，脚是半铁半泥的。'),
('CUV', '但以理书', 27, 2, 34, '你观看，见有一块非人手凿出来的石头打在这像半铁半泥的脚上，把脚砸碎；'),
('CUV', '但以理书', 27, 2, 35, '于是金、银、铜、铁、泥都一同砸得粉碎，成如夏天禾场上的糠秕，被风吹散，无处可寻。打碎这像的石头变成一座大山，充满天下。'),
('CUV', '但以理书', 27, 2, 36, '这就是那梦。我们在王面前要讲解那梦。'),
('CUV', '但以理书', 27, 2, 37, '王啊，你是诸王之王。天上的神已将国度、权柄、能力、尊荣都赐给你。'),
('CUV', '但以理书', 27, 2, 38, '凡世人所住之地的走兽，并天空的飞鸟，他都交付你手，使你掌管这一切。你就是那金头。'),
('CUV', '但以理书', 27, 2, 39, '在你以后必另兴一国，不及于你；又有第三国，就是铜的，必掌管天下。'),
('CUV', '但以理书', 27, 2, 40, '第四国，必坚壮如铁，铁能打碎克制百物，又能压碎一切，那国也必打碎压制列国。'),
('CUV', '但以理书', 27, 2, 41, '你既见像的脚和脚指头，一半是窑匠的泥，一半是铁，那国将来也必分开。你既见铁与泥搀杂，那国也必有铁的力量。'),
('CUV', '但以理书', 27, 2, 42, '那脚指头，既是半铁半泥，那国也必半强半弱。'),
('CUV', '但以理书', 27, 2, 43, '你既见铁与泥搀杂，那国民也必与各种人搀杂，却不能彼此相合，正如铁与泥不能相合一样。'),
('CUV', '但以理书', 27, 2, 44, '当那列王在位的时候，天上的神必另立一国，永不败坏，也不归别国的人，却要打碎灭绝那一切国，这国必存到永远。'),
('CUV', '但以理书', 27, 2, 45, '你既看见非人手凿出来的一块石头从山而出，打碎金、银、铜、铁、泥，那就是至大的神把后来必有的事给王指明。这梦准是这样，这讲解也是确实的。'),
('CUV', '但以理书', 27, 2, 46, '当时，尼布甲尼撒王俯伏在地，向但以理下拜，并且吩咐人给他奉上供物和香品。'),
('CUV', '但以理书', 27, 2, 47, '王对但以理说：你既能显明这奥秘的事，你们的神诚然是万神之神、万王之主，又是显明奥秘事的。'),
('CUV', '但以理书', 27, 2, 48, '于是王高抬但以理，赏赐他许多上等礼物，派他管理巴比伦全省，又立他为总理，掌管巴比伦的一切哲士。'),
('CUV', '但以理书', 27, 2, 49, '但以理求王，王就派沙得拉、米煞、亚伯尼歌管理巴比伦省的事务，只是但以理常在朝中侍立。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '但以理书', 27, 3, 1, '尼布甲尼撒王造了一个金像，高六十肘，宽六肘，立在巴比伦省杜拉平原。'),
('CUV', '但以理书', 27, 3, 2, '尼布甲尼撒王差人将总督、钦差、巡抚、臬司、藩司、谋士、法官，和各省的官员都召了来，为尼布甲尼撒王所立的像行开光之礼。'),
('CUV', '但以理书', 27, 3, 3, '于是总督、钦差、巡抚、臬司、藩司、谋士、法官，和各省的官员都聚集了来，要为尼布甲尼撒王所立的像行开光之礼，就站在尼布甲尼撒所立的像前。'),
('CUV', '但以理书', 27, 3, 4, '那时传令的大声呼叫说：各方、各国、各族（原文是舌：下同）的人哪，有令传与你们：'),
('CUV', '但以理书', 27, 3, 5, '你们一听见角、笛、琵琶、琴、瑟、笙，和各样乐器的声音，就当俯伏敬拜尼布甲尼撒王所立的金像。'),
('CUV', '但以理书', 27, 3, 6, '凡不俯伏敬拜的，必立时扔在烈火的窑中。'),
('CUV', '但以理书', 27, 3, 7, '因此各方、各国、各族的人民一听见角、笛、琵琶、琴、瑟，和各样乐器的声音，就都俯伏敬拜尼布甲尼撒王所立的金像。'),
('CUV', '但以理书', 27, 3, 8, '那时，有几个迦勒底人进前来控告犹大人。'),
('CUV', '但以理书', 27, 3, 9, '他们对尼布甲尼撒王说：愿王万岁！'),
('CUV', '但以理书', 27, 3, 10, '王啊，你曾降旨说，凡听见角、笛、琵琶、琴、瑟、笙，和各样乐器声音的都当俯伏敬拜金像。'),
('CUV', '但以理书', 27, 3, 11, '凡不俯伏敬拜的，必扔在烈火的窑中。'),
('CUV', '但以理书', 27, 3, 12, '现在有几个犹大人，就是王所派管理巴比伦省事务的沙得拉、米煞、亚伯尼歌；王啊，这些人不理你，不事奉你的神，也不敬拜你所立的金像。'),
('CUV', '但以理书', 27, 3, 13, '当时，尼布甲尼撒冲冲大怒，吩咐人把沙得拉、米煞、亚伯尼歌带过来，他们就把那些人带到王面前。'),
('CUV', '但以理书', 27, 3, 14, '尼布甲尼撒问他们说：沙得拉、米煞、亚伯尼歌，你们不事奉我的神，也不敬拜我所立的金像，是故意的么？'),
('CUV', '但以理书', 27, 3, 15, '你们再听见角、笛、琵琶、琴、瑟、笙，和各样乐器的声音，若俯伏敬拜我所造的像，却还可以；若不敬拜，必立时扔在烈火的窑中，有何神能救你们脱离我手呢？'),
('CUV', '但以理书', 27, 3, 16, '沙得拉、米煞、亚伯尼歌对王说：尼布甲尼撒啊，这件事我们不必回答你；'),
('CUV', '但以理书', 27, 3, 17, '即便如此，我们所事奉的神能将我们从烈火的窑中救出来。王啊，他也必救我们脱离你的手；'),
('CUV', '但以理书', 27, 3, 18, '即或不然，王啊，你当知道我们决不事奉你的神，也不敬拜你所立的金像。'),
('CUV', '但以理书', 27, 3, 19, '当时，尼布甲尼撒怒气填胸，向沙得拉、米煞、亚伯尼歌变了脸色，吩咐人把窑烧热，比寻常更加七倍；'),
('CUV', '但以理书', 27, 3, 20, '又吩咐他军中的几个壮士，将沙得拉、米煞、亚伯尼歌捆起来，扔在烈火的窑中。'),
('CUV', '但以理书', 27, 3, 21, '这三人穿著裤子、内袍、外衣，和别的衣服，被捆起来扔在烈火的窑中。'),
('CUV', '但以理书', 27, 3, 22, '因为王命紧急，窑又甚热，那抬沙得拉、米煞、亚伯尼歌的人都被火燄烧死。'),
('CUV', '但以理书', 27, 3, 23, '沙得拉、米煞、亚伯尼歌这三个人都被捆著落在烈火的窑中。'),
('CUV', '但以理书', 27, 3, 24, '那时，尼布甲尼撒王惊奇，急忙起来，对谋士说：我捆起来扔在火里的不是三个人么？他们回答王说：王啊，是。'),
('CUV', '但以理书', 27, 3, 25, '王说：看哪，我见有四个人，并没有捆绑，在火中游行，也没有受伤；那第四个的相貌好像神子。'),
('CUV', '但以理书', 27, 3, 26, '于是，尼布甲尼撒就近烈火窑门，说：至高神的仆人沙得拉、米煞、亚伯尼歌出来，上这里来罢！沙得拉、米煞、亚伯尼歌就从火中出来了。'),
('CUV', '但以理书', 27, 3, 27, '那些总督、钦差、巡抚，和王的谋士一同聚集看这三个人，见火无力伤他们的身体，头发也没有烧焦，衣裳也没有变色，并没有火燎的气味。'),
('CUV', '但以理书', 27, 3, 28, '尼布甲尼撒说：沙得拉、米煞、亚伯尼歌的神是应当称颂的！他差遣使者救护倚靠他的仆人，他们不遵王命，舍去己身，在他们神以外不肯事奉敬拜别神。'),
('CUV', '但以理书', 27, 3, 29, '现在我降旨，无论何方、何国、何族的人，谤讟沙得拉、米煞、亚伯尼歌之神的，必被凌迟，他的房屋必成粪堆，因为没有别神能这样施行拯救。'),
('CUV', '但以理书', 27, 3, 30, '那时王在巴比伦省，高升了沙得拉、米煞、亚伯尼歌。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '但以理书', 27, 4, 1, '尼布甲尼撒王晓谕住在全地各方、各国、各族的人说：愿你们大享平安！'),
('CUV', '但以理书', 27, 4, 2, '我乐意将至高的神向我所行的神迹奇事宣扬出来。'),
('CUV', '但以理书', 27, 4, 3, '他的神迹何其大！他的奇事何其盛！他的国是永远的；他的权柄存到万代！'),
('CUV', '但以理书', 27, 4, 4, '我尼布甲尼撒安居在宫中，平顺在殿内。'),
('CUV', '但以理书', 27, 4, 5, '我做了一梦，使我惧怕。我在床上的思念，并脑中的异象，使我惊惶。'),
('CUV', '但以理书', 27, 4, 6, '所以我降旨召巴比伦的一切哲士到我面前，叫他们把梦的讲解告诉我。'),
('CUV', '但以理书', 27, 4, 7, '于是那些术士、用法术的、迦勒底人、观兆的都进来，我将那梦告诉了他们，他们却不能把梦的讲解告诉我。'),
('CUV', '但以理书', 27, 4, 8, '末后那照我神的名，称为伯提沙撒的但以理来到我面前，他里头有圣神的灵，我将梦告诉他说：'),
('CUV', '但以理书', 27, 4, 9, '术士的领袖伯提沙撒啊，因我知道你里头有圣神的灵，甚么奥秘的事都不能使你为难。现在要把我梦中所见的异象和梦的讲解告诉我。'),
('CUV', '但以理书', 27, 4, 10, '我在床上脑中的异象是这样：我看见地当中有一棵树，极其高大。'),
('CUV', '但以理书', 27, 4, 11, '那树渐长，而且坚固，高得顶天，从地极都能看见，'),
('CUV', '但以理书', 27, 4, 12, '叶子华美，果子甚多，可作众生的食物；田野的走兽卧在荫下，天空的飞鸟宿在枝上；凡有血气的都从这树得食。'),
('CUV', '但以理书', 27, 4, 13, '我在床上脑中的异象，见有一位守望的圣者从天而降。'),
('CUV', '但以理书', 27, 4, 14, '大声呼叫说：伐倒这树！砍下枝子！摇掉叶子！抛散果子！使走兽离开树下，飞鸟躲开树枝。'),
('CUV', '但以理书', 27, 4, 15, '树墩却要留在地内，用铁圈和铜圈箍住，在田野的青草中让天露滴湿，使他与地上的兽一同吃草，'),
('CUV', '但以理书', 27, 4, 16, '使他的心改变，不如人心；给他一个兽心，使他经过七期（期：或译年；本章同）。'),
('CUV', '但以理书', 27, 4, 17, '这是守望者所发的命，圣者所出的令，好叫世人知道至高者在人的国中掌权，要将国赐与谁就赐与谁，或立极卑微的人执掌国权。'),
('CUV', '但以理书', 27, 4, 18, '这是我─尼布甲尼撒王所做的梦。伯提沙撒啊，你要说明这梦的讲解；因为我国中的一切哲士都不能将梦的讲解告诉我，惟独你能，因你里头有圣神的灵。'),
('CUV', '但以理书', 27, 4, 19, '于是称为伯提沙撒的但以理惊讶片时，心意惊惶。王说：伯提沙撒啊，不要因梦和梦的讲解惊惶。伯提沙撒回答说：我主啊，愿这梦归与恨恶你的人，讲解归与你的敌人。'),
('CUV', '但以理书', 27, 4, 20, '你所见的树渐长，而且坚固，高得顶天，从地极都能看见；'),
('CUV', '但以理书', 27, 4, 21, '叶子华美，果子甚多，可作众生的食物；田野的走兽住在其下；天空的飞鸟宿在枝上。'),
('CUV', '但以理书', 27, 4, 22, '王啊，这渐长又坚固的树就是你。你的威势渐长及天，你的权柄管到地极。'),
('CUV', '但以理书', 27, 4, 23, '王既看见一位守望的圣者从天而降，说：将这树砍伐毁坏，树墩却要留在地内，用铁圈和铜圈箍住；在田野的青草中，让天露滴湿，使他与地上的兽一同吃草，直到经过七期。'),
('CUV', '但以理书', 27, 4, 24, '王啊，讲解就是这样：临到我主我王的事是出于至高者的命。'),
('CUV', '但以理书', 27, 4, 25, '你必被赶出离开世人，与野地的兽同居，吃草如牛，被天露滴湿，且要经过七期。等你知道至高者在人的国中掌权，要将国赐与谁就赐与谁。'),
('CUV', '但以理书', 27, 4, 26, '守望者既吩咐存留树墩，等你知道诸天掌权，以后你的国必定归你。'),
('CUV', '但以理书', 27, 4, 27, '王啊，求你悦纳我的谏言，以施行公义断绝罪过，以怜悯穷人除掉罪孽，或者你的平安可以延长。'),
('CUV', '但以理书', 27, 4, 28, '这事都临到尼布甲尼撒王。'),
('CUV', '但以理书', 27, 4, 29, '过了十二个月，他游行在巴比伦王宫里（原文是上）。'),
('CUV', '但以理书', 27, 4, 30, '他说：这大巴比伦不是我用大能大力建为京都，要显我威严的荣耀么？'),
('CUV', '但以理书', 27, 4, 31, '这话在王口中尚未说完，有声音从天降下，说：尼布甲尼撒王啊，有话对你说，你的国位离开你了。'),
('CUV', '但以理书', 27, 4, 32, '你必被赶出离开世人，与野地的兽同居，吃草如牛，且要经过七期。等你知道至高者在人的国中掌权，要将国赐与谁就赐与谁。'),
('CUV', '但以理书', 27, 4, 33, '当时这话就应验在尼布甲尼撒的身上，他被赶出离开世人，吃草如牛，身被天露滴湿，头发长长，好像鹰毛；指甲长长，如同鸟爪。'),
('CUV', '但以理书', 27, 4, 34, '日子满足，我─尼布甲尼撒举目望天，我的聪明复归于我，我便称颂至高者，赞美尊敬活到永远的神。他的权柄是永有的；他的国存到万代。'),
('CUV', '但以理书', 27, 4, 35, '世上所有的居民都算为虚无；在天上的万军和世上的居民中，他都凭自己的意旨行事。无人能拦住他手，或问他说，你做甚么呢？'),
('CUV', '但以理书', 27, 4, 36, '那时，我的聪明复归于我，为我国的荣耀、威严，和光耀也都复归于我；并且我的谋士和大臣也来朝见我。我又得坚立在国位上，至大的权柄加增于我。'),
('CUV', '但以理书', 27, 4, 37, '现在我─尼布甲尼撒赞美、尊崇、恭敬天上的王；因为他所做的全都诚实，他所行的也都公平。那行动骄傲的，他能降为卑。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '但以理书', 27, 5, 1, '伯沙撒王为他的一千大臣设摆盛筵，与这一千人对面饮酒。'),
('CUV', '但以理书', 27, 5, 2, '伯沙撒欢饮之间，吩咐人将他父（或译：祖；下同）尼布甲尼撒从耶路撒冷殿中所掠的金银器皿拿来，王与大臣、皇后、妃嫔好用这器皿饮酒。'),
('CUV', '但以理书', 27, 5, 3, '于是他们把耶路撒冷神殿库房中所掠的金器皿拿来，王和大臣、皇后、妃嫔就用这器皿饮酒。'),
('CUV', '但以理书', 27, 5, 4, '他们饮酒，赞美金、银、铜、铁、木、石所造的神。'),
('CUV', '但以理书', 27, 5, 5, '当时，忽有人的指头显出，在王宫与灯台相对的粉墙上写字。王看见写字的指头'),
('CUV', '但以理书', 27, 5, 6, '就变了脸色，心意惊惶，腰骨好像脱节，双膝彼此相碰，'),
('CUV', '但以理书', 27, 5, 7, '大声吩咐将用法术的和迦勒底人并观兆的领进来，对巴比伦的哲士说，谁能读这文字，把讲解告诉我，他必身穿紫袍，项带金链，在我国中位列第三。'),
('CUV', '但以理书', 27, 5, 8, '于是王的一切哲士都进来，却不能读那文字，也不能把讲解告诉王。'),
('CUV', '但以理书', 27, 5, 9, '伯沙撒王就甚惊惶，脸色改变，他的大臣也都惊奇。'),
('CUV', '但以理书', 27, 5, 10, '太后（或译：皇后；下同）因王和他大臣所说的话，就进入宴宫，说：愿王万岁！你心意不要惊惶，脸面不要变色。'),
('CUV', '但以理书', 27, 5, 11, '在你国中有一人，他里头有圣神的灵，你父在世的日子，这人心中光明，又有聪明智慧，好像神的智慧。你父尼布甲尼撒王，就是王的父，立他为术士、用法术的，和迦勒底人，并观兆的领袖。'),
('CUV', '但以理书', 27, 5, 12, '在他里头有美好的灵性，又有知识聪明，能圆梦，释谜语，解疑惑。这人名叫但以理，尼布甲尼撒王又称他为伯提沙撒，现在可以召他来，他必解明这意思。'),
('CUV', '但以理书', 27, 5, 13, '但以理就被领到王前。王问但以理说：你是被掳之犹大人中的但以理么？就是我父王从犹大掳来的么？'),
('CUV', '但以理书', 27, 5, 14, '我听说你里头有神的灵，心中光明，又有聪明和美好的智慧。'),
('CUV', '但以理书', 27, 5, 15, '现在哲士和用法术的都领到我面前，为叫他们读这文字，把讲解告诉我，无奈他们都不能把讲解说出来。'),
('CUV', '但以理书', 27, 5, 16, '我听说你善于讲解，能解疑惑；现在你若能读这文字，把讲解告诉我，就必身穿紫袍，项戴金链，在我国中位列第三。'),
('CUV', '但以理书', 27, 5, 17, '但以理在王面前回答说：你的赠品可以归你自己，你的赏赐可以归给别人；我却要为王读这文字，把讲解告诉王。'),
('CUV', '但以理书', 27, 5, 18, '王啊，至高的神曾将国位、大权、荣耀、威严赐与你父尼布甲尼撒；'),
('CUV', '但以理书', 27, 5, 19, '因神所赐他的大权，各方、各国、各族的人都在他面前战兢恐惧。他可以随意生杀，随意升降。'),
('CUV', '但以理书', 27, 5, 20, '但他心高气傲，灵也刚愎，甚至行事狂傲，就被革去王位，夺去荣耀。'),
('CUV', '但以理书', 27, 5, 21, '他被赶出离开世人，他的心变如兽心，与野驴同居，吃草如牛，身被天露滴湿，等他知道至高的神在人的国中掌权，凭自己的意旨立人治国。'),
('CUV', '但以理书', 27, 5, 22, '伯沙撒啊，你是他的儿子（或译：孙子），你虽知道这一切，你心仍不自卑，'),
('CUV', '但以理书', 27, 5, 23, '竟向天上的主自高，使人将他殿中的器皿拿到你面前，你和大臣、皇后、妃嫔用这器皿饮酒。你又赞美那不能看、不能听、无知无识、金、银、铜、铁、木、石所造的神，却没有将荣耀归与那手中有你气息，管理你一切行动的神。'),
('CUV', '但以理书', 27, 5, 24, '因此从神那里显出指头来写这文字。'),
('CUV', '但以理书', 27, 5, 25, '所写的文字是：弥尼，弥尼，提客勒，乌法珥新。'),
('CUV', '但以理书', 27, 5, 26, '讲解是这样：弥尼，就是神已经数算你国的年日到此完毕。'),
('CUV', '但以理书', 27, 5, 27, '提客勒，就是你被称在天平里，显出你的亏欠。'),
('CUV', '但以理书', 27, 5, 28, '毗勒斯（与乌法珥新同义），就是你的国分裂，归与玛代人和波斯人。'),
('CUV', '但以理书', 27, 5, 29, '伯沙撒下令，人就把紫袍给但以理穿上，把金链给他戴在颈项上，又传令使他在国中位列第三。'),
('CUV', '但以理书', 27, 5, 30, '当夜，迦勒底王伯沙撒被杀。'),
('CUV', '但以理书', 27, 5, 31, '玛代人大利乌年六十二岁，取了迦勒底国。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '但以理书', 27, 6, 1, '大利乌随心所愿，立一百二十个总督，治理通国。'),
('CUV', '但以理书', 27, 6, 2, '又在他们以上立总长三人（但以理在其中），使总督在他们三人面前回复事务，免得王受亏损。'),
('CUV', '但以理书', 27, 6, 3, '因这但以理有美好的灵性，所以显然超乎其余的总长和总督，王又想立他治理通国。'),
('CUV', '但以理书', 27, 6, 4, '那时，总长和总督寻找但以理误国的把柄，为要参他；只是找不著他的错误过失，因他忠心办事，毫无错误过失。'),
('CUV', '但以理书', 27, 6, 5, '那些人便说：我们要找参这但以理的把柄，除非在他神的律法中就寻不著。'),
('CUV', '但以理书', 27, 6, 6, '于是，总长和总督纷纷聚集来见王，说：愿大利乌王万岁！'),
('CUV', '但以理书', 27, 6, 7, '国中的总长、钦差、总督、谋士，和巡抚彼此商议，要立一条坚定的禁令（或译：求王下旨要立一条……），三十日内，不拘何人，若在王以外，或向神或向人求甚么，就必扔在狮子坑中。'),
('CUV', '但以理书', 27, 6, 8, '王啊，现在求你立这禁令，加盖玉玺，使禁令决不更改；照玛代和波斯人的例是不可更改的。'),
('CUV', '但以理书', 27, 6, 9, '于是大利乌王立这禁令，加盖玉玺。'),
('CUV', '但以理书', 27, 6, 10, '但以理知道这禁令盖了玉玺，就到自己家里（他楼上的窗户开向耶路撒冷），一日三次，双膝跪在他神面前，祷告感谢，与素常一样。'),
('CUV', '但以理书', 27, 6, 11, '那些人就纷纷聚集，见但以理在他神面前祈祷恳求。'),
('CUV', '但以理书', 27, 6, 12, '他们便进到王前，提王的禁令，说：王啊，三十日内不拘何人，若在王以外，或向神或向人求甚么，必被扔在狮子坑中。王不是在这禁令上盖了玉玺么？王回答说：实有这事，照玛代和波斯人的例是不可更改的。'),
('CUV', '但以理书', 27, 6, 13, '他们对王说：王啊，那被掳之犹大人中的但以理不理你，也不遵你盖了玉玺的禁令，他竟一日三次祈祷。'),
('CUV', '但以理书', 27, 6, 14, '王听见这话，就甚愁烦，一心要救但以理，筹划解救他，直到日落的时候。'),
('CUV', '但以理书', 27, 6, 15, '那些人就纷纷聚集来见王，说：王啊，当知道玛代人和波斯人有例，凡王所立的禁令和律例都不可更改。'),
('CUV', '但以理书', 27, 6, 16, '王下令，人就把但以理带来，扔在狮子坑中。王对但以理说：你所常事奉的神，他必救你。'),
('CUV', '但以理书', 27, 6, 17, '有人搬石头放在坑口，王用自己的玺和大臣的印，封闭那坑，使惩办但以理的事毫无更改。'),
('CUV', '但以理书', 27, 6, 18, '王回宫，终夜禁食，无人拿乐器到他面前，并且睡不著觉。'),
('CUV', '但以理书', 27, 6, 19, '次日黎明，王就起来，急忙往狮子坑那里去。'),
('CUV', '但以理书', 27, 6, 20, '临近坑边，哀声呼叫但以理，对但以理说：永生神的仆人但以理啊，你所常事奉的神能救你脱离狮子么？'),
('CUV', '但以理书', 27, 6, 21, '但以理对王说：愿王万岁！'),
('CUV', '但以理书', 27, 6, 22, '我的神差遣使者，封住狮子的口，叫狮子不伤我；因我在神面前无辜，我在王面前也没有行过亏损的事。'),
('CUV', '但以理书', 27, 6, 23, '王就甚喜乐，吩咐人将但以理从坑里系上来。于是但以理从坑里被系上来，身上毫无伤损，因为信靠他的神。'),
('CUV', '但以理书', 27, 6, 24, '王下令，人就把那些控告但以理的人，连他们的妻子儿女都带来，扔在狮子坑中。他们还没有到坑底，狮子就抓住（原文是胜了）他们，咬碎他们的骨头。'),
('CUV', '但以理书', 27, 6, 25, '那时，大利乌王传旨，晓谕住在全地各方、各国、各族的人说：愿你们大享平安！'),
('CUV', '但以理书', 27, 6, 26, '现在我降旨晓谕我所统辖的全国人民，要在但以理的神面前，战兢恐惧。因为他是永远长存的活神，他的国永不败坏；他的权柄永存无极！'),
('CUV', '但以理书', 27, 6, 27, '他护庇人，搭救人，在天上地下施行神迹奇事，救了但以理脱离狮子的口。'),
('CUV', '但以理书', 27, 6, 28, '如此，这但以理，当大利乌王在位的时候和波斯王古列在位的时候，大享亨通。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '但以理书', 27, 7, 1, '巴比伦王伯沙撒元年，但以理在床上做梦，见了脑中的异象，就记录这梦，述说其中的大意。'),
('CUV', '但以理书', 27, 7, 2, '但以理说：我夜里见异象，看见天的四风陡起，刮在大海之上。'),
('CUV', '但以理书', 27, 7, 3, '有四个大兽从海中上来，形状各有不同：'),
('CUV', '但以理书', 27, 7, 4, '头一个像狮子，有鹰的翅膀；我正观看的时候，兽的翅膀被拔去，兽从地上得立起来，用两脚站立，像人一样，又得了人心。'),
('CUV', '但以理书', 27, 7, 5, '又有一兽如熊，就是第二兽，旁跨而坐，口齿内啣著三根肋骨。有吩咐这兽的说：起来吞吃多肉。'),
('CUV', '但以理书', 27, 7, 6, '此后我观看，又有一兽如豹，背上有鸟的四个翅膀；这兽有四个头，又得了权柄。'),
('CUV', '但以理书', 27, 7, 7, '其后我在夜间的异象中观看，见第四兽甚是可怕，极其强壮，大有力量，有大铁牙，吞吃嚼碎，所剩下的用脚践踏。这兽与前三兽大不相同，头有十角。'),
('CUV', '但以理书', 27, 7, 8, '我正观看这些角，见其中又长起一个小角；先前的角中有三角在这角前，连根被他拔出来。这角有眼，像人的眼，有口说夸大的话。'),
('CUV', '但以理书', 27, 7, 9, '我观看，见有宝座设立，上头坐著亘古常在者。他的衣服洁白如雪，头发如纯净的羊毛。宝座乃火燄，其轮乃烈火。'),
('CUV', '但以理书', 27, 7, 10, '从他面前有火，像河发出；事奉他的有千千，在他面前侍立的有万万；他坐著要行审判，案卷都展开了。'),
('CUV', '但以理书', 27, 7, 11, '那时我观看，见那兽因小角说夸大话的声音被杀，身体损坏，扔在火中焚烧。'),
('CUV', '但以理书', 27, 7, 12, '其余的兽，权柄都被夺去，生命却仍存留，直到所定的时候和日期。'),
('CUV', '但以理书', 27, 7, 13, '我在夜间的异象中观看，见有一位像人子的，驾著天云而来，被领到亘古常在者面前，'),
('CUV', '但以理书', 27, 7, 14, '得了权柄、荣耀、国度，使各方、各国、各族的人都事奉他。他的权柄是永远的，不能废去；他的国必不败坏。'),
('CUV', '但以理书', 27, 7, 15, '至于我─但以理，我的灵在我里面愁烦，我脑中的异象使我惊惶。'),
('CUV', '但以理书', 27, 7, 16, '我就近一位侍立者，问他这一切的真情。他就告诉我，将那事的讲解给我说明。'),
('CUV', '但以理书', 27, 7, 17, '这四个大兽就是四王将要在世上兴起。'),
('CUV', '但以理书', 27, 7, 18, '然而，至高者的圣民，必要得国享受，直到永永远远。'),
('CUV', '但以理书', 27, 7, 19, '那时我愿知道第四兽的真情，他为何与那三兽的真情大不相同，甚是可怕，有铁牙铜爪，吞吃嚼碎，所剩下的用脚践踏；'),
('CUV', '但以理书', 27, 7, 20, '头有十角和那另长的一角，在这角前有三角被他打落。这角有眼，有说夸大话的口，形状强横，过于他的同类。'),
('CUV', '但以理书', 27, 7, 21, '我观看，见这角与圣民争战，胜了他们。'),
('CUV', '但以理书', 27, 7, 22, '直到亘古常在者来给至高者的圣民伸冤，圣民得国的时候就到了。'),
('CUV', '但以理书', 27, 7, 23, '那侍立者这样说：第四兽就是世上必有的第四国，与一切国大不相同，必吞吃全地，并且践踏嚼碎。'),
('CUV', '但以理书', 27, 7, 24, '至于那十角，就是从这国中必兴起的十王，后来又兴起一王，与先前的不同；他必制伏三王。'),
('CUV', '但以理书', 27, 7, 25, '他必向至高者说夸大的话，必折磨至高者的圣民，必想改变节期和律法。圣民必交付他手一载、二载、半载。'),
('CUV', '但以理书', 27, 7, 26, '然而，审判者必坐著行审判；他的权柄必被夺去，毁坏，灭绝，一直到底。'),
('CUV', '但以理书', 27, 7, 27, '国度、权柄，和天下诸国的大权必赐给至高者的圣民。他的国是永远的；一切掌权的都必事奉他，顺从他。'),
('CUV', '但以理书', 27, 7, 28, '那事至此完毕。至于我─但以理，心中甚是惊惶，脸色也改变了，却将那事存记在心。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '但以理书', 27, 8, 1, '伯沙撒王在位第三年，有异象现与我─但以理，是在先前所见的异象之后。'),
('CUV', '但以理书', 27, 8, 2, '我见了异象的时候，我以为在以拦省书珊城（或译：宫）中；我见异象又如在乌莱河边。'),
('CUV', '但以理书', 27, 8, 3, '我举目观看，见有双角的公绵羊站在河边，两角都高。这角高过那角，更高的是后长的。'),
('CUV', '但以理书', 27, 8, 4, '我见那公绵羊往西、往北、往南抵触。兽在他面前都站立不住，也没有能救护脱离他手的；但他任意而行，自高自大。'),
('CUV', '但以理书', 27, 8, 5, '我正思想的时候，见有一只公山羊从西而来，遍行全地，脚不沾尘。这山羊两眼当中有一非常的角。'),
('CUV', '但以理书', 27, 8, 6, '他往我所看见、站在河边有双角的公绵羊那里去，大发忿怒，向他直闯。'),
('CUV', '但以理书', 27, 8, 7, '我见公山羊就近公绵羊，向他发烈怒，抵触他，折断他的两角。绵羊在他面前站立不住；他将绵羊触倒在地，用脚践踏，没有能救绵羊脱离他手的。'),
('CUV', '但以理书', 27, 8, 8, '这山羊极其自高自大，正强盛的时候，那大角折断了，又在角根上向天的四方（原文是风）长出四个非常的角来。'),
('CUV', '但以理书', 27, 8, 9, '四角之中有一角长出一个小角，向南、向东、向荣美之地，渐渐成为强大。'),
('CUV', '但以理书', 27, 8, 10, '他渐渐强大，高及天象，将些天象和星宿抛落在地，用脚践踏。'),
('CUV', '但以理书', 27, 8, 11, '并且他自高自大，以为高及天象之君；除掉常献给君的燔祭，毁坏君的圣所。'),
('CUV', '但以理书', 27, 8, 12, '因罪过的缘故，有军旅和常献的燔祭交付他。他将真理抛在地上，任意而行，无不顺利。'),
('CUV', '但以理书', 27, 8, 13, '我听见有一位圣者说话，又有一位圣者问那说话的圣者说：这除掉常献的燔祭和施行毁坏的罪过，将圣所与军旅（或译：以色列的军）践踏的异象，要到几时才应验呢？'),
('CUV', '但以理书', 27, 8, 14, '他对我说：到二千三百日，圣所就必洁净。'),
('CUV', '但以理书', 27, 8, 15, '我─但以理见了这异象，愿意明白其中的意思。忽有一位形状像人的站在我面前。'),
('CUV', '但以理书', 27, 8, 16, '我又听见乌莱河两岸中有人声呼叫说：加百列啊，要使此人明白这异象。'),
('CUV', '但以理书', 27, 8, 17, '他便来到我所站的地方。他一来，我就惊慌俯伏在地；他对我说：人子啊，你要明白，因为这是关乎末后的异象。'),
('CUV', '但以理书', 27, 8, 18, '他与我说话的时候，我面伏在地沉睡；他就摸我，扶我站起来，'),
('CUV', '但以理书', 27, 8, 19, '说：我要指示你恼怒临完必有的事，因为这是关乎末后的定期。'),
('CUV', '但以理书', 27, 8, 20, '你所看见双角的公绵羊，就是玛代和波斯王。'),
('CUV', '但以理书', 27, 8, 21, '那公山羊就是希利尼王（希利尼：原文是雅完；下同）；两眼当中的大角就是头一王。'),
('CUV', '但以理书', 27, 8, 22, '至于那折断了的角，在其根上又长出四角，这四角就是四国，必从这国里兴起来，只是权势都不及他。'),
('CUV', '但以理书', 27, 8, 23, '这四国末时，犯法的人罪恶满盈，必有一王兴起，面貌凶恶，能用双关的诈语。'),
('CUV', '但以理书', 27, 8, 24, '他的权柄必大，却不是因自己的能力；他必行非常的毁灭，事情顺利，任意而行；又必毁灭有能力的和圣民。'),
('CUV', '但以理书', 27, 8, 25, '他用权术成就手中的诡计，心里自高自大，在人坦然无备的时候，毁灭多人；又要站起来攻击万君之君，至终却非因人手而灭亡。'),
('CUV', '但以理书', 27, 8, 26, '所说二千三百日的异象是真的，但你要将这异象封住，因为关乎后来许多的日子。'),
('CUV', '但以理书', 27, 8, 27, '于是我─但以理昏迷不醒，病了数日，然后起来办理王的事务。我因这异象惊奇，却无人能明白其中的意思。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '但以理书', 27, 9, 1, '玛代族亚哈随鲁的儿子大利乌立为迦勒底国的王元年，'),
('CUV', '但以理书', 27, 9, 2, '就是他在位第一年，我但以理从书上得知耶和华的话临到先知耶利米，论耶路撒冷荒凉的年数，七十年为满。'),
('CUV', '但以理书', 27, 9, 3, '我便禁食，披麻蒙灰，定意向主神祈祷恳求。'),
('CUV', '但以理书', 27, 9, 4, '我向耶和华─我的神祈祷、认罪，说：主啊，大而可畏的神，向爱主、守主诫命的人守约施慈爱。'),
('CUV', '但以理书', 27, 9, 5, '我们犯罪作孽，行恶叛逆，偏离你的诫命典章，'),
('CUV', '但以理书', 27, 9, 6, '没有听从你仆人众先知奉你名向我们君王、首领、列祖，和国中一切百姓所说的话。'),
('CUV', '但以理书', 27, 9, 7, '主啊，你是公义的，我们是脸上蒙羞的；因我们犹大人和耶路撒冷的居民，并以色列众人，或在近处，或在远处，被你赶到各国的人，都得罪了你，正如今日一样。'),
('CUV', '但以理书', 27, 9, 8, '主啊，我们和我们的君王、首领、列祖因得罪了你，就都脸上蒙羞。'),
('CUV', '但以理书', 27, 9, 9, '主─我们的神是怜悯饶恕人的，我们却违背了他，'),
('CUV', '但以理书', 27, 9, 10, '也没有听从耶和华─我们神的话，没有遵行他藉仆人众先知向我们所陈明的律法。'),
('CUV', '但以理书', 27, 9, 11, '以色列众人都犯了你的律法，偏行，不听从你的话；因此，在你仆人摩西律法上所写的咒诅和誓言都倾在我们身上，因我们得罪了神。'),
('CUV', '但以理书', 27, 9, 12, '他使大灾祸临到我们，成就了警戒我们和审判我们官长的话；原来在普天之下未曾行过像在耶路撒冷所行的。'),
('CUV', '但以理书', 27, 9, 13, '这一切灾祸临到我们身上是照摩西律法上所写的，我们却没有求耶和华─我们神的恩典，使我们回头离开罪孽，明白你的真理。'),
('CUV', '但以理书', 27, 9, 14, '所以耶和华留意使这灾祸临到我们身上，因为耶和华─我们的神在他所行的事上都是公义；我们并没有听从他的话。'),
('CUV', '但以理书', 27, 9, 15, '主─我们的神啊，你曾用大能的手领你的子民出埃及地，使自己得了名，正如今日一样。我们犯了罪，作了恶。'),
('CUV', '但以理书', 27, 9, 16, '主啊，求你按你的大仁大义，使你的怒气和忿怒转离你的城耶路撒冷，就是你的圣山。耶路撒冷和你的子民，因我们的罪恶和我们列祖的罪孽被四围的人羞辱。'),
('CUV', '但以理书', 27, 9, 17, '我们的神啊，现在求你垂听仆人的祈祷恳求，为自己使脸光照你荒凉的圣所。'),
('CUV', '但以理书', 27, 9, 18, '我的神啊，求你侧耳而听，睁眼而看，眷顾我们荒凉之地和称为你名下的城。我们在你面前恳求，原不是因自己的义，乃因你的大怜悯。'),
('CUV', '但以理书', 27, 9, 19, '求主垂听，求主赦免，求主应允而行，为你自己不要迟延。我的神啊，因这城和这民都是称为你名下的。'),
('CUV', '但以理书', 27, 9, 20, '我说话，祷告，承认我的罪和本国之民以色列的罪，为我神的圣山，在耶和华─我神面前恳求。'),
('CUV', '但以理书', 27, 9, 21, '我正祷告的时候，先前在异象中所见的那位加百列，奉命迅速飞来，约在献晚祭的时候，按手在我身上。'),
('CUV', '但以理书', 27, 9, 22, '他指教我说：但以理啊，现在我出来要使你有智慧，有聪明。'),
('CUV', '但以理书', 27, 9, 23, '你初恳求的时候，就发出命令，我来告诉你，因你大蒙眷爱；所以你要思想明白这以下的事和异象。'),
('CUV', '但以理书', 27, 9, 24, '为你本国之民和你圣城，已经定了七十个七。要止住罪过，除净罪恶，赎尽罪孽，引进（或译：彰显）永义，封住异象和预言，并膏至圣者（者：或译所）。'),
('CUV', '但以理书', 27, 9, 25, '你当知道，当明白，从出令重新建造耶路撒冷，直到有受膏君的时候，必有七个七和六十二个七。正在艰难的时候，耶路撒冷城连街带濠都必重新建造。'),
('CUV', '但以理书', 27, 9, 26, '过了六十二个七，那（或译：有）受膏者必被剪除，一无所有；必有一王的民来毁灭这城和圣所，至终必如洪水冲没。必有争战，一直到底，荒凉的事已经定了。'),
('CUV', '但以理书', 27, 9, 27, '一七之内，他必与许多人坚定盟约；一七之半，他必使祭祀与供献止息。那行毁坏可憎的（或译：使地荒凉的）如飞而来，并且有忿怒倾在那行毁坏的身上（或译：倾在那荒凉之地），直到所定的结局。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '但以理书', 27, 10, 1, '波斯王古列第三年，有事显给称为伯提沙撒的但以理。这事是真的，是指著大争战；但以理通达这事，明白这异象。'),
('CUV', '但以理书', 27, 10, 2, '当那时，我─但以理悲伤了三个七日。'),
('CUV', '但以理书', 27, 10, 3, '美味我没有吃，酒肉没有入我的口，也没有用油抹我的身，直到满了三个七日。'),
('CUV', '但以理书', 27, 10, 4, '正月二十四日，我在底格里斯大河边，'),
('CUV', '但以理书', 27, 10, 5, '举目观看，见有一人身穿细麻衣，腰束乌法精金带。'),
('CUV', '但以理书', 27, 10, 6, '他身体如水苍玉，面貌如闪电，眼目如火把，手和脚如光明的铜，说话的声音如大众的声音。'),
('CUV', '但以理书', 27, 10, 7, '这异象惟有我─但以理一人看见，同著我的人没有看见。他们却大大战兢，逃跑隐藏，'),
('CUV', '但以理书', 27, 10, 8, '只剩下我一人。我见了这大异象便浑身无力，面貌失色，毫无气力。'),
('CUV', '但以理书', 27, 10, 9, '我却听见他说话的声音，一听见就面伏在地沉睡了。'),
('CUV', '但以理书', 27, 10, 10, '忽然，有一手按在我身上，使我用膝和手掌支持微起。'),
('CUV', '但以理书', 27, 10, 11, '他对我说：大蒙眷爱的但以理啊，要明白我与你所说的话，只管站起来，因为我现在奉差遣来到你这里。他对我说这话，我便战战兢兢地立起来。'),
('CUV', '但以理书', 27, 10, 12, '他就说：但以理啊，不要惧怕！因为从你第一日专心求明白将来的事，又在你神面前刻苦己心，你的言语已蒙应允；我是因你的言语而来。'),
('CUV', '但以理书', 27, 10, 13, '但波斯国的魔君拦阻我二十一日。忽然有大君（就是天使长；二十一节同）中的一位米迦勒来帮助我，我就停留在波斯诸王那里。'),
('CUV', '但以理书', 27, 10, 14, '现在我来，要使你明白本国之民日后必遭遇的事，因为这异象关乎后来许多的日子。'),
('CUV', '但以理书', 27, 10, 15, '他向我这样说，我就脸面朝地，哑口无声。'),
('CUV', '但以理书', 27, 10, 16, '不料，有一位像人的，摸我的嘴唇，我便开口向那站在我面前的说：我主啊，因见这异象，我大大愁苦，毫无气力。'),
('CUV', '但以理书', 27, 10, 17, '我主的仆人怎能与我主说话呢？我一见异象就浑身无力，毫无气息。'),
('CUV', '但以理书', 27, 10, 18, '有一位形状像人的又摸我，使我有力量。'),
('CUV', '但以理书', 27, 10, 19, '他说：大蒙眷爱的人哪，不要惧怕，愿你平安！你总要坚强。他一向我说话，我便觉得有力量，说：我主请说，因你使我有力量。'),
('CUV', '但以理书', 27, 10, 20, '他就说：你知道我为何来见你么？现在我要回去与波斯的魔君争战，我去后，希利尼（原文是雅完）的魔君必来。'),
('CUV', '但以理书', 27, 10, 21, '但我要将那录在真确书上的事告诉你。除了你们的大君米迦勒之外，没有帮助我抵挡这两魔君的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '但以理书', 27, 11, 1, '又说：当玛代王大利乌元年，我曾起来扶助米迦勒，使他坚强。'),
('CUV', '但以理书', 27, 11, 2, '现在我将真事指示你：波斯还有三王兴起，第四王必富足远胜诸王。他因富足成为强盛，就必激动大众攻击希利尼国。'),
('CUV', '但以理书', 27, 11, 3, '必有一个勇敢的王兴起，执掌大权，随意而行。'),
('CUV', '但以理书', 27, 11, 4, '他兴起的时候，他的国必破裂，向天的四方（方：原文是风）分开，却不归他的后裔，治国的权势也都不及他；因为他的国必被拔出，归与他后裔之外的人。'),
('CUV', '但以理书', 27, 11, 5, '南方的王必强盛，他将帅中必有一个比他更强盛，执掌权柄，他的权柄甚大。'),
('CUV', '但以理书', 27, 11, 6, '过些年后，他们必互相连合，南方王的女儿必就了北方王来立约；但这女子帮助之力存立不住，王和他所倚靠之力也不能存立。这女子和引导他来的，并生他的，以及当时扶助他的，都必交与死地。'),
('CUV', '但以理书', 27, 11, 7, '但这女子的本家（原文是根）必另生一子（子：原文是枝）继续王位，他必率领军队进入北方王的保障，攻击他们，而且得胜；'),
('CUV', '但以理书', 27, 11, 8, '并将他们的神像和铸成的偶像，与金银的宝器掠到埃及去。数年之内，他不去攻击北方的王。'),
('CUV', '但以理书', 27, 11, 9, '北方的王（原文是他）必入南方王的国，却要仍回本地。'),
('CUV', '但以理书', 27, 11, 10, '北方王（原文是他）的二子必动干戈，招聚许多军兵。这军兵前去，如洪水泛滥，又必再去争战，直到南方王的保障。'),
('CUV', '但以理书', 27, 11, 11, '南方王必发烈怒，出来与北方王争战，摆列大军；北方王的军兵必交付他手。'),
('CUV', '但以理书', 27, 11, 12, '他的众军高傲，他的心也必自高；他虽使数万人仆倒，却不得常胜。'),
('CUV', '但以理书', 27, 11, 13, '北方王必回来摆列大军，比先前的更多。满了所定的年数，他必率领大军，带极多的军装来。'),
('CUV', '但以理书', 27, 11, 14, '那时，必有许多人起来攻击南方王，并且你本国的强暴人必兴起，要应验那异象，他们却要败亡。'),
('CUV', '但以理书', 27, 11, 15, '北方王必来筑垒攻取坚固城；南方的军兵必站立不住，就是选择的精兵（原文是民）也无力站住。'),
('CUV', '但以理书', 27, 11, 16, '来攻击他的，必任意而行，无人在北方王（原文是他）面前站立得住。他必站在那荣美之地，用手施行毁灭。'),
('CUV', '但以理书', 27, 11, 17, '他必定意用全国之力而来，立公正的约，照约而行，将自己的女儿给南方王为妻，想要败坏他（或译：埃及），这计却不得成就，与自己毫无益处。'),
('CUV', '但以理书', 27, 11, 18, '其后他必转回夺取了许多海岛。但有一大帅，除掉他令人受的羞辱，并且使这羞辱归他本身。'),
('CUV', '但以理书', 27, 11, 19, '他就必转向本地的保障，却要绊跌仆倒，归于无有。'),
('CUV', '但以理书', 27, 11, 20, '那时，必有一人兴起接续他为王，使横征暴敛的人通行国中的荣美地。这王不多日就必灭亡，却不因忿怒，也不因争战。'),
('CUV', '但以理书', 27, 11, 21, '必有一个卑鄙的人兴起接续为王，人未曾将国的尊荣给他，他却趁人坦然无备的时候，用谄媚的话得国。'),
('CUV', '但以理书', 27, 11, 22, '必有无数的军兵势如洪水，在他面前冲没败坏；同盟的君也必如此。'),
('CUV', '但以理书', 27, 11, 23, '与那君结盟之后，他必行诡诈，因为他必上来以微小的军（原文是民）成为强盛。'),
('CUV', '但以理书', 27, 11, 24, '趁人坦然无备的时候，他必来到国中极肥美之地，行他列祖和他列祖之祖所未曾行的，将掳物、掠物，和财宝散给众人，又要设计攻打保障，然而这都是暂时的。'),
('CUV', '但以理书', 27, 11, 25, '他必奋勇向前，率领大军攻击南方王；南方王也必以极大极强的军兵与他争战，却站立不住，因为有人设计谋害南方王。'),
('CUV', '但以理书', 27, 11, 26, '吃王膳的，必败坏他；他的军队必被冲没，而且被杀的甚多。'),
('CUV', '但以理书', 27, 11, 27, '至于这二王，他们心怀恶计，同席说谎，计谋却不成就；因为到了定期，事就了结。'),
('CUV', '但以理书', 27, 11, 28, '北方王（原文是他）必带许多财宝回往本国，他的心反对圣约，任意而行，回到本地。'),
('CUV', '但以理书', 27, 11, 29, '到了定期，他必返回，来到南方。后一次却不如前一次，'),
('CUV', '但以理书', 27, 11, 30, '因为基提战船必来攻击他，他就丧胆而回，又要恼恨圣约，任意而行；他必回来联络背弃圣约的人。'),
('CUV', '但以理书', 27, 11, 31, '他必兴兵，这兵必亵渎圣地，就是保障，除掉常献的燔祭，设立那行毁坏可憎的。'),
('CUV', '但以理书', 27, 11, 32, '作恶违背圣约的人，他必用巧言勾引；惟独认识神的子民必刚强行事。'),
('CUV', '但以理书', 27, 11, 33, '民间的智慧人必训诲多人；然而他们多日必倒在刀下，或被火烧，或被掳掠抢夺。'),
('CUV', '但以理书', 27, 11, 34, '他们仆倒的时候，稍得扶助，却有许多人用谄媚的话亲近他们。'),
('CUV', '但以理书', 27, 11, 35, '智慧人中有些仆倒的，为要熬炼其余的人，使他们清净洁白，直到末了；因为到了定期，事就了结。'),
('CUV', '但以理书', 27, 11, 36, '王必任意而行，自高自大，超过所有的神，又用奇异的话攻击万神之神。他必行事亨通，直到主的忿怒完毕，因为所定的事必然成就。'),
('CUV', '但以理书', 27, 11, 37, '他必不顾他列祖的神，也不顾妇女所羡慕的神，无论何神他都不顾；因为他必自大，高过一切。'),
('CUV', '但以理书', 27, 11, 38, '他倒要敬拜保障的神，用金、银、宝石和可爱之物敬奉他列祖所不认识的神。'),
('CUV', '但以理书', 27, 11, 39, '他必靠外邦神的帮助，攻破最坚固的保障。凡承认他的，他必将荣耀加给他们，使他们管辖许多人，又为贿赂分地与他们。'),
('CUV', '但以理书', 27, 11, 40, '到末了，南方王要与他交战。北方王必用战车、马兵，和许多战船，势如暴风来攻击他，也必进入列国，如洪水泛滥。'),
('CUV', '但以理书', 27, 11, 41, '又必进入那荣美之地，有许多国就被倾覆，但以东人、摩押人，和一大半亚扪人必脱离他的手。'),
('CUV', '但以理书', 27, 11, 42, '他必伸手攻击列国；埃及地也不得脱离。'),
('CUV', '但以理书', 27, 11, 43, '他必把持埃及的金银财宝和各样的宝物。吕彼亚人和古实人都必跟从他。'),
('CUV', '但以理书', 27, 11, 44, '但从东方和北方必有消息扰乱他，他就大发烈怒出去，要将多人杀灭净尽。'),
('CUV', '但以理书', 27, 11, 45, '他必在海和荣美的圣山中间设立他如宫殿的帐幕；然而到了他的结局，必无人能帮助他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '但以理书', 27, 12, 1, '那时，保佑你本国之民的天使长（原文是大君）米迦勒必站起来，并且有大艰难，从有国以来直到此时，没有这样的。你本国的民中，凡名录在册上的，必得拯救。'),
('CUV', '但以理书', 27, 12, 2, '睡在尘埃中的，必有多人复醒。其中有得永生的，有受羞辱永远被憎恶的。'),
('CUV', '但以理书', 27, 12, 3, '智慧人必发光，如同天上的光；那使多人归义的，必发光如星，直到永永远远。'),
('CUV', '但以理书', 27, 12, 4, '但以理啊，你要隐藏这话，封闭这书，直到末时。必有多人来往奔跑（或译：切心研究），知识就必增长。'),
('CUV', '但以理书', 27, 12, 5, '我─但以理观看，见另有两个人站立：一个在河这边，一个在河那边。'),
('CUV', '但以理书', 27, 12, 6, '有一个问那站在河水以上、穿细麻衣的说：这奇异的事到几时才应验呢？'),
('CUV', '但以理书', 27, 12, 7, '我听见那站在河水以上、穿细麻衣的，向天举起左右手，指著活到永远的主起誓说：要到一载、二载、半载，打破圣民权力的时候，这一切事就都应验了。'),
('CUV', '但以理书', 27, 12, 8, '我听见这话，却不明白，就说：我主啊，这些事的结局是怎样呢？'),
('CUV', '但以理书', 27, 12, 9, '他说：但以理啊，你只管去；因为这话已经隐藏封闭，直到末时。'),
('CUV', '但以理书', 27, 12, 10, '必有许多人使自己清净洁白，且被熬炼；但恶人仍必行恶，一切恶人都不明白，惟独智慧人能明白。'),
('CUV', '但以理书', 27, 12, 11, '从除掉常献的燔祭，并设立那行毁坏可憎之物的时候，必有一千二百九十日。'),
('CUV', '但以理书', 27, 12, 12, '等到一千三百三十五日的，那人便为有福。'),
('CUV', '但以理书', 27, 12, 13, '你且去等候结局，因为你必安歇。到了末期，你必起来，享受你的福分。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '何西阿书', 28, 1, 1, '当乌西雅、约坦、亚哈斯、希西家作犹大王，约阿施的儿子耶罗波安作以色列王的时候，耶和华的话临到备利的儿子何西阿。'),
('CUV', '何西阿书', 28, 1, 2, '耶和华初次与何西阿说话，对他说：你去娶淫妇为妻，也收那从淫乱所生的儿女；因为这地大行淫乱，离弃耶和华。'),
('CUV', '何西阿书', 28, 1, 3, '于是，何西阿去娶了滴拉音的女儿歌篾。这妇人怀孕，给他生了一个儿子。'),
('CUV', '何西阿书', 28, 1, 4, '耶和华对何西阿说：给他起名叫耶斯列；因为再过片时，我必讨耶户家在耶斯列杀人流血的罪，也必使以色列家的国灭绝。'),
('CUV', '何西阿书', 28, 1, 5, '到那日，我必在耶斯列平原折断以色列的弓。'),
('CUV', '何西阿书', 28, 1, 6, '歌篾又怀孕生了一个女儿，耶和华对何西阿说：给她起名叫罗路哈玛（就是不蒙怜悯的意思）；因为我必不再怜悯以色列家，决不赦免他们。'),
('CUV', '何西阿书', 28, 1, 7, '我却要怜悯犹大家，使他们靠耶和华─他们的神得救，不使他们靠弓、刀、争战、马匹，与马兵得救。'),
('CUV', '何西阿书', 28, 1, 8, '歌篾给罗路哈玛断奶以后，又怀孕生了一个儿子。'),
('CUV', '何西阿书', 28, 1, 9, '耶和华说：给他起名叫罗阿米（就是非我民的意思）；因为你们不作我的子民，我也不作你们的神。'),
('CUV', '何西阿书', 28, 1, 10, '然而，以色列的人数必如海沙，不可量，不可数。从前在甚么地方对他们说你们不是我的子民，将来在那里必对他们说你们是永生神的儿子。'),
('CUV', '何西阿书', 28, 1, 11, '犹大人和以色列人必一同聚集，为自己立一个首领，从这地上去（或译：从被掳之地上来），因为耶斯列的日子必为大日。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '何西阿书', 28, 2, 1, '你们要称你们的弟兄为阿米（就是我民的意思），称你们的姊妹为路哈玛（就是蒙怜悯的意思）。'),
('CUV', '何西阿书', 28, 2, 2, '你们要与你们的母亲大大争辩；因为她不是我的妻子，我也不是她的丈夫。叫她除掉脸上的淫像和胸间的淫态，'),
('CUV', '何西阿书', 28, 2, 3, '免得我剥她的衣服，使她赤体，与才生的时候一样，使她如旷野，如干旱之地，因渴而死。'),
('CUV', '何西阿书', 28, 2, 4, '我必不怜悯她的儿女，因为他们是从淫乱而生的。'),
('CUV', '何西阿书', 28, 2, 5, '他们的母亲行了淫乱，怀他们的母做了可羞耻的事，因为她说：我要随从所爱的；我的饼、水、羊毛、麻、油、酒都是他们给的。'),
('CUV', '何西阿书', 28, 2, 6, '因此，我必用荆棘堵塞她的道，筑墙挡住她，使她找不著路。'),
('CUV', '何西阿书', 28, 2, 7, '她必追随所爱的，却追不上；她必寻找他们，却寻不见，便说：我要归回前夫，因我那时的光景比如今还好。'),
('CUV', '何西阿书', 28, 2, 8, '她不知道是我给她五谷、新酒，和油，又加增她的金银；她却以此供奉（或译：制造）巴力。'),
('CUV', '何西阿书', 28, 2, 9, '因此到了收割的日子，出酒的时候，我必将我的五谷新酒收回，也必将她应当遮体的羊毛和麻夺回来。'),
('CUV', '何西阿书', 28, 2, 10, '如今我必在她所爱的眼前显露她的丑态；必无人能救她脱离我的手。'),
('CUV', '何西阿书', 28, 2, 11, '我也必使她的宴乐、节期、月朔、安息日，并她的一切大会都止息了。'),
('CUV', '何西阿书', 28, 2, 12, '我也必毁坏她的葡萄树和无花果树，就是她说这是我所爱的给我为赏赐的。我必使这些树变为荒林，为田野的走兽所吃。'),
('CUV', '何西阿书', 28, 2, 13, '我必追讨她素日给诸巴力烧香的罪；那时她佩带耳环和别样妆饰，随从她所爱的，却忘记我。这是耶和华说的。'),
('CUV', '何西阿书', 28, 2, 14, '后来我必劝导她，领她到旷野，对她说安慰的话。'),
('CUV', '何西阿书', 28, 2, 15, '她从那里出来，我必赐她葡萄园，又赐她亚割谷作为指望的门。她必在那里应声（或译：歌唱），与幼年的日子一样，与从埃及地上来的时候相同。'),
('CUV', '何西阿书', 28, 2, 16, '耶和华说：那日你必称呼我伊施（就是我夫的意思），不再称呼我巴力（就是我主的意思）；'),
('CUV', '何西阿书', 28, 2, 17, '因为我必从我民的口中除掉诸巴力的名号，这名号不再提起。'),
('CUV', '何西阿书', 28, 2, 18, '当那日，我必为我的民，与田野的走兽和空中的飞鸟，并地上的昆虫立约；又必在国中折断弓刀，止息争战，使他们安然躺卧。'),
('CUV', '何西阿书', 28, 2, 19, '我必聘你永远归我为妻，以仁义、公平、慈爱、怜悯聘你归我；'),
('CUV', '何西阿书', 28, 2, 20, '也以诚实聘你归我，你就必认识我─耶和华。'),
('CUV', '何西阿书', 28, 2, 21, '耶和华说：那日我必应允，我必应允天，天必应允地；'),
('CUV', '何西阿书', 28, 2, 22, '地必应允五谷、新酒，和油，这些必应允耶斯列民。〔耶斯列就是神栽种的意思〕'),
('CUV', '何西阿书', 28, 2, 23, '我必将她种在这地。素不蒙怜悯的，我必怜悯；本非我民的，我必对他说：你是我的民；他必说：你是我的神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '何西阿书', 28, 3, 1, '耶和华对我说：你再去爱一个淫妇，就是她情人所爱的；好像以色列人，虽然偏向别神，喜爱葡萄饼，耶和华还是爱他们。'),
('CUV', '何西阿书', 28, 3, 2, '我便用银子十五舍客勒，大麦一贺梅珥半，买她归我。'),
('CUV', '何西阿书', 28, 3, 3, '我对她说：你当多日为我独居，不可行淫，不可归别人为妻，我向你也必这样。'),
('CUV', '何西阿书', 28, 3, 4, '以色列人也必多日独居，无君王，无首领，无祭祀，无柱像，无以弗得，无家中的神像。'),
('CUV', '何西阿书', 28, 3, 5, '后来以色列人必归回（或译：回心转意），寻求他们的神─耶和华和他们的王大卫。在末后的日子，必以敬畏的心归向耶和华，领受他的恩惠。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '何西阿书', 28, 4, 1, '以色列人哪，你们当听耶和华的话。耶和华与这地的居民争辩，因这地上无诚实，无良善，无人认识神。'),
('CUV', '何西阿书', 28, 4, 2, '但起假誓，不践前言，杀害，偷盗，奸淫，行强暴，杀人流血，接连不断。'),
('CUV', '何西阿书', 28, 4, 3, '因此，这地悲哀，其上的民、田野的兽、空中的鸟必都衰微，海中的鱼也必消灭。'),
('CUV', '何西阿书', 28, 4, 4, '然而，人都不必争辩，也不必指责，因为这民与抗拒祭司的人一样。'),
('CUV', '何西阿书', 28, 4, 5, '你这祭司必日间跌倒；先知也必夜间与你一同跌倒；我必灭绝你的母亲。'),
('CUV', '何西阿书', 28, 4, 6, '我的民因无知识而灭亡。你弃掉知识，我也必弃掉你，使你不再给我作祭司。你既忘了你神的律法，我也必忘记你的儿女。'),
('CUV', '何西阿书', 28, 4, 7, '祭司越发增多，就越发得罪我；我必使他们的荣耀变为羞辱。'),
('CUV', '何西阿书', 28, 4, 8, '他们吃我民的赎罪祭，满心愿意我民犯罪。'),
('CUV', '何西阿书', 28, 4, 9, '将来民如何，祭司也必如何；我必因他们所行的惩罚他们，照他们所做的报应他们。'),
('CUV', '何西阿书', 28, 4, 10, '他们吃，却不得饱；行淫，而不得立后；因为他们离弃耶和华，不遵他的命。'),
('CUV', '何西阿书', 28, 4, 11, '奸淫和酒，并新酒，夺去人的心。'),
('CUV', '何西阿书', 28, 4, 12, '我的民求问木偶，以为木杖能指示他们；因为他们的淫心使他们失迷，他们就行淫离弃神，不守约束，'),
('CUV', '何西阿书', 28, 4, 13, '在各山顶，各高冈的橡树、杨树、栗树之下，献祭烧香，因为树影美好。所以，你们的女儿淫乱，你们的新妇（或译：儿妇；下同）行淫。'),
('CUV', '何西阿书', 28, 4, 14, '你们的女儿淫乱，你们的新妇行淫，我却不惩罚他们；因为你们自己离群与娼妓同居，与妓女一同献祭。这无知的民必致倾倒。'),
('CUV', '何西阿书', 28, 4, 15, '以色列啊，你虽然行淫，犹大却不可犯罪。不要往吉甲去，不要上到伯亚文，也不要指著永生的耶和华起誓。'),
('CUV', '何西阿书', 28, 4, 16, '以色列倔强，犹如倔强的母牛；现在耶和华要放他们，如同放羊羔在宽阔之地。'),
('CUV', '何西阿书', 28, 4, 17, '以法莲亲近偶像，任凭他罢！'),
('CUV', '何西阿书', 28, 4, 18, '他们所喝的已经发酸，他们时常行淫，他们的官长最爱羞耻的事。'),
('CUV', '何西阿书', 28, 4, 19, '风把他们裹在翅膀里；他们因所献的祭必致蒙羞。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '何西阿书', 28, 5, 1, '众祭司啊，要听我的话！以色列家啊，要留心听！王家啊，要侧耳而听！审判要临到你们，因你们在米斯巴如网罗，在他泊山如铺张的网。'),
('CUV', '何西阿书', 28, 5, 2, '这些悖逆的人肆行杀戮，罪孽极深；我却斥责他们众人。'),
('CUV', '何西阿书', 28, 5, 3, '以法莲为我所知；以色列不能向我隐藏。以法莲哪，现在你行淫了，以色列被玷污了。'),
('CUV', '何西阿书', 28, 5, 4, '他们所行的使他们不能归向神；因有淫心在他们里面，他们也不认识耶和华。'),
('CUV', '何西阿书', 28, 5, 5, '以色列的骄傲当面见证自己。故此，以色列和以法莲必因自己的罪孽跌倒；犹大也必与他们一同跌倒。'),
('CUV', '何西阿书', 28, 5, 6, '他们必牵著牛羊去寻求耶和华，却寻不见；他已经转去离开他们。'),
('CUV', '何西阿书', 28, 5, 7, '他们向耶和华行事诡诈，生了私子。到了月朔，他们与他们的地业必被吞灭。'),
('CUV', '何西阿书', 28, 5, 8, '你们当在基比亚吹角，在拉玛吹号，在伯亚文吹出大声，说：便雅悯哪，有仇敌在你后头！'),
('CUV', '何西阿书', 28, 5, 9, '在责罚的日子，以法莲必变为荒场；我在以色列支派中，指示将来必成的事。'),
('CUV', '何西阿书', 28, 5, 10, '犹大的首领如同挪移地界的人，我必将忿怒倒在他们身上，如水一般。'),
('CUV', '何西阿书', 28, 5, 11, '以法莲因乐从人的命令，就受欺压，被审判压碎。'),
('CUV', '何西阿书', 28, 5, 12, '我使以法莲如虫蛀之物，使犹大家如朽烂之木。'),
('CUV', '何西阿书', 28, 5, 13, '以法莲见自己有病，犹大见自己有伤，他们就打发人往亚述去见耶雷布王，他却不能医治你们，不能治好你们的伤。'),
('CUV', '何西阿书', 28, 5, 14, '我必向以法莲如狮子，向犹大家如少壮狮子。我必撕裂而去，我要夺去，无人搭救。'),
('CUV', '何西阿书', 28, 5, 15, '我要回到原处，等他们自觉有罪（或译：承认己罪），寻求我面；他们在急难的时候必切切寻求我。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '何西阿书', 28, 6, 1, '来罢，我们归向耶和华！他撕裂我们，也必医治；他打伤我们，也必缠裹。'),
('CUV', '何西阿书', 28, 6, 2, '过两天他必使我们苏醒，第三天他必使我们兴起，我们就在他面前得以存活。'),
('CUV', '何西阿书', 28, 6, 3, '我们务要认识耶和华，竭力追求认识他。他出现确如晨光，他必临到我们像甘雨，像滋润田地的春雨。'),
('CUV', '何西阿书', 28, 6, 4, '主说：以法莲哪，我可向你怎样行呢？犹大啊，我可向你怎样做呢？因为你们的良善如同早晨的云雾，又如速散的甘露。'),
('CUV', '何西阿书', 28, 6, 5, '因此，我藉先知砍伐他们，以我口中的话杀戮他们；我施行的审判如光发出。'),
('CUV', '何西阿书', 28, 6, 6, '我喜爱良善（或译：怜恤），不喜爱祭祀；喜爱认识神，胜于燔祭。'),
('CUV', '何西阿书', 28, 6, 7, '他们却如亚当背约，在境内向我行事诡诈。'),
('CUV', '何西阿书', 28, 6, 8, '基列是作孽之人的城，被血沾染。'),
('CUV', '何西阿书', 28, 6, 9, '强盗成群，怎样埋伏杀人，祭司结党，也照样在示剑的路上杀戮，行了邪恶。'),
('CUV', '何西阿书', 28, 6, 10, '在以色列家，我见了可憎的事；在以法莲那里有淫行，以色列被玷污。'),
('CUV', '何西阿书', 28, 6, 11, '犹大啊，我使被掳之民归回的时候，必有为你所命定的收场。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '何西阿书', 28, 7, 1, '我想医治以色列的时候，以法莲的罪孽和撒玛利亚的罪恶就显露出来。他们行事虚谎，内有贼人入室偷窃，外有强盗成群骚扰。'),
('CUV', '何西阿书', 28, 7, 2, '他们心里并不思想我记念他们的一切恶；他们所行的现在缠绕他们，都在我面前。'),
('CUV', '何西阿书', 28, 7, 3, '他们行恶使君王欢喜，说谎使首领喜乐。'),
('CUV', '何西阿书', 28, 7, 4, '他们都是行淫的，像火炉被烤饼的烧热，从抟面到发面的时候，暂不使火著旺。'),
('CUV', '何西阿书', 28, 7, 5, '在我们王宴乐的日子，首领因酒的烈性成病；王与亵慢人拉手。'),
('CUV', '何西阿书', 28, 7, 6, '首领埋伏的时候，心中热如火炉，就如烤饼的整夜睡卧，到了早晨火气炎炎。'),
('CUV', '何西阿书', 28, 7, 7, '众民也热如火炉，烧灭他们的官长。他们的君王都仆倒而死；他们中间无一人求告我。'),
('CUV', '何西阿书', 28, 7, 8, '以法莲与列邦人搀杂；以法莲是没有翻过的饼。'),
('CUV', '何西阿书', 28, 7, 9, '外邦人吞吃他劳力得来的，他却不知道；头发斑白，他也不觉得。'),
('CUV', '何西阿书', 28, 7, 10, '以色列的骄傲当面见证自己，虽遭遇这一切，他们仍不归向耶和华─他们的神，也不寻求他。'),
('CUV', '何西阿书', 28, 7, 11, '以法莲好像鸽子愚蠢无知；他们求告埃及，投奔亚述。'),
('CUV', '何西阿书', 28, 7, 12, '他们去的时候，我必将我的网撒在他们身上；我要打下他们，如同空中的鸟。我必按他们会众所听见的惩罚他们。'),
('CUV', '何西阿书', 28, 7, 13, '他们因离弃我，必定有祸；因违背我，必被毁灭。我虽要救赎他们，他们却向我说谎。'),
('CUV', '何西阿书', 28, 7, 14, '他们并不诚心哀求我，乃在床上呼号；他们为求五谷新酒聚集，仍然悖逆我。'),
('CUV', '何西阿书', 28, 7, 15, '我虽教导他们，坚固他们的膀臂，他们竟图谋抗拒我。'),
('CUV', '何西阿书', 28, 7, 16, '他们归向，却不归向至上者；他们如同翻背的弓。他们的首领必因舌头的狂傲倒在刀下；这在埃及地必作人的讥笑。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '何西阿书', 28, 8, 1, '你用口吹角罢！敌人如鹰来攻打耶和华的家；因为这民违背我的约，干犯我的律法。'),
('CUV', '何西阿书', 28, 8, 2, '他们必呼叫我说：我的神啊，我们以色列认识你了。'),
('CUV', '何西阿书', 28, 8, 3, '以色列丢弃良善（或译：福分）；仇敌必追逼他。'),
('CUV', '何西阿书', 28, 8, 4, '他们立君王，却不由我；他们立首领，我却不认。他们用金银为自己制造偶像，以致被剪除。'),
('CUV', '何西阿书', 28, 8, 5, '撒玛利亚啊，耶和华已经丢弃你的牛犊；我的怒气向拜牛犊的人发作。他们到几时方能无罪呢？'),
('CUV', '何西阿书', 28, 8, 6, '这牛犊出于以色列，是匠人所造的，并不是神。撒玛利亚的牛犊必被打碎。'),
('CUV', '何西阿书', 28, 8, 7, '他们所种的是风，所收的是暴风；所种的不成禾稼，就是发苗也不结实；即便结实，外邦人必吞吃。'),
('CUV', '何西阿书', 28, 8, 8, '以色列被吞吃；现今在列国中，好像人不喜悦的器皿。'),
('CUV', '何西阿书', 28, 8, 9, '他们投奔亚述，如同独行的野驴；以法莲贿买朋党。'),
('CUV', '何西阿书', 28, 8, 10, '他们虽在列邦中贿买人，现在我却要聚集惩罚他们；他们因君王和首领所加的重担日渐衰微。'),
('CUV', '何西阿书', 28, 8, 11, '以法莲增添祭坛取罪；因此，祭坛使他犯罪。'),
('CUV', '何西阿书', 28, 8, 12, '我为他写了律法万条，他却以为与他毫无关涉。'),
('CUV', '何西阿书', 28, 8, 13, '至于献给我的祭物，他们自食其肉，耶和华却不悦纳他们。现在必记念他们的罪孽，追讨他们的罪恶；他们必归回埃及。'),
('CUV', '何西阿书', 28, 8, 14, '以色列忘记造他的主，建造宫殿；犹大多造坚固城，我却要降火焚烧他的城邑，烧灭其中的宫殿。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '何西阿书', 28, 9, 1, '以色列啊，不要像外邦人欢喜快乐；因为你行邪淫离弃你的神，在各谷场上如妓女喜爱赏赐。'),
('CUV', '何西阿书', 28, 9, 2, '谷场和酒醡都不够以色列人使用；新酒也必缺乏。'),
('CUV', '何西阿书', 28, 9, 3, '他们必不得住耶和华的地；以法莲却要归回埃及，必在亚述吃不洁净的食物。'),
('CUV', '何西阿书', 28, 9, 4, '他们必不得向耶和华奠酒，即便奠酒也不蒙悦纳。他们的祭物必如居丧者的食物，凡吃的必被玷污；因他们的食物只为自己的口腹，必不奉入耶和华的殿。'),
('CUV', '何西阿书', 28, 9, 5, '在大会的日子，到耶和华的节期，你们怎样行呢？'),
('CUV', '何西阿书', 28, 9, 6, '看哪，他们逃避灾难；埃及人必收殓他们的尸首，摩弗人必葬埋他们的骸骨。他们用银子做的美物上必长蒺藜；他们的帐棚中必生荆棘。'),
('CUV', '何西阿书', 28, 9, 7, '以色列人必知道降罚的日子临近，报应的时候来到。民说：作先知的是愚昧；受灵感的是狂妄，皆因他们多多作孽，大怀怨恨。'),
('CUV', '何西阿书', 28, 9, 8, '以法莲曾作我神守望的；至于先知，在他一切的道上作为捕鸟人的网罗，在他神的家中怀怨恨。'),
('CUV', '何西阿书', 28, 9, 9, '以法莲深深地败坏，如在基比亚的日子一样。耶和华必记念他们的罪孽，追讨他们的罪恶。'),
('CUV', '何西阿书', 28, 9, 10, '主说：我遇见以色列如葡萄在旷野；我看见你们的列祖如无花果树上春季初熟的果子。他们却来到巴力毗珥专拜那可羞耻的，就成为可憎恶的，与他们所爱的一样。'),
('CUV', '何西阿书', 28, 9, 11, '至于以法莲人，他们的荣耀必如鸟飞去，必不生产，不怀胎，不成孕。'),
('CUV', '何西阿书', 28, 9, 12, '纵然养大儿女，我却必使他们丧子，甚至不留一个。我离弃他们，他们就有祸了。'),
('CUV', '何西阿书', 28, 9, 13, '我看以法莲如推罗栽于美地。以法莲却要将自己的儿女带出来，交与行杀戮的人。'),
('CUV', '何西阿书', 28, 9, 14, '耶和华啊，求你加给他们─加甚么呢？要使他们胎坠乳干。'),
('CUV', '何西阿书', 28, 9, 15, '耶和华说：他们一切的恶事都在吉甲；我在那里憎恶他们。因他们所行的恶，我必从我地上赶出他们去，不再怜爱他们；他们的首领都是悖逆的。'),
('CUV', '何西阿书', 28, 9, 16, '以法莲受责罚，根本枯干，必不能结果，即或生产，我必杀他们所生的爱子。'),
('CUV', '何西阿书', 28, 9, 17, '我的神必弃绝他们，因为他们不听从他；他们也必飘流在列国中。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '何西阿书', 28, 10, 1, '以色列是茂盛的葡萄树，结果繁多。果子越多，就越增添祭坛；地土越肥美，就越造美丽的柱像。'),
('CUV', '何西阿书', 28, 10, 2, '他们心怀二意，现今要定为有罪。耶和华必拆毁他们的祭坛，毁坏他们的柱像。'),
('CUV', '何西阿书', 28, 10, 3, '他们必说：我们没有王，因为我们不敬畏耶和华。王能为我们做甚么呢？'),
('CUV', '何西阿书', 28, 10, 4, '他们为立约说谎言，起假誓；因此，灾罚如苦菜滋生在田间的犁沟中。'),
('CUV', '何西阿书', 28, 10, 5, '撒玛利亚的居民必因伯亚文的牛犊惊恐；崇拜牛犊的民和喜爱牛犊的祭司都必因荣耀离开他，为他悲哀。'),
('CUV', '何西阿书', 28, 10, 6, '牛犊带到亚述当作礼物，献给耶雷布王。以法莲必蒙羞；以色列必因自己的计谋惭愧。'),
('CUV', '何西阿书', 28, 10, 7, '至于撒玛利亚，他的王必灭没，如水面的沫子一样。'),
('CUV', '何西阿书', 28, 10, 8, '伯亚文的邱坛─就是以色列取罪的地方必被毁灭；荆棘和蒺藜必长在他们的祭坛上。他们必对大山说：遮盖我们！对小山说：倒在我们身上！'),
('CUV', '何西阿书', 28, 10, 9, '以色列啊，你从基比亚的日子以来时常犯罪。你们的先人曾站在那里，现今住基比亚的人以为攻击罪孽之辈的战事临不到自己。'),
('CUV', '何西阿书', 28, 10, 10, '我必随意惩罚他们。他们为两样的罪所缠；列邦的民必聚集攻击他们。'),
('CUV', '何西阿书', 28, 10, 11, '以法莲是驯良的母牛犊，喜爱踹谷，我却将轭加在他肥美的颈项上，我要使以法莲拉套（或作：被骑）。犹大必耕田；雅各必耙地。'),
('CUV', '何西阿书', 28, 10, 12, '你们要为自己栽种公义，就能收割慈爱。现今正是寻求耶和华的时候；你们要开垦荒地，等他临到，使公义如雨降在你们身上。'),
('CUV', '何西阿书', 28, 10, 13, '你们耕种的是奸恶，收割的是罪孽，吃的是谎话的果子。因你倚靠自己的行为，仰赖勇士众多，'),
('CUV', '何西阿书', 28, 10, 14, '所以在这民中必有哄嚷之声，你一切的保障必被拆毁，就如沙勒幔在争战的日子拆毁伯亚比勒，将其中的母子一同摔死。'),
('CUV', '何西阿书', 28, 10, 15, '因他们的大恶，伯特利必使你们遭遇如此。到了黎明，以色列的王必全然灭绝。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '何西阿书', 28, 11, 1, '以色列年幼的时候，我爱他，就从埃及召出我的儿子来。'),
('CUV', '何西阿书', 28, 11, 2, '先知越发招呼他们，他们越发走开，向诸巴力献祭，给雕刻的偶像烧香。'),
('CUV', '何西阿书', 28, 11, 3, '我原教导以法莲行走，用膀臂抱著他们，他们却不知道是我医治他们。'),
('CUV', '何西阿书', 28, 11, 4, '我用慈绳（慈：原文是人的）爱索牵引他们；我待他们如人放松牛的两腮夹板，把粮食放在他们面前。'),
('CUV', '何西阿书', 28, 11, 5, '他们必不归回埃及地，亚述人却要作他们的王，因他们不肯归向我。'),
('CUV', '何西阿书', 28, 11, 6, '刀剑必临到他们的城邑，毁坏门闩，把人吞灭，都因他们随从自己的计谋。'),
('CUV', '何西阿书', 28, 11, 7, '我的民偏要背道离开我；众先知虽然招呼他们归向至上的主，却无人尊崇主。'),
('CUV', '何西阿书', 28, 11, 8, '以法莲哪，我怎能舍弃你？以色列啊，我怎能弃绝你？我怎能使你如押玛？怎能使你如洗扁？我回心转意，我的怜爱大大发动。'),
('CUV', '何西阿书', 28, 11, 9, '我必不发猛烈的怒气，也不再毁灭以法莲。因我是神，并非世人，是你们中间的圣者；我必不在怒中临到你们。'),
('CUV', '何西阿书', 28, 11, 10, '耶和华必如狮子吼叫，子民必跟随他。他一吼叫，他们就从西方急速而来。'),
('CUV', '何西阿书', 28, 11, 11, '他们必如雀鸟从埃及急速而来，又如鸽子从亚述地来到。我必使他们住自己的房屋。这是耶和华说的。'),
('CUV', '何西阿书', 28, 11, 12, '以法莲用谎话，以色列家用诡计围绕我；犹大却靠神掌权，向圣者有忠心（或译：犹大向神，向诚实的圣者犹疑不定）。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '何西阿书', 28, 12, 1, '以法莲吃风，且追赶东风，时常增添虚谎和强暴，与亚述立约，把油送到埃及。'),
('CUV', '何西阿书', 28, 12, 2, '耶和华与犹大争辩，必照雅各所行的惩罚他，按他所做的报应他。'),
('CUV', '何西阿书', 28, 12, 3, '他在腹中抓住哥哥的脚跟，壮年的时候与神较力，'),
('CUV', '何西阿书', 28, 12, 4, '与天使较力，并且得胜，哭泣恳求，在伯特利遇见耶和华。耶和华─万军之神在那里晓谕我们以色列人；耶和华是他可记念的名。'),
('CUV', '何西阿书', 28, 12, 5, 'a'),
('CUV', '何西阿书', 28, 12, 6, '所以你当归向你的神，谨守仁爱、公平，常常等候你的神。'),
('CUV', '何西阿书', 28, 12, 7, '以法莲是商人，手里有诡诈的天平，爱行欺骗。'),
('CUV', '何西阿书', 28, 12, 8, '以法莲说：我果然成了富足，得了财宝；我所劳碌得来的，人必不见有甚么不义，可算为罪的。'),
('CUV', '何西阿书', 28, 12, 9, '自从你出埃及地以来，我就是耶和华─你的神；我必使你再住帐棚，如在大会的日子一样。'),
('CUV', '何西阿书', 28, 12, 10, '我已晓谕众先知，并且加增默示，藉先知设立比喻。'),
('CUV', '何西阿书', 28, 12, 11, '基列人没有罪孽么？他们全然是虚假的。人在吉甲献牛犊为祭，他们的祭坛好像田间犁沟中的乱堆。'),
('CUV', '何西阿书', 28, 12, 12, '从前雅各逃到亚兰地，以色列为得妻服事人，为得妻与人放羊。'),
('CUV', '何西阿书', 28, 12, 13, '耶和华藉先知领以色列从埃及上来；以色列也藉先知而得保存。'),
('CUV', '何西阿书', 28, 12, 14, '以法莲大大惹动主怒，所以他流血的罪必归在他身上。主必将那因以法莲所受的羞辱归还他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '何西阿书', 28, 13, 1, '从前以法莲说话，人都战兢，他在以色列中居处高位；但他在事奉巴力的事上犯罪就死了。'),
('CUV', '何西阿书', 28, 13, 2, '现今他们罪上加罪，用银子为自己铸造偶像，就是照自己的聪明制造，都是匠人的工作。有人论说，献祭的人可以向牛犊亲嘴。'),
('CUV', '何西阿书', 28, 13, 3, '因此，他们必如早晨的云雾，又如速散的甘露，像场上的糠秕被狂风吹去，又像烟气腾于窗外。'),
('CUV', '何西阿书', 28, 13, 4, '自从你出埃及地以来，我就是耶和华─你的神。在我以外，你不可认识别神；除我以外并没有救主。'),
('CUV', '何西阿书', 28, 13, 5, '我曾在旷野干旱之地认识你。'),
('CUV', '何西阿书', 28, 13, 6, '这些民照我所赐的食物得了饱足；既得饱足，心就高傲，忘记了我。'),
('CUV', '何西阿书', 28, 13, 7, '因此，我向他们如狮子，又如豹伏在道旁。'),
('CUV', '何西阿书', 28, 13, 8, '我遇见他们必像丢崽子的母熊，撕裂他们的胸膛（或译：心膜）。在那里，我必像母狮吞吃他们；野兽必撕裂他们。'),
('CUV', '何西阿书', 28, 13, 9, '以色列啊，你与我反对，就是反对帮助你的，自取败坏。'),
('CUV', '何西阿书', 28, 13, 10, '你曾求我说：给我立王和首领。现在你的王在哪里呢？治理你的在哪里呢？让他在你所有的城中拯救你罢！'),
('CUV', '何西阿书', 28, 13, 11, '我在怒气中将王赐你，又在烈怒中将王废去。'),
('CUV', '何西阿书', 28, 13, 12, '以法莲的罪孽包裹；他的罪恶收藏。'),
('CUV', '何西阿书', 28, 13, 13, '产妇的疼痛必临到他身上；他是无智慧之子，到了产期不当迟延。'),
('CUV', '何西阿书', 28, 13, 14, '我必救赎他们脱离阴间，救赎他们脱离死亡。死亡啊，你的灾害在哪里呢？阴间哪，你的毁灭在哪里呢？在我眼前绝无后悔之事。'),
('CUV', '何西阿书', 28, 13, 15, '他在弟兄中虽然茂盛，必有东风刮来，就是耶和华的风从旷野上来。他的泉源必干；他的源头必竭；仇敌必掳掠他所积蓄的一切宝器。'),
('CUV', '何西阿书', 28, 13, 16, '撒玛利亚必担当自己的罪，因为悖逆他的神。他必倒在刀下；婴孩必被摔死；孕妇必被剖开。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '何西阿书', 28, 14, 1, '以色列啊，你要归向耶和华─你的神；你是因自己的罪孽跌倒了。'),
('CUV', '何西阿书', 28, 14, 2, '当归向耶和华，用言语祷告他说：求你除净罪孽，悦纳善行；这样，我们就把嘴唇的祭代替牛犊献上。'),
('CUV', '何西阿书', 28, 14, 3, '我们不向亚述求救，不骑埃及的马，也不再对我们手所造的说：你是我们的神。因为孤儿在你─耶和华那里得蒙怜悯。'),
('CUV', '何西阿书', 28, 14, 4, '我必医治他们背道的病，甘心爱他们；因为我的怒气向他们转消。'),
('CUV', '何西阿书', 28, 14, 5, '我必向以色列如甘露；他必如百合花开放，如利巴嫩的树木扎根。'),
('CUV', '何西阿书', 28, 14, 6, '他的枝条必延长；他的荣华如橄榄树；他的香气如利巴嫩的香柏树。'),
('CUV', '何西阿书', 28, 14, 7, '曾住在他荫下的必归回，发旺如五谷，开花如葡萄树。他的香气如利巴嫩的酒。'),
('CUV', '何西阿书', 28, 14, 8, '以法莲必说：我与偶像还有甚么关涉呢？我─耶和华回答他，也必顾念他。我如青翠的松树；你的果子从我而得。'),
('CUV', '何西阿书', 28, 14, 9, '谁是智慧人，可以明白这些事；谁是通达人，可以知道这一切。因为，耶和华的道是正直的；义人必在其中行走，罪人却在其上跌倒。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约珥书', 29, 1, 1, '耶和华的话临到毗土珥的儿子约珥。'),
('CUV', '约珥书', 29, 1, 2, '老年人哪，当听我的话；国中的居民哪，都要侧耳而听。在你们的日子，或你们列祖的日子，曾有这样的事么？'),
('CUV', '约珥书', 29, 1, 3, '你们要将这事传与子，子传与孙，孙，传与后代。'),
('CUV', '约珥书', 29, 1, 4, '剪虫剩下的，蝗虫来吃；蝗虫剩下的，蝻子来吃；蝻子剩下的，蚂蚱来吃。'),
('CUV', '约珥书', 29, 1, 5, '酒醉的人哪，要清醒哭泣；好酒的人哪，都要为甜酒哀号，因为从你们的口中断绝了。'),
('CUV', '约珥书', 29, 1, 6, '有一队蝗虫（原文是民）又强盛又无数，侵犯我的地；他的牙齿如狮子的牙齿，大牙如母狮的大牙。'),
('CUV', '约珥书', 29, 1, 7, '他毁坏我的葡萄树，剥了我无花果树的皮，剥尽而丢弃，使枝条露白。'),
('CUV', '约珥书', 29, 1, 8, '我的民哪，你当哀号，像处女腰束麻布，为幼年的丈夫哀号。'),
('CUV', '约珥书', 29, 1, 9, '素祭和奠祭从耶和华的殿中断绝；事奉耶和华的祭司都悲哀。'),
('CUV', '约珥书', 29, 1, 10, '田荒凉，地悲哀；因为五谷毁坏，新酒干竭，油也缺乏。'),
('CUV', '约珥书', 29, 1, 11, '农夫啊，你们要惭愧'),
('CUV', '约珥书', 29, 1, 12, '葡萄树枯干；无花果树衰残。石榴树、棕树、苹果树，连田野一切的树木也都枯干；众人的喜乐尽都消灭。'),
('CUV', '约珥书', 29, 1, 13, '祭司啊，你们当腰束麻布痛哭；伺候祭坛的啊，你们要哀号；事奉我神的啊，你们要来披上麻布过夜，因为素祭和奠祭从你们神的殿中断绝了。'),
('CUV', '约珥书', 29, 1, 14, '你们要分定禁食的日子，宣告严肃会，招聚长老和国中的一切居民到耶和华─你们神的殿，向耶和华哀求。'),
('CUV', '约珥书', 29, 1, 15, '哀哉!耶和华的日子临近了。这日来到，好像毁灭从全能者来到。'),
('CUV', '约珥书', 29, 1, 16, '粮食不是在我们眼前断绝了吗？欢喜快乐不是从我们神的殿中止息了吗？'),
('CUV', '约珥书', 29, 1, 17, '谷种在土块下朽烂；仓也荒凉，廪也破坏；因为五谷枯干了。'),
('CUV', '约珥书', 29, 1, 18, '牲畜哀鸣；牛群混乱，因为无草；羊群也受了困苦。'),
('CUV', '约珥书', 29, 1, 19, '耶和华啊，我向你求告，因为火烧灭旷野的草场；火焰烧尽田野的树木。'),
('CUV', '约珥书', 29, 1, 20, '田野的走兽向你发喘；因为溪水干涸，火也烧灭旷野的草场。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约珥书', 29, 2, 1, '你们要在锡安吹角，在我圣山吹出大声。国中的居民都要发颤；因为耶和华的日子将到，已经临近。'),
('CUV', '约珥书', 29, 2, 2, '那日是黑暗、幽冥、密云、乌黑的日子，好像晨光铺满山岭。有一队蝗虫（原文是民）又大又强；从来没有这样的，以后直到万代也必没有。'),
('CUV', '约珥书', 29, 2, 3, '他们前面如火烧灭，后面如火燄烧尽。未到以前，地如伊甸园；过去以后，成了荒凉的旷野；没有一样能躲避他们的。'),
('CUV', '约珥书', 29, 2, 4, '他们的形状如马，奔跑如马兵。'),
('CUV', '约珥书', 29, 2, 5, '在山顶蹦跳的响声，如车辆的响声，又如火燄烧碎秸的响声，好像强盛的民摆阵预备打仗。'),
('CUV', '约珥书', 29, 2, 6, '他们一来，众民伤恸，脸都变色。'),
('CUV', '约珥书', 29, 2, 7, '他们如勇士奔跑，像战士爬城；各都步行，不乱队伍。'),
('CUV', '约珥书', 29, 2, 8, '彼此并不拥挤，向前各行其路，直闯兵器，不偏左右。'),
('CUV', '约珥书', 29, 2, 9, '他们蹦上城，蹿上墙，爬上房屋，进入窗户如同盗贼。'),
('CUV', '约珥书', 29, 2, 10, '他们一来，地震天动，日月昏暗，星宿无光。'),
('CUV', '约珥书', 29, 2, 11, '耶和华在他军旅前发声，他的队伍甚大；成就他命的是强盛者。因为耶和华的日子大而可畏，谁能当得起呢？'),
('CUV', '约珥书', 29, 2, 12, '耶和华说：虽然如此，你们应当禁食、哭泣、悲哀，一心归向我。'),
('CUV', '约珥书', 29, 2, 13, '你们要撕裂心肠，不撕裂衣服。归向耶和华─你们的神；因为他有恩典，有怜悯，不轻易发怒，有丰盛的慈爱，并且后悔不降所说的灾。'),
('CUV', '约珥书', 29, 2, 14, '或者他转意后悔，留下余福，就是留下献给耶和华─你们神的素祭和奠祭，也未可知。'),
('CUV', '约珥书', 29, 2, 15, '你们要在锡安吹角，分定禁食的日子，宣告严肃会。'),
('CUV', '约珥书', 29, 2, 16, '聚集众民，使会众自洁：招聚老者，聚集孩童和吃奶的；使新郎出离洞房，新妇出离内室。'),
('CUV', '约珥书', 29, 2, 17, '事奉耶和华的祭司要在廊子和祭坛中间哭泣，说：耶和华啊，求你顾惜你的百姓，不要使你的产业受羞辱，列邦管辖他们。为何容列国的人说：他们的神在哪里呢？'),
('CUV', '约珥书', 29, 2, 18, '耶和华就为自己的地发热心，怜恤他的百姓。'),
('CUV', '约珥书', 29, 2, 19, '耶和华应允他的百姓说：我必赐给你们五谷、新酒，和油，使你们饱足；我也不再使你们受列国的羞辱；'),
('CUV', '约珥书', 29, 2, 20, '却要使北方来的军队远离你们，将他们赶到干旱荒废之地：前队赶入东海，后队赶入西海；因为他们所行的大恶（原文作事），臭气上升，腥味腾空。'),
('CUV', '约珥书', 29, 2, 21, '地土啊，不要惧怕；要欢喜快乐，因为耶和华行了大事。'),
('CUV', '约珥书', 29, 2, 22, '田野的走兽啊，不要惧怕；因为，旷野的草发生，树木结果，无花果树、葡萄树也都效力。'),
('CUV', '约珥书', 29, 2, 23, '锡安的民哪，你们要快乐，为耶和华─你们的神欢喜；因他赐给你们合宜的秋雨，为你们降下甘霖，就是秋雨、春雨，和先前一样。'),
('CUV', '约珥书', 29, 2, 24, '禾场必满了麦子；酒醡与油醡必有新酒和油盈溢。'),
('CUV', '约珥书', 29, 2, 25, '我打发到你们中间的大军队，就是蝗虫、蝻子、蚂蚱、剪虫，那些年所吃的，我要补还你们。'),
('CUV', '约珥书', 29, 2, 26, '你们必多吃而得饱足就赞美为你们行奇妙事之耶和华─你们神的名。我的百姓必永远不至羞愧。'),
('CUV', '约珥书', 29, 2, 27, '你们必知道我是在以色列中间，又知道我是耶和华─你们的神；在我以外并无别神。我的百姓必永远不致羞愧。'),
('CUV', '约珥书', 29, 2, 28, '以后，我要将我的灵浇灌凡有血气的。你们的儿女要说预言；你们的老年人要做异梦，少年人要见异象。'),
('CUV', '约珥书', 29, 2, 29, '在那些日子，我要将我的灵浇灌我的仆人和使女。'),
('CUV', '约珥书', 29, 2, 30, '在天上地下，我要显出奇事，有血，有火，有烟柱。'),
('CUV', '约珥书', 29, 2, 31, '日头要变为黑暗，月亮要变为血，这都在耶和华大而可畏的日子未到以前。'),
('CUV', '约珥书', 29, 2, 32, '到那时候，凡求告耶和华名的就必得救；因为照耶和华所说的，在锡安山，耶路撒冷必有逃脱的人，在剩下的人中必有耶和华所召的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约珥书', 29, 3, 1, '到那日，我使犹大和耶路撒冷被掳之人归回的时候，'),
('CUV', '约珥书', 29, 3, 2, '我要聚集万民，带他们下到约沙法谷，在那里施行审判；因为他们将我的百姓，就是我的产业以色列，分散在列国中，又分取我的地土，'),
('CUV', '约珥书', 29, 3, 3, '且为我的百姓拈阄，将童子换妓女，卖童女买酒喝。'),
('CUV', '约珥书', 29, 3, 4, '推罗、西顿，和非利士四境的人哪，你们与我何干？你们要报复我么？若报复我，我必使报应速速归到你们的头上。'),
('CUV', '约珥书', 29, 3, 5, '你们既然夺取我的金银，又将我可爱的宝物带入你们宫殿（或译：庙中），'),
('CUV', '约珥书', 29, 3, 6, '并将犹大人和耶路撒冷人卖给希利尼人（原文是雅完人），使他们远离自己的境界。'),
('CUV', '约珥书', 29, 3, 7, '我必激动他们离开你们所卖到之地，又必使报应归到你们的头上。'),
('CUV', '约珥书', 29, 3, 8, '我必将你们的儿女卖在犹大人的手中，他们必卖给远方示巴国的人。这是耶和华说的。'),
('CUV', '约珥书', 29, 3, 9, '当在万民中宣告说：要预备打仗；激动勇士，使一切战士上前来。'),
('CUV', '约珥书', 29, 3, 10, '要将犁头打成刀剑，将镰刀打成戈矛；软弱的要说：我有勇力。'),
('CUV', '约珥书', 29, 3, 11, '四围的列国啊，你们要速速地来，一同聚集。耶和华啊，求你使你的大能者降临。'),
('CUV', '约珥书', 29, 3, 12, '万民都当兴起，上到约沙法谷；因为我必坐在那里，审判四围的列国。'),
('CUV', '约珥书', 29, 3, 13, '开镰罢！因为庄稼熟了；践踏罢！因为酒醡满了。酒池盈溢；他们的罪恶甚大。'),
('CUV', '约珥书', 29, 3, 14, '许多许多的人在断定谷，因为耶和华的日子临近断定谷。'),
('CUV', '约珥书', 29, 3, 15, '日月昏暗，星宿无光。'),
('CUV', '约珥书', 29, 3, 16, '耶和华必从锡安吼叫，从耶路撒冷发声，天地就震动。耶和华却要作他百姓的避难所，作以色列人的保障。'),
('CUV', '约珥书', 29, 3, 17, '你们就知道我是耶和华─你们的神，且又住在锡安─我的圣山。那时，耶路撒冷必成为圣；外邦人不再从其中经过。'),
('CUV', '约珥书', 29, 3, 18, '到那日，大山要滴甜酒；小山要流奶子；犹大溪河都有水流。必有泉源从耶和华的殿中流出来，滋润什亭谷。'),
('CUV', '约珥书', 29, 3, 19, '埃及必然荒凉，以东变为凄凉的旷野，都因向犹大人所行的强暴，又因在本地流无辜人的血。'),
('CUV', '约珥书', 29, 3, 20, '但犹大必存到永远；耶路撒冷必存到万代。'),
('CUV', '约珥书', 29, 3, 21, '我未曾报复（或译：洗除；下同）流血的罪，现在我要报复，因为耶和华住在锡安。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '阿摩司书', 30, 1, 1, '当犹大王乌西雅，以色列王约阿施的儿子耶罗波安在位的时候，大地震前二年，提哥亚牧人中的阿摩司得默示论以色列。'),
('CUV', '阿摩司书', 30, 1, 2, '他说：耶和华必从锡安吼叫，从耶路撒冷发声；牧人的草场要悲哀；迦密的山顶要枯干。'),
('CUV', '阿摩司书', 30, 1, 3, '耶和华如此说：大马色三番四次地犯罪，我必不免去他的刑罚；因为他以打粮食的铁器打过基列。'),
('CUV', '阿摩司书', 30, 1, 4, '我却要降火在哈薛的家中，烧灭便哈达的宫殿。'),
('CUV', '阿摩司书', 30, 1, 5, '我必折断大马色的门闩，剪除亚文平原的居民和伯伊甸掌权的。亚兰人必被掳到吉珥。这是耶和华说的。'),
('CUV', '阿摩司书', 30, 1, 6, '耶和华如此说：迦萨三番四次地犯罪，我必不免去他的刑罚；因为他掳掠众民交给以东。'),
('CUV', '阿摩司书', 30, 1, 7, '我却要降火在迦萨的城内，烧灭其中的宫殿。'),
('CUV', '阿摩司书', 30, 1, 8, '我必剪除亚实突的居民和亚实基伦掌权的，也必反手攻击以革伦。非利士人所余剩的必都灭亡。这是主耶和华说的。'),
('CUV', '阿摩司书', 30, 1, 9, '耶和华如此说：推罗三番四次地犯罪，我必不免去他的刑罚；因为他将众民交给以东，并不记念弟兄的盟约。'),
('CUV', '阿摩司书', 30, 1, 10, '我却要降火在推罗的城内，烧灭其中的宫殿。'),
('CUV', '阿摩司书', 30, 1, 11, '耶和华如此说：以东三番四次地犯罪，我必不免去他的刑罚；因为他拿刀追赶兄弟，毫无怜悯，发怒撕裂，永怀忿怒。'),
('CUV', '阿摩司书', 30, 1, 12, '我却要降火在提幔，烧灭波斯拉的宫殿。'),
('CUV', '阿摩司书', 30, 1, 13, '耶和华如此说：亚扪人三番四次地犯罪，我必不免去他们的刑罚；因为他们剖开基列的孕妇，扩张自己的境界。'),
('CUV', '阿摩司书', 30, 1, 14, '我却要在争战呐喊的日子，旋风狂暴的时候，点火在拉巴的城内，烧灭其中的宫殿。'),
('CUV', '阿摩司书', 30, 1, 15, '他们的王和首领必一同被掳去。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '阿摩司书', 30, 2, 1, '耶和华如此说：摩押三番四次地犯罪，我必不免去他的刑罚；因为他将以东王的骸骨焚烧成灰。'),
('CUV', '阿摩司书', 30, 2, 2, '我却要降火在摩押，烧灭加略的宫殿。摩押必在哄嚷呐喊吹角之中死亡。'),
('CUV', '阿摩司书', 30, 2, 3, '我必剪除摩押中的审判者，将其中的一切首领和他一同杀戮。这是耶和华说的。'),
('CUV', '阿摩司书', 30, 2, 4, '耶和华如此说：犹大人三番四次地犯罪，我必不免去他们的刑罚；因为他们厌弃耶和华的训诲，不遵守他的律例。他们列祖所随从虚假的偶像使他们走迷了。'),
('CUV', '阿摩司书', 30, 2, 5, '我却要降火在犹大，烧灭耶路撒冷的宫殿。'),
('CUV', '阿摩司书', 30, 2, 6, '耶和华如此说：以色列人三番四次地犯罪，我必不免去他们的刑罚；因他们为银子卖了义人，为一双鞋卖了穷人。'),
('CUV', '阿摩司书', 30, 2, 7, '他们见穷人头上所蒙的灰也都垂涎，阻碍谦卑人的道路。父子同一个女子行淫，亵渎我的圣名。'),
('CUV', '阿摩司书', 30, 2, 8, '他们在各坛旁铺人所当的衣服，卧在其上，又在他们神的庙中喝受罚之人的酒。'),
('CUV', '阿摩司书', 30, 2, 9, '我从以色列人面前除灭亚摩利人。他虽高大如香柏树，坚固如橡树，我却上灭他的果子，下绝他的根本。'),
('CUV', '阿摩司书', 30, 2, 10, '我也将你们从埃及地领上来，在旷野引导你们四十年，使你们得亚摩利人之地为业。'),
('CUV', '阿摩司书', 30, 2, 11, '我从你们子弟中兴起先知，又从你们少年人中兴起拿细耳人。以色列人哪，不是这样么？这是耶和华说的。'),
('CUV', '阿摩司书', 30, 2, 12, '你们却给拿细耳人酒喝，嘱咐先知说：不要说预言。'),
('CUV', '阿摩司书', 30, 2, 13, '看哪，在你们所住之地，我必压你们，如同装满禾捆的车压物一样。'),
('CUV', '阿摩司书', 30, 2, 14, '快跑的不能逃脱；有力的不能用力；刚勇的也不能自救。'),
('CUV', '阿摩司书', 30, 2, 15, '拿弓的不能站立；腿快的不能逃脱；骑马的也不能自救。'),
('CUV', '阿摩司书', 30, 2, 16, '到那日，勇士中最有胆量的，必赤身逃跑。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '阿摩司书', 30, 3, 1, '以色列人哪，你们全家是我从埃及地领上来的，当听耶和华攻击你们的话：'),
('CUV', '阿摩司书', 30, 3, 2, '在地上万族中，我只认识你们；因此，我必追讨你们的一切罪孽。'),
('CUV', '阿摩司书', 30, 3, 3, '二人若不同心，岂能同行呢？'),
('CUV', '阿摩司书', 30, 3, 4, '狮子若非抓食，岂能在林中咆哮呢？少壮狮子若无所得，岂能从洞中发声呢？'),
('CUV', '阿摩司书', 30, 3, 5, '若没有机槛，雀鸟岂能陷在网罗里呢？网罗若无所得，岂能从地上翻起呢？'),
('CUV', '阿摩司书', 30, 3, 6, '城中若吹角，百姓岂不惊恐呢？灾祸若临到一城，岂非耶和华所降的么？'),
('CUV', '阿摩司书', 30, 3, 7, '主耶和华若不将奥秘指示他的仆人─众先知，就一无所行。'),
('CUV', '阿摩司书', 30, 3, 8, '狮子吼叫，谁不惧怕呢？主耶和华发命，谁能不说预言呢？'),
('CUV', '阿摩司书', 30, 3, 9, '要在亚实突的宫殿中和埃及地的宫殿里传扬说：你们要聚集在撒玛利亚的山上，就看见城中有何等大的扰乱与欺压的事。'),
('CUV', '阿摩司书', 30, 3, 10, '那些以强暴抢夺财物、积蓄在自己家中的人不知道行正直的事。这是耶和华说的。'),
('CUV', '阿摩司书', 30, 3, 11, '所以主耶和华如此说：敌人必来围攻这地，使你的势力衰微，抢掠你的家宅。'),
('CUV', '阿摩司书', 30, 3, 12, '耶和华如此说：牧人怎样从狮子口中抢回两条羊腿或半个耳朵，住撒玛利亚的以色列人躺卧在床角上或铺绣花毯的榻上，他们得救也不过如此。'),
('CUV', '阿摩司书', 30, 3, 13, '主耶和华─万军之神说：当听这话，警戒雅各家。'),
('CUV', '阿摩司书', 30, 3, 14, '我讨以色列罪的日子，也要讨伯特利祭坛的罪；坛角必被砍下，坠落于地。'),
('CUV', '阿摩司书', 30, 3, 15, '我要拆毁过冬和过夏的房屋。象牙的房屋也必毁灭；高大的房屋都归无有。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '阿摩司书', 30, 4, 1, '你们住撒玛利亚山如巴珊母牛的啊，当听我的话─你们欺负贫寒的，压碎穷乏的，对家主说：拿酒来，我们喝罢！'),
('CUV', '阿摩司书', 30, 4, 2, '主耶和华指著自己的圣洁起誓说：日子快到，人必用钩子将你们钩去，用鱼钩将你们余剩的钩去。'),
('CUV', '阿摩司书', 30, 4, 3, '你们各人必从破口直往前行，投入哈门。这是耶和华说的。'),
('CUV', '阿摩司书', 30, 4, 4, '以色列人哪，任你们往伯特利去犯罪，到吉甲加增罪过；每日早晨献上你们的祭物，每三日奉上你们的十分之一。'),
('CUV', '阿摩司书', 30, 4, 5, '任你们献有酵的感谢祭，把甘心祭宣传报告给众人，因为是你们所喜爱的。这是主耶和华说的。'),
('CUV', '阿摩司书', 30, 4, 6, '我使你们在一切城中牙齿干净，在你们各处粮食缺乏，你们仍不归向我。这是耶和华说的。'),
('CUV', '阿摩司书', 30, 4, 7, '在收割的前三月，我使雨停止，不降在你们那里；我降雨在这城，不降雨在那城；这块地有雨，那块地无雨；无雨的就枯干了。'),
('CUV', '阿摩司书', 30, 4, 8, '这样，两三城的人凑到一城去找水，却喝不足；你们仍不归向我。这是耶和华说的。'),
('CUV', '阿摩司书', 30, 4, 9, '我以旱风、霉烂攻击你们，你们园中许多菜蔬、葡萄树、无花果树、橄榄树都被剪虫所吃；你们仍不归向我。这是耶和华说的。'),
('CUV', '阿摩司书', 30, 4, 10, '我降瘟疫在你们中间，像在埃及一样；用刀杀戮你们的少年人，使你们的马匹被掳掠，营中尸首的臭气扑鼻；你们仍不归向我。这是耶和华说的。'),
('CUV', '阿摩司书', 30, 4, 11, '我倾覆你们中间的城邑，如同我从前倾覆所多玛、蛾摩拉一样，使你们好像从火中抽出来的一根柴；你们仍不归向我。这是耶和华说的。'),
('CUV', '阿摩司书', 30, 4, 12, '以色列啊，我必向你如此行；以色列啊，我既这样行，你当预备迎见你的神。'),
('CUV', '阿摩司书', 30, 4, 13, '那创山、造风、将心意指示人、使晨光变为幽暗、脚踏在地之高处的，他的名是耶和华─万军之神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '阿摩司书', 30, 5, 1, '以色列家啊，要听我为你们所作的哀歌：'),
('CUV', '阿摩司书', 30, 5, 2, '以色列民（原文是处女）跌倒，不得再起；躺在地上，无人搀扶。'),
('CUV', '阿摩司书', 30, 5, 3, '主耶和华如此说：以色列家的城发出一千兵的，只剩一百；发出一百的，只剩十个。'),
('CUV', '阿摩司书', 30, 5, 4, '耶和华向以色列家如此说：你们要寻求我，就必存活。'),
('CUV', '阿摩司书', 30, 5, 5, '不要往伯特利寻求，不要进入吉甲，不要过到别是巴；因为吉甲必被掳掠，伯特利也必归于无有。'),
('CUV', '阿摩司书', 30, 5, 6, '要寻求耶和华，就必存活，免得他在约瑟家像火发出，在伯特利焚烧，无人扑灭。'),
('CUV', '阿摩司书', 30, 5, 7, '你们这使公平变为茵𫈟、将公义丢弃于地的，'),
('CUV', '阿摩司书', 30, 5, 8, '要寻求那造昴星和参星，使死荫变为晨光，使白日变为黑夜，命海水来浇在地上的─耶和华是他的名；'),
('CUV', '阿摩司书', 30, 5, 9, '他使力强的忽遭灭亡，以致保障遭遇毁坏。'),
('CUV', '阿摩司书', 30, 5, 10, '你们怨恨那在城门口责备人的，憎恶那说正直话的。'),
('CUV', '阿摩司书', 30, 5, 11, '你们践踏贫民，向他们勒索麦子；你们用凿过的石头建造房屋，却不得住在其内；栽种美好的葡萄园，却不得喝所出的酒。'),
('CUV', '阿摩司书', 30, 5, 12, '我知道你们的罪过何等多，你们的罪恶何等大。你们苦待义人，收受贿赂，在城门口屈枉穷乏人。'),
('CUV', '阿摩司书', 30, 5, 13, '所以通达人见这样的时势必静默不言，因为时势真恶。'),
('CUV', '阿摩司书', 30, 5, 14, '你们要求善，不要求恶，就必存活。这样，耶和华─万军之神必照你们所说的与你们同在。'),
('CUV', '阿摩司书', 30, 5, 15, '要恶恶好善，在城门口秉公行义；或者耶和华─万军之神向约瑟的余民施恩。'),
('CUV', '阿摩司书', 30, 5, 16, '主耶和华─万军之神如此说：在一切宽阔处必有哀号的声音；在各街市上必有人说：哀哉！哀哉！又必叫农夫来哭号，叫善唱哀歌的来举哀。'),
('CUV', '阿摩司书', 30, 5, 17, '在各葡萄园必有哀号的声音，因为我必从你中间经过。这是耶和华说的。'),
('CUV', '阿摩司书', 30, 5, 18, '想望耶和华日子来到的有祸了！你们为何想望耶和华的日子呢？那日黑暗没有光明，'),
('CUV', '阿摩司书', 30, 5, 19, '景况好像人躲避狮子又遇见熊，或是进房屋以手靠墙，就被蛇咬。'),
('CUV', '阿摩司书', 30, 5, 20, '耶和华的日子不是黑暗没有光明么？不是幽暗毫无光辉么？'),
('CUV', '阿摩司书', 30, 5, 21, '我厌恶你们的节期，也不喜悦你们的严肃会。'),
('CUV', '阿摩司书', 30, 5, 22, '你们虽然向我献燔祭和素祭，我却不悦纳，也不顾你们用肥畜献的平安祭；'),
('CUV', '阿摩司书', 30, 5, 23, '要使你们歌唱的声音远离我，因为我不听你们弹琴的响声。'),
('CUV', '阿摩司书', 30, 5, 24, '惟愿公平如大水滚滚，使公义如江河滔滔。'),
('CUV', '阿摩司书', 30, 5, 25, '以色列家啊，你们在旷野四十年，岂是将祭物和供物献给我呢？'),
('CUV', '阿摩司书', 30, 5, 26, '你们抬著为自己所造之摩洛的帐幕和偶像的龛，并你们的神星。'),
('CUV', '阿摩司书', 30, 5, 27, '所以我要把你们掳到大马色以外。这是耶和华、名为万军之神说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '阿摩司书', 30, 6, 1, '国为列国之首，人最著名，且为以色列家所归向，在锡安和撒玛利亚山安逸无虑的，有祸了！'),
('CUV', '阿摩司书', 30, 6, 2, '你们要过到甲尼察看，从那里往大城哈马去，又下到非利士人的迦特。看那些比你们的国还强吗？境界比你们的境界还宽吗？'),
('CUV', '阿摩司书', 30, 6, 3, '你们以为降祸的日子还远，坐在位上尽行强暴（或译：行强暴使审判临近）。'),
('CUV', '阿摩司书', 30, 6, 4, '你们躺卧在象牙床上，舒身在榻上，吃群中的羊羔，棚里的牛犊；'),
('CUV', '阿摩司书', 30, 6, 5, '弹琴鼓瑟，唱消闲的歌曲，为自己制造乐器，如同大卫所造的；'),
('CUV', '阿摩司书', 30, 6, 6, '以大碗喝酒，用上等的油抹身，却不为约瑟的苦难担忧。'),
('CUV', '阿摩司书', 30, 6, 7, '所以这些人必在被掳的人中首先被掳，舒身的人荒宴之乐必消灭了。'),
('CUV', '阿摩司书', 30, 6, 8, '主耶和华万军之神指著自己起誓说，我憎恶雅各的荣华，厌弃他的宫殿；因此我必将城和其中所有的都交付敌人。'),
('CUV', '阿摩司书', 30, 6, 9, '那时，若在一房之内剩下十个人，也都必死。'),
('CUV', '阿摩司书', 30, 6, 10, '死人的伯叔，就是烧他尸首的，要将这尸首搬到房外，问房屋内间的人说：你那里还有人没有？他必说：没有；又说：，不要作声，因为我们不可提耶和华的名。'),
('CUV', '阿摩司书', 30, 6, 11, '看哪，耶和华出令，大房就被攻破，小屋就被打裂。'),
('CUV', '阿摩司书', 30, 6, 12, '马岂能在崖石上奔跑？人岂能在那里用牛耕种呢？你们却使公平变为苦胆，使公义的果子变为茵𫈟。'),
('CUV', '阿摩司书', 30, 6, 13, '你们喜爱虚浮的事，自夸说，我们不是凭自己的力量取了角么？'),
('CUV', '阿摩司书', 30, 6, 14, '耶和华万军之神说：，以色列家阿，我必兴起一国攻击你们；他们必欺压你们，从哈马口直到亚拉巴的河。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '阿摩司书', 30, 7, 1, '主耶和华指示我一件事：为王割菜（或译：草）之后，菜又发生；刚发生的时候，主造蝗虫。'),
('CUV', '阿摩司书', 30, 7, 2, '蝗虫吃尽那地的青物，我就说：主耶和华啊，求你赦免；因为雅各微弱，他怎能站立得住呢？'),
('CUV', '阿摩司书', 30, 7, 3, '耶和华就后悔，说：这灾可以免了。'),
('CUV', '阿摩司书', 30, 7, 4, '主耶和华又指示我一件事：他命火来惩罚以色列，火就吞灭深渊，险些将地烧灭。'),
('CUV', '阿摩司书', 30, 7, 5, '我就说：主耶和华啊，求你止息；因为雅各微弱，他怎能站立得住呢？'),
('CUV', '阿摩司书', 30, 7, 6, '耶和华就后悔，说：这灾也可免了。'),
('CUV', '阿摩司书', 30, 7, 7, '他又指示我一件事：有一道墙是按准绳建筑的，主手拿准绳站在其上。'),
('CUV', '阿摩司书', 30, 7, 8, '耶和华对我说：阿摩司啊，你看见甚么？我说：看见准绳。主说：我要吊起准绳在我民以色列中，我必不再宽恕他们。'),
('CUV', '阿摩司书', 30, 7, 9, '以撒的邱坛必然凄凉，以色列的圣所必然荒废。我必兴起，用刀攻击耶罗波安的家。'),
('CUV', '阿摩司书', 30, 7, 10, '伯特利的祭司亚玛谢打发人到以色列王耶罗波安那里，说：阿摩司在以色列家中图谋背叛你；他所说的一切话，这国担当不起；'),
('CUV', '阿摩司书', 30, 7, 11, '因为阿摩司如此说：耶罗波安必被刀杀，以色列民定被掳去离开本地。'),
('CUV', '阿摩司书', 30, 7, 12, '亚玛谢又对阿摩司说：你这先见哪，要逃往犹大地去，在那里糊口，在那里说预言，'),
('CUV', '阿摩司书', 30, 7, 13, '却不要在伯特利再说预言；因为这里有王的圣所，有王的宫殿。'),
('CUV', '阿摩司书', 30, 7, 14, '阿摩司对亚玛谢说：我原不是先知，也不是先知的门徒（原文是儿子）。我是牧人，又是修理桑树的。'),
('CUV', '阿摩司书', 30, 7, 15, '耶和华选召我，使我不跟从羊群，对我说：你去向我民以色列说预言。'),
('CUV', '阿摩司书', 30, 7, 16, '亚玛谢啊，现在你要听耶和华的话。你说：不要向以色列说预言，也不要向以撒家滴下预言。'),
('CUV', '阿摩司书', 30, 7, 17, '所以耶和华如此说：你的妻子必在城中作妓女，你的儿女必倒在刀下；你的地必有人用绳子量了分取，你自己必死在污秽之地。以色列民定被掳去离开本地。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '阿摩司书', 30, 8, 1, '主耶和华又指示我一件事：我看见一筐夏天的果子。'),
('CUV', '阿摩司书', 30, 8, 2, '他说：阿摩司啊，你看见甚么？我说：看见一筐夏天的果子。耶和华说：我民以色列的结局到了，我必不再宽恕他们。'),
('CUV', '阿摩司书', 30, 8, 3, '主耶和华说：那日，殿中的诗歌变为哀号；必有许多尸首在各处抛弃，无人作声。'),
('CUV', '阿摩司书', 30, 8, 4, '你们这些要吞吃穷乏人、使困苦人衰败的，当听我的话！'),
('CUV', '阿摩司书', 30, 8, 5, '你们说：月朔几时过去，我们好卖粮；安息日几时过去，我们好摆开麦子；卖出用小升斗，收银用大戥子，用诡诈的天平欺哄人，'),
('CUV', '阿摩司书', 30, 8, 6, '好用银子买贫寒人，用一双鞋换穷乏人，将坏了的麦子卖给人。'),
('CUV', '阿摩司书', 30, 8, 7, '耶和华指著雅各的荣耀起誓说：他们的一切行为，我必永远不忘。'),
('CUV', '阿摩司书', 30, 8, 8, '地岂不因这事震动？其上的居民不也悲哀吗？地必全然像尼罗河涨起，如同埃及河涌上落下。'),
('CUV', '阿摩司书', 30, 8, 9, '主耶和华说：到那日，我必使日头在午间落下，使地在白昼黑暗。'),
('CUV', '阿摩司书', 30, 8, 10, '我必使你们的节期变为悲哀，歌曲变为哀歌。众人腰束麻布，头上光秃，使这场悲哀如丧独生子，至终如痛苦的日子一样。'),
('CUV', '阿摩司书', 30, 8, 11, '主耶和华说：日子将到，我必命饥荒降在地上。人饥饿非因无饼，干渴非因无水，乃因不听耶和华的话。'),
('CUV', '阿摩司书', 30, 8, 12, '他们必飘流，从这海到那海，从北边到东边，往来奔跑，寻求耶和华的话，却寻不著。'),
('CUV', '阿摩司书', 30, 8, 13, '当那日，美貌的处女和少年的男子必因干渴发昏。'),
('CUV', '阿摩司书', 30, 8, 14, '那指著撒玛利亚牛犊（原文是罪）起誓的说：但哪，我们指著你那里的活神起誓；又说：我们指著别是巴的神道（神：原文是活）起誓。这些人都必仆倒，永不再起来。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '阿摩司书', 30, 9, 1, '我看见主站在祭坛旁边；他说：你要击打柱顶，使门槛震动，打碎柱顶，落在众人头上；所剩下的人，我必用刀杀戮，无一人能逃避，无一人能逃脱。'),
('CUV', '阿摩司书', 30, 9, 2, '他们虽然挖透阴间，我的手必取出他们来；虽然爬上天去，我必拿下他们来；'),
('CUV', '阿摩司书', 30, 9, 3, '虽然藏在迦密山顶，我必搜寻，捉出他们来；虽然从我眼前藏在海底，我必命蛇咬他们；'),
('CUV', '阿摩司书', 30, 9, 4, '虽被仇敌掳去，我必命刀剑杀戮他们；我必向他们定住眼目，降祸不降福。'),
('CUV', '阿摩司书', 30, 9, 5, '主─万军之耶和华摸地，地就消化，凡住在地上的都必悲哀。地必全然像尼罗河涨起，如同埃及河落下。'),
('CUV', '阿摩司书', 30, 9, 6, '那在天上建造楼阁、在地上安定穹苍、命海水浇在地上的─耶和华是他的名。'),
('CUV', '阿摩司书', 30, 9, 7, '耶和华说：以色列人哪，我岂不看你们如古实人吗？我岂不是领以色列人出埃及地，领非利士人出迦斐托，领亚兰人出吉珥吗？'),
('CUV', '阿摩司书', 30, 9, 8, '主耶和华的眼目察看这有罪的国，必将这国从地上灭绝，却不将雅各家灭绝净尽。这是耶和华说的。'),
('CUV', '阿摩司书', 30, 9, 9, '我必出令，将以色列家分散在列国中，好像用筛子筛谷，连一粒也不落在地上。'),
('CUV', '阿摩司书', 30, 9, 10, '我民中的一切罪人说：灾祸必追不上我们，也迎不著我们。他们必死在刀下。'),
('CUV', '阿摩司书', 30, 9, 11, '到那日，我必建立大卫倒塌的帐幕，堵住其中的破口，把那破坏的建立起来，重新修造，像古时一样，'),
('CUV', '阿摩司书', 30, 9, 12, '使以色列人得以东所余剩的和所有称为我名下的国。此乃行这事的耶和华说的。'),
('CUV', '阿摩司书', 30, 9, 13, '耶和华说：日子将到，耕种的必接续收割的；踹葡萄的必接续撒种的；大山要滴下甜酒；小山都必流奶（原文是消化，见约珥三章十八节）。'),
('CUV', '阿摩司书', 30, 9, 14, '我必使我民以色列被掳的归回；他们必重修荒废的城邑居住，栽种葡萄园，喝其中所出的酒，修造果木园，吃其中的果子。'),
('CUV', '阿摩司书', 30, 9, 15, '我要将他们栽于本地，他们不再从我所赐给他们的地上拔出来。这是耶和华─你的神说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '俄巴底亚书', 31, 1, 1, '俄巴底亚得了耶和华的默示。论以东说：我从耶和华那里听见信息，并有使者被差往列国去，说：起来罢，一同起来与以东争战！'),
('CUV', '俄巴底亚书', 31, 1, 2, '我使你─以东在列国中为最小的，被人大大藐视。'),
('CUV', '俄巴底亚书', 31, 1, 3, '住在山穴中、居所在高处的啊，你因狂傲自欺，心里说：谁能将我拉下地去呢？'),
('CUV', '俄巴底亚书', 31, 1, 4, '你虽如大鹰高飞，在星宿之间搭窝，我必从那里拉下你来。这是耶和华说的。'),
('CUV', '俄巴底亚书', 31, 1, 5, '盗贼若来在你那里，或强盗夜间而来─你何竟被剪除─岂不偷窃直到够了呢？摘葡萄的若来到你那里，岂不剩下些葡萄呢？'),
('CUV', '俄巴底亚书', 31, 1, 6, '以扫的隐密处何竟被搜寻？他隐藏的宝物何竟被查出？'),
('CUV', '俄巴底亚书', 31, 1, 7, '与你结盟的都送你上路，直到交界；与你和好的欺骗你，且胜过你；与你一同吃饭的设下网罗陷害你；在你心里毫无聪明。'),
('CUV', '俄巴底亚书', 31, 1, 8, '耶和华说：到那日，我岂不从以东除灭智慧人？从以扫山除灭聪明人？'),
('CUV', '俄巴底亚书', 31, 1, 9, '提幔哪，你的勇士必惊惶，甚至以扫山的人都被杀戮剪除。'),
('CUV', '俄巴底亚书', 31, 1, 10, '因你向兄弟雅各行强暴，羞愧必遮盖你，你也必永远断绝。'),
('CUV', '俄巴底亚书', 31, 1, 11, '当外人掳掠雅各的财物，外邦人进入他的城门，为耶路撒冷拈阄的日子，你竟站在一旁，像与他们同伙。'),
('CUV', '俄巴底亚书', 31, 1, 12, '你兄弟遭难的日子，你不当瞪眼看著；犹大人被灭的日子，你不当因此欢乐；他们遭难的日子，你不当说狂傲的话。'),
('CUV', '俄巴底亚书', 31, 1, 13, '我民遭灾的日子，你不当进他们的城门；他们遭灾的日子，你不当瞪眼看著他们受苦；他们遭灾的日子，你不当伸手抢他们的财物；'),
('CUV', '俄巴底亚书', 31, 1, 14, '你不当站在岔路口剪除他们中间逃脱的；他们遭难的日子，你不当将他们剩下的人交付仇敌。'),
('CUV', '俄巴底亚书', 31, 1, 15, '耶和华降罚的日子临近万国。你怎样行，他也必照样向你行；你的报应必归到你头上。'),
('CUV', '俄巴底亚书', 31, 1, 16, '你们犹大人在我圣山怎样喝了苦杯，万国也必照样常常地喝；且喝且咽，他们就归于无有。'),
('CUV', '俄巴底亚书', 31, 1, 17, '在锡安山必有逃脱的人，那山也必成圣；雅各家必得原有的产业。'),
('CUV', '俄巴底亚书', 31, 1, 18, '雅各家必成为大火；约瑟家必为火燄；以扫家必如碎秸；火必将他烧著吞灭。以扫家必无余剩的。这是耶和华说的。'),
('CUV', '俄巴底亚书', 31, 1, 19, '南地的人必得以扫山；高原的人必得非利士地，也得以法莲地和撒玛利亚地；便雅悯人必得基列。'),
('CUV', '俄巴底亚书', 31, 1, 20, '在迦南人中被掳的以色列众人必得地直到撒勒法；在西法拉中被掳的耶路撒冷人必得南地的城邑。'),
('CUV', '俄巴底亚书', 31, 1, 21, '必有拯救者上到锡安山，审判以扫山；国度就归耶和华了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约拿书', 32, 1, 1, '耶和华的话临到亚米太的儿子约拿，说：'),
('CUV', '约拿书', 32, 1, 2, '你起来往尼尼微大城去，向其中的居民呼喊，因为他们的恶达到我面前。'),
('CUV', '约拿书', 32, 1, 3, '约拿却起来，逃往他施去躲避耶和华；下到约帕，遇见一只船，要往他施去。他就给了船价，上了船，要与船上的人同往他施去躲避耶和华。'),
('CUV', '约拿书', 32, 1, 4, '然而耶和华使海中起大风，海就狂风大作，甚至船几乎破坏。'),
('CUV', '约拿书', 32, 1, 5, '水手便惧怕，各人哀求自己的神。他们将船上的货物抛在海中，为要使船轻些。约拿已下到底舱，躺卧沉睡。'),
('CUV', '约拿书', 32, 1, 6, '船主到他那里对他说：你这沉睡的人哪，为何这样呢？起来，求告你的神，或者神顾念我们，使我们不致灭亡。'),
('CUV', '约拿书', 32, 1, 7, '船上的人彼此说：来吧，我们掣签，看看这灾临到我们是因谁的缘故。于是他们掣签，掣出约拿来。'),
('CUV', '约拿书', 32, 1, 8, '众人对他说：请你告诉我们，这灾临到我们是因谁的缘故？你以何事为业？你从哪里来？你是哪一国？属哪一族的人？'),
('CUV', '约拿书', 32, 1, 9, '他说：我是希伯来人。我敬畏耶和华─那创造沧海旱地之天上的神。'),
('CUV', '约拿书', 32, 1, 10, '他们就大大惧怕，对他说：你做的是甚么事呢？他们已经知道他躲避耶和华，因为他告诉了他们。'),
('CUV', '约拿书', 32, 1, 11, '他们问他说：我们当向你怎样行，使海浪平静呢？这话是因海浪越发翻腾。'),
('CUV', '约拿书', 32, 1, 12, '他对他们说：你们将我抬起来，抛在海中，海就平静了；我知道你们遭这大风是因我的缘故。'),
('CUV', '约拿书', 32, 1, 13, '然而那些人竭力荡桨，要把船拢岸，却是不能，因为海浪越发向他们翻腾。'),
('CUV', '约拿书', 32, 1, 14, '他们便求告耶和华说：耶和华啊，我们恳求你，不要因这人的性命使我们死亡，不要使流无辜血的罪归与我们；因为你─耶和华是随自己的意旨行事。'),
('CUV', '约拿书', 32, 1, 15, '他们遂将约拿抬起，抛在海中，海的狂浪就平息了。'),
('CUV', '约拿书', 32, 1, 16, '那些人便大大敬畏耶和华，向耶和华献祭，并且许愿。'),
('CUV', '约拿书', 32, 1, 17, '耶和华安排一条大鱼吞了约拿，他在鱼腹中三日三夜。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约拿书', 32, 2, 1, '约拿在鱼腹中祷告耶和华─他的神，'),
('CUV', '约拿书', 32, 2, 2, '说：我遭遇患难求告耶和华，你就应允我；从阴间的深处呼求，你就俯听我的声音。'),
('CUV', '约拿书', 32, 2, 3, '你将我投下深渊，就是海的深处；大水环绕我，你的波浪洪涛都漫过我身。'),
('CUV', '约拿书', 32, 2, 4, '我说：我从你眼前虽被驱逐，我仍要仰望你的圣殿。'),
('CUV', '约拿书', 32, 2, 5, '诸水环绕我，几乎淹没我；深渊围住我；海草缠绕我的头。'),
('CUV', '约拿书', 32, 2, 6, '我下到山根，地的门将我永远关住。耶和华─我的神啊，你却将我的性命从坑中救出来。'),
('CUV', '约拿书', 32, 2, 7, '我心在我里面发昏的时候，我就想念耶和华。我的祷告进入你的圣殿，达到你的面前。'),
('CUV', '约拿书', 32, 2, 8, '那信奉虚无之神的人，离弃怜爱他们的主；'),
('CUV', '约拿书', 32, 2, 9, '但我必用感谢的声音献祭与你。我所许的愿，我必偿还。救恩出于耶和华。'),
('CUV', '约拿书', 32, 2, 10, '耶和华吩咐鱼，鱼就把约拿吐在旱地上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约拿书', 32, 3, 1, '耶和华的话二次临到约拿说：'),
('CUV', '约拿书', 32, 3, 2, '你起来！往尼尼微大城去，向其中的居民宣告我所吩咐你的话。'),
('CUV', '约拿书', 32, 3, 3, '约拿便照耶和华的话起来，往尼尼微去。这尼尼微是极大的城，有三日的路程。'),
('CUV', '约拿书', 32, 3, 4, '约拿进城走了一日，宣告说：再等四十日，尼尼微必倾覆了！'),
('CUV', '约拿书', 32, 3, 5, '尼尼微人信服神，便宣告禁食，从最大的到至小的都穿麻衣（或译：披上麻布）。'),
('CUV', '约拿书', 32, 3, 6, '这信息传到尼尼微王的耳中，他就下了宝座，脱下朝服，披上麻布，坐在灰中。'),
('CUV', '约拿书', 32, 3, 7, '他又使人遍告尼尼微通城，说：王和大臣有令，人不可尝甚么，牲畜、牛羊不可吃草，也不可喝水。'),
('CUV', '约拿书', 32, 3, 8, '人与牲畜都当披上麻布；人要切切求告神。各人回头离开所行的恶道，丢弃手中的强暴。'),
('CUV', '约拿书', 32, 3, 9, '或者神转意后悔，不发烈怒，使我们不致灭亡，也未可知。'),
('CUV', '约拿书', 32, 3, 10, '于是神察看他们的行为，见他们离开恶道，他就后悔，不把所说的灾祸降与他们了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约拿书', 32, 4, 1, '这事约拿大大不悦，且甚发怒，'),
('CUV', '约拿书', 32, 4, 2, '就祷告耶和华说：耶和华啊，我在本国的时候，岂不是这样说吗？我知道你是有恩典、有怜悯的神，不轻易发怒，有丰盛的慈爱，并且后悔不降所说的灾，所以我急速逃往他施去。'),
('CUV', '约拿书', 32, 4, 3, '耶和华啊，现在求你取我的命吧！因为我死了比活著还好。'),
('CUV', '约拿书', 32, 4, 4, '耶和华说：你这样发怒合乎理吗？'),
('CUV', '约拿书', 32, 4, 5, '于是约拿出城，坐在城的东边，在那里为自己搭了一座棚，坐在棚的荫下，要看看那城究竟如何。'),
('CUV', '约拿书', 32, 4, 6, '耶和华神安排一棵蓖麻，使其发生高过约拿，影儿遮盖他的头，救他脱离苦楚；约拿因这棵蓖麻大大喜乐。'),
('CUV', '约拿书', 32, 4, 7, '次日黎明，神却安排一条虫子咬这蓖麻，以致枯槁。'),
('CUV', '约拿书', 32, 4, 8, '日头出来的时候，神安排炎热的东风，日头曝晒约拿的头，使他发昏，他就为自己求死，说：我死了比活著还好！'),
('CUV', '约拿书', 32, 4, 9, '神对约拿说：你因这棵蓖麻发怒合乎理吗？他说：我发怒以至于死，都合乎理！'),
('CUV', '约拿书', 32, 4, 10, '耶和华说：这蓖麻，不是你栽种的，也不是你培养的；一夜发生，一夜干死，你尚且爱惜；'),
('CUV', '约拿书', 32, 4, 11, '何况这尼尼微大城，其中不能分辨左手右手的有十二万多人，并有许多牲畜，我岂能不爱惜呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '弥迦书', 33, 1, 1, '当犹大王约坦、亚哈斯、希西家在位的时候，摩利沙人弥迦得耶和华的默示，论撒玛利亚和耶路撒冷。'),
('CUV', '弥迦书', 33, 1, 2, '万民哪，你们都要听！地和其上所有的，也都要侧耳而听！主耶和华从他的圣殿要见证你们的不是。'),
('CUV', '弥迦书', 33, 1, 3, '看哪，耶和华出了他的居所，降临步行地的高处。'),
('CUV', '弥迦书', 33, 1, 4, '众山在他以下必消化，诸谷必崩裂，如蜡化在火中，如水冲下山坡。'),
('CUV', '弥迦书', 33, 1, 5, '这都因雅各的罪过，以色列家的罪恶。雅各的罪过在哪里呢？岂不是在撒玛利亚么？犹大的邱坛在哪里呢？岂不是在耶路撒冷么？'),
('CUV', '弥迦书', 33, 1, 6, '所以我必使撒玛利亚变为田野的乱堆，又作为种葡萄之处；也必将她的石头倒在谷中，露出根基来。'),
('CUV', '弥迦书', 33, 1, 7, '她一切雕刻的偶像必被打碎；她所得的财物必被火烧；所有的偶像我必毁灭；因为是从妓女雇价所聚来的，后必归为妓女的雇价。'),
('CUV', '弥迦书', 33, 1, 8, '先知说：因此我必大声哀号，赤脚露体而行；又要呼号如野狗，哀鸣如鸵鸟。'),
('CUV', '弥迦书', 33, 1, 9, '因为撒玛利亚的伤痕无法医治，延及犹大和耶路撒冷我民的城门。'),
('CUV', '弥迦书', 33, 1, 10, '不要在迦特报告这事，总不要哭泣；我在伯亚弗拉滚于灰尘之中。'),
('CUV', '弥迦书', 33, 1, 11, '沙斐的居民哪，你们要赤身蒙羞过去。撒南的居民不敢出来。伯以薛人的哀哭使你们无处可站。'),
('CUV', '弥迦书', 33, 1, 12, '玛律的居民心甚忧急，切望得好处，因为灾祸从耶和华那里临到耶路撒冷的城门。'),
('CUV', '弥迦书', 33, 1, 13, '拉吉的居民哪，要用快马套车；锡安民（原文是女子）的罪由你而起；以色列人的罪过在你那里显出。'),
('CUV', '弥迦书', 33, 1, 14, '犹大啊，你要将礼物送给摩利设迦特。亚革悉的众族必用诡诈待以色列诸王。'),
('CUV', '弥迦书', 33, 1, 15, '玛利沙的居民哪，我必使那夺取你的来到你这里；以色列的尊贵人（原文是荣耀）必到亚杜兰。'),
('CUV', '弥迦书', 33, 1, 16, '犹大啊，要为你所喜爱的儿女剪除你的头发，使头光秃，要大大地光秃，如同秃鹰，因为他们都被掳去离开你。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '弥迦书', 33, 2, 1, '祸哉，那些在床上图谋罪孽、造作奸恶的！天一发亮，因手有能力就行出来了。'),
('CUV', '弥迦书', 33, 2, 2, '他们贪图田地就占据，贪图房屋便夺取；他们欺压人，霸占房屋和产业。'),
('CUV', '弥迦书', 33, 2, 3, '所以耶和华如此说：我筹划灾祸降与这族；这祸在你们的颈项上不能解脱；你们也不能昂首而行，因为这时势是恶的。'),
('CUV', '弥迦书', 33, 2, 4, '到那日，必有人向你们提起悲惨的哀歌，讥刺说：我们全然败落了！耶和华将我们的分转归别人，何竟使这分离开我们？他将我们的田地分给悖逆的人。'),
('CUV', '弥迦书', 33, 2, 5, '所以在耶和华的会中，你必没有人拈阄拉准绳。'),
('CUV', '弥迦书', 33, 2, 6, '他们（或译：假先知）说：你们不可说预言；不可向这些人说预言，不住地羞辱我们。'),
('CUV', '弥迦书', 33, 2, 7, '雅各家啊，岂可说耶和华的心不忍耐么（或译：心肠狭窄么）？这些事是他所行的么？我─耶和华的言语岂不是与行动正直的人有益么？'),
('CUV', '弥迦书', 33, 2, 8, '然而，近来我的民兴起如仇敌，从那些安然经过不愿打仗之人身上剥去外衣。'),
('CUV', '弥迦书', 33, 2, 9, '你们将我民中的妇人从安乐家中赶出，又将我的荣耀从她们的小孩子尽行夺去。'),
('CUV', '弥迦书', 33, 2, 10, '你们起来去罢！这不是你们安息之所；因为污秽使人（或译：地）毁灭，而且大大毁灭。'),
('CUV', '弥迦书', 33, 2, 11, '若有人心存虚假，用谎言说：我要向你们预言得清酒和浓酒。那人就必作这民的先知。'),
('CUV', '弥迦书', 33, 2, 12, '雅各家啊，我必要聚集你们，必要招聚以色列剩下的人，安置在一处，如波斯拉的羊，又如草场上的羊群；因为人数众多就必大大喧哗。'),
('CUV', '弥迦书', 33, 2, 13, '开路的（或译：破城的）在他们前面上去；他们直闯过城门，从城门出去。他们的王在前面行；耶和华引导他们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '弥迦书', 33, 3, 1, '我说：雅各的首领，以色列家的官长啊，你们要听！你们不当知道公平么？'),
('CUV', '弥迦书', 33, 3, 2, '你们恶善好恶，从人身上剥皮，从人骨头上剔肉，'),
('CUV', '弥迦书', 33, 3, 3, '吃我民的肉，剥他们的皮，打折他们的骨头，分成块子像要下锅，又像釜中的肉。'),
('CUV', '弥迦书', 33, 3, 4, '到了遭灾的时候，这些人必哀求耶和华，他却不应允他们。那时他必照他们所行的恶事向他们掩面。'),
('CUV', '弥迦书', 33, 3, 5, '论到使我民走差路的先知─他们牙齿有所嚼的，他们就呼喊说：平安了！凡不供给他们吃的，他们就预备攻击他（预备攻击他：或译说必遭遇刀兵）─耶和华如此说：'),
('CUV', '弥迦书', 33, 3, 6, '你们必遭遇黑夜，以致不见异象；又必遭遇幽暗，以致不能占卜。日头必向你们沉落，白昼变为黑暗。'),
('CUV', '弥迦书', 33, 3, 7, '先见必抱愧，占卜的必蒙羞，都必摀著嘴唇，因为神不应允他们。'),
('CUV', '弥迦书', 33, 3, 8, '至于我，我藉耶和华的灵，满有力量、公平、才能，可以向雅各说明他的过犯，向以色列指出他的罪恶。'),
('CUV', '弥迦书', 33, 3, 9, '雅各家的首领、以色列家的官长啊，当听我的话！你们厌恶公平，在一切事上屈枉正直；'),
('CUV', '弥迦书', 33, 3, 10, '以人血建立锡安，以罪孽建造耶路撒冷。'),
('CUV', '弥迦书', 33, 3, 11, '首领为贿赂行审判；祭司为雇价施训诲；先知为银钱行占卜。他们却倚赖耶和华，说：耶和华不是在我们中间么？灾祸必不临到我们。'),
('CUV', '弥迦书', 33, 3, 12, '所以因你们的缘故，锡安必被耕种像一块田，耶路撒冷必变为乱堆；这殿的山必像丛林的高处。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '弥迦书', 33, 4, 1, '末后的日子，耶和华殿的山必坚立，超乎诸山，高举过于万岭；万民都要流归这山。'),
('CUV', '弥迦书', 33, 4, 2, '必有许多国的民前往，说：来吧，我们登耶和华的山，奔雅各神的殿。主必将他的道教训我们；我们也要行他的路。因为训诲必出于锡安；耶和华的言语必出于耶路撒冷。'),
('CUV', '弥迦书', 33, 4, 3, '他必在多国的民中施行审判，为远方强盛的国断定是非。他们要将刀打成犁头，把枪打成镰刀。这国不举刀攻击那国；他们也不再学习战事。'),
('CUV', '弥迦书', 33, 4, 4, '人人都要坐在自己葡萄树下和无花果树下，无人惊吓。这是万军之耶和华亲口说的。'),
('CUV', '弥迦书', 33, 4, 5, '万民各奉己神的名而行；我们却永永远远奉耶和华─我们神的名而行。'),
('CUV', '弥迦书', 33, 4, 6, '耶和华说：到那日，我必聚集瘸腿的，招聚被赶出的和我所惩治的。'),
('CUV', '弥迦书', 33, 4, 7, '我必使瘸腿的为余剩之民，使赶到远方的为强盛之民。耶和华要在锡安山作王治理他们，从今直到永远。'),
('CUV', '弥迦书', 33, 4, 8, '你这羊群的高台、锡安城（原文是女子）的山哪，，从前的权柄─就是耶路撒冷民（原文是女子）的国权─必归与你。'),
('CUV', '弥迦书', 33, 4, 9, '现在你为何大声哭号呢？疼痛抓住你仿佛产难的妇人，是因你中间没有君王么？你的谋士灭亡了么？'),
('CUV', '弥迦书', 33, 4, 10, '锡安的民（原文是女子）哪，你要疼痛劬劳，仿佛产难的妇人；因为你必从城里出来，住在田野，到巴比伦去。在那里要蒙解救；在那里耶和华必救赎你脱离仇敌的手。'),
('CUV', '弥迦书', 33, 4, 11, '现在有许多国的民聚集攻击你，说：愿锡安被玷污！愿我们亲眼见他遭报！'),
('CUV', '弥迦书', 33, 4, 12, '他们却不知道耶和华的意念，也不明白他的筹划。他聚集他们，好像把禾捆聚到禾场一样。'),
('CUV', '弥迦书', 33, 4, 13, '锡安的民（原文作女子）哪，起来踹谷罢！我必使你的角成为铁，使你的蹄成为铜。你必打碎多国的民，将他们的财献与耶和华，将他们的货献与普天下的主。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '弥迦书', 33, 5, 1, '成群的民（原文是女子）哪，现在你要聚集成队；因为仇敌围攻我们，要用杖击打以色列审判者的脸。'),
('CUV', '弥迦书', 33, 5, 2, '伯利恒、以法他啊，你在犹大诸城中为小，将来必有一位从你那里出来，在以色列中为我作掌权的；他的根源从亘古，从太初就有。'),
('CUV', '弥迦书', 33, 5, 3, '耶和华必将以色列人交付敌人，直等那生产的妇人生下子来。那时掌权者（原文是他）其余的弟兄必归到以色列人那里。'),
('CUV', '弥迦书', 33, 5, 4, '他必起来，倚靠耶和华的大能，并耶和华─他神之名的威严，牧养他的羊群。他们要安然居住；因为他必日见尊大，直到地极。'),
('CUV', '弥迦书', 33, 5, 5, '这位必作我们的平安。当亚述人进入我们的地境，践踏宫殿的时候，我们就立起七个牧者，八个首领攻击他。'),
('CUV', '弥迦书', 33, 5, 6, '他们必用刀剑毁坏亚述地和宁录地的关口。亚述人进入我们的地境践踏的时候，他必拯救我们。'),
('CUV', '弥迦书', 33, 5, 7, '雅各余剩的人必在多国的民中，如从耶和华那里降下的露水，又如甘霖降在草上；不仗赖人力，也不等候世人之功。'),
('CUV', '弥迦书', 33, 5, 8, '雅各余剩的人必在多国多民中，如林间百兽中的狮子，又如少壮狮子在羊群中。他若经过就必践踏撕裂，无人搭救。'),
('CUV', '弥迦书', 33, 5, 9, '愿你的手举起，高过敌人！愿你的仇敌都被剪除！'),
('CUV', '弥迦书', 33, 5, 10, '耶和华说：到那日，我必从你中间剪除马匹，毁坏车辆，'),
('CUV', '弥迦书', 33, 5, 11, '也必从你国中除灭城邑，拆毁一切的保障，'),
('CUV', '弥迦书', 33, 5, 12, '又必除掉你手中的邪术；你那里也不再有占卜的。'),
('CUV', '弥迦书', 33, 5, 13, '我必从你中间除灭雕刻的偶像和柱像，你就不再跪拜自己手所造的。'),
('CUV', '弥迦书', 33, 5, 14, '我必从你中间拔出木偶，又毁灭你的城邑。'),
('CUV', '弥迦书', 33, 5, 15, '我也必在怒气和忿怒中向那不听从的列国施报。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '弥迦书', 33, 6, 1, '以色列人哪，当听耶和华的话！要起来向山岭争辩，使冈陵听你的话。'),
('CUV', '弥迦书', 33, 6, 2, '山岭和地永久的根基啊，要听耶和华争辩的话！因为耶和华要与他的百姓争辩，与以色列争论。'),
('CUV', '弥迦书', 33, 6, 3, '我的百姓啊，我向你做了甚么呢？我在甚么事上使你厌烦？你可以对我证明。'),
('CUV', '弥迦书', 33, 6, 4, '我曾将你从埃及地领出来，从作奴仆之家救赎你；我也差遣摩西、亚伦，和米利暗在你前面行。'),
('CUV', '弥迦书', 33, 6, 5, '我的百姓啊，你们当追念摩押王巴勒所设的谋和比珥的儿子巴兰回答他的话，并你们从什亭到吉甲所遇见的事，好使你们知道耶和华公义的作为。'),
('CUV', '弥迦书', 33, 6, 6, '我朝见耶和华，在至高神面前跪拜，当献上甚么呢？岂可献一岁的牛犊为燔祭么？'),
('CUV', '弥迦书', 33, 6, 7, '耶和华岂喜悦千千的公羊，或是万万的油河么？我岂可为自己的罪过献我的长子么？为心中的罪恶献我身所生的么？'),
('CUV', '弥迦书', 33, 6, 8, '世人哪，耶和华已指示你何为善。他向你所要的是甚么呢？只要你行公义，好怜悯，存谦卑的心，与你的神同行。'),
('CUV', '弥迦书', 33, 6, 9, '耶和华向这城呼叫，智慧人必敬畏他的名。你们当听是谁派定刑杖的惩罚。'),
('CUV', '弥迦书', 33, 6, 10, '恶人家中不仍有非义之财和可恶的小升斗么？'),
('CUV', '弥迦书', 33, 6, 11, '我若用不公道的天平和囊中诡诈的法码，岂可算为清洁呢？'),
('CUV', '弥迦书', 33, 6, 12, '城里的富户满行强暴；其中的居民也说谎言，口中的舌头是诡诈的。'),
('CUV', '弥迦书', 33, 6, 13, '因此，我击打你，使你的伤痕甚重，使你因你的罪恶荒凉。'),
('CUV', '弥迦书', 33, 6, 14, '你要吃，却吃不饱；你的虚弱必显在你中间。你必挪去，却不得救护；所救护的，我必交给刀剑。'),
('CUV', '弥迦书', 33, 6, 15, '你必撒种，却不得收割；踹橄榄，却不得油抹身；踹葡萄，却不得酒喝。'),
('CUV', '弥迦书', 33, 6, 16, '因为你守暗利的恶规，行亚哈家一切所行的，顺从他们的计谋；因此，我必使你荒凉，使你的居民令人嗤笑，你们也必担当我民的羞辱。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '弥迦书', 33, 7, 1, '哀哉！我（或译：以色列）好像夏天的果子已被收尽，又像摘了葡萄所剩下的，没有一挂可吃的；我心羡慕初熟的无花果。'),
('CUV', '弥迦书', 33, 7, 2, '地上虔诚人灭尽；世间没有正直人；各人埋伏，要杀人流血，都用网罗猎取弟兄。'),
('CUV', '弥迦书', 33, 7, 3, '他们双手作恶；君王徇情面，审判官要贿赂；位分大的吐出恶意，都彼此结联行恶。'),
('CUV', '弥迦书', 33, 7, 4, '他们最好的，不过是蒺藜；最正直的，不过是荆棘篱笆。你守望者说，降罚的日子已经来到。他们必扰乱不安。'),
('CUV', '弥迦书', 33, 7, 5, '不要倚赖邻舍；不要信靠密友。要守住你的口；不要向你怀中的妻提说。'),
('CUV', '弥迦书', 33, 7, 6, '因为，儿子藐视父亲；女儿抗拒母亲；媳妇抗拒婆婆；人的仇敌就是自己家里的人。'),
('CUV', '弥迦书', 33, 7, 7, '至于我，我要仰望耶和华，要等候那救我的神；我的神必应允我。'),
('CUV', '弥迦书', 33, 7, 8, '我的仇敌啊，不要向我夸耀。我虽跌倒，却要起来；我虽坐在黑暗里，耶和华却作我的光。'),
('CUV', '弥迦书', 33, 7, 9, '我要忍受耶和华的恼怒；因我得罪了他，直等他为我辨屈，为我伸冤。他必领我到光明中；我必得见他的公义。'),
('CUV', '弥迦书', 33, 7, 10, '那时我的仇敌，就是曾对我说耶和华─你神在哪里的，他一看见这事就被羞愧遮盖。我必亲眼见他遭报；他必被践踏，如同街上的泥土。'),
('CUV', '弥迦书', 33, 7, 11, '以色列啊，日子必到，你的墙垣必重修；到那日，你的境界必开展（或译：命令必传到远方）。'),
('CUV', '弥迦书', 33, 7, 12, '当那日，人必从亚述，从埃及的城邑，从埃及到大河，从这海到那海，从这山到那山，都归到你这里。'),
('CUV', '弥迦书', 33, 7, 13, '然而，这地因居民的缘故，又因他们行事的结果，必然荒凉。'),
('CUV', '弥迦书', 33, 7, 14, '求耶和华在迦密山的树林中，用你的杖牧放你独居的民，就是你产业的羊群。求你容他们在巴珊和基列得食物，像古时一样。'),
('CUV', '弥迦书', 33, 7, 15, '耶和华说：我要把奇事显给他们看，好像出埃及地的时候一样。'),
('CUV', '弥迦书', 33, 7, 16, '列国看见这事，就必为自己的势力惭愧；他们必用手摀口，掩耳不听。'),
('CUV', '弥迦书', 33, 7, 17, '他们必舔土如蛇，又如土中腹行的物，战战兢兢地出他们的营寨。他们必战惧投降耶和华，也必因我们的神而惧怕。'),
('CUV', '弥迦书', 33, 7, 18, '神啊，有何神像你，赦免罪孽，饶恕你产业之余民的罪过，不永远怀怒，喜爱施恩？'),
('CUV', '弥迦书', 33, 7, 19, '必再怜悯我们，将我们的罪孽踏在脚下，又将我们的一切罪投于深海。'),
('CUV', '弥迦书', 33, 7, 20, '你必按古时起誓应许我们列祖的话，向雅各发诚实，向亚伯拉罕施慈爱。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '那鸿书', 34, 1, 1, '论尼尼微的默示，就是伊勒歌斯人那鸿所得的默示。'),
('CUV', '那鸿书', 34, 1, 2, '耶和华是忌邪施报的神。耶和华施报大有忿怒；向他的敌人施报，向他的仇敌怀怒。'),
('CUV', '那鸿书', 34, 1, 3, '耶和华不轻易发怒，大有能力，万不以有罪的为无罪。他乘旋风和暴风而来，云彩为他脚下的尘土。'),
('CUV', '那鸿书', 34, 1, 4, '他斥责海，使海干了，使一切江河干涸。巴珊和迦密的树林衰残；利巴嫩的花草也衰残了。'),
('CUV', '那鸿书', 34, 1, 5, '大山因他震动；小山也都消化。大地在他面前突起；世界和住在其间的也都如此。'),
('CUV', '那鸿书', 34, 1, 6, '他发忿恨，谁能立得住呢？他发烈怒，谁能当得起呢？他的忿怒如火倾倒；磐石因他崩裂。'),
('CUV', '那鸿书', 34, 1, 7, '耶和华本为善，在患难的日子为人的保障，并且认得那些投靠他的人。'),
('CUV', '那鸿书', 34, 1, 8, '但他必以涨溢的洪水淹没尼尼微，又驱逐仇敌进入黑暗。'),
('CUV', '那鸿书', 34, 1, 9, '尼尼微人哪，设何谋攻击耶和华呢？他必将你们灭绝净尽；灾难不再兴起。'),
('CUV', '那鸿书', 34, 1, 10, '你们像丛杂的荆棘，像喝醉了的人，又如枯干的碎秸全然烧灭。'),
('CUV', '那鸿书', 34, 1, 11, '有一人从你那里出来，图谋邪恶，设恶计攻击耶和华。'),
('CUV', '那鸿书', 34, 1, 12, '耶和华如此说：尼尼微虽然势力充足，人数繁多，也被剪除，归于无有。犹大啊，我虽然使你受苦，却不再使你受苦。'),
('CUV', '那鸿书', 34, 1, 13, '现在我必从你颈项上折断他的轭，扭开他的绳索。'),
('CUV', '那鸿书', 34, 1, 14, '耶和华已经出令，指著尼尼微说：你名下的人必不留后；我必从你神的庙中除灭雕刻的偶像和铸造的偶像；我必因你鄙陋，使你归于坟墓。'),
('CUV', '那鸿书', 34, 1, 15, '看哪，有报好信传平安之人的脚登山，说：犹大啊，可以守你的节期，还你所许的愿吧！因为那恶人不再从你中间经过，他已灭绝净尽了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '那鸿书', 34, 2, 1, '尼尼微啊，那打碎邦国的上来攻击你。你要看守保障，谨防道路，使腰强壮，大大勉力。'),
('CUV', '那鸿书', 34, 2, 2, '耶和华复兴雅各的荣华，好像以色列的荣华一样；因为使地空虚的，已经使雅各和以色列空虚，将他们的葡萄枝毁坏了。'),
('CUV', '那鸿书', 34, 2, 3, '他勇士的盾牌是红的，精兵都穿朱红衣服。在他预备争战的日子，战车上的钢铁闪烁如火，柏木把的枪也抡起来了。'),
('CUV', '那鸿书', 34, 2, 4, '车辆在街上（或译：城外）急行，在宽阔处奔来奔去，形状如火把，飞跑如闪电。'),
('CUV', '那鸿书', 34, 2, 5, '尼尼微王招聚他的贵胄；他们步行绊跌，速上城墙，预备挡牌。'),
('CUV', '那鸿书', 34, 2, 6, '河闸开放，宫殿冲没。'),
('CUV', '那鸿书', 34, 2, 7, '王后蒙羞，被人掳去；宫女搥胸，哀鸣如鸽。此乃命定之事。'),
('CUV', '那鸿书', 34, 2, 8, '尼尼微自古以来充满人民，如同聚水的池子；现在居民却都逃跑。虽有人呼喊说：站住！站住！却无人回顾。'),
('CUV', '那鸿书', 34, 2, 9, '你们抢掠金银罢！因为所积蓄的无穷，华美的宝器无数。'),
('CUV', '那鸿书', 34, 2, 10, '尼尼微现在空虚荒凉，人心消化，双膝相碰，腰都疼痛，脸都变色。'),
('CUV', '那鸿书', 34, 2, 11, '狮子的洞和少壮狮子喂养之处在哪里呢？公狮母狮小狮游行、无人惊吓之地在哪里呢？'),
('CUV', '那鸿书', 34, 2, 12, '公狮为小狮撕碎许多食物，为母狮掐死活物，把撕碎的、掐死的充满他的洞穴。'),
('CUV', '那鸿书', 34, 2, 13, '万军之耶和华说：我与你为敌，必将你的车辆焚烧成烟，刀剑也必吞灭你的少壮狮子。我必从地上除灭你所撕碎的，你使者的声音必不再听见。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '那鸿书', 34, 3, 1, '祸哉！这流人血的城，充满谎诈和强暴，抢夺的事总不止息。'),
('CUV', '那鸿书', 34, 3, 2, '鞭声响亮，车轮轰轰，马匹踢跳，车辆奔腾，'),
('CUV', '那鸿书', 34, 3, 3, '马兵争先，刀剑发光，枪矛闪烁，被杀的甚多，尸首成了大堆，尸骸无数，人碰著而跌倒，'),
('CUV', '那鸿书', 34, 3, 4, '都因那美貌的妓女多有淫行，惯行邪术，藉淫行诱惑列国，用邪术诱惑（原文是卖）多族。'),
('CUV', '那鸿书', 34, 3, 5, '万军之耶和华说：我与你为敌；我必揭起你的衣襟，蒙在你脸上，使列国看见你的赤体，使列邦观看你的丑陋。'),
('CUV', '那鸿书', 34, 3, 6, '我必将可憎污秽之物抛在你身上，辱没你，为众目所观。'),
('CUV', '那鸿书', 34, 3, 7, '凡看见你的，都必逃跑离开你，说：尼尼微荒凉了！有谁为你悲伤呢？我何处寻得安慰你的人呢？'),
('CUV', '那鸿书', 34, 3, 8, '你岂比挪亚们（或）强呢？挪亚们坐落在众河之间，周围有水；海（指尼罗河）作他的濠沟，又作他的城墙。'),
('CUV', '那鸿书', 34, 3, 9, '古实和埃及是他无穷的力量；弗人和路比族是他的帮手。'),
('CUV', '那鸿书', 34, 3, 10, '但他被迁移，被掳去；他的婴孩在各市口上也被摔死。人为他的尊贵人拈阄；他所有的大人都被链子锁著。'),
('CUV', '那鸿书', 34, 3, 11, '你也必喝醉，必被埋藏，并因仇敌的缘故寻求避难所。'),
('CUV', '那鸿书', 34, 3, 12, '你一切保障必像无花果树上初熟的无花果，若一摇撼就落在想吃之人的口中。'),
('CUV', '那鸿书', 34, 3, 13, '你地上的人民如同妇女；你国中的关口向仇敌敞开；你的门闩被火焚烧。'),
('CUV', '那鸿书', 34, 3, 14, '你要打水预备受困；要坚固你的保障，踹土和泥，修补砖窑。'),
('CUV', '那鸿书', 34, 3, 15, '在那里，火必烧灭你；刀必杀戮你，吞灭你如同蝻子。任你加增人数多如蝻子，多如蝗虫罢！'),
('CUV', '那鸿书', 34, 3, 16, '你增添商贾，多过天上的星；蝻子吃尽而去。'),
('CUV', '那鸿书', 34, 3, 17, '你的首领多如蝗虫；你的军长仿佛成群的蚂蚱，天凉的时候齐落在篱笆上，日头一出便都飞去，人不知道落在何处。'),
('CUV', '那鸿书', 34, 3, 18, '亚述王啊，你的牧人睡觉；你的贵胄安歇；你的人民散在山间，无人招聚。'),
('CUV', '那鸿书', 34, 3, 19, '你的损伤无法医治；你的伤痕极其重大。凡听你信息的必都因此向你拍掌。你所行的恶谁没有时常遭遇呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哈巴谷书', 35, 1, 1, '先知哈巴谷所得的默示。'),
('CUV', '哈巴谷书', 35, 1, 2, '他说：耶和华啊！我呼求你，你不应允，要到几时呢？我因强暴哀求你，你还不拯救。'),
('CUV', '哈巴谷书', 35, 1, 3, '你为何使我看见罪孽？你为何看著奸恶而不理呢？毁灭和强暴在我面前，又起了争端和相斗的事。'),
('CUV', '哈巴谷书', 35, 1, 4, '因此律法放松，公理也不显明，恶人围困义人，所以公理显然颠倒。'),
('CUV', '哈巴谷书', 35, 1, 5, '耶和华说：你们要向列国中观看，大大惊奇；因为在你们的时候，我行一件事，虽有人告诉你们，你们总是不信。'),
('CUV', '哈巴谷书', 35, 1, 6, '我必兴起迦勒底人，就是那残忍暴躁之民，通行遍地，占据那不属自己的住处。'),
('CUV', '哈巴谷书', 35, 1, 7, '他威武可畏，判断和势力都任意发出。'),
('CUV', '哈巴谷书', 35, 1, 8, '他的马比豹更快，比晚上的豺狼更猛。马兵踊跃争先，都从远方而来；他们飞跑如鹰抓食，'),
('CUV', '哈巴谷书', 35, 1, 9, '都为行强暴而来，定住脸面向前，将掳掠的人聚集，多如尘沙。'),
('CUV', '哈巴谷书', 35, 1, 10, '他们讥诮君王，笑话首领，嗤笑一切保障，筑垒攻取。'),
('CUV', '哈巴谷书', 35, 1, 11, '他以自己的势力为神，像风猛然扫过，显为有罪。'),
('CUV', '哈巴谷书', 35, 1, 12, '耶和华─我的神，我的圣者啊，你不是从亘古而有么？我们必不致死。耶和华啊，你派定他为要刑罚人；磐石啊，你设立他为要惩治人。'),
('CUV', '哈巴谷书', 35, 1, 13, '你眼目清洁，不看邪僻，不看奸恶；行诡诈的，你为何看著不理呢？恶人吞灭比自己公义的，你为何静默不语呢？'),
('CUV', '哈巴谷书', 35, 1, 14, '你为何使人如海中的鱼，又如没有管辖的爬物呢？'),
('CUV', '哈巴谷书', 35, 1, 15, '他用钩钩住，用网捕获，用拉网聚集他们；因此，他欢喜快乐，'),
('CUV', '哈巴谷书', 35, 1, 16, '就向网献祭，向网烧香，因他由此得肥美的分和富裕的食物。'),
('CUV', '哈巴谷书', 35, 1, 17, '他岂可屡次倒空网罗，将列国的人时常杀戮，毫不顾惜呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哈巴谷书', 35, 2, 1, '我要站在守望所，立在望楼上观看，看耶和华对我说甚么话，我可用甚么话向他诉冤（向他诉冤：或译回答所疑问的）。'),
('CUV', '哈巴谷书', 35, 2, 2, '他对我说：将这默示明明地写在版上，使读的人容易读（或译：随跑随读）。'),
('CUV', '哈巴谷书', 35, 2, 3, '因为这默示有一定的日期，快要应验，并不虚谎。虽然迟延，还要等候；因为必然临到，不再迟延。'),
('CUV', '哈巴谷书', 35, 2, 4, '迦勒底人自高自大，心不正直；惟义人因信得生。'),
('CUV', '哈巴谷书', 35, 2, 5, '迦勒底人因酒诡诈，狂傲，不住在家中，扩充心欲，好像阴间。他如死不能知足，聚集万国，堆积万民都归自己。'),
('CUV', '哈巴谷书', 35, 2, 6, '这些国的民岂不都要提起诗歌并俗语讥刺他说：祸哉！迦勒底人，你增添不属自己的财物，多多取人的当头，要到几时为止呢？'),
('CUV', '哈巴谷书', 35, 2, 7, '咬伤你的岂不忽然起来，扰害你的岂不兴起，你就作他们的掳物么？'),
('CUV', '哈巴谷书', 35, 2, 8, '因你抢夺许多的国，杀人流血，向国内的城并城中一切居民施行强暴，所以各国剩下的民都必抢夺你。'),
('CUV', '哈巴谷书', 35, 2, 9, '为本家积蓄不义之财、在高处搭窝、指望免灾的有祸了！'),
('CUV', '哈巴谷书', 35, 2, 10, '你图谋剪除多国的民，犯了罪，使你的家蒙羞，自害己命。'),
('CUV', '哈巴谷书', 35, 2, 11, '墙里的石头必呼叫；房内的栋梁必应声。'),
('CUV', '哈巴谷书', 35, 2, 12, '以人血建城、以罪孽立邑的有祸了！'),
('CUV', '哈巴谷书', 35, 2, 13, '众民所劳碌得来的被火焚烧，列国由劳乏而得的归于虚空，不都是出于万军之耶和华么？'),
('CUV', '哈巴谷书', 35, 2, 14, '认识耶和华荣耀的知识要充满遍地，好像水充满洋海一般。'),
('CUV', '哈巴谷书', 35, 2, 15, '给人酒喝、又加上毒物、使他喝醉、好看见他下体的有祸了！'),
('CUV', '哈巴谷书', 35, 2, 16, '你满受羞辱，不得荣耀；你也喝吧，显出是未受割礼的！耶和华右手的杯必传到你那里；你的荣耀就变为大大地羞辱。'),
('CUV', '哈巴谷书', 35, 2, 17, '你向利巴嫩行强暴与残害惊吓野兽的事必遮盖你；因你杀人流血，向国内的城并城中一切居民施行强暴。'),
('CUV', '哈巴谷书', 35, 2, 18, '雕刻的偶像，人将他刻出来，有甚么益处呢？铸造的偶像就是虚谎的师傅。制造者倚靠这哑巴偶像有甚么益处呢？'),
('CUV', '哈巴谷书', 35, 2, 19, '对木偶说：醒起！对哑巴石像说：起来！那人有祸了！这个还能教训人么？看哪，是包裹金银的，其中毫无气息。'),
('CUV', '哈巴谷书', 35, 2, 20, '惟耶和华在他的圣殿中；全地的人都当在他面前肃敬静默。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哈巴谷书', 35, 3, 1, '先知哈巴谷的祷告，调用流离歌。'),
('CUV', '哈巴谷书', 35, 3, 2, '耶和华啊，我听见你的名声（或译：言语）就惧怕。耶和华啊，求你在这些年间复兴你的作为，在这些年间显明出来；在发怒的时候以怜悯为念。'),
('CUV', '哈巴谷书', 35, 3, 3, '神从提幔而来；圣者从巴兰山临到。（细拉）他的荣光遮蔽诸天；颂赞充满大地。'),
('CUV', '哈巴谷书', 35, 3, 4, '他的辉煌如同日光；从他手里射出光线，在其中藏著他的能力。'),
('CUV', '哈巴谷书', 35, 3, 5, '在他前面有瘟疫流行；在他脚下有热症发出。'),
('CUV', '哈巴谷书', 35, 3, 6, '他站立，量了大地（或译：使地震动），观看，赶散万民。永久的山崩裂；长存的岭塌陷；他的作为与古时一样。'),
('CUV', '哈巴谷书', 35, 3, 7, '我见古珊的帐棚遭难，米甸的幔子战兢。'),
('CUV', '哈巴谷书', 35, 3, 8, '耶和华啊，你乘在马上，坐在得胜的车上，岂是不喜悦江河、向江河发怒气、向洋海发愤恨么？'),
('CUV', '哈巴谷书', 35, 3, 9, '你的弓全然显露，向众支派所起的誓都是可信的。（细拉）你以江河分开大地。'),
('CUV', '哈巴谷书', 35, 3, 10, '山岭见你，无不战惧；大水泛滥过去，深渊发声，汹涌翻腾（原文是向上举手）。'),
('CUV', '哈巴谷书', 35, 3, 11, '因你的箭射出，发光，你的枪闪出光耀，日月都在本宫停住。'),
('CUV', '哈巴谷书', 35, 3, 12, '你发愤恨通行大地，发怒气责打列国，如同打粮。'),
('CUV', '哈巴谷书', 35, 3, 13, '你出来要拯救你的百姓，拯救你的受膏者，打破恶人家长的头，露出他的脚（原文是根基），直到颈项。（细拉）'),
('CUV', '哈巴谷书', 35, 3, 14, '你用敌人的戈矛刺透他战士的头；他们来如旋风，要将我们分散。他们所喜爱的是暗中吞吃贫民。'),
('CUV', '哈巴谷书', 35, 3, 15, '你乘马践踏红海，就是践踏汹涌的大水。'),
('CUV', '哈巴谷书', 35, 3, 16, '我听见耶和华的声音，身体战兢，嘴唇发颤，骨中朽烂；我在所立之处战兢。我只可安静等候灾难之日临到，犯境之民上来。'),
('CUV', '哈巴谷书', 35, 3, 17, '虽然无花果树不发旺，葡萄树不结果，橄榄树也不效力，田地不出粮食，圈中绝了羊，棚内也没有牛；'),
('CUV', '哈巴谷书', 35, 3, 18, '然而，我要因耶和华欢欣，因救我的神喜乐。'),
('CUV', '哈巴谷书', 35, 3, 19, '主耶和华是我的力量；他使我的脚快如母鹿的蹄，又使我稳行在高处。这歌交与伶长，用丝弦的乐器。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '西番雅书', 36, 1, 1, '当犹大王亚们的儿子约西亚在位的时候，耶和华的话临到希西家的玄孙，亚玛利雅的曾孙，基大利的孙子，古示的儿子西番雅。'),
('CUV', '西番雅书', 36, 1, 2, '耶和华说：我必从地上除灭万类。'),
('CUV', '西番雅书', 36, 1, 3, '我必除灭人和牲畜，与空中的鸟、海里的鱼，以及绊脚石和恶人；我必将人从地上剪除。这是耶和华说的。'),
('CUV', '西番雅书', 36, 1, 4, '我必伸手攻击犹大和耶路撒冷的一切居民，也必从这地方剪除所剩下的巴力，并基玛林的名和祭司，'),
('CUV', '西番雅书', 36, 1, 5, '与那些在房顶上敬拜天上万象的，并那些敬拜耶和华指著他起誓，又指著玛勒堪起誓的，'),
('CUV', '西番雅书', 36, 1, 6, '与那些转去不跟从耶和华的，和不寻求耶和华也不访问他的。'),
('CUV', '西番雅书', 36, 1, 7, '你要在主耶和华面前静默无声，因为耶和华的日子快到。耶和华已经预备祭物，将他的客分别为圣。'),
('CUV', '西番雅书', 36, 1, 8, '到了我─耶和华献祭的日子，必惩罚首领和王子，并一切穿外邦衣服的。'),
('CUV', '西番雅书', 36, 1, 9, '到那日，我必惩罚一切跳过门槛、将强暴和诡诈得来之物充满主人房屋的。'),
('CUV', '西番雅书', 36, 1, 10, '耶和华说：当那日，从鱼门必发出悲哀的声音，从二城发出哀号的声音，从山间发出大破裂的响声。'),
('CUV', '西番雅书', 36, 1, 11, '玛革提施的居民哪，你们要哀号，因为迦南的商民都灭亡了！凡搬运银子的都被剪除。'),
('CUV', '西番雅书', 36, 1, 12, '那时，我必用灯巡查耶路撒冷；我必惩罚那些如酒在渣滓上澄清的；他们心里说：耶和华必不降福，也不降祸。'),
('CUV', '西番雅书', 36, 1, 13, '他们的财宝必成为掠物；他们的房屋必变为荒场。他们必建造房屋，却不得住在其内；栽种葡萄园，却不得喝所出的酒。'),
('CUV', '西番雅书', 36, 1, 14, '耶和华的大日临近，临近而且甚快，乃是耶和华日子的风声；勇士必痛痛地哭号。'),
('CUV', '西番雅书', 36, 1, 15, '那日是忿怒的日子，是急难困苦的日子，是荒废凄凉的日子，是黑暗幽冥、密云乌黑的日子，'),
('CUV', '西番雅书', 36, 1, 16, '是吹角呐喊的日子，要攻击坚固城和高大的城楼。'),
('CUV', '西番雅书', 36, 1, 17, '我必使灾祸临到人身上，使他们行走如同瞎眼的，因为得罪了我。他们的血必倒出如灰尘；他们的肉必抛弃如粪土。'),
('CUV', '西番雅书', 36, 1, 18, '当耶和华发怒的日子，他们的金银不能救他们；他的忿怒如火必烧灭全地，毁灭这地的一切居民，而且大大毁灭。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '西番雅书', 36, 2, 1, '不知羞耻的国民哪，你们应当聚集！趁命令没有发出，日子过去如风前的糠，耶和华的烈怒未临到你们，他发怒的日子未到以先，你们应当聚集前来。'),
('CUV', '西番雅书', 36, 2, 2, 'a'),
('CUV', '西番雅书', 36, 2, 3, '世上遵守耶和华典章的谦卑人哪，你们都当寻求耶和华！当寻求公义谦卑，或者在耶和华发怒的日子可以隐藏起来。'),
('CUV', '西番雅书', 36, 2, 4, '迦萨必致见弃；亚实基伦必然荒凉。人在正午必赶出亚实突的民；以革伦也被拔出根来。'),
('CUV', '西番雅书', 36, 2, 5, '住沿海之地的基利提族有祸了！迦南、非利士人之地啊，耶和华的话与你反对，说：我必毁灭你，以致无人居住。'),
('CUV', '西番雅书', 36, 2, 6, '沿海之地要变为草场，其上有牧人的住处和羊群的圈。'),
('CUV', '西番雅书', 36, 2, 7, '这地必为犹大家剩下的人所得；他们必在那里牧放群羊，晚上必躺卧在亚实基伦的房屋中；因为耶和华─他们的神必眷顾他们，使他们被掳的人归回。'),
('CUV', '西番雅书', 36, 2, 8, '我听见摩押人的毁谤和亚扪人的辱骂，就是毁谤我的百姓，自夸自大，侵犯他们的境界。'),
('CUV', '西番雅书', 36, 2, 9, '万军之耶和华─以色列的神说：我指著我的永生起誓：摩押必像所多玛，亚扪人必像蛾摩拉，都变为刺草、盐坑、永远荒废之地。我百姓所剩下的必掳掠他们；我国中所余剩的必得著他们的地。'),
('CUV', '西番雅书', 36, 2, 10, '这事临到他们是因他们骄傲，自夸自大，毁谤万军之耶和华的百姓。'),
('CUV', '西番雅书', 36, 2, 11, '耶和华必向他们显可畏之威，因他必叫世上的诸神瘦弱。列国海岛的居民各在自己的地方敬拜他。'),
('CUV', '西番雅书', 36, 2, 12, '古实人哪，你们必被我的刀所杀。'),
('CUV', '西番雅书', 36, 2, 13, '耶和华必伸手攻击北方，毁灭亚述，使尼尼微荒凉，又干旱如旷野。'),
('CUV', '西番雅书', 36, 2, 14, '群畜，就是各国（国：或译类）的走兽必卧在其中；鹈鹕和箭猪要宿在柱顶上。在窗户内有鸣叫的声音；门槛都必毁坏，香柏木已经露出。'),
('CUV', '西番雅书', 36, 2, 15, '这是素来欢乐安然居住的城，心里说：惟有我，除我以外再没有别的；现在何竟荒凉成为野兽躺卧之处！凡经过的人都必摇手嗤笑他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '西番雅书', 36, 3, 1, '这悖逆、污秽、欺压的城有祸了！'),
('CUV', '西番雅书', 36, 3, 2, '他不听从命令，不领受训诲，不倚靠耶和华，不亲近他的神。'),
('CUV', '西番雅书', 36, 3, 3, '他中间的首领是咆哮的狮子；他的审判官是晚上的豺狼，一点食物也不留到早晨。'),
('CUV', '西番雅书', 36, 3, 4, '他的先知是虚浮诡诈的人；他的祭司亵渎圣所，强解律法。'),
('CUV', '西番雅书', 36, 3, 5, '耶和华在他中间是公义的，断不做非义的事，每早晨显明他的公义，无日不然；只是不义的人不知羞耻。'),
('CUV', '西番雅书', 36, 3, 6, '我─耶和华已经除灭列国的民；他们的城楼毁坏。我使他们的街道荒凉，以致无人经过；他们的城邑毁灭，以致无人，也无居民。'),
('CUV', '西番雅书', 36, 3, 7, '我说：你只要敬畏我，领受训诲；如此，你的住处不致照我所拟定的除灭。只是你们从早起来就在一切事上败坏自己。'),
('CUV', '西番雅书', 36, 3, 8, '耶和华说：你们要等候我，直到我兴起掳掠的日子；因为我已定意招聚列国，聚集列邦，将我的恼怒─就是我的烈怒都倾在他们身上。我的忿怒如火，必烧灭全地。'),
('CUV', '西番雅书', 36, 3, 9, '那时，我必使万民用清洁的言语好求告我─耶和华的名，同心合意地事奉我。'),
('CUV', '西番雅书', 36, 3, 10, '祈祷我的，就是我所分散的民（原文是女子；下同），必从古实河外来，给我献供物。'),
('CUV', '西番雅书', 36, 3, 11, '当那日，你必不因你一切得罪我的事自觉羞愧；因为那时我必从你中间除掉矜夸高傲之辈，你也不再于我的圣山狂傲。'),
('CUV', '西番雅书', 36, 3, 12, '我却要在你中间留下困苦贫寒的民；他们必投靠我─耶和华的名。'),
('CUV', '西番雅书', 36, 3, 13, '以色列所剩下的人必不作罪孽，不说谎言，口中也没有诡诈的舌头；而且吃喝躺卧，无人惊吓。'),
('CUV', '西番雅书', 36, 3, 14, '锡安的民哪，应当歌唱！以色列啊，应当欢呼！耶路撒冷的民哪，应当满心欢喜快乐！'),
('CUV', '西番雅书', 36, 3, 15, '耶和华已经除去你的刑罚，赶出你的仇敌。以色列的王─耶和华在你中间；你必不再惧怕灾祸。'),
('CUV', '西番雅书', 36, 3, 16, '当那日，必有话向耶路撒冷说：不要惧怕！锡安哪；不要手软！'),
('CUV', '西番雅书', 36, 3, 17, '耶和华─你的神是施行拯救、大有能力的主。他在你中间必因你欢欣喜乐，默然爱你，且因你喜乐而欢呼。'),
('CUV', '西番雅书', 36, 3, 18, '那些属你、为无大会愁烦、因你担当羞辱的，我必聚集他们。'),
('CUV', '西番雅书', 36, 3, 19, '那时，我必罚办一切苦待你的人，又拯救你瘸腿的，聚集你被赶出的。那些在全地受羞辱的，我必使他们得称赞，有名声。'),
('CUV', '西番雅书', 36, 3, 20, '那时，我必领你们进来，聚集你们；我使你们被掳之人归回的时候，就必使你们在地上的万民中有名声，得称赞。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哈该书', 37, 1, 1, '大利乌王第二年六月初一日，耶和华的话藉先知哈该向犹大省长撒拉铁的儿子所罗巴伯和约撒答的儿子大祭司约书亚说：'),
('CUV', '哈该书', 37, 1, 2, '万军之耶和华如此说：这百姓说，建造耶和华殿的时候尚未来到。'),
('CUV', '哈该书', 37, 1, 3, '那时耶和华的话临到先知哈该说：'),
('CUV', '哈该书', 37, 1, 4, '这殿仍然荒凉，你们自己还住天花板的房屋么？'),
('CUV', '哈该书', 37, 1, 5, '现在万军之耶和华如此说：你们要省察自己的行为。'),
('CUV', '哈该书', 37, 1, 6, '你们撒的种多，收的却少；你们吃，却不得饱；喝，却不得足；穿衣服，却不得暖；得工钱的，将工钱装在破漏的囊中。'),
('CUV', '哈该书', 37, 1, 7, '万军之耶和华如此说：你们要省察自己的行为。'),
('CUV', '哈该书', 37, 1, 8, '你们要上山取木料，建造这殿，我就因此喜乐，且得荣耀。这是耶和华说的。'),
('CUV', '哈该书', 37, 1, 9, '你们盼望多得，所得的却少；你们收到家中，我就吹去。这是为甚么呢？因为我的殿荒凉，你们各人却顾（原文是奔）自己的房屋。这是万军之耶和华说的。'),
('CUV', '哈该书', 37, 1, 10, '所以为你们的缘故，天就不降甘露，地也不出土产。'),
('CUV', '哈该书', 37, 1, 11, '我命干旱临到地土、山冈、五谷、新酒，和油，并地上的出产、人民、牲畜，以及人手一切劳碌得来的。'),
('CUV', '哈该书', 37, 1, 12, '那时，撒拉铁的儿子所罗巴伯和约撒答的儿子大祭司约书亚，并剩下的百姓，都听从耶和华─他们神的话和先知哈该奉耶和华─他们神差来所说的话；百姓也在耶和华面前存敬畏的心。'),
('CUV', '哈该书', 37, 1, 13, '耶和华的使者哈该奉耶和华差遣对百姓说：耶和华说：我与你们同在。'),
('CUV', '哈该书', 37, 1, 14, '耶和华激动犹大省长撒拉铁的儿子所罗巴伯和约撒答的儿子大祭司约书亚，并剩下之百姓的心，他们就来为万军之耶和华─他们神的殿做工。'),
('CUV', '哈该书', 37, 1, 15, '这是在大利乌王第二年六月二十四日。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '哈该书', 37, 2, 1, '七月二十一日，耶和华的话临到先知哈该说：'),
('CUV', '哈该书', 37, 2, 2, '你要晓谕犹大省长撒拉铁的儿子所罗巴伯和约撒答的儿子大祭司约书亚，并剩下的百姓，说：'),
('CUV', '哈该书', 37, 2, 3, '你们中间存留的，有谁见过这殿从前的荣耀呢？现在你们看著如何？岂不在眼中看如无有么？'),
('CUV', '哈该书', 37, 2, 4, '耶和华说：所罗巴伯啊，虽然如此，你当刚强！约撒答的儿子大祭司约书亚啊，你也当刚强！这地的百姓，你们都当刚强作工，因为我与你们同在。这是万军之耶和华说的。'),
('CUV', '哈该书', 37, 2, 5, '这是照著你们出埃及我与你们立约的话。那时，我的灵住在你们中间，你们不要惧怕。'),
('CUV', '哈该书', 37, 2, 6, '万军之耶和华如此说：过不多时，我必再一次震动天地、沧海，与旱地。'),
('CUV', '哈该书', 37, 2, 7, '我必震动万国；万国的珍宝必都运来（或译：万国所羡慕的必来到），我就使这殿满了荣耀。这是万军之耶和华说的。'),
('CUV', '哈该书', 37, 2, 8, '万军之耶和华说：银子是我的，金子也是我的。'),
('CUV', '哈该书', 37, 2, 9, '这殿后来的荣耀必大过先前的荣耀；在这地方我必赐平安。这是万军之耶和华说的。'),
('CUV', '哈该书', 37, 2, 10, '大利乌王第二年九月二十四日，耶和华的话临到先知哈该说：'),
('CUV', '哈该书', 37, 2, 11, '万军之耶和华如此说：你要向祭司问律法，'),
('CUV', '哈该书', 37, 2, 12, '说：若有人用衣襟兜圣肉，这衣襟挨著饼，或汤，或酒，或油，或别的食物，便算为圣么？祭司说：不算为圣。'),
('CUV', '哈该书', 37, 2, 13, '哈该又说：若有人因摸死尸染了污秽，然后挨著这些物的哪一样，这物算污秽么？祭司说：必算污秽。'),
('CUV', '哈该书', 37, 2, 14, '于是哈该说：耶和华说：这民这国，在我面前也是如此；他们手下的各样工作都是如此；他们在坛上所献的也是如此。'),
('CUV', '哈该书', 37, 2, 15, '现在你们要追想，此日以前，耶和华的殿没有一块石头垒在石头上的光景。'),
('CUV', '哈该书', 37, 2, 16, '在那一切日子，有人来到谷堆，想得二十斗，只得了十斗。有人来到酒池，想得五十桶，只得了二十桶。'),
('CUV', '哈该书', 37, 2, 17, '在你们手下的各样工作上，我以旱风、霉烂、冰雹攻击你们，你们仍不归向我。这是耶和华说的。'),
('CUV', '哈该书', 37, 2, 18, '你们要追想此日以前，就是从这九月二十四日起，追想到立耶和华殿根基的日子。'),
('CUV', '哈该书', 37, 2, 19, '仓里有谷种么？葡萄树、无花果树、石榴树、橄榄树都没有结果子。从今日起，我必赐福与你们。'),
('CUV', '哈该书', 37, 2, 20, '这月二十四日，耶和华的话二次临到哈该说：'),
('CUV', '哈该书', 37, 2, 21, '你要告诉犹大省长所罗巴伯说：我必震动天地。'),
('CUV', '哈该书', 37, 2, 22, '我必倾覆列国的宝座，除灭列邦的势力，并倾覆战车和坐在其上的。马必跌倒，骑马的败落，各人被弟兄的刀所杀。'),
('CUV', '哈该书', 37, 2, 23, '万军之耶和华说：我仆人撒拉铁的儿子所罗巴伯啊，到那日，我必以你为印，因我拣选了你。这是万军之耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒迦利亚书', 38, 1, 1, '大利乌王第二年八月，耶和华的话临到易多的孙子、比利家的儿子先知撒迦利亚，说：'),
('CUV', '撒迦利亚书', 38, 1, 2, '耶和华曾向你们列祖大大发怒。'),
('CUV', '撒迦利亚书', 38, 1, 3, '所以你要对以色列人说，万军之耶和华如此说：你们要转向我，我就转向你们。这是万军之耶和华说的。'),
('CUV', '撒迦利亚书', 38, 1, 4, '不要效法你们列祖。从前的先知呼叫他们说，万军之耶和华如此说：你们要回头离开你们的恶道恶行。他们却不听，也不顺从我。这是耶和华说的。'),
('CUV', '撒迦利亚书', 38, 1, 5, '你们的列祖在哪里呢？那些先知能永远存活么？'),
('CUV', '撒迦利亚书', 38, 1, 6, '只是我的言语和律例，就是所吩咐我仆人众先知的，岂不临到你们列祖么？他们就回头，说：万军之耶和华定意按我们的行动作为向我们怎样行，他已照样行了。'),
('CUV', '撒迦利亚书', 38, 1, 7, '大利乌第二年十一月，就是细罢特月二十四日，耶和华的话临到易多的孙子、比利家的儿子先知撒迦利亚，说：'),
('CUV', '撒迦利亚书', 38, 1, 8, '我夜间观看，见一人骑著红马，站在洼地番石榴树中间。在他身后又有红马、黄马，和白马。'),
('CUV', '撒迦利亚书', 38, 1, 9, '我对与我说话的天使说：主啊，这是甚么意思？他说：我要指示你这是甚么意思。'),
('CUV', '撒迦利亚书', 38, 1, 10, '那站在番石榴树中间的人说：这是奉耶和华差遣在遍地走来走去的。'),
('CUV', '撒迦利亚书', 38, 1, 11, '那些骑马的对站在番石榴树中间耶和华的使者说：我们已在遍地走来走去，见全地都安息平静。'),
('CUV', '撒迦利亚书', 38, 1, 12, '于是，耶和华的使者说：万军之耶和华啊，你恼恨耶路撒冷和犹大的城邑已经七十年，你不施怜悯要到几时呢？'),
('CUV', '撒迦利亚书', 38, 1, 13, '耶和华就用美善的安慰话回答那与我说话的天使。'),
('CUV', '撒迦利亚书', 38, 1, 14, '与我说话的天使对我说：你要宣告说，万军之耶和华如此说：我为耶路撒冷为锡安，心里极其火热。'),
('CUV', '撒迦利亚书', 38, 1, 15, '我甚恼怒那安逸的列国，因我从前稍微恼怒我民，他们就加害过分。'),
('CUV', '撒迦利亚书', 38, 1, 16, '所以耶和华如此说：现今我回到耶路撒冷，仍施怜悯，我的殿必重建在其中，准绳必拉在耶路撒冷之上。这是万军之耶和华说的。'),
('CUV', '撒迦利亚书', 38, 1, 17, '你要再宣告说，万军之耶和华如此说：我的城邑必再丰盛发达。耶和华必再安慰锡安，拣选耶路撒冷。'),
('CUV', '撒迦利亚书', 38, 1, 18, '我举目观看，见有四角。'),
('CUV', '撒迦利亚书', 38, 1, 19, '我就问与我说话的天使说：这是甚么意思？他回答说：这是打散犹大、以色列，和耶路撒冷的角。'),
('CUV', '撒迦利亚书', 38, 1, 20, '耶和华又指四个匠人给我看。'),
('CUV', '撒迦利亚书', 38, 1, 21, '我说：他们来做甚么呢？他说：这是打散犹大的角，使人不敢抬头；但这些匠人来威吓列国，打掉他们的角，就是举起打散犹大地的角。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒迦利亚书', 38, 2, 1, '我又举目观看，见一人手拿准绳。'),
('CUV', '撒迦利亚书', 38, 2, 2, '我说：你往哪里去？他对我说：要去量耶路撒冷，看有多宽多长。'),
('CUV', '撒迦利亚书', 38, 2, 3, '与我说话的天使去的时候，又有一位天使迎著他来，'),
('CUV', '撒迦利亚书', 38, 2, 4, '对他说：你跑去告诉那少年人说，耶路撒冷必有人居住，好像无城墙的乡村，因为人民和牲畜甚多。'),
('CUV', '撒迦利亚书', 38, 2, 5, '耶和华说：我要作耶路撒冷四围的火城，并要作其中的荣耀。'),
('CUV', '撒迦利亚书', 38, 2, 6, '耶和华说：我从前分散你们在天的四方（原文是犹如天的四风），现在你们要从北方之地逃回。这是耶和华说的。'),
('CUV', '撒迦利亚书', 38, 2, 7, '与巴比伦人同住的锡安民哪，应当逃脱。'),
('CUV', '撒迦利亚书', 38, 2, 8, '万军之耶和华说，在显出荣耀之后，差遣我去惩罚那掳掠你们的列国，摸你们的就是摸他眼中的瞳人。'),
('CUV', '撒迦利亚书', 38, 2, 9, '看哪，我（或译：他）要向他们抡手，他们就必作服事他们之人的掳物，你们便知道万军之耶和华差遣我了。'),
('CUV', '撒迦利亚书', 38, 2, 10, '锡安城啊，应当欢乐歌唱，因为我来要住在你中间。这是耶和华说的。'),
('CUV', '撒迦利亚书', 38, 2, 11, '那时，必有许多国归附耶和华，作他（原文是我）的子民。他（原文是我）要住在你中间，你就知道万军之耶和华差遣我到你那里去了。'),
('CUV', '撒迦利亚书', 38, 2, 12, '耶和华必收回犹大作他圣地的分，也必再拣选耶路撒冷。'),
('CUV', '撒迦利亚书', 38, 2, 13, '凡有血气的都当在耶和华面前静默无声；因为他兴起，从圣所出来了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒迦利亚书', 38, 3, 1, '天使（原文是他）又指给我看：大祭司约书亚站在耶和华的使者面前；撒但也站在约书亚的右边，与他作对。'),
('CUV', '撒迦利亚书', 38, 3, 2, '耶和华向撒但说：撒但哪，耶和华责备你！就是拣选耶路撒冷的耶和华责备你！这不是从火中抽出来的一根柴么？'),
('CUV', '撒迦利亚书', 38, 3, 3, '约书亚穿著污秽的衣服站在使者面前。'),
('CUV', '撒迦利亚书', 38, 3, 4, '使者吩咐站在面前的说：你们要脱去他污秽的衣服；又对约书亚说：我使你脱离罪孽，要给你穿上华美的衣服。'),
('CUV', '撒迦利亚书', 38, 3, 5, '我说：要将洁净的冠冕戴在他头上。他们就把洁净的冠冕戴在他头上，给他穿上华美的衣服，耶和华的使者在旁边站立。'),
('CUV', '撒迦利亚书', 38, 3, 6, '耶和华的使者告诫约书亚说：'),
('CUV', '撒迦利亚书', 38, 3, 7, '万军之耶和华如此说：你若遵行我的道，谨守我的命令，你就可以管理我的家，看守我的院宇；我也要使你在这些站立的人中间来往。'),
('CUV', '撒迦利亚书', 38, 3, 8, '大祭司约书亚啊，你和坐在你面前的同伴都当听。他们是作预兆的。我必使我仆人大卫的苗裔发出。'),
('CUV', '撒迦利亚书', 38, 3, 9, '看哪，我在约书亚面前所立的石头，在一块石头上有七眼。万军之耶和华说：我要亲自雕刻这石头，并要在一日之间除掉这地的罪孽。'),
('CUV', '撒迦利亚书', 38, 3, 10, '当那日，你们各人要请邻舍坐在葡萄树和无花果树下。这是万军之耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒迦利亚书', 38, 4, 1, '那与我说话的天使又来叫醒我，好像人睡觉被唤醒一样。'),
('CUV', '撒迦利亚书', 38, 4, 2, '他问我说：你看见了甚么？我说：我看见了一个纯金的灯台，顶上有盏灯，灯台上有七盏灯，每盏有七个管子。'),
('CUV', '撒迦利亚书', 38, 4, 3, '旁边有两棵橄榄树，一棵在灯盏的右边，一棵在灯盏的左边。'),
('CUV', '撒迦利亚书', 38, 4, 4, '我问与我说话的天使说：主啊，这是甚么意思？'),
('CUV', '撒迦利亚书', 38, 4, 5, '与我说话的天使回答我说：你不知道这是甚么意思么？我说：主啊，我不知道。'),
('CUV', '撒迦利亚书', 38, 4, 6, '他对我说：这是耶和华指示所罗巴伯的。万军之耶和华说：不是倚靠势力，不是倚靠才能，乃是倚靠我的灵方能成事。'),
('CUV', '撒迦利亚书', 38, 4, 7, '大山哪，你算甚么呢？在所罗巴伯面前，你必成为平地。他必搬出一块石头，安在殿顶上。人且大声欢呼说：愿恩惠恩惠归与这殿（殿：或译石）！'),
('CUV', '撒迦利亚书', 38, 4, 8, '耶和华的话又临到我说：'),
('CUV', '撒迦利亚书', 38, 4, 9, '所罗巴伯的手立了这殿的根基，他的手也必完成这工，你就知道万军之耶和华差遣我到你们这里来了。'),
('CUV', '撒迦利亚书', 38, 4, 10, '谁藐视这日的事为小呢？这七眼乃是耶和华的眼睛，遍察全地，见所罗巴伯手拿线铊就欢喜。'),
('CUV', '撒迦利亚书', 38, 4, 11, '我又问天使说：这灯台左右的两棵橄榄树是甚么意思？'),
('CUV', '撒迦利亚书', 38, 4, 12, '我二次问他说：这两根橄榄枝在两个流出金色油的金嘴旁边是甚么意思？'),
('CUV', '撒迦利亚书', 38, 4, 13, '他对我说：你不知道这是甚么意思么？我说：主啊，我不知道。'),
('CUV', '撒迦利亚书', 38, 4, 14, '他说：这是两个受膏者站在普天下主的旁边。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒迦利亚书', 38, 5, 1, '我又举目观看，见有一飞行书卷。'),
('CUV', '撒迦利亚书', 38, 5, 2, '他问我说：你看见甚么？我回答说：我看见一飞行的书卷，长二十肘，宽十肘。'),
('CUV', '撒迦利亚书', 38, 5, 3, '他对我说：这是发出行在遍地上的咒诅。凡偷窃的必按卷上这面的话除灭；凡起假誓的必按卷上那面的话除灭。'),
('CUV', '撒迦利亚书', 38, 5, 4, '万军之耶和华说：我必使这书卷出去，进入偷窃人的家和指我名起假誓人的家，必常在他家里，连房屋带木石都毁灭了。'),
('CUV', '撒迦利亚书', 38, 5, 5, '与我说话的天使出来，对我说：你要举目观看，见所出来的是甚么？'),
('CUV', '撒迦利亚书', 38, 5, 6, '我说：这是甚么呢？他说：这出来的是量器。他又说：这是恶人在遍地的形状。'),
('CUV', '撒迦利亚书', 38, 5, 7, '（我见有一片圆铅被举起来。）这坐在量器中的是个妇人。'),
('CUV', '撒迦利亚书', 38, 5, 8, '天使说：这是罪恶。他就把妇人扔在量器中，将那片圆铅扔在量器的口上。'),
('CUV', '撒迦利亚书', 38, 5, 9, '我又举目观看，见有两个妇人出来，在他们翅膀中有风，飞得甚快，翅膀如同鹳鸟的翅膀。他们将量器抬起来，悬在天地中间。'),
('CUV', '撒迦利亚书', 38, 5, 10, '我问与我说话的天使说：他们要将量器抬到哪里去呢？'),
('CUV', '撒迦利亚书', 38, 5, 11, '他对我说：要往示拿地去，为他盖造房屋；等房屋齐备，就把他安置在自己的地方。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒迦利亚书', 38, 6, 1, '我又举目观看，见有四辆车从两山中间出来；那山是铜山。'),
('CUV', '撒迦利亚书', 38, 6, 2, '第一辆车套著红马，第二辆车套著黑马。'),
('CUV', '撒迦利亚书', 38, 6, 3, '第三辆车套著白马，第四辆车套著有斑点的壮马。'),
('CUV', '撒迦利亚书', 38, 6, 4, '我就问与我说话的天使说：主啊，这是甚么意思？'),
('CUV', '撒迦利亚书', 38, 6, 5, '天使回答我说：这是天的四风，是从普天下的主面前出来的。'),
('CUV', '撒迦利亚书', 38, 6, 6, '套著黑马的车往北方去，白马跟随在后；有斑点的马往南方去。'),
('CUV', '撒迦利亚书', 38, 6, 7, '壮马出来，要在遍地走来走去。天使说：你们只管在遍地走来走去。他们就照样行了。'),
('CUV', '撒迦利亚书', 38, 6, 8, '他又呼叫我说：看哪，往北方去的已在北方安慰我的心。'),
('CUV', '撒迦利亚书', 38, 6, 9, '耶和华的话临到我说：'),
('CUV', '撒迦利亚书', 38, 6, 10, '你要从被掳之人中取黑玳、多比雅、耶大雅的金银。这三人是从巴比伦来到西番雅的儿子约西亚的家里。当日你要进他的家，'),
('CUV', '撒迦利亚书', 38, 6, 11, '取这金银做冠冕，戴在约撒答的儿子大祭司约书亚的头上，'),
('CUV', '撒迦利亚书', 38, 6, 12, '对他说，万军之耶和华如此说：看哪，那名称为大卫苗裔的，他要在本处长起来，并要建造耶和华的殿。'),
('CUV', '撒迦利亚书', 38, 6, 13, '他要建造耶和华的殿，并担负尊荣，坐在位上掌王权；又必在位上作祭司，使两职之间筹定和平。'),
('CUV', '撒迦利亚书', 38, 6, 14, '这冠冕要归希连（就是黑玳）、多比雅、耶大雅，和西番雅的儿子贤（就是约西亚），放在耶和华的殿里为记念。'),
('CUV', '撒迦利亚书', 38, 6, 15, '远方的人也要来建造耶和华的殿，你们就知道万军之耶和华差遣我到你们这里来。你们若留意听从耶和华─你们神的话，这事必然成就。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒迦利亚书', 38, 7, 1, '大利乌王第四年九月，就是基斯流月初四日，耶和华的话临到撒迦利亚。'),
('CUV', '撒迦利亚书', 38, 7, 2, '那时伯特利人已经打发沙利亚和利坚米勒，并跟从他们的人，去恳求耶和华的恩，'),
('CUV', '撒迦利亚书', 38, 7, 3, '并问万军之耶和华殿中的祭司和先知说：我历年以来，在五月间哭泣斋戒，现在还当这样行么？'),
('CUV', '撒迦利亚书', 38, 7, 4, '万军之耶和华的话就临到我说：'),
('CUV', '撒迦利亚书', 38, 7, 5, '你要宣告国内的众民和祭司，说：你们这七十年，在五月、七月禁食悲哀，岂是丝毫向我禁食么？'),
('CUV', '撒迦利亚书', 38, 7, 6, '你们吃喝，不是为自己吃，为自己喝么？'),
('CUV', '撒迦利亚书', 38, 7, 7, '当耶路撒冷和四围的城邑有居民，正兴盛，南地高原有人居住的时候，耶和华藉从前的先知所宣告的话，你们不当听么？'),
('CUV', '撒迦利亚书', 38, 7, 8, '耶和华的话又临到撒迦利亚说：'),
('CUV', '撒迦利亚书', 38, 7, 9, '万军之耶和华曾对你们的列祖如此说：要按至理判断，各人以慈爱怜悯弟兄。'),
('CUV', '撒迦利亚书', 38, 7, 10, '不可欺压寡妇、孤儿、寄居的，和贫穷人。谁都不可心里谋害弟兄。'),
('CUV', '撒迦利亚书', 38, 7, 11, '他们却不肯听从，扭转肩头，塞耳不听，'),
('CUV', '撒迦利亚书', 38, 7, 12, '使心硬如金钢石，不听律法和万军之耶和华用灵藉从前的先知所说的话。故此，万军之耶和华大发烈怒。'),
('CUV', '撒迦利亚书', 38, 7, 13, '万军之耶和华说：我曾呼唤他们，他们不听；将来他们呼求我，我也不听！'),
('CUV', '撒迦利亚书', 38, 7, 14, '我必以旋风吹散他们到素不认识的万国中。这样，他们的地就荒凉，甚至无人来往经过，因为他们使美好之地荒凉了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒迦利亚书', 38, 8, 1, '万军之耶和华的话临到我说：'),
('CUV', '撒迦利亚书', 38, 8, 2, '万军之耶和华如此说：我为锡安心里极其火热，我为他火热，向他的仇敌发烈怒。'),
('CUV', '撒迦利亚书', 38, 8, 3, '耶和华如此说：我现在回到锡安，要住在耶路撒冷中。耶路撒冷必称为诚实的城，万军之耶和华的山必称为圣山。'),
('CUV', '撒迦利亚书', 38, 8, 4, '万军之耶和华如此说：将来必有年老的男女坐在耶路撒冷街上，因为年纪老迈就手拿拐杖。'),
('CUV', '撒迦利亚书', 38, 8, 5, '城中街上必满有男孩女孩玩耍。'),
('CUV', '撒迦利亚书', 38, 8, 6, '万军之耶和华如此说：到那日，这事在余剩的民眼中看为希奇，在我眼中也看为希奇么？这是万军之耶和华说的。'),
('CUV', '撒迦利亚书', 38, 8, 7, '万军之耶和华如此说：我要从东方从西方救回我的民。'),
('CUV', '撒迦利亚书', 38, 8, 8, '我要领他们来，使他们住在耶路撒冷中。他们要作我的子民，我要作他们的神，都凭诚实和公义。'),
('CUV', '撒迦利亚书', 38, 8, 9, '万军之耶和华如此说：当建造万军之耶和华的殿，立根基之日的先知所说的话，现在你们听见，应当手里强壮。'),
('CUV', '撒迦利亚书', 38, 8, 10, '那日以先，人得不著雇价，牲畜也是如此；且因敌人的缘故，出入之人不得平安，乃因我使众人互相攻击。'),
('CUV', '撒迦利亚书', 38, 8, 11, '但如今，我待这余剩的民必不像从前。这是万军之耶和华说的。'),
('CUV', '撒迦利亚书', 38, 8, 12, '因为他们必平安撒种，葡萄树必结果子，地土必有出产，天也必降甘露。我要使这余剩的民享受这一切的福。'),
('CUV', '撒迦利亚书', 38, 8, 13, '犹大家和以色列家啊，你们从前在列国中怎样成为可咒诅的；照样，我要拯救你们，使人称你们为有福的（或译：使你们叫人得福）。你们不要惧怕，手要强壮。'),
('CUV', '撒迦利亚书', 38, 8, 14, '万军之耶和华如此说：你们列祖惹我发怒的时候，我怎样定意降祸，并不后悔。'),
('CUV', '撒迦利亚书', 38, 8, 15, '现在我照样定意施恩与耶路撒冷和犹大家，你们不要惧怕。'),
('CUV', '撒迦利亚书', 38, 8, 16, '你们所当行的是这样：各人与邻舍说话诚实，在城门口按至理判断，使人和睦。'),
('CUV', '撒迦利亚书', 38, 8, 17, '谁都不可心里谋害邻舍，也不可喜爱起假誓，因为这些事都为我所恨恶。这是耶和华说的。'),
('CUV', '撒迦利亚书', 38, 8, 18, '万军之耶和华的话临到我说：'),
('CUV', '撒迦利亚书', 38, 8, 19, '万军之耶和华如此说：四月、五月禁食的日子，七月、十月禁食的日子，必变为犹大家欢喜快乐的日子和欢乐的节期；所以你们要喜爱诚实与和平。'),
('CUV', '撒迦利亚书', 38, 8, 20, '万军之耶和华如此说：将来必有列国的人和多城的居民来到。'),
('CUV', '撒迦利亚书', 38, 8, 21, '这城的居民必到那城，说：我们要快去恳求耶和华的恩，寻求万军之耶和华；我也要去。'),
('CUV', '撒迦利亚书', 38, 8, 22, '必有列邦的人和强国的民来到耶路撒冷寻求万军之耶和华，恳求耶和华的恩。'),
('CUV', '撒迦利亚书', 38, 8, 23, '万军之耶和华如此说：在那些日子，必有十个人从列国诸族（原文是方言）中出来，拉住一个犹大人的衣襟，说：我们要与你们同去，因为我们听见神与你们同在了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒迦利亚书', 38, 9, 1, '耶和华的默示应验在哈得拉地大马色─世人和以色列各支派的眼目都仰望耶和华─'),
('CUV', '撒迦利亚书', 38, 9, 2, '和靠近的哈马，并推罗、西顿；因为这二城的人大有智慧。'),
('CUV', '撒迦利亚书', 38, 9, 3, '推罗为自己修筑保障，积蓄银子如尘沙，堆起精金如街上的泥土。'),
('CUV', '撒迦利亚书', 38, 9, 4, '主必赶出他，打败他海上的权利；他必被火烧灭。'),
('CUV', '撒迦利亚书', 38, 9, 5, '亚实基伦看见必惧怕；迦萨看见甚痛苦；以革伦因失了盼望蒙羞。迦萨必不再有君王；亚实基伦也不再有居民。'),
('CUV', '撒迦利亚书', 38, 9, 6, '私生子（或译：外族人）必住在亚实突；我必除灭非利士人的骄傲。'),
('CUV', '撒迦利亚书', 38, 9, 7, '我必除去他口中带血之肉和牙齿内可憎之物。他必作为余剩的人归与我们的神，必在犹大像族长；以革伦人必如耶布斯人。'),
('CUV', '撒迦利亚书', 38, 9, 8, '我必在我家的四围安营，使敌军不得任意往来，暴虐的人也不再经过，因为我亲眼看顾我的家。'),
('CUV', '撒迦利亚书', 38, 9, 9, '锡安的民哪，应当大大喜乐；耶路撒冷的民哪，应当欢呼。看哪，你的王来到你这里！他是公义的，并且施行拯救，谦谦和和地骑著驴，就是骑著驴的驹子。'),
('CUV', '撒迦利亚书', 38, 9, 10, '我必除灭以法莲的战车和耶路撒冷的战马；争战的弓也必除灭。他必向列国讲和平；他的权柄必从这海管到那海，从大河管到地极。'),
('CUV', '撒迦利亚书', 38, 9, 11, '锡安哪，我因与你立约的血，将你中间被掳而囚的人从无水的坑中释放出来。'),
('CUV', '撒迦利亚书', 38, 9, 12, '你们被囚而有指望的人都要转回保障。我今日说明，我必加倍赐福给你们。'),
('CUV', '撒迦利亚书', 38, 9, 13, '我拿犹大作上弦的弓；我拿以法莲为张弓的箭。锡安哪，我要激发你的众子，攻击希利尼（原文是雅完）的众子，使你如勇士的刀。'),
('CUV', '撒迦利亚书', 38, 9, 14, '耶和华必显现在他们以上；他的箭必射出像闪电。主耶和华必吹角，乘南方的旋风而行。'),
('CUV', '撒迦利亚书', 38, 9, 15, '万军之耶和华必保护他们；他们必吞灭仇敌，践踏弹石。他们必喝血呐喊，犹如饮酒；他们必像盛满血的碗，又像坛的四角满了血。'),
('CUV', '撒迦利亚书', 38, 9, 16, '当那日，耶和华─他们的神必看他的民如群羊，拯救他们；因为他们必像冠冕上的宝石，高举在他的地以上（或译：在他的地上发光辉）。'),
('CUV', '撒迦利亚书', 38, 9, 17, '他的恩慈何等大！他的荣美何其盛！五谷健壮少男；新酒培养处女。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒迦利亚书', 38, 10, 1, '当春雨的时候，你们要向发闪电的耶和华求雨。他必为众人降下甘霖，使田园生长菜蔬。'),
('CUV', '撒迦利亚书', 38, 10, 2, '因为，家神所言的是虚空；卜士所见的是虚假；做梦者所说的是假梦。他们白白地安慰人，所以众人如羊流离，因无牧人就受苦。'),
('CUV', '撒迦利亚书', 38, 10, 3, '我的怒气向牧人发作；我必惩罚公山羊；因我─万军之耶和华眷顾自己的羊群，就是犹大家，必使他们如骏马在阵上。'),
('CUV', '撒迦利亚书', 38, 10, 4, '房角石、钉子、争战的弓，和一切掌权的都从他而出。'),
('CUV', '撒迦利亚书', 38, 10, 5, '他们必如勇士在阵上将仇敌践踏在街上的泥土中。他们必争战，因为耶和华与他们同在；骑马的也必羞愧。'),
('CUV', '撒迦利亚书', 38, 10, 6, '我要坚固犹大家，拯救约瑟家，要领他们归回。我要怜恤他们；他们必像未曾弃绝的一样，都因我是耶和华─他们的神，我必应允他们的祷告。'),
('CUV', '撒迦利亚书', 38, 10, 7, '以法莲人必如勇士；他们心中畅快如同喝酒；他们的儿女必看见而快活；他们的心必因耶和华喜乐。'),
('CUV', '撒迦利亚书', 38, 10, 8, '我要发嘶声，聚集他们，因我已经救赎他们。他们的人数必加增，如从前加增一样。'),
('CUV', '撒迦利亚书', 38, 10, 9, '我虽然（或译：必）播散他们在列国中，他们必在远方记念我。他们与儿女都必存活，且得归回。'),
('CUV', '撒迦利亚书', 38, 10, 10, '我必再领他们出埃及地，招聚他们出亚述，领他们到基列和利巴嫩；这地尚且不够他们居住。'),
('CUV', '撒迦利亚书', 38, 10, 11, '耶和华必经过苦海，击打海浪，使尼罗河的深处都枯干。亚述的骄傲必致卑微；埃及的权柄必然灭没。'),
('CUV', '撒迦利亚书', 38, 10, 12, '我必使他们倚靠我，得以坚固；一举一动必奉我的名。这是耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒迦利亚书', 38, 11, 1, '利巴嫩哪，开开你的门，任火烧灭你的香柏树。'),
('CUV', '撒迦利亚书', 38, 11, 2, '松树啊，应当哀号；因为香柏树倾倒，佳美的树毁坏。巴珊的橡树啊，应当哀号，因为茂盛的树林已经倒了。'),
('CUV', '撒迦利亚书', 38, 11, 3, '听啊，有牧人哀号的声音，因他们荣华的草场毁坏了。有少壮狮子咆哮的声音，因约但河旁的丛林荒废了。'),
('CUV', '撒迦利亚书', 38, 11, 4, '耶和华─我的神如此说：你─撒迦利亚要牧养这将宰的群羊。'),
('CUV', '撒迦利亚书', 38, 11, 5, '买他们的宰了他们，以自己为无罪；卖他们的说：耶和华是应当称颂的，因我成为富足。牧养他们的并不怜恤他们。'),
('CUV', '撒迦利亚书', 38, 11, 6, '耶和华说：我不再怜恤这地的居民，必将这民交给各人的邻舍和他们王的手中。他们必毁灭这地，我也不救这民脱离他们的手。'),
('CUV', '撒迦利亚书', 38, 11, 7, '于是，我牧养这将宰的群羊，就是群中最困苦的羊。我拿著两根杖，一根我称为荣美，一根我称为联索。这样，我牧养了群羊。'),
('CUV', '撒迦利亚书', 38, 11, 8, '一月之内，我除灭三个牧人，因为我的心厌烦他们；他们的心也憎嫌我。'),
('CUV', '撒迦利亚书', 38, 11, 9, '我就说：我不牧养你们。要死的，由他死；要丧亡的，由他丧亡；余剩的，由他们彼此相食。'),
('CUV', '撒迦利亚书', 38, 11, 10, '我折断那称为荣美的杖，表明我废弃与万民所立的约。'),
('CUV', '撒迦利亚书', 38, 11, 11, '当日就废弃了。这样，那些仰望我的困苦羊就知道所说的是耶和华的话。'),
('CUV', '撒迦利亚书', 38, 11, 12, '我对他们说：你们若以为美，就给我工价。不然，就罢了！于是他们给了三十块钱作为我的工价。'),
('CUV', '撒迦利亚书', 38, 11, 13, '耶和华吩咐我说：要把众人所估定美好的价值丢给窑户。我便将这三十块钱，在耶和华的殿中丢给窑户了。'),
('CUV', '撒迦利亚书', 38, 11, 14, '我又折断称为联索的那根杖，表明我废弃犹大与以色列弟兄的情谊。'),
('CUV', '撒迦利亚书', 38, 11, 15, '耶和华又吩咐我说：你再取愚昧人所用的器具，'),
('CUV', '撒迦利亚书', 38, 11, 16, '因我要在这地兴起一个牧人。他不看顾丧亡的，不寻找分散的，不医治受伤的，也不牧养强壮的；却要吃肥羊的肉，撕裂他的蹄子。'),
('CUV', '撒迦利亚书', 38, 11, 17, '无用的牧人丢弃羊群有祸了！刀必临到他的膀臂和右眼上。他的膀臂必全然枯干；他的右眼也必昏暗失明。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒迦利亚书', 38, 12, 1, '耶和华论以色列的默示。铺张诸天、建立地基、造人里面之灵的耶和华说：'),
('CUV', '撒迦利亚书', 38, 12, 2, '我必使耶路撒冷被围困的时候，向四围列国的民成为令人昏醉的杯；这默示也论到犹大（或译：犹大也是如此）。'),
('CUV', '撒迦利亚书', 38, 12, 3, '那日，我必使耶路撒冷向聚集攻击他的万民当作一块重石头；凡举起的必受重伤。'),
('CUV', '撒迦利亚书', 38, 12, 4, '耶和华说：到那日，我必使一切马匹惊惶，使骑马的颠狂。我必看顾犹大家，使列国的一切马匹瞎眼。'),
('CUV', '撒迦利亚书', 38, 12, 5, '犹大的族长必心里说：耶路撒冷的居民倚靠万军之耶和华─他们的神，就作我们的能力。'),
('CUV', '撒迦利亚书', 38, 12, 6, '那日，我必使犹大的族长如火盆在木柴中，又如火把在禾捆里；他们必左右烧灭四围列国的民。耶路撒冷人必仍住本处，就是耶路撒冷。'),
('CUV', '撒迦利亚书', 38, 12, 7, '耶和华必先拯救犹大的帐棚，免得大卫家的荣耀和耶路撒冷居民的荣耀胜过犹大。'),
('CUV', '撒迦利亚书', 38, 12, 8, '那日，耶和华必保护耶路撒冷的居民。他们中间软弱的必如大卫；大卫的家必如神，如行在他们前面之耶和华的使者。'),
('CUV', '撒迦利亚书', 38, 12, 9, '那日，我必定意灭绝来攻击耶路撒冷各国的民。'),
('CUV', '撒迦利亚书', 38, 12, 10, '我必将那施恩叫人恳求的灵，浇灌大卫家和耶路撒冷的居民。他们必仰望我（或译：他；本节同），就是他们所扎的；必为我悲哀，如丧独生子，又为我愁苦，如丧长子。'),
('CUV', '撒迦利亚书', 38, 12, 11, '那日，耶路撒冷必有大大的悲哀，如米吉多平原之哈达临门的悲哀。'),
('CUV', '撒迦利亚书', 38, 12, 12, '境内一家一家地都必悲哀。大卫家，男的独在一处，女的独在一处。拿单家，男的独在一处，女的独在一处。'),
('CUV', '撒迦利亚书', 38, 12, 13, '利未家，男的独在一处，女的独在一处。示每家，男的独在一处，女的独在一处。'),
('CUV', '撒迦利亚书', 38, 12, 14, '其余的各家，男的独在一处，女的独在一处。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒迦利亚书', 38, 13, 1, '那日，必给大卫家和耶路撒冷的居民开一个泉源，洗除罪恶与污秽。'),
('CUV', '撒迦利亚书', 38, 13, 2, '万军之耶和华说：那日，我必从地上除灭偶像的名，不再被人记念；也必使这地不再有假先知与污秽的灵。'),
('CUV', '撒迦利亚书', 38, 13, 3, '若再有人说预言，生他的父母必对他说：你不得存活，因为你托耶和华的名说假预言。生他的父母在他说预言的时候，要将他刺透。'),
('CUV', '撒迦利亚书', 38, 13, 4, '那日，凡作先知说预言的必因他所论的异象羞愧，不再穿毛衣哄骗人。'),
('CUV', '撒迦利亚书', 38, 13, 5, '他必说：我不是先知，我是耕地的；我从幼年作人的奴仆。'),
('CUV', '撒迦利亚书', 38, 13, 6, '必有人问他说：你两臂中间是甚么伤呢？他必回答说：这是我在亲友家中所受的伤。'),
('CUV', '撒迦利亚书', 38, 13, 7, '万军之耶和华说：刀剑哪，应当兴起，攻击我的牧人和我的同伴。击打牧人，羊就分散；我必反手加在微小者的身上。'),
('CUV', '撒迦利亚书', 38, 13, 8, '耶和华说：这全地的人，三分之二必剪除而死，三分之一仍必存留。'),
('CUV', '撒迦利亚书', 38, 13, 9, '我要使这三分之一经火，熬炼他们，如熬炼银子；试炼他们，如试炼金子。他们必求告我的名，我必应允他们。我要说：这是我的子民。他们也要说：耶和华是我们的神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '撒迦利亚书', 38, 14, 1, '耶和华的日子临近，你的财物必被抢掠，在你中间分散。'),
('CUV', '撒迦利亚书', 38, 14, 2, '因为我必聚集万国与耶路撒冷争战，城必被攻取，房屋被抢夺，妇女被玷污，城中的民一半被掳去；剩下的民仍在城中，不致剪除。'),
('CUV', '撒迦利亚书', 38, 14, 3, '那时，耶和华必出去与那些国争战，好像从前争战一样。'),
('CUV', '撒迦利亚书', 38, 14, 4, '那日，他的脚必站在耶路撒冷前面朝东的橄榄山上。这山必从中间分裂，自东至西成为极大的谷。山的一半向北挪移，一半向南挪移。'),
('CUV', '撒迦利亚书', 38, 14, 5, '你们要从我山的谷中逃跑，因为山谷必延到亚萨。你们逃跑，必如犹大王乌西雅年间的人逃避大地震一样。耶和华─我的神必降临，有一切圣者同来。'),
('CUV', '撒迦利亚书', 38, 14, 6, '那日，必没有光，三光必退缩。'),
('CUV', '撒迦利亚书', 38, 14, 7, '那日，必是耶和华所知道的，不是白昼，也不是黑夜，到了晚上才有光明。'),
('CUV', '撒迦利亚书', 38, 14, 8, '那日，必有活水从耶路撒冷出来，一半往东海流，一半往西海流；冬夏都是如此。'),
('CUV', '撒迦利亚书', 38, 14, 9, '耶和华必作全地的王。那日耶和华必为独一无二的，他的名也是独一无二的。'),
('CUV', '撒迦利亚书', 38, 14, 10, '全地，从迦巴直到耶路撒冷南方的临门，要变为亚拉巴。耶路撒冷必仍居高位，就是从便雅悯门到第一门之处，又到角门，并从哈楠业楼，直到王的酒醡。'),
('CUV', '撒迦利亚书', 38, 14, 11, '人必住在其中，不再有咒诅。耶路撒冷人必安然居住。'),
('CUV', '撒迦利亚书', 38, 14, 12, '耶和华用灾殃攻击那与耶路撒冷争战的列国人，必是这样：他们两脚站立的时候，肉必消没，眼在眶中干瘪，吞在口中溃烂。'),
('CUV', '撒迦利亚书', 38, 14, 13, '那日，耶和华必使他们大大扰乱。他们各人彼此揪住，举手攻击。'),
('CUV', '撒迦利亚书', 38, 14, 14, '犹大也必在耶路撒冷争战。那时四围各国的财物，就是许多金银衣服，必被收聚。'),
('CUV', '撒迦利亚书', 38, 14, 15, '那临到马匹、骡子、骆驼、驴，和营中一切牲畜的灾殃是与那灾殃一般。'),
('CUV', '撒迦利亚书', 38, 14, 16, '所有来攻击耶路撒冷列国中剩下的人，必年年上来敬拜大君王─万军之耶和华，并守住棚节。'),
('CUV', '撒迦利亚书', 38, 14, 17, '地上万族中，凡不上耶路撒冷敬拜大君王─万军之耶和华的，必无雨降在他们的地上。'),
('CUV', '撒迦利亚书', 38, 14, 18, '埃及族若不上来，雨也不降在他们的地上；凡不上来守住棚节的列国人，耶和华也必用这灾攻击他们。'),
('CUV', '撒迦利亚书', 38, 14, 19, '这就是埃及的刑罚和那不上来守住棚节之列国的刑罚。'),
('CUV', '撒迦利亚书', 38, 14, 20, '当那日，马的铃铛上必有归耶和华为圣的这句话。耶和华殿内的锅必如祭坛前的碗一样。'),
('CUV', '撒迦利亚书', 38, 14, 21, '凡耶路撒冷和犹大的锅都必归万军之耶和华为圣。凡献祭的都必来取这锅，煮肉在其中。当那日，在万军之耶和华的殿中必不再有迦南人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '玛拉基书', 39, 1, 1, '耶和华藉玛拉基传给以色列的默示。'),
('CUV', '玛拉基书', 39, 1, 2, '耶和华说：我曾爱你们。你们却说：你在何事上爱我们呢？耶和华说：以扫不是雅各的哥哥么？我却爱雅各，'),
('CUV', '玛拉基书', 39, 1, 3, '恶以扫，使他的山岭荒凉，把他的地业交给旷野的野狗。'),
('CUV', '玛拉基书', 39, 1, 4, '以东人说：我们现在虽被毁坏，却要重建荒废之处。万军之耶和华如此说：任他们建造，我必拆毁；人必称他们的地为罪恶之境；称他们的民为耶和华永远恼怒之民。'),
('CUV', '玛拉基书', 39, 1, 5, '你们必亲眼看见，也必说：愿耶和华在以色列境界之外被尊为大！'),
('CUV', '玛拉基书', 39, 1, 6, '藐视我名的祭司啊，万军之耶和华对你们说：儿子尊敬父亲，仆人敬畏主人；我既为父亲，尊敬我的在哪里呢？我既为主人，敬畏我的在哪里呢？你们却说：我们在何事上藐视你的名呢？'),
('CUV', '玛拉基书', 39, 1, 7, '你们将污秽的食物献在我的坛上，且说：我们在何事上污秽你呢？因你们说，耶和华的桌子是可藐视的。'),
('CUV', '玛拉基书', 39, 1, 8, '你们将瞎眼的献为祭物，这不为恶么？将瘸腿的、有病的献上，这不为恶么？你献给你的省长，他岂喜悦你，岂能看你的情面么？这是万军之耶和华说的。'),
('CUV', '玛拉基书', 39, 1, 9, '现在我劝你们恳求神，他好施恩与我们。这妄献的事，既由你们经手，他岂能看你们的情面么？这是万军之耶和华说的。'),
('CUV', '玛拉基书', 39, 1, 10, '甚愿你们中间有一人关上殿门，免得你们徒然在我坛上烧火。万军之耶和华说：我不喜悦你们，也不从你们手中收纳供物。'),
('CUV', '玛拉基书', 39, 1, 11, '万军之耶和华说：从日出之地到日落之处，我的名在外邦中必尊为大。在各处，人必奉我的名烧香，献洁净的供物，因为我的名在外邦中必尊为大。'),
('CUV', '玛拉基书', 39, 1, 12, '你们却亵渎我的名，说：耶和华的桌子是污秽的，其上的食物是可藐视的。'),
('CUV', '玛拉基书', 39, 1, 13, '你们又说：这些事何等烦琐！并嗤之以鼻。这是万军之耶和华说的。你们把抢夺的、瘸腿的、有病的拿来献上为祭。我岂能从你们手中收纳呢？这是耶和华说的。'),
('CUV', '玛拉基书', 39, 1, 14, '行诡诈的在群中有公羊，他许愿却用有残疾的献给主，这人是可咒诅的。因为我是大君王，我的名在外邦中是可畏的。这是万军之耶和华说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '玛拉基书', 39, 2, 1, '众祭司啊，这诫命是传给你们的。'),
('CUV', '玛拉基书', 39, 2, 2, '万军之耶和华说：你们若不听从，也不放在心上，将荣耀归与我的名，我就使咒诅临到你们，使你们的福分变为咒诅；因你们不把诫命放在心上，我已经咒诅你们了。'),
('CUV', '玛拉基书', 39, 2, 3, '我必斥责你们的种子，又把你们牺牲的粪抹你们的脸上；你们要与粪一同除掉。'),
('CUV', '玛拉基书', 39, 2, 4, '你们就知道我传这诫命给你们，使我与利未（或译：利未人）所立的约可以常存。这是万军之耶和华说的。'),
('CUV', '玛拉基书', 39, 2, 5, '我曾与他立生命和平安的约。我将这两样赐给他，使他存敬畏的心，他就敬畏我，惧怕我的名。'),
('CUV', '玛拉基书', 39, 2, 6, '真实的律法在他口中，他嘴里没有不义的话。他以平安和正直与我同行，使多人回头离开罪孽。'),
('CUV', '玛拉基书', 39, 2, 7, '祭司的嘴里当存知识，人也当由他口中寻求律法，因为他是万军之耶和华的使者。'),
('CUV', '玛拉基书', 39, 2, 8, '你们却偏离正道，使许多人在律法上跌倒。你们废弃我与利未所立的约。这是万军之耶和华说的。'),
('CUV', '玛拉基书', 39, 2, 9, '所以我使你们被众人藐视，看为下贱；因你们不守我的道，竟在律法上瞻徇情面。'),
('CUV', '玛拉基书', 39, 2, 10, '我们岂不都是一位父么？岂不是一位神所造的么？我们各人怎么以诡诈待弟兄，背弃了神与我们列祖所立的约呢？'),
('CUV', '玛拉基书', 39, 2, 11, '犹大人行事诡诈，并且在以色列和耶路撒冷中行一件可憎的事；因为犹大人亵渎耶和华所喜爱的圣洁（或译：圣地），娶事奉外邦神的女子为妻。'),
('CUV', '玛拉基书', 39, 2, 12, '凡行这事的，无论何人（何人：原文是叫醒的，答应的），就是献供物给万军之耶和华，耶和华也必从雅各的帐棚中剪除他。'),
('CUV', '玛拉基书', 39, 2, 13, '你们又行了一件这样的事，使前妻叹息哭泣的眼泪遮盖耶和华的坛，以致耶和华不再看顾那供物，也不乐从你们手中收纳。'),
('CUV', '玛拉基书', 39, 2, 14, '你们还说：这是为甚么呢？因耶和华在你和你幼年所娶的妻中间作见证。他虽是你的配偶，又是你盟约的妻，你却以诡诈待他。'),
('CUV', '玛拉基书', 39, 2, 15, '虽然神有灵的余力能造多人，他不是单造一人么？为何只造一人呢？乃是他愿人得虔诚的后裔。所以当谨守你们的心，谁也不可以诡诈待幼年所娶的妻。'),
('CUV', '玛拉基书', 39, 2, 16, '耶和华─以色列的神说：休妻的事和以强暴待妻的人都是我所恨恶的！所以当谨守你们的心，不可行诡诈。这是万军之耶和华说的。'),
('CUV', '玛拉基书', 39, 2, 17, '你们用言语烦琐耶和华，你们还说：我们在何事上烦琐他呢？因为你们说：凡行恶的，耶和华眼看为善，并且他喜悦他们；或说：公义的神在哪里呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '玛拉基书', 39, 3, 1, '万军之耶和华说：我要差遣我的使者在我前面预备道路。你们所寻求的主必忽然进入他的殿；立约的使者，就是你们所仰慕的，快要来到。'),
('CUV', '玛拉基书', 39, 3, 2, '他来的日子，谁能当得起呢？他显现的时候，谁能立得住呢？因为他如炼金之人的火，如漂布之人的碱。'),
('CUV', '玛拉基书', 39, 3, 3, '他必坐下如炼净银子的，必洁净利未人，熬炼他们像金银一样；他们就凭公义献供物给耶和华。'),
('CUV', '玛拉基书', 39, 3, 4, '那时，犹大和耶路撒冷所献的供物必蒙耶和华悦纳，仿佛古时之日、上古之年。'),
('CUV', '玛拉基书', 39, 3, 5, '万军之耶和华说：我必临近你们，施行审判。我必速速作见证，警戒行邪术的、犯奸淫的、起假誓的、亏负人之工价的、欺压寡妇孤儿的、屈枉寄居的，和不敬畏我的。'),
('CUV', '玛拉基书', 39, 3, 6, '因我─耶和华是不改变的，所以你们雅各之子没有灭亡。'),
('CUV', '玛拉基书', 39, 3, 7, '万军之耶和华说：从你们列祖的日子以来，你们常常偏离我的典章而不遵守。现在你们要转向我，我就转向你们。你们却问说：我们如何才是转向呢？'),
('CUV', '玛拉基书', 39, 3, 8, '人岂可夺取神之物呢？你们竟夺取我的供物。你们却说：我们在何事上夺取你的供物呢？就是你们在当纳的十分之一和当献的供物上。'),
('CUV', '玛拉基书', 39, 3, 9, '因你们通国的人都夺取我的供物，咒诅就临到你们身上。'),
('CUV', '玛拉基书', 39, 3, 10, '万军之耶和华说：你们要将当纳的十分之一全然送入仓库，使我家有粮，以此试试我，是否为你们敞开天上的窗户，倾福与你们，甚至无处可容。'),
('CUV', '玛拉基书', 39, 3, 11, '万军之耶和华说：我必为你们斥责蝗虫（原文是吞噬者），不容他毁坏你们的土产。你们田间的葡萄树在未熟之先也不掉果子。'),
('CUV', '玛拉基书', 39, 3, 12, '万军之耶和华说：万国必称你们为有福的，因你们的地必成为喜乐之地。'),
('CUV', '玛拉基书', 39, 3, 13, '耶和华说：你们用话顶撞我，你们还说：我们用甚么话顶撞了你呢？'),
('CUV', '玛拉基书', 39, 3, 14, '你们说：事奉神是徒然的，遵守神所吩咐的，在万军之耶和华面前苦苦斋戒，有甚么益处呢？'),
('CUV', '玛拉基书', 39, 3, 15, '如今我们称狂傲的人为有福，并且行恶的人得建立；他们虽然试探神，却得脱离灾难。'),
('CUV', '玛拉基书', 39, 3, 16, '那时，敬畏耶和华的彼此谈论，耶和华侧耳而听，且有纪念册在他面前，记录那敬畏耶和华、思念他名的人。'),
('CUV', '玛拉基书', 39, 3, 17, '万军之耶和华说：在我所定的日子，他们必属我，特特归我。我必怜恤他们，如同人怜恤服事自己的儿子。'),
('CUV', '玛拉基书', 39, 3, 18, '那时你们必归回，将善人和恶人，事奉神的和不事奉神的，分别出来。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '玛拉基书', 39, 4, 1, '万军之耶和华说：那日临近，势如烧著的火炉，凡狂傲的和行恶的必如碎秸，在那日必被烧尽，根本枝条一无存留。'),
('CUV', '玛拉基书', 39, 4, 2, '但向你们敬畏我名的人必有公义的日头出现，其光线（原文是翅膀）有医治之能。你们必出来跳跃如圈里的肥犊。'),
('CUV', '玛拉基书', 39, 4, 3, '你们必践踏恶人；在我所定的日子，他们必如灰尘在你们脚掌之下。这是万军之耶和华说的。'),
('CUV', '玛拉基书', 39, 4, 4, '你们当记念我仆人摩西的律法，就是我在何烈山为以色列众人所吩咐他的律例典章。'),
('CUV', '玛拉基书', 39, 4, 5, '看哪，耶和华大而可畏之日未到以前，我必差遣先知以利亚到你们那里去。'),
('CUV', '玛拉基书', 39, 4, 6, '他必使父亲的心转向儿女，儿女的心转向父亲，免得我来咒诅遍地。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 1, 1, '亚伯拉罕的后裔，大卫的子孙（后裔子孙原文都作儿子下同），耶稣基督的家谱：'),
('CUV', '马太福音', 40, 1, 2, '亚伯拉罕生以撒；以撒生雅各；雅各生犹大和他的弟兄；'),
('CUV', '马太福音', 40, 1, 3, '犹大从他玛氏生法勒斯和谢拉；法勒斯生希斯仑；希斯仑生亚兰；'),
('CUV', '马太福音', 40, 1, 4, '亚兰生亚米拿达；亚米拿达生拿顺；拿顺生撒门；'),
('CUV', '马太福音', 40, 1, 5, '撒门从喇合氏生波阿斯；波阿斯从路得氏生俄备得；俄备得生耶西；'),
('CUV', '马太福音', 40, 1, 6, '耶西生大卫王。大卫从乌利亚的妻子生所罗门；'),
('CUV', '马太福音', 40, 1, 7, '所罗门生罗波安；罗波安生亚比雅；亚比雅生亚撒；'),
('CUV', '马太福音', 40, 1, 8, '亚撒生约沙法；约沙法生约兰；约兰生乌西亚；'),
('CUV', '马太福音', 40, 1, 9, '乌西亚生约坦；约坦生亚哈斯；亚哈斯生希西家；'),
('CUV', '马太福音', 40, 1, 10, '希西家生玛拿西；玛拿西生亚们；亚们生约西亚；'),
('CUV', '马太福音', 40, 1, 11, '百姓被迁到巴比伦的时候，约西亚生耶哥尼雅和他的弟兄。'),
('CUV', '马太福音', 40, 1, 12, '迁到巴比伦之后，耶哥尼雅生撒拉铁；撒拉铁生所罗巴伯；'),
('CUV', '马太福音', 40, 1, 13, '所罗巴伯生亚比玉；亚比玉生以利亚敬；以利亚敬生亚所；'),
('CUV', '马太福音', 40, 1, 14, '亚所生撒督；撒督生亚金；亚金生以律；'),
('CUV', '马太福音', 40, 1, 15, '以律生以利亚撒；以利亚撒生马但；马但生雅各；'),
('CUV', '马太福音', 40, 1, 16, '雅各生约瑟，就是马利亚的丈夫。那称为基督的耶稣是从马利亚生的。'),
('CUV', '马太福音', 40, 1, 17, '这样，从亚伯拉罕到大卫共有十四代；从大卫到迁至巴比伦的时候也有十四代；从迁至巴比伦的时候到基督又有十四代。'),
('CUV', '马太福音', 40, 1, 18, '耶稣基督降生的事记在下面：他母亲马利亚已经许配了约瑟，还没有迎娶，马利亚就从圣灵怀了孕。'),
('CUV', '马太福音', 40, 1, 19, '他丈夫约瑟是个义人，不愿意明明的羞辱他，想要暗暗的把他休了。'),
('CUV', '马太福音', 40, 1, 20, '正思念这事的时候，有主的使者向他梦中显现，说：大卫的子孙约瑟，不要怕！只管娶过你的妻子马利亚来，因他所怀的孕是从圣灵来的。'),
('CUV', '马太福音', 40, 1, 21, '他将要生一个儿子，你要给他起名叫耶稣，因他要将自己的百姓从罪恶里救出来。'),
('CUV', '马太福音', 40, 1, 22, '这一切的事成就是要应验主藉先知所说的话，'),
('CUV', '马太福音', 40, 1, 23, '说：必有童女怀孕生子；人要称他的名为以马内利。（以马内利翻出来就是神与我们同在。）'),
('CUV', '马太福音', 40, 1, 24, '约瑟醒了，起来，就遵著主使者的吩咐把妻子娶过来；'),
('CUV', '马太福音', 40, 1, 25, '只是没有和他同房，等他生了儿子（有古卷：等他生了头胎的儿子），就给他起名叫耶稣。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 2, 1, '当希律王的时候，耶稣生在犹太的伯利恒。有几个博士从东方来到耶路撒冷，说：'),
('CUV', '马太福音', 40, 2, 2, '那生下来作犹太人之王的在那里？我们在东方看见他的星，特来拜他。'),
('CUV', '马太福音', 40, 2, 3, '希律王听见了，就心里不安；耶路撒冷合城的人也都不安。'),
('CUV', '马太福音', 40, 2, 4, '他就召齐了祭司长和民间的文士，问他们说：基督当生在何处？'),
('CUV', '马太福音', 40, 2, 5, '他们回答说：在犹太的伯利恒。因为有先知记著，说：'),
('CUV', '马太福音', 40, 2, 6, '犹大地的伯利恒阿，你在犹大诸城中并不是最小的；因为将来有一位君王要从你那里出来，牧养我以色列民。'),
('CUV', '马太福音', 40, 2, 7, '当下，希律暗暗的召了博士来，细问那星是甚么时候出现的，'),
('CUV', '马太福音', 40, 2, 8, '就差他们往伯利恒去，说：你们去仔细寻访那小孩子，寻到了，就来报信，我也好去拜他。'),
('CUV', '马太福音', 40, 2, 9, '他们听见王的话就去了。在东方所看见的那星忽然在他们前头行，直行到小孩子的地方，就在上头停住了。'),
('CUV', '马太福音', 40, 2, 10, '他们看见那星，就大大的欢喜；'),
('CUV', '马太福音', 40, 2, 11, '进了房子，看见小孩子和他母亲马利亚，就俯伏拜那小孩子，揭开宝盒，拿黄金、乳香、没药为礼物献给他。'),
('CUV', '马太福音', 40, 2, 12, '博士因为在梦中被主指示不要回去见希律，就从别的路回本地去了。'),
('CUV', '马太福音', 40, 2, 13, '他们去后，有主的使者向约瑟梦中显现，说：起来！带著小孩子同他母亲逃往埃及，住在那里，等我吩咐你；因为希律必寻找小孩子，要除灭他。'),
('CUV', '马太福音', 40, 2, 14, '约瑟就起来，夜间带著小孩子和他母亲往埃及去，'),
('CUV', '马太福音', 40, 2, 15, '住在那里，直到希律死了。这是要应验主藉先知所说的话，说：我从埃及召出我的儿子来。'),
('CUV', '马太福音', 40, 2, 16, '希律见自己被博士愚弄，就大大发怒，差人将伯利恒城里并四境所有的男孩，照著他向博士仔细查问的时候，凡两岁以里的，都杀尽了。'),
('CUV', '马太福音', 40, 2, 17, '这就应了先知耶利米的话，说：'),
('CUV', '马太福音', 40, 2, 18, '在拉玛听见号咷大哭的声音，是拉结哭他儿女，不肯受安慰，因为他们都不在了。'),
('CUV', '马太福音', 40, 2, 19, '希律死了以后，有主的使者在埃及向约瑟梦中显现，说：'),
('CUV', '马太福音', 40, 2, 20, '起来！带著小孩子和他母亲往以色列地去，因为要害小孩子性命的人已经死了。'),
('CUV', '马太福音', 40, 2, 21, '约瑟就起来，把小孩子和他母亲带到以色列地去；'),
('CUV', '马太福音', 40, 2, 22, '只因听见亚基老接著他父亲希律作了犹太王，就怕往那里去，又在梦中被主指示，便往加利利境内去了，'),
('CUV', '马太福音', 40, 2, 23, '到了一座城，名叫拿撒勒，就住在那里。这是要应验先知所说，他将称为拿撒勒人的话了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 3, 1, '那时，有施洗的约翰出来，在犹太的旷野传道，说：'),
('CUV', '马太福音', 40, 3, 2, '天国近了，你们应当悔改！'),
('CUV', '马太福音', 40, 3, 3, '这人就是先知以赛亚所说的。他说：在旷野有人声喊著说：预备主的道，修直他的路！'),
('CUV', '马太福音', 40, 3, 4, '这约翰身穿骆驼毛的衣服，腰束皮带，吃的是蝗虫、野蜜。'),
('CUV', '马太福音', 40, 3, 5, '那时，耶路撒冷和犹太全地，并约但河一带地方的人，都出去到约翰那里，'),
('CUV', '马太福音', 40, 3, 6, '承认他们的罪，在约但河里受他的洗。'),
('CUV', '马太福音', 40, 3, 7, '约翰看见许多法利赛人和撒都该人也来受洗，就对他们说：毒蛇的种类！谁指示你们逃避将来的忿怒呢？'),
('CUV', '马太福音', 40, 3, 8, '你们要结出果子来，与悔改的心相称。'),
('CUV', '马太福音', 40, 3, 9, '不要自己心里说：有亚伯拉罕为我们的祖宗。我告诉你们，神能从这些石头中给亚伯拉罕兴起子孙来。'),
('CUV', '马太福音', 40, 3, 10, '现在斧子已经放在树根上，凡不结好果子的树就砍下来，丢在火里。'),
('CUV', '马太福音', 40, 3, 11, '我是用水给你们施洗，叫你们悔改。但那在我以后来的，能力比我更大，我就是给他提鞋也不配。他要用圣灵与火给你们施洗。'),
('CUV', '马太福音', 40, 3, 12, '他手里拿著簸箕，要扬净他的场，把麦子收在仓里，把糠用不灭的火烧尽了。'),
('CUV', '马太福音', 40, 3, 13, '当下耶稣从加利利来到约但河，见了约翰，要受他的洗。'),
('CUV', '马太福音', 40, 3, 14, '约翰想要拦住他，说：我当受你的洗，你反倒上我这里来么？'),
('CUV', '马太福音', 40, 3, 15, '耶稣回答说：你暂且许我，因为我们理当这样尽诸般的义（或作：礼）。于是约翰许了他。'),
('CUV', '马太福音', 40, 3, 16, '耶稣受了洗，随即从水里上来。天忽然为他开了，他就看见神的灵仿佛鸽子降下，落在他身上。'),
('CUV', '马太福音', 40, 3, 17, '从天上有声音说：这是我的爱子，我所喜悦的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 4, 1, '当时，耶稣被圣灵引到旷野，受魔鬼的试探。'),
('CUV', '马太福音', 40, 4, 2, '他禁食四十昼夜，后来就饿了。'),
('CUV', '马太福音', 40, 4, 3, '那试探人的进前来，对他说：你若是神的儿子，可以吩咐这些石头变成食物。'),
('CUV', '马太福音', 40, 4, 4, '耶稣却回答说：经上记著说：人活著，不是单靠食物，乃是靠神口里所出的一切话。'),
('CUV', '马太福音', 40, 4, 5, '魔鬼就带他进了圣城，叫他站在殿顶（顶：原文是翅）上，'),
('CUV', '马太福音', 40, 4, 6, '对他说：你若是神的儿子，可以跳下去，因为经上记著说：主要为你吩咐他的使者用手托著你，免得你的脚碰在石头上。'),
('CUV', '马太福音', 40, 4, 7, '耶稣对他说：经上又记著说：不可试探主─你的神。'),
('CUV', '马太福音', 40, 4, 8, '魔鬼又带他上了一座最高的山，将世上的万国与万国的荣华都指给他看，'),
('CUV', '马太福音', 40, 4, 9, '对他说：你若俯伏拜我，我就把这一切都赐给你。'),
('CUV', '马太福音', 40, 4, 10, '耶稣说：撒但（撒但就是抵挡的意思，乃魔鬼的别名），退去罢！因为经上记著说：当拜主你的神，单要事奉他。'),
('CUV', '马太福音', 40, 4, 11, '于是，魔鬼离了耶稣，有天使来伺候他。'),
('CUV', '马太福音', 40, 4, 12, '耶稣听见约翰下了监，就退到加利利去；'),
('CUV', '马太福音', 40, 4, 13, '后又离开拿撒勒，往迦百农去，就住在那里。那地方靠海，在西布伦和拿弗他利的边界上。'),
('CUV', '马太福音', 40, 4, 14, '这是要应验先知以赛亚的话，'),
('CUV', '马太福音', 40, 4, 15, '说：西布伦地，拿弗他利地，就是沿海的路，约但河外，外邦人的加利利地。'),
('CUV', '马太福音', 40, 4, 16, '那坐在黑暗里的百姓看见了大光；坐在死荫之地的人有光发现照著他们。'),
('CUV', '马太福音', 40, 4, 17, '从那时候，耶稣就传起道来，说：天国近了，你们应当悔改！'),
('CUV', '马太福音', 40, 4, 18, '耶稣在加利利海边行走，看见弟兄二人，就是那称呼彼得的西门和他兄弟安得烈，在海里撒网；他们本是打鱼的。'),
('CUV', '马太福音', 40, 4, 19, '耶稣对他们说：来跟从我，我要叫你们得人如得鱼一样。'),
('CUV', '马太福音', 40, 4, 20, '他们就立刻舍了网，跟从了他。'),
('CUV', '马太福音', 40, 4, 21, '从那里往前走，又看见弟兄二人，就是西庇太的儿子雅各和他兄弟约翰，同他们的父亲西庇太在船上补网，耶稣就招呼他们，'),
('CUV', '马太福音', 40, 4, 22, '他们立刻舍了船，别了父亲，跟从了耶稣。'),
('CUV', '马太福音', 40, 4, 23, '耶稣走遍加利利，在各会堂里教训人，传天国的福音，医治百姓各样的病症。'),
('CUV', '马太福音', 40, 4, 24, '他的名声就传遍了叙利亚。那里的人把一切害病的，就是害各样疾病、各样疼痛的和被鬼附的、癫痫的、瘫痪的，都带了来，耶稣就治好了他们。'),
('CUV', '马太福音', 40, 4, 25, '当下，有许多人从加利利、低加波利、耶路撒冷、犹太、约但河外来跟著他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 5, 1, '耶稣看见这许多的人，就上了山，既已坐下，门徒到他跟前来，'),
('CUV', '马太福音', 40, 5, 2, '他就开口教训他们，说：'),
('CUV', '马太福音', 40, 5, 3, '虚心的人有福了！因为天国是他们的。'),
('CUV', '马太福音', 40, 5, 4, '哀恸的人有福了！因为他们必得安慰。'),
('CUV', '马太福音', 40, 5, 5, '温柔的人有福了！因为他们必承受地土。'),
('CUV', '马太福音', 40, 5, 6, '饥渴慕义的人有福了！因为他们必得饱足。'),
('CUV', '马太福音', 40, 5, 7, '怜恤人的人有福了！因为他们必蒙怜恤。'),
('CUV', '马太福音', 40, 5, 8, '清心的人有福了！因为他们必得见神。'),
('CUV', '马太福音', 40, 5, 9, '使人和睦的人有福了！因为他们必称为神的儿子。'),
('CUV', '马太福音', 40, 5, 10, '为义受逼迫的人有福了！因为天国是他们的。'),
('CUV', '马太福音', 40, 5, 11, '人若因我辱骂你们，逼迫你们，捏造各样坏话毁谤你们，你们就有福了！'),
('CUV', '马太福音', 40, 5, 12, '应当欢喜快乐，因为你们在天上的赏赐是大的。在你们以前的先知，人也是这样逼迫他们。'),
('CUV', '马太福音', 40, 5, 13, '你们是世上的盐。盐若失了味，怎能叫他再咸呢？以后无用，不过丢在外面，被人践踏了。'),
('CUV', '马太福音', 40, 5, 14, '你们是世上的光。城造在山上是不能隐藏的。'),
('CUV', '马太福音', 40, 5, 15, '人点灯，不放在斗底下，是放在灯台上，就照亮一家的人。'),
('CUV', '马太福音', 40, 5, 16, '你们的光也当这样照在人前，叫他们看见你们的好行为，便将荣耀归给你们在天上的父。'),
('CUV', '马太福音', 40, 5, 17, '莫想我来要废掉律法和先知。我来不是要废掉，乃是要成全。'),
('CUV', '马太福音', 40, 5, 18, '我实在告诉你们，就是到天地都废去了，律法的一点一画也不能废去，都要成全。'),
('CUV', '马太福音', 40, 5, 19, '所以，无论何人废掉这诫命中最小的一条，又教训人这样作，他在天国要称为最小的。但无论何人遵行这诫命，又教训人遵行，他在天国要称为大的。'),
('CUV', '马太福音', 40, 5, 20, '我告诉你们，你们的义若不胜于文士和法利赛人的义，断不能进天国。'),
('CUV', '马太福音', 40, 5, 21, '你们听见有吩咐古人的话，说：不可杀人；又说：凡杀人的难免受审判。'),
('CUV', '马太福音', 40, 5, 22, '只是我告诉你们：凡（有古卷在凡字下加：无缘无故地）向弟兄动怒的，难免受审断；凡骂弟兄是拉加的，难免公会的审断；凡骂弟兄是魔利的，难免地狱的火。'),
('CUV', '马太福音', 40, 5, 23, '所以，你在祭坛上献礼物的时候，若想起弟兄向你怀怨，'),
('CUV', '马太福音', 40, 5, 24, '就把礼物留在坛前，先去同弟兄和好，然后来献礼物。'),
('CUV', '马太福音', 40, 5, 25, '你同告你的对头还在路上，就赶紧与他和息，恐怕他把你送给审判官，审判官交付衙役，你就下在监里了。'),
('CUV', '马太福音', 40, 5, 26, '我实在告诉你，若有一文钱没有还清，你断不能从那里出来。'),
('CUV', '马太福音', 40, 5, 27, '你们听见有话说：不可奸淫。'),
('CUV', '马太福音', 40, 5, 28, '只是我告诉你们，凡看见妇女就动淫念的，这人心里已经与他犯奸淫了。'),
('CUV', '马太福音', 40, 5, 29, '若是你的右眼叫你跌倒，就剜出来丢掉，宁可失去百体中的一体，不叫全身丢在地狱里。'),
('CUV', '马太福音', 40, 5, 30, '若是右手叫你跌倒，就砍下来丢掉，宁可失去百体中的一体，不叫全身下入地狱。'),
('CUV', '马太福音', 40, 5, 31, '又有话说：人若休妻，就当给他休书。'),
('CUV', '马太福音', 40, 5, 32, '只是我告诉你们，凡休妻的，若不是为淫乱的缘故，就是叫他作淫妇了；人若娶这被休的妇人，也是犯奸淫了。'),
('CUV', '马太福音', 40, 5, 33, '你们又听见有吩咐古人的话，说：不可背誓，所起的誓总要向主谨守。'),
('CUV', '马太福音', 40, 5, 34, '只是我告诉你们，甚么誓都不可起。不可指著天起誓，因为天是神的座位；'),
('CUV', '马太福音', 40, 5, 35, '不可指著地起誓，因为地是他的脚凳；也不可指著耶路撒冷起誓，因为耶路撒冷是大君的京城；'),
('CUV', '马太福音', 40, 5, 36, '又不可指著你的头起誓，因为你不能使一根头发变黑变白了。'),
('CUV', '马太福音', 40, 5, 37, '你们的话，是，就说是；不是，就说不是；若再多说，就是出于那恶者（或作：就是从恶里出来的）。'),
('CUV', '马太福音', 40, 5, 38, '你们听见有话说：以眼还眼，以牙还牙。'),
('CUV', '马太福音', 40, 5, 39, '只是我告诉你们，不要与恶人作对。有人打你的右脸，连左脸也转过来由他打；'),
('CUV', '马太福音', 40, 5, 40, '有人想要告你，要拿你的里衣，连外衣也由他拿去；'),
('CUV', '马太福音', 40, 5, 41, '有人强逼你走一里路，你就同他走二里；'),
('CUV', '马太福音', 40, 5, 42, '有求你的，就给他；有向你借贷的，不可推辞。'),
('CUV', '马太福音', 40, 5, 43, '你们听见有话说：当爱你的邻舍，恨你的仇敌。'),
('CUV', '马太福音', 40, 5, 44, '只是我告诉你们，要爱你们的仇敌，为那逼迫你们的祷告。'),
('CUV', '马太福音', 40, 5, 45, '这样就可以作你们天父的儿子；因为他叫日头照好人，也照歹人；降雨给义人，也给不义的人。'),
('CUV', '马太福音', 40, 5, 46, '你们若单爱那爱你们的人，有甚么赏赐呢？就是税吏不也是这样行么？'),
('CUV', '马太福音', 40, 5, 47, '你们若单请你弟兄的安，比人有甚么长处呢？就是外邦人不也是这样行么？'),
('CUV', '马太福音', 40, 5, 48, '所以，你们要完全，像你们的天父完全一样。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 6, 1, '你们要小心，不可将善事行在人的面前，故意叫他们看见，若是这样，就不能得你们天父的赏赐了。'),
('CUV', '马太福音', 40, 6, 2, '所以，你施舍的时候，不可在你面前吹号，像那假冒为善的人在会堂里和街道上所行的，故意要得人的荣耀。我实在告诉你们，他们已经得了他们的赏赐。'),
('CUV', '马太福音', 40, 6, 3, '你施舍的时候，不要叫左手知道右手所做的，'),
('CUV', '马太福音', 40, 6, 4, '要叫你施舍的事行在暗中。你父在暗中察看，必然报答你（有古卷：必在明处报答你）。'),
('CUV', '马太福音', 40, 6, 5, '你们祷告的时候，不可像那假冒为善的人，爱站在会堂里和十字路口上祷告，故意叫人看见。我实在告诉你们，他们已经得了他们的赏赐。'),
('CUV', '马太福音', 40, 6, 6, '你祷告的时候，要进你的内屋，关上门，祷告你在暗中的父；你父在暗中察看，必然报答你。'),
('CUV', '马太福音', 40, 6, 7, '你们祷告，不可像外邦人，用许多重复话，他们以为话多了必蒙垂听。'),
('CUV', '马太福音', 40, 6, 8, '你们不可效法他们；因为你们没有祈求以先，你们所需用的，你们的父早已知道了。'),
('CUV', '马太福音', 40, 6, 9, '所以，你们祷告要这样说：我们在天上的父：愿人都尊你的名为圣。'),
('CUV', '马太福音', 40, 6, 10, '愿你的国降临；愿你的旨意行在地上，如同行在天上。'),
('CUV', '马太福音', 40, 6, 11, '我们日用的饮食，今日赐给我们。'),
('CUV', '马太福音', 40, 6, 12, '免我们的债，如同我们免了人的债。'),
('CUV', '马太福音', 40, 6, 13, '不叫我们遇见试探；救我们脱离凶恶（或作：脱离恶者）。因为国度、权柄、荣耀，全是你的，直到永远。阿们（有古卷没有因为……阿们等字）！'),
('CUV', '马太福音', 40, 6, 14, '你们饶恕人的过犯，你们的天父也必饶恕你们的过犯；'),
('CUV', '马太福音', 40, 6, 15, '你们不饶恕人的过犯，你们的天父也必不饶恕你们的过犯。'),
('CUV', '马太福音', 40, 6, 16, '你们禁食的时候，不可像那假冒为善的人，脸上带著愁容；因为他们把脸弄得难看，故意叫人看出他们是禁食。我实在告诉你们，他们已经得了他们的赏赐。'),
('CUV', '马太福音', 40, 6, 17, '你禁食的时候，要梳头洗脸，'),
('CUV', '马太福音', 40, 6, 18, '不叫人看出你禁食来，只叫你暗中的父看见；你父在暗中察看，必然报答你。'),
('CUV', '马太福音', 40, 6, 19, '不要为自己积儹财宝在地上；地上有虫子咬，能�坏，也有贼挖窟窿来偷。'),
('CUV', '马太福音', 40, 6, 20, '只要积儹财宝在天上；天上没有虫子咬，不能�坏，也没有贼挖窟窿来偷。'),
('CUV', '马太福音', 40, 6, 21, '因为你的财宝在那里，你的心也在那里。'),
('CUV', '马太福音', 40, 6, 22, '眼睛就是身上的灯。你的眼睛若瞭亮，全身就光明；'),
('CUV', '马太福音', 40, 6, 23, '你的眼睛若昏花，全身就黑暗。你里头的光若黑暗了，那黑暗是何等大呢！'),
('CUV', '马太福音', 40, 6, 24, '一个人不能事奉两个主；不是恶这个，爱那个，就是重这个，轻那个。你们不能又事奉神，又事奉玛门（玛门：财利的意思）。'),
('CUV', '马太福音', 40, 6, 25, '所以我告诉你们，不要为生命忧虑吃甚么，喝甚么；为身体忧虑穿甚么。生命不胜于饮食么？身体不胜于衣裳么？'),
('CUV', '马太福音', 40, 6, 26, '你们看那天上的飞鸟，也不种，也不收，也不积蓄在仓里，你们的天父尚且养活他。你们不比飞鸟贵重得多么？'),
('CUV', '马太福音', 40, 6, 27, '你们那一个能用思虑使寿数多加一刻呢（或作：使身量多加一肘呢）？'),
('CUV', '马太福音', 40, 6, 28, '何必为衣裳忧虑呢？你想野地里的百合花怎么长起来；他也不劳苦，也不纺线。'),
('CUV', '马太福音', 40, 6, 29, '然而我告诉你们，就是所罗门极荣华的时候，他所穿戴的，还不如这花一朵呢！'),
('CUV', '马太福音', 40, 6, 30, '你们这小信的人哪！野地里的草今天还在，明天就丢在炉里，神还给他这样的妆饰，何况你们呢！'),
('CUV', '马太福音', 40, 6, 31, '所以，不要忧虑说：吃甚么？喝甚么？穿甚么？'),
('CUV', '马太福音', 40, 6, 32, '这都是外邦人所求的，你们需用的这一切东西，你们的天父是知道的。'),
('CUV', '马太福音', 40, 6, 33, '你们要先求他的国和他的义，这些东西都要加给你们了。'),
('CUV', '马太福音', 40, 6, 34, '所以，不要为明天忧虑，因为明天自有明天的忧虑；一天的难处一天当就够了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 7, 1, '你们不要论断人，免得你们被论断。'),
('CUV', '马太福音', 40, 7, 2, '因为你们怎样论断人，也必怎样被论断；你们用甚么量器量给人，也必用甚么量器量给你们。'),
('CUV', '马太福音', 40, 7, 3, '为甚么看见你弟兄眼中有刺，却不想自己眼中有梁木呢？'),
('CUV', '马太福音', 40, 7, 4, '你自己眼中有梁木，怎能对你弟兄说：容我去掉你眼中的刺呢？'),
('CUV', '马太福音', 40, 7, 5, '你这假冒为善的人！先去掉自己眼中的梁木，然后才能看得清楚，去掉你弟兄眼中的刺。'),
('CUV', '马太福音', 40, 7, 6, '不要把圣物给狗，也不要把你们的珍珠丢在猪前，恐怕他践踏了珍珠，转过来咬你们。'),
('CUV', '马太福音', 40, 7, 7, '你们祈求，就给你们；寻找，就寻见；叩门，就给你们开门。'),
('CUV', '马太福音', 40, 7, 8, '因为凡祈求的，就得著；寻找的，就寻见；叩门的，就给他开门。'),
('CUV', '马太福音', 40, 7, 9, '你们中间谁有儿子求饼，反给他石头呢？'),
('CUV', '马太福音', 40, 7, 10, '求鱼，反给他蛇呢？'),
('CUV', '马太福音', 40, 7, 11, '你们虽然不好，尚且知道拿好东西给儿女，何况你们在天上的父，岂不更把好东西给求他的人么？'),
('CUV', '马太福音', 40, 7, 12, '所以，无论何事，你们愿意人怎样待你们，你们也要怎样待人，因为这就是律法和先知的道理。'),
('CUV', '马太福音', 40, 7, 13, '你们要进窄门。因为引到灭亡，那门是宽的，路是大的，进去的人也多；'),
('CUV', '马太福音', 40, 7, 14, '引到永生，那门是窄的，路是小的，找著的人也少。'),
('CUV', '马太福音', 40, 7, 15, '你们要防备假先知。他们到你们这里来，外面披著羊皮，里面却是残暴的狼。'),
('CUV', '马太福音', 40, 7, 16, '凭著他们的果子，就可以认出他们来。荆棘上岂能摘葡萄呢？蒺藜里岂能摘无花果呢？'),
('CUV', '马太福音', 40, 7, 17, '这样，凡好树都结好果子，惟独坏树结坏果子。'),
('CUV', '马太福音', 40, 7, 18, '好树不能结坏果子；坏树不能结好果子。'),
('CUV', '马太福音', 40, 7, 19, '凡不结好果子的树就砍下来，丢在火里。'),
('CUV', '马太福音', 40, 7, 20, '所以，凭著他们的果子就可以认出他们来。'),
('CUV', '马太福音', 40, 7, 21, '凡称呼我主阿，主阿的人不能都进天国；惟独遵行我天父旨意的人才能进去。'),
('CUV', '马太福音', 40, 7, 22, '当那日必有许多人对我说：主阿，主阿，我们不是奉你的名传道，奉你的名赶鬼，奉你的名行许多异能么？'),
('CUV', '马太福音', 40, 7, 23, '我就明明的告诉他们说：我从来不认识你们，你们这些作恶的人，离开我去罢！'),
('CUV', '马太福音', 40, 7, 24, '所以，凡听见我这话就去行的，好比一个聪明人，把房子盖在磐石上；'),
('CUV', '马太福音', 40, 7, 25, '雨淋，水冲，风吹，撞著那房子，房子总不倒塌，因为根基立在磐石上。'),
('CUV', '马太福音', 40, 7, 26, '凡听见我这话不去行的，好比一个无知的人，把房子盖在沙土上；'),
('CUV', '马太福音', 40, 7, 27, '雨淋，水冲，风吹，撞著那房子，房子就倒塌了，并且倒塌得很大。'),
('CUV', '马太福音', 40, 7, 28, '耶稣讲完了这些话，众人都希奇他的教训；'),
('CUV', '马太福音', 40, 7, 29, '因为他教训他们，正像有权柄的人，不像他们的文士。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 8, 1, '耶稣下了山，有许多人跟著他。'),
('CUV', '马太福音', 40, 8, 2, '有一个长大痲疯的来拜他，说：主若肯，必能叫我洁净了。'),
('CUV', '马太福音', 40, 8, 3, '耶稣伸手摸他，说：我肯，你洁净了罢！他的大痲疯立刻就洁净了。'),
('CUV', '马太福音', 40, 8, 4, '耶稣对他说：你切不可告诉人，只要去把身体给祭司察看，献上摩西所吩咐的礼物，对众人作证据。'),
('CUV', '马太福音', 40, 8, 5, '耶稣进了迦百农，有一个百夫长进前来，求他说：'),
('CUV', '马太福音', 40, 8, 6, '主阿，我的仆人害瘫痪病，躺在家里，甚是疼苦。'),
('CUV', '马太福音', 40, 8, 7, '耶稣说：我去医治他。'),
('CUV', '马太福音', 40, 8, 8, '百夫长回答说：主阿，你到我舍下，我不敢当；只要你说一句话，我的仆人就必好了。'),
('CUV', '马太福音', 40, 8, 9, '因为我在人的权下，也有兵在我以下；对这个说：去！他就去；对那个说：来！他就来；对我的仆人说：你作这事！他就去作。'),
('CUV', '马太福音', 40, 8, 10, '耶稣听见就希奇，对跟从的人说：我实在告诉你们，这么大的信心，就是在以色列中，我也没有遇见过。'),
('CUV', '马太福音', 40, 8, 11, '我又告诉你们，从东从西，将有许多人来，在天国里与亚伯拉罕、以撒、雅各一同坐席；'),
('CUV', '马太福音', 40, 8, 12, '惟有本国的子民竟被赶到外边黑暗里去，在那里必要哀哭切齿了。'),
('CUV', '马太福音', 40, 8, 13, '耶稣对百夫长说：你回去罢！照你的信心，给你成全了。那时，他的仆人就好了。'),
('CUV', '马太福音', 40, 8, 14, '耶稣到了彼得家里，见彼得的岳母害热病躺著。'),
('CUV', '马太福音', 40, 8, 15, '耶稣把他的手一摸，热就退了；他就起来服事耶稣。'),
('CUV', '马太福音', 40, 8, 16, '到了晚上，有人带著许多被鬼附的来到耶稣跟前，他只用一句话就把鬼都赶出去，并且治好了一切有病的人。'),
('CUV', '马太福音', 40, 8, 17, '这是要应验先知以赛亚的话，说：他代替我们的软弱，担当我们的疾病。'),
('CUV', '马太福音', 40, 8, 18, '耶稣见许多人围著他，就吩咐渡到那边去。'),
('CUV', '马太福音', 40, 8, 19, '有一个文士来，对他说：夫子，你无论往那里去，我要跟从你。'),
('CUV', '马太福音', 40, 8, 20, '耶稣说：狐狸有洞，天空的飞鸟有窝，人子却没有枕头的地方。'),
('CUV', '马太福音', 40, 8, 21, '又有一个门徒对耶稣说：主阿，容我先回去埋葬我的父亲。'),
('CUV', '马太福音', 40, 8, 22, '耶稣说：任凭死人埋葬他们的死人；你跟从我罢！'),
('CUV', '马太福音', 40, 8, 23, '耶稣上了船，门徒跟著他。'),
('CUV', '马太福音', 40, 8, 24, '海里忽然起了暴风，甚至船被波浪掩盖；耶稣却睡著了。'),
('CUV', '马太福音', 40, 8, 25, '门徒来叫醒了他，说：主阿，救我们，我们丧命啦！'),
('CUV', '马太福音', 40, 8, 26, '耶稣说：你们这小信的人哪，为甚么胆怯呢？于是起来，斥责风和海，风和海就大大的平静了。'),
('CUV', '马太福音', 40, 8, 27, '众人希奇，说：这是怎样的人？连风和海也听从他了！'),
('CUV', '马太福音', 40, 8, 28, '耶稣既渡到那边去，来到加大拉人的地方，就有两个被鬼附的人从坟茔里出来迎著他，极其凶猛，甚至没有人能从那条路上经过。'),
('CUV', '马太福音', 40, 8, 29, '他们喊著说：神的儿子，我们与你有甚么相干？时候还没有到，你就上这里来叫我们受苦么？'),
('CUV', '马太福音', 40, 8, 30, '离他们很远，有一大群猪吃食。'),
('CUV', '马太福音', 40, 8, 31, '鬼就央求耶稣，说：若把我们赶出去，就打发我们进入猪群罢！'),
('CUV', '马太福音', 40, 8, 32, '耶稣说：去罢！鬼就出来，进入猪群。全群忽然闯下山崖，投在海里淹死了。'),
('CUV', '马太福音', 40, 8, 33, '放猪的就逃跑进城，将这一切事和被鬼附的人所遭遇的都告诉人。'),
('CUV', '马太福音', 40, 8, 34, '合城的人都出来迎见耶稣，既见了就央求他离开他们的境界。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 9, 1, '耶稣上了船，渡过海，来到自己的城里。'),
('CUV', '马太福音', 40, 9, 2, '有人用褥子抬著一个瘫子到耶稣跟前来。耶稣见他们的信心，就对瘫子说：小子，放心罢！你的罪赦了。'),
('CUV', '马太福音', 40, 9, 3, '有几个文士心里说：这个人说僭妄的话了。'),
('CUV', '马太福音', 40, 9, 4, '耶稣知道他们的心意，就说：你们为甚么心里怀著恶念呢？'),
('CUV', '马太福音', 40, 9, 5, '或说：你的罪赦了，或说：你起来行走，那一样容易呢？'),
('CUV', '马太福音', 40, 9, 6, '但要叫你们知道，人子在地上有赦罪的权柄；就对瘫子说：起来！拿你的褥子回家去罢。'),
('CUV', '马太福音', 40, 9, 7, '那人就起来，回家去了。'),
('CUV', '马太福音', 40, 9, 8, '众人看见都惊奇，就归荣耀与神，因为他将这样的权柄赐给人。'),
('CUV', '马太福音', 40, 9, 9, '耶稣从那里往前走，看见一个人名叫马太，坐在税关上，就对他说：你跟从我来。他就起来跟从了耶稣。'),
('CUV', '马太福音', 40, 9, 10, '耶稣在屋里坐席的时候，有好些税吏和罪人来，与耶稣和他的门徒一同坐席。'),
('CUV', '马太福音', 40, 9, 11, '法利赛人看见，就对耶稣的门徒说：你们的先生为甚么和税吏并罪人一同吃饭呢？'),
('CUV', '马太福音', 40, 9, 12, '耶稣听见，就说：康健的人用不著医生，有病的人才用得著。'),
('CUV', '马太福音', 40, 9, 13, '经上说：我喜爱怜恤，不喜爱祭祀。这句话的意思，你们且去揣摩。我来本不是召义人，乃是召罪人。'),
('CUV', '马太福音', 40, 9, 14, '那时，约翰的门徒来见耶稣，说：我们和法利赛人常常禁食，你的门徒倒不禁食，这是为甚么呢？'),
('CUV', '马太福音', 40, 9, 15, '耶稣对他们说：新郎和陪伴之人同在的时候，陪伴之人岂能哀恸呢？但日子将到，新郎要离开他们，那时候他们就要禁食。'),
('CUV', '马太福音', 40, 9, 16, '没有人把新布补在旧衣服上；因为所补上的反带坏了那衣服，破的就更大了。'),
('CUV', '马太福音', 40, 9, 17, '也没有人把新酒装在旧皮袋里；若是这样，皮袋就裂开，酒漏出来，连皮袋也坏了。惟独把新酒装在新皮袋里，两样就都保全了。'),
('CUV', '马太福音', 40, 9, 18, '耶稣说这话的时候，有一个管会堂的来拜他，说：我女儿刚才死了，求你去按手在他身上，他就必活了。'),
('CUV', '马太福音', 40, 9, 19, '耶稣便起来跟著他去；门徒也跟了去。'),
('CUV', '马太福音', 40, 9, 20, '有一个女人，患了十二年的血漏，来到耶稣背后，摸他的衣裳䍁子；'),
('CUV', '马太福音', 40, 9, 21, '因为他心里说：我只摸他的衣裳，就必痊愈。'),
('CUV', '马太福音', 40, 9, 22, '耶稣转过来，看见他，就说：女儿，放心！你的信救了你。从那时候，女人就痊愈了。'),
('CUV', '马太福音', 40, 9, 23, '耶稣到了管会堂的家里，看见有吹手，又有许多人乱嚷，'),
('CUV', '马太福音', 40, 9, 24, '就说：退去罢！这闺女不是死了，是睡著了。他们就嗤笑他。'),
('CUV', '马太福音', 40, 9, 25, '众人既被撵出，耶稣就进去，拉著闺女的手，闺女便起来了。'),
('CUV', '马太福音', 40, 9, 26, '于是这风声传遍了那地方。'),
('CUV', '马太福音', 40, 9, 27, '耶稣从那里往前走，有两个瞎子跟著他，喊叫说：大卫的子孙，可怜我们罢！'),
('CUV', '马太福音', 40, 9, 28, '耶稣进了房子，瞎子就来到他跟前。耶稣说：你们信我能作这事么？他们说：主阿，我们信。'),
('CUV', '马太福音', 40, 9, 29, '耶稣就摸他们的眼睛，说：照著你们的信给你们成全了罢。'),
('CUV', '马太福音', 40, 9, 30, '他们的眼睛就开了。耶稣切切的嘱咐他们说：你们要小心，不可叫人知道。'),
('CUV', '马太福音', 40, 9, 31, '他们出去，竟把他的名声传遍了那地方。'),
('CUV', '马太福音', 40, 9, 32, '他们出去的时候，有人将鬼所附的一个哑吧带到耶稣跟前来。'),
('CUV', '马太福音', 40, 9, 33, '鬼被赶出去，哑吧就说出话来。众人都希奇，说：在以色列中，从来没有见过这样的事。'),
('CUV', '马太福音', 40, 9, 34, '法利赛人却说：他是靠著鬼王赶鬼。'),
('CUV', '马太福音', 40, 9, 35, '耶稣走遍各城各乡，在会堂里教训人，宣讲天国的福音，又医治各样的病症。'),
('CUV', '马太福音', 40, 9, 36, '他看见许多的人，就怜悯他们；因为他们困苦流离，如同羊没有牧人一般。'),
('CUV', '马太福音', 40, 9, 37, '于是对门徒说：要收的庄稼多，作工的人少。'),
('CUV', '马太福音', 40, 9, 38, '所以，你们当求庄稼的主打发工人出去收他的庄稼。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 10, 1, '耶稣叫了十二个门徒来，给他们权柄，能赶逐污鬼，并医治各样的病症。'),
('CUV', '马太福音', 40, 10, 2, '这十二使徒的名：头一个叫西门、又称彼得，还有他兄弟安得烈，西庇太的儿子雅各和雅各的兄弟约翰，'),
('CUV', '马太福音', 40, 10, 3, '腓力和巴多罗买，多马和税吏马太，亚勒腓的儿子雅各，和达太，'),
('CUV', '马太福音', 40, 10, 4, '奋锐党的西门，还有卖耶稣的加略人犹大。'),
('CUV', '马太福音', 40, 10, 5, '耶稣差这十二个人去，吩咐他们说：外邦人的路，你们不要走；撒玛利亚人的城，你们不要进；'),
('CUV', '马太福音', 40, 10, 6, '宁可往以色列家迷失的羊那里去。'),
('CUV', '马太福音', 40, 10, 7, '随走随传，说天国近了！'),
('CUV', '马太福音', 40, 10, 8, '医治病人，叫死人复活，叫长大痲疯的洁净，把鬼赶出去。你们白白的得来，也要白白的舍去。'),
('CUV', '马太福音', 40, 10, 9, '腰袋里不要带金银铜钱。'),
('CUV', '马太福音', 40, 10, 10, '行路不要带口袋；不要带两件褂子，也不要带鞋和拐杖。因为工人得饮食是应当的。'),
('CUV', '马太福音', 40, 10, 11, '你们无论进那一城，那一村，要打听那里谁是好人，就住在他家，直住到走的时候。'),
('CUV', '马太福音', 40, 10, 12, '进他家里去，要请他的安。'),
('CUV', '马太福音', 40, 10, 13, '那家若配得平安，你们所求的平安就必临到那家；若不配得，你们所求的平安仍归你们。'),
('CUV', '马太福音', 40, 10, 14, '凡不接待你们、不听你们话的人，你们离开那家，或是那城的时候，就把脚上的尘土跺下去。'),
('CUV', '马太福音', 40, 10, 15, '我实在告诉你们，当审判的日子，所多玛和蛾摩拉所受的，比那城还容易受呢！'),
('CUV', '马太福音', 40, 10, 16, '我差你们去，如同羊进入狼群；所以你们要灵巧像蛇，驯良像鸽子。'),
('CUV', '马太福音', 40, 10, 17, '你们要防备人；因为他们要把你们交给公会，也要在会堂里鞭打你们，'),
('CUV', '马太福音', 40, 10, 18, '并且你们要为我的缘故被送到诸侯君王面前，对他们和外邦人作见证。'),
('CUV', '马太福音', 40, 10, 19, '你们被交的时候，不要思虑怎样说话，或说甚么话。到那时候，必赐给你们当说的话；'),
('CUV', '马太福音', 40, 10, 20, '因为不是你们自己说的，乃是你们父的灵在你们里头说的。'),
('CUV', '马太福音', 40, 10, 21, '弟兄要把弟兄，父亲要把儿子，送到死地；儿女要与父母为敌，害死他们；'),
('CUV', '马太福音', 40, 10, 22, '并且你们要为我的名被众人恨恶。惟有忍耐到底的必然得救。'),
('CUV', '马太福音', 40, 10, 23, '有人在这城里逼迫你们，就逃到那城里去。我实在告诉你们，以色列的城邑，你们还没有走遍，人子就到了。'),
('CUV', '马太福音', 40, 10, 24, '学生不能高过先生；仆人不能高过主人。'),
('CUV', '马太福音', 40, 10, 25, '学生和先生一样，仆人和主人一样，也就罢了。人既骂家主是别西卜（别西卜：是鬼王的名），何况他的家人呢？'),
('CUV', '马太福音', 40, 10, 26, '所以，不要怕他们；因为掩盖的事没有不露出来的，隐藏的事没有不被人知道的。'),
('CUV', '马太福音', 40, 10, 27, '我在暗中告诉你们的，你们要在明处说出来；你们耳中所听的，要在房上宣扬出来。'),
('CUV', '马太福音', 40, 10, 28, '那杀身体，不能杀灵魂的，不要怕他们；惟有能把身体和灵魂都灭在地狱里的，正要怕他。'),
('CUV', '马太福音', 40, 10, 29, '两个麻雀不是卖一分银子么？若是你们的父不许，一个也不能掉在地上；'),
('CUV', '马太福音', 40, 10, 30, '就是你们的头发也都被数过了。'),
('CUV', '马太福音', 40, 10, 31, '所以，不要惧怕，你们比许多麻雀还贵重！'),
('CUV', '马太福音', 40, 10, 32, '凡在人面前认我的，我在我天上的父面前也必认他；'),
('CUV', '马太福音', 40, 10, 33, '凡在人面前不认我的，我在我天上的父面前也必不认他。'),
('CUV', '马太福音', 40, 10, 34, '你们不要想我来是叫地上太平；我来并不是叫地上太平，乃是叫地上动刀兵。'),
('CUV', '马太福音', 40, 10, 35, '因为我来是叫人与父亲生疏，女儿与母亲生疏，媳妇与婆婆生疏。'),
('CUV', '马太福音', 40, 10, 36, '人的仇敌就是自己家里的人。'),
('CUV', '马太福音', 40, 10, 37, '爱父母过于爱我的，不配作我的门徒；爱儿女过于爱我的，不配作我的门徒；'),
('CUV', '马太福音', 40, 10, 38, '不背著他的十字架跟从我的，也不配作我的门徒。'),
('CUV', '马太福音', 40, 10, 39, '得著生命的，将要失丧生命；为我失丧生命的，将要得著生命。'),
('CUV', '马太福音', 40, 10, 40, '人接待你们就是接待我；接待我就是接待那差我来的。'),
('CUV', '马太福音', 40, 10, 41, '人因为先知的名接待先知，必得先知所得的赏赐；人因为义人的名接待义人，必得义人所得的赏赐。'),
('CUV', '马太福音', 40, 10, 42, '无论何人，因为门徒的名，只把一杯凉水给这小子里的一个喝，我实在告诉你们，这人不能不得赏赐。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 11, 1, '耶稣吩咐完了十二个门徒，就离开那里，往各城去传道，教训人。'),
('CUV', '马太福音', 40, 11, 2, '约翰在监里听见基督所作的事，就打发两个门徒去，'),
('CUV', '马太福音', 40, 11, 3, '问他说：那将要来的是你么？还是我们等候别人呢？'),
('CUV', '马太福音', 40, 11, 4, '耶稣回答说：你们去，把所听见，所看见的事告诉约翰。'),
('CUV', '马太福音', 40, 11, 5, '就是瞎子看见，瘸子行走，长大痲疯的洁净，聋子听见，死人复活，穷人有福音传给他们。'),
('CUV', '马太福音', 40, 11, 6, '凡不因我跌倒的就有福了！'),
('CUV', '马太福音', 40, 11, 7, '他们走的时候，耶稣就对众人讲论约翰说：你们从前出到旷野是要看甚么呢？要看风吹动的芦苇么？'),
('CUV', '马太福音', 40, 11, 8, '你们出去到底是要看甚么？要看穿细软衣服的人么？那穿细软衣服的人是在王宫里。'),
('CUV', '马太福音', 40, 11, 9, '你们出去究竟是为甚么？是要看先知么？我告诉你们，是的，他比先知大多了。'),
('CUV', '马太福音', 40, 11, 10, '经上记著说：我要差遣我的使者在你前面预备道路，所说的就是这个人。'),
('CUV', '马太福音', 40, 11, 11, '我实在告诉你们，凡妇人所生的，没有一个兴起来大过施洗约翰的；然而天国里最小的比他还大。'),
('CUV', '马太福音', 40, 11, 12, '从施洗约翰的时候到如今，天国是努力进入的，努力的人就得著了。'),
('CUV', '马太福音', 40, 11, 13, '因为众先知和律法说预言，到约翰为止。'),
('CUV', '马太福音', 40, 11, 14, '你们若肯领受，这人就是那应当来的以利亚。'),
('CUV', '马太福音', 40, 11, 15, '有耳可听的，就应当听！'),
('CUV', '马太福音', 40, 11, 16, '我可用甚么比这世代呢？好像孩童坐在街市上招呼同伴，说：'),
('CUV', '马太福音', 40, 11, 17, '我们向你们吹笛，你们不跳舞；我们向你们举哀，你们不捶胸。'),
('CUV', '马太福音', 40, 11, 18, '约翰来了，也不吃也不喝，人就说他是被鬼附著的；'),
('CUV', '马太福音', 40, 11, 19, '人子来了，也吃也喝，人又说他是贪食好酒的人，是税吏和罪人的朋友。但智慧之子总以智慧为是（有古卷：但智慧在行为上就显为是）。'),
('CUV', '马太福音', 40, 11, 20, '耶稣在诸城中行了许多异能，那些城的人终不悔改，就在那时候责备他们，说：'),
('CUV', '马太福音', 40, 11, 21, '哥拉汛哪，你有祸了！伯赛大阿，你有祸了！因为在你们中间所行的异能，若行在推罗、西顿，他们早已披麻蒙灰悔改了。'),
('CUV', '马太福音', 40, 11, 22, '但我告诉你们，当审判的日子，推罗、西顿所受的，比你们还容易受呢！'),
('CUV', '马太福音', 40, 11, 23, '迦百农阿，你已经升到天上（或作：你将要升到天上么），将来必坠落阴间；因为在你那里所行的异能，若行在所多玛，他还可以存到今日。'),
('CUV', '马太福音', 40, 11, 24, '但我告诉你们，当审判的日子，所多玛所受的，比你还容易受呢！'),
('CUV', '马太福音', 40, 11, 25, '那时，耶稣说：父阿，天地的主，我感谢你！因为你将这些事向聪明通达人就藏起来，向婴孩就显出来。'),
('CUV', '马太福音', 40, 11, 26, '父阿，是的，因为你的美意本是如此。'),
('CUV', '马太福音', 40, 11, 27, '一切所有的，都是我父交付我的；除了父，没有人知道子；除了子和子所愿意指示的，没有人知道父。'),
('CUV', '马太福音', 40, 11, 28, '凡劳苦担重担的人可以到我这里来，我就使你们得安息。'),
('CUV', '马太福音', 40, 11, 29, '我心里柔和谦卑，你们当负我的轭，学我的样式；这样，你们心里就必得享安息。'),
('CUV', '马太福音', 40, 11, 30, '因为我的轭是容易的，我的担子是轻省的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 12, 1, '那时，耶稣在安息日从麦地经过。他的门徒饿了，就掐起麦穗来吃。'),
('CUV', '马太福音', 40, 12, 2, '法利赛人看见，就对耶稣说：看哪，你的门徒作安息日不可作的事了！'),
('CUV', '马太福音', 40, 12, 3, '耶稣对他们说：经上记著大卫和跟从他的人饥饿之时所作的事，你们没有念过么？'),
('CUV', '马太福音', 40, 12, 4, '他怎么进了神的殿，吃了陈设饼，这饼不是他和跟从他的人可以吃得，惟独祭司才可以吃。'),
('CUV', '马太福音', 40, 12, 5, '再者，律法上所记的，当安息日，祭司在殿里犯了安息日还是没有罪，你们没有念过么？'),
('CUV', '马太福音', 40, 12, 6, '但我告诉你们，在这里有一人比殿更大。'),
('CUV', '马太福音', 40, 12, 7, '我喜爱怜恤，不喜爱祭祀。你们若明白这话的意思，就不将无罪的当作有罪的了。'),
('CUV', '马太福音', 40, 12, 8, '因为人子是安息日的主。'),
('CUV', '马太福音', 40, 12, 9, '耶稣离开那地方，进了一个会堂。'),
('CUV', '马太福音', 40, 12, 10, '那里有一个人枯干了一只手。有人问耶稣说：安息日治病可以不可以？意思是要控告他。'),
('CUV', '马太福音', 40, 12, 11, '耶稣说：你们中间谁有一只羊，当安息日掉在坑里，不把他抓住，拉上来呢？'),
('CUV', '马太福音', 40, 12, 12, '人比羊何等贵重呢！所以，在安息日作善事是可以的。'),
('CUV', '马太福音', 40, 12, 13, '于是对那人说：伸出手来！他把手一伸，手就复了原，和那只手一样。'),
('CUV', '马太福音', 40, 12, 14, '法利赛人出去，商议怎样可以除灭耶稣。'),
('CUV', '马太福音', 40, 12, 15, '耶稣知道了，就离开那里，有许多人跟著他。他把其中有病的人都治好了；'),
('CUV', '马太福音', 40, 12, 16, '又嘱咐他们，不要给他传名。'),
('CUV', '马太福音', 40, 12, 17, '这是要应验先知以赛亚的话，说：'),
('CUV', '马太福音', 40, 12, 18, '看哪！我的仆人，我所拣选，所亲爱，心里所喜悦的，我要将我的灵赐给他；他必将公理传给外邦。'),
('CUV', '马太福音', 40, 12, 19, '他不争竞，不喧嚷；街上也没有人听见他的声音。'),
('CUV', '马太福音', 40, 12, 20, '压伤的芦苇，他不折断；将残的灯火，他不吹灭；等他施行公理，叫公理得胜。'),
('CUV', '马太福音', 40, 12, 21, '外邦人都要仰望他的名。'),
('CUV', '马太福音', 40, 12, 22, '当下，有人将一个被鬼附著、又瞎又哑的人带到耶稣那里，耶稣就医治他，甚至那哑吧又能说话，又能看见。'),
('CUV', '马太福音', 40, 12, 23, '众人都惊奇，说：这不是大卫的子孙么？'),
('CUV', '马太福音', 40, 12, 24, '但法利赛人听见，就说：这个人赶鬼，无非是靠著鬼王别西卜阿。'),
('CUV', '马太福音', 40, 12, 25, '耶稣知道他们的意念，就对他们说：凡一国自相纷争，就成为荒场；一城一家自相纷争，必站立不住；'),
('CUV', '马太福音', 40, 12, 26, '若撒但赶逐撒但，就是自相纷争，他的国怎能站得住呢？'),
('CUV', '马太福音', 40, 12, 27, '我若靠著别西卜赶鬼，你们的子弟赶鬼又靠著谁呢？这样，他们就要断定你们的是非。'),
('CUV', '马太福音', 40, 12, 28, '我若靠著神的灵赶鬼，这就是神的国临到你们.了。'),
('CUV', '马太福音', 40, 12, 29, '人怎能进壮士家里，抢夺他的家具呢？除非先捆住那壮士，才可以抢夺他的家财。'),
('CUV', '马太福音', 40, 12, 30, '不与我相合的，就是敌我的；不同我收聚的，就是分散的。'),
('CUV', '马太福音', 40, 12, 31, '所以我告诉你们：人一切的罪和亵渎的话都可得赦免，惟独亵渎圣灵，总不得赦免。'),
('CUV', '马太福音', 40, 12, 32, '凡说话干犯人子的，还可得赦免；惟独说话干犯圣灵的，今世来世总不得赦免。'),
('CUV', '马太福音', 40, 12, 33, '你们或以为树好，果子也好；树坏，果子也坏；因为看果子就可以知道树。'),
('CUV', '马太福音', 40, 12, 34, '毒蛇的种类！你们既是恶人，怎能说出好话来呢？因为心里所充满的，口里就说出来。'),
('CUV', '马太福音', 40, 12, 35, '善人从他心里所存的善就发出善来；恶人从他心里所存的恶就发出恶来。'),
('CUV', '马太福音', 40, 12, 36, '我又告诉你们，凡人所说的闲话，当审判的日子，必要句句供出来；'),
('CUV', '马太福音', 40, 12, 37, '因为要凭你的话定你为义，也要凭你的话定你有罪。'),
('CUV', '马太福音', 40, 12, 38, '当时，有几个文士和法利赛人对耶稣说：夫子，我们愿意你显个神迹给我们看。'),
('CUV', '马太福音', 40, 12, 39, '耶稣回答说：一个邪恶淫乱的世代求看神迹，除了先知约拿的神迹以外，再没有神迹给他们看。'),
('CUV', '马太福音', 40, 12, 40, '约拿三日三夜在大鱼肚腹中，人子也要这样三日三夜在地里头。'),
('CUV', '马太福音', 40, 12, 41, '当审判的时候，尼尼微人要起来定这世代的罪，因为尼尼微人听了约拿所传的就悔改了。看哪，在这里有一人比约拿更大！'),
('CUV', '马太福音', 40, 12, 42, '当审判的时候，南方的女王要起来定这世代的罪，因为他从地极而来，要听所罗门的智慧话。看哪！在这里有一人比所罗门更大。'),
('CUV', '马太福音', 40, 12, 43, '污鬼离了人身，就在无水之地过来过去，寻求安歇之处，却寻不著。'),
('CUV', '马太福音', 40, 12, 44, '于是说：我要回到我所出来的屋里去。到了，就看见里面空闲，打扫干净，修饰好了，'),
('CUV', '马太福音', 40, 12, 45, '便去另带了七个比自己更恶的鬼来，都进去住在那里。那人末后的景况比先前更不好了。这邪恶的世代也要如此。'),
('CUV', '马太福音', 40, 12, 46, '耶稣还对众人说话的时候，不料他母亲和他弟兄站在外边，要与他说话。'),
('CUV', '马太福音', 40, 12, 47, '有人告诉他说：看哪，你母亲和你弟兄站在外边，要与你说话。'),
('CUV', '马太福音', 40, 12, 48, '他却回答那人说：谁是我的母亲？谁是我的弟兄？'),
('CUV', '马太福音', 40, 12, 49, '就伸手指著门徒，说：看哪，我的母亲，我的弟兄。'),
('CUV', '马太福音', 40, 12, 50, '凡遵行我天父旨意的人，就是我的弟兄姐妹和母亲了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 13, 1, '当那一天，耶稣从房子里出来，坐在海边。'),
('CUV', '马太福音', 40, 13, 2, '有许多人到他那里聚集，他只得上船坐下，众人都站在岸上。'),
('CUV', '马太福音', 40, 13, 3, '他用比喻对他们讲许多道理，说：有一个撒种的出去撒种；'),
('CUV', '马太福音', 40, 13, 4, '撒的时候，有落在路旁的，飞鸟来吃尽了；'),
('CUV', '马太福音', 40, 13, 5, '有落在土浅石头地上的，土既不深，发苗最快，'),
('CUV', '马太福音', 40, 13, 6, '日头出来一晒，因为没有根，就枯干了；'),
('CUV', '马太福音', 40, 13, 7, '有落在荆棘里的，荆棘长起来，把他挤住了；'),
('CUV', '马太福音', 40, 13, 8, '又有落在好土里的，就结实，有一百倍的，有六十倍的，有三十倍的。'),
('CUV', '马太福音', 40, 13, 9, '有耳可听的，就应当听！'),
('CUV', '马太福音', 40, 13, 10, '门徒进前来，问耶稣说：对众人讲话，为甚么用比喻呢？'),
('CUV', '马太福音', 40, 13, 11, '耶稣回答说：因为天国的奥秘只叫你们知道，不叫他们知道。'),
('CUV', '马太福音', 40, 13, 12, '凡有的，还要加给他，叫他有余；凡没有的，连他所有的，也要夺去。'),
('CUV', '马太福音', 40, 13, 13, '所以我用比喻对他们讲，是因他们看也看不见，听也听不见，也不明白。'),
('CUV', '马太福音', 40, 13, 14, '在他们身上，正应了以赛亚的预言，说：你们听是要听见，却不明白；看是要看见，却不晓得；'),
('CUV', '马太福音', 40, 13, 15, '因为这百姓油蒙了心，耳朵发沉，眼睛闭著，恐怕眼睛看见，耳朵听见，心里明白，回转过来，我就医治他们。'),
('CUV', '马太福音', 40, 13, 16, '但你们的眼睛是有福的，因为看见了；你们的耳朵也是有福的，因为听见了。'),
('CUV', '马太福音', 40, 13, 17, '我实在告诉你们，从前有许多先知和义人要看你们所看的，却没有看见，要听你们所听的，却没有听见。'),
('CUV', '马太福音', 40, 13, 18, '所以，你们当听这撒种的比喻。'),
('CUV', '马太福音', 40, 13, 19, '凡听见天国道理不明白的，那恶者就来，把所撒在他心里的夺了去；这就是撒在路旁的了。'),
('CUV', '马太福音', 40, 13, 20, '撒在石头地上的，就是人听了道，当下欢喜领受，'),
('CUV', '马太福音', 40, 13, 21, '只因心里没有根，不过是暂时的，及至为道遭了患难，或是受了逼迫，立刻就跌倒了。'),
('CUV', '马太福音', 40, 13, 22, '撒在荆棘里的，就是人听了道，后来有世上的思虑、钱财的迷惑把道挤住了，不能结实。'),
('CUV', '马太福音', 40, 13, 23, '撒在好地上的，就是人听道明白了，后来结实，有一百倍的，有六十倍的，有三十倍的。'),
('CUV', '马太福音', 40, 13, 24, '耶稣又设个比喻对他们说：天国好像人撒好种在田里，'),
('CUV', '马太福音', 40, 13, 25, '及至人睡觉的时候，有仇敌来，将稗子撒在麦子里就走了。'),
('CUV', '马太福音', 40, 13, 26, '到长苗吐穗的时候，稗子也显出来。'),
('CUV', '马太福音', 40, 13, 27, '田主的仆人来告诉他说：主阿，你不是撒好种在田里么？从那里来的稗子呢？'),
('CUV', '马太福音', 40, 13, 28, '主人说：这是仇敌做的。仆人说：你要我们去薅出来么？'),
('CUV', '马太福音', 40, 13, 29, '主人说：不必，恐怕薅稗子，连麦子也拔出来。'),
('CUV', '马太福音', 40, 13, 30, '容这两样一齐长，等著收割。当收割的时候，我要对收割的人说，先将稗子薅出来，捆成捆，留著烧；惟有麦子要收在仓里。'),
('CUV', '马太福音', 40, 13, 31, '他又设个比喻对他们说：天国好像一粒芥菜种，有人拿去种在田里。'),
('CUV', '马太福音', 40, 13, 32, '这原是百种里最小的，等到长起来，却比各样的菜都大，且成了树，天上的飞鸟来宿在他的枝上。'),
('CUV', '马太福音', 40, 13, 33, '他又对他们讲个比喻说：天国好像面酵，有妇人拿来，藏在三斗面里，直等全团都发起来。'),
('CUV', '马太福音', 40, 13, 34, '这都是耶稣用比喻对众人说的话；若不用比喻，就不对他们说甚么。'),
('CUV', '马太福音', 40, 13, 35, '这是要应验先知的话，说：我要开口用比喻，把创世以来所隐藏的事发明出来。'),
('CUV', '马太福音', 40, 13, 36, '当下，耶稣离开众人，进了房子。他的门徒进前来，说：请把田间稗子的比喻讲给我们听。'),
('CUV', '马太福音', 40, 13, 37, '他回答说：那撒好种的就是人子；'),
('CUV', '马太福音', 40, 13, 38, '田地就是世界；好种就是天国之子；稗子就是那恶者之子；'),
('CUV', '马太福音', 40, 13, 39, '撒稗子的仇敌就是魔鬼；收割的时候就是世界的末了；收割的人就是天使。'),
('CUV', '马太福音', 40, 13, 40, '将稗子薅出来用火焚烧，世界的末了也要如此。'),
('CUV', '马太福音', 40, 13, 41, '人子要差遣使者，把一切叫人跌倒的和作恶的，从他国里挑出来，'),
('CUV', '马太福音', 40, 13, 42, '丢在火炉里；在那里必要哀哭切齿了。'),
('CUV', '马太福音', 40, 13, 43, '那时，义人在他们父的国里，要发出光来，像太阳一样。有耳可听的，就应当听！'),
('CUV', '马太福音', 40, 13, 44, '天国好像宝贝藏在地里，人遇见了就把他藏起来，欢欢喜喜的去变卖一切所有的，买这块地。'),
('CUV', '马太福音', 40, 13, 45, '天国又好像买卖人寻找好珠子，'),
('CUV', '马太福音', 40, 13, 46, '遇见一颗重价的珠子，就去变卖他一切所有的，买了这颗珠子。'),
('CUV', '马太福音', 40, 13, 47, '天国又好像网撒在海里，聚拢各样水族，'),
('CUV', '马太福音', 40, 13, 48, '网既满了，人就拉上岸来，坐下，拣好的收在器具里，将不好的丢弃了。'),
('CUV', '马太福音', 40, 13, 49, '世界的末了也要这样。天使要出来，从义人中把恶人分别出来，'),
('CUV', '马太福音', 40, 13, 50, '丢在火炉里；在那里必要哀哭切齿了。'),
('CUV', '马太福音', 40, 13, 51, '耶稣说：这一切的话你们都明白了么？他们说：我们明白了。'),
('CUV', '马太福音', 40, 13, 52, '他说：凡文士受教作天国的门徒，就像一个家主从他库里拿出新旧的东西来。'),
('CUV', '马太福音', 40, 13, 53, '耶稣说完了这些比喻，就离开那里，'),
('CUV', '马太福音', 40, 13, 54, '来到自己的家乡，在会堂里教训人，甚至他们都希奇，说：这人从那里有这等智慧和异能呢？'),
('CUV', '马太福音', 40, 13, 55, '这不是木匠的儿子么？他母亲不是叫马利亚么？他弟兄们不是叫雅各、约西（有古卷：约瑟）、西门、犹大么？'),
('CUV', '马太福音', 40, 13, 56, '他妹妹们不是都在我们这里么？这人从那里有这一切的事呢？'),
('CUV', '马太福音', 40, 13, 57, '他们就厌弃他（厌弃他：原文是因他跌倒）。耶稣对他们说：大凡先知，除了本地本家之外，没有不被人尊敬的。'),
('CUV', '马太福音', 40, 13, 58, '耶稣因为他们不信，就在那里不多行异能了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 14, 1, '那时，分封的王希律听见耶稣的名声，'),
('CUV', '马太福音', 40, 14, 2, '就对臣仆说：这是施洗的约翰从死里复活，所以这些异能从他里面发出来。'),
('CUV', '马太福音', 40, 14, 3, '起先，希律为他兄弟腓力的妻子希罗底的缘故，把约翰拿住，锁在监里。'),
('CUV', '马太福音', 40, 14, 4, '因为约翰曾对他说：你娶这妇人是不合理的。'),
('CUV', '马太福音', 40, 14, 5, '希律就想要杀他，只是怕百姓，因为他们以约翰为先知。'),
('CUV', '马太福音', 40, 14, 6, '到了希律的生日，希罗底的女儿在众人面前跳舞，使希律欢喜。'),
('CUV', '马太福音', 40, 14, 7, '希律就起誓，应许随他所求的给他。'),
('CUV', '马太福音', 40, 14, 8, '女儿被母亲所使，就说：请把施洗约翰的头放在盘子里，拿来给我。'),
('CUV', '马太福音', 40, 14, 9, '王便}忧愁，但因他所起的誓，又因同席的人，就吩咐给他；'),
('CUV', '马太福音', 40, 14, 10, '于是打发人去，在监里斩了约翰，'),
('CUV', '马太福音', 40, 14, 11, '把头放在盘子里，拿来给了女子；女子拿去给他母亲。'),
('CUV', '马太福音', 40, 14, 12, '约翰的门徒来，把尸首领去埋葬了，就去告诉耶稣。'),
('CUV', '马太福音', 40, 14, 13, '耶稣听见了，就上船从那里独自退到野地里去。众人听见，就从各城里步行跟随他。'),
('CUV', '马太福音', 40, 14, 14, '耶稣出来，见有许多的人，就怜悯他们，治好了他们的病人。'),
('CUV', '马太福音', 40, 14, 15, '天将晚的时候，门徒进前来，说：这是野地，时候已经过了，请叫众人散开，他们好往村子里去，自己买吃的。'),
('CUV', '马太福音', 40, 14, 16, '耶稣说：不用他们去，你们给他们吃罢！'),
('CUV', '马太福音', 40, 14, 17, '门徒说：我们这里只有五个饼，两条鱼。'),
('CUV', '马太福音', 40, 14, 18, '耶稣说：拿过来给我。'),
('CUV', '马太福音', 40, 14, 19, '于是吩咐众人坐在草地上，就拿著这五个饼，两条鱼，望著天祝福，擘开饼，递给门徒，门徒又递给众人。'),
('CUV', '马太福音', 40, 14, 20, '他们都吃，并且吃饱了；把剩下的零碎收拾起来，装满了十二个篮子。'),
('CUV', '马太福音', 40, 14, 21, '吃的人，除了妇女孩子，约有五千。'),
('CUV', '马太福音', 40, 14, 22, '耶稣随即催门徒上船，先渡到那边去，等他叫众人散开。'),
('CUV', '马太福音', 40, 14, 23, '散了众人以后，他就独自上山去祷告。到了晚上，只有他一人在那里。'),
('CUV', '马太福音', 40, 14, 24, '那时船在海中，因风不顺，被浪摇撼。'),
('CUV', '马太福音', 40, 14, 25, '夜里四更天，耶稣在海面上走，往门徒那里去。'),
('CUV', '马太福音', 40, 14, 26, '门徒看见他在海面上走，就惊慌了，说：是个鬼怪！便害怕，喊叫起来。'),
('CUV', '马太福音', 40, 14, 27, '耶稣连忙对他们说：你们放心！是我，不要怕！'),
('CUV', '马太福音', 40, 14, 28, '彼得说：主，如果是你，请叫我从水面上走到你那里去。'),
('CUV', '马太福音', 40, 14, 29, '耶稣说：你来罢。彼得就从船上下去，在水面上走，要到耶稣那里去；'),
('CUV', '马太福音', 40, 14, 30, '只因见风甚大，就害怕，将要沉下去，便喊著说：主阿，救我！'),
('CUV', '马太福音', 40, 14, 31, '耶稣赶紧伸手拉住他，说：你这小信的人哪，为甚么疑惑呢？'),
('CUV', '马太福音', 40, 14, 32, '他们上了船，风就住了。'),
('CUV', '马太福音', 40, 14, 33, '在船上的人都拜他，说：你真是神的儿子了。'),
('CUV', '马太福音', 40, 14, 34, '他们过了海，来到革尼撒勒地方。'),
('CUV', '马太福音', 40, 14, 35, '那里的人一认出是耶稣，就打发人到周围地方去，把所有的病人带到他那里，'),
('CUV', '马太福音', 40, 14, 36, '只求耶稣准他们摸他的衣裳䍁子；摸著的人就都好了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 15, 1, '那时，有法利赛人和文士从耶路撒冷来见耶稣，说：'),
('CUV', '马太福音', 40, 15, 2, '你的门徒为甚么犯古人的遗传呢？因为吃饭的时候，他们不洗手。'),
('CUV', '马太福音', 40, 15, 3, '耶稣回答说：你们为甚么因著你们的遗传犯神的诫命呢？'),
('CUV', '马太福音', 40, 15, 4, '神说：当孝敬父母；又说：咒骂父母的，必治死他。'),
('CUV', '马太福音', 40, 15, 5, '你们倒说：无论何人对父母说：我所当奉给你的已经作了供献，'),
('CUV', '马太福音', 40, 15, 6, '他就可以不孝敬父母。这就是你们藉著遗传，废了神的诫命。'),
('CUV', '马太福音', 40, 15, 7, '假冒为善的人哪，以赛亚指著你们说的预言是不错的。他说：'),
('CUV', '马太福音', 40, 15, 8, '这百姓用嘴唇尊敬我，心却远离我；'),
('CUV', '马太福音', 40, 15, 9, '他们将人的吩咐当作道理教导人，所以拜我也是枉然。'),
('CUV', '马太福音', 40, 15, 10, '耶稣就叫了众人来，对他们说：你们要听，也要明白。'),
('CUV', '马太福音', 40, 15, 11, '入口的不能污秽人，出口的乃能污秽人。'),
('CUV', '马太福音', 40, 15, 12, '当时，门徒进前来对他说：法利赛人听见这话，不服（原文是跌倒），你知道么？'),
('CUV', '马太福音', 40, 15, 13, '耶稣回答说：凡栽种的物，若不是我天父栽种的，必要拔出来。'),
('CUV', '马太福音', 40, 15, 14, '任凭他们罢！他们是瞎眼领路的；若是瞎子领瞎子，两个人都要掉在坑里。'),
('CUV', '马太福音', 40, 15, 15, '彼得对耶稣说：请将这比喻讲给我们听。'),
('CUV', '马太福音', 40, 15, 16, '耶稣说：你们到如今还不明白么？'),
('CUV', '马太福音', 40, 15, 17, '岂不知凡入口的，是运到肚子里，又落在茅厕里么？'),
('CUV', '马太福音', 40, 15, 18, '惟独出口的，是从心里发出来的，这才污秽人。'),
('CUV', '马太福音', 40, 15, 19, '因为从心里发出来的，有恶念、凶杀、奸淫、苟合、偷盗、妄证、谤讟。'),
('CUV', '马太福音', 40, 15, 20, '这都是污秽人的；至于不洗手吃饭，那却不污秽人。'),
('CUV', '马太福音', 40, 15, 21, '耶稣离开那里，退到推罗、西顿的境内去。'),
('CUV', '马太福音', 40, 15, 22, '有一个迦南妇人，从那地方出来，喊著说：主阿，大卫的子孙，可怜我！我女儿被鬼附得甚苦。'),
('CUV', '马太福音', 40, 15, 23, '耶稣却一言不答。门徒进前来，求他说：这妇人在我们后头喊叫，请打发他走罢。'),
('CUV', '马太福音', 40, 15, 24, '耶稣说：我奉差遣不过是到以色列家迷失的羊那里去。'),
('CUV', '马太福音', 40, 15, 25, '那妇人来拜他，说：主阿，帮助我！'),
('CUV', '马太福音', 40, 15, 26, '他回答说：不好拿儿女的饼丢给狗吃。'),
('CUV', '马太福音', 40, 15, 27, '妇人说：主阿，不错；但是狗也吃他主人桌子上掉下来的碎渣儿。'),
('CUV', '马太福音', 40, 15, 28, '耶稣说：妇人，你的信心是大的！照你所要的，给你成全了罢。从那时候，他女儿就好了。'),
('CUV', '马太福音', 40, 15, 29, '耶稣离开那地方，来到靠近加利利的海边，就上山坐下。'),
('CUV', '马太福音', 40, 15, 30, '有许多人到他那里，带著瘸子、瞎子、哑吧、有残疾的，和好些别的病人，都放在他脚前；他就治好了他们。'),
('CUV', '马太福音', 40, 15, 31, '甚至众人都希奇；因为看见哑吧说话，残疾的痊愈，瘸子行走，瞎子看见，他们就归荣耀给以色列的神。'),
('CUV', '马太福音', 40, 15, 32, '耶稣叫门徒来，说：我怜悯这众人，因为他们同我在这里已经三天，也没有吃的了。我不愿意叫他们饿著回去，恐怕在路上困乏。'),
('CUV', '马太福音', 40, 15, 33, '门徒说：我们在这野地，那里有这么多的饼叫这许多人吃饱呢？'),
('CUV', '马太福音', 40, 15, 34, '耶稣说：你们有多少饼？他们说：有七个，还有几条小鱼。'),
('CUV', '马太福音', 40, 15, 35, '他就吩咐众人坐在地上，'),
('CUV', '马太福音', 40, 15, 36, '拿著这七个饼和几条鱼，祝谢了，擘开，递给门徒；门徒又递给众人。'),
('CUV', '马太福音', 40, 15, 37, '众人都吃，并且吃饱了，收拾剩下的零碎，装满了七个筐子。'),
('CUV', '马太福音', 40, 15, 38, '吃的人，除了妇女孩子，共有四千。'),
('CUV', '马太福音', 40, 15, 39, '耶稣叫众人散去，就上船，来到马加丹的境界。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 16, 1, '法利赛人和撒都该人来试探耶稣，请他从天上显个神迹给他们看。'),
('CUV', '马太福音', 40, 16, 2, '耶稣回答说：晚上天发红，你们就说：天必要晴。'),
('CUV', '马太福音', 40, 16, 3, '早晨天发红，又发黑，你们就说：今日必有风雨。你们知道分辨天上的气色，倒不能分辨这时候的神迹。'),
('CUV', '马太福音', 40, 16, 4, '一个邪恶淫乱的世代求神迹，除了约拿的神迹以外，再没有神迹给他看。耶稣就离开他们去了。'),
('CUV', '马太福音', 40, 16, 5, '门徒渡到那边去，忘了带饼。'),
('CUV', '马太福音', 40, 16, 6, '耶稣对他们说：你们要谨慎，防备法利赛人和撒都该人的酵。'),
('CUV', '马太福音', 40, 16, 7, '门徒彼此议论说：这是因为我们没有带饼罢。'),
('CUV', '马太福音', 40, 16, 8, '耶稣看出来，就说：你们这小信的人，为甚么因为没有饼彼此议论呢？'),
('CUV', '马太福音', 40, 16, 9, '你们还不明白么？不记得那五个饼分给五千人、又收拾了多少篮子的零碎么？'),
('CUV', '马太福音', 40, 16, 10, '也不记得那七个饼分给四千人、又收拾了多少筐子的零碎么？'),
('CUV', '马太福音', 40, 16, 11, '我对你们说：要防备法利赛人和撒都该人的酵，这话不是指著饼说的，你们怎么不明白呢？'),
('CUV', '马太福音', 40, 16, 12, '门徒这才晓得他说的不是叫他们防备饼的酵，乃是防备法利赛人和撒都该人的教训。'),
('CUV', '马太福音', 40, 16, 13, '耶稣到了该撒利亚腓立比的境内，就问门徒说：人说我（有古卷没有我字）人子是谁？'),
('CUV', '马太福音', 40, 16, 14, '他们说：有人说是施洗的约翰；有人说是以利亚；又有人说是耶利米或是先知里的一位。'),
('CUV', '马太福音', 40, 16, 15, '耶稣说：你们说我是谁？'),
('CUV', '马太福音', 40, 16, 16, '西门彼得回答说：你是基督，是永生神的儿子。'),
('CUV', '马太福音', 40, 16, 17, '耶稣对他说：西门巴约拿，你是有福的！因为这不是属血肉的指示你的，乃是我在天上的父指示的。'),
('CUV', '马太福音', 40, 16, 18, '我还告诉你，你是彼得，我要把我的教会建造在这磐石上；阴间的权柄（权柄：原文是门），不能胜过他。'),
('CUV', '马太福音', 40, 16, 19, '我要把天国的钥匙给你，凡你在地上所捆绑的，在天上也要捆绑；凡你在地上所释放的，在天上也要释放。'),
('CUV', '马太福音', 40, 16, 20, '当下，耶稣嘱咐门徒，不可对人说他是基督。'),
('CUV', '马太福音', 40, 16, 21, '从此，耶稣才指示门徒，他必须上耶路撒冷去，受长老、祭司长、文士许多的苦，并且被杀，第三日复活。'),
('CUV', '马太福音', 40, 16, 22, '彼得就拉著他，劝他说：主阿，万不可如此！这事必不临到你身上。'),
('CUV', '马太福音', 40, 16, 23, '耶稣转过来，对彼得说：撒但，退我后边去罢！你是绊我脚的；因为你不体贴神的意思，只体贴人的意思。'),
('CUV', '马太福音', 40, 16, 24, '于是耶稣对门徒说：若有人要跟从我，就当舍己，背起他的十字架来跟从我。'),
('CUV', '马太福音', 40, 16, 25, '因为，凡要救自己生命（生命：或作灵魂；下同）的，必丧掉生命；凡为我丧掉生命的，必得著生命。'),
('CUV', '马太福音', 40, 16, 26, '人若赚得全世界，赔上自己的生命，有甚么益处呢？人还能拿甚么换生命呢？'),
('CUV', '马太福音', 40, 16, 27, '人子要在他父的荣耀里，同著众使者降临；那时候，他要照各人的行为报应各人。'),
('CUV', '马太福音', 40, 16, 28, '我实在告诉你们，站在这里的，有人在没尝死味以前必看见人子降临在他的国里。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 17, 1, '过了六天，耶稣带著彼得、雅各，和雅各的兄弟约翰，暗暗的上了高山，'),
('CUV', '马太福音', 40, 17, 2, '就在他们面前变了形像，脸面明亮如日头，衣裳洁白如光。'),
('CUV', '马太福音', 40, 17, 3, '忽然，有摩西、以利亚向他们显现，同耶稣说话。'),
('CUV', '马太福音', 40, 17, 4, '彼得对耶稣说：主阿，我们在这里真好！你若愿意，我就在这里搭三座棚，一座为你，一座为摩西，一座为以利亚。'),
('CUV', '马太福音', 40, 17, 5, '说话之间，忽然有一朵光明的云彩遮盖他们，且有声音从云彩里出来，说：这是我的爱子，我所喜悦的。你们要听他！'),
('CUV', '马太福音', 40, 17, 6, '门徒听见﹐就俯伏在地，极其害怕。'),
('CUV', '马太福音', 40, 17, 7, '耶稣进前来，摸他们，说：起来，不要害怕！'),
('CUV', '马太福音', 40, 17, 8, '他们举目不见一人，只见耶稣在那里。'),
('CUV', '马太福音', 40, 17, 9, '下山的时候，耶稣吩咐他们说：人子还没有从死里复活，你们不要将所看见的告诉人。'),
('CUV', '马太福音', 40, 17, 10, '门徒问耶稣说：文士为甚么说以利亚必须先来？'),
('CUV', '马太福音', 40, 17, 11, '耶稣回答说：以利亚固然先来，并要复兴万事；'),
('CUV', '马太福音', 40, 17, 12, '只是我告诉你们，以利亚已经来了，人却不认识他，竟任意待他。人子也将要这样受他们的害。'),
('CUV', '马太福音', 40, 17, 13, '门徒这才明白耶稣所说的是指著施洗的约翰。'),
('CUV', '马太福音', 40, 17, 14, '耶稣和门徒到了众人那里，有一个人来见耶稣，跪下，说：'),
('CUV', '马太福音', 40, 17, 15, '主阿，怜悯我的儿子。他害癫痫的病很苦，屡次跌在火里，屡次跌在水里。'),
('CUV', '马太福音', 40, 17, 16, '我带他到你门徒那里，他们却不能医治他。'),
('CUV', '马太福音', 40, 17, 17, '耶稣说：嗳！这又不信又悖谬的世代阿，我在你们这里要到几时呢？我忍耐你们要到几时呢？把他带到我这里来罢！'),
('CUV', '马太福音', 40, 17, 18, '耶稣斥责那鬼，鬼就出来；从此孩子就痊愈了。'),
('CUV', '马太福音', 40, 17, 19, '门徒暗暗的到耶稣跟前，说：我们为甚么不能赶出那鬼呢？'),
('CUV', '马太福音', 40, 17, 20, '耶稣说：是因你们的信心小。我实在告诉你们，你们若有信心，像一粒芥菜种，就是对这座山说：你从这边挪到那边。他也必挪去；并且你们没有一件不能做的事了。'),
('CUV', '马太福音', 40, 17, 21, '至于这一类的鬼，若不祷告、禁食，他就不出来（或作：不能赶他出来）。'),
('CUV', '马太福音', 40, 17, 22, '他们还住在加利利的时候，耶稣对门徒说：人子将要被交在人手里。'),
('CUV', '马太福音', 40, 17, 23, '他们要杀害他，第三日他要复活。门徒就大大的忧愁。'),
('CUV', '马太福音', 40, 17, 24, '到了迦百农，有收丁税的人来见彼得，说：你们的先生不纳丁税（丁税约有半块钱）么？'),
('CUV', '马太福音', 40, 17, 25, '彼得说：纳。他进了屋子，耶稣先向他说：西门﹐你的意思如何？世上的君王向谁征收关税、丁税？是向自己的儿子呢？是向外人呢？'),
('CUV', '马太福音', 40, 17, 26, '彼得说：是向外人。耶稣说：既然如此，儿子就可以免税了。'),
('CUV', '马太福音', 40, 17, 27, '但恐怕触犯（触犯：原文是绊倒）他们，你且往海边去钓鱼，把先钓上来的鱼拿起来，开了他的口，必得一块钱，可以拿去给他们，作你我的税银。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 18, 1, '当时，门徒进前来，问耶稣说：天国里谁是最大的？'),
('CUV', '马太福音', 40, 18, 2, '耶稣便叫一个小孩子来，使他站在他们当中，'),
('CUV', '马太福音', 40, 18, 3, '说：我实在告诉你们，你们若不回转，变成小孩子的样式，断不得进天国。'),
('CUV', '马太福音', 40, 18, 4, '所以，凡自己谦卑像这小孩子的，他在天国里就是最大的。'),
('CUV', '马太福音', 40, 18, 5, '凡为我的名接待一个像这小孩子的，就是接待我。'),
('CUV', '马太福音', 40, 18, 6, '凡使这信我的一个小子跌倒的，倒不如把大磨石拴在这人的颈项上，沉在深海里。'),
('CUV', '马太福音', 40, 18, 7, '这世界有祸了，因为将人绊倒；绊倒人的事是免不了的，但那绊倒人的有祸了！'),
('CUV', '马太福音', 40, 18, 8, '倘若你一只手，或是一只脚，叫你跌倒，就砍下来丢掉。你缺一只手，或是一只脚，进入永生，强如有两手两脚被丢在永火里。'),
('CUV', '马太福音', 40, 18, 9, '倘若你一只眼叫你跌倒，就把他剜出来丢掉。你只有一只眼进入永生，强如有两只眼被丢在地狱的火里。'),
('CUV', '马太福音', 40, 18, 10, '你们要小心，不可轻看这小子里的一个；我告诉你们，他们的使者在天上，常见我天父的面。（有古卷在此有'),
('CUV', '马太福音', 40, 18, 11, '人子来，为要拯救失丧的人。）'),
('CUV', '马太福音', 40, 18, 12, '一个人若有一百只羊，一只走迷了路，你们的意思如何？他岂不撇下这九十九只，往山里去找那只迷路的羊么？'),
('CUV', '马太福音', 40, 18, 13, '若是找著了，我实在告诉你们，他为这一只羊欢喜，比为那没有迷路的九十九只欢喜还大呢！'),
('CUV', '马太福音', 40, 18, 14, '你们在天上的父也是这样，不愿意这小子里失丧一个。'),
('CUV', '马太福音', 40, 18, 15, '倘若你的弟兄得罪你，你就去，趁著只有他和你在一处的时候，指出他的错来。他若听你，你便得了你的弟兄；'),
('CUV', '马太福音', 40, 18, 16, '他若不听，你就另外带一两个人同去，要凭两三个人的口作见证，句句都可定准。'),
('CUV', '马太福音', 40, 18, 17, '若是不听他们，就告诉教会；若是不听教会，就看他像外邦人和税吏一样。'),
('CUV', '马太福音', 40, 18, 18, '我实在告诉你们，凡你们在地上所捆绑的，在天上也要捆绑；凡你们在地上所释放的，在天上也要释放。'),
('CUV', '马太福音', 40, 18, 19, '我又告诉你们，若是你们中间有两个人在地上同心合意的求甚么事，我在天上的父必为他们成全。'),
('CUV', '马太福音', 40, 18, 20, '因为无论在那里，有两三个人奉我的名聚会，那里就有我在他们中间。'),
('CUV', '马太福音', 40, 18, 21, '那时，彼得进前来，对耶稣说：主阿，我弟兄得罪我，我当饶恕他几次呢？到七次可以么？'),
('CUV', '马太福音', 40, 18, 22, '耶稣说：我对你说，不是到七次，乃是到七十个七次。'),
('CUV', '马太福音', 40, 18, 23, '天国好像一个王要和他仆人算账。'),
('CUV', '马太福音', 40, 18, 24, '才算的时候，有人带了一个欠一千万银子的来。'),
('CUV', '马太福音', 40, 18, 25, '因为他没有甚么偿还之物，主人吩咐把他和他妻子儿女，并一切所有的都卖了偿还。'),
('CUV', '马太福音', 40, 18, 26, '那仆人就俯伏拜他，说：主阿，宽容我，将来我都要还清。'),
('CUV', '马太福音', 40, 18, 27, '那仆人的主人就动了慈心，把他释放了，并且免了他的债。'),
('CUV', '马太福音', 40, 18, 28, '那仆人出来，遇见他的一个同伴欠他十两银子，便揪著他，掐住他的喉咙，说：你把所欠的还我！'),
('CUV', '马太福音', 40, 18, 29, '他的同伴就俯伏央求他，说：宽容我罢，将来我必还清。'),
('CUV', '马太福音', 40, 18, 30, '他不肯，竟去把他下在监里，等他还了所欠的债。'),
('CUV', '马太福音', 40, 18, 31, '众同伴看见他所做的事就甚忧愁，去把这事都告诉了主人。'),
('CUV', '马太福音', 40, 18, 32, '于是主人叫了他来，对他说：你这恶奴才！你央求我，我就把你所欠的都免了，'),
('CUV', '马太福音', 40, 18, 33, '你不应当怜恤你的同伴，像我怜恤你么？'),
('CUV', '马太福音', 40, 18, 34, '主人就大怒，把他交给掌刑的，等他还清了所欠的债。'),
('CUV', '马太福音', 40, 18, 35, '你们各人若不从心里饶恕你的弟兄，我天父也要这样待你们了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 19, 1, '耶稣说完了这些话，就离开加利利，来到犹太的境界约但河外。'),
('CUV', '马太福音', 40, 19, 2, '有许多人跟著他，他就在那里把他们的病人治好了。'),
('CUV', '马太福音', 40, 19, 3, '有法利赛人来试探耶稣，说：人无论甚么缘故都可以休妻么？'),
('CUV', '马太福音', 40, 19, 4, '耶稣回答说：那起初造人的，是造男造女，'),
('CUV', '马太福音', 40, 19, 5, '并且说：因此，人要离开父母，与妻子连合，二人成为一体。这经你们没有念过么？'),
('CUV', '马太福音', 40, 19, 6, '既然如此，夫妻不再是两个人，乃是一体的了。所以，神配合的，人不可分开。'),
('CUV', '马太福音', 40, 19, 7, '法利赛人说：这样，摩西为甚么吩咐给妻子休书，就可以休他呢？'),
('CUV', '马太福音', 40, 19, 8, '耶稣说：摩西因为你们的心硬，所以许你们休妻，但起初并不是这样。'),
('CUV', '马太福音', 40, 19, 9, '我告诉你们，凡休妻另娶的，若不是为淫乱的缘故，就是犯奸淫了；有人娶那被休的妇人，也是犯奸淫了。'),
('CUV', '马太福音', 40, 19, 10, '门徒对耶稣说：人和妻子既是这样，倒不如不娶。'),
('CUV', '马太福音', 40, 19, 11, '耶稣说：这话不是人都能领受的，惟独赐给谁，谁才能领受。'),
('CUV', '马太福音', 40, 19, 12, '因为有生来是阉人，也有被人阉的，并有为天国的缘故自阉的。这话谁能领受就可以领受。'),
('CUV', '马太福音', 40, 19, 13, '那时，有人带著小孩子来见耶稣，要耶稣给他们按手祷告，门徒就责备那些人。'),
('CUV', '马太福音', 40, 19, 14, '耶稣说：让小孩子到我这里来，不要禁止他们；因为在天国的，正是这样的人。'),
('CUV', '马太福音', 40, 19, 15, '耶稣给他们按手，就离开那地方去了。'),
('CUV', '马太福音', 40, 19, 16, '有一个人来见耶稣，说：夫子（有古卷：良善的夫子），我该做甚么善事才能得永生？'),
('CUV', '马太福音', 40, 19, 17, '耶稣对他说：你为甚么以善事问我呢？只有一位是善的（有古卷：你为什么称我是良善的？除了神以外，没有一个良善的）。你若要进入永生，就当遵守诫命。'),
('CUV', '马太福音', 40, 19, 18, '他说：甚么诫命？耶稣说：就是不可杀人；不可奸淫；不可偷盗；不可作假见证；'),
('CUV', '马太福音', 40, 19, 19, '当孝敬父母，又当爱人如己。'),
('CUV', '马太福音', 40, 19, 20, '那少年人说：这一切我都遵守了，还缺少甚么呢？'),
('CUV', '马太福音', 40, 19, 21, '耶稣说：你若愿意作完全人，可去变卖你所有的，分给穷人，就必有财宝在天上；你还要来跟从我。'),
('CUV', '马太福音', 40, 19, 22, '那少年人听见这话，就忧忧愁愁的走了，因为他的产业很多。'),
('CUV', '马太福音', 40, 19, 23, '耶稣对门徒说：我实在告诉你们，财主进天国是难的。'),
('CUV', '马太福音', 40, 19, 24, '我又告诉你们，骆驼穿过针的眼，比财主进神的国还容易呢！'),
('CUV', '马太福音', 40, 19, 25, '门徒听见这话，就希奇得很，说：这样谁能得救呢？'),
('CUV', '马太福音', 40, 19, 26, '耶稣看著他们，说：在人这是不能的，在神凡事都能。'),
('CUV', '马太福音', 40, 19, 27, '彼得就对他说：看哪，我们已经撇下所有的跟从你，将来我们要得甚么呢？'),
('CUV', '马太福音', 40, 19, 28, '耶稣说：我实在告诉你们，你们这跟从我的人，到复兴的时候，人子坐在他荣耀的宝座上，你们也要坐在十二个宝座上，审判以色列十二个支派。'),
('CUV', '马太福音', 40, 19, 29, '凡为我的名撇下房屋，或是弟兄、姐妹、父亲、母亲、（有古卷在此有：妻子）儿女、田地的，必要得著百倍，并且承受永生。'),
('CUV', '马太福音', 40, 19, 30, '然而，有许多在前的，将要在后；在后的，将要在前。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 20, 1, '因为天国好像家主清早去雇人进他的葡萄园做工，'),
('CUV', '马太福音', 40, 20, 2, '和工人讲定一天一钱银子，就打发他们进葡萄园去。'),
('CUV', '马太福音', 40, 20, 3, '约在巳初出去，看见市上还有闲站的人，'),
('CUV', '马太福音', 40, 20, 4, '就对他们说：你们也进葡萄园去，所当给的，我必给你们。他们也进去了。'),
('CUV', '马太福音', 40, 20, 5, '约在午正和申初又出去，也是这样行。'),
('CUV', '马太福音', 40, 20, 6, '约在酉初出去，看见还有人站在那里，就问他们说：你们为甚么整天在这里闲站呢？'),
('CUV', '马太福音', 40, 20, 7, '他们说：因为没有人雇我们。他说：你们也进葡萄园去。'),
('CUV', '马太福音', 40, 20, 8, '到了晚上，园主对管事的说：叫工人都来，给他们工钱，从后来的起，到先来的为止。'),
('CUV', '马太福音', 40, 20, 9, '约在酉初雇的人来了，各人得了一钱银子。'),
('CUV', '马太福音', 40, 20, 10, '及至那先雇的来了，他们以为必要多得；谁知也是各得一钱。'),
('CUV', '马太福音', 40, 20, 11, '他们得了，就埋怨家主说：'),
('CUV', '马太福音', 40, 20, 12, '我们整天劳苦受热，那后来的只做了一小时，你竟叫他们和我们一样么？'),
('CUV', '马太福音', 40, 20, 13, '家主回答其中的一人说：朋友，我不亏负你，你与我讲定的不是一钱银子么？'),
('CUV', '马太福音', 40, 20, 14, '拿你的走罢！我给那后来的和给你一样，这是我愿意的。'),
('CUV', '马太福音', 40, 20, 15, '我的东西难道不可随我的意思用么？因为我作好人，你就红了眼么？'),
('CUV', '马太福音', 40, 20, 16, '这样，那在后的，将要在前；在前的，将要在后了。（有古卷在此有：因为被召的人多，选上的人少。）'),
('CUV', '马太福音', 40, 20, 17, '耶稣上耶路撒冷去的时候，在路上把十二个门徒带到一边，对他们说：'),
('CUV', '马太福音', 40, 20, 18, '看哪，我们上耶路撒冷去，人子要被交给祭司长和文士。他们要定他死罪，'),
('CUV', '马太福音', 40, 20, 19, '又交给外邦人，将他戏弄，鞭打，钉在十字架上；第三日他要复活。'),
('CUV', '马太福音', 40, 20, 20, '那时，西庇太儿子的母亲同他两个儿子上前来拜耶稣，求他一件事。'),
('CUV', '马太福音', 40, 20, 21, '耶稣说：你要甚么呢？他说：愿你叫我这两个儿子在你国里，一个坐在你右边，一个坐在你左边。'),
('CUV', '马太福音', 40, 20, 22, '耶稣回答说：你们不知道所求的是甚么；我将要喝的杯，你们能喝么？他们说：我们能。'),
('CUV', '马太福音', 40, 20, 23, '耶稣说：我所喝的杯，你们必要喝；只是坐在我的左右，不是我可以赐的，乃是我父为谁预备的，就赐给谁。'),
('CUV', '马太福音', 40, 20, 24, '那十个门徒听见，就恼怒他们弟兄二人。'),
('CUV', '马太福音', 40, 20, 25, '耶稣叫了他们来，说：你们知道外邦人有君王为主治理他们，有大臣操权管束他们。'),
('CUV', '马太福音', 40, 20, 26, '只是在你们中间，不可这样；你们中间谁愿为大，就必作你们的用人；'),
('CUV', '马太福音', 40, 20, 27, '谁愿为首，就必作你们的仆人。'),
('CUV', '马太福音', 40, 20, 28, '正如人子来，不是要受人的服事，乃是要服事人，并且要舍命，作多人的赎价。'),
('CUV', '马太福音', 40, 20, 29, '他们出耶利哥的时候，有极多的人跟随他。'),
('CUV', '马太福音', 40, 20, 30, '有两个瞎子坐在路旁，听说是耶稣经过，就喊著说：主阿，大卫的子孙，可怜我们罢！'),
('CUV', '马太福音', 40, 20, 31, '众人责备他们，不许他们作声；他们却越发喊著说：主阿，大卫的子孙，可怜我们罢！'),
('CUV', '马太福音', 40, 20, 32, '耶稣就站住，叫他们来，说：要我为你们做甚么？'),
('CUV', '马太福音', 40, 20, 33, '他们说：主阿，要我们的眼睛能看见！'),
('CUV', '马太福音', 40, 20, 34, '耶稣就动了慈心，把他们的眼睛一摸，他们立刻看见，就跟从了耶稣。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 21, 1, '耶稣和门徒将近耶路撒冷，到了伯法其，在橄榄山那里。'),
('CUV', '马太福音', 40, 21, 2, '耶稣就打发两个门徒，对他们说：你们往对面村子里去，必看见一匹驴拴在那里，还有驴驹同在一处；你们解开，牵到我这里来。'),
('CUV', '马太福音', 40, 21, 3, '若有人对你们说甚么，你们就说：主要用他。那人必立时让你们牵来。'),
('CUV', '马太福音', 40, 21, 4, '这事成就是要应验先知的话，说：'),
('CUV', '马太福音', 40, 21, 5, '要对锡安的居民（原文是女子）说：看哪，你的王来到你这里，是温柔的，又骑著驴，就是骑著驴驹子。'),
('CUV', '马太福音', 40, 21, 6, '门徒就照耶稣所吩咐的去行，'),
('CUV', '马太福音', 40, 21, 7, '牵了驴和驴驹来，把自己的衣服搭在上面，耶稣就骑上。'),
('CUV', '马太福音', 40, 21, 8, '众人多半把衣服铺在路上；还有人砍下树枝来铺在路上。'),
('CUV', '马太福音', 40, 21, 9, '前行后随的众人喊著说：和散那（原有求救的意思，在此是称颂的话）归于大卫的子孙！奉主名来的是应当称颂的！高高在上和散那！'),
('CUV', '马太福音', 40, 21, 10, '耶稣既进了耶路撒冷，合城都惊动了，说：这是谁？'),
('CUV', '马太福音', 40, 21, 11, '众人说：这是加利利拿撒勒的先知耶稣。'),
('CUV', '马太福音', 40, 21, 12, '耶稣进了神的殿，赶出殿里一切作买卖的人，推倒兑换银钱之人的桌子，和卖鸽子之人的凳子；'),
('CUV', '马太福音', 40, 21, 13, '对他们说：经上记著说：我的殿必称为祷告的殿，你们倒使他成为贼窝了。'),
('CUV', '马太福音', 40, 21, 14, '在殿里有瞎子、瘸子到耶稣跟前，他就治好了他们.。'),
('CUV', '马太福音', 40, 21, 15, '祭司长和文士看见耶稣所行的奇事，又见小孩子在殿里喊著说：和散那归于大卫的子孙！就甚恼怒，'),
('CUV', '马太福音', 40, 21, 16, '对他说：这些人所说的，你听见了么？耶稣说：是的。经上说你从婴孩和吃奶的口中完全了赞美的话，你们没有念过么？'),
('CUV', '马太福音', 40, 21, 17, '于是离开他们，出城到伯大尼去，在那里住宿。'),
('CUV', '马太福音', 40, 21, 18, '早晨回城的时候，他饿了，'),
('CUV', '马太福音', 40, 21, 19, '看见路旁有一棵无花果树，就走到跟前，在树上找不著甚么，不过有叶子，就对树说：从今以后，你永不结果子。那无花果树就立刻枯干了。'),
('CUV', '马太福音', 40, 21, 20, '门徒看见了﹐便希奇说：无花果树怎么立刻枯干了呢？'),
('CUV', '马太福音', 40, 21, 21, '耶稣回答说：我实在告诉你们，你们若有信心，不疑惑，不但能行无花果树上所行的事，就是对这座山说：你挪开此地，投在海里！也必成就。'),
('CUV', '马太福音', 40, 21, 22, '你们祷告，无论求甚么，只要信，就必得著。'),
('CUV', '马太福音', 40, 21, 23, '耶稣进了殿，正教训人的时候，祭司长和民间的长老来问他说：你仗著甚么权柄做这些事？给你这权柄的是谁呢？'),
('CUV', '马太福音', 40, 21, 24, '耶稣回答说：我也要问你们一句话，你们若告诉我，我就告诉你们我仗著甚么权柄做这些事。'),
('CUV', '马太福音', 40, 21, 25, '约翰的洗礼是从那里来的？是从天上来的？是从人间来的呢？他们彼此商议说：我们若说从天上来，他必对我们说：这样，你们为甚么不信他呢？'),
('CUV', '马太福音', 40, 21, 26, '若说从人间来，我们又怕百姓，因为他们都以约翰为先知。'),
('CUV', '马太福音', 40, 21, 27, '于是回答耶稣说：我们不知道。耶稣说：我也不告诉你们我仗著甚么权柄做这些事。'),
('CUV', '马太福音', 40, 21, 28, '又说：一个人有两个儿子。他来对大儿子说：我儿，你今天到葡萄园里去做工。'),
('CUV', '马太福音', 40, 21, 29, '他回答说：我不去，以后自己懊悔，就去了。'),
('CUV', '马太福音', 40, 21, 30, '又来对小儿子也是这样说。他回答说：父阿，我去，他却不去。'),
('CUV', '马太福音', 40, 21, 31, '你们想，这两个儿子是那一个遵行父命呢？他们说：大儿子。耶稣说：我实在告诉你们，税吏和娼妓倒比你们先进神的国。'),
('CUV', '马太福音', 40, 21, 32, '因为约翰遵著义路到你们这里来，你们却不信他；税吏和娼妓倒信他。你们看见了，后来还是不懊悔去信他。'),
('CUV', '马太福音', 40, 21, 33, '你们再听一个比喻：有个家主栽了一个葡萄园，周围圈上篱笆，里面挖了一个压酒池，盖了一座楼，租给园户，就往外国去了。'),
('CUV', '马太福音', 40, 21, 34, '收果子的时候近了，就打发仆人到园户那里去收果子。'),
('CUV', '马太福音', 40, 21, 35, '园户拿住仆人，打了一个，杀了一个，用石头打死一个。'),
('CUV', '马太福音', 40, 21, 36, '主人又打发别的仆人去，比先前更多；园户还是照样待他们。'),
('CUV', '马太福音', 40, 21, 37, '后来打发他的儿子到他们那里去，意思说：他们必尊敬我的儿子。'),
('CUV', '马太福音', 40, 21, 38, '不料，园户看见他儿子，就彼此说：这是承受产业的。来罢，我们杀他，占他的产业！'),
('CUV', '马太福音', 40, 21, 39, '他们就拿住他，推出葡萄园外，杀了。'),
('CUV', '马太福音', 40, 21, 40, '园主来的时候要怎样处治这些园户呢？'),
('CUV', '马太福音', 40, 21, 41, '他们说：要下毒手除灭那些恶人，将葡萄园另租给那按著时候交果子的园户。'),
('CUV', '马太福音', 40, 21, 42, '耶稣说：经上写著：匠人所弃的石头已作了房角的头块石头。这是主所做的，在我们眼中看为希奇。这经你们没有念过么？'),
('CUV', '马太福音', 40, 21, 43, '所以我告诉你们，神的国必从你们夺去，赐给那能结果子的百姓。'),
('CUV', '马太福音', 40, 21, 44, '谁掉在这石头上，必要跌碎；这石头掉在谁的身上，就要把谁砸得稀烂。'),
('CUV', '马太福音', 40, 21, 45, '祭司长和法利赛人听见他的比喻，就看出他是指著他们说的。'),
('CUV', '马太福音', 40, 21, 46, '他们想要捉拿他，只是怕众人，因为众人以他为先知。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 22, 1, '耶稣又用比喻对他们说：'),
('CUV', '马太福音', 40, 22, 2, '天国好比一个王为他儿子摆设娶亲的筵席，'),
('CUV', '马太福音', 40, 22, 3, '就打发仆人去，请那些被召的人来赴席，他们却不肯来。'),
('CUV', '马太福音', 40, 22, 4, '王又打发别的仆人，说：你们告诉那被召的人，我的筵席已经预备好了，牛和肥畜已经宰了，各样都齐备，请你们来赴席。'),
('CUV', '马太福音', 40, 22, 5, '那些人不理就走了；一个到自己田里去；一个作买卖去；'),
('CUV', '马太福音', 40, 22, 6, '其余的拿住仆人，凌辱他们，把他们杀了。'),
('CUV', '马太福音', 40, 22, 7, '王就大怒，发兵除灭那些凶手，烧毁他们的城。'),
('CUV', '马太福音', 40, 22, 8, '于是对仆人说：喜筵已经齐备，只是所召的人不配。'),
('CUV', '马太福音', 40, 22, 9, '所以你们要往岔路口上去，凡遇见的，都召来赴席。'),
('CUV', '马太福音', 40, 22, 10, '那些仆人就出去，到大路上，凡遇见的，不论善恶都召聚了来，筵席上就坐满了客。'),
('CUV', '马太福音', 40, 22, 11, '王进来观看宾客，见那里有一个没有穿礼服的，'),
('CUV', '马太福音', 40, 22, 12, '就对他说：朋友，你到这里来怎么不穿礼服呢？那人无言可答。'),
('CUV', '马太福音', 40, 22, 13, '于是王对使唤的人说：捆起他的手脚来，把他丢在外边的黑暗里；在那里必要哀哭切齿了。'),
('CUV', '马太福音', 40, 22, 14, '因为被召的人多，选上的人少。'),
('CUV', '马太福音', 40, 22, 15, '当时，法利赛人出去商议，怎样就著耶稣的话陷害他，'),
('CUV', '马太福音', 40, 22, 16, '就打发他们的门徒同希律党的人去见耶稣，说：夫子，我们知道你是诚实人，并且诚诚实实传神的道，甚么人你都不徇情面，因为你不看人的外貌。'),
('CUV', '马太福音', 40, 22, 17, '请告诉我们，你的意见如何？纳税给该撒可以不可以？'),
('CUV', '马太福音', 40, 22, 18, '耶稣看出他们的恶意，就说：假冒为善的人哪，为甚么试探我？'),
('CUV', '马太福音', 40, 22, 19, '拿一个上税的钱给我看！他们就拿一个银钱来给他。'),
('CUV', '马太福音', 40, 22, 20, '耶稣说：这像和这号是谁的？'),
('CUV', '马太福音', 40, 22, 21, '他们说：是该撒的。耶稣说：这样，该撒的物当归给该撒；神的物当归给神。'),
('CUV', '马太福音', 40, 22, 22, '他们听见就希奇，离开他走了。'),
('CUV', '马太福音', 40, 22, 23, '撒都该人常说没有复活的事。那天，他们来问耶稣说：'),
('CUV', '马太福音', 40, 22, 24, '夫子，摩西说：人若死了，没有孩子，他兄弟当娶他的妻，为哥哥生子立后。'),
('CUV', '马太福音', 40, 22, 25, '从前，在我们这里有弟兄七人，第一个娶了妻，死了，没有孩子，撇下妻子给兄弟。'),
('CUV', '马太福音', 40, 22, 26, '第二、第三、直到第七个，都是如此。'),
('CUV', '马太福音', 40, 22, 27, '末后，妇人也死了。'),
('CUV', '马太福音', 40, 22, 28, '这样，当复活的时候，他是七个人中那一个的妻子呢？因为他们都娶过他。'),
('CUV', '马太福音', 40, 22, 29, '耶稣回答说：你们错了；因为不明白圣经，也不晓得神的大能。'),
('CUV', '马太福音', 40, 22, 30, '当复活的时候，人也不娶也不嫁，乃像天上的使者一样。'),
('CUV', '马太福音', 40, 22, 31, '论到死人复活，神在经上向你们所说的，你们没有念过么？'),
('CUV', '马太福音', 40, 22, 32, '他说：我是亚伯拉罕的神，以撒的神，雅各的神。神不是死人的神，乃是活人的神。'),
('CUV', '马太福音', 40, 22, 33, '众人听见这话，就希奇他的教训。'),
('CUV', '马太福音', 40, 22, 34, '法利赛人听见耶稣堵住了撒都该人的口，他们就聚集。'),
('CUV', '马太福音', 40, 22, 35, '内中有一个人是律法师，要试探耶稣，就问他说：'),
('CUV', '马太福音', 40, 22, 36, '夫子，律法上的诫命，那一条是最大的呢？'),
('CUV', '马太福音', 40, 22, 37, '耶稣对他说：你要尽心、尽性、尽意爱主─你的神。'),
('CUV', '马太福音', 40, 22, 38, '这是诫命中的第一，且是最大的。'),
('CUV', '马太福音', 40, 22, 39, '其次也相倣，就是要爱人如己。'),
('CUV', '马太福音', 40, 22, 40, '这两条诫命是律法和先知一切道理的总纲。'),
('CUV', '马太福音', 40, 22, 41, '法利赛人聚集的时候，耶稣问他们说：'),
('CUV', '马太福音', 40, 22, 42, '论到基督，你们的意见如何？他是谁的子孙呢？他们回答说：是大卫的子孙。'),
('CUV', '马太福音', 40, 22, 43, '耶稣说：这样，大卫被圣灵感动，怎么还称他为主，说：'),
('CUV', '马太福音', 40, 22, 44, '主对我主说：你坐在我的右边，等我把你仇敌放在你的脚下。'),
('CUV', '马太福音', 40, 22, 45, '大卫既称他为主，他怎么又是大卫的子孙呢？'),
('CUV', '马太福音', 40, 22, 46, '他们没有一个人能回答一言。从那日以后，也没有人敢再问他甚么。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 23, 1, '那时﹐耶稣对众人和门徒讲论，'),
('CUV', '马太福音', 40, 23, 2, '说：文士和法利赛人坐在摩西的位上，'),
('CUV', '马太福音', 40, 23, 3, '凡他们所吩咐你们的，你们都要谨守遵行；但不要效法他们的行为；因为他们能说，不能行。'),
('CUV', '马太福音', 40, 23, 4, '他们把难担的重担捆起来，搁在人的肩上，但自己一个指头也不肯动。'),
('CUV', '马太福音', 40, 23, 5, '他们一切所做的事都是要叫人看见，所以将佩戴的经文做宽了，衣裳的䍁子做长了，'),
('CUV', '马太福音', 40, 23, 6, '喜爱筵席上的首座，会堂里的高位，'),
('CUV', '马太福音', 40, 23, 7, '又喜爱人在街市上问他安，称呼他拉比（拉比就是夫子）。'),
('CUV', '马太福音', 40, 23, 8, '但你们不要受拉比的称呼，因为只有一位是你们的夫子；你们都是弟兄。'),
('CUV', '马太福音', 40, 23, 9, '也不要称呼地上的人为父，因为只有一位是你们的父，就是在天上的父。'),
('CUV', '马太福音', 40, 23, 10, '也不要受师尊的称呼，因为只有一位是你们的师尊，就是基督。'),
('CUV', '马太福音', 40, 23, 11, '你们中间谁为大，谁就要作你们的用人。'),
('CUV', '马太福音', 40, 23, 12, '凡自高的，必降为卑；自卑的，必升为高。'),
('CUV', '马太福音', 40, 23, 13, '你们这假冒为善的文士和法利赛人有祸了！因为你们正当人前，把天国的门关了，自己不进去，正要进去的人，你们也不容他们进去。（有古卷在此有'),
('CUV', '马太福音', 40, 23, 14, '你们这假冒为善的文士和法利赛人有祸了！因为你们侵吞寡妇的家产，假意做很长的祷告，所以要受更重的刑罚。）'),
('CUV', '马太福音', 40, 23, 15, '你们这假冒为善的文士和法利赛人有祸了！因为你们走遍洋海陆地，勾引一个人入教，既入了教，却使他作地狱之子，比你们还加倍。'),
('CUV', '马太福音', 40, 23, 16, '你们这瞎眼领路的有祸了！你们说：凡指著殿起誓的，这算不得甚么；只是凡指著殿中金子起誓的，他就该谨守。'),
('CUV', '马太福音', 40, 23, 17, '你们这无知瞎眼的人哪，甚么是大的？是金子呢？还是叫金子成圣的殿呢？'),
('CUV', '马太福音', 40, 23, 18, '你们又说：凡指著坛起誓的，这算不得甚么；只是凡指著坛上礼物起誓的，他就该谨守。'),
('CUV', '马太福音', 40, 23, 19, '你们这瞎眼的人哪，甚么是大的？是礼物呢？还是叫礼物成圣的坛呢？'),
('CUV', '马太福音', 40, 23, 20, '所以，人指著坛起誓，就是指著坛和坛上一切所有的起誓；'),
('CUV', '马太福音', 40, 23, 21, '人指著殿起誓，就是指著殿和那住在殿里的起誓；'),
('CUV', '马太福音', 40, 23, 22, '人指著天起誓，就是指著神的宝座和那坐在上面的起誓。'),
('CUV', '马太福音', 40, 23, 23, '你们这假冒为善的文士和法利赛人有祸了！因为你们将薄荷、茴香、芹菜，献上十分之一，那律法上更重的事，就是公义、怜悯、信实，反倒不行了。这更重的是你们当行的；那也是不可不行的。'),
('CUV', '马太福音', 40, 23, 24, '你们这瞎眼领路的，蠓虫你们就滤出来，骆驼你们倒吞下去。'),
('CUV', '马太福音', 40, 23, 25, '你们这假冒为善的文士和法利赛人有祸了！因为你们洗净杯盘的外面，里面却盛满了勒索和放荡。'),
('CUV', '马太福音', 40, 23, 26, '你这瞎眼的法利赛人，先洗净杯盘的里面，好叫外面也干净了。'),
('CUV', '马太福音', 40, 23, 27, '你们这假冒为善的文士和法利赛人有祸了！因为你们好像粉饰的坟墓，外面好看，里面却装满了死人的骨头和一切的污秽。'),
('CUV', '马太福音', 40, 23, 28, '你们也是如此，在人前，外面显出公义来，里面却装满了假善和不法的事。'),
('CUV', '马太福音', 40, 23, 29, '你们这假冒为善的文士和法利赛人有祸了！因为你们建造先知的坟，修饰义人的墓，说：'),
('CUV', '马太福音', 40, 23, 30, '若是我们在我们祖宗的时候，必不和他们同流先知的血。'),
('CUV', '马太福音', 40, 23, 31, '这就是你们自己证明是杀害先知者的子孙了。'),
('CUV', '马太福音', 40, 23, 32, '你们去充满你们祖宗的恶贯罢！'),
('CUV', '马太福音', 40, 23, 33, '你们这些蛇类、毒蛇之种阿，怎能逃脱地狱?的刑罚呢？'),
('CUV', '马太福音', 40, 23, 34, '所以我差遣先知和智慧人并文士到你们这里来，有的你们要杀害，要钉十字架；有的你们要在会堂里鞭打，从这城追逼到那城，'),
('CUV', '马太福音', 40, 23, 35, '叫世上所流义人的血都归到你们身上，从义人亚伯的血起，直到你们在殿和坛中间所杀的巴拉加的儿子撒迦利亚的血为止。'),
('CUV', '马太福音', 40, 23, 36, '我实在告诉你们，这一切的罪都要归到这世代了。'),
('CUV', '马太福音', 40, 23, 37, '耶路撒冷阿，耶路撒冷阿，你常杀害先知，又用石头打死那奉差遣到你这里来的人。我多次愿意聚集你的儿女，好像母鸡把小鸡聚集在翅膀底下，只是你们不愿意。'),
('CUV', '马太福音', 40, 23, 38, '看哪，你们的家成为荒场留给你们。'),
('CUV', '马太福音', 40, 23, 39, '我告诉你们，从今以后，你们不得再见我，直等到你们说：奉主名来的是应当称颂的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 24, 1, '耶稣出了圣殿，正走的时候，门徒进前来，把殿宇指给他看。'),
('CUV', '马太福音', 40, 24, 2, '耶稣对他们说：你们不是看见这殿宇么？我实在告诉你们，将来在这里没有一块石头留在石头上，不被拆毁了。'),
('CUV', '马太福音', 40, 24, 3, '耶稣在橄榄山上坐著，门徒暗暗的来说：请告诉我们，甚么时候有这些事？你降临和世界的末了有甚么豫兆呢？'),
('CUV', '马太福音', 40, 24, 4, '耶稣回答说：你们要谨慎，免得有人迷惑你们。'),
('CUV', '马太福音', 40, 24, 5, '因为将来有好些人冒我的名来，说：我是基督，并且要迷惑许多人。'),
('CUV', '马太福音', 40, 24, 6, '你们也要听见打仗和打仗的风声，总不要惊慌；因为这些事是必须有的，只是末期还没有到。'),
('CUV', '马太福音', 40, 24, 7, '民要攻打民，国要攻打国；多处必有饥荒、地震。'),
('CUV', '马太福音', 40, 24, 8, '这都是灾难（灾难：原文是生产之难）的起头。'),
('CUV', '马太福音', 40, 24, 9, '那时，人要把你们陷在患难里，也要杀害你们；你们又要为我的名被万民恨恶。'),
('CUV', '马太福音', 40, 24, 10, '那时，必有许多人跌倒，也要彼此陷害，彼此恨恶；'),
('CUV', '马太福音', 40, 24, 11, '且有好些假先知起来，迷惑多人。'),
('CUV', '马太福音', 40, 24, 12, '只因不法的事增多，许多人的爱心才渐渐冷淡了。'),
('CUV', '马太福音', 40, 24, 13, '惟有忍耐到底的，必然得救。'),
('CUV', '马太福音', 40, 24, 14, '这天国的福音要传遍天下，对万民作见证，然后末期才来到。'),
('CUV', '马太福音', 40, 24, 15, '你们看见先知但以理所说的那行毁坏可憎的站在圣地（读这经的人须要会意）。'),
('CUV', '马太福音', 40, 24, 16, '那时，在犹太的，应当逃到山上；'),
('CUV', '马太福音', 40, 24, 17, '在房上的，不要下来拿家里的东西；'),
('CUV', '马太福音', 40, 24, 18, '在田里的，也不要回去取衣裳。'),
('CUV', '马太福音', 40, 24, 19, '当那些日子，怀孕的和奶孩子的有祸了。'),
('CUV', '马太福音', 40, 24, 20, '你们应当祈求，叫你们逃走的时候，不遇见冬天或是安息日。'),
('CUV', '马太福音', 40, 24, 21, '因为那时必有大灾难，从世界的起头直到如今，没有这样的灾难，后来也必没有。'),
('CUV', '马太福音', 40, 24, 22, '若不减少那日子，凡有血气的总没有一个得救的；只是为选民，那日子必减少了。'),
('CUV', '马太福音', 40, 24, 23, '那时，若有人对你们说：基督在这里，或说：基督在那里，你们不要信！'),
('CUV', '马太福音', 40, 24, 24, '因为假基督、假先知将要起来，显大神迹、大奇事，倘若能行，连选民也就迷惑了。'),
('CUV', '马太福音', 40, 24, 25, '看哪，我预先告诉你们了。'),
('CUV', '马太福音', 40, 24, 26, '若有人对你们说：看哪，基督在旷野里，你们不要出去！或说：看哪，基督在内屋中，你们不要信！'),
('CUV', '马太福音', 40, 24, 27, '闪电从东边发出，直照到西边。人子降临，也要这样。'),
('CUV', '马太福音', 40, 24, 28, '尸首在那里，鹰也必聚在那里。'),
('CUV', '马太福音', 40, 24, 29, '那些日子的灾难一过去，日头就变黑了，月亮也不放光，众星要从天上坠落，天势都要震动。'),
('CUV', '马太福音', 40, 24, 30, '那时，人子的兆头要显在天上，地上的万族都要哀哭。他们要看见人子，有能力，有大荣耀.，驾著天上的云降临。'),
('CUV', '马太福音', 40, 24, 31, '他要差遣使者，用号筒的大声，将他的选民，从四方（方：原文是风），从天这边到天那边，都招聚了来。'),
('CUV', '马太福音', 40, 24, 32, '你们可以从无花果树学个比方：当树枝发嫩长叶的时候，你们就知道夏天近了。'),
('CUV', '马太福音', 40, 24, 33, '这样，你们看见这一切的事，也该知道人子近了，正在门口了。'),
('CUV', '马太福音', 40, 24, 34, '我实在告诉你们，这世代还没有过去，这些事都要成就。'),
('CUV', '马太福音', 40, 24, 35, '天地要废去，我的话却不能废去。'),
('CUV', '马太福音', 40, 24, 36, '那日子，那时辰，没有人知道，连天上的使者也不知道，子也不知道，惟独父知道。'),
('CUV', '马太福音', 40, 24, 37, '挪亚的日子怎样，人子降临也要怎样。'),
('CUV', '马太福音', 40, 24, 38, '当洪水以前的日子，人照常吃喝嫁娶，直到挪亚进方舟的那日；'),
('CUV', '马太福音', 40, 24, 39, '不知不觉洪水来了，把他们全都冲去。人子降临也要这样。'),
('CUV', '马太福音', 40, 24, 40, '那时，两个人在田里，取去一个，撇下一个。'),
('CUV', '马太福音', 40, 24, 41, '两个女人推磨，取去一个，撇下一个。'),
('CUV', '马太福音', 40, 24, 42, '所以，你们要儆醒，因为不知道你们的主是那一天来到。'),
('CUV', '马太福音', 40, 24, 43, '家主若知道几更天有贼来，就必儆醒，不容人挖透房屋；这是你们所知道的。'),
('CUV', '马太福音', 40, 24, 44, '所以，你们也要预备，因为你们想不到的时候，人子就来了。'),
('CUV', '马太福音', 40, 24, 45, '谁是忠心有见识的仆人，为主人所派，管理家里的人，按时分粮给他们呢？'),
('CUV', '马太福音', 40, 24, 46, '主人来到，看见他这样行，那仆人就有福了。'),
('CUV', '马太福音', 40, 24, 47, '我实在告诉你们，主人要派他管理一切所有的。'),
('CUV', '马太福音', 40, 24, 48, '倘若那恶仆心里说：我的主人必来得迟，'),
('CUV', '马太福音', 40, 24, 49, '就动手打他的同伴，又和酒醉的人一同吃喝。'),
('CUV', '马太福音', 40, 24, 50, '在想不到的日子，不知道的时辰，那仆人的主人要来，'),
('CUV', '马太福音', 40, 24, 51, '重重的处治他（或作：把他腰斩了），定他和假冒为善的人同罪；在那里必要哀哭切齿了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 25, 1, '那时，天国好比十个童女拿著灯出去迎接新郎。'),
('CUV', '马太福音', 40, 25, 2, '其中有五个是愚拙的，五个是聪明的。'),
('CUV', '马太福音', 40, 25, 3, '愚拙的拿著灯，却不预备油；'),
('CUV', '马太福音', 40, 25, 4, '聪明的拿著灯，又预备油在器皿里。'),
('CUV', '马太福音', 40, 25, 5, '新郎迟延的时候，他们都打盹，睡著了。'),
('CUV', '马太福音', 40, 25, 6, '半夜有人喊著说：新郎来了，你们出来迎接他！'),
('CUV', '马太福音', 40, 25, 7, '那些童女就都起来收拾灯。'),
('CUV', '马太福音', 40, 25, 8, '愚拙的对聪明的说：请分点油给我们，因为我们的灯要灭了。'),
('CUV', '马太福音', 40, 25, 9, '聪明的回答说：恐怕不够你我用的；不如你们自己到卖油的那里去买罢。'),
('CUV', '马太福音', 40, 25, 10, '他们去买的时候，新郎到了。那预备好了的，同他进去坐席，门就关了。'),
('CUV', '马太福音', 40, 25, 11, '其余的童女随后也来了，说：主阿，主阿，给我们开门！'),
('CUV', '马太福音', 40, 25, 12, '他却回答说：我实在告诉你们，我不认识你们。'),
('CUV', '马太福音', 40, 25, 13, '所以，你们要儆醒；因为那日子，那时辰，你们不知道。'),
('CUV', '马太福音', 40, 25, 14, '天国又好比一个人要往外国去，就叫了仆人来，把他的家业交给他们，'),
('CUV', '马太福音', 40, 25, 15, '按著各人的才干给他们银子：一个给了五千，一个给了二千，一个给了一千，就往外国去了。'),
('CUV', '马太福音', 40, 25, 16, '那领五千的随即拿去做买卖，另外赚了五千。'),
('CUV', '马太福音', 40, 25, 17, '那领二千的也照样另赚了二千。'),
('CUV', '马太福音', 40, 25, 18, '但那领一千的去掘开地，把主人的银子埋藏了。'),
('CUV', '马太福音', 40, 25, 19, '过了许久，那些仆人的主人来了，和他们算账。'),
('CUV', '马太福音', 40, 25, 20, '那领五千银子的又带著那另外的五千来，说：主阿，你交给我五千银子。请看，我又赚了五千。'),
('CUV', '马太福音', 40, 25, 21, '主人说：好，你这又良善又忠心的仆人，你在不多的事上有忠心，我要把许多事派你管理；可以进来享受你主人的快乐。'),
('CUV', '马太福音', 40, 25, 22, '那领二千的也来，说：主阿，你交给我二千银子。请看，我又赚了二千。'),
('CUV', '马太福音', 40, 25, 23, '主人说：好，你这又良善又忠心的仆人，你在不多的事上有忠心，我要把许多事派你管理；可以进来享受你主人的快乐。'),
('CUV', '马太福音', 40, 25, 24, '那领一千的也来，说：主阿，我知道你是忍心的人，没有种的地方要收割，没有散的地方要聚敛，'),
('CUV', '马太福音', 40, 25, 25, '我就害怕，去把你的一千银子埋藏在地里。请看，你的原银子在这里。'),
('CUV', '马太福音', 40, 25, 26, '主人回答说：你这又恶又懒的仆人，你既知道我没有种的地方要收割，没有散的地方要聚敛，'),
('CUV', '马太福音', 40, 25, 27, '就当把我的银子放给兑换银钱的人，到我来的时候，可以连本带利收回。'),
('CUV', '马太福音', 40, 25, 28, '夺过他这一千来，给那有一万的。'),
('CUV', '马太福音', 40, 25, 29, '因为凡有的，还要加给他，叫他有余；没有的，连他所有的也要夺过来。'),
('CUV', '马太福音', 40, 25, 30, '把这无用的仆人丢在外面黑暗里；在那里必要哀哭切齿了。'),
('CUV', '马太福音', 40, 25, 31, '当人子在他荣耀里、同著众天使降临的时候，要坐在他荣耀的宝座上。'),
('CUV', '马太福音', 40, 25, 32, '万民都要聚集在他面前。他要把他们分别出来，好像牧羊的分别绵羊山羊一般，'),
('CUV', '马太福音', 40, 25, 33, '把绵羊安置在右边，山羊在左边。'),
('CUV', '马太福音', 40, 25, 34, '于是王要向那右边的说：你们这蒙我父赐福的，可来承受那创世以来为你们所预备的国；'),
('CUV', '马太福音', 40, 25, 35, '因为我饿了，你们给我吃，渴了，你们给我喝；我作客旅，你们留我住；'),
('CUV', '马太福音', 40, 25, 36, '我赤身露体，你们给我穿；我病了、你们看顾我；我在监里，你们来看我。'),
('CUV', '马太福音', 40, 25, 37, '义人就回答说：主阿，我们甚么时候见你饿了，给你吃，渴了，给你喝？'),
('CUV', '马太福音', 40, 25, 38, '甚么时候见你作客旅，留你住，或是赤身露体，给你穿？'),
('CUV', '马太福音', 40, 25, 39, '又甚么时候见你病了，或是在监里，来看你呢？'),
('CUV', '马太福音', 40, 25, 40, '王要回答说：我实在告诉你们，这些事你们既做在我这弟兄中一个最小的身上，就是做在我身上了。'),
('CUV', '马太福音', 40, 25, 41, '王又要向那左边的说：你们这被咒诅的人，离开我！进入那为魔鬼和他的使者所预备的永火里去！'),
('CUV', '马太福音', 40, 25, 42, '因为我饿了，你们不给我吃，渴了，你们不给我喝；'),
('CUV', '马太福音', 40, 25, 43, '我作客旅，你们不留我住；我赤身露体，你们不给我穿；我病了，我在监里，你们不来看顾我。'),
('CUV', '马太福音', 40, 25, 44, '他们也要回答说：主阿，我们甚么时候见你饿了，或渴了，或作客旅，或赤身露体，或病了，或在监里，不伺候你呢？'),
('CUV', '马太福音', 40, 25, 45, '王要回答说：我实在告诉你们，这些事你们既不做在我这弟兄中一个最小的身上，就是不做在我身上了。'),
('CUV', '马太福音', 40, 25, 46, '这些人要往永刑里去；那些义人要往永生里去。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 26, 1, '耶稣说完了这一切的话，就对门徒说：'),
('CUV', '马太福音', 40, 26, 2, '你们知道，过两天是逾越节，人子将要被交给人，钉在十字架上。'),
('CUV', '马太福音', 40, 26, 3, '那时，祭司长和民间的长老聚集在大祭司称为该亚法的院里。'),
('CUV', '马太福音', 40, 26, 4, '大家商议要用诡计拿住耶稣，杀他，'),
('CUV', '马太福音', 40, 26, 5, '只是说：当节的日子不可，恐怕民间生乱。'),
('CUV', '马太福音', 40, 26, 6, '耶稣在伯大尼长大痲疯的西门家里，'),
('CUV', '马太福音', 40, 26, 7, '有一个女人拿著一玉瓶极贵的香膏来，趁耶稣坐席的时候，浇在他的头上。'),
('CUV', '马太福音', 40, 26, 8, '门徒看见就很不喜悦，说：何用这样的枉费呢！'),
('CUV', '马太福音', 40, 26, 9, '这香膏可以卖许多钱，赒济穷人。'),
('CUV', '马太福音', 40, 26, 10, '耶稣看出他们的意思，就说：为甚么难为这女人呢？他在我身上做的是一件美事。'),
('CUV', '马太福音', 40, 26, 11, '因为常有穷人和你们同在；只是你们不常有我。'),
('CUV', '马太福音', 40, 26, 12, '他将这香膏浇在我身上是为我安葬做的。'),
('CUV', '马太福音', 40, 26, 13, '我实在告诉你们，普天之下，无论在甚么地方传这福音，也要述说这女人所行的，作个纪念。'),
('CUV', '马太福音', 40, 26, 14, '当下，十二门徒里有一个称为加略人犹大的，去见祭司长，'),
('CUV', '马太福音', 40, 26, 15, '说：我把他交给你们，你们愿意给我多少钱？他们就给了他三十块钱。'),
('CUV', '马太福音', 40, 26, 16, '从那时候，他就找机会要把耶稣交给他们。'),
('CUV', '马太福音', 40, 26, 17, '除酵节的第一天，门徒来问耶稣说：你吃逾越节的筵席，要我们在那里给你预备？'),
('CUV', '马太福音', 40, 26, 18, '耶稣说：你们进城去，到某人那里，对他说：夫子说：我的时候快到了，我与门徒要在你家里守逾越节。'),
('CUV', '马太福音', 40, 26, 19, '门徒遵著耶稣所吩咐的就去预备了逾越节的筵席。'),
('CUV', '马太福音', 40, 26, 20, '到了晚上，耶稣和十二个门徒坐席。'),
('CUV', '马太福音', 40, 26, 21, '正吃的时候，耶稣说：我实在告诉你们，你们中间有一个人要卖我了。'),
('CUV', '马太福音', 40, 26, 22, '他们就甚忧愁，一个一个的问他说：主，是我么？'),
('CUV', '马太福音', 40, 26, 23, '耶稣回答说：同我蘸手在盘子里的，就是他要卖我。'),
('CUV', '马太福音', 40, 26, 24, '人子必要去世，正如经上指著他所写的；但卖人子的人有祸了！那人不生在世上倒好。'),
('CUV', '马太福音', 40, 26, 25, '卖耶稣的犹大问他说：拉比，是我么？耶稣说：你说的是。'),
('CUV', '马太福音', 40, 26, 26, '他们吃的时候，耶稣拿起饼来，祝福，就擘开，递给门徒，说：你们拿著吃，这是我的身体；'),
('CUV', '马太福音', 40, 26, 27, '又拿起杯来，祝谢了，递给他们，说：你们都喝这个；'),
('CUV', '马太福音', 40, 26, 28, '因为这是我立约的血，为多人流出来，使罪得赦。'),
('CUV', '马太福音', 40, 26, 29, '但我告诉你们，从今以后，我不再喝这葡萄汁，直到我在我父的国里同你们喝新的那日子。'),
('CUV', '马太福音', 40, 26, 30, '他们唱了诗，就出来往橄榄山去。'),
('CUV', '马太福音', 40, 26, 31, '那时，耶稣对他们说：今夜，你们为我的缘故都要跌倒。因为经上记著说：我要击打牧人，羊就分散了。'),
('CUV', '马太福音', 40, 26, 32, '但我复活以后，要在你们以先往加利利去。'),
('CUV', '马太福音', 40, 26, 33, '彼得说：众人虽然为你的缘故跌倒，我却永不跌倒。'),
('CUV', '马太福音', 40, 26, 34, '耶稣说：我实在告诉你，今夜鸡叫以先，你要三次不认我。'),
('CUV', '马太福音', 40, 26, 35, '彼得说：我就是必须和你同死，也总不能不认你。众门徒都是这样说。'),
('CUV', '马太福音', 40, 26, 36, '耶稣同门徒来到一个地方，名叫客西马尼，就对他们说：你们坐在这里，等我到那边去祷告。'),
('CUV', '马太福音', 40, 26, 37, '于是带著彼得和西庇太的两个儿子同去，就忧愁起来，极其难过，'),
('CUV', '马太福音', 40, 26, 38, '便对他们说：我心里甚是忧伤，几乎要死；你们在这里等候，和我一同儆醒。'),
('CUV', '马太福音', 40, 26, 39, '他就稍往前走，俯伏在地，祷告说：我父阿，倘若可行，求你叫这杯离开我。然而，不要照我的意思，只要照你的意思。'),
('CUV', '马太福音', 40, 26, 40, '来到门徒那里，见他们睡著了，就对彼得说：怎么样？你们不能同我儆醒片时么？'),
('CUV', '马太福音', 40, 26, 41, '总要儆醒祷告，免得入了迷惑。你们心灵固然愿意，肉体却软弱了。'),
('CUV', '马太福音', 40, 26, 42, '第二次又去祷告说：我父阿，这杯若不能离开我，必要我喝，就愿你的意旨成全。'),
('CUV', '马太福音', 40, 26, 43, '又来，见他们睡著了，因为他们的眼睛困倦。'),
('CUV', '马太福音', 40, 26, 44, '耶稣又离开他们去了。第三次祷告，说的话还是与先前一样。'),
('CUV', '马太福音', 40, 26, 45, '于是来到门徒那里，对他们说：现在你们仍然睡觉安歇罢（罢：或作么？）！时候到了，人子被卖在罪人手里了。'),
('CUV', '马太福音', 40, 26, 46, '起来！我们走罢。看哪，卖我的人近了。'),
('CUV', '马太福音', 40, 26, 47, '说话之间，那十二个门徒里的犹大来了，并有许多人带著刀棒，从祭司长和民间的长老那里与他同来。'),
('CUV', '马太福音', 40, 26, 48, '那卖耶稣的给了他们一个暗号，说：我与谁亲嘴，谁就是他。你们可以拿住他。'),
('CUV', '马太福音', 40, 26, 49, '犹大随即到耶稣跟前，说：请拉比安，就与他亲嘴。'),
('CUV', '马太福音', 40, 26, 50, '耶稣对他说：朋友，你来要做的事，就做罢。于是那些人上前，下手拿住耶稣。'),
('CUV', '马太福音', 40, 26, 51, '有跟随耶稣的一个人伸手拔出刀来，将大祭司的仆人砍了一刀，削掉了他一个耳朵。'),
('CUV', '马太福音', 40, 26, 52, '耶稣对他说：收刀入鞘罢！凡动刀的，必死在刀下。'),
('CUV', '马太福音', 40, 26, 53, '你想，我不能求我父现在为我差遣十二营多天使来么？'),
('CUV', '马太福音', 40, 26, 54, '若是这样，经上所说，事情必须如此的话怎么应验呢？'),
('CUV', '马太福音', 40, 26, 55, '当时，耶稣对众人说：你们带著刀棒出来拿我，如同拿强盗么？我天天坐在殿里教训人，你们并没有拿我。'),
('CUV', '马太福音', 40, 26, 56, '但这一切的事成就了，为要应验先知书上的话。当下，门徒都离开他逃走了。'),
('CUV', '马太福音', 40, 26, 57, '拿耶稣的人把他带到大祭司该亚法那里去；文士和长老已经在那里聚会。'),
('CUV', '马太福音', 40, 26, 58, '彼得远远的跟著耶稣，直到大祭司的院子，进到里面，就和差役同坐，要看这事到底怎样。'),
('CUV', '马太福音', 40, 26, 59, '祭司长和全公会寻找假见证控告耶稣，要治死他。'),
('CUV', '马太福音', 40, 26, 60, '虽有好些人来作假见证，总得不著实据。末后有两个人前来，说：'),
('CUV', '马太福音', 40, 26, 61, '这个人曾说：我能拆毁神的殿，三日内又建造起来。'),
('CUV', '马太福音', 40, 26, 62, '大祭司就站起来，对耶稣说：你甚么都不回答么？这些人作见证告你的是甚么呢？'),
('CUV', '马太福音', 40, 26, 63, '耶稣却不言语。大祭司对他说：我指著永生神叫你起誓告诉我们，你是神的儿子基督不是？'),
('CUV', '马太福音', 40, 26, 64, '耶稣对他说：你说的是。然而，我告诉你们，后来你们要看见人子坐在那权能者的右边，驾著天上的云降临。'),
('CUV', '马太福音', 40, 26, 65, '大祭司就撕开衣服，说：他说了僭妄的话，我们何必再用见证人呢？这僭妄的话，现在你们都听见了。'),
('CUV', '马太福音', 40, 26, 66, '你们的意见如何？他们回答说：他是该死的。'),
('CUV', '马太福音', 40, 26, 67, '他们就吐唾沫在他脸上，用拳头打他；也有用手掌打他的，说：'),
('CUV', '马太福音', 40, 26, 68, '基督阿！你是先知，告诉我们打你的是谁？'),
('CUV', '马太福音', 40, 26, 69, '彼得在外面院子里坐著，有一个使女前来，说：你素来也是同那加利利人耶稣一伙的。'),
('CUV', '马太福音', 40, 26, 70, '彼得在众人面前却不承认，说：我不知道你说的是甚么！'),
('CUV', '马太福音', 40, 26, 71, '既出去，到了门口，又有一个使女看见他，就对那里的人说：这个人也是同拿撒勒人耶稣一伙的。'),
('CUV', '马太福音', 40, 26, 72, '彼得又不承认，并且起誓说：我不认得那个人。'),
('CUV', '马太福音', 40, 26, 73, '过了不多的时候，旁边站著的人前来，对彼得说：你真是他们一党的，你的口音把你露出来了。'),
('CUV', '马太福音', 40, 26, 74, '彼得就发咒起誓的说：我不认得那个人。立时，鸡就叫了。'),
('CUV', '马太福音', 40, 26, 75, '彼得想起耶稣所说的话：鸡叫以先，你要三次不认我。他就出去痛哭。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 27, 1, '到了早晨，众祭司长和民间的长老大家商议要治死耶稣，'),
('CUV', '马太福音', 40, 27, 2, '就把他捆绑，解去，交给巡抚彼拉多。'),
('CUV', '马太福音', 40, 27, 3, '这时候，卖耶稣的犹大看见耶稣已经定了罪，就后悔，把那三十块钱拿回来给祭司长和长老，说：'),
('CUV', '马太福音', 40, 27, 4, '我卖了无辜之人的血是有罪了。他们说：那与我们有甚么相干？你自己承当罢！'),
('CUV', '马太福音', 40, 27, 5, '犹大就把那银钱丢在殿里，出去吊死了。'),
('CUV', '马太福音', 40, 27, 6, '祭司长拾起银钱来，说：这是血价，不可放在库里。'),
('CUV', '马太福音', 40, 27, 7, '他们商议，就用那银钱买了窑户的一块田，为要埋葬外乡人。'),
('CUV', '马太福音', 40, 27, 8, '所以那块田直到今日还叫做血田。'),
('CUV', '马太福音', 40, 27, 9, '这就应验了先知耶利米的话，说：他们用那三十块钱，就是被估定之人的价钱，是以色列人中所估定的，'),
('CUV', '马太福音', 40, 27, 10, '买了窑户的一块田；这是照著主所吩咐我的。'),
('CUV', '马太福音', 40, 27, 11, '耶稣站在巡抚面前；巡抚问他说：你是犹太人的王么？耶稣说：你说的是。'),
('CUV', '马太福音', 40, 27, 12, '他被祭司长和长老控告的时候，甚么都不回答。'),
('CUV', '马太福音', 40, 27, 13, '彼拉多就对他说：他们作见证告你这么多的事，你没有听见么？'),
('CUV', '马太福音', 40, 27, 14, '耶稣仍不回答，连一句话也不说，以致巡抚甚觉希奇。'),
('CUV', '马太福音', 40, 27, 15, '巡抚有一个常例，每逢这节期，随众人所要的释放一个囚犯给他们。'),
('CUV', '马太福音', 40, 27, 16, '当时有一个出名的囚犯叫巴拉巴。'),
('CUV', '马太福音', 40, 27, 17, '众人聚集的时候，彼拉多就对他们说：你们要我释放那一个给你们？是巴拉巴呢？是称为基督的耶稣呢？'),
('CUV', '马太福音', 40, 27, 18, '巡抚原知道他们是因为嫉妒才把他解了来。'),
('CUV', '马太福音', 40, 27, 19, '正坐堂的时候，他的夫人打发人来说：这义人的事，你一点不可管，因为我今天在梦中为他受了许多的苦。'),
('CUV', '马太福音', 40, 27, 20, '祭司长和长老挑唆众人，求释放巴拉巴，除灭耶稣。'),
('CUV', '马太福音', 40, 27, 21, '巡抚对众人说：这两个人，你们要我释放那一个给你们呢？他们说：巴拉巴。'),
('CUV', '马太福音', 40, 27, 22, '彼拉多说：这样，那称为基督的耶稣我怎么办他呢？他们都说：把他钉十字架！'),
('CUV', '马太福音', 40, 27, 23, '巡抚说：为甚么呢？他作了甚么恶事呢？他们便极力的喊著说：把他钉十字架！'),
('CUV', '马太福音', 40, 27, 24, '彼拉多见说也无济于事，反要生乱，就拿水在众人面前洗手，说：流这义人的血，罪不在我，你们承当罢。'),
('CUV', '马太福音', 40, 27, 25, '众人都回答说：他的血归到我们和我们的子孙身上。'),
('CUV', '马太福音', 40, 27, 26, '于是彼拉多释放巴拉巴给他们，把耶稣鞭打了，交给人钉十字架。'),
('CUV', '马太福音', 40, 27, 27, '巡抚的兵就把耶稣带进衙门，叫全营的兵都聚集在他那里。'),
('CUV', '马太福音', 40, 27, 28, '他们给他脱了衣服，穿上一件朱红色袍子，'),
('CUV', '马太福音', 40, 27, 29, '用荆棘编做冠冕，戴在他头上，拿一根苇子放在他右手里，跪在他面前，戏弄他，说：恭喜，犹太人的王阿！'),
('CUV', '马太福音', 40, 27, 30, '又吐唾沫在他脸上，拿苇子打他的头。'),
('CUV', '马太福音', 40, 27, 31, '戏弄完了，就给他脱了袍子，仍穿上他自己的衣服，带他出去，要钉十字架。'),
('CUV', '马太福音', 40, 27, 32, '他们出来的时候，遇见一个古利奈人，名叫西门，就勉强他同去，好背著耶稣的十字架。'),
('CUV', '马太福音', 40, 27, 33, '到了一个地方名叫各各他，意思就是髑髅地。'),
('CUV', '马太福音', 40, 27, 34, '兵丁拿苦胆调和的酒给耶稣喝。他尝了，就不肯喝。'),
('CUV', '马太福音', 40, 27, 35, '他们既将他钉在十字架上，就拈阄分他的衣服，'),
('CUV', '马太福音', 40, 27, 36, '又坐在那里看守他。'),
('CUV', '马太福音', 40, 27, 37, '在他头以上安一个牌子，写著他的罪状，说：这是犹太人的王耶稣。'),
('CUV', '马太福音', 40, 27, 38, '当时，有两个强盗和他同钉十字架，一个在右边，一个在左边。'),
('CUV', '马太福音', 40, 27, 39, '从那里经过的人讥诮他，摇著头，说：'),
('CUV', '马太福音', 40, 27, 40, '你这拆毁圣殿、三日又建造起来的，可以救自己罢！你如果是神的儿子，就从十字架上下来罢！'),
('CUV', '马太福音', 40, 27, 41, '祭司长和文士并长老也是这样戏弄他，说：'),
('CUV', '马太福音', 40, 27, 42, '他救了别人，不能救自己。他是以色列的王，现在可以从十字架上下来，我们就信他。'),
('CUV', '马太福音', 40, 27, 43, '他倚靠神，神若喜悦他，现在可以救他；因为他曾说：我是神的儿子。'),
('CUV', '马太福音', 40, 27, 44, '那和他同钉的强盗也是这样的讥诮他。'),
('CUV', '马太福音', 40, 27, 45, '从午正到申初，遍地都黑暗了。'),
('CUV', '马太福音', 40, 27, 46, '约在申初，耶稣大声喊著说：以利！以利！拉马撒巴各大尼？就是说：我的神！我的神！为甚么离弃我？'),
('CUV', '马太福音', 40, 27, 47, '站在那里的人，有的听见就说：这个人呼叫以利亚呢！'),
('CUV', '马太福音', 40, 27, 48, '内中有一个人赶紧跑去，拿海绒蘸满了醋，绑在苇子上，送给他喝。'),
('CUV', '马太福音', 40, 27, 49, '其余的人说：且等著，看以利亚来救他不来。'),
('CUV', '马太福音', 40, 27, 50, '耶稣又大声喊叫，气就断了。'),
('CUV', '马太福音', 40, 27, 51, '忽然，殿里的幔子从上到下裂为两半，地也震动，磐石也崩裂，'),
('CUV', '马太福音', 40, 27, 52, '坟墓也开了，已睡圣徒的身体多有起来的。'),
('CUV', '马太福音', 40, 27, 53, '到耶稣复活以后，他们从坟墓里出来，进了圣城，向许多人显现。'),
('CUV', '马太福音', 40, 27, 54, '百夫长和一同看守耶稣的人看见地震并所经历的事，就极其害怕，说：这真是神的儿子了！'),
('CUV', '马太福音', 40, 27, 55, '有好些妇女在那里，远远的观看；他们是从加利利跟随耶稣来服事他的。'),
('CUV', '马太福音', 40, 27, 56, '内中有抹大拉的马利亚，又有雅各和约西的母亲马利亚，并有西庇太两个儿子的母亲。'),
('CUV', '马太福音', 40, 27, 57, '到了晚上，有一个财主，名叫约瑟，是亚利马太来的，他也是耶稣的门徒。'),
('CUV', '马太福音', 40, 27, 58, '这人去见彼拉多，求耶稣的身体；彼拉多就吩咐给他。'),
('CUV', '马太福音', 40, 27, 59, '约瑟取了身体，用干净细麻布裹好，'),
('CUV', '马太福音', 40, 27, 60, '安放在自己的新坟墓里，就是他凿在磐石里的。他又把大石头滚到墓门口，就去了。'),
('CUV', '马太福音', 40, 27, 61, '有抹大拉的马利亚和那个马利亚在那里，对著坟墓坐著。'),
('CUV', '马太福音', 40, 27, 62, '次日，就是预备日的第二天，祭司长和法利赛人聚集来见彼拉多，说：'),
('CUV', '马太福音', 40, 27, 63, '大人，我们记得那诱惑人的还活著的时候曾说：三日后我要复活。'),
('CUV', '马太福音', 40, 27, 64, '因此，请吩咐人将坟墓把守妥当，直到第三日，恐怕他的门徒来，把他偷了去，就告诉百姓说：他从死里复活了。这样，那后来的迷惑比先前的更利害了！'),
('CUV', '马太福音', 40, 27, 65, '彼拉多说：你们有看守的兵，去罢！尽你们所能的把守妥当。'),
('CUV', '马太福音', 40, 27, 66, '他们就带著看守的兵同去，封了石头，将坟墓把守妥当。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马太福音', 40, 28, 1, '安息日将尽，七日的头一日，天快亮的时候，抹大拉的马利亚和那个马利亚来看坟墓。'),
('CUV', '马太福音', 40, 28, 2, '忽然，地大震动；因为有主的使者从天上下来，把石头滚开，坐在上面。'),
('CUV', '马太福音', 40, 28, 3, '他的像貌如同闪电，衣服洁白如雪。'),
('CUV', '马太福音', 40, 28, 4, '看守的人就因他吓得浑身乱战，甚至和死人一样。'),
('CUV', '马太福音', 40, 28, 5, '天使对妇女说：不要害怕！我知道你们是寻找那钉十字架的耶稣。'),
('CUV', '马太福音', 40, 28, 6, '他不在这里，照他所说的，已经复活了。你们来看安放主的地方。'),
('CUV', '马太福音', 40, 28, 7, '快去告诉他的门徒，说他从死里复活了，并且在你们以先往加利利去，在那里你们要见他。看哪，我已经告诉你们了。'),
('CUV', '马太福音', 40, 28, 8, '妇女们就急忙离开坟墓，又害怕，又大大的欢喜，跑去要报给他的门徒。'),
('CUV', '马太福音', 40, 28, 9, '忽然，耶稣遇见他们，说：愿你们平安！他们就上前抱住他的脚拜他。'),
('CUV', '马太福音', 40, 28, 10, '耶稣对他们说：不要害怕！你们去告诉我的弟兄，叫他们往加利利去，在那里必见我。'),
('CUV', '马太福音', 40, 28, 11, '他们去的时候，看守的兵有几个进城去，将所经历的事都报给祭司长。'),
('CUV', '马太福音', 40, 28, 12, '祭司长和长老聚集商议，就拿许多银钱给兵丁，说：'),
('CUV', '马太福音', 40, 28, 13, '你们要这样说：夜间我们睡觉的时候，他的门徒来，把他偷去了。'),
('CUV', '马太福音', 40, 28, 14, '倘若这话被巡抚听见，有我们劝他，保你们无事。'),
('CUV', '马太福音', 40, 28, 15, '兵丁受了银钱，就照所嘱咐他们的去行。这话就传说在犹太人中间，直到今日。'),
('CUV', '马太福音', 40, 28, 16, '十一个门徒往加利利去，到了耶稣约定的山上。'),
('CUV', '马太福音', 40, 28, 17, '他们见了耶稣就拜他，然而还有人疑惑。'),
('CUV', '马太福音', 40, 28, 18, '耶稣进前来，对他们说：天上地下所有的权柄都赐给我了。'),
('CUV', '马太福音', 40, 28, 19, '所以，你们要去，使万民作我的门徒，奉父、子、圣灵的名给他们施洗（或作：给他们施洗，归于父、子、圣灵的名）。'),
('CUV', '马太福音', 40, 28, 20, '凡我所吩咐你们的，都教训他们遵守，我就常与你们同在，直到世界的末了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 1, 1, '神的儿子，耶稣基督福音的起头。'),
('CUV', '马可福音', 41, 1, 2, '正如先知以赛亚（有古卷无以赛亚三个字）书上记著说：看哪，我要差遣我的使者在你前面，预备道路。'),
('CUV', '马可福音', 41, 1, 3, '在旷野有人声喊著说：预备主的道，修直他的路。'),
('CUV', '马可福音', 41, 1, 4, '照这话，约翰来了，在旷野施洗，传悔改的洗礼，使罪得赦。'),
('CUV', '马可福音', 41, 1, 5, '犹太全地和耶路撒冷的人都出去到约翰那里，承认他们的罪，在约但河里受他的洗。'),
('CUV', '马可福音', 41, 1, 6, '约翰穿骆驼毛的衣服，腰束皮带，吃的是蝗虫、野蜜。'),
('CUV', '马可福音', 41, 1, 7, '他传道说：有一位在我以后来的，能力比我更大，我就是弯腰给他解鞋带也是不配的。'),
('CUV', '马可福音', 41, 1, 8, '我是用水给你们施洗，他却要用圣灵给你们施洗。'),
('CUV', '马可福音', 41, 1, 9, '那时，耶稣从加利利的拿撒勒来，在约但河里受了约翰的洗。'),
('CUV', '马可福音', 41, 1, 10, '他从水里一上来，就看见天裂开了，圣灵仿佛鸽子，降在他身上。'),
('CUV', '马可福音', 41, 1, 11, '又有声音从天上来，说：你是我的爱子，我喜悦你。'),
('CUV', '马可福音', 41, 1, 12, '圣灵就把耶稣催到旷野里去。'),
('CUV', '马可福音', 41, 1, 13, '他在旷野四十天，受撒但的试探，并与野兽同在一处，且有天使来伺候他。'),
('CUV', '马可福音', 41, 1, 14, '约翰下监以后，耶稣来到加利利，宣传神的福音，'),
('CUV', '马可福音', 41, 1, 15, '说：日期满了，神的国近了。你们当悔改，信福音！'),
('CUV', '马可福音', 41, 1, 16, '耶稣顺著加利利的海边走，看见西门和西门的兄弟安得烈在海里撒网；他们本是打鱼的。'),
('CUV', '马可福音', 41, 1, 17, '耶稣对他们说：来跟从我，我要叫你们得人如得鱼一样。'),
('CUV', '马可福音', 41, 1, 18, '他们就立刻舍了网，跟从了他。'),
('CUV', '马可福音', 41, 1, 19, '耶稣稍往前走，又见西庇太的儿子雅各和雅各的兄弟约翰在船上补网。'),
('CUV', '马可福音', 41, 1, 20, '耶稣随即招呼他们，他们就把父亲西庇太和雇工人留在船上，跟从耶稣去了。'),
('CUV', '马可福音', 41, 1, 21, '到了迦百农，耶稣就在安息日进了会堂教训人。'),
('CUV', '马可福音', 41, 1, 22, '众人很希奇他的教训；因为他教训他们，正像有权柄的人，不像文士。'),
('CUV', '马可福音', 41, 1, 23, '在会堂里，有一个人被污鬼附著。他喊叫说：'),
('CUV', '马可福音', 41, 1, 24, '拿撒勒人耶稣，我们与你有甚么相干？你来灭我们么？我知道你是谁，乃是神的圣者。'),
('CUV', '马可福音', 41, 1, 25, '耶稣责备他说：不要作声！从这人身上出来罢。'),
('CUV', '马可福音', 41, 1, 26, '污鬼叫那人抽了一阵疯，大声喊叫，就出来了。'),
('CUV', '马可福音', 41, 1, 27, '众人都惊讶，以致彼此对问说：这是甚么事？是个新道理阿！他用权柄吩咐污鬼，连污鬼也听从了他。'),
('CUV', '马可福音', 41, 1, 28, '耶稣的名声就传遍了加利利的四方。'),
('CUV', '马可福音', 41, 1, 29, '他们一出会堂，就同著雅各、约翰，进了西门和安得烈的家。'),
('CUV', '马可福音', 41, 1, 30, '西门的岳母正害热病躺著，就有人告诉耶稣。'),
('CUV', '马可福音', 41, 1, 31, '耶稣进前拉著他的手，扶他起来，热就退了，他就服事他们。'),
('CUV', '马可福音', 41, 1, 32, '天晚日落的时候，有人带著一切害病的，和被鬼附的，来到耶稣跟前。'),
('CUV', '马可福音', 41, 1, 33, '合城的人都聚集在门前。'),
('CUV', '马可福音', 41, 1, 34, '耶稣治好了许多害各样病的人，又赶出许多鬼，不许鬼说话，因为鬼认识他。'),
('CUV', '马可福音', 41, 1, 35, '次日早晨，天未亮的时候，耶稣起来，到旷野地方去，在那里祷告。'),
('CUV', '马可福音', 41, 1, 36, '西门和同伴追了他去，'),
('CUV', '马可福音', 41, 1, 37, '遇见了就对他说：众人都找你。'),
('CUV', '马可福音', 41, 1, 38, '耶稣对他们说：我们可以往别处去，到邻近的乡村，我也好在那里传道，因为我是为这事出来的。'),
('CUV', '马可福音', 41, 1, 39, '于是在加利利全地，进了会堂，传道，赶鬼。'),
('CUV', '马可福音', 41, 1, 40, '有一个长大痲疯的来求耶稣，向他跪下，说：你若肯，必能叫我洁净了。'),
('CUV', '马可福音', 41, 1, 41, '耶稣动了慈心，就伸手摸他，说：我肯，你洁净了罢！'),
('CUV', '马可福音', 41, 1, 42, '大痲疯即时离开他，他就洁净了。'),
('CUV', '马可福音', 41, 1, 43, '耶稣严严的嘱咐他，就打发他走，'),
('CUV', '马可福音', 41, 1, 44, '对他说：你要谨慎，甚么话都不可告诉人，只要去把身体给祭司察看，又因为你洁净了，献上摩西所吩咐的礼物，对众人作证据。'),
('CUV', '马可福音', 41, 1, 45, '那人出去，倒说许多的话，把这件事传扬开了，叫耶稣以后不得再明明的进城，只好在外边旷野地方。人从各处都就了他来。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 2, 1, '过了些日子，耶稣又进了迦百农。人听见他在房子里，'),
('CUV', '马可福音', 41, 2, 2, '就有许多人聚集，甚至连门前都没有空地；耶稣就对他们讲道。'),
('CUV', '马可福音', 41, 2, 3, '有人带著一个瘫子来见耶稣，是用四个人抬来的；'),
('CUV', '马可福音', 41, 2, 4, '因为人多，不得近前，就把耶稣所在的房子，拆了房顶，既拆通了，就把瘫子连所躺卧的褥子都缒下来。'),
('CUV', '马可福音', 41, 2, 5, '耶稣见他们的信心，就对瘫子说：小子，你的罪赦了。'),
('CUV', '马可福音', 41, 2, 6, '有几个文士坐在那里，心里议论，说：'),
('CUV', '马可福音', 41, 2, 7, '这个人为甚么这样说呢？他说僭妄的话了。除了神以外，谁能赦罪呢？'),
('CUV', '马可福音', 41, 2, 8, '耶稣心中知道他们心里这样议论，就说：你们心里为甚么这样议论呢？'),
('CUV', '马可福音', 41, 2, 9, '或对瘫子说你的罪赦了，或说起来！拿你的褥子行走；那一样容易呢？'),
('CUV', '马可福音', 41, 2, 10, '但要叫你们知道，人子在地上有赦罪的权柄。就对瘫子说：'),
('CUV', '马可福音', 41, 2, 11, '我吩咐你，起来！拿你的褥子回家去罢。'),
('CUV', '马可福音', 41, 2, 12, '那人就起来，立刻拿著褥子，当众人面前出去了，以致众人都惊奇，归荣耀与神，说：我们从来没有见过这样的事！'),
('CUV', '马可福音', 41, 2, 13, '耶稣又出到海边去，众人都就了他来，他便教训他们。'),
('CUV', '马可福音', 41, 2, 14, '耶稣经过的时候，看见亚勒腓的儿子利未坐在税关上，就对他说：你跟从我来。他就起来，跟从了耶稣。'),
('CUV', '马可福音', 41, 2, 15, '耶稣在利未家里坐席的时候，有好些税吏和罪人与耶稣并门徒一同坐席；因为这样的人多，他们也跟随耶稣。'),
('CUV', '马可福音', 41, 2, 16, '法利赛人中的文士（有古卷：文士和法利赛人）看见耶稣和罪人并税吏一同吃饭，就对他门徒说：他和税吏并罪人一同吃喝么？'),
('CUV', '马可福音', 41, 2, 17, '耶稣听见，就对他们说：康健的人用不著医生，有病的人才用得著。我来本不是召义人，乃是召罪人。'),
('CUV', '马可福音', 41, 2, 18, '当下，约翰的门徒和法利赛人禁食。他们来问耶稣说：约翰的门徒和法利赛人的门徒禁食，你的门徒倒不禁食，这是为甚么呢？'),
('CUV', '马可福音', 41, 2, 19, '耶稣对他们说：新郎和陪伴之人同在的时候，陪伴之人岂能禁食呢？新郎还同在，他们不能禁食。'),
('CUV', '马可福音', 41, 2, 20, '但日子将到，新郎要离开他们，那日他们就要禁食。'),
('CUV', '马可福音', 41, 2, 21, '没有人把新布缝在旧衣服上，恐怕所补上的新布带坏了旧衣服，破的就更大了。'),
('CUV', '马可福音', 41, 2, 22, '也没有人把新酒装在旧皮袋里，恐怕酒把皮袋裂开，酒和皮袋就都坏了；惟把新酒装在新皮袋里。'),
('CUV', '马可福音', 41, 2, 23, '耶稣当安息日从麦地经过。他门徒行路的时候，掐了麦穗。'),
('CUV', '马可福音', 41, 2, 24, '法利赛人对耶稣说：看哪，他们在安息日为甚么做不可做的事呢？'),
('CUV', '马可福音', 41, 2, 25, '耶稣对他们说：经上记著大卫和跟从他的人缺乏饥饿之时所做的事，你们没有念过么？'),
('CUV', '马可福音', 41, 2, 26, '他当亚比亚他作大祭司的时候，怎么进了神的殿，吃了陈设饼，又给跟从他的人吃。这饼除了祭司以外，人都不可吃。'),
('CUV', '马可福音', 41, 2, 27, '又对他们说：安息日是为人设立的，人不是为安息日设立的。'),
('CUV', '马可福音', 41, 2, 28, '所以，人子也是安息日的主。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 3, 1, '耶稣又进了会堂，在那里有一个人枯干了一只手。'),
('CUV', '马可福音', 41, 3, 2, '众人窥探耶稣，在安息日医治不医治，意思是要控告耶稣。'),
('CUV', '马可福音', 41, 3, 3, '耶稣对那枯干一只手的人说：起来，站在当中。'),
('CUV', '马可福音', 41, 3, 4, '又问众人说：在安息日行善行恶，救命害命，那样是可以的呢？他们都不作声。'),
('CUV', '马可福音', 41, 3, 5, '耶稣怒目周围看他们，忧愁他们的心刚硬，就对那人说：伸出手来！他把手一伸，手就复了原。'),
('CUV', '马可福音', 41, 3, 6, '法利赛人出去，同希律一党的人商议怎样可以除灭耶稣。'),
('CUV', '马可福音', 41, 3, 7, '耶稣和门徒退到海边去，有许多人从加利利跟随他。'),
('CUV', '马可福音', 41, 3, 8, '还有许多人听见他所做的大事，就从犹太、耶路撒冷、以土买、约但河外，并推罗、西顿的四方来到他那里。'),
('CUV', '马可福音', 41, 3, 9, '他因为人多，就吩咐门徒叫一只小船伺候著，免得众人拥挤他。'),
('CUV', '马可福音', 41, 3, 10, '他治好了许多人，所以凡有灾病的，都挤进来要摸他。'),
('CUV', '马可福音', 41, 3, 11, '污鬼无论何时看见他，就俯伏在他面前，喊著说：你是神的儿子。'),
('CUV', '马可福音', 41, 3, 12, '耶稣再三的嘱咐他们，不要把他显露出来。'),
('CUV', '马可福音', 41, 3, 13, '耶稣上了山，随自己的意思叫人来；他们便来到他那里。'),
('CUV', '马可福音', 41, 3, 14, '他就设立十二个人，要他们常和自己同在，也要差他们去传道，'),
('CUV', '马可福音', 41, 3, 15, '并给他们权柄赶鬼。'),
('CUV', '马可福音', 41, 3, 16, '这十二个人有西门─耶稣又给他起名叫彼得，'),
('CUV', '马可福音', 41, 3, 17, '还有西庇太的儿子雅各和雅各的兄弟约翰，又给这两个人起名叫半尼其，就是雷子的意思，'),
('CUV', '马可福音', 41, 3, 18, '又有安得烈、腓力、巴多罗买、马太、多马、亚勒腓的儿子雅各、和达太，并奋锐党的西门；'),
('CUV', '马可福音', 41, 3, 19, '还有卖耶稣的加略人犹大。'),
('CUV', '马可福音', 41, 3, 20, '耶稣进了一个屋子，众人又聚集，甚至他连饭也顾不得吃。'),
('CUV', '马可福音', 41, 3, 21, '耶稣的亲属听见，就出来要拉住他，因为他们说他癫狂了。'),
('CUV', '马可福音', 41, 3, 22, '从耶路撒冷下来的文士说：他是被别西卜附著；又说：他是靠著鬼王赶鬼。'),
('CUV', '马可福音', 41, 3, 23, '耶稣叫他们来，用比喻对他们说：撒但怎能赶出撒但呢？'),
('CUV', '马可福音', 41, 3, 24, '若一国自相分争，那国就站立不住；'),
('CUV', '马可福音', 41, 3, 25, '若一家自相分争，那家就站立不住。'),
('CUV', '马可福音', 41, 3, 26, '若撒但自相攻打分争，他就站立不住，必要灭亡。'),
('CUV', '马可福音', 41, 3, 27, '没有人能进壮士家里，抢夺他的家具；必先捆住那壮士，才可以抢夺他的家。'),
('CUV', '马可福音', 41, 3, 28, '我实在告诉你们，世人一切的罪和一切亵渎的话都可得赦免；'),
('CUV', '马可福音', 41, 3, 29, '凡亵渎圣灵的，却永不得赦免，乃要担当永远的罪。'),
('CUV', '马可福音', 41, 3, 30, '这话是因为他们说：他是被污鬼附著的。'),
('CUV', '马可福音', 41, 3, 31, '当下，耶稣的母亲和弟兄来，站在外边，打发人去叫他。'),
('CUV', '马可福音', 41, 3, 32, '有许多人在耶稣周围坐著，他们就告诉他说：看哪，你母亲和你弟兄在外边找你。'),
('CUV', '马可福音', 41, 3, 33, '耶稣回答说：谁是我的母亲？谁是我的弟兄？'),
('CUV', '马可福音', 41, 3, 34, '就四面观看那周围坐著的人，说：看哪，我的母亲，我的弟兄。'),
('CUV', '马可福音', 41, 3, 35, '凡遵行神旨意的人就是我的弟兄姐妹和母亲了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 4, 1, '耶稣又在海边教训人。有许多人到他那里聚集，他只得上船坐下。船在海里，众人都靠近海，站在岸上。'),
('CUV', '马可福音', 41, 4, 2, '耶稣就用比喻教训他们许多道理。在教训之间，对他们说：'),
('CUV', '马可福音', 41, 4, 3, '你们听阿！有一个撒种的出去撒种。'),
('CUV', '马可福音', 41, 4, 4, '撒的时候，有落在路旁的，飞鸟来吃尽了；'),
('CUV', '马可福音', 41, 4, 5, '有落在土浅石头地上的，土既不深，发苗最快，'),
('CUV', '马可福音', 41, 4, 6, '日头出来一晒，因为没有根，就枯干了；'),
('CUV', '马可福音', 41, 4, 7, '有落在荆棘里的，荆棘长起来，把他挤住了，就不结实；'),
('CUV', '马可福音', 41, 4, 8, '又有落在好土里的，就发生长大，结实有三十倍的，有六十倍的，有一百倍的；'),
('CUV', '马可福音', 41, 4, 9, '又说：有耳可听的，就应当听！'),
('CUV', '马可福音', 41, 4, 10, '无人的时候，跟随耶稣的人和十二个门徒问他这比喻的意思。'),
('CUV', '马可福音', 41, 4, 11, '耶稣对他们说：神国的奥秘只叫你们知道，若是对外人讲，凡事就用比喻，'),
('CUV', '马可福音', 41, 4, 12, '叫他们看是看见，却不晓得；听是听见，却不明白；恐怕他们回转过来，就得赦免。'),
('CUV', '马可福音', 41, 4, 13, '又对他们说：你们不明白这比喻么？这样怎能明白一切的比喻呢？'),
('CUV', '马可福音', 41, 4, 14, '撒种之人所撒的就是道。'),
('CUV', '马可福音', 41, 4, 15, '那撒在路旁的，就是人听了道，撒但立刻来，把撒在他心里的道夺了去。'),
('CUV', '马可福音', 41, 4, 16, '那撒在石头地上的，就是人听了道，立刻欢喜领受，'),
('CUV', '马可福音', 41, 4, 17, '但他心里没有根，不过是暂时的，及至为道遭了患难，或是受了逼迫，立刻就跌倒了。'),
('CUV', '马可福音', 41, 4, 18, '还有那撒在荆棘里的，就是人听了道，'),
('CUV', '马可福音', 41, 4, 19, '后来有世上的思虑、钱财的迷惑，和别样的私欲进来，把道挤住了，就不能结实。'),
('CUV', '马可福音', 41, 4, 20, '那撒在好地上的，就是人听道，又领受，并且结实，有三十倍的，有六十倍的，有一百倍的。'),
('CUV', '马可福音', 41, 4, 21, '耶稣又对他们说：人拿灯来，岂是要放在斗底下，床底下，不放在灯台上么？'),
('CUV', '马可福音', 41, 4, 22, '因为掩藏的事，没有不显出来的；隐瞒的事，没有不露出来的。'),
('CUV', '马可福音', 41, 4, 23, '有耳可听的，就应当听！'),
('CUV', '马可福音', 41, 4, 24, '又说：你们所听的要留心。你们用甚么量器量给人，也必用甚么量器量给你们，并且要多给你们。'),
('CUV', '马可福音', 41, 4, 25, '因为有的，还要给他；没有的，连他所有的也要夺去。'),
('CUV', '马可福音', 41, 4, 26, '又说：神的国如同人把种撒在地上。'),
('CUV', '马可福音', 41, 4, 27, '黑夜睡觉，白日起来，这种就发芽渐长，那人却不晓得如何这样。'),
('CUV', '马可福音', 41, 4, 28, '地生五谷是出于自然的：先发苗，后长穗，再后穗上结成饱满的子粒；'),
('CUV', '马可福音', 41, 4, 29, '谷既熟了，就用镰刀去割，因为收成的时候到了。'),
('CUV', '马可福音', 41, 4, 30, '又说：神的国，我们可用甚么比较呢？可用甚么比喻表明呢？'),
('CUV', '马可福音', 41, 4, 31, '好像一粒芥菜种，种在地里的时候，虽比地上的百种都小，'),
('CUV', '马可福音', 41, 4, 32, '但种上以后，就长起来，比各样的菜都大，又长出大枝来，甚至天上的飞鸟可以宿在他的荫下。'),
('CUV', '马可福音', 41, 4, 33, '耶稣用许多这样的比喻，照他们所能听的，对他们讲道。'),
('CUV', '马可福音', 41, 4, 34, '若不用比喻，就不对他们讲；没有人的时候，就把一切的道讲给门徒听。'),
('CUV', '马可福音', 41, 4, 35, '当那天晚上，耶稣对门徒说：我们渡到那边去罢。'),
('CUV', '马可福音', 41, 4, 36, '门徒离开众人，耶稣仍在船上，他们就把他一同带去；也有别的船和他同行。'),
('CUV', '马可福音', 41, 4, 37, '忽然起了暴风，波浪打入船内，甚至船要满了水。'),
('CUV', '马可福音', 41, 4, 38, '耶稣在船尾上，枕著枕头睡觉。门徒叫醒了他，说：夫子！我们丧命，你不顾么？'),
('CUV', '马可福音', 41, 4, 39, '耶稣醒了，斥责风，向海说：住了罢！静了罢！风就止住，大大的平静了。'),
('CUV', '马可福音', 41, 4, 40, '耶稣对他们说：为甚么胆怯？你们还没有信心么？'),
('CUV', '马可福音', 41, 4, 41, '他们就大大的惧怕，彼此说：这到底是谁，连风和海也听从他了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 5, 1, '他们来到海那边格拉森人的地方。'),
('CUV', '马可福音', 41, 5, 2, '耶稣一下船，就有一个被污鬼附著的人从坟茔里出来迎著他。'),
('CUV', '马可福音', 41, 5, 3, '那人常住在坟茔里，没有人能捆住他，就是用铁链也不能；'),
('CUV', '马可福音', 41, 5, 4, '因为人屡次用脚镣和铁链捆锁他，铁链竟被他挣断了，脚镣也被他弄碎了；总没有人能制伏他。'),
('CUV', '马可福音', 41, 5, 5, '他昼夜常在坟茔里和山中喊叫，又用石头砍自己。'),
('CUV', '马可福音', 41, 5, 6, '他远远的看见耶稣，就跑过去拜他，'),
('CUV', '马可福音', 41, 5, 7, '大声呼叫说：至高神的儿子耶稣，我与你有甚么相干？我指著神恳求你，不要叫我受苦！'),
('CUV', '马可福音', 41, 5, 8, '是因耶稣曾吩咐他说：污鬼阿，从这人身上出来罢！'),
('CUV', '马可福音', 41, 5, 9, '耶稣问他说：你名叫甚么？回答说：我名叫群，因为我们多的缘故；'),
('CUV', '马可福音', 41, 5, 10, '就再三的求耶稣，不要叫他们离开那地方。'),
('CUV', '马可福音', 41, 5, 11, '在那里山坡上，有一大群猪吃食；'),
('CUV', '马可福音', 41, 5, 12, '鬼就央求耶稣说：求你打发我们往猪群里，附著猪去。'),
('CUV', '马可福音', 41, 5, 13, '耶稣准了他们，污鬼就出来，进入猪里去。于是那群猪闯下山崖，投在海里，淹死了。猪的数目约有二千。'),
('CUV', '马可福音', 41, 5, 14, '放猪的就逃跑了，去告诉城里和乡下的人。众人就来，要看是甚么事。'),
('CUV', '马可福音', 41, 5, 15, '他们来到耶稣那里，看见那被鬼附著的人，就是从前被群鬼所附的，坐著，穿上衣服，心里明白过来，他们就害怕。'),
('CUV', '马可福音', 41, 5, 16, '看见这事的，便将鬼附之人所遇见的和那群猪的事都告诉了众人；'),
('CUV', '马可福音', 41, 5, 17, '众人就央求耶稣离开他们的境界。'),
('CUV', '马可福音', 41, 5, 18, '耶稣上船的时候，那从前被鬼附著的人恳求和耶稣同在。'),
('CUV', '马可福音', 41, 5, 19, '耶稣不许，却对他说：你回家去，到你的亲属那里，将主为你所做的是何等大的事，是怎样怜悯你，都告诉他们。'),
('CUV', '马可福音', 41, 5, 20, '那人就走了，在低加波利传扬耶稣为他做了何等大的事，众人就都希奇。'),
('CUV', '马可福音', 41, 5, 21, '耶稣坐船又渡到那边去，就有许多人到他那里聚集；他正在海边上。'),
('CUV', '马可福音', 41, 5, 22, '有一个管会堂的人，名叫睚鲁，来见耶稣，就俯伏在他脚前，'),
('CUV', '马可福音', 41, 5, 23, '再三的求他，说：我的小女儿快要死了，求你去按手在他身上，使他痊愈，得以活了。'),
('CUV', '马可福音', 41, 5, 24, '耶稣就和他同去。有许多人跟随拥挤他。'),
('CUV', '马可福音', 41, 5, 25, '有一个女人，患了十二年的血漏，'),
('CUV', '马可福音', 41, 5, 26, '在好些医生手里受了许多的苦，又花尽了他所有的，一点也不见好，病势反倒更重了。'),
('CUV', '马可福音', 41, 5, 27, '他听见耶稣的事，就从后头来，杂在众人中间，摸耶稣的衣裳，'),
('CUV', '马可福音', 41, 5, 28, '意思说：我只摸他的衣裳，就必痊愈。'),
('CUV', '马可福音', 41, 5, 29, '于是他血漏的源头立刻干了；他便觉得身上的灾病好了。'),
('CUV', '马可福音', 41, 5, 30, '耶稣顿时心里觉得有能力从自己身上出去，就在众人中间转过来，说：谁摸我的衣裳？'),
('CUV', '马可福音', 41, 5, 31, '门徒对他说：你看众人拥挤你，还说谁摸我么？'),
('CUV', '马可福音', 41, 5, 32, '耶稣周围观看，要见做这事的女人。'),
('CUV', '马可福音', 41, 5, 33, '那女人知道在自己身上所成的事，就恐惧战兢，来俯伏在耶稣跟前，将实情全告诉他。'),
('CUV', '马可福音', 41, 5, 34, '耶稣对他说：女儿，你的信救了你，平平安安的回去罢！你的灾病痊愈了。'),
('CUV', '马可福音', 41, 5, 35, '还说话的时候，有人从管会堂的家里来，说：你的女儿死了，何必还劳动先生呢？'),
('CUV', '马可福音', 41, 5, 36, '耶稣听见所说的话，就对管会堂的说：不要怕，只要信！'),
('CUV', '马可福音', 41, 5, 37, '于是带著彼得、雅各、和雅各的兄弟约翰同去，不许别人跟随他。'),
('CUV', '马可福音', 41, 5, 38, '他们来到管会堂的家里；耶稣看见那里乱嚷，并有人大大的哭泣哀号，'),
('CUV', '马可福音', 41, 5, 39, '进到里面，就对他们说：为甚么乱嚷哭泣呢？孩子不是死了，是睡著了。'),
('CUV', '马可福音', 41, 5, 40, '他们就嗤笑耶稣。耶稣把他们都撵出去，就带著孩子的父母，和跟随的人进了孩子所在的地方，'),
('CUV', '马可福音', 41, 5, 41, '就拉著孩子的手，对他说：大利大，古米！繙出来就是说：闺女，我吩咐你起来！'),
('CUV', '马可福音', 41, 5, 42, '那闺女立时起来走。他们就大大的惊奇；闺女已经十二岁了。'),
('CUV', '马可福音', 41, 5, 43, '耶稣切切的嘱咐他们，不要叫人知道这事，又吩咐给他东西吃。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 6, 1, '耶稣离开那里，来到自己的家乡；门徒也跟从他。'),
('CUV', '马可福音', 41, 6, 2, '到了安息日，他在会堂里教训人。众人听见，就甚希奇，说：这人从那里有这些事呢？所赐给他的是甚么智慧？他手所做的是何等的异能呢？'),
('CUV', '马可福音', 41, 6, 3, '这不是那木匠么？不是马利亚的儿子雅各、约西、犹大、西门的长兄么？他妹妹们不也是在我们这里么？他们就厌弃他。（厌弃他：原文是因他跌倒）'),
('CUV', '马可福音', 41, 6, 4, '耶稣对他们说：大凡先知，除了本地、亲属、本家之外，没有不被人尊敬的。'),
('CUV', '马可福音', 41, 6, 5, '耶稣就在那里不得行甚么异能，不过按手在几个病人身上，治好他们。'),
('CUV', '马可福音', 41, 6, 6, '他也诧异他们不信，就往周围乡村教训人去了。'),
('CUV', '马可福音', 41, 6, 7, '耶稣叫了十二个门徒来，差遣他们两个两个的出去，也赐给他们权柄，制伏污鬼；'),
('CUV', '马可福音', 41, 6, 8, '并且嘱咐他们：行路的时候不要带食物和口袋，腰袋里也不要带钱，除了拐杖以外，甚么都不要带；'),
('CUV', '马可福音', 41, 6, 9, '只要穿鞋，也不要穿两件挂子，'),
('CUV', '马可福音', 41, 6, 10, '又对他们说：你们无论到何处，进了人的家，就住在那里，直到离开那地方。'),
('CUV', '马可福音', 41, 6, 11, '何处的人不接待你们，不听你们，你们离开那里的时候，就把脚上的尘土跺下去，对他们作见证。'),
('CUV', '马可福音', 41, 6, 12, '门徒就出去传道，叫人悔改，'),
('CUV', '马可福音', 41, 6, 13, '又赶出许多的鬼，用油抹了许多病人，治好他们。'),
('CUV', '马可福音', 41, 6, 14, '耶稣的名声传扬出来。希律王听见了，就说：施洗的约翰从死里复活了，所以这些异能由他里面发出来。'),
('CUV', '马可福音', 41, 6, 15, '但别人说：是以利亚。又有人说：是先知，正像先知中的一位。'),
('CUV', '马可福音', 41, 6, 16, '希律听见却说：是我所斩的约翰，他复活了。'),
('CUV', '马可福音', 41, 6, 17, '先是希律为他兄弟腓力的妻子希罗底的缘故，差人去拿住约翰，锁在监里，因为希律已经娶了那妇人。'),
('CUV', '马可福音', 41, 6, 18, '约翰曾对希律说：你娶你兄弟的妻子是不合理的。'),
('CUV', '马可福音', 41, 6, 19, '于是希罗底怀恨他，想要杀他，只是不能；'),
('CUV', '马可福音', 41, 6, 20, '因为希律知道约翰是义人，是圣人，所以敬畏他，保护他，听他讲论，就多照著行（有古卷：游移不定），并且乐意听他。'),
('CUV', '马可福音', 41, 6, 21, '有一天，恰巧是希律的生日，希律摆设筵席，请了大臣和千夫长，并加利利作首领的。'),
('CUV', '马可福音', 41, 6, 22, '希罗底的女儿进来跳舞，使希律和同席的人都欢喜。王就对女子说：你随意向我求甚么，我必给你；'),
('CUV', '马可福音', 41, 6, 23, '又对他起誓说：随你向我求甚么，就是我国的一半，我也必给你。'),
('CUV', '马可福音', 41, 6, 24, '他就出去对他母亲说：我可以求甚么呢？他母亲说：施洗约翰的头。'),
('CUV', '马可福音', 41, 6, 25, '他就急忙进去见王，求他说：我愿王立时把施洗约翰的头放在盘子里给我。'),
('CUV', '马可福音', 41, 6, 26, '王就甚忧愁；但因他所起的誓，又因同席的人，就不肯推辞，'),
('CUV', '马可福音', 41, 6, 27, '随即差一个护卫兵，吩咐拿约翰的头来。护卫兵就去，在监里斩了约翰，'),
('CUV', '马可福音', 41, 6, 28, '把头放在盘子里，拿来给女子，女子就给他母亲。'),
('CUV', '马可福音', 41, 6, 29, '约翰的门徒听见了，就来把他的尸首领去，葬在坟墓里。'),
('CUV', '马可福音', 41, 6, 30, '使徒聚集到耶稣那里，将一切所做的事、所传的道全告诉他。'),
('CUV', '马可福音', 41, 6, 31, '他就说：你们来，同我暗暗的到旷野地方去歇一歇。这是因为来往的人多，他们连吃饭也没有工夫。'),
('CUV', '马可福音', 41, 6, 32, '他们就坐船，暗暗的往旷野地方去。'),
('CUV', '马可福音', 41, 6, 33, '众人看见他们去，有许多认识他们的，就从各城步行，一同跑到那里，比他们先赶到了。'),
('CUV', '马可福音', 41, 6, 34, '耶稣出来，见有许多的人，就怜悯他们，因为他们如同羊没有牧人一般，于是开口教训他们许多道理。'),
('CUV', '马可福音', 41, 6, 35, '天已经晚了，门徒进前来，说：这是野地，天已经晚了，'),
('CUV', '马可福音', 41, 6, 36, '请叫众人散开，他们好往四面乡村里去，自己买甚么吃。'),
('CUV', '马可福音', 41, 6, 37, '耶稣回答说：你们给他们吃罢。门徒说：我们可以去买二十两银子的饼，给他们吃么？'),
('CUV', '马可福音', 41, 6, 38, '耶稣说：你们有多少饼，可以去看看。他们知道了，就说：五个饼，两条鱼。'),
('CUV', '马可福音', 41, 6, 39, '耶稣吩咐他们，叫众人一帮一帮的坐在青草地上。'),
('CUV', '马可福音', 41, 6, 40, '众人就一排一排的坐下，有一百一排的，有五十一排的。'),
('CUV', '马可福音', 41, 6, 41, '耶稣拿著这五个饼，两条鱼，望著天祝福，擘开饼，递给门徒，摆在众人面前，也把那两条鱼分给众人。'),
('CUV', '马可福音', 41, 6, 42, '他们都吃，并且吃饱了。'),
('CUV', '马可福音', 41, 6, 43, '门徒就把碎饼碎鱼收拾起来，装满了十二个篮子。'),
('CUV', '马可福音', 41, 6, 44, '吃饼的男人共有五千。'),
('CUV', '马可福音', 41, 6, 45, '耶稣随即催门徒上船，先渡到那边伯赛大去，等他叫众人散开。'),
('CUV', '马可福音', 41, 6, 46, '他既辞别了他们，就往山上去祷告。'),
('CUV', '马可福音', 41, 6, 47, '到了晚上，船在海中，耶稣独自在岸上；'),
('CUV', '马可福音', 41, 6, 48, '看见门徒因风不顺，摇橹甚苦。夜里约有四更天，就在海面上走，往他们那里去，意思要走过他们去。'),
('CUV', '马可福音', 41, 6, 49, '但门徒看见他在海面上走，以为是鬼怪，就喊叫起来；'),
('CUV', '马可福音', 41, 6, 50, '因为他们都看见了他，且甚惊慌。耶稣连忙对他们说：你们放心！是我，不要怕！'),
('CUV', '马可福音', 41, 6, 51, '于是到他们那里，上了船，风就住了；他们心里十分惊奇。'),
('CUV', '马可福音', 41, 6, 52, '这是因为他们不明白那分饼的事，心里还是愚顽。'),
('CUV', '马可福音', 41, 6, 53, '既渡过去，来到革尼撒勒地方，就靠了岸，'),
('CUV', '马可福音', 41, 6, 54, '一下船，众人认得是耶稣，'),
('CUV', '马可福音', 41, 6, 55, '就跑遍那一带地方，听见他在何处，便将有病的人用褥子抬到那里。'),
('CUV', '马可福音', 41, 6, 56, '凡耶稣所到的地方，或村中，或城里，或乡间，他们都将病人放在街市上，求耶稣只容他们摸他的衣裳䍁子；凡摸著的人就都好了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 7, 1, '有法利赛人和几个文士从耶路撒冷来，到耶稣那里聚集。'),
('CUV', '马可福音', 41, 7, 2, '他们曾看见他的门徒中有人用俗手，就是没有洗的手，吃饭。'),
('CUV', '马可福音', 41, 7, 3, '（原来法利赛人和犹太人都拘守古人的遗传，若不仔细洗手就不吃饭；'),
('CUV', '马可福音', 41, 7, 4, '从市上来，若不洗浴也不吃饭；还有好些别的规矩，他们历代拘守，就是洗杯、罐、铜器等物。）'),
('CUV', '马可福音', 41, 7, 5, '法利赛人和文士问他说：你的门徒为甚么不照古人的遗传，用俗手吃饭呢？'),
('CUV', '马可福音', 41, 7, 6, '耶稣说：以赛亚指著你们假冒为善之人所说的预言是不错的。如经上说：这百姓用嘴唇尊敬我，心却远离我。'),
('CUV', '马可福音', 41, 7, 7, '他们将人的吩咐当作道理教导人，所以拜我也是枉然。'),
('CUV', '马可福音', 41, 7, 8, '你们是离弃神的诫命，拘守人的遗传；'),
('CUV', '马可福音', 41, 7, 9, '又说：你们诚然是废弃神的诫命，要守自己的遗传。'),
('CUV', '马可福音', 41, 7, 10, '摩西说：当孝敬父母；又说：咒骂父母的，必治死他。'),
('CUV', '马可福音', 41, 7, 11, '你们倒说：人若对父母说：我所当奉给你的，已经作了各耳板（各耳板就是供献的意思），'),
('CUV', '马可福音', 41, 7, 12, '以后你们就不容他再奉养父母。'),
('CUV', '马可福音', 41, 7, 13, '这就是你们承接遗传，废了神的道。你们还做许多这样的事。'),
('CUV', '马可福音', 41, 7, 14, '耶稣又叫众人来，对他们说：你们都要听我的话，也要明白。'),
('CUV', '马可福音', 41, 7, 15, '从外面进去的不能污秽人，惟有从里面出来的乃能污秽人。（有古卷在此有：'),
('CUV', '马可福音', 41, 7, 16, '有耳可听的，就应当听！）'),
('CUV', '马可福音', 41, 7, 17, '耶稣离开众人，进了屋子，门徒就问他这比喻的意思。'),
('CUV', '马可福音', 41, 7, 18, '耶稣对他们说：你们也是这样不明白么？岂不晓得凡从外面进入的，不能污秽人，'),
('CUV', '马可福音', 41, 7, 19, '因为不是入他的心，乃是入他的肚腹，又落到茅厕里。这是说，各样的食物都是洁净的；'),
('CUV', '马可福音', 41, 7, 20, '又说：从人里面出来的，那才能污秽人；'),
('CUV', '马可福音', 41, 7, 21, '因为从里面，就是从人心里，发出恶念、苟合、'),
('CUV', '马可福音', 41, 7, 22, '偷盗、凶杀、奸淫、贪婪、邪恶、诡诈、淫荡、嫉妒、谤讟、骄傲、狂妄。'),
('CUV', '马可福音', 41, 7, 23, '这一切的恶都是从里面出来，且能污秽人。'),
('CUV', '马可福音', 41, 7, 24, '耶稣从那里起身，往推罗、西顿的境内去，进了一家，不愿意人知道，却隐藏不住。'),
('CUV', '马可福音', 41, 7, 25, '当下，有一个妇人，他的小女儿被污鬼附著，听见耶稣的事，就来俯伏在他脚前。'),
('CUV', '马可福音', 41, 7, 26, '这妇人是希利尼人，属叙利腓尼基族。他求耶稣赶出那鬼离开他的女儿。'),
('CUV', '马可福音', 41, 7, 27, '耶稣对他说：让儿女们先吃饱，不好拿儿女的饼丢给狗吃。'),
('CUV', '马可福音', 41, 7, 28, '妇人回答说：主阿，不错；但是狗在桌子底下也吃孩子们的碎渣儿。'),
('CUV', '马可福音', 41, 7, 29, '耶稣对他说：因这句话，你回去罢；鬼已经离开你的女儿了。'),
('CUV', '马可福音', 41, 7, 30, '他就回家去，见小孩子躺在床上，鬼已经出去了。'),
('CUV', '马可福音', 41, 7, 31, '耶稣又离了推罗的境界，经过西顿，就从低加波利境内来到加利利海。'),
('CUV', '马可福音', 41, 7, 32, '有人带著一个耳聋舌结的人来见耶稣，求他按手在他身上。'),
('CUV', '马可福音', 41, 7, 33, '耶稣领他离开众人，到一边去，就用指头探他的耳朵，吐唾沫抹他的舌头，'),
('CUV', '马可福音', 41, 7, 34, '望天叹息，对他说：以法大！就是说：开了罢！'),
('CUV', '马可福音', 41, 7, 35, '他的耳朵就开了，舌结也解了，说话也清楚了。'),
('CUV', '马可福音', 41, 7, 36, '耶稣嘱咐他们不要告诉人；但他越发嘱咐，他们越发传扬开了。'),
('CUV', '马可福音', 41, 7, 37, '众人分外希奇，说：他所做的事都好，他连聋子也叫他们听见，哑吧也叫他们说话。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 8, 1, '那时，又有许多人聚集，并没有甚么吃的。耶稣叫门徒来，说：'),
('CUV', '马可福音', 41, 8, 2, '我怜悯这众人；因为他们同我在这里已经三天，也没有吃的了。'),
('CUV', '马可福音', 41, 8, 3, '我若打发他们饿著回家，就必在路上困乏，因为其中有从远处来的。'),
('CUV', '马可福音', 41, 8, 4, '门徒回答说：在这野地，从那里能得饼，叫这些人吃饱呢？'),
('CUV', '马可福音', 41, 8, 5, '耶稣问他们说：你们有多少饼？他们说：七个。'),
('CUV', '马可福音', 41, 8, 6, '他吩咐众人坐在地上，就拿著这七个饼祝谢了，擘开，递给门徒，叫他们摆开，门徒就摆在众人面前。'),
('CUV', '马可福音', 41, 8, 7, '又有几条小鱼；耶稣祝了福，就吩咐也摆在众人面前。'),
('CUV', '马可福音', 41, 8, 8, '众人都吃，并且吃饱了，收拾剩下的零碎，有七筐子。'),
('CUV', '马可福音', 41, 8, 9, '人数约有四千。耶稣打发他们走了，'),
('CUV', '马可福音', 41, 8, 10, '随即同门徒上船，来到大玛努他境内。'),
('CUV', '马可福音', 41, 8, 11, '法利赛人出来盘问耶稣，求他从天上显个神迹给他们看，想要试探他。'),
('CUV', '马可福音', 41, 8, 12, '耶稣心里深深的叹息，说：这世代为甚么求神迹呢？我实在告诉你们，没有神迹给这世代看。'),
('CUV', '马可福音', 41, 8, 13, '他就离开他们，又上船往海那边去了。'),
('CUV', '马可福音', 41, 8, 14, '门徒忘了带饼；在船上除了一个饼，没有别的食物。'),
('CUV', '马可福音', 41, 8, 15, '耶稣嘱咐他们说：你们要谨慎，防备法利赛人的酵和希律的酵。'),
('CUV', '马可福音', 41, 8, 16, '他们彼此议论说：这是因为我们没有饼罢。'),
('CUV', '马可福音', 41, 8, 17, '耶稣看出来，就说：你们为甚么因为没有饼就议论呢？你们还不省悟，还不明白么？你们的心还是愚顽么？'),
('CUV', '马可福音', 41, 8, 18, '你们有眼睛，看不见么？有耳朵，听不见么？也不记得么？'),
('CUV', '马可福音', 41, 8, 19, '我擘开那五个饼分给五千人，你们收拾的零碎装满了多少篮子呢？他们说：十二个。'),
('CUV', '马可福音', 41, 8, 20, '又擘开那七个饼分给四千人，你们收拾的零碎装满了多少筐子呢？他们说：七个。'),
('CUV', '马可福音', 41, 8, 21, '耶稣说：你们还是不明白么？'),
('CUV', '马可福音', 41, 8, 22, '他们来到伯赛大，有人带一个瞎子来，求耶稣摸他。'),
('CUV', '马可福音', 41, 8, 23, '耶稣拉著瞎子的手，领他到村外，就吐唾沫在他眼睛上，按手在他身上，问他说：你看见甚么了？'),
('CUV', '马可福音', 41, 8, 24, '他就抬头一看，说：我看见人了；他们好像树木，并且行走。'),
('CUV', '马可福音', 41, 8, 25, '随后又按手在他眼睛上，他定睛一看，就复了原，样样都看得清楚了。'),
('CUV', '马可福音', 41, 8, 26, '耶稣打发他回家，说：连这村子你也不要进去。'),
('CUV', '马可福音', 41, 8, 27, '耶稣和门徒出去，往该撒利亚腓立比的村庄去；在路上问门徒说：人说我是谁？'),
('CUV', '马可福音', 41, 8, 28, '他们说：有人说是施洗的约翰；有人说是以利亚；又有人说是先知里的一位。'),
('CUV', '马可福音', 41, 8, 29, '又问他们说：你们说我是谁？彼得回答说：你是基督。'),
('CUV', '马可福音', 41, 8, 30, '耶稣就禁戒他们，不要告诉人。'),
('CUV', '马可福音', 41, 8, 31, '从此，他教训他们说：人子必须受许多的苦，被长老、祭司长，和文士弃绝，并且被杀，过三天复活。'),
('CUV', '马可福音', 41, 8, 32, '耶稣明明的说这话，彼得就拉著他，劝他。'),
('CUV', '马可福音', 41, 8, 33, '耶稣转过来，看著门徒，就责备彼得说：撒但，退我后边去罢！因为你不体贴神的意思，只体贴人的意思。'),
('CUV', '马可福音', 41, 8, 34, '于是叫众人和门徒来，对他们说：若有人要跟从我，就当舍己，背起他的十字架来跟从我。'),
('CUV', '马可福音', 41, 8, 35, '因为，凡要救自己生命（或作：灵魂；下同）的，必丧掉生命；凡为我和福音丧掉生命的，必救了生命。'),
('CUV', '马可福音', 41, 8, 36, '人就是赚得全世界，赔上自己的生命，有甚么益处呢？'),
('CUV', '马可福音', 41, 8, 37, '人还能拿甚么换生命呢？'),
('CUV', '马可福音', 41, 8, 38, '凡在这淫乱罪恶的世代，把我和我的道当作可耻的，人子在他父的荣耀里，同圣天使降临的时候，也要把那人当作可耻的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '马可福音', 41, 9, 1, '耶稣又对他们说：我实在告诉你们，站在这里的，有人在没尝死味以前，必要看见神的国大有能力临到。'),
('CUV', '马可福音', 41, 9, 2, '过了六天，耶稣带著彼得、雅各、约翰暗暗的上了高山，就在他们面前变了形像，'),
('CUV', '马可福音', 41, 9, 3, '衣服放光，极其洁白，地上漂布的，没有一个能漂得那样白。'),
('CUV', '马可福音', 41, 9, 4, '忽然，有以利亚同摩西向他们显现，并且和耶稣说话。'),
('CUV', '马可福音', 41, 9, 5, '彼得对耶稣说：拉比（就是夫子），我们在这里真好！可以搭三座棚，一座为你，一座为摩西，一座为以利亚。'),
('CUV', '马可福音', 41, 9, 6, '彼得不知道说甚么才好，因为他们甚是惧怕。'),
('CUV', '马可福音', 41, 9, 7, '有一朵云彩来遮盖他们；也有声音从云彩里出来，说：这是我的爱子，你们要听他。'),
('CUV', '马可福音', 41, 9, 8, '门徒忽然周围一看，不再见一人，只见耶稣同他们在那里。'),
('CUV', '马可福音', 41, 9, 9, '下山的时候，耶稣嘱咐他们说：人子还没有从死里复活，你们不要将所看见的告诉人。'),
('CUV', '马可福音', 41, 9, 10, '门徒将这话存记在心，彼此议论从死里复活是甚么意思。'),
('CUV', '马可福音', 41, 9, 11, '他们就问耶稣说：文士为甚么说以利亚必须先来？'),
('CUV', '马可福音', 41, 9, 12, '耶稣说：以利亚固然先来复兴万事；经上不是指著人子说，他要受许多的苦被人轻慢呢？'),
('CUV', '马可福音', 41, 9, 13, '我告诉你们，以利亚已经来了，他们也任意待他，正如经上所指著他的话。'),
('CUV', '马可福音', 41, 9, 14, '耶稣到了门徒那里，看见有许多人围著他们，又有文士和他们辩论。'),
('CUV', '马可福音', 41, 9, 15, '众人一见耶稣，都甚希奇，就跑上去问他的安。'),
('CUV', '马可福音', 41, 9, 16, '耶稣问他们说：你们和他们辩论的是甚么？'),
('CUV', '马可福音', 41, 9, 17, '众人中间有一个人回答说：夫子，我带了我的儿子到你这里来，他被哑吧鬼附著。'),
('CUV', '马可福音', 41, 9, 18, '无论在那里，鬼捉弄他，把他摔倒，他就口中流沫，咬牙切齿，身体枯干。我请过你的门徒把鬼赶出去，他们却是不能。'),
('CUV', '马可福音', 41, 9, 19, '耶稣说：嗳！不信的世代阿，我在你们这里要到几时呢？我忍耐你们要到几时呢？把他带到我这里来罢。'),
('CUV', '马可福音', 41, 9, 20, '他们就带了他来。他一见耶稣，鬼便叫他重重的抽疯，倒在地上，翻来覆去，口中流沫。'),
('CUV', '马可福音', 41, 9, 21, '耶稣问他父亲说：他得这病有多少日子呢？回答说：从小的时候。'),
('CUV', '马可福音', 41, 9, 22, '鬼屡次把他扔在火里、水里，要灭他。你若能做甚么，求你怜悯我们，帮助我们。'),
('CUV', '马可福音', 41, 9, 23, '耶稣对他说：你若能信，在信的人，凡事都能。'),
('CUV', '马可福音', 41, 9, 24, '孩子的父亲立时喊著说（有古卷：立时流泪的喊著说）：我信！但我信不足，求主帮助。'),
('CUV', '马可福音', 41, 9, 25, '耶稣看见众人都跑上来，就斥责那污鬼说：你这聋哑的鬼，我吩咐你从他里头出来，再不要进去！'),
('CUV', '马可福音', 41, 9, 26, '那鬼喊叫，使孩子大大的抽了一阵疯，就出来了。孩子好像死了一般。以致众人多半说：他是死了。'),
('CUV', '马可福音', 41, 9, 27, '但耶稣拉著他的手，扶他起来，他就站起来了。'),
('CUV', '马可福音', 41, 9, 28, '耶稣进了屋子，门徒就暗暗的问他说：我们为甚么不能赶出他去呢？'),
('CUV', '马可福音', 41, 9, 29, '耶稣说：非用祷告（有古卷在此有：禁食二字），这一类的鬼总不能出来（或作：不能赶出他去来）。'),
('CUV', '马可福音', 41, 9, 30, '他们离开那地方，经过加利利；耶稣不愿意人知道。'),
('CUV', '马可福音', 41, 9, 31, '于是教训门徒，说：人子将要被交在人手里，他们要杀害他；被杀以后，过三天他要复活。'),
('CUV', '马可福音', 41, 9, 32, '门徒却不明白这话，又不敢问他。'),
('CUV', '马可福音', 41, 9, 33, '他们来到迦百农，耶稣在屋里问门徒说：你们在路上议论的是甚么？'),
('CUV', '马可福音', 41, 9, 34, '门徒不作声，因为他们在路上彼此争论谁为大。'),
('CUV', '马可福音', 41, 9, 35, '耶稣坐下，叫十二个门徒来，说：若有人愿意作首先的，他必作众人末后的，作众人的用人。'),
('CUV', '马可福音', 41, 9, 36, '于是领过一个小孩子来，叫他站在门徒中间，又抱起他来，对他们说：'),
('CUV', '马可福音', 41, 9, 37, '凡为我名接待一个像这小孩子的，就是接待我；凡接待我的，不是接待我，乃是接待那差我来的。'),
('CUV', '马可福音', 41, 9, 38, '约翰对耶稣说：夫子，我们看见一个人奉你的名赶鬼，我们就禁止他，因为他不跟从我们。'),
('CUV', '马可福音', 41, 9, 39, '耶稣说：不要禁止他；因为没有人奉我名行异能，反倒轻易毁谤我。'),
('CUV', '马可福音', 41, 9, 40, '不敌挡我们的，就是帮助我们的。'),
('CUV', '马可福音', 41, 9, 41, '凡因你们是属基督，给你们一杯水喝的，我实在告诉你们，他不能不得赏赐。'),
('CUV', '马可福音', 41, 9, 42, '凡使这信我的一个小子跌倒的，倒不如把大磨石拴在这人的颈项上，扔在海里。'),
('CUV', '马可福音', 41, 9, 43, '倘若你一只手叫你跌倒，就把他砍下来；'),
('CUV', '马可福音', 41, 9, 44, '你缺了肢体进入永生，强如有两只手落到地狱，入那不灭的火里去。'),
('CUV', '马可福音', 41, 9, 45, '倘若你一只脚叫你跌倒，就把他砍下来；'),
('CUV', '马可福音', 41, 9, 46, '你瘸腿进入永生，强如有两只脚被丢在地狱里。'),
('CUV', '马可福音', 41, 9, 47, '倘若你一只眼叫你跌倒，就去掉他；你只有一只眼进入神的国，强如有两只眼被丢在地狱里。'),
('CUV', '马可福音', 41, 9, 48, '在那里，虫是不死的，火是不灭的。'),
('CUV', '马可福音', 41, 9, 49, '因为必用火当盐腌各人。（有古卷在此有：凡祭物必用盐腌。）'),
('CUV', '马可福音', 41, 9, 50, '盐本是好的，若失了味，可用甚么叫他再咸呢？你们里头应当有盐，彼此和睦。')
on conflict (version, book, chapter, verse) do nothing;
